ZoneLore.Subzones = {
	-- Durotar: 43 subzones
	[1411] = {
		["bladefist bay"] = {
			name = "Bladefist Bay",
			short = "Bladefist Bay is a portion of the Great Sea off the eastern coast of central Kalimdor. It is on the northeastern coast of Durotar around Skull Rock, and the southern coast of Azshara can be seen to the north.",
			full = "Bladefist Bay is a portion of the Great Sea off the eastern coast of central Kalimdor. It is on the northeastern coast of Durotar around Skull Rock, and the southern coast of Azshara can be seen to the north. The bay can be easily reached from Orgrimmar by taking the road east out of the front gate, past the Dranosh'ar Blockade.\n\nIt is named after Kargath Bladefist, the former chieftain of the Shattered Hand clan. Ships coming from the Great Sea dock at this place, and the port is built up with wood and steel. Bladefist Bay has been called \"the Great Sea's midden heap\", since rubble from the sea frequently washes in on the tide.",
			source = "https://warcraft.wiki.gg/wiki/Bladefist_Bay",
		},
		["bloodtalon shore"] = {
			name = "Bloodtalon Shore",
			short = "The Bloodtalon Shore is the southern most island of the Echo Isles. This is also the main area where the Bloodtalon raptors are bred.",
			full = "The Bloodtalon Shore is the southern most island of the Echo Isles. This is also the main area where the Bloodtalon raptors are bred.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtalon_Shore",
		},
		["burning blade coven"] = {
			name = "Burning Blade Coven",
			short = "The Burning Blade Coven lies within the dusty red mountains that form the northern border of the Valley of Trials.",
			full = "The Burning Blade Coven lies within the dusty red mountains that form the northern border of the Valley of Trials. The valley, which serves as a proving ground for aspiring orcs and trolls, is no longer as safe as it used to be. Imps and other weak demons have spilled out from the mouth of the cave and are causing mischief. Some say that there is more than mischief on the minds of stronger demons that inhabit the cave, and that there may be members of the Burning Blade within the abandoned caverns. New adventurers often tackle the dangers of the Coven as their final test before leaving the Valley of Trials. The Burning Blade Coven is led by a warlock called Yarrog Baneshadow.\n\nForeman Thazz'ril left his pick inside after surveying the area for minerals.",
			source = "https://warcraft.wiki.gg/wiki/Burning_Blade_Coven",
		},
		["darkspear hold"] = {
			name = "Darkspear Hold",
			short = "Darkspear Hold is the main fortress on Darkspear Isle.",
			full = "Darkspear Hold is the main fortress on Darkspear Isle.\n\nThe area was liberated by Thrall and the Horde adventurer when they killed Gul'tar the Subjugator.\n\nThe Horde adventurer went there to take the glaive.",
			source = "https://warcraft.wiki.gg/wiki/Darkspear_Hold",
		},
		["darkspear isle"] = {
			name = "Darkspear Isle",
			short = "Darkspear Isle (or the Echo Isle) is the largest island of the Echo Isles.",
			full = "Darkspear Isle (or the Echo Isle) is the largest island of the Echo Isles.\n\nFollowing the death of the traitorous witch doctor Zalazane, the Darkspear jungle trolls rebuilt their home, and converted the largest isle of the Echo Isles into Darkspear Isle. Regardless, the Darkspear tribe has vowed to stand firm and face whatever challenges lie ahead. The island consists of the training grounds, the Darkspear Hold, and a shore.\n\nIt was liberated by Thrall and the Horde adventurer.\n\nIt was defended by members of the Darkspear tribe.",
			source = "https://warcraft.wiki.gg/wiki/Darkspear_Isle",
		},
		["darkspear shore"] = {
			name = "Darkspear Shore",
			short = "Darkspear Shore is a small beach on the coast of Darkspear Isle, near the Darkspear Training Grounds. New troll players start here, ready for training.",
			full = "Darkspear Shore is a small beach on the coast of Darkspear Isle, near the Darkspear Training Grounds. New troll players start here, ready for training. They are greeted by Jin'thala and Zuni. There is also a Darkspear Watcher present playing a drum.",
			source = "https://warcraft.wiki.gg/wiki/Darkspear_Shore",
		},
		["darkspear strand"] = {
			name = "Darkspear Strand",
			short = "The Darkspear Strand is where the Darkspear trolls arrived upon their evacuation of the Echo Isles. Just yards away from the strand sits Sen'jin Village, where the trolls gathered after fleeing the islands.",
			full = "The Darkspear Strand is where the Darkspear trolls arrived upon their evacuation of the Echo Isles. Just yards away from the strand sits Sen'jin Village, where the trolls gathered after fleeing the islands.",
			source = "https://warcraft.wiki.gg/wiki/Darkspear_Strand",
		},
		["darkspear training grounds"] = {
			name = "Darkspear Training Grounds",
			short = "The Darkspear Training Grounds are a massive area, taking much of the Darkspear Isle, and serves to train members of the Darkspear tribe.",
			full = "The Darkspear Training Grounds are a massive area, taking much of the Darkspear Isle, and serves to train members of the Darkspear tribe.\n\nThe hostile orcs captured many members of the tribe while some guards stood up to them. The area was liberated by Thrall and the Horde adventurer.\n\nYears later, when the Darkspear members conducted the Trial of the Loa, Witch Doctor Tzadah betrayed her tribe and summoned Mueh'zala who empowered Tzadah. She and her undead army took over the training grounds, scattering and cursing its trainees. The Darkspear hero was sent to kill the undead minions of Mueh'zala, thwart Tzadah's evil magical circles, and free the trainees.",
			source = "https://warcraft.wiki.gg/wiki/Darkspear_Training_Grounds",
		},
		["deadeye shore"] = {
			name = "Deadeye Shore",
			short = "Deadeye Shore is a section of seashore on the eastern coast of Durotar, directly east of Drygulch Ravine.",
			full = "Deadeye Shore is a section of seashore on the eastern coast of Durotar, directly east of Drygulch Ravine. Featuring a large patch of sand missing from the desert, shaped like a skull missing an eye, it is named after Kilrogg Deadeye, orcish hero and former chieftain of the Bleeding Hollow clan. It is mostly empty, except for raptors, scorpids, and boars.\n\nAt some point, the orc fisherman Byrok was attacked here by the members of the Burning Blade.",
			source = "https://warcraft.wiki.gg/wiki/Deadeye_Shore",
		},
		["den"] = {
			name = "The Den",
			short = "The Den is the base of operations in the Valley of Trials, and is the starting camp for young orc adventurers. It is in the small southwest corner of Durotar.",
			full = "The Den is the base of operations in the Valley of Trials, and is the starting camp for young orc adventurers. It is in the small southwest corner of Durotar. This is where nearly all the Valley of Trials quests are obtained. It contains basic class trainers and vendors, but no profession trainers.\n\nInside the cave are several cages, used for holding hostile Captured Northwatch Scouts. At some point, the scouts were visited by Zekhan.",
			source = "https://warcraft.wiki.gg/wiki/The_Den",
		},
		["dranoshar blockade"] = {
			name = "Dranosh'ar Blockade",
			short = "The Dranosh'ar Blockade is a massive system of fortifications outside the Gates of Orgrimmar, stretching east-west in front of the northern mountains of Durotar.",
			full = "The Dranosh'ar Blockade is a massive system of fortifications outside the Gates of Orgrimmar, stretching east-west in front of the northern mountains of Durotar. It reaches from Skull Rock to the east to Rocktusk Farm to the west. It is presumably named in honor of Dranosh Saurfang, who fell at the Battle of Angrathar the Wrathgate during the war against the Lich King.\n\nAt the front of it, several siege weapons stand ready for defense. Behind these, archers of the Horde train for battle, while laborers build machinery and transport goods. The blockade has built around Jaggedswine Farm and uses the hut there for storage. The hut just to the west of the front gate contains Gor the Enforcer and Shin Stonepillar, who have differing views on the leadership of the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Dranosh'ar_Blockade",
		},
		["drygulch ravine"] = {
			name = "Drygulch Ravine",
			short = "Drygulch Ravine is a location in Durotar. Apart from falling down into the ravine from above, the only entrance is from Razorwind Canyon, through a small cave at .",
			full = "Drygulch Ravine is a location in Durotar. Apart from falling down into the ravine from above, the only entrance is from Razorwind Canyon, through a small cave at .\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nThree years after the Third War ended, thunder lizards escaped from Thunder Ridge and endangered the ravine. A young orc messenger from Drygulch Ravine went to Orgrimmar and reported the news to Warchief Thrall. In addition to the orcs living here, there is also a river that feeds the ravine.\n\nThis section concerns content related to the original World of Warcraft.\n\nThe ravine is now home to the Dustwind harpies. They have taken to banditry, stealing supplies from caravans and hoarding them on their high cliffs. Here the harpies nest, and the most powerful of them guard their eggs.",
			source = "https://warcraft.wiki.gg/wiki/Drygulch_Ravine",
		},
		["dustwind cave"] = {
			name = "Dustwind Cave",
			short = "Dustwind Cave is a rather small cave in Durotar located atop the cliffs of Razorwind Canyon, just northeast of Razor Hill. This is where new members of the Burning Blade go to train under the Burning Blade Cultists.",
			full = "Dustwind Cave is a rather small cave in Durotar located atop the cliffs of Razorwind Canyon, just northeast of Razor Hill. This is where new members of the Burning Blade go to train under the Burning Blade Cultists.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Cave",
		},
		["echo isles"] = {
			name = "Echo Isles",
			short = "The Echo Isles are a small cluster of tropical landmasses located off the southeastern coast of Durotar.",
			full = "The Echo Isles are a small cluster of tropical landmasses located off the southeastern coast of Durotar. In addition to being the home of the Darkspear tribe of jungle trolls, the archipelago teems with raptors, lynxes, and other dangerous predators.\n\nThe largest isle is called the Darkspear Isle or the Echo Isle.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Isles",
		},
		["hellscreams fist"] = {
			name = "Hellscream's Fist",
			short = "Some members of the crew (between them the player, Nazgrim and Dubs) left the airship to attack directly the stronghold but, after being confronted by them, Captain Doren of the Alliance forces escapes with a gyrocopter, managing to deal a fatal blow to the gunship in the meantime.",
			full = "Some members of the crew (between them the player, Nazgrim and Dubs) left the airship to attack directly the stronghold but, after being confronted by them, Captain Doren of the Alliance forces escapes with a gyrocopter, managing to deal a fatal blow to the gunship in the meantime. This causes the Hellscream's Fist to crash violently to the ground, leaving half the vessel on the cliff and the other half in the sea (and almost taking down the Morningbreeze sisters' air balloon with it).\n\nOf all the crew members that still were on the gunship, only a few managed to leave it in some way before the crash (namely Kiryn, Shokia, Gorrok, Rivett Clutchpop and Zin'Jun with his pet Snuff; all the others, presumably, died in the crash.",
			source = "https://warcraft.wiki.gg/wiki/Hellscream's_Fist",
		},
		["hidden path"] = {
			name = "Hidden Path",
			short = "Those just beginning to follow the path of the shaman are tasked with finding this secret route through the mountains that border the Valley of Trials.",
			full = "Those just beginning to follow the path of the shaman are tasked with finding this secret route through the mountains that border the Valley of Trials. Aside from providing shaman with access to the mystical Spirit Rock, the Hidden Path provides a good view of the Barrens from its highest point. There is also a low point that can be used to get to Ratchet or Orgrimmar, and could be used by Alliance to get into the Valley of Trials.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Path",
		},
		["jaggedswine farm"] = {
			name = "Jaggedswine Farm",
			short = "Jaggedswine Farm is one of several pig farms located near the front gates of Orgrimmar in the orcish homeland of Durotar.",
			full = "Jaggedswine Farm is one of several pig farms located near the front gates of Orgrimmar in the orcish homeland of Durotar. This farm, which is partially surrounded by the Dranosh'ar Blockade, contains a storage house, a large pig pen, and a pond. The swine from this farm are a source of food for the Horde.\n\nDuring the battle at the Gates of Orgrimmar, the farm was taken by Varok Saurfang, Thrall, and Anduin Wrynn to serve as a base for the attack on the gates.",
			source = "https://warcraft.wiki.gg/wiki/Jaggedswine_Farm",
		},
		["kolkar crag"] = {
			name = "Kolkar Crag",
			short = "Kolkar Crag was a craggy gorge in southern Durotar called this way because of the Kolkar centaurs inhabiting it.",
			full = "Kolkar Crag was a craggy gorge in southern Durotar called this way because of the Kolkar centaurs inhabiting it.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nThree years after the Battle of Mount Hyjal, when Theramore received words that orc troops were massing at Kolkar Crag, they sent reinforcements to Northwatch Hold.\n\nThis section concerns content related to the original World of Warcraft.\n\nThe Kolkar plotted to launch an attack on the towns of Durotar: The Valley of Trials, Sen'jin Village, Razor Hill, and even the gates of Orgrimmar. The Kolkar here were led by Warlord Kolkanis.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Crag",
		},
		["northwatch foothold"] = {
			name = "Northwatch Foothold",
			short = "Northwatch Foothold, once known as the Kolkar Crag, is a valley located west of Sen'jin Village in Durotar.",
			full = "Northwatch Foothold, once known as the Kolkar Crag, is a valley located west of Sen'jin Village in Durotar. The humans of Northwatch Hold have begun to gain a foothold into Durotar and with the orcs of Razor Hill having their own problems to deal with it is up to the Darkspear Trolls to prevent this from happening. The humans are transferring large crates of supplies from two icebreakers docked at the nearby Darkspear Strand.",
			source = "https://warcraft.wiki.gg/wiki/Northwatch_Foothold",
		},
		["orgrimmar"] = {
			name = "Orgrimmar",
			short = "Orgrimmar ['ɔɹgɹɪmɑɹ] is the capital city of the orcs and the Horde as a whole.",
			full = "Orgrimmar ['ɔɹgɹɪmɑɹ] is the capital city of the orcs and the Horde as a whole. Named in honor of the legendary Orgrim Doomhammer, and nestled into a system of valleys on the northern edge of Durotar, Orgrimmar stands as one of the mightiest warrior cities in the world. It is the seat of the Horde Council that governs the entire faction. It is the primary hub for player characters of the Horde and, as with all capital cities, has banks, class and profession trainers, and auction houses.",
			source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
		},
		["razor hill"] = {
			name = "Razor Hill",
			short = "Razor Hill is an orcish settlement built on a crossroads in central Durotar. The southern road eventually leads to Sen'jin Village and the Valley of Trials.",
			full = "Razor Hill is an orcish settlement built on a crossroads in central Durotar. The southern road eventually leads to Sen'jin Village and the Valley of Trials. The northern road leads to Orgrimmar, and the road west (now largely washed out by the Southfury Watershed) leads across the Southfury River to the Northern Barrens and eventually to the major Horde gathering point of the Crossroads. The Razor Hill Barracks is the single most prominent structure in the town. The town also has a burrow. Orgnil Soulscar is occupied with investigating the activities of the Burning Blade in the area.\n\nRazor Hill is the major quest hub for those continuing from Sen'jin Village; after that players go to the Dranosh'ar Blockade.",
			source = "https://warcraft.wiki.gg/wiki/Razor_Hill",
		},
		["razor hill barracks"] = {
			name = "Razor Hill Barracks",
			short = "The Razor Hill Barracks features trainers for warriors, priests, shamans and first aid. It also has a general goods vendor.",
			full = "The Razor Hill Barracks features trainers for warriors, priests, shamans and first aid. It also has a general goods vendor. The barracks is the largest building in Razor Hill, and marks it as one of the main settlements in Durotar (excluding Orgrimmar).",
			source = "https://warcraft.wiki.gg/wiki/Razor_Hill_Barracks",
		},
		["razor hill outskirts"] = {
			name = "Razor Hill Outskirts",
			short = "The Razor Hill Outskirts is the area around Razor Hill. During the Darkspear Rebellion, the Darkspear attack the Kor'kron soldiers on the southern side.",
			full = "The Razor Hill Outskirts is the area around Razor Hill. During the Darkspear Rebellion, the Darkspear attack the Kor'kron soldiers on the southern side.",
			source = "https://warcraft.wiki.gg/wiki/Razor_Hill_Outskirts",
		},
		["razor hill watchtower"] = {
			name = "Razor Hill Watchtower",
			short = "The Razor Hill Watchtower is an old watch tower on the cliffs above Razor Hill in Durotar. Thonk mans the tower, using his spyglass to find survivors of the flood in nearby Southfury Watershed.",
			full = "The Razor Hill Watchtower is an old watch tower on the cliffs above Razor Hill in Durotar. Thonk mans the tower, using his spyglass to find survivors of the flood in nearby Southfury Watershed.\n\nKor'kron Overseers took control of the tower and the town below. He made a small base here alongside Chen Stormstout and Baine Bloodhoof to continue their supply runs in the Northern Barrens.\n\nNotable NPCs\n\nRavika <Darkspear Rebellion Quartermaster>\n\nKi'ta Arrowtusk - provides [90W] Battlefield: Barrens",
			source = "https://warcraft.wiki.gg/wiki/Razor_Hill_Watchtower",
		},
		["razormane grounds"] = {
			name = "Razormane Grounds",
			short = "The Razormane Grounds, located in central Durotar, are the front lines of the battle for the Razormane quilboars' expansion from the Barrens into Durotar.",
			full = "The Razormane Grounds, located in central Durotar, are the front lines of the battle for the Razormane quilboars' expansion from the Barrens into Durotar. Bones of dead animals stripped of their flesh litter the grounds, and brambles burst out of the red mountains high above. The orcs fight to keep the Razormane out of the orcish homeland, but for every one cut down, two seem to emerge from the thickets. The leaders of this quilboar encampment are Geolord Mottle and Captain Flat Tusk, captain of the Battleguard.",
			source = "https://warcraft.wiki.gg/wiki/Razormane_Grounds",
		},
		["razorwind canyon"] = {
			name = "Razorwind Canyon",
			short = "Razorwind Canyon is a nesting ground for the Dustwind harpies of Durotar. It is located in two areas, to the east and west of the main road leading between Razor Hill and Orgrimmar.",
			full = "Razorwind Canyon is a nesting ground for the Dustwind harpies of Durotar. It is located in two areas, to the east and west of the main road leading between Razor Hill and Orgrimmar. There are entrances to it by taking paths right or left from that road just north of Razor Hill, or by the going to the north exit of that canyon and checking to the immediate right. Two other entrances from the west are near Tor'kren Farm and by the Southfury Watershed. An entrance to Drygulch Ravine is located in the eastern section of the canyon, through a cave .\n\nAdventurers should prepare themselves for battle before heading into this area, as the aggressive bird women are quite numerous through the canyon, and can quickly subdue or kill unwary travelers.",
			source = "https://warcraft.wiki.gg/wiki/Razorwind_Canyon",
		},
		["rocktusk farm"] = {
			name = "Rocktusk Farm",
			short = "Rocktusk Farm is situated in Durotar just down the western road outside the gates of Orgrimmar. The owners feel fairly safe as their pig farm is just against the Dranosh'ar Blockade and provides sustenance for the Horde.",
			full = "Rocktusk Farm is situated in Durotar just down the western road outside the gates of Orgrimmar. The owners feel fairly safe as their pig farm is just against the Dranosh'ar Blockade and provides sustenance for the Horde.\n\nDuring the Elemental Unrest, Twilight's Hammer units were seen near the farm.",
			source = "https://warcraft.wiki.gg/wiki/Rocktusk_Farm",
		},
		["scuttle coast"] = {
			name = "Scuttle Coast",
			short = "The Scuttle Coast is on the east coast of Durotar, looking out to the Great Sea. It is southeast of Razor Hill and north of Tiragarde Keep.",
			full = "The Scuttle Coast is on the east coast of Durotar, looking out to the Great Sea. It is southeast of Razor Hill and north of Tiragarde Keep. The coast was littered with ships from Kul Tiras, smashed upon the rocks as a result of the great battles fought between the orcs and Admiral Daelin Proudmoore's fleet. Angry sea elementals brought in by the tide now roam the beach, attacking those that come near.\n\nThe orcs are still salvaging bits and pieces of gnome technology from the stores of the ships, while trying to curb the presence of the sea elementals.",
			source = "https://warcraft.wiki.gg/wiki/Scuttle_Coast",
		},
		["senjin village"] = {
			name = "Sen'jin Village",
			short = "Sen'jin Village is a settlement of the Darkspear tribe located on the southern coast of Durotar.",
			full = "Sen'jin Village is a settlement of the Darkspear tribe located on the southern coast of Durotar.\n\nDuring the events of Escalation, it once more became the main stand of the Darkspear Rebellion. Right after this, the new center for the rebellion became the newly retaken Razor Hill.\n\nUsually the first settlement most orcs and trolls encounter on their adventures after around level 5. The road from the Valley of Trials leads east to a crossroads. The path to Sen'jin heads southeast, while the other path turns north toward Razor Hill.\n\nMost of the inhabitants here seem to be alchemists and herbalists. These are the only two professions trained here.\n\nSen'jin Village consists of:\n\n3 very small huts\n\n2 small huts\n\n1 big hut\n\nA dock by the sea",
			source = "https://warcraft.wiki.gg/wiki/Sen'jin_Village",
		},
		["senjin village outskirts"] = {
			name = "Sen'jin Village Outskirts",
			short = "The Sen'jin Village Outskirts is the area around Sen'jin Village. The outskirts is where the majority of the fighting took place.",
			full = "The Sen'jin Village Outskirts is the area around Sen'jin Village. The outskirts is where the majority of the fighting took place.",
			source = "https://warcraft.wiki.gg/wiki/Sen'jin_Village_Outskirts",
		},
		["shrine of the dormant flame"] = {
			name = "Shrine of the Dormant Flame",
			short = "The Shrine of the Dormant Flame (or the Shrine of Eternal Flame) is a place most holy to all shaman of the Horde.",
			full = "The Shrine of the Dormant Flame (or the Shrine of Eternal Flame) is a place most holy to all shaman of the Horde. It is accessible via a secret path that spirals around the tallest mountain of the region, just northwest of the Valley of Trials. The top provides a fantastic view of the region, but jumping from the peak is ill-advised.\n\nIn order to reach the shrine, there is a path starting next to the Southfury River at the southwestern tip of the Southfury Watershed.\n\nTelf Joolam is the keeper of the shrine, and wanders alone around it. In prior times, he was responsible for guiding aspiring shaman in the way of taming fire. The brazier at the top would be lit by shamans using the ember of a fire elemental they had defeated, to show that they had control over fire.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Dormant_Flame",
		},
		["skull rock"] = {
			name = "Skull Rock",
			short = "Skull Rock in northeastern Durotar is one of several holdouts of the Burning Blade cult in the region. The leader of the Burning Blade within Skull Rock is the orc warlock Gazz'uz.",
			full = "Skull Rock in northeastern Durotar is one of several holdouts of the Burning Blade cult in the region. The leader of the Burning Blade within Skull Rock is the orc warlock Gazz'uz. The quest [1-30] Skull Rock is performed within this cave.\n\nKor'kron Deathbringers used to be at its entrance.",
			source = "https://warcraft.wiki.gg/wiki/Skull_Rock",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls.",
			full = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls. The resulting wide, swiftly-flowing river forms the boundary between the forest of Ashenvale and Azshara, and further south, the border between the Northern Barrens and Durotar. The river empties into the Great Sea in a cascading waterfall just northeast of the goblin port city of Ratchet.\n\nThere are three bridges that span the Southfury River: one crossing from Azshara into Ashenvale, one leading into the Horde's capital city of Orgrimmar, and one that crosses from Durotar into the Northern Barrens. Notably, just north of the western bridge of Orgrimmar, there is a spot on the river where four in-game zones meet: Ashenvale, Azshara, Durotar, and Northern Barrens.\n\nA goblin named Horton Hornblower sits at a dock near the mouth of the Southfury with his Riverboat. After doing quests for the goblins in Ratchet, he offers [5-30] Raging River Ride, which provides transportation to the area outside Nozzlepot's Outpost in the Northern Barrens.\n\nIt could still be used to water the crops, but it could no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southfury watershed"] = {
			name = "Southfury Watershed",
			short = "It is a dangerous area densely occupied by quilboars, scorpids, crocolisks, and raptors. The region previously has an appearance similar to the rest of Durotar.",
			full = "It is a dangerous area densely occupied by quilboars, scorpids, crocolisks, and raptors. The region previously has an appearance similar to the rest of Durotar. It is bordered by the Southfury River to the west, the Razormane Grounds to the south, Razor Hill to the east, Razorwind Canyon to the northeast, and Tor'kren Farm and Thunder Ridge to the north. The zone of Northern Barrens is accessible from here by heading west across the Southfury river.\n\nIn World of Warcraft, the Watershed is a questing area involved with the guard tower in the western part of Razor Hill. Many residents were lost during the flooding of the region, and the ones that have survived need to be rescued.\n\nThonk at the guard tower sends players to assist the inhabitants of the region in [1-30] Watershed Patrol.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_Watershed",
		},
		["spirit rock"] = {
			name = "Spirit Rock",
			short = "Spirit Rock is a place sacred to the shaman of the Horde. It is located in the hills high above the Valley of Trials in Durotar, and is accessible from the Hidden Path leading up to it.",
			full = "Spirit Rock is a place sacred to the shaman of the Horde. It is located in the hills high above the Valley of Trials in Durotar, and is accessible from the Hidden Path leading up to it.\n\nAspiring shaman used to drink a sapta near the rock in order to commune with the earth.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rock",
		},
		["spitescale cavern"] = {
			name = "Spitescale Cavern",
			short = "Spitescale Cavern is a naga cave system found on the Spitescale Cove in Echo Isles.",
			full = "Spitescale Cavern is a naga cave system found on the Spitescale Cove in Echo Isles.",
			source = "https://warcraft.wiki.gg/wiki/Spitescale_Cavern",
		},
		["spitescale cove"] = {
			name = "Spitescale Cove",
			short = "Spitescale Cove is the northernmost island of the Echo Isles. The naga used this isle to build a staging ground from which to attack and destroy the Darkspear tribe.",
			full = "Spitescale Cove is the northernmost island of the Echo Isles. The naga used this isle to build a staging ground from which to attack and destroy the Darkspear tribe. They are led by the sea witch Zar'jira, and there is a cave there.",
			source = "https://warcraft.wiki.gg/wiki/Spitescale_Cove",
		},
		["sunstrider"] = {
			name = "The Sunstrider",
			short = "The captain of the ship is Fleet Admiral Zar'gov.",
			full = "The captain of the ship is Fleet Admiral Zar'gov.\n\nLady Liadrin, Aethas Sunreaver, Silgryn, and the adventurer boarded it from Bladefist Bay to get to Azuremyst.",
			source = "https://warcraft.wiki.gg/wiki/The_Sunstrider",
		},
		["thunder ridge"] = {
			name = "Thunder Ridge",
			short = "Thunder Ridge is a flooded gorge in northwestern Durotar, just southwest of Orgrimmar.",
			full = "Thunder Ridge is a flooded gorge in northwestern Durotar, just southwest of Orgrimmar.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Ridge",
		},
		["tiragarde keep"] = {
			name = "Tiragarde Keep",
			short = "Tiragarde Keep is an Alliance stronghold located in the Scuttle Coast in Durotar. It was previously manned by soldiers loyal to Admiral Daelin Proudmoore, Lord of Kul Tiras, and was ruined in a battle against the Horde.",
			full = "Tiragarde Keep is an Alliance stronghold located in the Scuttle Coast in Durotar. It was previously manned by soldiers loyal to Admiral Daelin Proudmoore, Lord of Kul Tiras, and was ruined in a battle against the Horde. After Daelin's death, a reserve force under Lieutenant Benedict took control of the ruins and continued the Admiral's crusade against the orcs.",
			source = "https://warcraft.wiki.gg/wiki/Tiragarde_Keep",
		},
		["torkren farm"] = {
			name = "Tor'kren Farm",
			short = "Tor'kren Farm is located southeast of Thunder Ridge and north of the Southfury Watershed in northwestern Durotar. It hasn't seen as much profit as other pig farms in the area.",
			full = "Tor'kren Farm is located southeast of Thunder Ridge and north of the Southfury Watershed in northwestern Durotar. It hasn't seen as much profit as other pig farms in the area. It was previously run by Misha Tor'kren and her son Kron, before Kron's death several years ago while hunting crocolisks in the Southfury River.\n\nMisha now runs the farm alone, and while on the quest [1-30] Watershed Patrol she will ask for help creating a crocolisk tooth necklace in memory of her son.",
			source = "https://warcraft.wiki.gg/wiki/Tor'kren_Farm",
		},
		["valley of trials"] = {
			name = "Valley of Trials",
			short = "The Valley of Trials in southern Durotar is where all young orcish adventurers begin their journey. Within the valley, they take on challenges that enable them to get used to their new status as recruits of the Horde.",
			full = "The Valley of Trials in southern Durotar is where all young orcish adventurers begin their journey. Within the valley, they take on challenges that enable them to get used to their new status as recruits of the Horde. By the time they leave the valley, they are more than ready to face the trials that await beyond the tall walls. Those that fail and die are left to bake in the scorching desert sun.\n\nWhat was once a small network of natural caves in the cliffs to the north has recently been inhabited by foul demons of the Burning Blade. Even though the demons there are relatively weak and harmless, they have begun to spill out into the valley proper. Furthermore, the presence of the demons suggests that rumors about the Shadow Council getting a foothold in the region may have some truth.\n\nThe trolls of the Darkspear tribe also packed up and left for the newly-freed Echo Isles.\n\nWildlife in the area includes venomous scorpids and brutish boars. While most of them are fairly harmless, a particularly nasty scorpid called Sarkoth has been causing trouble. Orcish peons also utilize the area gathering lumber from what few trees grow in the arid landscape.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
		["zalazanes fall subzone"] = {
			name = "Zalazane's Fall (subzone)",
			short = "Zalazane's Fall is a corrupted island just west of the Bloodtalon Shore in the Echo Isles. This is the island where Zalazane was defeated, but in his demise he left the land tainted.",
			full = "Zalazane's Fall is a corrupted island just west of the Bloodtalon Shore in the Echo Isles. This is the island where Zalazane was defeated, but in his demise he left the land tainted. Naj'tess now resides there, using his Orb of Corruption to taint the Lost Bloodtalon Hatchlings that have wandered there.\n\nRokhan, Talanji, and the Horde adventurer ventured here and killed the traitorous lich once again.",
			source = "https://warcraft.wiki.gg/wiki/Zalazane's_Fall_(subzone)",
		},
	},
	-- Mulgore: 25 subzones
	[1412] = {
		["baeldun digsite"] = {
			name = "Bael'dun Digsite",
			short = "The Bael'dun Digsite is an excavation site of the dwarven expedition based at Bael Modan. It is a large quarry dug into the mountainside in the western edge of Mulgore.",
			full = "The Bael'dun Digsite is an excavation site of the dwarven expedition based at Bael Modan. It is a large quarry dug into the mountainside in the western edge of Mulgore. This incursion was against the warnings of Baine Bloodhoof, who saw the excavations as an affront to the Earth Mother, and as diplomatic solutions failed, the Bloodhoof tribe resolved to drive the invaders out by taking and breaking their pickaxes. The dwarves refused to heed the tauren's warnings and their reckless digging infuriated the spirits of the land and killed them.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Digsite",
		},
		["battleboar pen"] = {
			name = "Battleboar Pen",
			short = "The Battleboar Pen is an area of southern Mulgore, in the south section of Red Cloud Mesa, southwest of the Thornsnarl.",
			full = "The Battleboar Pen is an area of southern Mulgore, in the south section of Red Cloud Mesa, southwest of the Thornsnarl.\n\nHere the Bristleback quilboar under Chief Squealer Thornmantle raise Armored Battleboars, which are force-fed raw flesh and trained to be malicious. Nearby, the tauren Adana Thunderhorn is intent on killing the Battleboars and retaking the land, and asks for aid in doing so.",
			source = "https://warcraft.wiki.gg/wiki/Battleboar_Pen",
		},
		["bloodhoof village"] = {
			name = "Bloodhoof Village",
			short = "Bloodhoof Village is a tauren settlement named in honor of the Bloodhoof tribe, located in central Mulgore, around the waters of Stonebull Lake.",
			full = "Bloodhoof Village is a tauren settlement named in honor of the Bloodhoof tribe, located in central Mulgore, around the waters of Stonebull Lake.\n\nThis is the first settlement in which young tauren adventurers arrive after departing from Camp Narache to the south. Located in the central plains of Mulgore, the village is the hub of questing and commerce until adventurers depart for Thunder Bluff to the north. Bloodhoof Village is also the principal location in which the wild kodo beasts are tamed and sold as mounts for the tauren.\n\nBaine Bloodhoof is the leader of the village and oversaw its protection from threats, and later took command in Thunder Bluff as High Chieftain of the tauren tribes. While Baine focused on more day-to-day matters, the spiritual needs of the Bloodhoof tribe and young tauren passing through are catered to by Zarlman Two-Moons.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nThe attack was repelled by a tauren champion.",
			source = "https://warcraft.wiki.gg/wiki/Bloodhoof_Village",
		},
		["brambleblade ravine"] = {
			name = "Brambleblade Ravine",
			short = "Brambleblade Ravine is the home to the Bristleback quilboars found on the northeastern edge of Red Cloud Mesa.",
			full = "Brambleblade Ravine is the home to the Bristleback quilboars found on the northeastern edge of Red Cloud Mesa. Early tauren adventurers journeyed here in order to disrupt the quilboar attacks, even to go as far as attacking their leader Chief Sharptusk Thornmantle, who resided in a large hut towards the back of this ravine.\n\nMany Bristleback quilboars have also moved out of their home to join the efforts of claiming new land from the tauren in the Thornsnarl.",
			source = "https://warcraft.wiki.gg/wiki/Brambleblade_Ravine",
		},
		["camp narache"] = {
			name = "Camp Narache",
			short = "Camp Narache is the starting town for the tauren, which is located in southern Mulgore at the northern edge of the Red Cloud Mesa.",
			full = "Camp Narache is the starting town for the tauren, which is located in southern Mulgore at the northern edge of the Red Cloud Mesa. Camp Narache is the main village of the Hawkwind Tribe, and its Chief gives the first quest for tauren. It has five buildings: the main tent (where several wounded braves rest), a spirit lounge, a bakery tent, an armory tent and a simple trader's tent. The class trainers are gathered in a circle around the center of the village, paying respect to the fallen matriarch Greatmother Hawkwind.\n\nMuln and his shaman could do nothing but retreat. However, Shotoa took care of it.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Narache",
		},
		["camp sungraze"] = {
			name = "Camp Sungraze",
			short = "Camp Sungraze is a small Horde camp and quest hub in Mulgore located northeast of Thunder Bluff.",
			full = "Camp Sungraze is a small Horde camp and quest hub in Mulgore located northeast of Thunder Bluff.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Sungraze",
		},
		["fargaze mesa"] = {
			name = "Fargaze Mesa",
			short = "Fargaze Mesa is a tall mesa in southwestern Mulgore, west of Red Cloud Mesa and northeast of Thornmantle's Hideout. A path leads to the top of it from west of Camp Narache.",
			full = "Fargaze Mesa is a tall mesa in southwestern Mulgore, west of Red Cloud Mesa and northeast of Thornmantle's Hideout. A path leads to the top of it from west of Camp Narache.\n\nDyami Windsoar resides here, guiding young tauren from Red Cloud Mesa out into the rest of Mulgore.\n\nThe mesa is a sacred place for spiritwalkers. They commune with tauren ancestors here. Spiritwalker Ussoh sits within the stone ring.",
			source = "https://warcraft.wiki.gg/wiki/Fargaze_Mesa",
		},
		["golden plains"] = {
			name = "Golden Plains",
			short = "The Golden Plains are a large basin surrounding Thunder Bluff on the southeast. These plains are one of the most treasured parts of the tauren homeland, and are one of the tauren people's favorite hunting grounds.",
			full = "The Golden Plains are a large basin surrounding Thunder Bluff on the southeast. These plains are one of the most treasured parts of the tauren homeland, and are one of the tauren people's favorite hunting grounds. Large numbers of kodo congregate here, and it is said that the famous Arra'chea also dwells in the shifting green sea of grass.",
			source = "https://warcraft.wiki.gg/wiki/Golden_Plains",
		},
		["great gate"] = {
			name = "Great Gate",
			short = "After this, the Horde army marched east, passing through the Ruins of Taurajo and the Fields of Blood towards Northwatch Hold.",
			full = "After this, the Horde army marched east, passing through the Ruins of Taurajo and the Fields of Blood towards Northwatch Hold.\n\nAccording to Zekhan's report after the war, the gate still stands and protects tauren tribes from quilboar moving into Mulgore and the Alliance's many needling strikes.",
			source = "https://warcraft.wiki.gg/wiki/Great_Gate",
		},
		["kodo rock"] = {
			name = "Kodo Rock",
			short = "Kodo Rock was a natural monument near Camp Narache that tauren shaman needed to go to for one of their early quests. The rock could only be seen from a short distance so one needed to pay attention.",
			full = "Kodo Rock was a natural monument near Camp Narache that tauren shaman needed to go to for one of their early quests. The rock could only be seen from a short distance so one needed to pay attention.\n\nTo get there, one could travel from Camp Narache directly towards the Brambleblade Ravine and it would be located about halfway along the direct line. A small dirt area would be seen on the minimap to pinpoint it.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Rock",
		},
		["palemane rock"] = {
			name = "Palemane Rock",
			short = "Palemane Rock is a cave in western Mulgore inhabited by gnolls of the Palemane tribe. They are aggressive creatures and will attack any who wander too close.",
			full = "Palemane Rock is a cave in western Mulgore inhabited by gnolls of the Palemane tribe. They are aggressive creatures and will attack any who wander too close.\n\nThe gnolls live both inside the cave and in a camp outside, and the cave itself stretches fairly deep into the mountainside.",
			source = "https://warcraft.wiki.gg/wiki/Palemane_Rock",
		},
		["ravaged caravan"] = {
			name = "Ravaged Caravan",
			short = "The Ravaged Caravan is a ruined Venture Company camp on the northeastern shore of Stonebull Lake.",
			full = "The Ravaged Caravan is a ruined Venture Company camp on the northeastern shore of Stonebull Lake. The caravan is what's left of a conflict between the tauren and the Venture Co. after the tauren saw them traveling throughout Mulgore. The caravan's initial goal was to deliver more supplies to Supervisor Fizsprocket's mining endeavor. It now sits on a mound, spewing out black smoke. The remaining company aggressively defends the smoldering remains of their precious cargo.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Red Cloud Mesa",
			short = "Red Cloud Mesa is the name for the rolling plains atop the high cliffs in southern Mulgore. Here, young tauren adventurers prove themselves by helping drive back the invading Bristleback quilboars.",
			full = "Red Cloud Mesa is the name for the rolling plains atop the high cliffs in southern Mulgore. Here, young tauren adventurers prove themselves by helping drive back the invading Bristleback quilboars. Camp Narache in the northwest portion of the Mesa is the last safe area on the mesa.\n\nOnce known for being a place of peaceful, serene beauty, Red Cloud Mesa has suffered visibly after coming under siege by the Bristleback quilboar. The quilboar spread out from their home of Brambleblade Ravine in the northeast, growing twisting, thorned vines on every piece of new territory they snatched. Burned out tauren huts line the warzone in which they fight against the tauren braves, and the water well formerly used in the area has been destroyed.\n\nAt the southwest corner, the former pass out of the mesa has been destroyed by a landslide and taken over by the leader of the quilboar, who created it into an area now known as Thornmantle's Hideout. A new exit leading down from the mesa was carved out of the hillside just north of Camp Narache. There is also a path leading up from the graveyard west of Camp Narache, to the top of Fargaze Mesa.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Red Rocks",
			short = "Red Rocks is a naturally occurring formation of red sandstone located in northeastern Mulgore.",
			full = "Red Rocks is a naturally occurring formation of red sandstone located in northeastern Mulgore. It is a peaceful and reflective site where one can step out of the world of Thunder Bluff into a place serving as a transition between that world and the next.\n\nRed Rocks is a sacred burial ground for the tauren tribes, where fallen heroes of the tauren are sent to the Earth Mother and Sky Father via cleansing flame. Only the most valiant tauren are laid to rest at Red Rocks. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains. Red Rocks isn't just a place for death, but for life and its greatest journeys too. Tauren braves fulfill their rites to enter adulthood, listening for the wisdom and blessings of their ancestors on the winds.\n\nRecently, a group of Bristleback quilboar invaded Red Rocks and defiled the holy place with their filth, which has greatly enraged the tauren of Thunder Bluff.\n\nThe top area of Red Rocks is also used for ceremonies. At the start of the war against the Lich King, Hamuul Runetotem performed a ceremony atop Red Rocks for a deceased female tauren and her son. The Bristleback quilboar attacked him there, but he defeated them. Valeera Sanguinar and Rehgar Earthfury flew there to meet with Hamuul and to invite him to Theramore and the New Council of Tirisfal.\n\nRed Rocks was also the place where Cairne Bloodhoof was cremated.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Rolling Plains",
			short = "The Rolling Plains cover much of southern Mulgore, stretching from Bloodhoof Village to the Barrens border. It is inhabited by many species of animal; wolves, kodo, tallstriders and cougars can all be found here.",
			full = "The Rolling Plains cover much of southern Mulgore, stretching from Bloodhoof Village to the Barrens border. It is inhabited by many species of animal; wolves, kodo, tallstriders and cougars can all be found here. This is also the only place in all Mulgore where centaurs have been able to penetrate - their outriders have been known to wander the grassy fields. A nest of Windfury harpies can be found in the eastern part of the region.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["stonebull lake"] = {
			name = "Stonebull Lake",
			short = "Stonebull Lake is a long horseshoe-shaped lake that surrounds Bloodhoof Village in central Mulgore on three sides. It is known for its abundant fish, and many an hour is spent casting lines into the cool water.",
			full = "Stonebull Lake is a long horseshoe-shaped lake that surrounds Bloodhoof Village in central Mulgore on three sides. It is known for its abundant fish, and many an hour is spent casting lines into the cool water. A bridge spans the lake at its narrowest point. The road that crosses this bridge connects Thunder Bluff to Bloodhoof Village.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["stonetalon pass mulgore"] = {
			name = "Stonetalon Pass (Mulgore)",
			short = "Stonetalon Pass is a small quest area where Horde players battle the Grimtotem. It is located to the northwest of Thunder Bluff in Mulgore.",
			full = "Stonetalon Pass is a small quest area where Horde players battle the Grimtotem. It is located to the northwest of Thunder Bluff in Mulgore. The path ends at a painted rock on a high plateau.\n\nHowever, intrepid explorers can fall to Boulderslide Ravine or Malaka'jin in Stonetalon Mountains if they head northeast (almost due east) from the top of the path. Walking along the rim of Mulgore can get one to the High Road, used by Horde players to travel between Stonetalon and the Southern Barrens while skirting the Alliance forces at Honor's Stand.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Pass_(Mulgore)",
		},
		["thornmantles hideout"] = {
			name = "Thornmantle's Hideout",
			short = "Thornmantle's Hideout is a small enclave in the southwestern corner of Mulgore. The ground is covered with vines, and the quilboar have grown massive thorns so that the area resembles a cave.",
			full = "Thornmantle's Hideout is a small enclave in the southwestern corner of Mulgore. The ground is covered with vines, and the quilboar have grown massive thorns so that the area resembles a cave. It is inhabited by the leader of the Bristleback tribe, Chief Squealer Thornmantle, and two Thornguards. They are surrounded by the burning corpses of tauren braves that have fallen against them.",
			source = "https://warcraft.wiki.gg/wiki/Thornmantle's_Hideout",
		},
		["thornsnarl"] = {
			name = "Thornsnarl",
			short = "The Thornsnarl is an area in southern Mulgore where Fledgling Braves fight against Bristleback Invaders seeking to claim new land from the tauren.",
			full = "The Thornsnarl is an area in southern Mulgore where Fledgling Braves fight against Bristleback Invaders seeking to claim new land from the tauren.\n\nOther quilboar inhabitants include Bristleback Gun Thieves, Bristleback Thorncallers and Young Battleboars.\n\nCaptured Braves can be found in the northern portion of this subzone and are rescued as part of a tauren starting quest.\n\nHowever, it is not included in any subzone.",
			source = "https://warcraft.wiki.gg/wiki/Thornsnarl",
		},
		["thunder bluff"] = {
			name = "Thunder Bluff",
			short = "Thunder Bluff (sometimes spelled as Thunderbluff) is the tauren capital city located in the northern part of the region of Mulgore on the continent of Kalimdor.",
			full = "Thunder Bluff (sometimes spelled as Thunderbluff) is the tauren capital city located in the northern part of the region of Mulgore on the continent of Kalimdor. The entire city is built on bluffs several hundred feet above the surrounding landscape and is accessible by elevators on the southwestern and northeastern sides. Established by the wise chieftain Cairne Bloodhoof and his stalwart tribe, Thunder Bluff overlooks the verdant land of Mulgore from atop a series of windswept mesas. Prior to the construction of the capital, the tauren had lived as nomads for countless generations, often under attack by marauding bands of centaur. With Thunder Bluff's founding, however, the proud and good-spirited race was finally granted a permanent home.\n\nThe city of many tribes is a hub for tauren, welcoming tradesfolk and artisans of every kind.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
		},
		["thunderhorn water well"] = {
			name = "Thunderhorn Water Well",
			short = "The Thunderhorn Water Well is located in the midst of the grasslands in Mulgore, by the north road between Thunder Bluff and Bloodhoof Village.",
			full = "The Thunderhorn Water Well is located in the midst of the grasslands in Mulgore, by the north road between Thunder Bluff and Bloodhoof Village.\n\nThis well had been taken over by the Venture Company in order to control the water supply but were run off by the tauren.\n\nThis section concerns content related to the Warcraft manga or comics.\n\nThe tauren shaman Muln Earthfury and the Earthen Ring tried to stop the disaster by asking help from the elements, in vain, until the mysterious Shotoa achieved this by forcing the elements to obey him.\n\nAt some point, the Grimtotem tribe have been tainting the water supply as payback for being exiled from Thunder Bluff.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Venture Co. Mine",
			short = "The Venture Co. Mine (also spelled Venture Company Mine) is an enormous mine run by the Venture Company in the eastern cliffs of Mulgore.",
			full = "The Venture Co. Mine (also spelled Venture Company Mine) is an enormous mine run by the Venture Company in the eastern cliffs of Mulgore. The mine has three entrance points. The first is the main entrance where Supervisor Fizsprocket resides -- it is the only entrance accessible on foot. Fizsprocket is the goblin in charge of Venture Co. operations in the tauren homeland. The second entrance is a cliff, and the third entrance is a small lumber camp.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Wildmane Water Well",
			short = "The Wildmane Water Well is located just north of Thunder Bluff. It is the northernmost of the tauren people's sacred water wells.",
			full = "The Wildmane Water Well is located just north of Thunder Bluff. It is the northernmost of the tauren people's sacred water wells. This well had been taken over by the Venture Company in order to control the water supply but were run off by the tauren. Recently the Grimtotem tribe have been tainting the water supply as payback for being exiled from Thunder Bluff.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Windfury Ridge",
			short = "Windfury Ridge is a dangerous place to travel for those who are not aware of its inhabitants.",
			full = "Windfury Ridge is a dangerous place to travel for those who are not aware of its inhabitants. Furious harpies swoop down to capture or kill those who come too near to their nests, and the hills are also dotted with wild cougars and wolves.\n\nThe Windfury harpies are often hunted for their brilliant feathers, which the tauren of Thunder Bluff appropriate for decoration in weddings and feasts.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Winterhoof Water Well",
			short = "The Winterhoof Water Well is located at the edge of the Rolling Plains in southern Mulgore.",
			full = "The Winterhoof Water Well is located at the edge of the Rolling Plains in southern Mulgore.\n\nThis section concerns content related to the original World of Warcraft.\n\nYears after the Third War, the well was taken and poisoned over by the Venture Company in order to control the water supply, but they were eventually run off by the tauren adventurers, while Mull Thunderhorn created a totem to cleanse the waters.\n\nUltimately, Mull Thunderhorn and the Horde adventurers purified it once again.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- The Barrens: 34 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Agama'gor was a large Bristleback quilboar settlement located just north of the road leading west from Camp Taurajo.",
			full = "Agama'gor was a large Bristleback quilboar settlement located just north of the road leading west from Camp Taurajo. Its close proximity to the camp makes it a convenient area to grind for Blood Shards which are dropped by Bristleback quilboar mobs and can be returned to the exile Mangletooth for temporary buffs.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "Bael Modan is a dwarven base in the Southern Barrens consisting of a fortress with a giant cannon and an excavation site for digging.",
			full = "Bael Modan is a dwarven base in the Southern Barrens consisting of a fortress with a giant cannon and an excavation site for digging. Before the dwarves came, the area was home to the Stonespire tauren. There is an ancient titan complex and research facility under Bael Modan. It seems likely that there are many relics and much knowledge to be discovered deep beneath the surface.\n\nThe Bael Modan digsite and the nearby mighty Bael'dun Keep are led by General Twinbraid, Heggin Stonewhisker, Prospector Khazgorm, Malgin Barleybrew, Captain Gerogg Hammertoe, and Lord Cyrik Blackforge. A number of dwarves from Bael Modan traveled west to Mulgore and set up another digsite known as the Bael'dun Digsite.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Bael'dun Keep",
			short = "Bael'dun Keep is the fortress that overlooks the Bael Modan digsite in the southern Barrens. It is inhabited by a force of dwarves that are hostile to Horde players.",
			full = "Bael'dun Keep is the fortress that overlooks the Bael Modan digsite in the southern Barrens. It is inhabited by a force of dwarves that are hostile to Horde players. Gann Stonespire and Feegly the Exiled give out quests to raid the stronghold, which is ruled by the cunning General Twinbraid.\n\nThe keep was seemingly built by the architect Haggis Boatmurder.\n\nGann Stonespire, already upset about the loss of his tribe and the deaths at Camp Taurajo, helps the Horde player and a goblin called Weezil Slipshadow attack Bael'dun's forces. In the final quest, a dwarven artillery shell is rigged by the Horde adventurer and blows up the whole keep, killing the dwarves there. Several survivors from the rubble were rescued.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Blackthorn Ridge",
			short = "Blackthorn Ridge is a thorny valley located just north of the Quilboar capital of Razorfen Kraul, populated primarily by Razormane Quilboar.",
			full = "Blackthorn Ridge is a thorny valley located just north of the Quilboar capital of Razorfen Kraul, populated primarily by Razormane Quilboar. The orc shaman Brine dwells on the ridge that gives this area it's name. Just below her camp, lies a pool whose water is of notable quality and purity.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Boulder Lode Mine",
			short = "The Boulder Lode Mine is a mine located in the northeastern section of the Northern Barrens.",
			full = "The Boulder Lode Mine is a mine located in the northeastern section of the Northern Barrens. It is controlled by the Venture Company and seems to have once belonged to the Horde judging by the orcish architecture and Horde banners found around the area. Boss Copperplug runs this operation.\n\nWhen Wharfmaster Dizzywig heard that one of the miners there had discovered a giant emerald, he hired adventurers to go and retrieve it for him, promising to split the profits.\n\nWhen adventurers sought out Rilli Greasygob to fix a samophlange for Sputtervalve, he had them go to the Boulder Lode Mine and collect Copperplug's Samophlange Manual and any pages he might have given to anyone else there.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Bramblescar",
			short = "Bramblescar is the location of a tribe of Razormane quilboar. They are at war with the Bristleback tribe which has a holding at Agama'gor on the opposite side of the road.",
			full = "Bramblescar is the location of a tribe of Razormane quilboar. They are at war with the Bristleback tribe which has a holding at Agama'gor on the opposite side of the road. The quilboar also readily attack anyone who wanders close to their lair.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Camp Taurajo",
			short = "Camp Taurajo was a tauren outpost situated in the Southern Barrens near the mountain pass leading to Mulgore. It could be reached by starting tauren players by following the road east from Bloodhoof Village.",
			full = "Camp Taurajo was a tauren outpost situated in the Southern Barrens near the mountain pass leading to Mulgore. It could be reached by starting tauren players by following the road east from Bloodhoof Village. It had an inn, a few vendors, some profession trainers and a flight master.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["cavern of mists"] = {
			name = "Cavern of Mists",
			short = "The Cavern of Mists (or the Wailing Cavern) is a section of the Wailing Caverns located just outside the instance. Geysers erupt from the cavern floor, forming a verdant pool in the center of the chamber.",
			full = "The Cavern of Mists (or the Wailing Cavern) is a section of the Wailing Caverns located just outside the instance. Geysers erupt from the cavern floor, forming a verdant pool in the center of the chamber. The mist from these geysers hangs heavy on the still air. The caverns is dominated by the central pool, and various creatures roam the area, including raptors, oozes, wind serpents, snakes, and toads. Trigore the Lasher, a rare hydra, is sometimes seen in the water among the threshadons.",
			source = "https://warcraft.wiki.gg/wiki/Cavern_of_Mists",
		},
		["crossroads"] = {
			name = "Crossroads",
			short = "The Crossroads is the largest Horde town in the Northern Barrens, aptly named for the crossing of the main north-south road (from the Gold Road) and the road from Ratchet in the east all the way to the Stonetalon Mountains in the west.",
			full = "The Crossroads is the largest Horde town in the Northern Barrens, aptly named for the crossing of the main north-south road (from the Gold Road) and the road from Ratchet in the east all the way to the Stonetalon Mountains in the west. Combined with its central location and the wyvern flight routes, the Crossroads offers access to nearly all Horde outposts in Kalimdor. As such, this small crossing is usually the first place you will see large gatherings of players outside of Orgrimmar or Thunder Bluff.\n\nThe Crossroads graveyard is considered the default graveyard for Horde players, much like the Sentinel Hill graveyard for Alliance players.\n\nDespite having only few lodgings, the Crossroads is a busy bustling trade center. Traders enjoy shouting their wares and interests. Just past the settlement, there is a burial area that the Horde members visit to pay their respects to the dead.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Dreadmist Den",
			short = "Dreadmist Den is a Burning Blade cultist holding located within Dreadmist Peak. It contains the [Demon Seed], an invaluable artifact to the Cult.",
			full = "Dreadmist Den is a Burning Blade cultist holding located within Dreadmist Peak. It contains the [Demon Seed], an invaluable artifact to the Cult. The den is perpetually shrouded in a dark red mist that taints the peak and cloaks the nefarious demon worshippers who live there in eternal twilight.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Dreadmist Peak",
			short = "Dreadmist Peak is a mountain northwest of the Crossroads in the Northern Barrens. As you climb to the top of the Peak, the atmosphere becomes red and foggy.",
			full = "Dreadmist Peak is a mountain northwest of the Crossroads in the Northern Barrens. As you climb to the top of the Peak, the atmosphere becomes red and foggy. At the top is the home of a group of Burning Blade cultists. They protect the Demon Seed which is in the Dreadmist Den.\n\nThe orange miasma is residuum from an ancient demonic curse.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Dry Hills",
			short = "The Dry Hills are located in the far northwestern corner of the Northern Barrens. Despite their name, the Dry Hills are actually one of the greener areas of the Barrens.",
			full = "The Dry Hills are located in the far northwestern corner of the Northern Barrens. Despite their name, the Dry Hills are actually one of the greener areas of the Barrens. These foothills of the Stonetalon Mountains to the west are primarily populated by Witchwing harpies who have recently been raiding caravans traveling the northern Gold Road.\n\nDuring the Elemental Unrest, several elemental rifts opened in the Dry Hills, from which Searing Elementals invaded the area.\n\nDuring the Primalists' attack, the area was invaded by elementals. Their presence imbued the harpies.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Far Watch Post",
			short = "Far Watch Post is a small Horde outpost located just west of the bridge between Durotar and the Northern Barrens. It contains a watch tower, an orc burrow and a few catapults.",
			full = "Far Watch Post is a small Horde outpost located just west of the bridge between Durotar and the Northern Barrens. It contains a watch tower, an orc burrow and a few catapults. A riding wolf pen watched over by a pair of peons is located directly south.\n\nAlthough not an accommodating spot, the outpost is vital for the protection of supply caravans, as well as keeping Durotar safe from Alliance and quilboar threats.\n\nDuring the Burning Legion's invasions, the outpost fell under the Legion's control. Several of its residents were enslaved by nathrezim and were either killed or rescued by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Field of Giants",
			short = "The Field of Giants was once an area found in the southern reaches of the Barrens.",
			full = "The Field of Giants was once an area found in the southern reaches of the Barrens.\n\nCovering much of the southernmost portion of the Barrens, the Field of Giants lied between Camp Taurajo and the entrance to Dustwallow Marsh. Numerous herds of thunder lizards, kodo, and other varieties of Kalimdorean megafauna roamed this land. The plains were straddled by the southern leg of the Gold Road which was less well defended than the northern reaches -- the watch towers that were built to guard it appeared to had been abandoned.\n\nThe Horde did not forsaken this tract entirely however -- the wise shaman Brine made her home on a ridge on the southern borders of the Field, while Gann Stonespire seeked to avenge his tribe, who were driven out of their village when the dwarves started digging for titan ruins in the land adjacent to their settlement, which is now Bael Modan.\n\nThe main concern to those with interests in the region was the recent appearance of silithid hives -- the northernmost in all Kalimdor. The troll Korran of the Crossroads and tauren Ruga Ragetotem of Camp Taurajo tasked Horde adventurers with investigating this incursion.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Forgotten Pools",
			short = "The Forgotten Pools are the northernmost of the oases in the Northern Barrens, located north off the western road out of the Crossroads.",
			full = "The Forgotten Pools are the northernmost of the oases in the Northern Barrens, located north off the western road out of the Crossroads. As with many of these verdant pools, it is patrolled by Kolkar centaurs along with the indigenous wildlife, such as turtles. Laden Mushrooms are unique to this pool, and grow along its shore.\n\nTa'jari and Telar Highstrider can be found here, assessing the centaur threat. This is one of only three fishing locations where [Deviate Fish] can be found.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasions, the pools fall under the Legion's control. All residents, including the centaur, were killed by the demons.\n\nDuring the Primalists' attack, the northern portion of the area was invaded by elementals.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Fray Island",
			short = "Fray Island is a small arid island located off the eastern shore of the Northern Barrens. A small sewer stretches the length of the island and players diving into it will be able to find several hostile fish.",
			full = "Fray Island is a small arid island located off the eastern shore of the Northern Barrens. A small sewer stretches the length of the island and players diving into it will be able to find several hostile fish.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Gold Road",
			short = "The Gold Road runs north-south from Mor'shan Rampart to the Great Divide. South of the bridge, the road was called the Southern Gold Road.",
			full = "The Gold Road runs north-south from Mor'shan Rampart to the Great Divide. South of the bridge, the road was called the Southern Gold Road.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Grol'dom Farm",
			short = "Grol'dom Farm is one of the many orcish pig farms that have sprung up in the years after the founding of Orgrimmar.",
			full = "Grol'dom Farm is one of the many orcish pig farms that have sprung up in the years after the founding of Orgrimmar.\n\nThe farm is under constant attack from Razormane Pillagers. The farm serves as a quest hub, with an innkeeper, stable master, and repairs.\n\nHere, adventurers will first meet Mankrik and can pay their respects at the Humble Monument, a memorial to Mankrik's deceased wife, Olgra.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasions, the farm was assaulted by the Legion, leaving the area in turmoil. The swines specifically were targeted by imps.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Lushwater Oasis",
			short = "Lushwater Oasis , just south of the Crossroads, is one of three major oases in the Northern Barrens. It is notable for containing the entrance to the accursed Wailing Caverns.",
			full = "Lushwater Oasis , just south of the Crossroads, is one of three major oases in the Northern Barrens. It is notable for containing the entrance to the accursed Wailing Caverns. Kolkar centaur stalk between the trees, eager to hunt the wild beasts coming to drink. It is directly on the edge of the Great Divide.\n\nDue to its closeness to the Wailing Caverns and Crossroads, this is a popular spot to fish for [Deviate Fish], the integral ingredient in the popular [Savory Deviate Delight].",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "Merchant Coast",
			short = "The Merchant Coast is the name given to the small portion of the Northern Barrens that forms the coastline of the Great Sea.",
			full = "The Merchant Coast is the name given to the small portion of the Northern Barrens that forms the coastline of the Great Sea. Along the Merchant Coast is the goblin port town of Ratchet, and the Theramore outpost, Northwatch Hold. Off the coast is Fray Island. The Merchant Coast receives its name from the lucrative trade that takes place through the thrifty hands of the Ratchet goblins.\n\nFor years, the southern portion of the Merchant Coast was controlled by the Southsea Freebooters. Much to Gazlowe's dismay, the Northwatch forces have been interrupting his trade with the Horde and also captured Baron Longshore, a pirate who stole and buried some of his most valuable cargo.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Mor'shan Base Camp",
			short = "Mor'shan Base Camp, one of the more sizable Horde settlements in the Northern Barrens, is located just south of the Ashenvale-Barrens border, near the Mor'shan Rampart.",
			full = "Mor'shan Base Camp, one of the more sizable Horde settlements in the Northern Barrens, is located just south of the Ashenvale-Barrens border, near the Mor'shan Rampart. It is the base of the Warsong Outriders and also the location of the Horde entrance to the Warsong Gulch battleground.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Mor'shan Rampart",
			short = "The Mor'shan Rampart lies at the northern terminus of the Gold Road in Northern Barrens. This makeshift defensive post was built to withstand the push of Alliance forces into the region from Ashenvale to the north.",
			full = "The Mor'shan Rampart lies at the northern terminus of the Gold Road in Northern Barrens. This makeshift defensive post was built to withstand the push of Alliance forces into the region from Ashenvale to the north. The rampart and its watch towers still serve as a makeshift launching point for raids on the night elven town of Astranaar.\n\nAshenvale Skirmishers regularly charge the rampart and engage in combat with the Mor'shan Defenders, while Ashenvale Bowmen shoot arrows at them.\n\nDuring the War of the Thorns, the elves were killed by two Horde rogues.\n\nThe area was changing hands between the Alliance and Mor'shan defenders since then.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Raptor Grounds",
			short = "Raptor Grounds was a tiny valley located in the southern part of the Barrens and west of Northwatch Hold.",
			full = "Raptor Grounds was a tiny valley located in the southern part of the Barrens and west of Northwatch Hold. It was densely populated by the Sunscale raptors, who are odd among their kind, showing an unnatural intelligence and even building their own crude huts and tools. Their attraction to shiny objects and, indeed, anything out of the ordinary caused them to steal many items from the Horde settlements in the area.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Ratchet",
			short = "Ratchet is a major goblin port in Kalimdor, a medium-sized harbor city located on the eastern shore of the Northern Barrens, directly between Orgrimmar and Theramore Isle.",
			full = "Ratchet is a major goblin port in Kalimdor, a medium-sized harbor city located on the eastern shore of the Northern Barrens, directly between Orgrimmar and Theramore Isle. The town does most of its business through Booty Bay and Baron Revilgaz on the other side of the Great Sea.\n\nThe majority of quests in Ratchet are only available to Horde players.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["razorfen downs classic"] = {
			name = "Razorfen Downs",
			short = "Razorfen Downs are the ancestral burial grounds of the quilboar, nestled amid huge brambles in the Barrens, on the east side of the far southern edge.",
			full = "Razorfen Downs are the ancestral burial grounds of the quilboar, nestled amid huge brambles in the Barrens, on the east side of the far southern edge. The Scourge have taken over much of the downs, and infest the burial grounds with the reawakened dead. It is also known as RFD, not to be confused with RFK or BFD.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs_(Classic)",
		},
		["razorfen kraul classic"] = {
			name = "Razorfen Kraul",
			short = "Razorfen Kraul is the ancestral home of the quilboar, heavily entrenched within the thorns that supposedly sprang from the corpse of the demigod Agamaggan.",
			full = "Razorfen Kraul is the ancestral home of the quilboar, heavily entrenched within the thorns that supposedly sprang from the corpse of the demigod Agamaggan. It is found in the Southern Barrens, at the far southern edge, west side.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Kraul_(Classic)",
		},
		["shrine of the fallen warrior"] = {
			name = "Shrine of the Fallen Warrior",
			short = "The Shrine of the Fallen Warrior is located on a small hill in the Northern Barrens west of the Crossroads.",
			full = "The Shrine of the Fallen Warrior is located on a small hill in the Northern Barrens west of the Crossroads. To reach it, the player must follow a ridge to the southwest and half-way up the hill will find the base of a mound. The short trail will lead directly to the shrine.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "Sludge Fen",
			short = "The Sludge Fen (or the Sludge Fens) is an oil field found on the northeast corner of the Northern Barrens. It is close to a few other Venture Co. properties; the Venture Co.",
			full = "The Sludge Fen (or the Sludge Fens) is an oil field found on the northeast corner of the Northern Barrens. It is close to a few other Venture Co. properties; the Venture Co. Tower can be found north of it, a Venture Co. research facility to the west, and the Boulder Lode Mine in the north-east.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Southern Gold Road",
			short = "This trade route is named for the trade caravans that travel regularly along the highway.",
			full = "This trade route is named for the trade caravans that travel regularly along the highway. Officially, the section of the road that bears the name Southern Gold Road begins at the Great Lift at the southern end of the Barrens and ends at the bridge connecting the northern and southern ends of the Barrens. North of here, the road is simply known as the Gold Road. The road is traveled by traders and adventurers alike, hailing from regions as distant as Gadgetzan in Tanaris Desert and Auberdine in Darkshore, and Nighthaven in the north.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls.",
			full = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls. The resulting wide, swiftly-flowing river forms the boundary between the forest of Ashenvale and Azshara, and further south, the border between the Northern Barrens and Durotar. The river empties into the Great Sea in a cascading waterfall just northeast of the goblin port city of Ratchet.\n\nThere are three bridges that span the Southfury River: one crossing from Azshara into Ashenvale, one leading into the Horde's capital city of Orgrimmar, and one that crosses from Durotar into the Northern Barrens. Notably, just north of the western bridge of Orgrimmar, there is a spot on the river where four in-game zones meet: Ashenvale, Azshara, Durotar, and Northern Barrens.\n\nA goblin named Horton Hornblower sits at a dock near the mouth of the Southfury with his Riverboat. After doing quests for the goblins in Ratchet, he offers [5-30] Raging River Ride, which provides transportation to the area outside Nozzlepot's Outpost in the Northern Barrens.\n\nIt could still be used to water the crops, but it could no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "Stagnant Oasis",
			short = "The Stagnant Oasis is an oasis located between the Merchant Coast and the Gold Road.",
			full = "The Stagnant Oasis is an oasis located between the Merchant Coast and the Gold Road. In addition to Kolkar centaur camped on its fringes and other indigenous oasis flora, it is also home to several Lost Barrens Kodos, which due to their weakened state and solitary nature are much easier to hunt than the kodo of the Field of Giants to the south.\n\nThe Stagnant Oasis can be fished for [Deviate Fish] which can be valuable when cooked into Savory Deviate Delights. Oasis Snapjaws are also indigenous here.\n\nDuring the Primalists' attack, the area was invaded by elementals. Their presence imbued the centaur.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Thorn Hill",
			short = "Thorn Hill is a sizable settlement nestled on the north face of a mountain top between the Crossroads and Durotar.",
			full = "Thorn Hill is a sizable settlement nestled on the north face of a mountain top between the Crossroads and Durotar. It is populated by a large number of Razormane quilboar who have recently been raiding Horde caravans in the region, and thus have attracted the ire of the local security forces. Thorn Hill is led by the quilboar Tortusk.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasions, the camp assaulted by the Legion, leaving the area in turmoil.\n\nDuring the Primalists' attack, the area was invaded by elementals. Their presence imbued the quilboar.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "Tidus Stair",
			short = "The Tidus Stair is an interesting geological formation that has the form of several terraces forming a giant set of stone stairs overlooking part of the Merchant Coast.",
			full = "The Tidus Stair is an interesting geological formation that has the form of several terraces forming a giant set of stone stairs overlooking part of the Merchant Coast. It is located southeast of Ratchet, on the coast of the Northern Barrens. A pair of tauren, Islen Waterseer and Mahren Skyseer, sit and fish and converse with water spirits there.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Wailing Caverns",
			short = "The Wailing Caverns is in the Northern Barrens, to the south of Crossroads, on the north side of the Lushwater Oasis.",
			full = "The Wailing Caverns is in the Northern Barrens, to the south of Crossroads, on the north side of the Lushwater Oasis.\n\nThe Wailing Caverns are a network of underground caverns within the heart of the Barrens. Its waterways carry underground rivers for miles beneath the savannah, and naturally bubbles to the surface as small oases throughout the Barrens. The caverns were discovered by the night elf druid Naralex, who named them after the mournful howls produced by the wind traveling through the caverns and the steam venting through small cracks in the rock. Naralex believed that if he connected the underground waters directly to the Emerald Dream, he could spread growth across the Barrens and restore the region to its original lush state. He traveled into the caverns with his loyal disciples and settled into meditation, allowing the Dream to connect to Azeroth through his body. However, he was unexpectedly overwhelmed by the Emerald Nightmare. Unable to wake, the sleeping Naralex inadvertently channeled the Nightmare's energies into the caverns, corrupting the waters, the wildlife (which turned into deviate forms), and his disciples, most of whom went insane and became the Druids of the Fang.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Alterac Mountains: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Dalaran, also City of Dalaran and Dalaran City, was the capital of the magocratic nation of the same name.",
			full = "Dalaran, also City of Dalaran and Dalaran City, was the capital of the magocratic nation of the same name. Founded as a city-state by magi of the Arathorian Empire after the Troll Wars, it was ruled by the Kirin Tor, an elite cadre of the most powerful wizards in the known world, under the leadership of the Council of Six. The Violet Citadel, the city's inner fortress described as a sanctum and haven for mages, served as the focal point for magi and the study of the arcane throughout human history. The city of Dalaran had the greatest concentration of magic in the world, other than the lands of Quel'Thalas, and was defended by some of the most powerful magi in Azeroth. The Kirin Tor Guardians patrolled and protected the surface of Dalaran, while the Underbelly Guard were the guardians of the Underbelly, the sewer system beneath the capital.\n\nBy the time of the Third War, Dalaran was home to many of the greatest sorcerers of the time, while most contemporary human and high elven mages of Quel'Thalas bowed to both the sovereignty of the Kirin Tor. However, the Siege of Dalaran by the Scourge forced the Dalaranian people to flee their kingdom, while the Kirin Tor's leadership and its surviving members were scattered after Archimonde destroyed the city. In the aftermath of the Third War, the survivors returned to rebuild the ruins of Dalaran and created a vast, magical dome around the heart of their city. After Dalaran was restored to its former glory, the Kirin Tor magically floated the city so that no ground assault by the undead could ever reach them again. The nation since became one of the foremost forces standing against the threats posed to Azeroth's survival, with Dalaran serving as a neutral ground where the heroes of every kingdom could join together against their mutual foe; a place where all were welcome, so long as they behaved themselves.\n\nAfter Dalaran was teleported above the Isle of Dorn in Khaz Algar, Xal'atath unleashed the nerubians of Azj-Kahet upon the city. The Harbinger of the Void then siphoned Dalaran's power into the Dark Heart from the Violet Citadel and ultimately used the artifact to destroy the city in an explosion. Its remains can be found across the shores of the Tranquil Strand on the Isle of Dorn.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Dandred's Fold",
			short = "Dandred's Fold is a small farm and manor on the westernmost side of the Uplands, in northwestern Alterac Mountains. Since it has a harbor on Lordamere Lake, it is also on the Misty Shore.",
			full = "Dandred's Fold is a small farm and manor on the westernmost side of the Uplands, in northwestern Alterac Mountains. Since it has a harbor on Lordamere Lake, it is also on the Misty Shore.\n\nHorde adventurers were sent here to retrieve the necklace that had once belonged to Taretha Foxton, and end Aliden's life. After killing him, Aliden's mistress Elysa gave them the necklace, which she was wearing, in fear they would also harm her.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Lordamere Internment Camp",
			short = "Lordamere Internment Camp was the only internment camp based in the Alterac Mountains. It was located on a hill overlooking the Dalaran Crater, and was defended by Dalaranian forces.",
			full = "Lordamere Internment Camp was the only internment camp based in the Alterac Mountains. It was located on a hill overlooking the Dalaran Crater, and was defended by Dalaranian forces.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "Ruins of Alterac",
			short = "The Ruins of Alterac (or Alterac Ruins) are what remains of the former Alterac City (or the Keep at Alterac) located in the Alterac Mountains.",
			full = "The Ruins of Alterac (or Alterac Ruins) are what remains of the former Alterac City (or the Keep at Alterac) located in the Alterac Mountains. The city was the capital city of the Kingdom of Alterac until it was attacked and put under martial law by King Terenas Menethil II and the Alliance of Lordaeron for their treason and pact with the Old Horde. Following the fall of the kingdom, the ruins became home to the Crushridge ogres who disputed the territories for years with the Syndicate. They were not contested by the Alliance but were spied on.\n\nBro'kin, a goblin alchemy supplier, can be found on top of the wall in the northern part of the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "Uplands",
			short = "The Uplands is a region with hills in northeastern Alterac Mountains.",
			full = "The Uplands is a region with hills in northeastern Alterac Mountains. It was the bread basket of the kingdom of Alterac, but after the destruction of the core of that nation, the Uplands fell under the control of the Syndicate, who have several camps in the area. This area is where they are strongest. Baron Vardus could be found here. Dandred's Fold is found in the westernmost part of the Uplands.\n\nNo quests take place here anymore and this area no longer serves any purpose.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Arathi Highlands: 46 subzones
	[1417] = {
		["argorok"] = {
			name = "Ar'gorok",
			short = "Ar'gorok was a Horde fortress located on the northwestern part of the Arathi Highlands.",
			full = "Ar'gorok was a Horde fortress located on the northwestern part of the Arathi Highlands.",
			source = "https://warcraft.wiki.gg/wiki/Ar'gorok",
		},
		["barracks stromgarde keep"] = {
			name = "Barracks (Stromgarde Keep)",
			short = "Barracks is located at Stromgarde Keep in Arathi Highlands.",
			full = "Barracks is located at Stromgarde Keep in Arathi Highlands.",
			source = "https://warcraft.wiki.gg/wiki/Barracks_(Stromgarde_Keep)",
		},
		["boulderfist hall"] = {
			name = "Boulderfist Hall",
			short = "Boulderfist Hall is a fortress of the Boulderfist ogres in southern Arathi Highlands, near Thandol Span and Witherbark Village.",
			full = "Boulderfist Hall is a fortress of the Boulderfist ogres in southern Arathi Highlands, near Thandol Span and Witherbark Village. The ogre mound is strongly fortified, and inside the larger cave you can find chief Kor'gresh Coldrage.\n\nBy the time of the Battle for Stromgarde, the Boulderfist still remained active in this area, having expanded their camp out into the surrounding hills and fortified it better.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["boulderfist outpost"] = {
			name = "Boulderfist Outpost",
			short = "Boulderfist Outpost is an ogre mound found inside of Boulder'gor in western Arathi Highlands. The majority of the ogres in this area are found inside the outpost, while only a few forest trolls are found within.",
			full = "Boulderfist Outpost is an ogre mound found inside of Boulder'gor in western Arathi Highlands. The majority of the ogres in this area are found inside the outpost, while only a few forest trolls are found within.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Outpost",
		},
		["bouldergor"] = {
			name = "Boulder'gor",
			short = "Boulder'gor is a hill found north of Stromgarde Keep in the Arathi Highlands. It is home to some of the Boulderfist ogres and where several forest trolls of the Witherbark tribe hangout.",
			full = "Boulder'gor is a hill found north of Stromgarde Keep in the Arathi Highlands. It is home to some of the Boulderfist ogres and where several forest trolls of the Witherbark tribe hangout. The ogre mound of Boulderfist Outpost is within.\n\nThe Circle of Elements was built on the eastern side of the hill as well as a pair of farms just south of it.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["brew bay"] = {
			name = "Brew Bay",
			short = "Brew Bay is the lobby and waiting room of Plunderstorm. Captain Keg Leg and Keg Leg's Crew have set up here in an attempt to gather plunder.",
			full = "Brew Bay is the lobby and waiting room of Plunderstorm. Captain Keg Leg and Keg Leg's Crew have set up here in an attempt to gather plunder. The bay is located where the Arathi coast dwarven farm would be in non-Plunderstorm realms on the southeastern shore of the Arathi Highlands.\n\nThe area also serves as a training room, letting players interact with mechanics, loot chests to acquire spells, and practice combat/revival in the untimed Practice mode, or briefly before the match begins.",
			source = "https://warcraft.wiki.gg/wiki/Brew_Bay",
		},
		["circle of east binding"] = {
			name = "Circle of East Binding",
			short = "Circle of East Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the eastern part of the region, near Hammerfall and is the location of the Stone of East Binding guarded by water elementals.",
			full = "Circle of East Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the eastern part of the region, near Hammerfall and is the location of the Stone of East Binding guarded by water elementals.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of elements"] = {
			name = "Circle of Elements",
			short = "The Circle of Elements is a location in western Arathi Highlands.",
			full = "The Circle of Elements is a location in western Arathi Highlands. As a contested foothold in the Battle for Stromgarde, control over the Circle of Elements provides the adventurer's faction access to magic warfare by harnessing the power of the elements. Depending on who controls the area, an Alliance or Horde mage tower will be built in front of the circle.\n\nAfter each phase of the battle, the adventurers are tasked to scavenge the area, in order to replenish their faction's depleted supplies. At some point, the magic that bound the elementals to the land began to weaken, until they eventually burst free of their bonds across the Highlands. Adventurers were later sent by their faction to destroy them before they could rage across the newly claimed territories.\n\nSince the canonical ending to the Warfront was the Alliance victory, the Circle of Elements is under Stromgarde control.\n\nAfter the Battle of Go'Shek Farm, the area was taken over by fire elementals.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Elements",
		},
		["circle of inner binding"] = {
			name = "Circle of Inner Binding",
			short = "Circle of Inner Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the southern part of the region, near Stromgarde Keep, and is guarded by earth elementals.",
			full = "Circle of Inner Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the southern part of the region, near Stromgarde Keep, and is guarded by earth elementals. The Stone of Inner Binding, the strongest of the stones, lies here.\n\nIt is through this circle's shard that Myzrael was able to contact mortal travelers.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Circle of Outer Binding",
			short = "Circle of Outer Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the central part of the region, near Refuge Pointe.",
			full = "Circle of Outer Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the central part of the region, near Refuge Pointe. The Stone of Outer Binding is guarded by air elementals.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Circle of West Binding",
			short = "Circle of West Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the western part of the region, near Thoradin's Wall.",
			full = "Circle of West Binding is one of the Circles of Binding in the Arathi Highlands. It lies in the western part of the region, near Thoradin's Wall. It's here the Stone of West Binding is guarded by fire elementals.\n\nAfter the Horde built their settlement Ar'gorok, the Circle of West Binding can no longer be found. In its place is Hatchet Ridge, where the Horde gathers lumber.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["clearfells patch"] = {
			name = "Clearfell's Patch",
			short = "Clearfell's Patch is a subzone by the northern end of Thoradin's Wall in the Arathi Highlands in the Plunderstorm.",
			full = "Clearfell's Patch is a subzone by the northern end of Thoradin's Wall in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Clearfell's_Patch",
		},
		["contested pass"] = {
			name = "Contested Pass",
			short = "The Contested Pass is a subzone found east of Ar'gorok in the Arathi Highlands in the Plunderstorm.",
			full = "The Contested Pass is a subzone found east of Ar'gorok in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Contested_Pass",
		},
		["crypt stromgarde keep"] = {
			name = "Crypt (Stromgarde Keep)",
			short = "The Crypt is located in the Sanctum of Stromgarde Keep, in the Arathi Highlands, deep in the militia-controlled districts of the city and beyond its chapel.",
			full = "The Crypt is located in the Sanctum of Stromgarde Keep, in the Arathi Highlands, deep in the militia-controlled districts of the city and beyond its chapel. This crypt holds the tomb of Thoras Trollbane, and was the location of the sword Trol'kalar. The tomb was once personally guarded by Prince Galen Trollbane, alongside the caretakers Alaric, Nevlin, and Weston.\n\nDuring the third invasion of the Burning Legion, the crypt was opened by the Knights of the Ebon Blade with Trol'kalar who raised King Thoras Trollbane as a member of the Four Horsemen. When the death knights left, Trol'kalar was stolen. Not long after Thoras's rebirth, Mathias Shaw visited the crypt and found the tomb empty.",
			source = "https://warcraft.wiki.gg/wiki/Crypt_(Stromgarde_Keep)",
		},
		["dabyries farmstead"] = {
			name = "Dabyrie's Farmstead",
			short = "Dabyrie's Farmstead is a farm located in the northern reaches of the Arathi Highlands.",
			full = "Dabyrie's Farmstead is a farm located in the northern reaches of the Arathi Highlands. It is the home of the Dabyrie family -- Kenata Dabyrie and her children Fardel and Marcel -- citizens of the kingdom of Stromgarde and members of the Alliance. The farmstead is protected by the Dabyrie Militia.\n\nThe rare wasp Boros is found in the hills directly northwest of the farm.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Drowned Reef",
			short = "The Drowned Reef is a dangerous and mysterious reef on the southern shores of Arathi Highlands.",
			full = "The Drowned Reef is a dangerous and mysterious reef on the southern shores of Arathi Highlands.\n\nThe dangers of the reef are many, and numerous ships have found their last harbor there, including Maiden's Folly and Spirit of Silverpine. Under the waters of the bay lies a ruined, sunken, ancient elven city, which is now inhabited by the naga of the Daggerspine tribe, who are led by Prince Nazjak.\n\nThe Daggerspine seem to be able to control the tides of the bay, dooming many hapless crews trying to find refuge in Faldir's Cove.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Drywhisker Gorge",
			short = "Drywhisker Gorge is a gorge cutting through the mountains in the eastern section the Arathi Highlands, northeast of Hammerfall. At the end of the gorge lies a cave.",
			full = "Drywhisker Gorge is a gorge cutting through the mountains in the eastern section the Arathi Highlands, northeast of Hammerfall. At the end of the gorge lies a cave. It is currently inhabited by the Drywhisker kobolds. Deep within the cave, a mysterious stone shard can be found in which a piece of the essence of Princess Myzrael was trapped.\n\nThese kobolds, allies to the giants, guard the motes and the shard within.\n\nBy the time of the Battle for Stromgarde, the Drywhisker kobolds still remained active in this area. Among them, Geomancer Flintdagger and Overseer Krix were priority targets. Krix eventually succumbed to his opponents, and the [Lil' Donkey] that was to be his dinner was saved and found a new home.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["drywhisker mine"] = {
			name = "Drywhisker Mine",
			short = "Drywhisker Mine is located right next to Ar'gorok, in northwestern Arathi Highlands, and it is the primary source of iron for the Horde stronghold.",
			full = "Drywhisker Mine is located right next to Ar'gorok, in northwestern Arathi Highlands, and it is the primary source of iron for the Horde stronghold. This mine is a contested foothold in the Battle for Stromgarde.\n\nAs the canonical ending to the Warfront was the Alliance victory, Drywhisker Mine fell under control of the Drywhisker kobolds.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Mine",
		},
		["faldirs cove"] = {
			name = "Faldir's Cove",
			short = "Faldir's Cove is a small natural harbor on the southern shores of Arathi Highlands, near Stromgarde Keep and the Drowned Reef.",
			full = "Faldir's Cove is a small natural harbor on the southern shores of Arathi Highlands, near Stromgarde Keep and the Drowned Reef.\n\nThe cove is named after Faldir, apparently marking the spot where he and his followers began their voyage across the sea to create the kingdom of Stormwind.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["fishing shack arathi highlands"] = {
			name = "Fishing Shack (Arathi Highlands)",
			short = "The Fishing Shack is located at Faldir's Cove in Arathi Highlands.",
			full = "The Fishing Shack is located at Faldir's Cove in Arathi Highlands.",
			source = "https://warcraft.wiki.gg/wiki/Fishing_Shack_(Arathi_Highlands)",
		},
		["forsaken wagon"] = {
			name = "Forsaken Wagon",
			short = "The Forsaken Wagon is a subzone found northwest of Boulderfist Hall in the Arathi Highlands in the Plunderstorm. It's guarded by a group of Forsaken.",
			full = "The Forsaken Wagon is a subzone found northwest of Boulderfist Hall in the Arathi Highlands in the Plunderstorm. It's guarded by a group of Forsaken.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_Wagon",
		},
		["galens fall"] = {
			name = "Galen's Fall",
			short = "Galen's Fall was a Forsaken camp along Thoradin's Wall near the entrance into the Hillsbrad Foothills from the Arathi Highlands.",
			full = "Galen's Fall was a Forsaken camp along Thoradin's Wall near the entrance into the Hillsbrad Foothills from the Arathi Highlands.\n\nIt was at this place that Prince Galen Trollbane was killed by the Forsaken. The former prince asked Horde adventurers to retrieve Trol'kalar for him.\n\nYears later, on the day before the Gathering, Elsie Benton and Parqual Fintallas met at Galen's Fall to discuss the upcoming meeting. Annie Lansing was also present, giving her fellow Forsaken scarves and sachets.",
			source = "https://warcraft.wiki.gg/wiki/Galen's_Fall",
		},
		["galsons lode"] = {
			name = "Galson's Lode",
			short = "Galson's Lode is a mine located not far from Stromgarde Keep and right next to to the Circle of Inner Binding, in midwestern Arathi Highlands.",
			full = "Galson's Lode is a mine located not far from Stromgarde Keep and right next to to the Circle of Inner Binding, in midwestern Arathi Highlands.\n\nAs a contested foothold in the Battle for Stromgarde, this mine is the primary source of iron for Stromgarde Keep, and its workers ensure the iron supply never runs dry. In charge of the mine, Foreman Tully mentioned that the Horde were a thorn in their side, and the kobolds annoying, but nothing the miners couldn't handle. At some point, adventurers were sent to encounter Overseer Krix, who eventually succumbed to his opponents, while the [Lil' Donkey] that was to be his dinner was saved and found a new home.\n\nSince the canonical ending to the Warfront was the Alliance victory, Galson's Lode is under Stromgarde control.",
			source = "https://warcraft.wiki.gg/wiki/Galson's_Lode",
		},
		["goblin workshop argorok"] = {
			name = "Goblin Workshop (Ar'gorok)",
			short = "The Goblin Workshop is located at Ar'gorok in the Arathi Highlands.",
			full = "The Goblin Workshop is located at Ar'gorok in the Arathi Highlands.",
			source = "https://warcraft.wiki.gg/wiki/Goblin_Workshop_(Ar'gorok)",
		},
		["goblin workshop stromgarde keep"] = {
			name = "Goblin Workshop (Stromgarde Keep)",
			short = "The Goblin Workshop is a subzone found inside Stromgarde Keep in the Arathi Highlands in the Plunderstorm.",
			full = "The Goblin Workshop is a subzone found inside Stromgarde Keep in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Goblin_Workshop_(Stromgarde_Keep)",
		},
		["goshek farm"] = {
			name = "Go'Shek Farm",
			short = "Go'Shek Farm is a farmstead in the eastern part of the Arathi Highlands, near Witherbark Village. The farm is protected by Hammerfall Grunts.",
			full = "Go'Shek Farm is a farmstead in the eastern part of the Arathi Highlands, near Witherbark Village. The farm is protected by Hammerfall Grunts.\n\nThe rare armored boar Swee can be found in the stables of the farm.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Hammerfall",
			short = "Hammerfall is the capital city of the Mag'har Clans within the Arathi Highlands.",
			full = "Hammerfall is the capital city of the Mag'har Clans within the Arathi Highlands. It was once one of the largest of the Alliance of Lordaeron's internment camps, and where Orgrim Doomhammer fell during the liberation of the orcs by Warchief Thrall. Following the Third War, the ruins were re-occupied by the Horde as the unofficial refuge for discontents who felt that they had no place in the current world.\n\nIt has two spirit lodges, stables, a blacksmith, and a great hall.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["hatchet ridge"] = {
			name = "Hatchet Ridge",
			short = "Hatchet Ridge is a lumber mill located in northwestern Arathi Highlands, and it was the primary source of lumber for Ar'gorok. It is a contested foothold in the Battle for Stromgarde.",
			full = "Hatchet Ridge is a lumber mill located in northwestern Arathi Highlands, and it was the primary source of lumber for Ar'gorok. It is a contested foothold in the Battle for Stromgarde.\n\nAs the canonical ending to the Warfront was the Alliance victory, Hatchet Ridge fell under control of a group of wildkin.",
			source = "https://warcraft.wiki.gg/wiki/Hatchet_Ridge",
		},
		["high perch"] = {
			name = "High Perch",
			short = "High Perch is an outpost located on a high hill in the Arathi Highlands, in between Stromgarde Keep and Ar'gorok. It has a large tower along with a defensible camp.",
			full = "High Perch is an outpost located on a high hill in the Arathi Highlands, in between Stromgarde Keep and Ar'gorok. It has a large tower along with a defensible camp.\n\nAs a contested foothold in the Battle for Stromgarde, High Perch was valued by the Alliance and the Horde for its strategic central location and its ability to provide the adventurer's faction access to a safe flight network to the other controlled footholds. After each phase of the battle, the adventurers are tasked to scavenge the area, in order to replenish their faction's depleted supplies.\n\nSince the canonical ending to the Warfront was the Alliance victory, High Perch is under Stromgarde control.",
			source = "https://warcraft.wiki.gg/wiki/High_Perch",
		},
		["highlands mill"] = {
			name = "Highlands Mill",
			short = "Highlands Mill is a lumber mill located in western Arathi Highlands. As a contested foothold in the Battle for Stromgarde, this lumber mill is the primary source of lumber for Stromgarde Keep.",
			full = "Highlands Mill is a lumber mill located in western Arathi Highlands. As a contested foothold in the Battle for Stromgarde, this lumber mill is the primary source of lumber for Stromgarde Keep. At some point, Mathias Shaw's agents spotted the wildkin Rageback in the area, and adventurers were sent to eliminate it. Since the canonical ending to the Warfront was the Alliance victory, Highlands Mill is under Stromgarde control.",
			source = "https://warcraft.wiki.gg/wiki/Highlands_Mill",
		},
		["labors rest"] = {
			name = "Labor's Rest",
			short = "Labor's Rest is a graveyard found east of the Highlands Mill in the Arathi Highlands in the Plunderstorm.",
			full = "Labor's Rest is a graveyard found east of the Highlands Mill in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Labor's_Rest",
		},
		["mage tower plunderstorm"] = {
			name = "Mage Tower (Plunderstorm)",
			short = "The Mage Tower is a subzone found at Circle of Elements in the Arathi Highlands in the Plunderstorm.",
			full = "The Mage Tower is a subzone found at Circle of Elements in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Mage_Tower_(Plunderstorm)",
		},
		["mangled chord"] = {
			name = "Mangled Chord",
			short = "The Mangled Chord is a subzone found southwest of Circle of Outer Binding in the Arathi Highlands in the Plunderstorm.",
			full = "The Mangled Chord is a subzone found southwest of Circle of Outer Binding in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Mangled_Chord",
		},
		["marrows farm"] = {
			name = "Marrow's Farm",
			short = "Marrow's Farm is a subzone found between Circle of Elements and Valorcall Pass in the Arathi Highlands in the Plunderstorm.",
			full = "Marrow's Farm is a subzone found between Circle of Elements and Valorcall Pass in the Arathi Highlands in the Plunderstorm.",
			source = "https://warcraft.wiki.gg/wiki/Marrow's_Farm",
		},
		["neglected seat"] = {
			name = "Neglected Seat",
			short = "The Neglected Seat is a subzone found between Dabyrie's Farmstead and Circle of East Binding in the Arathi Highlands in the Plunderstorm.",
			full = "The Neglected Seat is a subzone found between Dabyrie's Farmstead and Circle of East Binding in the Arathi Highlands in the Plunderstorm. It is inhabited by Water Elementals and Raging Waters.",
			source = "https://warcraft.wiki.gg/wiki/Neglected_Seat",
		},
		["newstead"] = {
			name = "Newstead",
			short = "Newstead is a farmstead located on the road to Thoradin's Wall, in western Arathi Highlands.",
			full = "Newstead is a farmstead located on the road to Thoradin's Wall, in western Arathi Highlands.",
			source = "https://warcraft.wiki.gg/wiki/Newstead",
		},
		["northfold crossing"] = {
			name = "Northfold Crossing",
			short = "Northfold Crossing is a crossroads located in front of Ar'gorok in the Arathi Highlands. It is the last foothold buffering the Horde stronghold from the Alliance during the Battle for Stromgarde.",
			full = "Northfold Crossing is a crossroads located in front of Ar'gorok in the Arathi Highlands. It is the last foothold buffering the Horde stronghold from the Alliance during the Battle for Stromgarde. There is a small camp with two siege towers defending the intersection from invaders. However, should the foothold fall to the Alliance, the siege towers will lie in ruins.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Crossing",
		},
		["northfold manor"] = {
			name = "Northfold Manor",
			short = "A rare spawn named Singer appeared in the small house here.",
			full = "A rare spawn named Singer appeared in the small house here.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Refuge Pointe",
			short = "Refuge Pointe is a Stromic outpost located in the Arathi Highlands. The inn is the southernmost tent, and there is an Alliance entrance to the Arathi Basin.",
			full = "Refuge Pointe is a Stromic outpost located in the Arathi Highlands. The inn is the southernmost tent, and there is an Alliance entrance to the Arathi Basin.\n\nFollowing the Third War in 21 ADP, when the Stromgarde capital fell in ruins, most of the populace fled south while the proud remnants of the Stromgarde army stayed behind, determined to fight on to reclaim their land. The Alliance's military operations were conducted from here, and were most concerned with aiding the kingdom forces in retaking their former capital, but also to secure resources for the Alliance in the Highlands.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["sanctum stromgarde keep"] = {
			name = "Sanctum (Stromgarde Keep)",
			short = "The Sanctum is the area beyond the chapel of the Church of Light found within Stromgarde Keep, leading to the Trollbane family crypt.",
			full = "The Sanctum is the area beyond the chapel of the Church of Light found within Stromgarde Keep, leading to the Trollbane family crypt. A graveyard is also present next to the church.\n\nFor a time it was under the control of the Alliance with Stromgarde Soldiers found inside. Prior to his first death, the chapel was where Prince Galen Trollbane could be found. Ironically, this is also where he met his final fate at the hands of the Knights of the Ebon Blade, who also came to raise King Thoras Trollbane as a death knight during the third invasion of the Burning Legion.\n\nThe day before the Gathering, the human citizens present for the meeting were taken to the chapel, where the Conclave priests, Alonsus Faol and Calia Menethil, gave them their blessings. King Anduin Wrynn and High Exarch Turalyon were also present to attend the Archbishop's mass.",
			source = "https://warcraft.wiki.gg/wiki/Sanctum_(Stromgarde_Keep)",
		},
		["stromgarde keep"] = {
			name = "Stromgarde Keep",
			short = "Stromgarde Keep, also known simply as Stromgarde, is the capital city of the kingdom of Stromgarde, located in the southwest of the Arathi Highlands.",
			full = "Stromgarde Keep, also known simply as Stromgarde, is the capital city of the kingdom of Stromgarde, located in the southwest of the Arathi Highlands. In ages past, the settlement was a cradle for human civilization, when it served as the capital of the Arathorian Empire under the name of Strom. By the time of the arrival of the Orcish Horde, it stood as a major power center as part of the Alliance of Lordaeron during and after some time following the Second War.\n\nStromgarde was eventually sacked and left in ruins at some point after the events of the Third War and remained in this condition for many years to follow. It was divided into three sections -- one around the inner keep itself and under the rule of the Syndicate, the former mage district largely under the control of the Boulderfist clan ogres with aid from the Witherbark trolls, while the last section remained under the control of the Stromgarde military and once served as the headquarters of Prince Galen Trollbane, until his death.\n\nSupported by the Alliance and led by Danath Trollbane, the League of Arathor fully re-established itself in Stromgarde and began restoring the settlement to its former glory. However, it soon became the focal point of the conflict between the Alliance and the Horde for control of the Arathi Highlands. Ultimately, the Alliance managed to defeat the Horde, returning most of Arathi into the hands of Stromgarde after many years of strife.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "The Thandol Span is a set of massive stone bridges connecting the Wetlands of northern Khaz Modan with the Arathi Highlands of southeastern Lordaeron.",
			full = "The Thandol Span is a set of massive stone bridges connecting the Wetlands of northern Khaz Modan with the Arathi Highlands of southeastern Lordaeron. It is one of the greatest engineering projects ever completed by the dwarves, having been under the guard of the Anvilmars for at least three generations. The area where it is located was once known as the Thandol Valley.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "Thoradin's Wall is a gigantic heavily damaged wall separating the Arathi Highlands from Hillsbrad Foothills. It was built under the Empire of Arathor to protect mankind from the Amani trolls.",
			full = "Thoradin's Wall is a gigantic heavily damaged wall separating the Arathi Highlands from Hillsbrad Foothills. It was built under the Empire of Arathor to protect mankind from the Amani trolls.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Tower of Arathor",
			short = "The Tower of Arathor is a mage tower located in the former mage district in the southwestern part of Stromgarde Keep, in the Arathi Highlands.",
			full = "The Tower of Arathor is a mage tower located in the former mage district in the southwestern part of Stromgarde Keep, in the Arathi Highlands. It is named after the Empire of Arathor.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["valorcall pass"] = {
			name = "Valorcall Pass",
			short = "Valorcall Pass is a crossroads located in front of Stromgarde Keep in the Arathi Highlands. It is the last foothold buffering the Alliance stronghold from the Horde during the Battle for Stromgarde.",
			full = "Valorcall Pass is a crossroads located in front of Stromgarde Keep in the Arathi Highlands. It is the last foothold buffering the Alliance stronghold from the Horde during the Battle for Stromgarde. There is a small camp with two siege towers defending the road to the citadel from invaders. However, should the foothold fall to the Horde, the siege towers will lie in ruins.\n\nAfter the Battle of Go'Shek Farm, Stromgarde Stonemasons were seen working in the area.",
			source = "https://warcraft.wiki.gg/wiki/Valorcall_Pass",
		},
		["witherbark village"] = {
			name = "Witherbark Village",
			short = "Witherbark Village is a village, around a small lake in the southeast area of the Arathi Highlands, of trolls belonging to the Witherbark tribe.",
			full = "Witherbark Village is a village, around a small lake in the southeast area of the Arathi Highlands, of trolls belonging to the Witherbark tribe. Behind the village is a large cavern, where the leaders of the tribe are often found.\n\nThe Witherbark trolls have made a loose alliance with the nearby Boulderfist clan of ogres against the forces of Stromgarde and Hammerfall. The ogre and troll forces have even secured and are currently in control of a section of Stromgarde itself.\n\nBy the time of the Battle for Stromgarde, the Witherbark trolls still remained active in this area and were the target of the Alliance and the Horde who wished to see them disappear. Among them, Nimar the Slayer was a priority target for his dangerousness, taking many fighters with him in death.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Badlands: 30 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Agmond's End",
			short = "Agmond's End is an abandoned dig site in the southern central Badlands, where the dwarven prospector Agmond met an unfortunate end thanks to the troggs that had infested the site.",
			full = "Agmond's End is an abandoned dig site in the southern central Badlands, where the dwarven prospector Agmond met an unfortunate end thanks to the troggs that had infested the site.\n\nTheldurin relocated to a small camp within the Scar of the Worldbreaker. But a gnome by the name of Dr. Hieronymus Blam moved in instead. He created several Blam Turrets situated nearby.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Angor Fortress",
			short = "Angor Fortress is the main site of operations of the Dark Iron dwarves in the Badlands. Here, they organize their exploration for exploiting Uldaman.",
			full = "Angor Fortress is the main site of operations of the Dark Iron dwarves in the Badlands. Here, they organize their exploration for exploiting Uldaman. An agent of Ragnaros, Ambassador Infernus, also resides in this keep.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Apocryphan's Rest",
			short = "Apocryphan's Rest is the name of a large draconic skeleton that lies fallen in the Badlands south of Kargath. It is populated by a flock of hungry buzzards.",
			full = "Apocryphan's Rest is the name of a large draconic skeleton that lies fallen in the Badlands south of Kargath. It is populated by a flock of hungry buzzards.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["bloodwatcher point"] = {
			name = "Bloodwatcher Point",
			short = "Bloodwatcher Point is a new Horde encampment in the Badlands located northwest of Camp Boff and south of the Tomb of the Watchers.",
			full = "Bloodwatcher Point is a new Horde encampment in the Badlands located northwest of Camp Boff and south of the Tomb of the Watchers. It has been set up by blood elves of the Reliquary, a Horde equivalent of the Explorers' League, and serves as a quest hub. It also contains a flight master. It is made up from tents, a wagon and decorated by banners.",
			source = "https://warcraft.wiki.gg/wiki/Bloodwatcher_Point",
		},
		["camp boff"] = {
			name = "Camp Boff",
			short = "Camp Boff is, together with Camp Cagg, Kosh, and Wurg, the home of some of the Dustbelcher ogres. It is the southeastern camp, only guarded by three Dustbelcher ogres.",
			full = "Camp Boff is, together with Camp Cagg, Kosh, and Wurg, the home of some of the Dustbelcher ogres. It is the southeastern camp, only guarded by three Dustbelcher ogres. One exception though was their leader, Boss Tho'grun, who patrolled the Badlands between the four ogre bases.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Camp Cagg",
			short = "Camp Cagg is, together with Camp Boff, Kosh and Wurg, the home of some of the Dustbelcher ogres. One exception though was their leader, Boss Tho'grun, who patrolled the Badlands between the four ogre bases.",
			full = "Camp Cagg is, together with Camp Boff, Kosh and Wurg, the home of some of the Dustbelcher ogres. One exception though was their leader, Boss Tho'grun, who patrolled the Badlands between the four ogre bases.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Camp Kosh",
			short = "Camp Kosh is, together with Camp Boff, Cagg and Wurg, the home of some of the Dustbelcher ogres. It is the northernmost camp.",
			full = "Camp Kosh is, together with Camp Boff, Cagg and Wurg, the home of some of the Dustbelcher ogres. It is the northernmost camp. There the ogres prey on supply caravans that must traverse the barren Badlands headed to Kargath or into the Searing Gorge.\n\nWhen Sigrun Ironhew and his men left the Uldaman excavation site, they were forced to abandon many wagons and crates of supplies along the way. The ogres from Camp Kosh plundered their abandoned equipment, which consisted of all their weapons and food. He later tasked Alliance adventurers to recover theirs supplies.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Camp Wurg",
			short = "Camp Wurg is, together with Camp Cagg, Boff and Kosh, the homes of some of the Dustbelcher ogres. One exception though was their leader, Boss Tho'grun, who patrolled the Badlands between the four ogre bases.",
			full = "Camp Wurg is, together with Camp Cagg, Boff and Kosh, the homes of some of the Dustbelcher ogres. One exception though was their leader, Boss Tho'grun, who patrolled the Badlands between the four ogre bases.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["crypt badlands"] = {
			name = "Crypt (Badlands)",
			short = "The Badlands Crypt is located southeast of Hammertoe's Digsite, at the top of the hill behind Sigrun Ironhew. Its entrance is via a natural and unmarked path up the hill.",
			full = "The Badlands Crypt is located southeast of Hammertoe's Digsite, at the top of the hill behind Sigrun Ironhew. Its entrance is via a natural and unmarked path up the hill. The bottom of the Crypt contains a number of urns, chests, and skeletons, with the centerpiece being an armored skeleton seated on a throne with the Sword of the Barbarian King next to it.",
			source = "https://warcraft.wiki.gg/wiki/Crypt_(Badlands)",
		},
		["dragons mouth"] = {
			name = "Dragon's Mouth",
			short = "Dragon's Mouth is an Alliance camp in the southwestern Badlands. It is situated northeast of Camp Cagg and southeast of New Kargath, at the southwest end of the Scar of the Worldbreaker.",
			full = "Dragon's Mouth is an Alliance camp in the southwestern Badlands. It is situated northeast of Camp Cagg and southeast of New Kargath, at the southwest end of the Scar of the Worldbreaker. It has flight paths connecting to Fuselight, Dustwind Dig, and Morgan's Vigil, a functioning mailbox, repair and trade goods vendor, and a tiny inn consisting of a tent.\n\nTerrance sent Alliance adventurers to preemptively thin the ogres' ranks. The black dragons' ravaging of the camp's would-be hunting grounds left Dragon's Mouth short on supplies, so Victoria Dolen sent adventurers to obtain food and crafting supplies from the ogres.",
			source = "https://warcraft.wiki.gg/wiki/Dragon's_Mouth",
		},
		["dustbelch grotto"] = {
			name = "Dustbelch Grotto",
			short = "Dustbelch Grotto is a large ogre mound in southwestern Badlands. It is home to the Dustbelcher ogres.",
			full = "Dustbelch Grotto is a large ogre mound in southwestern Badlands. It is home to the Dustbelcher ogres.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Dustbowl",
			short = "The Dustbowl is a large area of the northwest of Badlands between kargath and valley of fangs (center of Badlands). It is home to a variety of species including coyotes, Rock Elementals, and buzzards.",
			full = "The Dustbowl is a large area of the northwest of Badlands between kargath and valley of fangs (center of Badlands). It is home to a variety of species including coyotes, Rock Elementals, and buzzards. Some flora have been able to grow on the arid landscape such as a myriad of cacti and a few trees. This place also contains Camp Wurg.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind dig"] = {
			name = "Dustwind Dig",
			short = "Dustwind Dig is situated in the hills above Hammertoe's Digsite in the Badlands and is the expanded Alliance camp of Sigrun Ironhew.",
			full = "Dustwind Dig is situated in the hills above Hammertoe's Digsite in the Badlands and is the expanded Alliance camp of Sigrun Ironhew. It contains a flight path.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Dig",
		},
		["dustwind gulch"] = {
			name = "Dustwind Gulch",
			short = "Dustwind Gulch is located in the Badlands to the west of Lethlor Ravine.",
			full = "Dustwind Gulch is located in the Badlands to the west of Lethlor Ravine.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["fuselight"] = {
			name = "Fuselight",
			short = "Fuselight is a new town in the Lethlor Ravine of the Badlands. It is run by the Steamwheedle Cartel goblins, and unlike most of the smaller towns the few quests there will award reputation with them.",
			full = "Fuselight is a new town in the Lethlor Ravine of the Badlands. It is run by the Steamwheedle Cartel goblins, and unlike most of the smaller towns the few quests there will award reputation with them. It contains a goblin laboratory.\n\nGek Nozzlerocket is a Fuselight recruiter in the Eastern Plaguelands.",
			source = "https://warcraft.wiki.gg/wiki/Fuselight",
		},
		["fuselight by the sea"] = {
			name = "Fuselight-by-the-Sea",
			short = "Fuselight-by-the-Sea is a picturesque seaside town founded by explosives enthusiasts for explosives enthusiasts.",
			full = "Fuselight-by-the-Sea is a picturesque seaside town founded by explosives enthusiasts for explosives enthusiasts. This new Steamwheedle Cartel port town in the Badlands is connected via transporter to its sister town, also in the Badlands, Fuselight. Questing players get sent here from Light's Hope Chapel in Eastern Plaguelands by way of rocket in one of the central breadcrumb quests ( [15-30] Hero's Call: Badlands! / [15-30] Warchief's Command: Badlands!)",
			source = "https://warcraft.wiki.gg/wiki/Fuselight-by-the-Sea",
		},
		["hammertoes digsite"] = {
			name = "Hammertoe's Digsite",
			short = "Hammertoe's Digsite lies in the northern part of the Badlands. The dig has recently been abandoned by Hammertoe and taken over by a gang of Dark Irons, presumably part of the same force that has moved into Uldaman.",
			full = "Hammertoe's Digsite lies in the northern part of the Badlands. The dig has recently been abandoned by Hammertoe and taken over by a gang of Dark Irons, presumably part of the same force that has moved into Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["hidden clutch"] = {
			name = "Hidden Clutch",
			short = "The Hidden Clutch is a small area in the mountains directly north of New Kargath in the Badlands. It has a small cave and a handful of patrolling Rock Elementals.",
			full = "The Hidden Clutch is a small area in the mountains directly north of New Kargath in the Badlands. It has a small cave and a handful of patrolling Rock Elementals.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Clutch",
		},
		["kargath"] = {
			name = "Kargath",
			short = "Kargath was at its time the only Horde outpost in Khaz Modan, named after the Shattered Hand clan chieftain Kargath Bladefist.",
			full = "Kargath was at its time the only Horde outpost in Khaz Modan, named after the Shattered Hand clan chieftain Kargath Bladefist.\n\nKargath's flight path was very important because it linked the northern and the southern areas of Horde flight paths on the Eastern Kingdoms. It linked Hammerfall and the Undercity in the north to Grom'Gol, Booty Bay, and Stonard in the south.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Lethlor Ravine",
			short = "Lethlor Ravine is a wide craggy valley located in the eastern section of the Badlands.",
			full = "Lethlor Ravine is a wide craggy valley located in the eastern section of the Badlands. It is populated with dragon whelps and drakes from the black dragonflight, and contains several crystalline obelisks that are part of a quest chain.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Maker's Terrace",
			short = "The Maker's Terrace is a large excavation site located just outside the entrance to Uldaman in the Badlands.",
			full = "The Maker's Terrace is a large excavation site located just outside the entrance to Uldaman in the Badlands. For most adventurers first venturing into the Badlands from Loch Modan, it will be the first place they travel past. The Terrace is patrolled by Dark Iron dwarves.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Mirage Flats",
			short = "The Mirage Flats is located east of Dustbelch Grotto in the Badlands. It lays between Dragon's Mouth and New Kargath. It is populated primarily by Giant Buzzards, Ridge Stalker Patriarchs, and Rabid Crag Coyotes.",
			full = "The Mirage Flats is located east of Dustbelch Grotto in the Badlands. It lays between Dragon's Mouth and New Kargath. It is populated primarily by Giant Buzzards, Ridge Stalker Patriarchs, and Rabid Crag Coyotes.\n\nWhat little remains of it makes up part of the no-man's land between New Kargath and Dragon's Mouth.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["new kargath"] = {
			name = "New Kargath",
			short = "It is a full-fledged town and appears to be under constant attack by members of the Black dragonflight, and its blacksmith is occupied by them.",
			full = "It is a full-fledged town and appears to be under constant attack by members of the Black dragonflight, and its blacksmith is occupied by them.\n\nThe town is equipped with several catapults and blade throwers.",
			source = "https://warcraft.wiki.gg/wiki/New_Kargath",
		},
		["rheas camp"] = {
			name = "Rhea's Camp",
			short = "Rhea's Camp is a very small dot of land located in Lethlor Ravine of the Badlands.",
			full = "Rhea's Camp is a very small dot of land located in Lethlor Ravine of the Badlands.\n\nThe only inhabitant is Rhea, a neutral Goblin who is in fact a red dragon in disguise.",
			source = "https://warcraft.wiki.gg/wiki/Rhea's_Camp",
		},
		["ruins of kargath"] = {
			name = "Ruins of Kargath",
			short = "The Ruins of Kargath lie within the Badlands. The area is now overrun with Nyxondra's Broodlings, small black dragon whelps, guarded by their ever watchful parent, Nyxondra.",
			full = "The Ruins of Kargath lie within the Badlands. The area is now overrun with Nyxondra's Broodlings, small black dragon whelps, guarded by their ever watchful parent, Nyxondra.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kargath",
		},
		["scar of the worldbreaker"] = {
			name = "Scar of the Worldbreaker",
			short = "It stretches from just south of Angor Fortress to the southwest corner of the zone.",
			full = "It stretches from just south of Angor Fortress to the southwest corner of the zone.\n\nCamp Wurg, Valley of Fangs and large portions of the Dustbowl and Mirage Flats are now a charred swath of destruction, with the nearby mountaintops sheared off. The tops of these mountains simmer like molten glass.",
			source = "https://warcraft.wiki.gg/wiki/Scar_of_the_Worldbreaker",
		},
		["tomb of the watchers"] = {
			name = "Tomb of the Watchers",
			short = "The Tomb of the Watchers is a dig site in the Badlands that shares an appearance with that of Uldaman.",
			full = "The Tomb of the Watchers is a dig site in the Badlands that shares an appearance with that of Uldaman. Both Alliance and Horde excavators scour and hammer away at the land nearby, as the Alliance camp of Dustwind Dig overlooks it from the hills and the Horde camp of Bloodwatcher Point sits nearby. Oddly, the minimap shows the dirt around it as a rather different color than it is, likely due to a texturing change.\n\nDwarven artifacts can be retrieved from this archaeology dig site.",
			source = "https://warcraft.wiki.gg/wiki/Tomb_of_the_Watchers",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Uldaman is a huge and ancient, massive vault created by the titan keepers, buried deep within mountains of Khaz Modan. It is located in the Badlands, west of what was once the entrance to Loch Modan.",
			full = "Uldaman is a huge and ancient, massive vault created by the titan keepers, buried deep within mountains of Khaz Modan. It is located in the Badlands, west of what was once the entrance to Loch Modan. Prior to the Third War, it was partially excavated by the dwarves from Ironforge, but has since fallen into the hands of the troggs and Dark Irons, who find the place ideal to dig for earthly riches. It was previously a titan-forged facility.\n\nUldaman contains many artifacts for those willing to seek them out, primarily archaeologists and adventurers, who are slowly digging up this ruin of a titan-forged city. There are members of the Explorers' League, but also of the Reliquary, equally eager to get their hands on ancient treasures.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["uldaman legacy of tyr"] = {
			name = "Uldaman: Legacy of Tyr",
			short = "It is a separate instance from the original Uldaman dungeon and initially sees players passing through updated versions of familiar parts of the complex, before diverging into a newly-uncovered section leading to the Discs of Tyr.",
			full = "It is a separate instance from the original Uldaman dungeon and initially sees players passing through updated versions of familiar parts of the complex, before diverging into a newly-uncovered section leading to the Discs of Tyr.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman%3A_Legacy_of_Tyr",
		},
		["valley of fangs"] = {
			name = "Valley of Fangs",
			short = "The Valley of Fangs is a small valley between two massive stone formations located in the central Badlands.",
			full = "The Valley of Fangs is a small valley between two massive stone formations located in the central Badlands. It is the location of one of the many small quest camps in the region, this one containing Martek the Exiled, Rigglefuzz, and Jazzrik. Travel through the valley can be hazardous as it is home to both wolves and cougars.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Blasted Lands: 26 subzones
	[1419] = {
		["altar of storms blasted lands"] = {
			name = "Altar of Storms (Blasted Lands)",
			short = "An Altar of Storms can be found at the western edge of the Blasted Lands. Lady Sevine, now dead, was the one who built it here.",
			full = "An Altar of Storms can be found at the western edge of the Blasted Lands. Lady Sevine, now dead, was the one who built it here.\n\nDuring the Burning Legion's third invasion of Azeroth, the altar was taken by the Veiled Hand cultists led by Caden Shadowgaze.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Storms_(Blasted_Lands)",
		},
		["bloodwash cavern"] = {
			name = "Bloodwash Cavern",
			short = "Bloodwash Cavern is a large cavern located near the shores of the Red Reaches in Blasted Lands. It's here the Bloodwash naga have setup up a fortress and send many of their enslaved murlocs.",
			full = "Bloodwash Cavern is a large cavern located near the shores of the Red Reaches in Blasted Lands. It's here the Bloodwash naga have setup up a fortress and send many of their enslaved murlocs. Ancient elf ruins can be found within.",
			source = "https://warcraft.wiki.gg/wiki/Bloodwash_Cavern",
		},
		["bloodwash fighting pits"] = {
			name = "Bloodwash Fighting Pits",
			short = "Bloodwash Fighting Pits is a small area on the Red Reaches in the Blasted Lands, where the Bloodwash naga force their enslaved murlocs to fight each other.",
			full = "Bloodwash Fighting Pits is a small area on the Red Reaches in the Blasted Lands, where the Bloodwash naga force their enslaved murlocs to fight each other.",
			source = "https://warcraft.wiki.gg/wiki/Bloodwash_Fighting_Pits",
		},
		["bloodwash shrine"] = {
			name = "Bloodwash Shrine",
			short = "Bloodwash Shrine is a small area on the Red Reaches in the Blasted Lands, where the Bloodwash naga built a shrine to Queen Azshara. This is the location where they sacrifice the Rockpool murlocs.",
			full = "Bloodwash Shrine is a small area on the Red Reaches in the Blasted Lands, where the Bloodwash naga built a shrine to Queen Azshara. This is the location where they sacrifice the Rockpool murlocs.",
			source = "https://warcraft.wiki.gg/wiki/Bloodwash_Shrine",
		},
		["dark portal"] = {
			name = "Dark Portal",
			short = "Before the destruction of Draenor, it was located in the eastern section of Tanaan Jungle.",
			full = "Before the destruction of Draenor, it was located in the eastern section of Tanaan Jungle.\n\nOriginally created in a joint effort between Gul'dan and Medivh, the Dark Portal served as the Old Horde's method of reaching Azeroth and beginning the First War, as a way to weaken it for the Burning Legion's eventual invasion. The portal appears to be functionally indestructible, as the Alliance under Khadgar were only able to destroy the structure, not the portal itself.\n\nSince making its debut in Warcraft II: Tides of Darkness, the Dark Portal remains one of the Warcraft universe's most recognizable and iconic structures.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul furnace"] = {
			name = "Dreadmaul Furnace",
			short = "The Dreadmaul Furnace lies northwest of the Dreadmaul Post in the Blasted Lands. The siblings Lynnore and Drazial have reached an agreement with the ogres, allowing them to set up a base in a part of the ogre mound.",
			full = "The Dreadmaul Furnace lies northwest of the Dreadmaul Post in the Blasted Lands. The siblings Lynnore and Drazial have reached an agreement with the ogres, allowing them to set up a base in a part of the ogre mound.\n\nIt is unknown whether the agreement continued after the arrival of the Iron Horde, since their chamber is now occupied by a Dreadmaul Flamebelcher and the two elves are no-where to be seen.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Furnace",
		},
		["dreadmaul post"] = {
			name = "Dreadmaul Post",
			short = "Dreadmaul Post is an ogre mound of the Dreadmaul ogre Clan in the Blasted Lands. Dreadmaul Ogres remained close to the Dark Portal after coming to Azeroth from Draenor.",
			full = "Dreadmaul Post is an ogre mound of the Dreadmaul ogre Clan in the Blasted Lands. Dreadmaul Ogres remained close to the Dark Portal after coming to Azeroth from Draenor. They continue to maintain a strong presence in the area. An occasional lost draenei can also be found wandering the nearby territory.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["forge grounds"] = {
			name = "Forge Grounds",
			short = "The Forge Grounds, once known as Nethergarde Supply Camps, is the area outside Nethergarde Mines in the Blasted Lands.",
			full = "The Forge Grounds, once known as Nethergarde Supply Camps, is the area outside Nethergarde Mines in the Blasted Lands. The Iron Horde have taken over this land and use it as an outpost to continue mining out the nearby mine.",
			source = "https://warcraft.wiki.gg/wiki/Forge_Grounds",
		},
		["garrison armory"] = {
			name = "Garrison Armory",
			short = "The Garrison Armory is a vital Alliance mining outpost near the Nethergarde Keep in the Blasted Lands. Here Alliance miners toil to gather precious resources and minerals for the Nethergarde Keep.",
			full = "The Garrison Armory is a vital Alliance mining outpost near the Nethergarde Keep in the Blasted Lands. Here Alliance miners toil to gather precious resources and minerals for the Nethergarde Keep. These resources are frequently shipped to Stormwind in exchange for the other vital resources Nethergarde Keep depends upon to survive.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["maldraz"] = {
			name = "Maldraz",
			short = "Maldraz is a great tree located in the Tainted Forest of the Blasted Lands. From underneath its trunk, he entered a druidic trance and began to bring life back to the area.",
			full = "Maldraz is a great tree located in the Tainted Forest of the Blasted Lands. From underneath its trunk, he entered a druidic trance and began to bring life back to the area.\n\nAt first, it was a success and the forest was restored, allowing the refugees to build Surwich. However, the residual demonic powers left on the land began to take their toll, and while Wormthorn's attention was drawn to fighting back the demonic taint, the nathrezim who had formerly resided there took the opportunity to infiltrate Madraz. Once inside, they corrupted Wormthorn's trance, making him lose his mind in the process, and used his body as a weapon to corrupt the tree and the forest.\n\nIn order to halt the corruption, a [Demoniac Vessel] was separately created by Cenarion Observer Shayana and Elijah Dawnflight to break Wormthorn's trance, and adventurers from both factions were sent to Maldraz, in order to kill the corrupted druid. The mission was a success.",
			source = "https://warcraft.wiki.gg/wiki/Maldraz",
		},
		["nethergarde keep"] = {
			name = "Nethergarde Keep",
			short = "Nethergarde Keep, also known as the Citadel of Nethergarde, was a Dalaranian fortress built to keep watch over the Dark Portal after the Second War.",
			full = "Nethergarde Keep, also known as the Citadel of Nethergarde, was a Dalaranian fortress built to keep watch over the Dark Portal after the Second War. It stood on a high bluff along the only road into the Blasted Lands, a road often traveled by both the Alliance and the Horde as they prepared to do battle with the demonic forces in the region.\n\nNethergarde Keep was a heavily defended Alliance town, and although technically it was a castle-like Northwatch Hold in the Barrens, none of the guards were PvP-enabled except the Gryphon Master and a few quest givers. Its defenses were no match for the armies of the Iron Horde.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["nethergarde mines"] = {
			name = "Nethergarde Mines",
			short = "The Nethergarde Mines is an iron mine located in northern Blasted Lands. The mine is controlled by the Alliance from Nethergarde Keep.",
			full = "The Nethergarde Mines is an iron mine located in northern Blasted Lands. The mine is controlled by the Alliance from Nethergarde Keep. The Horde have recently begun attacking the mines to slow down supplying the keep.\n\nThe main entrance area is filled with dead Nethergarde defenders, beyond that Nethergarde miners can be found in mostly all the other sections. Some miners have accidentally released a demon, Illycor, that for some reason was buried deep within the mine. Chief Prospector Hondo leads the miners from his office in the upper chamber.\n\nA couple of Horde infiltrators can be found hiding along the cart tracks awaiting operatives to help them in their mission.\n\nWhen the Iron Horde began their invasion in Blasted Lands, they also took control of the mines and murdered its miners, whose bones where piled up in the lowest section. Unexpectedly, the miners came back as ghosts to haunt the lowest levels.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Mines",
		},
		["nethergarde supply camps"] = {
			name = "Nethergarde Supply Camps",
			short = "The Nethergarde Supply Camps is an area just outside the Nethergarde Mines in the Blasted Lands. The Alliance and Horde soldiers are currently fighting each other here.",
			full = "The Nethergarde Supply Camps is an area just outside the Nethergarde Mines in the Blasted Lands. The Alliance and Horde soldiers are currently fighting each other here.\n\nCaptain Metlek leads the Okril'lon Infantry in the attack.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Supply_Camps",
		},
		["okrillon hold"] = {
			name = "Okril'lon Hold",
			short = "Okril'lon Hold, previously called Dreadmaul Hold, was a Horde fortress in the northwest corner of the Blasted Lands.",
			full = "Okril'lon Hold, previously called Dreadmaul Hold, was a Horde fortress in the northwest corner of the Blasted Lands. It was originally an orc settlement known as Rockard, but was later taken over by the Dreadmaul ogres, who renamed it. It contains a barracks and a blacksmith.\n\nDuring the Ironmarch invasion the hold was captured by the Iron Horde and served as their headquarters for the invasion. The Horde and the Alliance eventually killed its leader.",
			source = "https://warcraft.wiki.gg/wiki/Okril'lon_Hold",
		},
		["red reaches"] = {
			name = "Red Reaches",
			short = "The Red Reaches is a large beach shore along the southeastern most part of the Blasted Lands.",
			full = "The Red Reaches is a large beach shore along the southeastern most part of the Blasted Lands. It was here that the Rockpool murlocs and the Bloodwash naga lived among each other in relative peace, as the even worshiped the same god, Neptulon, until the naga turned on them and started enslaving, sacrificing, and even force them to fight each other.",
			source = "https://warcraft.wiki.gg/wiki/Red_Reaches",
		},
		["rise of the defiler"] = {
			name = "Rise of the Defiler",
			short = "The Rise of the Defiler is a craggy set of mountains placed near the middle of the Blasted Lands. They are the home to the great demon, Razelikh.",
			full = "The Rise of the Defiler is a craggy set of mountains placed near the middle of the Blasted Lands. They are the home to the great demon, Razelikh.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["rockpool village"] = {
			name = "Rockpool Village",
			short = "Rockpool Village is the village of the Rockpool murlocs located on the eastern shores of the Red Reaches in the Blasted Lands. That is until the Bloodwash naga turned on them, taking their village, and enslaving them.",
			full = "Rockpool Village is the village of the Rockpool murlocs located on the eastern shores of the Red Reaches in the Blasted Lands. That is until the Bloodwash naga turned on them, taking their village, and enslaving them.",
			source = "https://warcraft.wiki.gg/wiki/Rockpool_Village",
		},
		["serpents coil"] = {
			name = "Serpent's Coil",
			short = "Serpent's Coil is a winding cave system, located in eastern Blasted Lands, that had been occupied by evil cultists worshipping Kirith the Damned.",
			full = "Serpent's Coil is a winding cave system, located in eastern Blasted Lands, that had been occupied by evil cultists worshipping Kirith the Damned. Several burnt-out orcish structures stand here, remnants from the Second War.\n\nArchmage Allistarj operated his Shadowsworn forces from within this small labyrinth, that is until he was killed, now the Shadowsworn forces continue on with someone else leading them. Near the entrance is a chest with the [Amulet of Allistarj] inside.\n\nDeep within the cavern is a gnome named Kasim Sharim, and although he's an Alliance member he has set up a small camp within the cave with a Horde banner.\n\nWhen the Iron Horde began their invasion, they took control of the cave.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["shattered beachhead"] = {
			name = "Shattered Beachhead",
			short = "Shattered Beachhead is a small Alliance outpost found north of the Shattershore battlefield. It was established in response to the Iron Horde Incursion in the Blasted Lands.",
			full = "Shattered Beachhead is a small Alliance outpost found north of the Shattershore battlefield. It was established in response to the Iron Horde Incursion in the Blasted Lands.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Beachhead",
		},
		["shattered front"] = {
			name = "Shattered Front",
			short = "The Shattered Front is an area just beyond the Shattershore in the Blasted Lands. It's controlled by the Iron Horde.",
			full = "The Shattered Front is an area just beyond the Shattershore in the Blasted Lands. It's controlled by the Iron Horde.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Front",
		},
		["shattered landing"] = {
			name = "Shattered Landing",
			short = "Shattered Landing was established in response to the Iron Horde attack on Okril'lon Hold.",
			full = "Shattered Landing was established in response to the Iron Horde attack on Okril'lon Hold.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Landing",
		},
		["shattershore"] = {
			name = "Shattershore",
			short = "Shattershore is a part of the eastern coastline of the Blasted Lands. Gilnean ship wrecks litter the shore and ghosts of Gilnean worgen inhabit the area.",
			full = "Shattershore is a part of the eastern coastline of the Blasted Lands. Gilnean ship wrecks litter the shore and ghosts of Gilnean worgen inhabit the area.\n\nIn one of the shipwreck's cargo holds is the head of Grol which still has the [Amulet of Grol] on it. It's unknown how it ended up here, or what caused the Gilneans to crash their ships and be killed off, but the Spirit of Grol may have something to do with it.\n\nWhen the Iron Horde came through the Dark Portal and invaded the Blasted Lands, the Alliance and Horde launched a joint offensive to drive them back through the portal. Shattershore became the scene of a fierce battle as the Alliance and Horde forces established a beachhead and gradually forced back the Iron Horde.",
			source = "https://warcraft.wiki.gg/wiki/Shattershore",
		},
		["sunveil excursion"] = {
			name = "Sunveil Excursion",
			short = "The Sunveil Excursion is a blood elf encampment located to the southwest of the Blasted Lands.",
			full = "The Sunveil Excursion is a blood elf encampment located to the southwest of the Blasted Lands. Interested in the demonic artifacts once hidden in the Tainted Scar, the leader of the excursion, Rohan Sunveil, ordered the creation of the camp and led his subordinates to practice an archaeological study in the Tainted Forest, where they focused their work in the acquisition, cataloging, and preservation of any and all magical artifacts.\n\nHowever, because of a corrupted Gilnean druid of substantial power named Marl Wormthorn, the unnatural forest threatened the Reliquary excursion's progress, as its trees' roots broke their picks, its moss grew over their excavation sites, and its animals attacked their men. In order to halt the corruption, and to finally be able to continue their archaeological study, Rohan Sunveil asked Horde adventurers, sent by Warlord Dar'toon on his request, to reduce the number of demons, and to kill the corrupted druid.\n\nYears later, when the Ironmarch entered Azeroth through the Dark Portal, the camp seems to have been deserted by its occupants.",
			source = "https://warcraft.wiki.gg/wiki/Sunveil_Excursion",
		},
		["surwich"] = {
			name = "Surwich",
			short = "Surwich is a Gilnean fishing village and port located to the southwest of the Blasted Lands.",
			full = "Surwich is a Gilnean fishing village and port located to the southwest of the Blasted Lands.",
			source = "https://warcraft.wiki.gg/wiki/Surwich",
		},
		["tainted forest"] = {
			name = "Tainted Forest",
			short = "The Tainted Forest is an expanse of the revitalized area in the Tainted Scar, created thanks to the efforts of a worgen druid named Marl Wormthorn.",
			full = "The Tainted Forest is an expanse of the revitalized area in the Tainted Scar, created thanks to the efforts of a worgen druid named Marl Wormthorn.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Forest",
		},
		["tainted scar"] = {
			name = "Tainted Scar",
			short = "The Tainted Scar is a small region in the western Blasted Lands, corrupted for years by the energies of the Dark Portal.",
			full = "The Tainted Scar is a small region in the western Blasted Lands, corrupted for years by the energies of the Dark Portal.\n\nOnce a part of the Black Morass, the area became a completely waterless and treeless wasteland, caused by the corrupting energies of the Dark Portal, which transformed the region into barren soil the color of blood, teeming with strange and demonic beasts.\n\nFollowing the Battle of Mount Hyjal in 21 ADP, the colossal ered'ruin Lord Kazzak led many of the remaining Burning Legion forces on Azeroth in the Tainted Scar. He subsequently ordered his most fearsome lieutenant Razelikh the Defiler to secure the land.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Tirisfal Glades: 45 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Agamand Family Crypt",
			short = "The Agamand Family Crypt is located just north of Agamand Mills in northern Tirisfal Glades.",
			full = "The Agamand Family Crypt is located just north of Agamand Mills in northern Tirisfal Glades. Captain Dargol, a minion of the Scourge, has settled here and awakened all the corpses and spirits of the Agamands' dead ancestors. It is a dark and dusty place, and the vengeful undead attack anyone who enter unbidden.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Agamand Mills",
			short = "The Agamand Mills is a vast windmill network in the highlands of northern Tirisfal Glades.",
			full = "The Agamand Mills is a vast windmill network in the highlands of northern Tirisfal Glades. Once owned by the wealthy Agamand family, the area was taken over by the undead and is now probably the largest Scourge outpost in Tirisfal. It can be accessed from the west by a road leading up from Calston Estate, and from the east by a road from Garren's Haunt.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Balnir Farmstead",
			short = "The Balnir Farmstead is a ruined farm in eastern Tirisfal Glades, northeast of the Ruins of Lordaeron.",
			full = "The Balnir Farmstead is a ruined farm in eastern Tirisfal Glades, northeast of the Ruins of Lordaeron. It was the home of the Balnir family, who bred the famous white horses of Lordaeron (most famously Arthas Menethil's Invincible and Anduin Wrynn's Reverence), but is now inhabited only by a few roaming Scourge. The farm's most notable feature is the grave of Invincible, left empty since Arthas resurrected the horse during the Third War.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Brightwater Lake",
			short = "Brightwater Lake is the biggest lake in Tirisfal Glades, located just northeast of Brill, south of the North Coast, and west of the Scarlet Watch Post.",
			full = "Brightwater Lake is the biggest lake in Tirisfal Glades, located just northeast of Brill, south of the North Coast, and west of the Scarlet Watch Post. Gunther's Retreat is situated on a large island in the center.\n\n2,600 BDP, Eidre and her family owned the land around a keep near the lake. The dreadlord Kathra'natir infected the area. The first Guardian of Tirisfal, Alodi, battled the demon on a small island here.\n\nBrightwater's entire western shore was scorched by the Lion's Wake during the Battle for Lordaeron, but the water itself and the islands on it were unaffected.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Brill",
			short = "Brill is a small town under the control of the Forsaken, in the Tirisfal Glades of northern Lordaeron.",
			full = "Brill is a small town under the control of the Forsaken, in the Tirisfal Glades of northern Lordaeron. Upon leaving Deathknell, new Forsaken adventurers will be directed to Brill where they will continue the Forsaken's war against both the Scarlet Crusade and the ever-present Scourge. It is located in the center of Tirisfal, directly north of the Ruins of Capital City.\n\nAfter the Battle for Lordaeron, not much was left of the town but rubble and ruins. Sometime after the war against the Jailer, the Forsaken regained control of the town and began its reconstruction.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Brill Town Hall",
			short = "The Brill Town Hall was the most prominent structure in the town of Brill in central Tirisfal Glades. Magistrate Sevren led the town from his podium, issuing orders and tasks to willing Forsaken subjects.",
			full = "The Brill Town Hall was the most prominent structure in the town of Brill in central Tirisfal Glades. Magistrate Sevren led the town from his podium, issuing orders and tasks to willing Forsaken subjects. The town hall was also notable because it was the only town hall in the realms known to be run by the Forsaken besides the Defiler's Den.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark is the Forsaken's last bastion of defense against the forces of the Scourge to the east, located on the border of Tirisfal Glades and the Western Plaguelands.",
			full = "The Bulwark is the Forsaken's last bastion of defense against the forces of the Scourge to the east, located on the border of Tirisfal Glades and the Western Plaguelands. The Argent Dawn and Forsaken defenders at the Bulwark have teamed up to protect the land from the hordes of undead to the east, and send experienced adventurers of the Horde to battle the minions of the Lich King.\n\nUnlike the rest of Tirisfal Glades, this area was filled with plaguemist until recently, the sky tinted the same yellowish-gray color as in the Western Plaguelands. However, with the reclamation efforts underway in the Plaguelands, this effect has subsided and the area looks like the rest of Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["calston estate"] = {
			name = "Calston Estate",
			short = "Calston Estate is a new Horde quest hub in Tirisfal Glades, complete with Forsaken-themed architecture, located west of Stillwater Pond.",
			full = "Calston Estate is a new Horde quest hub in Tirisfal Glades, complete with Forsaken-themed architecture, located west of Stillwater Pond. It contains profession and class trainers so players will not need to run back and forth between here and Brill. The estate is owned by the lonely Sedrick Calston.\n\nFrom here the Forsaken launch attacks on the Solliden Farmstead, perform experiments along the Tirisfal coast, etc.\n\nSome Scarlet Crusade propaganda pamphlets were distributed near the estate, accusing Anduin of conspiring with his secret lover Sylvanas at the Gathering of the Arathi Highlands in order to kill Calia Menethil and make secure his claims to the kingdom, and further claiming to have Calia's surviving son as the last remaining heir to the Menethil dynasty, with whom the Brotherhood intended to one day end Anduin's \"puppet reign\".",
			source = "https://warcraft.wiki.gg/wiki/Calston_Estate",
		},
		["cold hearth manor"] = {
			name = "Cold Hearth Manor",
			short = "Cold Hearth Manor is a farmstead in central Tirisfal Glades, formerly known for its warm atmosphere and bountiful crops.",
			full = "Cold Hearth Manor is a farmstead in central Tirisfal Glades, formerly known for its warm atmosphere and bountiful crops. After the Plague of Undeath claimed the lives of everyone who lived or worked here, the fields have grown barren and become infested with mindless Scourge zombies.\n\nThe Forsaken managed to claim the farmhouse for themselves. They now offer trade opportunities to travelers passing on the main road nearby.\n\nAfter the Forsaken reclaimed Brill, Tirisfal Farmers took control of the manor, and Scarlet Warriors patroled the road in front of it.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Crusader Outpost",
			short = "Crusader Outpost is a scout tower located in eastern Tirisfal Glades.",
			full = "Crusader Outpost is a scout tower located in eastern Tirisfal Glades. It is under the control of the Scarlet Crusade, who use it to keep an eye on the main road through the glades south of the hills the tower has been built on, and also to provide for flanking opportunities against enemies who try to assault the Scarlet Monastery. This particular tower is commanded by Captain Vachon. There's evidence of an attack here from Lilian Voss.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["crusaders outpost"] = {
			name = "Crusader's Outpost",
			short = "This Crusader's Outpost is a scout tower located within the Scarlet Palisade of western Tirisfal Glades.",
			full = "This Crusader's Outpost is a scout tower located within the Scarlet Palisade of western Tirisfal Glades. It is under the control of the Scarlet Crusade, who have allied with the farmers of Solliden Farmstead in order to fight back the Scourge and Forsaken who have settlements nearby. This tower is the westernmost holding of the Scarlet Crusade in all of Lordaeron, which also means they are so far from their main base of Tyr's Hand that should any trouble befall them, they will not have enough time to wait for reinforcements. It is one of the four Crusader's Outpost towers in Tirisfal Glades.\n\nIt's here the Scarlet Crusade brought Lilian Voss as a prisoner, awaiting word back from her father for her fate.",
			source = "https://warcraft.wiki.gg/wiki/Crusader's_Outpost",
		},
		["darkwalk"] = {
			name = "Darkwalk",
			short = "The Darkwalk is an underground and partially collapsed passage found within the Tomb of Tyr that leads from the proper tomb chamber to the Grave-Prison of Zakajz.",
			full = "The Darkwalk is an underground and partially collapsed passage found within the Tomb of Tyr that leads from the proper tomb chamber to the Grave-Prison of Zakajz.\n\nDuring the third invasion of the Burning Legion, the tomb was breached by the Argent Crusade with Tyr's Guard, priests of the Conclave, and Valarjar warriors sent by Odyn, they passed through the Darkwalk, defeating the Twilight's Hammer and Old Gods' forces.\n\nYears later, Travard entered the Tomb again, this time with Watcher Koranos. When they escaped to the Darkwalk, they found a Damaged Titan Matrix, guarded by two Silver Golems, and a Titan Transporter.",
			source = "https://warcraft.wiki.gg/wiki/Darkwalk",
		},
		["deathknell"] = {
			name = "Deathknell",
			short = "Deathknell is a small Forsaken village nestled in a well-guarded valley just north of Silverpine Forest in Tirisfal Glades which serves as the starting area for the Forsaken.",
			full = "Deathknell is a small Forsaken village nestled in a well-guarded valley just north of Silverpine Forest in Tirisfal Glades which serves as the starting area for the Forsaken. One of the greatest struggles for the citizens of Deathknell is obtaining the natural resources they need to survive, particularly gold. The gold mine to the northwest has been overrun by spiders, and the people of Deathknell frequently attempt to clear it out, so that they may begin mining its precious metals. In the meantime, they do what they must to survive in the face of the Scourge and the Scarlet Crusade.\n\nLore-wise, Deathknell is unique among Forsaken sites due to its name. While other communities inhabited by the rebel undead of the Banshee Queen retained their names from their days as centers of human civilization, Deathknell was obviously renamed to its current appellation for reasons unknown. The valley itself is guarded by a number of Deathguard Elites.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["deathknell graves"] = {
			name = "Deathknell Graves",
			short = "The Deathknell Graves is a mass grave outside the Shadow Grave in Deathknell. All undead player characters start here, waiting to be \"resurrected\" by their first quest, given by the val'kyr Agatha.",
			full = "The Deathknell Graves is a mass grave outside the Shadow Grave in Deathknell. All undead player characters start here, waiting to be \"resurrected\" by their first quest, given by the val'kyr Agatha. A grave marker next to the player reads, \"Corpse of <player name>\".\n\nIn addition to Agatha, two other val'kyr, Arthura and Aradne, are present as well. Arthura will patrol the area while Aradne goes about attempting to resurrect the Risen Dead in a periodic scripted event with mixed results.\n\nUpon approaching a corpse, Aradne will say something such as, \"Rise from the grave and serve the Dark Lady!\" While the Risen Dead often either embrace their fate or at least resign themselves to it and seek assistance from Undertaker Mordo, they will sometimes react similarly to Lilian Voss and declare, \"I should be dead and to death I will return!\" They will then perform a death animation. They also occasionally say, \"I never asked for this! Leave me alone!\" after which they perform an enrage animation and become one of the Mindless Zombies who wander the area.\n\nOther recent arrivals from death include Darnell, an companion NPC similar to Zuni who follows the player. Additionally, Caretaker Caice sends players to introduce Voss, Marshal Redpath and Valdred Moray to their new lives.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell_Graves",
		},
		["deaths watch waystation"] = {
			name = "Death's Watch Waystation",
			short = "Death's Watch Waystation was a small camp just southeast of Brill in the Tirisfal Glades. It was a Deathguard waystation.",
			full = "Death's Watch Waystation was a small camp just southeast of Brill in the Tirisfal Glades. It was a Deathguard waystation.\n\nDuring the events of the Battle for Lordaeron, the waystation had been already destroyed and there was no trace of it.\n\nWhen the Forsaken reclaimed Brill, they used the area of the Waystation as a staging ground for the deployment of the Plague Eater against the remaining blight in Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Death's_Watch_Waystation",
		},
		["faols rest"] = {
			name = "Faol's Rest",
			short = "Faol's Rest is located in eastern Tirisfal Glades, just southwest of the Scarlet Monastery. It serves as the graveyard for those dying in Scarlet Monastery or low-level quests around that place.",
			full = "Faol's Rest is located in eastern Tirisfal Glades, just southwest of the Scarlet Monastery. It serves as the graveyard for those dying in Scarlet Monastery or low-level quests around that place.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Gallows' End Tavern",
			short = "Gallows' End Tavern is an inn located in Brill in the Tirisfal Glades. It features trainers for warriors, priests, mages, rogues, warlocks, enchanters, and first aid, in addition to the innkeeper and a few other vendors.",
			full = "Gallows' End Tavern is an inn located in Brill in the Tirisfal Glades. It features trainers for warriors, priests, mages, rogues, warlocks, enchanters, and first aid, in addition to the innkeeper and a few other vendors.\n\nA captured Scarlet Zealot and Dwarven Mountaineer are held in the cellars.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Garren's Haunt",
			short = "Garren's Haunt is a large farmstead in the northern part of the Tirisfal Glades. It includes a farmhouse, a barn, a couple of silos, and a wide-stretched field.",
			full = "Garren's Haunt is a large farmstead in the northern part of the Tirisfal Glades. It includes a farmhouse, a barn, a couple of silos, and a wide-stretched field.\n\nThe darkhound Plague can be found in the barn.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["grand vestibule"] = {
			name = "Grand Vestibule",
			short = "The Grand Vestibule is the outermost chamber of the Scarlet Monastery. It holds the entrances to both the Scarlet Halls and Scarlet Monastery instances.",
			full = "The Grand Vestibule is the outermost chamber of the Scarlet Monastery. It holds the entrances to both the Scarlet Halls and Scarlet Monastery instances.\n\nThe vestibule itself is decorated with pillars and statues of scarlet warriors. It is often a contested place, as Horde and Alliance-affiliated adventurers mingle in the hall; with sometimes brutal results.",
			source = "https://warcraft.wiki.gg/wiki/Grand_Vestibule",
		},
		["grave prison of zakajz"] = {
			name = "Grave-Prison of Zakajz",
			short = "The Grave-Prison of Zakajz is a partially collapsed cavern where the C'Thrax known as Zakajz the Corruptor was imprisoned after his defeat against the titan keeper Tyr thousands of years ago.",
			full = "The Grave-Prison of Zakajz is a partially collapsed cavern where the C'Thrax known as Zakajz the Corruptor was imprisoned after his defeat against the titan keeper Tyr thousands of years ago. The cavern is housed under the Tomb of Tyr, connected by the Darkwalk.\n\nDuring the third invasion of the Burning Legion, a chosen warrior of Odyn was tasked to defeat Zakajz and obtain [Strom'kar, the Warbreaker] from his head. In the process, the chosen met the soul of Thoradin, who guided them to Zakajz and was able to leave this place and be at peace after the battle. The Conclave priests entered the tomb and the grave-prison where they fought Twilight Deacon Farthing who had [Xal'atath, Blade of the Black Empire]. In the end, the blade turned on Farthing and allowed itself to be claimed by the High Lord, followed by destroying the corpse of Zakajz. When Travard of the Tyr's Guard and the Highlord of the Order of the Silver Hand recovered a Spark of Tyr from the grave-prison, they retreated back to the Tomb of Tyr, chased by Mordoth the Hunter, where they freed [The Silver Hand], the prison collapsed with the tomb that lost its power source.",
			source = "https://warcraft.wiki.gg/wiki/Grave-Prison_of_Zakajz",
		},
		["gunthers retreat"] = {
			name = "Gunther's Retreat",
			short = "Gunther's Retreat is an island located in Brightwater Lake in central Tirisfal Glades. It is home to the Forsaken lich Gunther Arcanus and his zombie minions.",
			full = "Gunther's Retreat is an island located in Brightwater Lake in central Tirisfal Glades. It is home to the Forsaken lich Gunther Arcanus and his zombie minions. On the southwestern side of the retreat is a small, unnamed islet holding Lillith's Dinner Table.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Night Web's Hollow",
			short = "Night Web's Hollow is a small valley and gold mine just northwest of Deathknell in Tirisfal Glades.",
			full = "Night Web's Hollow is a small valley and gold mine just northwest of Deathknell in Tirisfal Glades. Both the outdoors vale and the indoors mine are infested with spiders, which skitter among the shadows and lurk from their webbed corners. Young Forsaken usually test their mettle against the numerous spiders and sometimes venture deep into the mine to uncover its dusty secrets.\n\nOutside the mine, Young Night Web Spiders wander about. The mine itself houses many adult Night Web Spiders. In the deepest recesses of the mine, the Night Web Matriarch sits.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Nightmare Vale",
			short = "Nightmare Vale is a wide valley located just west of the Scarlet Watchtower in southwestern Tirisfal Glades.",
			full = "Nightmare Vale is a wide valley located just west of the Scarlet Watchtower in southwestern Tirisfal Glades. While the glades here were once verdant and teeming with forest animals, now the trees have withered and the wildlife has been eaten by hungry darkhounds and huge vampire bats. Ressan the Needler, a rare white bat, also appears here.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "North Coast",
			short = "The North Coast is a stretch of beach bordering a portion of the Great Sea. It lies along the northern edge of the Tirisfal Glades, and is mostly inhabited by ravenous murlocs and various marine animals.",
			full = "The North Coast is a stretch of beach bordering a portion of the Great Sea. It lies along the northern edge of the Tirisfal Glades, and is mostly inhabited by ravenous murlocs and various marine animals. Since the Plague of Undeath marred the region with its taint, the coast has become dark and cold, the site of several dead sea creatures rotting at the edge of the water.\n\nThe murloc Deeb can be found standing idle here.\n\nIn the Battle for Lordaeron, the coast became the landing site for the Alliance, destroying much of it -- including the murloc huts. The trail of destruction ranging from the Alliance's landfall to the ruins of Brill is called the Lion's Wake.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["rotbrain encampment"] = {
			name = "Rotbrain Encampment",
			short = "The Rotbrain Encampment is an area just outside Deathknell in the Forsaken starting zone inhabited by the Rotbrain Undead, those who have recently been resurrected but either are in denial, confused or wishing to exact vengeance.",
			full = "The Rotbrain Encampment is an area just outside Deathknell in the Forsaken starting zone inhabited by the Rotbrain Undead, those who have recently been resurrected but either are in denial, confused or wishing to exact vengeance. Led by Marcus Redpath, they are plotting an assault on the Forsaken.\n\nThe area is infested with Rotbrain Magi and Rotbrain Berserkers, locked in combat with Deathguard Protectors. Darnell will send players to deal with these recalcitrant undead and is promoted to a Deathguard for his efforts, though he does not actually help players fight.\n\nThe camp was ultimately attacked by Forsaken adventurers, leading to the destruction of the group.",
			source = "https://warcraft.wiki.gg/wiki/Rotbrain_Encampment",
		},
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "The Ruins of Lordaeron (or Lordaeron Keep, also called Ruins of Capital City and Capital City Ruins, and sometimes referred to as Lordaeron City) is the remains of the city of Lordaeron, the great capital city of the fallen kingdom of Lordaeron.",
			full = "The Ruins of Lordaeron (or Lordaeron Keep, also called Ruins of Capital City and Capital City Ruins, and sometimes referred to as Lordaeron City) is the remains of the city of Lordaeron, the great capital city of the fallen kingdom of Lordaeron. It was destroyed by the Scourge after Arthas Menethil betrayed his people and set on the path to become the Lich King. The area is literally haunted by the final tragic events that led to the death of King Terenas and the city's destruction. Lordaeron's palace still stands, and once served as an entrance into the Forsaken capital of the Undercity.\n\nAfter the Battle for Lordaeron, the Forsaken lost control of the ruins, and the city was further devastated and completely blighted. With the help of adventurers, the Forsaken later applied techniques learned in Maldraxxus to purge the blight from the ruins. Afterward, the city became their new capital, watched over by the new Desolate Council. The city holds a translocation orb that links to Silvermoon City, and has also several portals that lead to Orgrimmar, Vengeance Landing, and Grom'gol Base Camp; in lieu of the still ruined zeppelin towers that once led to these locations.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet encampment"] = {
			name = "Scarlet Encampment",
			short = "The Scarlet Encampment is a small Scarlet Crusade camp located in the northern area of the Venomweb Vale in the Tirisfal Glades.",
			full = "The Scarlet Encampment is a small Scarlet Crusade camp located in the northern area of the Venomweb Vale in the Tirisfal Glades. This camp was under the command of Lieutenant Sanders, until Lilian Voss destroyed the camp and everyone within it.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Encampment",
		},
		["scarlet monastery"] = {
			name = "Scarlet Monastery",
			short = "The Scarlet Monastery, once known as the Old Monastery, is a fortified monastery located in the northeast corner of the blighted Tirisfal Glades, it was once a cathedral of the Church of the Holy Light, which was taken over by the Scarlet Crusade after the end of the Third War.",
			full = "The Scarlet Monastery, once known as the Old Monastery, is a fortified monastery located in the northeast corner of the blighted Tirisfal Glades, it was once a cathedral of the Church of the Holy Light, which was taken over by the Scarlet Crusade after the end of the Third War.\n\nAt the time of the third invasion of the Burning Legion, the remaining zealots of the Scarlet Crusade gathered at the monastery where they were massacred by the Knights of the Ebon Blade.\n\nThe Scarlet Monastery is a complex of two instanced dungeons, Scarlet Halls and Scarlet Monastery. Heroic mode is available for both wings at level 35.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet palisade"] = {
			name = "Scarlet Palisade",
			short = "The Scarlet Palisade is a Scarlet Crusade fortified camp located just west of the Solliden Farmstead in Tirisfal Glades.",
			full = "The Scarlet Palisade is a Scarlet Crusade fortified camp located just west of the Solliden Farmstead in Tirisfal Glades. It is from here the Scarlet Warriors protect the neighboring farm from any non-human that comes near. In the center of the camp is the Crusader's Outpost.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Palisade",
		},
		["scarlet watch post"] = {
			name = "Scarlet Watch Post",
			short = "The Scarlet Watch Post (or Crusader's Run) is a scout tower located in northeastern Tirisfal Glades, just north of the Scarlet Monastery.",
			full = "The Scarlet Watch Post (or Crusader's Run) is a scout tower located in northeastern Tirisfal Glades, just north of the Scarlet Monastery. Its maintenance despite its remote location is solely to prevent enemies of the Scarlet Crusade from assaulting the monastery from its less defensible north side. It's one of the four Crusader's Outpost towers in Tirisfal Glades. This particular tower is commanded by Captain Melrache.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["scarlet watchtower"] = {
			name = "Scarlet Watchtower",
			short = "The Scarlet Watchtower is a ruined scout tower located in southern Tirisfal Glades near the entrance to the Sewers of the Undercity.",
			full = "The Scarlet Watchtower is a ruined scout tower located in southern Tirisfal Glades near the entrance to the Sewers of the Undercity. It is under the control of the Scarlet Crusade, who use it to keep a watchful eye on flight routes coming to and from the Forsaken capital. It is one of four Crusader's Outpost towers in the Tirisfal Glades.\n\nThis particular tower is commanded by Captain Perrine.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watchtower",
		},
		["sewers"] = {
			name = "Sewers",
			short = "The Sewers (or the bat sewer entrances) are a side entrance to the Undercity, accessible from west of the main gate to the Ruins of Lordaeron, near the Scarlet Watchtower in Tirisfal Glades.",
			full = "The Sewers (or the bat sewer entrances) are a side entrance to the Undercity, accessible from west of the main gate to the Ruins of Lordaeron, near the Scarlet Watchtower in Tirisfal Glades. This is used as the quickest way in and out for flight paths, as the only other way into the city is by using elevators from the ruins.\n\nThe sewers were used by the Alliance to enter the city during the Battle for the Undercity.\n\nYears later, the sewers were used by the Ebon Blade to enter the city during a mission to rescue Koltira Deathweaver.",
			source = "https://warcraft.wiki.gg/wiki/Sewers",
		},
		["shadow grave"] = {
			name = "Shadow Grave",
			short = "Shadow Grave is a crypt that lies at the top of a slope, within the Deathknell Graves, along the Tirisfal Glades mountains. A path runs down from Shadow Grave to Deathknell.",
			full = "Shadow Grave is a crypt that lies at the top of a slope, within the Deathknell Graves, along the Tirisfal Glades mountains. A path runs down from Shadow Grave to Deathknell.\n\nPlayers now awake in the nearby Deathknell Graves.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Solliden Farmstead",
			short = "The Solliden Farmstead is a human pumpkin farm in western Tirisfal Glades, just north of Deathknell and west of Calston Estate.",
			full = "The Solliden Farmstead is a human pumpkin farm in western Tirisfal Glades, just north of Deathknell and west of Calston Estate. One of the only places in northern Lordaeron where the native farmers have survived unaffected by the Plague of Undeath, its denizens are protected from the Forsaken and Scourge by the Scarlet Crusade at the nearby Scarlet Palisade. The farmers are hostile to both the Horde and the Alliance.\n\nArathorian settlers began establishing farmsteads in Tirisfal during Arathor's expansion circa 2,700 BDP. Circa 1,200 BDP, immigrant noble families from Strom bought up large plots of land developed by earlier settlers in Tirisfal, including the Solliden Farmstead.\n\nIn the current day, the Royal Apothecary Society sends adventurers to steal some of the farmstead's pumpkins for use in experiments with the New Plague. Deathguard Simmer sends adventurers to kill the humans themselves, out of a concern that the currently-peaceful farmers might be recruited by the Alliance in Gilneas or Stormwind and used against the Forsaken in the future.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Stillwater Pond",
			short = "Stillwater Pond is a small lake located west of Brill in Tirisfal Glades.",
			full = "Stillwater Pond is a small lake located west of Brill in Tirisfal Glades. Before the Plague of Undeath, it was a popular site for picnics by the inhabitants of the glades, and the pond offered swimming opportunities for children who were not yet old enough to test their mettle in the much larger and deeper Brightwater Lake.\n\nNow the pond lies gray and forgotten, and only wandering undead and wild beasts set their eyes on its cold waters as they pass by. Only the still living skeletons of the lake's fish remain beneath the surface. The powerful darkhound Bayne roams around the pond, feasting on the unwary.\n\nA few new types of plant have begun to grow at Stillwater, with Marrowpetals growing at the bottom of the pond, and Stillwater Lilies growing around the edges. Furthermore, it has become infested with Giant Flesh-Eating Tadpoles thanks to irresponsible chemical disposal, courtesy of the Royal Apothecary Society.\n\nBy the time the Forsaken started rebuilding Brill, Scarlet Warriors were patroling around Stillwater Pond.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terrace of Repose",
			short = "The Terrace of Repose is located on the grounds just north of the Scarlet Monastery entrance.",
			full = "The Terrace of Repose is located on the grounds just north of the Scarlet Monastery entrance. It is one of the very few places in northern Lordaeron where the Plague of Undeath has not reached, and the Scarlet Crusade have been able to grow green hedges and maintain a fountain with water that is fresh rather than stagnant like the rest of Tirisfal Glades.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["tomb of tyr"] = {
			name = "Tomb of Tyr",
			short = "The Tomb of Tyr (or Keeper's Rest) is an underground area located under the lake of Tyr's Fall in the Whispering Forest in western Tirisfal Glades.",
			full = "The Tomb of Tyr (or Keeper's Rest) is an underground area located under the lake of Tyr's Fall in the Whispering Forest in western Tirisfal Glades. It is accessible from a narrow entrance at the bottom of the lake. The area is comprised of the Vestibule of the Silver Hand, Tyr's tomb proper, the Darkwalk, and the Grave-Prison of Zakajz.",
			source = "https://warcraft.wiki.gg/wiki/Tomb_of_Tyr",
		},
		["tyrs fall"] = {
			name = "Tyr's Fall",
			short = "Tyr's Fall (or Tirisfal in the vrykul tongue) is a craterous lake found within the Whispering Forest in western Tirisfal Glades, for which it is the namesake.",
			full = "Tyr's Fall (or Tirisfal in the vrykul tongue) is a craterous lake found within the Whispering Forest in western Tirisfal Glades, for which it is the namesake. As the name suggests, it was the place where the titan keeper Tyr made his final stand against the C'Thrax generals Zakajz and Kith'ix. Under the lake lies a tomb, the final resting place of Tyr, which collapsed.\n\nThe tomb and the surrounding area have been guarded by a secretive group of paladins known as the Tyr's Guard for thousands of years.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Fall",
		},
		["undercity"] = {
			name = "Undercity",
			short = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades.",
			full = "The Undercity, now known as the Ruins of Undercity, was the capital city of the Forsaken kingdom, located beneath the ruins of Capital City in Tirisfal Glades. Originally intended by Arthas Menethil to be the Scourge's seat of power in Lordaeron, the budding \"Undercity\" was abandoned when the death knight was recalled by the Lich King in the distant Northrend. During the Plaguelands civil war, Sylvanas Windrunner and the Forsaken rebels claimed the Undercity for their own, then spent years completing the twisted maze of catacombs the Scourge had begun constructing. It was much more defensible than the city above it.\n\nPlagued by the Banshee Queen during the Battle for Lordaeron, its surface has since been cleansed by the efforts of the Desolate Council.",
			source = "https://warcraft.wiki.gg/wiki/Undercity",
		},
		["underwater passage"] = {
			name = "Underwater Passage",
			short = "The Underwater Passage is a sub-aquatic tunnel in western Tirisfal Glades that leads from the lake of Tyr's Fall in the Whispering Forest to the Tomb of Tyr beneath the lake's floor.",
			full = "The Underwater Passage is a sub-aquatic tunnel in western Tirisfal Glades that leads from the lake of Tyr's Fall in the Whispering Forest to the Tomb of Tyr beneath the lake's floor.",
			source = "https://warcraft.wiki.gg/wiki/Underwater_Passage",
		},
		["venomweb vale"] = {
			name = "Venomweb Vale",
			short = "Venomweb Vale is a wide valley located in eastern Tirisfal Glades, just south of the Scarlet Monastery.",
			full = "Venomweb Vale is a wide valley located in eastern Tirisfal Glades, just south of the Scarlet Monastery. While the vale used to be a haven for hunting deer and rabbits, its trees verdant and the grass green, it is now a tainted place full of poisonous and deadly spiders led by Sri'skulk which give the vale its new name.\n\nIn the northern part of the valley, darkhounds roam near the Scarlet Encampment, a Scarlet Crusade camp under the command of Lieutenant Sanders.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["vestibule of the silver hand"] = {
			name = "Vestibule of the Silver Hand",
			short = "The Vestibule of the Silver Hand is the proper entrance to the Tomb of Tyr found after swimming through the Underwater Passage.",
			full = "The Vestibule of the Silver Hand is the proper entrance to the Tomb of Tyr found after swimming through the Underwater Passage.\n\nThey found Travard in the vestibule, frustrated at being locked out by the tomb's defense systems. The old paladin decided to aid them as they entered the Tomb of Tyr, hoping that they contained enough memories to activate the [Silver Scale] in order to revive Tyr's new body.",
			source = "https://warcraft.wiki.gg/wiki/Vestibule_of_the_Silver_Hand",
		},
		["whispering forest"] = {
			name = "Whispering Forest",
			short = "The Whispering Forest is a large forest located within the mountains of western Tirisfal Glades, just west of Deathknell and south of Tyr's Fall.",
			full = "The Whispering Forest is a large forest located within the mountains of western Tirisfal Glades, just west of Deathknell and south of Tyr's Fall. It is accessible via flight or by druids with Glyph of One With Nature. The forest contains families of diseased stags, does and fawns, rats and one diseased bear.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Forest",
		},
		["whispering gardens"] = {
			name = "Whispering Gardens",
			short = "The Whispering Gardens are located in northeastern Tirisfal Glades, on the hill south of Scarlet Monastery entrance. A great battle was fought here between, what would become, the Scarlet Crusade and a host of Scourge.",
			full = "The Whispering Gardens are located in northeastern Tirisfal Glades, on the hill south of Scarlet Monastery entrance. A great battle was fought here between, what would become, the Scarlet Crusade and a host of Scourge. The spirits of those fallen in battle can still be heard here as faint whispers in the twilight.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Whispering Shore",
			short = "The Whispering Shore is a small stretch of coast located in western Tirisfal Glades, just north of the Solliden Farmstead.",
			full = "The Whispering Shore is a small stretch of coast located in western Tirisfal Glades, just north of the Solliden Farmstead. While this area used to be a popular spot for fishing, it is now the site of a band of murlocs ravenously attacking anyone who wanders near. The water off the coast is cold and dark, and nothing remains of its former bounty. The fierce murloc Muad is the leader of the invaders.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Silverpine Forest: 33 subzones
	[1421] = {
		["7th legion base camp"] = {
			name = "7th Legion Base Camp",
			short = "7th Legion Base Camp is a dwarven base of operations in Silverpine Forest, headed by General Marstone. Dwarven Infantry patrol the area.",
			full = "7th Legion Base Camp is a dwarven base of operations in Silverpine Forest, headed by General Marstone. Dwarven Infantry patrol the area.\n\nLord Godfrey will have Horde heroes come here to assassinate Marstone in the quest [5-30] Sowing Discord in order to slow the advance of the Alliance forces in the resultant confusion. Meanwhile Lord Walden wants some recon data in [5-30] 7th Legion Battle Plans. Heroes wandering into the area should be advised that the mobs are elites due to the presence of three friendly NPCs during the associated quests.",
			source = "https://warcraft.wiki.gg/wiki/7th_Legion_Base_Camp",
		},
		["ambermill"] = {
			name = "Ambermill",
			short = "Ambermill (or Amber Mill) was a human town located slightly southwest of Lordamere Lake in Silverpine Forest. It is made up of a town hall, a stables, several mills, and a lumber mill.",
			full = "Ambermill (or Amber Mill) was a human town located slightly southwest of Lordamere Lake in Silverpine Forest. It is made up of a town hall, a stables, several mills, and a lumber mill. It was originally part of kingdom of Gilneas. Following the Third War, the town was occupied by the forces of the Kirin Tor from the Magocracy of Dalaran, who were friendly with the Alliance. However, the town was eventually conquered by the Forsaken at the time of the invasion of Gilneas. Following the final battle of the Silverpine Forest campaign, the area is inhabited by servitors once more, though the shield is gone.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["battlefront"] = {
			name = "Battlefront",
			short = "The Battlefront is large region of Silverpine Forest between Shadowfang Keep and the Greymane Wall.",
			full = "The Battlefront is large region of Silverpine Forest between Shadowfang Keep and the Greymane Wall. It is currently inhabited by both Forsaken Horde forces, and the 7th Legion and Gilneas Liberation Front of the Alliance. Additionally, Marsh Crocolisks have eaten one of Lord Godfrey's friends here and will drop an item that begins a quest.\n\nThe main Horde camp is the Forsaken Front, where Sylvanas Windrunner leads the war preparations that culminate in a final showdown in [5-30] Cities in Dust. Alliance encampments include the 7th Legion Base Camp, where the dwarves under General Marstone are located, and the Gilneas Liberation Front Base Camp, where Lorna Crowley can be found. The once isolated Pyrewood Village has become ground zero for the conflict between these two sides.",
			source = "https://warcraft.wiki.gg/wiki/Battlefront",
		},
		["berens peril"] = {
			name = "Beren's Peril",
			short = "Beren's Peril is located in Silverpine Forest due southwest of Ambermill, between the main road and the side road coming from Ambermill in the hills.",
			full = "Beren's Peril is located in Silverpine Forest due southwest of Ambermill, between the main road and the side road coming from Ambermill in the hills. The path leading up to it starts at .",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Dawning Isles",
			short = "The Dawning Isles used to be an idyllic set of low keys that rose from the crystalline surface of Lordamere Lake, but had been affected by the Plague of Undeath.",
			full = "The Dawning Isles used to be an idyllic set of low keys that rose from the crystalline surface of Lordamere Lake, but had been affected by the Plague of Undeath. The trees grew sickly, and dangerous murlocs and bog beasts roamed the islets. The bog beasts have since vanished and the Vile Fin murlocs are grown to a very large population taking control of the isles.\n\nThe isles were taken over by the Scarlet Crusade. They mounted an attack on the Ruins of Lordaeron, and the Forsaken tried to counterattack.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Dead Field",
			short = "The Dead Field was the name of a decrepit and abandoned farm in northern Silverpine Forest. The nature and number of the farm's former inhabitants were unknown.",
			full = "The Dead Field was the name of a decrepit and abandoned farm in northern Silverpine Forest. The nature and number of the farm's former inhabitants were unknown. The Dead Field became a base for the Rot Hide gnolls, servants of the Scourge. It is unknown what the Scourge planned are for the farm, but the increasing number of gnolls suggested imminent military action.\n\nA reconnaissance mission undertaken by the Deathstalkers passed through the field on their mission through northern Silverpine, noting the presence of the Scourge at the farm. Repeated small assaults by the Forsaken upon the Dead Field have been unsuccessful because of the arrival of a banshee known as Nightlash. The banshee appears when the Rot Hides under her command are attacked.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Decrepit Ferry",
			short = "The Decrepit Ferry used to be the location of a bustling ferry service that transported goods and people to and from Fenris Isle.",
			full = "The Decrepit Ferry used to be the location of a bustling ferry service that transported goods and people to and from Fenris Isle. The nearby farmsteads all sold part of their crops to the island's rich lord and his family, and the ferryman was paid a small fee for each trip.\n\nThen the Scourge invaded Lordaeron. The ferryman was brutally murdered, the ferry was destroyed, and ghouls, skeletal warriors, and Rot Hide gnolls invaded the docks. It is now a hazardous place to venture for inexperienced travelers.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["decrepit fields"] = {
			name = "Decrepit Fields",
			short = "The Decrepit Fields, formerly the Decrepit Ferry, is an area in Silverpine Forest located between the Sepulcher and Fenris Isle, on the shore of Lordamere Lake.",
			full = "The Decrepit Fields, formerly the Decrepit Ferry, is an area in Silverpine Forest located between the Sepulcher and Fenris Isle, on the shore of Lordamere Lake. It has become home to a large number of Hillsbrad Worgen who chose to seek vengeance against the Forsaken rather than be raised into undeath. A number of ruined Forsaken catapults are located here.\n\nWarlord Torok made the mistake of sending his Orc Sea Dogs to fight the Hillsbrad forces without providing them with adequate alcohol. They now lie unconscious on the ground. He will send players to wake them up while Sylvanas has you deal with the worgen.\n\nAt the end of the fields along the shoreline exists a pier that once had a ferry filled with corpses. The pier now has a Horde Communication Panel and three Horde Cannons on it, along with Killian Sanatha whom apparently was of no interest to the waves of newly transformed worgen refugees, as he still stands on the pier fishing, unmolested. Fenwick Thatros, a rare spawn, can be found here as well.\n\nWhen the Scarlet Crusade took over Fenris Isle and attacked the Ruins of Lordaeron, the Decrepit Fields was empty of the orc and worgen forces, and instead it was inhabited by Giant Rabid Bears and Rabid Worgs. The dock was taken over by Scarlet Recruits, with Killian relocating to the Sepulcher.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Fields",
		},
		["deep elem mine"] = {
			name = "Deep Elem Mine",
			short = "The Deep Elem Mine is a mine in the middle of Silverpine Forest.",
			full = "The Deep Elem Mine is a mine in the middle of Silverpine Forest.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Fenris Isle",
			short = "Fenris Isle is a large island located in the center of Lordamere Lake and it is generally considered to be a part of Silverpine Forest.",
			full = "Fenris Isle is a large island located in the center of Lordamere Lake and it is generally considered to be a part of Silverpine Forest. Together with the Dawning Isles, they form a broken circle of dry land in the lake.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Fenris Keep",
			short = "The gloomy Fenris Keep lays at the center of Lordamere Lake in Silverpine Forest upon the Fenris Isle. The keep had strategic significance, and was home to a sizable portion of Lordaeron's military.",
			full = "The gloomy Fenris Keep lays at the center of Lordamere Lake in Silverpine Forest upon the Fenris Isle. The keep had strategic significance, and was home to a sizable portion of Lordaeron's military.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["forsaken front"] = {
			name = "Forsaken Front",
			short = "The Forsaken Front is an outpost and front lines to the Battlefront in southern Silverpine Forest.",
			full = "The Forsaken Front is an outpost and front lines to the Battlefront in southern Silverpine Forest. It's here Lady Sylvanas commands the attack on the Gilneas Liberation Front and where she had Lord Godfrey, Walden, and Baron Ashbury raised into her service.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_Front",
		},
		["forsaken high command"] = {
			name = "Forsaken High Command",
			short = "Forsaken High Command, part of the Forsaken Front, is a subzone of Silverpine Forest and is the first quest hub players will run across after their adventures in Tirisfal Glades.",
			full = "Forsaken High Command, part of the Forsaken Front, is a subzone of Silverpine Forest and is the first quest hub players will run across after their adventures in Tirisfal Glades.\n\nYou will need to complete this in order to make the flightmaster and other vendors appear.\n\nOn the way here from Tirisfal Glades, players will witness Dreadguards marching up and down the zone as well as pass by Forsaken Troopers and Forsaken Apothecaries preparing for battle with Gilneas.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_High_Command",
		},
		["forsaken rear guard"] = {
			name = "Forsaken Rear Guard",
			short = "Forsaken Rear Guard is a Forsaken base located between Forsaken High Command and the Sepulcher in Silverpine Forest.",
			full = "Forsaken Rear Guard is a Forsaken base located between Forsaken High Command and the Sepulcher in Silverpine Forest. A large contingent of Orgrimmar sea forces has recently arrived here, and they appear to enjoy their alcohol. Orc Sea Dogs can be found throughout the area.",
			source = "https://warcraft.wiki.gg/wiki/Forsaken_Rear_Guard",
		},
		["gilneas liberation front base camp"] = {
			name = "Gilneas Liberation Front Base Camp",
			short = "Gilneas Liberation Front Base Camp is a worgen base of operations in Silverpine Forest, headed by Commander Lorna Crowley and inhabited by Worgen Warbringers.",
			full = "Gilneas Liberation Front Base Camp is a worgen base of operations in Silverpine Forest, headed by Commander Lorna Crowley and inhabited by Worgen Warbringers.\n\nLord Godfrey will have Horde heroes come here to kidnap Crowley during an assignment. Heroes wandering into the area should be advised that the mobs are elites due to the presence of three friendly during the associated quests.",
			source = "https://warcraft.wiki.gg/wiki/Gilneas_Liberation_Front_Base_Camp",
		},
		["greymane wall"] = {
			name = "Greymane Wall",
			short = "The Greymane Wall was erected before the Third War by order of King Genn Greymane, as the kingdom of Gilneas isolated itself from the Alliance of Lordaeron and the rest of the world due to a disagreement surrounding the maintenance taxes about the internment camps for the orcs, and other political disputes.",
			full = "The Greymane Wall was erected before the Third War by order of King Genn Greymane, as the kingdom of Gilneas isolated itself from the Alliance of Lordaeron and the rest of the world due to a disagreement surrounding the maintenance taxes about the internment camps for the orcs, and other political disputes. It is a colossal wall with a substantially sized gate, located at the southern edge of the Silverpine Forest in Lordaeron (its entrance near Pyrewood Village) and the northern edge of the Gilnean peninsula.\n\nThe controversial edifice led to the rise of tensions among the people of Gilneas, but protected them from the Plague of Undeath and the Scourging of Lordaeron. During the war across the continent, many refugees that escaped the undead made camp outside of the wall, but its gates remained closed for years, and the refugees perished at some point.\n\nFollowing the end of the Third War, the wall sowed civil discord in the isolated kingdom, rising until eventually led to the Northgate Rebellion, a devastating civil war that nearly destroyed the nation. Though King Greymane was able to put down the dissenters with the apprehension of the rebellion's leader, Lord Darius Crowley, the kingdom began to experience other troubles, in the form of the worgen curse.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Ivar Patch",
			short = "The Ivar Patch is a pumpkin patch in northern Silverpine Forest. This was once a prosperous and pleasant farm, and Ivar employed many farmhands and servants.",
			full = "The Ivar Patch is a pumpkin patch in northern Silverpine Forest. This was once a prosperous and pleasant farm, and Ivar employed many farmhands and servants. That was only until the Scourge ravaged the lands of Lordaeron, however.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Lordamere Lake (or Lake Lordamere) is one of the largest lakes in the Eastern Kingdoms, rivaled only by Darrowmere Lake to the east.",
			full = "Lordamere Lake (or Lake Lordamere) is one of the largest lakes in the Eastern Kingdoms, rivaled only by Darrowmere Lake to the east. Along with Darrowmere, this lake has been marked by many events that took place around it. Here, many human kingdoms, at the age of the Alliance of Lordaeron, that were prosperous, have been found around the lake's shores and nearby mountains, including Lordaeron, Dalaran and Alterac. Lordamere was very likely given its name from the nearby Capital City of the kingdom of Lordaeron which was built on its northern shores and which was named after Lordain.\n\nSome time after the Third War, Lady Vashj and her naga retreated here after the battle at the ruins of Dalaran.\n\nThe lake, for a time, acted as a natural barrier between the Forsaken lands of Tirisfal Glades and Silverpine Forest and the contested lands of the Alterac Mountains. At its center lie the Dawning Isles, and Fenris Isle which was taken over by agents of the Scourge, who were being attacked by the Forsaken. However, they were ultimately removed by the worgen. Fenris Isle was later taken by Hillsbrad Refugees and the leaders of Southshore, having escaped from the Hillsbrad Foothills, as a temporary safe haven from the Forsaken. East of Fenris Isle, the small group of islands called the Dawning Isles are where the Vile Fin murlocs have made their claim overrunning them.\n\nAt some point, Fenris Isle, namely its keep, was overtaken by the Forsaken led by Deathstalker Hayward. The Horde later distracted these forces to evacuate Undercity refugees across the lake.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Malden's Orchard",
			short = "Malden's Orchard is a small orchard in northern Silverpine Forest. The trees in the orchard are dark and evergreen, but their fruits have not been picked in years.",
			full = "Malden's Orchard is a small orchard in northern Silverpine Forest. The trees in the orchard are dark and evergreen, but their fruits have not been picked in years. The orchard is named for its former owner, who was forced to flee his home when the Scourge invaded Lordaeron.\n\nRecently, large numbers of black worgs have taken up residence around the orchard and its single small cottage. When the Deathstalkers Rane Yorick, Quinn Yorick, and Erland McKree were conducting their reconnaissance mission, Erland was tasked with exploring Malden's Orchard. When he arrived, he encountered the numerous worgs and was forced to take refuge within the abandoned cottage. He was pinned down for several days until with the aid of Forsaken agents, he managed to make his escape and flee back to his partners at the Ivar Patch to the southwest.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides beachhead"] = {
			name = "North Tide's Beachhead",
			short = "North Tide's Beachhead is the shore in northwestern Silverpine Forest currently under the control of Bloodfang worgen.",
			full = "North Tide's Beachhead is the shore in northwestern Silverpine Forest currently under the control of Bloodfang worgen. This is the location where two of the three Horde ships filled with reinforcements and a drunken crew built a small camp before being defeated by the feral worgen.\n\nThe third ship sank just north of here at the Skittering Dark.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Beachhead",
		},
		["north tides hollow"] = {
			name = "North Tide's Hollow",
			short = "North Tide's Hollow was a region of Silverpine Forest just north of the Sepulcher. The Hollow was one of the many haunts of the evil Moonrage worgen, the servants of the Archmage Arugal.",
			full = "North Tide's Hollow was a region of Silverpine Forest just north of the Sepulcher. The Hollow was one of the many haunts of the evil Moonrage worgen, the servants of the Archmage Arugal. These worgen set up very crude encampments in some places. These camps employed only the meanest necessities of survival needed by the tough worgen.\n\nWhile the subzone has been removed, the camp still exists, but as part of the North Tide's Beachhead.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "North Tide's Run",
			short = "North Tide's Run is the name given to the northwestern shoreline of Silverpine Forest. The region includes the beach and a thin strip of the Great Sea.",
			full = "North Tide's Run is the name given to the northwestern shoreline of Silverpine Forest. The region includes the beach and a thin strip of the Great Sea. The most prominent feature of the run is the partially submerged ship that lies at the edge of the water.\n\nWallace the Blind has setup a small campfire near the waters by the sunken Horde ship.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Olsen's Farthing",
			short = "Olsen's Farthing was once a bustling farmstead with direct contact into the main throughway of trade in the Silverpine Forest.",
			full = "Olsen's Farthing was once a bustling farmstead with direct contact into the main throughway of trade in the Silverpine Forest.\n\nThis section concerns content related to the original World of Warcraft.\n\nA few years after the Third War, the Olsen's Farthing was left in ruins, with undead under the control of Thule Ravenclaw ravenously attacking anyone in the area.\n\nDuring the invasion of Gilneas, Bloodfang Stalkers prowled around the area, while the corpses of Veteran Forsaken Troopers littered the ground. Caretaker Smithers relocated here from Hillsbrad, while Lady Sylvanas Windrunner sent Horde adventurers there to avenge the Forsaken forces and search for clues as to the recent dealings of Darius Crowley and Ivar Bloodfang. The fields are also much bigger.\n\nYears later, by the time the Scarlet Crusade took control of Fenris Isle, several plagued wolves, bears, and sickly deer were present on the farm. The crusaders also left propaganda against the Forsaken on the trees. Velonara and Faranell sent adventurers to the farm to kill the beasts for their flesh, collect [Boom Weed], and to destroy the propaganda.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood chapel"] = {
			name = "Pyrewood Chapel",
			short = "Pyrewood Chapel is the chapel of Pyrewood Village located near the entrance into town in Silverpine Forest.",
			full = "Pyrewood Chapel is the chapel of Pyrewood Village located near the entrance into town in Silverpine Forest.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Chapel",
		},
		["pyrewood inn"] = {
			name = "Pyrewood Inn",
			short = "Pyrewood Inn is the local inn of Pyrewood Village located on a hill towards the back of town in Silverpine Forest.",
			full = "Pyrewood Inn is the local inn of Pyrewood Village located on a hill towards the back of town in Silverpine Forest.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Inn",
		},
		["pyrewood town hall"] = {
			name = "Pyrewood Town Hall",
			short = "Pyrewood Town Hall is the town hall of Pyrewood Village located at the back of town in Silverpine Forest.",
			full = "Pyrewood Town Hall is the town hall of Pyrewood Village located at the back of town in Silverpine Forest.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Town_Hall",
		},
		["pyrewood village"] = {
			name = "Pyrewood Village",
			short = "Pyrewood Village (or simply Pyrewood) was an Alliance-friendly Gilnean village within the Silverpine Forest.",
			full = "Pyrewood Village (or simply Pyrewood) was an Alliance-friendly Gilnean village within the Silverpine Forest. The village was a settlement, with a town hall, a blacksmith, and a chapel, inhabited by a group of humans who had survived the coming of the Scourge during the Third War. However, they were later cursed by the maddened Arugal, who turned the townsfolk into rampaging worgen at night.\n\nIt was finally being burned down by agents of the Horde on the orders of Lord Vincent Godfrey.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "Sepulcher",
			short = "The Sepulcher, also known as the Silverpine Sepulcher, is a Forsaken base located in the western side of Silverpine Forest. The area itself lies above the Lordaeronian coastline, nestled within the surrounding hills.",
			full = "The Sepulcher, also known as the Silverpine Sepulcher, is a Forsaken base located in the western side of Silverpine Forest. The area itself lies above the Lordaeronian coastline, nestled within the surrounding hills. It was nothing more than a large graveyard and string of expeditionary caravans and individuals.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Shadowfang Keep",
			short = "Shadowfang Keep is a haunted keep not far from the borders of Gilneas in southern Silverpine Forest, on a high bluff overlooking Pyrewood Village.",
			full = "Shadowfang Keep is a haunted keep not far from the borders of Gilneas in southern Silverpine Forest, on a high bluff overlooking Pyrewood Village. It was named for the forces of its former master, the demented Archmage Arugal, who wrested the keep from Baron Silverlaine with his worgen \"children\" and held it until he was defeated by a group of Horde heroes. The keep was then occupied by the Scourge remnants and followers of the renegade Gilnean nobleman Vincent Godfrey, traitor to both his homeland and to the Forsaken who returned him from death.\n\nBy the end of the war, the Bloodfang pack had taken control of the keep, moving most of its artifacts to Fenris Keep to be guarded closely.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Shining Strand",
			short = "The Shining Strand is the name of the section of shoreline of Lordamere Lake in Silverpine Forest.",
			full = "The Shining Strand is the name of the section of shoreline of Lordamere Lake in Silverpine Forest. It stretches from the Lordaeron capital city in the north and ends at the range of rough hills that divides Silverpine from the Alterac Mountains.\n\nThe Vile Fin tribe of murlocs used to have several settlements along the strand making it very dangerous for unseasoned travelers, until they moved to the Dawning Isles. In his journal, the late Apothecary Berard spoke of a rare item that could be obtained from the Vile Fins, a Hardened Tumor. Berard speculated that the tumor could be used in the concoction of a new plague.\n\nThe Forsaken, likely having forced the murlocs out, have setup several camps along the shoreline and are currently fighting with worgen.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Skittering Dark",
			short = "The Skittering Dark is an abandoned mine and nearby area crawling with Skitterweb spiders found just west of the Forsaken Rear Guard and east of North Tide's Run in Silverpine Forest.",
			full = "The Skittering Dark is an abandoned mine and nearby area crawling with Skitterweb spiders found just west of the Forsaken Rear Guard and east of North Tide's Run in Silverpine Forest.\n\nThe spiders here are led by the Skitterweb Matriarch, a gigantic spider hiding deep within the mine. Krethis the Shadowspinner, a rare spider, can sometimes be found outside the mine. Several cocoons litter the area filled with worgen, worgs, bears, and even the orcs that crashed along the shore to the west.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "South Tide's Run",
			short = "South Tide's Run is complementary to North Tide's Run, and is the name for the southwestern coast of Silverpine Forest bordering the Great Sea.",
			full = "South Tide's Run is complementary to North Tide's Run, and is the name for the southwestern coast of Silverpine Forest bordering the Great Sea.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Valgan's Field",
			short = "Valgan's Field is yet another among the desolate farms of northern Silverpine Forest. This farm is located just west of the Shining Strand, east of the main north-south road, and north of a small river.",
			full = "Valgan's Field is yet another among the desolate farms of northern Silverpine Forest. This farm is located just west of the Shining Strand, east of the main north-south road, and north of a small river. It is named after its former owner, who was either killed or forced to flee from his farm when the Scourge arrived in Silverpine. Formerly occupied by the feral Moonrage worgen, they have since vanished, leaving the farm empty. Only Nightlash can occasionally be spotted around here. At its heyday, the farm would have been a lovely place, offering a magnificent view of Lordamere Lake.\n\nCommanded by Lieutenant Hawlsey, it was used as a training ground. The Forsaken leadership sent adventurers to kill Hawlsey and his recruits.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Western Plaguelands: 29 subzones
	[1422] = {
		["andorhal"] = {
			name = "Andorhal",
			short = "Andorhal is a destroyed human city located in the Western Plaguelands, formerly known as the western Eastweald, Lordaeron's breadbasket.",
			full = "Andorhal is a destroyed human city located in the Western Plaguelands, formerly known as the western Eastweald, Lordaeron's breadbasket. One of the largest cities in northern Lordaeron, Andorhal was the main agricultural distribution point in the region. It is from here that the plague of undeath started to spread at the beginning of the Third War. Following the Scourging of Lordaeron, the undead Scourge took control of the ruined city for years, until the Alliance and the Forsaken expelled them and fought each other in the Battle for Andorhal. The waters around Andorhal are still contaminated by the plague.",
			source = "https://warcraft.wiki.gg/wiki/Andorhal",
		},
		["bulwark"] = {
			name = "Bulwark",
			short = "The Bulwark is the Forsaken's last bastion of defense against the forces of the Scourge to the east, located on the border of Tirisfal Glades and the Western Plaguelands.",
			full = "The Bulwark is the Forsaken's last bastion of defense against the forces of the Scourge to the east, located on the border of Tirisfal Glades and the Western Plaguelands. The Argent Dawn and Forsaken defenders at the Bulwark have teamed up to protect the land from the hordes of undead to the east, and send experienced adventurers of the Horde to battle the minions of the Lich King.\n\nUnlike the rest of Tirisfal Glades, this area was filled with plaguemist until recently, the sky tinted the same yellowish-gray color as in the Western Plaguelands. However, with the reclamation efforts underway in the Plaguelands, this effect has subsided and the area looks like the rest of Tirisfal.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Caer Darrow",
			short = "Caer Darrow is an island and a ruined keep located on Darrowmere Lake in the Western Plaguelands.",
			full = "Caer Darrow is an island and a ruined keep located on Darrowmere Lake in the Western Plaguelands. Prior to the Third War, Kel'Thuzad made a deal with the House Barov and established the headquarters of the Cult of the Damned under this ancient human fortress, in the catacombs that became Scholomance, a school of necromancy. Once a bright institution it is now dedicated to the darkest, most vile arts, where human monsters seek to push the bounds of power and life itself.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["charred outpost"] = {
			name = "Charred Outpost",
			short = "The Charred Outpost is a ruined Scarlet Crusade camp in the Western Plaguelands, found in between the Felstone Field and Dalson's Farm.",
			full = "The Charred Outpost is a ruined Scarlet Crusade camp in the Western Plaguelands, found in between the Felstone Field and Dalson's Farm.\n\nAs one of the last outposts held by the Crusade in the area, the camp hosted several hunters, medics and invokers.\n\nThe sole survivor of this ordeal -- or perhaps a late arrival -- was a Scarlet High Clerist, who was seen afterward investigating the bodies. Later, Lindsay Ravensun used the site as a temporary staging point to direct Horde agents against Felstone Field.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Outpost",
		},
		["chillwind camp"] = {
			name = "Chillwind Camp",
			short = "Chillwind Camp is an Alliance encampment in the Western Plaguelands. It is located in the south, at the entrance to the Plaguelands from Chillwind Point in the Alterac Mountains.",
			full = "Chillwind Camp is an Alliance encampment in the Western Plaguelands. It is located in the south, at the entrance to the Plaguelands from Chillwind Point in the Alterac Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons farm"] = {
			name = "Dalson's Farm",
			short = "With the Scourge having been expunged from Dalson's Tears, it has been rebuilt as Dalson's Farm in the middle of the Western Plaguelands.",
			full = "With the Scourge having been expunged from Dalson's Tears, it has been rebuilt as Dalson's Farm in the middle of the Western Plaguelands. Formerly known as Dalson's Orchard, the farm appears to be abandoned but is presently growing a variety of vegetables including pumpkins. The nearby neutral quest hub of the Menders' Stead is nearby, run by the Cenarion Circle.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Farm",
		},
		["dalsons tears"] = {
			name = "Dalson's Tears",
			short = "Dalson's Tears is an abandoned farm located in the middle of the Western Plaguelands. Formerly known as Dalson's Orchard, the farm has been taken over by the Scourge.",
			full = "Dalson's Tears is an abandoned farm located in the middle of the Western Plaguelands. Formerly known as Dalson's Orchard, the farm has been taken over by the Scourge. They have placed a large cauldron in the middle of the field which constantly spews disease-filled vapors into the air. The cauldron is guarded by Cauldron Lord Malvinious, Blighted Zombies, Rotting Cadavers, and Skeletal Terrors.\n\nThe unfortunate inhabitants of the farm still wander it in undeath. Mrs. Dalson now roams the property as a Wandering Skeleton, and once you read her diary, she can drop the key to the outhouse, where Farmer Dalson, now a terrible ghoul, is trapped. If one kills Farmer Dalson, he drops a key to a cabinet. The cabinet left in the farmhouse can be opened for a reward.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Darrowmere Lake",
			short = "Darrowmere Lake is one of the largest lakes in the Eastern Kingdoms. It is located in the southeastern part of the Western Plaguelands, and is one of the most symbolic places of the fallen kingdom of Lordaeron.",
			full = "Darrowmere Lake is one of the largest lakes in the Eastern Kingdoms. It is located in the southeastern part of the Western Plaguelands, and is one of the most symbolic places of the fallen kingdom of Lordaeron. At its center, there is the abandoned island town of Caer Darrow where the House of Barov stood. Underneath the town lies Scholomance, home of the Cult of the Damned and countless undead minions.\n\nIt is connected to the Thondroril River in the north and Darrowmere River in the south.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Felstone Field",
			short = "Felstone Field is located in northwestern Western Plaguelands. Originally, the area had been a life-sustaining farm, but it was overrun by the vile Scourge.",
			full = "Felstone Field is located in northwestern Western Plaguelands. Originally, the area had been a life-sustaining farm, but it was overrun by the vile Scourge. In their quest to destroy the living, they placed a large cauldron in the middle of the field which constantly spewed disease-filled vapors into the air. The cauldron itself was protected by Cauldron Lord Bilemaw, Skeletal Sorcerers, Skeletal Flayers and Slavering Ghouls.\n\nA Scarlet Crusader party was also detected in Felstone and would destroy both players and Scourge with equal vengeance.\n\nInside the house in the northeastern corner of the field was a friendly NPC, Janice Felstone, who offered a quest.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Gahrron's Withering",
			short = "Gahrron's Withering is an abandoned farmstead located at the eastern end of the Western Plaguelands. Formerly known as Gahrron's Quickening, the farm has been taken over by the Scourge.",
			full = "Gahrron's Withering is an abandoned farmstead located at the eastern end of the Western Plaguelands. Formerly known as Gahrron's Quickening, the farm has been taken over by the Scourge. They have placed a large cauldron in the middle of the field which constantly spews disease-filled vapors into the air. The cauldron is guarded by Cauldron Lord Soulwrath and other Scourge officers. Haunting Visions and many Wailing Deaths and Hungering Wraiths. Gahrron's Withering is a popular place for grinding Argent Dawn reputation, as the quest involving the Scourge Cauldron located here provides the best reputation of the four Cauldron quests.\n\nGahrron's Withering is the only farm of the four Target: Plague Cauldron quests given by High Priestess MacDonnell at Chillwind Camp that does not have additional quest givers in the area. It was once owned by Del Gahrron before the Scourge arrived. At the farm, the Alliance forces killed the corrupted Joseph Redpath. His shield remained there.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Hearthglen",
			short = "Hearthglen is a fortified town and former principality of the kingdom of Lordaeron, located north of Andorhal in the Western Plaguelands.",
			full = "Hearthglen is a fortified town and former principality of the kingdom of Lordaeron, located north of Andorhal in the Western Plaguelands. It is a sturdy fortress, its walls encircling a town hall, mage tower, lumber mill, blacksmith, stables, scout tower and a mine besides its keep. The road to the town is called Hearthglen Pass, and a forest near Hearthglen is called the Hearthglen Woods.\n\nHearthglen stands out from the rest of the region for its peaceful appearance, although it has not been spared from the attacks of the Scourge. The town and formerly the region was controlled from Mardenholde Keep. It fell under the control of the Scarlet Crusade until Tirion Fordring returned and resumed control. It now serves as a training ground and headquarters for the Argent Crusade.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["legacy of scholomance"] = {
			name = "Legacy of Scholomance",
			short = "It is unlocked by completing the [Memory of Scholomance] achievement, and can be accessed via a portal across the hall from the normal dungeon entrance.",
			full = "It is unlocked by completing the [Memory of Scholomance] achievement, and can be accessed via a portal across the hall from the normal dungeon entrance.\n\nScholomance maps",
			source = "https://warcraft.wiki.gg/wiki/Legacy_of_Scholomance",
		},
		["malicias outpost"] = {
			name = "Malicia's Outpost",
			short = "Malicia's Outpost is south of the Weeping Cave in the Western Plaguelands. The area appears to be inhabited by members of the Cult of the Damned who have various animals imprisoned in cages, led by Malicia herself.",
			full = "Malicia's Outpost is south of the Weeping Cave in the Western Plaguelands. The area appears to be inhabited by members of the Cult of the Damned who have various animals imprisoned in cages, led by Malicia herself.",
			source = "https://warcraft.wiki.gg/wiki/Malicia's_Outpost",
		},
		["mardenholde keep"] = {
			name = "Mardenholde Keep",
			short = "Mardenholde Keep is the fortress keep of Hearthglen in the Western Plaguelands. Currently held by the Argent Crusade, the town is controlled from here, and formerly was the rest of the region.",
			full = "Mardenholde Keep is the fortress keep of Hearthglen in the Western Plaguelands. Currently held by the Argent Crusade, the town is controlled from here, and formerly was the rest of the region.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["menders stead"] = {
			name = "Menders' Stead",
			short = "The Menders' Stead is a subzone in the center of Western Plaguelands that is inhabited by the Cenarion Circle and Argent Crusade, who are cleansing the area.",
			full = "The Menders' Stead is a subzone in the center of Western Plaguelands that is inhabited by the Cenarion Circle and Argent Crusade, who are cleansing the area.",
			source = "https://warcraft.wiki.gg/wiki/Menders'_Stead",
		},
		["northridge lumber camp"] = {
			name = "Northridge Lumber Camp",
			short = "The Northridge Lumber Camp (or Northridge Lumber Mill) is a lumber mill operated by the Scarlet Crusade in the northern part of the Western Plaguelands, close to Hearthglen.",
			full = "The Northridge Lumber Camp (or Northridge Lumber Mill) is a lumber mill operated by the Scarlet Crusade in the northern part of the Western Plaguelands, close to Hearthglen. Both agents of the Alliance and of the Horde realize the importance of this outpost, and send adventurers out to gather termites to wreak havoc on the Scarlet Crusade's precious lumber supply. Mickey Levine's family worked at the mill.\n\nNathaniel Dumah, a human whose family ran the Northridge Lumber Mill before the Third War, has returned and reclaimed the mill for the Argent Crusade. The camp is currently under siege by Northridge Spiders. Many of the trees surrounding the area have been cut down.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["path of uther"] = {
			name = "Path of Uther",
			short = "The Path of Uther is the walkway leading up to Uther's Tomb at Sorrow Hill in the Western Plaguelands.",
			full = "The Path of Uther is the walkway leading up to Uther's Tomb at Sorrow Hill in the Western Plaguelands. With the restoration of the cemetery after the death of the Lich King, the path leading to the tomb is now lined with hedges, and marked by a great lion's-head gate at its start.",
			source = "https://warcraft.wiki.gg/wiki/Path_of_Uther",
		},
		["plaguemist ravine"] = {
			name = "Plaguemist Ravine",
			short = "Plaguemist Ravine is a pathway in the Hinterlands which leads north to Caer Darrow in the Western Plaguelands.",
			full = "Plaguemist Ravine is a pathway in the Hinterlands which leads north to Caer Darrow in the Western Plaguelands. It is located northwest of Quel'Danil Lodge, and the entrance to it can be found within the woods west of Quel'Danil Lodge at on the other side of the mountain. This can also be found to the north of Rhapsody Shindigger at Shindigger's Camp. There are no mobs or NPCs in this subzone.\n\nThe name \"Plaguemist Ravine\" was given recently, as the plaguing mist from the pathway is a stark contrast to the natural freshness of the rest of the Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["redpine dell"] = {
			name = "Redpine Dell",
			short = "Redpine Dell is a small forest clearing south of Hearthglen, named for the Redpine gnolls that wander the area and patrol the road between it and the gates of Hearthglen.",
			full = "Redpine Dell is a small forest clearing south of Hearthglen, named for the Redpine gnolls that wander the area and patrol the road between it and the gates of Hearthglen.",
			source = "https://warcraft.wiki.gg/wiki/Redpine_Dell",
		},
		["ruins of andorhal"] = {
			name = "Ruins of Andorhal",
			short = "The Ruins of Andorhal are the ruins of the city of Andorhal, located in the center of the Western Plaguelands. The ruins are controlled by Araj the Summoner, a level 61 elite lich, surrounded by Scourge agents.",
			full = "The Ruins of Andorhal are the ruins of the city of Andorhal, located in the center of the Western Plaguelands. The ruins are controlled by Araj the Summoner, a level 61 elite lich, surrounded by Scourge agents. The inhabitants are for the most part ghouls, skeletons, banshees, and abominations.\n\nMany players in WoW once regarded Andorhal as some of the most difficult (if not the most difficult) non-instance content in the game. During the pre-release beta, all of the mobs in Andorhal were elites, which practically made it an outdoor dungeon. For several months after the original release of WoW, Andorhal was very different than it appears in-game today. Although most of the mobs lost their elite status, the city was still encircled by walls on all sides and had a much thicker infestation of undead than it does currently. Most players, even at level 60, struggled soloing Andorhal, particularly since these were times before Onyxia or Molten Core gear was commonplace. Eventually, Andorhal received a significant nerf; the walls were removed, some houses were spread out or removed, and many mob spawns were similarly curtailed.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scholomance",
			short = "The Scholomance, also known as the School of Necromancy, is a vile academy for prospective necromancers of the Scourge, is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of Caer Darrow.",
			full = "The Scholomance, also known as the School of Necromancy, is a vile academy for prospective necromancers of the Scourge, is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of Caer Darrow. The layout of the dungeon changed to be less confusing, similar to how the Sunken Temple was done. Five bosses await adventurers there.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["scholomance classic"] = {
			name = "Scholomance",
			short = "The Scholomance, a vile academy for prospective necromancers of the Scourge, is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of Caer Darrow.",
			full = "The Scholomance, a vile academy for prospective necromancers of the Scourge, is located in the ruins of the palatial House of Barov, on a rise overlooking the abandoned city of Caer Darrow. The enemy level range is 57-62.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance_(Classic)",
		},
		["sorrow hill"] = {
			name = "Sorrow Hill",
			short = "Sorrow Hill is a large cemetery south of Andorhal in what is now the Western Plaguelands.",
			full = "Sorrow Hill is a large cemetery south of Andorhal in what is now the Western Plaguelands.\n\nIn more peaceful times the cemetery was used to bury the deceased from Andorhal and the surrounding area. The cemetery was used for both the rich and poor, having many crypts as well as simple plots. When the Plague of Undeath struck and the Scourge began their relentless raids and attacks, the number of cemetery residences skyrocketed. Quickly dug and poorly marked graves can still be seen at Sorrow Hill from the massive casualties suffered in the defense of Andorhal. Eventually, the surviving townspeople stopped burying their dead, and instead dug a mass grave south of the cemetery to incinerate their loved ones, for fear of undeath taking them. The final blow for the surviving townsfolk was when Lord Uther was struck down by Arthas; the final act of the dwindling population before abandoning the town was to erect a great tomb where they buried the torn body of the great hero on the top of the cemetery hill. \"Sorrow Hill\" may refer to Uther's final resting place.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["sorrow hill crypt"] = {
			name = "Sorrow Hill Crypt",
			short = "Sorrow Hill, located in Western Plaguelands, is a large graveyard filled with victims from the plague and of the Scourge War, including the nearby tomb of Uther the Lightbringer.",
			full = "Sorrow Hill, located in Western Plaguelands, is a large graveyard filled with victims from the plague and of the Scourge War, including the nearby tomb of Uther the Lightbringer. The dilapidated crypt on the eastern edge of Sorrow Hill is inhabited by skeletal magi and Scourge warders.\n\nThe Crypt on the edge of Sorrow Hill is now devoid of mobs, but still accessible. [15-30] The Abandoned Crypt takes place here. It was apparently used for weapon storage. The books are unexplained.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill_Crypt",
		},
		["taelans tower"] = {
			name = "Taelan's Tower",
			short = "Taelan's Tower is an Argent Crusade guard tower along the road to Hearthglen in the Western Plaguelands.",
			full = "Taelan's Tower is an Argent Crusade guard tower along the road to Hearthglen in the Western Plaguelands.\n\nA Holy Coffer containing the [Mark of the Lightbringer] was situated at the top of the structure. In the quest [60G] In Dreams, Taelan Fordring was killed at this location by Grand Inquisitor Isillien, who was in turn killed by Taelan's father, Highlord Tirion Fordring.\n\nThe Hearthglen priest Daria L'Rayne is responsible for maintaining it. The tower is currently controlled by Redpine gnolls, who have killed the Hearthglen troops who guarded it.",
			source = "https://warcraft.wiki.gg/wiki/Taelan's_Tower",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril River forms a natural boundary between the Western and Eastern Plaguelands.",
			full = "The Thondroril River forms a natural boundary between the Western and Eastern Plaguelands. The spring of this river is located in the current closed area known as Northern Lordaeron and runs from near the Terrorweb Tunnel to the north and empties out into Darrowmere Lake to the south. South of the lake it becomes the Darrowmere River.\n\nAlong the river on on both sides, you can find maggots, vampire bats, plaguebears, spiders and later snapjaws.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Uther's Tomb",
			short = "Uther's Tomb is a monument dedicated to Uther the Lightbringer, at Sorrow Hill in what is now the Western Plaguelands - the only bastion of Light in a dying land.",
			full = "Uther's Tomb is a monument dedicated to Uther the Lightbringer, at Sorrow Hill in what is now the Western Plaguelands - the only bastion of Light in a dying land. It is connected to the lower parts of Sorrow Hill by the Path of Uther. The grave is sacred to followers of the Light. High Priest Thel'danis is the caretaker of the tomb.\n\nDuring the Harvest Festival, Wagner Hammerstrike asks Alliance adventurers to honor Uther by placing offerings at his statue.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "Weeping Cave",
			short = "The Weeping Cave is a cave filled with bog beasts and oozes, and also the location of a rare spawn elemental named The Husk.",
			full = "The Weeping Cave is a cave filled with bog beasts and oozes, and also the location of a rare spawn elemental named The Husk. The cave is located in the northeastern area of the Western Plaguelands, just west of the Thondroril River.\n\nThe Rotting Behemoth and Decaying Horror mobs inside this cave have a low chance to drop [Recipe: Greater Nature Protection Potion].",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "Writhing Haunt",
			short = "The Writhing Haunt is an area located in the central part of the Western Plaguelands, just east of the Ruins of Andorhal. Originally the area was a life-sustaining farm, but it has since been overrun by the vile Scourge.",
			full = "The Writhing Haunt is an area located in the central part of the Western Plaguelands, just east of the Ruins of Andorhal. Originally the area was a life-sustaining farm, but it has since been overrun by the vile Scourge. In their quest to destroy the living, they have placed a large cauldron in the middle of the field which constantly spews disease-filled vapors into the air. The cauldron itself is protected by Cauldron Lord Razarch, Rotting Ghouls, Freezing Ghouls, and Fetid Zombies.\n\nYou can find Mulgris Deepriver, a quest giving NPC, hidden inside a house at the Writhing Haunt.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Eastern Plaguelands: 49 subzones
	[1423] = {
		["acherus the ebon hold"] = {
			name = "Acherus: The Ebon Hold",
			short = "Acherus: The Ebon Hold is a former Scourge necropolis originally floating above Light's Hope Chapel in the Eastern Plaguelands.",
			full = "Acherus: The Ebon Hold is a former Scourge necropolis originally floating above Light's Hope Chapel in the Eastern Plaguelands. It is the headquarters of the Knights of the Ebon Blade and the starting area for all death knights of the Alliance and the Horde. As such, the Ebon Hold has been designated as a sanctuary, and can be reached by death knights through the [Death Gate] ability.",
			source = "https://warcraft.wiki.gg/wiki/Acherus%3A_The_Ebon_Hold",
		},
		["blackwood lake"] = {
			name = "Blackwood Lake",
			short = "Blackwood Lake is a polluted lake in the Eastern Plaguelands. Its waters are infested by corrupted water elementals.",
			full = "Blackwood Lake is a polluted lake in the Eastern Plaguelands. Its waters are infested by corrupted water elementals. Blackwood Lake has been mentioned in the quest item Extended Annals of Darrowshire from the quest Brother Carlin as being the resting place of Horgus the Ravager's head.\n\nThere was once a town here by the name of Blackwood, home to the infamous Grand Marshal Othmar Garithos.\n\nThere is a small Argent Dawn camp here with an Argent Medic tending to infantry.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Browman Mill",
			short = "Browman Mill (or Browman's Mill) is a haunted lumber mill just north of Light's Hope Chapel in the Eastern Plaguelands. Currently, the mill is crawling with skeletons, banshees and Abominations.",
			full = "Browman Mill (or Browman's Mill) is a haunted lumber mill just north of Light's Hope Chapel in the Eastern Plaguelands. Currently, the mill is crawling with skeletons, banshees and Abominations. The owner was Stephen Browman, who was killed and raised as a ghoul in service to the Scourge. He currently stands guard inside his former mill.\n\nIn the Scarlet Enclave - the death knight starting area - the mill is the Scourge staging ground for the Battle for Light's Hope Chapel.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Corin's Crossing",
			short = "Corin's Crossing is a ruined town in south-central Eastern Plaguelands, located on a crossroads between Andorhal, Darrowshire, Stratholme, and Tyr's Hand and nestled between the shores of the Infectis Scar and Lake Mereldar.",
			full = "Corin's Crossing is a ruined town in south-central Eastern Plaguelands, located on a crossroads between Andorhal, Darrowshire, Stratholme, and Tyr's Hand and nestled between the shores of the Infectis Scar and Lake Mereldar. Light's Shield Tower is located just to the north. The town, which has a town hall and blacksmith, is filled to the brim with Scourge. Even rogues using [Stealth] are advised not to attempt to sneak through the town, as the invisible Unseen Servants can see through stealth.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Crown Guard Tower",
			short = "Crown Guard Tower is a scout tower located in the Eastern Plaguelands. During the Scourge invasion of Lordaeron, Crown Guard Tower was destroyed and left in ruins.",
			full = "Crown Guard Tower is a scout tower located in the Eastern Plaguelands. During the Scourge invasion of Lordaeron, Crown Guard Tower was destroyed and left in ruins. Later it became a battleground as it was one of the fallen towers that the Alliance and Horde fought over for in order to fortify themselves in Lordaeron. The Crown Guard Tower, along with all the other towers of the Eastern Plaguelands, have since been rebuilt by the Argent Crusade and is being used as an outpost for the region. Like the nearby Light's Hope Chapel, there are signs of life around the tower, and there is also a neutral flight master.\n\nOne can only presume that Blizzard understands the players' affinity for exiting a tower by jumping over the ledge.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["crypt lights hope chapel"] = {
			name = "Crypt (Light's Hope Chapel)",
			short = "Behind Light's Hope Chapel is a rather large cemetery and within that cemetery lies a crypt. Lord Raymond George can be summoned here after completion of [15-30] Argent Call: The Trial of the Crypt.",
			full = "Behind Light's Hope Chapel is a rather large cemetery and within that cemetery lies a crypt. Lord Raymond George can be summoned here after completion of [15-30] Argent Call: The Trial of the Crypt.\n\nThis section concerns content related to Legion.\n\nDuring the third invasion of the Burning Legion, the new Deathlord of the Knights of the Ebon Blade invaded the chapel once more. The Deathlord arrived here and raised ghouls and sent them at the Argent sentries while the three horsemen entered the chapel and the Sanctum of Light. They managed to raise the undead there because the Light is weak in the crypt.",
			source = "https://warcraft.wiki.gg/wiki/Crypt_(Light's_Hope_Chapel)",
		},
		["crypt of remembrance"] = {
			name = "Crypt of Remembrance",
			short = "The Crypt of Remembrance is a crypt located in southern Havenshire, south of the Havenshire Farms and just north of New Avalon's wall.",
			full = "The Crypt of Remembrance is a crypt located in southern Havenshire, south of the Havenshire Farms and just north of New Avalon's wall. In the Scarlet Enclave, Baron Rivendare and Prince Keleseth - Scourge bosses in Stratholme and Utgarde Keep, respectively - give quests to starting death knight players here. In Phase 2 of the Scarlet Enclave, they have overtaken the crypt and established themselves, Crypt Guardians, and Fineous, a vendor. It changes throughout the phases of the Scarlet Enclave. It is most active during the Second Phase.\n\nAfter the death knight starting zone is complete, the Crypt of Remembrance is thereafter known simply as \"Crypt\".",
			source = "https://warcraft.wiki.gg/wiki/Crypt_of_Remembrance",
		},
		["darrowshire"] = {
			name = "Darrowshire",
			short = "Darrowshire is a village located in the southern part of what is now the Eastern Plaguelands.",
			full = "Darrowshire is a village located in the southern part of what is now the Eastern Plaguelands. During the Third War, Darrowshire came under attack by a Scourge force led by the ghoul lord Horgus the Ravager and the death knight Marduk Blackpool. Though the defenders of Darrowshire made headway at first, the defenders were eventually slaughtered.\n\nToday, Darrowshire is silent, and remains in ruins, a place where only ghosts and memories remain. Those defenders who fell now litter the Plaguelands as ghouls in the service of the Scourge, their spirits trapped in their rotting corpses. Very rarely in Darrowshire an event can be seen where the Battle of Darrowshire is re-enacted by ghosts and undead.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["darrowshire hunting grounds"] = {
			name = "Darrowshire Hunting Grounds",
			short = "The Darrowshire Hunting Grounds is a contested subzone of the Eastern Plaguelands zone.",
			full = "The Darrowshire Hunting Grounds is a contested subzone of the Eastern Plaguelands zone.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire_Hunting_Grounds",
		},
		["death cultist base camp"] = {
			name = "Death Cultist Base Camp",
			short = "The Death Cultist Base Camp is a Scourge-controlled subzone of the Eastern Plaguelands. It's located west of Tyr's Hand and has its own plague cauldron, which Betina Bigglezink wanted disturbed with her mixture.",
			full = "The Death Cultist Base Camp is a Scourge-controlled subzone of the Eastern Plaguelands. It's located west of Tyr's Hand and has its own plague cauldron, which Betina Bigglezink wanted disturbed with her mixture.",
			source = "https://warcraft.wiki.gg/wiki/Death_Cultist_Base_Camp",
		},
		["deaths breach"] = {
			name = "Death's Breach",
			short = "Death's Breach is a plateau below Acherus: The Ebon Hold in the Eastern Plaguelands, to the west of Havenshire. It can be accessed directly by going through the cave in the Noxious Glade.",
			full = "Death's Breach is a plateau below Acherus: The Ebon Hold in the Eastern Plaguelands, to the west of Havenshire. It can be accessed directly by going through the cave in the Noxious Glade. Ebon Hold can be access the by taking the teleporter located in the northern part of the breach, directly east from the tunnel to the Noxious Glade. A ramp on each side of the plateau leads down into the Ruins of the Scarlet Enclave. Death's Breach changes throughout the Phases of the Scarlet Enclave.",
			source = "https://warcraft.wiki.gg/wiki/Death's_Breach",
		},
		["deaths step"] = {
			name = "Death's Step",
			short = "Death's Step is a small enclosure mostly surrounded by trees, located directly west of the Undercroft in the Eastern Plaguelands, near the shore of Darrowmere Lake.",
			full = "Death's Step is a small enclosure mostly surrounded by trees, located directly west of the Undercroft in the Eastern Plaguelands, near the shore of Darrowmere Lake. There are several groups of three mobs, consisting of Death's Step Putrifier and Death's Step Miscreation.\n\nIt is also where adventurers first meet Tarenar Sunstrike.",
			source = "https://warcraft.wiki.gg/wiki/Death's_Step",
		},
		["eastwall gate"] = {
			name = "Eastwall Gate",
			short = "Eastwall Gate is the side entrance to the city of Stratholme, located in the Eastern Plaguelands. The Eastwall Gate enters directly into the Elder's Square near the Alonsus Chapel where Aurius resides.",
			full = "Eastwall Gate is the side entrance to the city of Stratholme, located in the Eastern Plaguelands. The Eastwall Gate enters directly into the Elder's Square near the Alonsus Chapel where Aurius resides.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Eastwall Tower",
			short = "Eastwall Tower is a scout tower located in the Eastern Plaguelands. During the Scourge invasion of Lordaeron, Eastwall Tower was destroyed and left in ruins.",
			full = "Eastwall Tower is a scout tower located in the Eastern Plaguelands. During the Scourge invasion of Lordaeron, Eastwall Tower was destroyed and left in ruins. Later it became a battleground as it was one of the fallen towers that the Alliance and Horde fought over for in order to fortify themselves in Lordaeron. The Eastwall Tower, along with all the other towers of the Eastern Plaguelands, have been rebuilt by the Argent Crusade and are currently being used as outposts throughout the region. Like the nearby Light's Hope Chapel, there are signs of life around the tower, and there is also a neutral flight master. The PvP component has been removed.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Fungal Vale",
			short = "The Fungal Vale is one of the most corrupted areas of the Eastern Plaguelands, where the Plague of Undeath has taken a strong hold over the land.",
			full = "The Fungal Vale is one of the most corrupted areas of the Eastern Plaguelands, where the Plague of Undeath has taken a strong hold over the land. The ground is a dark purple and the Vale is filled with a murky haze. The Fungal Vale is infested with members of the Scourge and the Cult of the Damned, at levels 40-41. The Vale is found north of the Marris Stead and Crown Guard Tower.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["hall of arms tyrs hand"] = {
			name = "Hall of Arms (Tyr's Hand)",
			short = "The Hall of Arms wing of Tyr's Hand Abbey, located in Tyr's Hand in the Eastern Plaguelands, was home to numerous militant members of the Scarlet Crusade.",
			full = "The Hall of Arms wing of Tyr's Hand Abbey, located in Tyr's Hand in the Eastern Plaguelands, was home to numerous militant members of the Scarlet Crusade. It is situated south of the Main Hall, and the Library Wing lies on the opposite side of the abbey. The Hall of Arms points towards the east and only slightly north.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Arms_(Tyr's_Hand)",
		},
		["infectis scar"] = {
			name = "Infectis Scar",
			short = "The Infectis Scar is a deep lake in the blighted earth of the Eastern Plaguelands. Unlike the Pestilent Scar, which was a natural gorge, the Infectis Scar on the other hand is the result of dark magic.",
			full = "The Infectis Scar is a deep lake in the blighted earth of the Eastern Plaguelands. Unlike the Pestilent Scar, which was a natural gorge, the Infectis Scar on the other hand is the result of dark magic. When his runesword was broken against the shield of a dwarf captain near Corin's Crossing, the death knight Marduk Blackpool discarded the blade and kept the hilt with him. The evil blade sunk into the earth creating a chasm.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["ixlars domain"] = {
			name = "Ix'lar's Domain",
			short = "Ix'lar's Domain is a small encampment of the Scourge remnant in Lordaeron, located north of Eastwall Tower in the Eastern Plaguelands.",
			full = "Ix'lar's Domain is a small encampment of the Scourge remnant in Lordaeron, located north of Eastwall Tower in the Eastern Plaguelands. They are ruled by Ix'lar the Underlord, a crypt lord who fancies himself the next leader of the Scourge.",
			source = "https://warcraft.wiki.gg/wiki/Ix'lar's_Domain",
		},
		["lake mereldar"] = {
			name = "Lake Mereldar",
			short = "Lake Mereldar is a large lake located south of Corin's Crossing in the Eastern Plaguelands. The polluted body of water is infested by corrupted water elementals.",
			full = "Lake Mereldar is a large lake located south of Corin's Crossing in the Eastern Plaguelands. The polluted body of water is infested by corrupted water elementals.\n\nThere are ruins of an old house nearby and a shack and ferry that belonged to the farm.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["library wing tyrs hand"] = {
			name = "Library Wing (Tyr's Hand)",
			short = "The Library Wing of Tyr's Hand Abbey, located in Tyr's Hand in the Eastern Plaguelands.",
			full = "The Library Wing of Tyr's Hand Abbey, located in Tyr's Hand in the Eastern Plaguelands. It was home to numerous members of the Scarlet Crusade who sought knowledge and enlightenment in the tomes of religious propaganda and insanity that can be found here. It is situated south of the Main Hall, and the Hall of Arms lies on the opposite side of the abbey. The library wing points towards the north, and was noted for the Basin of Holy Water on a table in the back room; which was required for the third quest in the Blood Knight epic mount quest chain.",
			source = "https://warcraft.wiki.gg/wiki/Library_Wing_(Tyr's_Hand)",
		},
		["lights hope chapel"] = {
			name = "Light's Hope Chapel",
			short = "Light's Hope Chapel is the Argent Crusade base of operations in the Eastern Plaguelands, and a place of comfort for those who make the journey here.",
			full = "Light's Hope Chapel is the Argent Crusade base of operations in the Eastern Plaguelands, and a place of comfort for those who make the journey here. Located on the slopes of a mountainous area east of the region, it was originally a mere chapel of the Church of the Holy Light, until it expanded into a full-fledged fortified outpost after the end of the Scourgewar. Underneath is the Sanctum of Light, catacombs which house the remains of the heroes of Lordaeron. Many were exhumed from around Lordaeron and moved to here so they could not be resurrected in the service of the Lich King.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["lights shield tower"] = {
			name = "Light's Shield Tower",
			short = "The Light's Shield Tower is a new scout tower near Corin's Crossing in the Eastern Plaguelands. It was constructed by the Argent Crusade and offers quests and a neutral flight path.",
			full = "The Light's Shield Tower is a new scout tower near Corin's Crossing in the Eastern Plaguelands. It was constructed by the Argent Crusade and offers quests and a neutral flight path.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Shield_Tower",
		},
		["main hall tyrs hand"] = {
			name = "Main Hall (Tyr's Hand)",
			short = "The Main Hall of Tyr's Hand Abbey, located in Tyr's Hand in the Eastern Plaguelands, is the part of the abbey through which all access to the tower, Hall of Arms, and Library Wing is done.",
			full = "The Main Hall of Tyr's Hand Abbey, located in Tyr's Hand in the Eastern Plaguelands, is the part of the abbey through which all access to the tower, Hall of Arms, and Library Wing is done. It was heavily patrolled by the Scarlet Crusade.",
			source = "https://warcraft.wiki.gg/wiki/Main_Hall_(Tyr's_Hand)",
		},
		["marris stead"] = {
			name = "Marris Stead",
			short = "The Marris Stead is located atop a small ridge in the southwestern area of the Eastern Plaguelands.",
			full = "The Marris Stead is located atop a small ridge in the southwestern area of the Eastern Plaguelands. It is found along the region's main road, not far from the border with the Western Plaguelands, and due west of the Crown Guard Tower.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "Mazra'Alor is the large ziggurat located at the heart of Zul'Mashar in the Eastern Plaguelands. It is populated by several forest troll shadow hunters of the Mossflayer tribe.",
			full = "Mazra'Alor is the large ziggurat located at the heart of Zul'Mashar in the Eastern Plaguelands. It is populated by several forest troll shadow hunters of the Mossflayer tribe.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Northdale",
			short = "Northdale is a destroyed town located north of Light's Hope Chapel and southeast of the entrance to Quel'Thalas in the Eastern Plaguelands.",
			full = "Northdale is a destroyed town located north of Light's Hope Chapel and southeast of the entrance to Quel'Thalas in the Eastern Plaguelands. It is where Taelan Fordring renounced the Order of the Silver Hand and joined the Scarlet Crusade. The ruins are inhabited by banshees and invisible eyeless watchers, while the nearby lake is populated by corrupted water elementals.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Northpass Tower",
			short = "Northpass Tower is a scout tower located in the Eastern Plaguelands. It is, as the name implies, the farthest north of the towers, lying along the road to the Ghostlands in Quel'Thalas.",
			full = "Northpass Tower is a scout tower located in the Eastern Plaguelands. It is, as the name implies, the farthest north of the towers, lying along the road to the Ghostlands in Quel'Thalas. During the Scourge invasion of Lordaeron, Northpass Tower was destroyed and left in ruins. Later it became a battleground as it was one of the fallen towers that the Alliance and Horde fought over for in order to fortify themselves in Lordaeron. Northpass Tower, along with all the other towers of the Eastern Plaguelands, have since been rebuilt by the Argent Crusade and is being used as an outpost for the region. Like the nearby Light's Hope Chapel, there are signs of life around the tower, and there is also a neutral flight master.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "Noxious Glade",
			short = "The Noxious Glade is a secluded glade found in the Eastern Plaguelands just north of Light's Hope Chapel up a hill.",
			full = "The Noxious Glade is a secluded glade found in the Eastern Plaguelands just north of Light's Hope Chapel up a hill. The glade suffers from the blight of the Scourge and is even more tainted than the surrounding Plaguelands. The air of the glade is a thick, sickly green and the ground is a dark purple. A plague cauldron, a slaughterhouse and a few ziggurats are found within the glade, as well as several Scourge mobs. The glade is connected to Death's Breach through a tunnel named the Noxious Pass, although the area is only named in the Plaguelands: The Scarlet Enclave.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Pestilent Scar",
			short = "The Pestilent Scar is a deep lake in the blighted earth of the Eastern Plaguelands.",
			full = "The Pestilent Scar is a deep lake in the blighted earth of the Eastern Plaguelands. Unlike the Infectis Scar, however, the Pestilent Scar appears to be a natural gorge, possibly a lake that dried up after the Plague of Undeath struck. The Pestilent Scar was flooded to the rim, though still it is home to the oozes. A series of bridges constructed by the Argent Crusade serve as crossing points.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Plaguewood",
			short = "The Plaguewood is a large area directly south of Stratholme and stretching all the way to Terrordale within the Eastern Plaguelands.",
			full = "The Plaguewood is a large area directly south of Stratholme and stretching all the way to Terrordale within the Eastern Plaguelands. It is heavily occupied by the Scourge and contains large amounts of infrastructure, including ziggurats and slaughterhouses.\n\nDespite (or perhaps because of) the prevalence of the Scourge, representatives of the Scarlet Crusade routinely patrol the road leading to and from Stratholme. They attack any undead that they encounter -- as well as any other travelers that these fanatics chance upon. All those journeying along the forest's road should be on the lookout for them, as they present as much of a danger as the ravening Scourge.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["plaguewood tower"] = {
			name = "Plaguewood Tower",
			short = "Plaguewood Tower is a scout tower located in the Plaguewood of the Eastern Plaguelands, very close to the nearby Terrordale. During the Scourge invasion of Lordaeron, the tower was probably destroyed and left in ruins.",
			full = "Plaguewood Tower is a scout tower located in the Plaguewood of the Eastern Plaguelands, very close to the nearby Terrordale. During the Scourge invasion of Lordaeron, the tower was probably destroyed and left in ruins. It later became a battleground as it was one of the fallen towers that the Alliance and Horde fought over in order to fortify themselves in the region.\n\nLike Light's Hope Chapel, there are signs of life around the tower, and there is also a neutral flight master.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood_Tower",
		},
		["quellithien lodge"] = {
			name = "Quel'Lithien Lodge",
			short = "Not to be confused with Quel'Danil Lodge in Hinterlands.",
			full = "Not to be confused with Quel'Danil Lodge in Hinterlands.\n\nQuel'Lithien Lodge is a high elven hunting lodge near the entrance to Quel'Thalas. It was one of two major concentrations of high elves in Lordaeron.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["ruins of the scarlet enclave"] = {
			name = "Ruins of the Scarlet Enclave",
			short = "The Ruins of the Scarlet Enclave is the combined region around the towns of New Avalon and Havenshire, which were destroyed by the Scourge (with the aid of death knight player characters).",
			full = "The Ruins of the Scarlet Enclave is the combined region around the towns of New Avalon and Havenshire, which were destroyed by the Scourge (with the aid of death knight player characters). The Enclave is accessible by going through Tyr's Hand or the cave between the Noxious Glade and Death's Breach.\n\nThroughout the ruins, the banner of the Knights of the Ebon Blade (rather than that of the Scourge) can be seen in certain areas, such as the courtyard of New Avalon and outside the ruined Scarlet Hold. The ruins of these last human settlements in the Eastern Plaguelands serve only as a sad reminder of what the Scourge can do to its enemies. The Havenshire Farms contains a plague cauldron put in place by one of them, and it has turned what used to be pumpkins into hideous mounds of unnatural flora that look like they are breathing. The trees, already dying before the coming of Acherus, are rotting away, some of them already mutating. King's Harbor is deserted, the last ship having left shortly before the massacre of almost the entire Scarlet Crusade. Some ruined buildings still contain a cozy fire, only reinforcing how recently the Scarlet refuge was ended. Corpses still litter the ground in the ruins of New Avalon and Havenshire, and Death's Breach rises above the ruins at the north side, with Acherus still floating overhead, and the banner of the Ebon Blade placed all over the campsites. The whole area is covered in a veil of reddish-orange smog, like the majority of Eastern Plaguelands.\n\nThere is nothing to do except view the ruins of New Avalon, Havenshire and the surrounding areas before the city of Tyr's Hand.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_the_Scarlet_Enclave",
		},
		["sanctum of light"] = {
			name = "Sanctum of Light",
			short = "The Sanctum of Light, also known as Light's Hope Sanctum, is a secret hall located beneath Light's Hope Chapel.",
			full = "The Sanctum of Light, also known as Light's Hope Sanctum, is a secret hall located beneath Light's Hope Chapel. It is a catacomb that houses the remains of a thousand heroes of Lordaeron, which are those of warriors, priests, paladins, and champions of battles long past. It serves as the Order Hall for paladins, and as the headquarters of the Knights of the Silver Hand, led by their new Highlord since the death of Tirion Fordring.",
			source = "https://warcraft.wiki.gg/wiki/Sanctum_of_Light",
		},
		["scarlet base camp"] = {
			name = "Scarlet Base Camp",
			short = "The Scarlet Base Camp is a small barricaded fortification located on the east banks of Lake Mereldar, not far from the religious bastion of Tyr's Hand.",
			full = "The Scarlet Base Camp is a small barricaded fortification located on the east banks of Lake Mereldar, not far from the religious bastion of Tyr's Hand.\n\nThe subject of this section is unique to the World of Warcraft Classic: Season of Discovery.\n\nThe area was reinforced and contains the entrance to the Scarlet Enclave.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "Scarlet Basilica",
			short = "The Scarlet Basilica is a large cathedral located inside Tyr's Hand in the Eastern Plaguelands.",
			full = "The Scarlet Basilica is a large cathedral located inside Tyr's Hand in the Eastern Plaguelands. It is the high seat of religious power for the Scarlet Crusade and has close ties to Tyr's Hand Abbey nearby as well as the Scarlet Monastery much further west in Tirisfal Glades. It is the location of Crusader Lord Valdelmar.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["siege vise"] = {
			name = "Siege Vise",
			short = "The Siege Vise is a contested subzone of the Eastern Plaguelands zone. The undead Scourge have set up a small siege camp near the gateway to Quel'Thalas.",
			full = "The Siege Vise is a contested subzone of the Eastern Plaguelands zone. The undead Scourge have set up a small siege camp near the gateway to Quel'Thalas. Scourge Siege Engineers are found around here, along with many meat wagons.",
			source = "https://warcraft.wiki.gg/wiki/Siege_Vise",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "Stratholme (or Stratholme City) was the northernmost and second-most populous city of the kingdom of Lordaeron. It was here that the Order of the Silver Hand was founded prior to the Second War.",
			full = "Stratholme (or Stratholme City) was the northernmost and second-most populous city of the kingdom of Lordaeron. It was here that the Order of the Silver Hand was founded prior to the Second War. Years later, the port city was plagued by the Cult of the Damned, using infected grain from Andorhal, and its population was ultimately purged by the mad Prince Arthas Menethil. In the aftermath, Stratholme became the Scourge's capital in Lordaeron after the undead moved in, and is still burning to this day.\n\nThe city included many well-known buildings, from the glorious Bastion of the Silver Hand to Ezra Grimm's famous tobacco shop.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["stratholme classic"] = {
			name = "Stratholme",
			short = "The city of Stratholme (pronounced ˈstrathːhɔlm or STRATH-olm) was the northernmost and second most populous city of the kingdom of Lordaeron, and is the city where the Order of the Silver Hand was founded.",
			full = "The city of Stratholme (pronounced ˈstrathːhɔlm or STRATH-olm) was the northernmost and second most populous city of the kingdom of Lordaeron, and is the city where the Order of the Silver Hand was founded. Today, Stratholme is the Scourge's capital in Lordaeron. The mad Prince Arthas ravaged Stratholme in the Third War and the undead moved in soon after. Stratholme burns to this day, and its districts have been split between the overzealous Scarlet Crusade led by Grand Crusader Dathrohan, and the Scourge forces led by the death knight Baron Rivendare.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme_(Classic)",
		},
		["stratholme main gate"] = {
			name = "Stratholme Main Gate",
			short = "The city of Stratholme (pronounced ˈstrathːhɔlm) was the northernmost and second most populous city of the kingdom of Lordaeron, and is the city where the Order of the Silver Hand was founded.",
			full = "The city of Stratholme (pronounced ˈstrathːhɔlm) was the northernmost and second most populous city of the kingdom of Lordaeron, and is the city where the Order of the Silver Hand was founded. Today, Stratholme is the Scourge's capital in Lordaeron. The mad Prince Arthas ravaged Stratholme in the Third War and the undead moved in soon after. Stratholme burns to this day.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme_Main_Gate",
		},
		["stratholme service entrance"] = {
			name = "Stratholme Service Entrance",
			short = "The city of Stratholme was the northernmost and second most populous city of the kingdom of Lordaeron, and is the city where the Order of the Silver Hand was founded.",
			full = "The city of Stratholme was the northernmost and second most populous city of the kingdom of Lordaeron, and is the city where the Order of the Silver Hand was founded. Today, Stratholme is the Scourge's capital in Lordaeron. The mad Prince Arthas ravaged Stratholme in the Third War and the undead moved in soon after. Stratholme burns to this day.\n\nThe service entrace is found at Eastwall Gate.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme_Service_Entrance",
		},
		["terrordale"] = {
			name = "Terrordale",
			short = "Terrordale is a small town nestled in the northwest corner of Eastern Plaguelands.",
			full = "Terrordale is a small town nestled in the northwest corner of Eastern Plaguelands. Because it lies on the edge of the Plaguewood, the area is a ghost town, inhabited only by Scourge and plagued animals, with the exception of the merchant Augustus the Touched and the ghost hunter Egan. Just east of Terrordale lies the Argent Crusade-controlled Plaguewood Tower, and just north lies an entrance to the crypt fiend-infested Terrorweb Tunnel, which leads to the banks of the Thondroril River.\n\nTerrordale was previously haunted by Terrordale Spirits, with parts of the town being spots of a special spiritual disturbance where \"the physical world buckle[d] under the torment of the spirit realm\". Lord Grayson Shadowbreaker sent paladin adventurers to exorcise the spirits in order to demonstrate judgment and sacrifice, as part of the preparation to acquire their chargers.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Terrorweb Tunnel",
			short = "Terrorweb Tunnel is a long and winding tunnel into the mountain northwest of Terrordale.",
			full = "Terrorweb Tunnel is a long and winding tunnel into the mountain northwest of Terrordale. It is full of crypt fiends (nerubians), and stretches through the mountain from Terrordale in the north and extends south to the Thondroril River. Tirion Fordring was located at the entrance from the river. One must be very careful when traveling this path, as not only is this path crowded with many Crypt Fiends, but occasionally a very powerful and elite member of its kind, the Nerubian Overseer, stalks the tunnel.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thalassian pass"] = {
			name = "Thalassian Pass",
			short = "The Thalassian Pass is the passage through the mountains south from Quel'Thalas to the Eastern Plaguelands, and is located in the far southern Ghostlands.",
			full = "The Thalassian Pass is the passage through the mountains south from Quel'Thalas to the Eastern Plaguelands, and is located in the far southern Ghostlands.\n\nThe large gatehouse near the portal is believed to be one of the elfgates gates that sealed off Quel'Thalas from Lordaeron. The gates are flanked by Scourge banners -- possibly placed when the Scourge snuck through Quel'Thalas' defenses, aided by the traitor Dar'Khan Drathir -- and for a time, the blood elves were too disheartened by the Fall to remove them.\n\nWith much of the Ghostlands healed and spirits heightened among the sin'dorei, the banners of the Scourge were torn down and replaced with the heraldry of Quel'Thalas. As of Xal'atath's attack on the Isle of Quel'Danas, the area was rumored to be one of the most uneventful posts, and Bloodguard Nelric stood guard there.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Pass",
		},
		["thondroril river"] = {
			name = "Thondroril River",
			short = "The Thondroril River forms a natural boundary between the Western and Eastern Plaguelands.",
			full = "The Thondroril River forms a natural boundary between the Western and Eastern Plaguelands. The spring of this river is located in the current closed area known as Northern Lordaeron and runs from near the Terrorweb Tunnel to the north and empties out into Darrowmere Lake to the south. South of the lake it becomes the Darrowmere River.\n\nAlong the river on on both sides, you can find maggots, vampire bats, plaguebears, spiders and later snapjaws.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Tyr's Hand",
			short = "Tyr's Hand is a fortified human city and was one of the last holdouts of the living against the Scourge in the region.",
			full = "Tyr's Hand is a fortified human city and was one of the last holdouts of the living against the Scourge in the region. Located in the southeast of the Eastern Plaguelands, its surroundings are in a much better condition than the rest of the Plaguelands, although the trees and other flora are decaying.\n\nSubsequently, the Brotherhood of the Light defeated the undead forces within Tyr's Hand and took control of the city.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["tyrs hand abbey"] = {
			name = "Tyr's Hand Abbey",
			short = "Tyr's Hand Abbey is the smaller of the two religious facilities at Tyr's Hand, the larger being the Scarlet Basilica.",
			full = "Tyr's Hand Abbey is the smaller of the two religious facilities at Tyr's Hand, the larger being the Scarlet Basilica. The abbey is well tended for, and has different function for the religious Scarlet Crusade than the basilica does. It is built very much like Northshire Abbey, comprised of three sections named the Main Hall, the Hall of Arms, and the Library Wing.\n\nBlood Knights who sought to obtain the rank of Master and ride the Thalassian charger had to enter the Abbey, obtain a vial of its holy water and bring it back to Lord Solanar Bloodwrath in Silvermoon City.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand_Abbey",
		},
		["undercroft"] = {
			name = "Undercroft",
			short = "The Undercroft is a crypt in the southwestern region of the Eastern Plaguelands. It is home to a band of undead trolls who are led by the undead dire troll Zaeldarr the Outcast.",
			full = "The Undercroft is a crypt in the southwestern region of the Eastern Plaguelands. It is home to a band of undead trolls who are led by the undead dire troll Zaeldarr the Outcast. He leads occasional raids on the Argent Dawn's base at Light's Hope Chapel to steal bodies from their grave pit. It is also the location of Tirion Fordring's ersatz grave.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Zul'Mashar is located in the northeastern part of the Eastern Plaguelands.",
			full = "Zul'Mashar is located in the northeastern part of the Eastern Plaguelands. It was once the capital of the Mossflayer tribe, a small tribe of forest trolls, but the long arduous fighting with the humans of Lordaeron have caused the trolls' land to fall into disarray. Although they retook parts of the land, the coming of the plague of undeath wrought more destruction upon the land itself, and today Zul'Mashar is a shadow of its former glory. Currently, it is in danger of becoming a bastion for the undead as its own people are being covertly transformed. Zul'Mashar contains the troll ziggurat Mazra'Alor, and is home to Warlord Thresh'jin and Zul'Brin Warpbranch.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Hillsbrad Foothills: 38 subzones
	[1424] = {
		["alterac mountains"] = {
			name = "Alterac Mountains",
			short = "Alterac Mountains is the location of the former nation of Alterac and the city-state of Dalaran, and its chief settlements included Alterac City, Dalaran and Strahnbrad.",
			full = "Alterac Mountains is the location of the former nation of Alterac and the city-state of Dalaran, and its chief settlements included Alterac City, Dalaran and Strahnbrad. The central mountains have been overrun by ogres, while the organization called the Syndicate controls Strahnbrad and other areas. Dalaran was enclosed within an impregnable magic shell before the city was lifted in the air and moved to Northrend. A high, wooded region, the Alterac Mountains see much rainfall and its skies are constantly overcast. Crushridge ogres and the Syndicate, a wicked group of rogues led by fallen human nobles, clash repeatedly for control of this land.",
			source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
		},
		["azurelode mine"] = {
			name = "Azurelode Mine",
			short = "The Azurelode Mine is a mine in southwestern Hillsbrad Foothills, south of Hillsbrad Fields and west of what was once Southshore.",
			full = "The Azurelode Mine is a mine in southwestern Hillsbrad Foothills, south of Hillsbrad Fields and west of what was once Southshore.\n\nBefore the Greymane Wall was built, Azurelode Mine and its surrounding hill were a part of Gilneas.\n\nThis section concerns content related to the original World of Warcraft.\n\nDuring the time of the Battle for Hillsbrad, it was an Alliance-controlled mine. It was a home to miners under Foreman Bonds from Hillsbrad Fields, and had guards to protects the miners. It supplied iron to Alliance armories.\n\nThe remaining humans (Hillsbrad Sentry, Hillsbrad Foreman and Hillsbrad Miners) which were not able to escape in time have been paralyzed by the spiders' Paralytic Poison. These humans are being saved until they're needed at the Sludge Fields to the north. Unfortunately, Dumass has also fallen prey to the spiders and must be rescued.\n\nThe Domesticated Mine Creepers, which have not been fed for days, have begun sampling the humans and refuse commands to stop. The Forsaken can't feed them at the moment due to their \"supplies\" being stolen by the nearby murlocs, but they also can't leave to gather new supplies as they're afraid the same murlocs will take over the mine as soon as they leave.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["brazie farmstead"] = {
			name = "Brazie Farmstead",
			short = "The Brazie Farmstead is a residence that has been erected on the former location of the Lordamere Internment Camp.",
			full = "The Brazie Farmstead is a residence that has been erected on the former location of the Lordamere Internment Camp. Brazie the Botanist resides here, and he requests the assistance of adventurers in defending his farm from attacks by Warden Stillwater of the nearby Sludge Fields.",
			source = "https://warcraft.wiki.gg/wiki/Brazie_Farmstead",
		},
		["chillwind point"] = {
			name = "Chillwind Point",
			short = "Chillwind Point is a small rise on the far eastern edge of the Alterac Mountains region.",
			full = "Chillwind Point is a small rise on the far eastern edge of the Alterac Mountains region. It is dominated by a small, ancient troll ruin and named for the chill winds that sweep through the nearby ravine from the Western Plaguelands to the north. This pass was previously part of the kingdom of Lordaeron.\n\nBath'rah the Windwatcher, a friendly jungle troll, resides here.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Corrahn's Dagger",
			short = "Corrahn's Dagger is the second of the four fingers of Hillsbrad. It is here the Stormpike clan have made their forward base camp for the assault they plan on the Forsaken.",
			full = "Corrahn's Dagger is the second of the four fingers of Hillsbrad. It is here the Stormpike clan have made their forward base camp for the assault they plan on the Forsaken. Captain Iceheart leads the troops here.\n\nPrior to this, the Syndicate held the hill.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Crushridge Hold",
			short = "Crushridge Hold is an ogre mound near the Ruins of Alterac of the Alterac Mountains. The cave and nearby encampments house a large number of Crushridge ogres.",
			full = "Crushridge Hold is an ogre mound near the Ruins of Alterac of the Alterac Mountains. The cave and nearby encampments house a large number of Crushridge ogres.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["dalaran crater"] = {
			name = "Dalaran Crater",
			short = "Dalaran Crater is an area in the Hillsbrad Foothills located at the west end, on the shores of Lordamere Lake. It is north of Brazie Farmstead, the former Lordamere Internment Camp, and just east of Silverpine.",
			full = "Dalaran Crater is an area in the Hillsbrad Foothills located at the west end, on the shores of Lordamere Lake. It is north of Brazie Farmstead, the former Lordamere Internment Camp, and just east of Silverpine. It is a massive crater where the city of Dalaran once stood, which was destroyed during the Third War. The region was once patrolled by Dalaran wizards and their rock elemental minions, who were leveled in their mid-thirties. The NPCs that remain around the crater are friendly to the Alliance and hostile to the Horde. The camp was led by Archmage Ansirem Runeweaver.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran_Crater",
		},
		["dandreds fold"] = {
			name = "Dandred's Fold",
			short = "Dandred's Fold is a small farm and manor on the westernmost side of the Uplands, in northwestern Alterac Mountains. Since it has a harbor on Lordamere Lake, it is also on the Misty Shore.",
			full = "Dandred's Fold is a small farm and manor on the westernmost side of the Uplands, in northwestern Alterac Mountains. Since it has a harbor on Lordamere Lake, it is also on the Misty Shore.\n\nHorde adventurers were sent here to retrieve the necklace that had once belonged to Taretha Foxton, and end Aliden's life. After killing him, Aliden's mistress Elysa gave them the necklace, which she was wearing, in fear they would also harm her.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["darrow hill"] = {
			name = "Darrow Hill",
			short = "Darrow Hill is an area in the northern part of the Hillsbrad Foothills, right under the Headland.",
			full = "Darrow Hill is an area in the northern part of the Hillsbrad Foothills, right under the Headland. Mountain lions and stags roam its fields, and yetis inhabit the Foothill Caverns. [Alterac Granite] can be found within the cave found here. This area is a prime griefing spot for both factions.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok was a dwarven keep nestled into the southeastern hills of the Hillsbrad Foothills. Led by Captain Ironhill, the dwarves helped protect the humans of Hillsbrad as well as the Azurelode Mine.",
			full = "Dun Garok was a dwarven keep nestled into the southeastern hills of the Hillsbrad Foothills. Led by Captain Ironhill, the dwarves helped protect the humans of Hillsbrad as well as the Azurelode Mine. The Forsaken loathed the presence of these dwarves and once offered several quests for Horde adventurers to infiltrate Dun Garok and kill the dwarves within.\n\nThe Forsaken, outnumbering the dwarves ten-to-one, assaulted them with all their might. The dwarves fought until the bitter end, but every last one of them died in defense of Dun Garok.\n\nThe dwarves who fell in battle rose again as Dun Garok Spirits and now haunt the land, refusing to yield it even in death. The Forsaken eventually gave up on trying to inhabit the fortress and let the dead spirits keep their land.\n\nThe ghost of Captain Ironhill has remained in Dun Garok, not for vengeance, but out of sadness for his people that have remained. He tasks Horde adventurers to release their spirits from the place. Additionally, the ghost of Tamra Stormpike can occasionally be found in the main quarters, seething with hatred.\n\nSome time later, the Forsaken finally took over Dun Garok by controlling the ghosts. Meanwhile, troops from Ironforge marched to purge the Forsaken and the ghosts, and to retake the fortress. Jezelle Pruitt and Brandur Ironhammer‎ were encountered here, by the Alliance and Horde respectively.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Durnholde Keep",
			short = "Durnholde Keep is a ruined stronghold located east of the town of Tarren Mill in the Hillsbrad Foothills. It used to be an internment camp and prison for the orcs.",
			full = "Durnholde Keep is a ruined stronghold located east of the town of Tarren Mill in the Hillsbrad Foothills. It used to be an internment camp and prison for the orcs.\n\nAlong with its inner barracks, Durnholde also had a mage tower and an arena.\n\nThe small village that encircled Durnholde was inhabited by those who made their living off tending to the needs of the fortress's inhabitants.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Eastern Strand",
			short = "The Eastern Strand is a stretch of coastline in the southeast of Hillsbrad Foothills, complementary to the Western Strand further to the west.",
			full = "The Eastern Strand is a stretch of coastline in the southeast of Hillsbrad Foothills, complementary to the Western Strand further to the west. The Eastern Strand is home to the Daggerspine naga who are found on the beaches and in the water.\n\nKilling one will drop [Daggerspine Attack Plans], which starts the quest [7-30] Preemptive Strike.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["eastpoint tower"] = {
			name = "Eastpoint Tower",
			short = "Eastpoint Tower, located in Hillsbrad Foothills southwest of Durnholde Keep, was originally unnamed and guarded by the Syndicate.",
			full = "Eastpoint Tower, located in Hillsbrad Foothills southwest of Durnholde Keep, was originally unnamed and guarded by the Syndicate. The Forsaken now occupy the scout tower and it serves as a Horde quest hub, complete with a flight master and an innkeeper.\n\nThough primarily a Forsaken outpost, the tower contains two orcs, Drull and Tog'thar, who lie on couches next to one another. They will regularly interact with Nils Beerot, a \"psylosopher\". Nils Beerot is however a little paranoid and believes the nearby Rampaging Owlbeasts are planning to attack them.",
			source = "https://warcraft.wiki.gg/wiki/Eastpoint_Tower",
		},
		["gallows corner"] = {
			name = "Gallows' Corner",
			short = "Gallows' Corner is a crossroads in the Alterac Mountains, close to the Ruins of Alterac. This area is held by Crushridge ogres who patrol the area around the ruined scout tower.",
			full = "Gallows' Corner is a crossroads in the Alterac Mountains, close to the Ruins of Alterac. This area is held by Crushridge ogres who patrol the area around the ruined scout tower.\n\nNo quests take place here and this area no longer serves any purpose.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Gavin's Naze",
			short = "Gavin's Naze is the last of the four fingers of Hillsbrad and the most protected hill. It is here the Stormpike clan assembles their siege engines, to use against the Forsaken when the time is right.",
			full = "Gavin's Naze is the last of the four fingers of Hillsbrad and the most protected hill. It is here the Stormpike clan assembles their siege engines, to use against the Forsaken when the time is right.\n\nPrior to the dwarves taking the hill, Mountain Lions roamed the area, including the uniquely colored Araga.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Growless Cave",
			short = "Growless Cave is a cave in the Alterac Mountains that is home to mountain yeti. Occasionally Skhowl can be found just outside the entrance.",
			full = "Growless Cave is a cave in the Alterac Mountains that is home to mountain yeti. Occasionally Skhowl can be found just outside the entrance.\n\nInside the cave used to be the Flame of Uzel, a ceremonial pyre created by a human named Helcular, it was to be used in his ritual to become a lich. The powerful yeti Frostmaw used approach the cave if meat is burned upon the Flame of Uzel. However, the flame has since been removed.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "Headland",
			short = "The Headland is the third of the four fingers of Hillsbrad. It's here the Stormpike clan have built a training camp for their soldiers to prefect their fighting skills and learn new ones.",
			full = "The Headland is the third of the four fingers of Hillsbrad. It's here the Stormpike clan have built a training camp for their soldiers to prefect their fighting skills and learn new ones. The Alliance entrance to the Alterac Valley battleground is nearby.\n\nInstructor Rufus, Drill Sergeant Magnus, and Captain Crudbeard are found here training the trainees. While on the cliffside Araga and her many cubs rest.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Hillsbrad Fields",
			short = "The Hillsbrad Fields refers to the area which included the town of Hillsbrad and a large and fertile cultivated area that provided food for the people of Southshore and the whole of Hillsbrad Foothills.",
			full = "The Hillsbrad Fields refers to the area which included the town of Hillsbrad and a large and fertile cultivated area that provided food for the people of Southshore and the whole of Hillsbrad Foothills.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["hillsbrad subzone"] = {
			name = "Hillsbrad (subzone)",
			short = "Hillsbrad is the town hall found in western Hillsbrad Foothills. The area is surrounded by the Hillsbrad Fields.",
			full = "Hillsbrad is the town hall found in western Hillsbrad Foothills. The area is surrounded by the Hillsbrad Fields.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_(subzone)",
		},
		["lordamere lake"] = {
			name = "Lordamere Lake",
			short = "Lordamere Lake (or Lake Lordamere) is one of the largest lakes in the Eastern Kingdoms, rivaled only by Darrowmere Lake to the east.",
			full = "Lordamere Lake (or Lake Lordamere) is one of the largest lakes in the Eastern Kingdoms, rivaled only by Darrowmere Lake to the east. Along with Darrowmere, this lake has been marked by many events that took place around it. Here, many human kingdoms, at the age of the Alliance of Lordaeron, that were prosperous, have been found around the lake's shores and nearby mountains, including Lordaeron, Dalaran and Alterac. Lordamere was very likely given its name from the nearby Capital City of the kingdom of Lordaeron which was built on its northern shores and which was named after Lordain.\n\nSome time after the Third War, Lady Vashj and her naga retreated here after the battle at the ruins of Dalaran.\n\nThe lake, for a time, acted as a natural barrier between the Forsaken lands of Tirisfal Glades and Silverpine Forest and the contested lands of the Alterac Mountains. At its center lie the Dawning Isles, and Fenris Isle which was taken over by agents of the Scourge, who were being attacked by the Forsaken. However, they were ultimately removed by the worgen. Fenris Isle was later taken by Hillsbrad Refugees and the leaders of Southshore, having escaped from the Hillsbrad Foothills, as a temporary safe haven from the Forsaken. East of Fenris Isle, the small group of islands called the Dawning Isles are where the Vile Fin murlocs have made their claim overrunning them.\n\nAt some point, Fenris Isle, namely its keep, was overtaken by the Forsaken led by Deathstalker Hayward. The Horde later distracted these forces to evacuate Undercity refugees across the lake.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["misty shore"] = {
			name = "Misty Shore",
			short = "Misty Shore is a stretch of waterline along Lordamere Lake, running from Dandred's Fold to Dalaran Crater in the Hillsbrad Foothills.",
			full = "Misty Shore is a stretch of waterline along Lordamere Lake, running from Dandred's Fold to Dalaran Crater in the Hillsbrad Foothills. Aside from its rather large population of turtles, the shore once housed a pair of Scarlet Crusade-affiliated humans, who zealously attacked those who passed too close.\n\nIt is possible to view the Dawning Isles from the Misty Shore, with the eerie Fenris Keep in the distance.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Nethander Stead",
			short = "Nethander Stead is a farm just east of Southshore. It has been overrun by Mudsnout gnolls and is the only location in which gnolls of this tribe can be found.",
			full = "Nethander Stead is a farm just east of Southshore. It has been overrun by Mudsnout gnolls and is the only location in which gnolls of this tribe can be found. Giant white mushrooms called Mudsnout Blossoms grow in its abandoned fields. These mushrooms were once of particular interest to Apothecary Lydon in order to make a deadly brew, Elixir of Agony. Now Kingslayer Orkus wants them to save his mount.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Purgation Isle",
			short = "Purgation Isle is an island south of the shores of Hillsbrad Foothills, in a shape of a towering spiral. It contains a cemetery and a ruined scout tower.",
			full = "Purgation Isle is an island south of the shores of Hillsbrad Foothills, in a shape of a towering spiral. It contains a cemetery and a ruined scout tower.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Ravenholdt Manor",
			short = "Ravenholdt Manor is the headquarters for the Ravenholdt faction. It is the property of Lord Jorach Ravenholdt and has its own garden, supervised by Simone Cantrell, as well as a training arena, domain of Master Kang.",
			full = "Ravenholdt Manor is the headquarters for the Ravenholdt faction. It is the property of Lord Jorach Ravenholdt and has its own garden, supervised by Simone Cantrell, as well as a training arena, domain of Master Kang. Outsiders are not really welcome here.\n\nFor those having trouble finding the manor, there is a plateau slightly northwest of Durnholde Keep in Hillsbrad Foothills. At the back of this plateau, where it meets the mountains (the Alterac Mountains, incidentally), you should find a small path leading up into the mountains. This path twists back and forth, goes through a small cave, and then leads to Ravenholdt Manor. There is a chest that used to spawn Milton Beats if you open it.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["ruins of alterac"] = {
			name = "Ruins of Alterac",
			short = "The Ruins of Alterac (or Alterac Ruins) are what remains of the former Alterac City (or the Keep at Alterac) located in the Alterac Mountains.",
			full = "The Ruins of Alterac (or Alterac Ruins) are what remains of the former Alterac City (or the Keep at Alterac) located in the Alterac Mountains. The city was the capital city of the Kingdom of Alterac until it was attacked and put under martial law by King Terenas Menethil II and the Alliance of Lordaeron for their treason and pact with the Old Horde. Following the fall of the kingdom, the ruins became home to the Crushridge ogres who disputed the territories for years with the Syndicate. They were not contested by the Alliance but were spied on.\n\nBro'kin, a goblin alchemy supplier, can be found on top of the wall in the northern part of the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["ruins of southshore"] = {
			name = "Ruins of Southshore",
			short = "The Ruins of Southshore are all that remain of the human port town of Southshore, one of the last intact Alliance towns in Lordaeron.",
			full = "The Ruins of Southshore are all that remain of the human port town of Southshore, one of the last intact Alliance towns in Lordaeron.\n\nThe outskirts now serve as a quest hub for them, complete with a flight master, but the town itself is inhabited only by slimes. Blight Slimes, Angry Blight Slimes and a unique ooze named Chet the Slime-Breeder infest the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Southshore",
		},
		["slaughter hollow"] = {
			name = "Slaughter Hollow",
			short = "Slaughter Hollow is an ogre mound deep in the Alterac Mountains home to the Crushridge ogres.",
			full = "Slaughter Hollow is an ogre mound deep in the Alterac Mountains home to the Crushridge ogres.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["sludge fields"] = {
			name = "Sludge Fields",
			short = "The Sludge Fields is a Forsaken fortification built over the town of Hillsbrad Fields.",
			full = "The Sludge Fields is a Forsaken fortification built over the town of Hillsbrad Fields. It is an internment camp or prison where the captured humans of Lordaeron are sent for labor to work on the Lordaeron's largest sludge and mushroom plantation. It comprises of guard towers and searchlights, and there are also plague tanks present as well. Warden Stillwater resides and oversees here.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fields",
		},
		["sludgeguard tower"] = {
			name = "Sludgeguard Tower",
			short = "Sludgeguard Tower is a Forsaken guard tower of Hillsbrad Foothills located between the Sludge Fields and Dalaran Crater, adjacent the Brazie Farmstead.",
			full = "Sludgeguard Tower is a Forsaken guard tower of Hillsbrad Foothills located between the Sludge Fields and Dalaran Crater, adjacent the Brazie Farmstead.",
			source = "https://warcraft.wiki.gg/wiki/Sludgeguard_Tower",
		},
		["soferas naze"] = {
			name = "Sofera's Naze",
			short = "Sofera's Naze is one of the four fingers of Hillsbrad and where a small scouting camp was placed by the SI:7, which were recruited by the Stormpike clan.",
			full = "Sofera's Naze is one of the four fingers of Hillsbrad and where a small scouting camp was placed by the SI:7, which were recruited by the Stormpike clan.\n\nPrior to the SI:7 taking the area, the Syndicate held the hill.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint gate"] = {
			name = "Southpoint Gate",
			short = "Southpoint Gate (or Southpoint Blockade) is a Forsaken outpost in Hillsbrad Foothills, on the border with Silverpine Forest.",
			full = "Southpoint Gate (or Southpoint Blockade) is a Forsaken outpost in Hillsbrad Foothills, on the border with Silverpine Forest. Most notably this is where the adventurer for the first time becomes a quest giver dispensing out three quests for three different types of other \"heroes\".\n\nThe area surrounding the gate has been overrun by Domesticated Creepers, and Infested Bears now wander around with spider eggs on their backs.\n\nIt was built over the now-destroyed Southpoint Tower.\n\nHorde champions encountered Darius Crowley at the Sludge Fields, where he led a Gilnean army against Hillsbrad. Given that, in order to reach the Sludge Fields the Gilneans would have had to go through Southpoint Gate, it is unknown how the gate fared by the end of the war.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Gate",
		},
		["southpoint tower"] = {
			name = "Southpoint Tower",
			short = "Southpoint Tower was a ruined scout tower at the far west end of Hillsbrad Foothills, just south of the road to Silverpine Forest.",
			full = "Southpoint Tower was a ruined scout tower at the far west end of Hillsbrad Foothills, just south of the road to Silverpine Forest. The Forsaken Deathstalker Lesh was stationed there, spying on the Alliance activity in the area. Lesh was often killed by Alliance players because of her secluded position. This tower was not ruined in the instance, nor was the unnamed tower between Tarren Mill and Southshore. There was also a gate further down the road, blocking the road to Silverpine Forest. There is no sign of this gate in the overworld.\n\nAfter the Forsaken at last claimed victory in the Battle for Hillsbrad, Southpoint Tower was completely demolished and Southpoint Gate was erected in its place, leaving no trace of the former human structure.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["southshore town hall"] = {
			name = "Southshore Town Hall",
			short = "Magistrate Henry Maleb was Southshore's ruler, and held office in the building. Kundric Zanden was also here.",
			full = "Magistrate Henry Maleb was Southshore's ruler, and held office in the building. Kundric Zanden was also here.\n\nThe town hall and the rest of the town were left in ruins by the Forsaken plague bombing when they achieved victory in the Battle for Hillsbrad. Magistrate Maleb fled to Fenris Isle, and the town hall is now occupied by slime creatures left over from the plague toxins, including Chet the Slime-Breeder.",
			source = "https://warcraft.wiki.gg/wiki/Southshore_Town_Hall",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad is a ghost town located east of Alterac and west of Chillwind Point.",
			full = "Strahnbrad is a ghost town located east of Alterac and west of Chillwind Point. The town is situated in a strategic position on the northeastern foothills of the Alterac Mountains, close to the border with the Western Plaguelands. It has an abandoned town hall and blacksmith. There is a Horde flightmaster, Phillip Harding, located nearby. Gol'dir, formerly a prisoner here, stands next to him.\n\nOnce a part of the Kingdom of Alterac prior to the First War, the town was integrated into the Kingdom of Lordaeron after the Second War, before falling under control of the Syndicate following the Scourging of Lordaeron.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Tarren Mill",
			short = "Tarren Mill is a Forsaken town located in northern Hillsbrad Foothills, near the Alterac Mountains. Prior to the Third War, Tarren Mill was a simple Lordaeronian town.",
			full = "Tarren Mill is a Forsaken town located in northern Hillsbrad Foothills, near the Alterac Mountains. Prior to the Third War, Tarren Mill was a simple Lordaeronian town.\n\nAt some point after the Third War, Forsaken afterward, where it served as the staging point against the Alliance forces of Southshore and Dun Garok. Tarren Mill now stands as a bastion of the Forsaken power, while its former rival Southshore lies in ruins.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Thoradin's Wall",
			short = "Thoradin's Wall is a gigantic heavily damaged wall separating the Arathi Highlands from Hillsbrad Foothills. It was built under the Empire of Arathor to protect mankind from the Amani trolls.",
			full = "Thoradin's Wall is a gigantic heavily damaged wall separating the Arathi Highlands from Hillsbrad Foothills. It was built under the Empire of Arathor to protect mankind from the Amani trolls.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["uplands"] = {
			name = "Uplands",
			short = "The Uplands is a region with hills in northeastern Alterac Mountains.",
			full = "The Uplands is a region with hills in northeastern Alterac Mountains. It was the bread basket of the kingdom of Alterac, but after the destruction of the core of that nation, the Uplands fell under the control of the Syndicate, who have several camps in the area. This area is where they are strongest. Baron Vardus could be found here. Dandred's Fold is found in the westernmost part of the Uplands.\n\nNo quests take place here anymore and this area no longer serves any purpose.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
		["western strand"] = {
			name = "Western Strand",
			short = "The Western Strand is a stretch of coastline in the southwest of Hillsbrad Foothills, complementary to the Eastern Strand further east.",
			full = "The Western Strand is a stretch of coastline in the southwest of Hillsbrad Foothills, complementary to the Eastern Strand further east. The Western Strand is home to the many Torn Fin murlocs who have built small camps along the shore. Andy Murgole patrols the area.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- The Hinterlands: 22 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Aerie Peak",
			short = "Aerie Peak (or the Aerie (s)) is the capital of the Wildhammer clan of dwarves affiliated with the Alliance.",
			full = "Aerie Peak (or the Aerie (s)) is the capital of the Wildhammer clan of dwarves affiliated with the Alliance. It is located in the Hinterlands in a mountainside to the northwest, and it has a range of different services including a gryphon master or a leatherworking trainer.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "Agol'watha is a forest troll ruin in the north-central Hinterlands that was overrun by animated sludges.",
			full = "Agol'watha is a forest troll ruin in the north-central Hinterlands that was overrun by animated sludges. It was once a temple of the late Amani Empire, and later the Vilebranch trolls whose broodguards tended the eggs of Shadra's brood.\n\nThe eye of Shadra was guarded in Agol'watha until it was recovered by adventurers.\n\nA version of the ruins also exists within the Emerald Dream. Here, Nightmare-corrupted dragonkin can be found under the command of Florius, some of them protecting dragon eggs.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "Altar of Zul",
			short = "The Altar of Zul is a Vilebranch forest troll altar in the Hinterlands. Qiaga the Keeper can be found on top of the altar.",
			full = "The Altar of Zul is a Vilebranch forest troll altar in the Hinterlands. Qiaga the Keeper can be found on top of the altar.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Bogen's Ledge",
			short = "Bogen's Ledge is a cave in southwestern Hinterlands.",
			full = "Bogen's Ledge is a cave in southwestern Hinterlands.\n\nAmbassador Rualeth at Aerie Peak wanted adventurers to to kill them as a gesture of goodwill. After Mai'jin and Tcha'kaz' removal, the cave serves no purpose.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "Creeping Ruin",
			short = "The Creeping Ruin is a forest troll ruin in the Hinterlands. Once overrun by hostile slimes, it is now home to the spider children of Shadra.",
			full = "The Creeping Ruin is a forest troll ruin in the Hinterlands. Once overrun by hostile slimes, it is now home to the spider children of Shadra.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Featherbeard's Hovel",
			short = "Featherbeard's Hovel is a house next to Aerie Peak in the Hinterlands. It was Featherbeard's home.",
			full = "Featherbeard's Hovel is a house next to Aerie Peak in the Hinterlands. It was Featherbeard's home.\n\nPreviously, it was the objective of Featherbeard's Endorsement. Now it serves no purpose.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "Hiri'watha is a Witherbark forest troll village located within the Hinterlands and due south of the Quel'Danil Lodge.",
			full = "Hiri'watha is a Witherbark forest troll village located within the Hinterlands and due south of the Quel'Danil Lodge.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["hiriwatha research station"] = {
			name = "Hiri'watha Research Station",
			short = "Hiri'watha Research Station is a subzone of Hinterlands.",
			full = "Hiri'watha Research Station is a subzone of Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha_Research_Station",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Jintha'Alor (also spelled Jintha'alor) is a forest troll city of the located in the Hinterlands. Jintha'Alor was built by the trolls of the Amani Empire, and named after Jintha, a leader of the Amani in ancient times.",
			full = "Jintha'Alor (also spelled Jintha'alor) is a forest troll city of the located in the Hinterlands. Jintha'Alor was built by the trolls of the Amani Empire, and named after Jintha, a leader of the Amani in ancient times. It is the second largest city of the forest trolls, second only to Zul'Aman. It was ruled by the Vilebranch tribe for many years and used as a fortress to sacrifice others.\n\nThe Totem of Akil'darah can be found here. Both the Wildhammer clan and Revantusk tribe laid siege to the city, seeking to end the Vilebranch's incursions upon their land and claim vengeance for their fallen kindred. In the aftermath of this attack, the Revantusk took a step further and claimed the city for their tribe and the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Overlook Cliffs",
			short = "The Overlook Cliffs are a set of steep cliffs that provide a drastic change from the mountainous Hinterlands to the eastern shoreline of the region.",
			full = "The Overlook Cliffs are a set of steep cliffs that provide a drastic change from the mountainous Hinterlands to the eastern shoreline of the region.\n\nThe cliffs are known for their steepness and height. Many travellers have underestimated their height and plummeted to their deaths. The big river that runs through Hinterlands ends here, pouring over the edge in a massive waterfall. This is also the end point for the Hinterlands robot chicken quest.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Plaguemist Ravine",
			short = "Plaguemist Ravine is a pathway in the Hinterlands which leads north to Caer Darrow in the Western Plaguelands.",
			full = "Plaguemist Ravine is a pathway in the Hinterlands which leads north to Caer Darrow in the Western Plaguelands. It is located northwest of Quel'Danil Lodge, and the entrance to it can be found within the woods west of Quel'Danil Lodge at on the other side of the mountain. This can also be found to the north of Rhapsody Shindigger at Shindigger's Camp. There are no mobs or NPCs in this subzone.\n\nThe name \"Plaguemist Ravine\" was given recently, as the plaguing mist from the pathway is a stark contrast to the natural freshness of the rest of the Hinterlands.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Quel'Danil Lodge",
			short = "Not to be confused with Quel'Lithien Lodge in the Eastern Plaguelands.",
			full = "Not to be confused with Quel'Lithien Lodge in the Eastern Plaguelands.\n\nQuel'Danil Lodge is a high elven outpost situated in the Hinterlands, serving as the base of operations near Aerie Peak for the Highvale faction. It is the larger of the two major concentrations of high elves in Lordaeron and is one of the very last high elven settlements.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Revantusk Village",
			short = "Revantusk Village is the only visitable settlement of the Revantusk tribe of forest trolls. You can find the port village on the coast of the Hinterlands.",
			full = "Revantusk Village is the only visitable settlement of the Revantusk tribe of forest trolls. You can find the port village on the coast of the Hinterlands. Now it is just a Horde settlement with reputation going to the Darkspear Trolls.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "Seradane is an area in the northeastern part of the Hinterlands which houses one of the four entrances to the Emerald Dream, a large circular portal.",
			full = "Seradane is an area in the northeastern part of the Hinterlands which houses one of the four entrances to the Emerald Dream, a large circular portal.\n\nThe Great Tree was planted by the followers of Fandral Staghelm from one of Nordrassil's branches in order to stem the tide of saronite seeping up from the land.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "Shadra'Alor is a settlement built by the forest trolls of the Amani Empire in the Hinterlands. The loa Shadra could be summoned here.",
			full = "Shadra'Alor is a settlement built by the forest trolls of the Amani Empire in the Hinterlands. The loa Shadra could be summoned here.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Shaol'watha is a Vilebranch forest troll ruin in northeastern Hinterlands. It used to be a temple.",
			full = "Shaol'watha is a Vilebranch forest troll ruin in northeastern Hinterlands. It used to be a temple.\n\nA version of the ruins also exists within the Emerald Dream. Here, giant turtles led by Ghamoo-Raja brought Dreampearls from the Dreaming Sea.\n\nThe Revantusk tribe drove out the Vilebranch tribe from the ruins and used it as a staging ground to attack Stormfeather Outpost and claim it for the Horde.\n\nThe Wildhammer clan has taken the former troll camp nearby.\n\nBoth the Revantusk general Gan'dranda and the Wildhammer general Thornar Thunderclash were killed by the opposite faction.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Shindigger's Camp",
			short = "Shindigger's Camp is a small camp in the Hinterlands where the drunken dwarf Rhapsody Shindigger and the high elf Gilveradin Sunchaser are located.",
			full = "Shindigger's Camp is a small camp in the Hinterlands where the drunken dwarf Rhapsody Shindigger and the high elf Gilveradin Sunchaser are located.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Skulk Rock",
			short = "Skulk Rock is a forest troll ruin, infested with slimes. A cave exists in this area, and it is one of the few places one can find Ghost Mushrooms.",
			full = "Skulk Rock is a forest troll ruin, infested with slimes. A cave exists in this area, and it is one of the few places one can find Ghost Mushrooms.\n\nDuring the Second War, Skulk Rock housed an Old Horde base, but it was abandoned when the Alliance of Lordaeron drove them out. Several cases of Hinterlands Honey Ripple were abandoned with the base.\n\nA version of the ruins also exists within the Emerald Dream. Here, Nightmare-corrupted wildkin can be found under the command of the Doomkin, some of them protecting the [Elunar Relic].",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["stormfeather outpost"] = {
			name = "Stormfeather Outpost",
			short = "It has an inn, flight master, and quests for Alliance players.",
			full = "It has an inn, flight master, and quests for Alliance players.",
			source = "https://warcraft.wiki.gg/wiki/Stormfeather_Outpost",
		},
		["valorwind lake"] = {
			name = "Valorwind Lake",
			short = "Valorwind Lake is a small lake located to the northeast of Shadra'Alor in the Hinterlands. It is the only known place to find the Violet Tragan, a mysterious mushroom.",
			full = "Valorwind Lake is a small lake located to the northeast of Shadra'Alor in the Hinterlands. It is the only known place to find the Violet Tragan, a mysterious mushroom.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Wildhammer Keep",
			short = "The Wildhammer Keep is a large keep inside Aerie Peak maintained by the Wildhammer dwarves. The keep is also used as an inn and there is an anvil but no forge within.",
			full = "The Wildhammer Keep is a large keep inside Aerie Peak maintained by the Wildhammer dwarves. The keep is also used as an inn and there is an anvil but no forge within.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "Zun'watha is a forest troll ruin that were once inhabited by trolls of the Witherbark tribe tribe in the Hinterlands. The Witherbark tribe has apparently abandoned the ruins, which now lie empty.",
			full = "Zun'watha is a forest troll ruin that were once inhabited by trolls of the Witherbark tribe tribe in the Hinterlands. The Witherbark tribe has apparently abandoned the ruins, which now lie empty. However, Zul'arek Hatefowler can be seen occasionally visiting the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 40 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Amberstill Ranch",
			short = "Amberstill Ranch is a ranch found off the road that leads to Loch Modan, north of Gol'Bolar Quarry in Dun Morogh.",
			full = "Amberstill Ranch is a ranch found off the road that leads to Loch Modan, north of Gol'Bolar Quarry in Dun Morogh. Players can buy a [Rabbit Crate (Snowshoe)] here from Yarlyn Amberstill, as well as accept a quest, [1-30] Protecting the Herd, to kill a Wendigo named Vagash. This ranch also has a Riding trainer and mount vendor, from whom dwarves (or players of any other Alliance race who have obtained exalted Ironforge reputation) can buy Barak Tor'ol mountain rams to ride.\n\nOnly dwarves and people with Exalted reputation with Ironforge can learn riding skill here.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Anvilmar",
			short = "Anvilmar (also known as building A3) is the first settlement of significance encountered by starting dwarves.",
			full = "Anvilmar (also known as building A3) is the first settlement of significance encountered by starting dwarves. It lies to the north in Coldridge Valley and has a set of trainers and some quest givers, as well as a few vendors. The central structure of Anvilmar houses a large forge, although there are no tradeskill trainers present.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["bahrums post"] = {
			name = "Bahrum's Post",
			short = "Bahrum's Post is a small outpost found in eastern Dun Morogh.",
			full = "Bahrum's Post is a small outpost found in eastern Dun Morogh.",
			source = "https://warcraft.wiki.gg/wiki/Bahrum's_Post",
		},
		["brewnall village"] = {
			name = "Brewnall Village",
			short = "Brewnall Village is a tiny dwarven village established in Chill Breeze Valley, near Gnomeregan.",
			full = "Brewnall Village is a tiny dwarven village established in Chill Breeze Valley, near Gnomeregan. It serves as a home for the Barleybrews, who constantly work to experiment and improve on the venerable dwarven beer brewing tradition. The Barleybrews send young dwarves out on missions to protect the village from wild animals and seek out secret ingredients for the ultimate ale.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Chill Breeze Valley",
			short = "Chill Breeze Valley is a T-shaped region in western Dun Morogh, situated between Gnomeregan to the west and Kharanos to the east.",
			full = "Chill Breeze Valley is a T-shaped region in western Dun Morogh, situated between Gnomeregan to the west and Kharanos to the east. Although the east-west branch of the valley is a hub that sees frequent use by young dwarves and gnomes, the north-south section sees a far smaller amount of passers-through, as ominous signs of dangerous monsters can be seen staining the snow there: large bloodstains and ripped-up animal carcasses. More experienced adventurers seek out these ferocious beasts in order to end their threat to the dwarven lands, but many have died in the attempt.\n\nA level 11 elite wendigo is in one of the caves.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Coldridge Pass",
			short = "Coldridge Pass links Coldridge Valley to the rest of Dun Morogh, and is crucial to give the trickle of dwarven recruits to the frontier town of Kharanos.",
			full = "Coldridge Pass links Coldridge Valley to the rest of Dun Morogh, and is crucial to give the trickle of dwarven recruits to the frontier town of Kharanos. Unfortunately, the pass has become infested with troggs, and the only chance for travelers to get through is either to run at top speed or slash their way through the hostile invaders.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nFendrig Redbeard along with twelve other miners were asked to investigate the trogg infestation from Coldridge Pass. As they entered, Fendrig was trapped under rubble of stone. Although the others tried to save him, that was a mistake as the pass collapsed and all of them were killed. The sole survivor was Fendrig after he was rescued.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Coldridge Valley",
			short = "Coldridge Valley is an isolated area in the southwestern corner of Dun Morogh, and is the starting area for dwarven players.",
			full = "Coldridge Valley is an isolated area in the southwestern corner of Dun Morogh, and is the starting area for dwarven players. It is linked to the rest of the zone by the tunnel of Coldridge Pass to the northeast, which is infested with trogg raiders. The road from the valley continues east after the tunnel and then north through Kharanos, eventually winding up into the mountains and terminating at the gates of the dwarven capital of Ironforge.\n\nThe dwarven starting experience takes place almost entirely in Coldridge Valley, with the final quests bringing characters to Kharanos.\n\nThe troggs and trolls were a nuisance prior to the disaster as well; at that time new adventurers were also tasked with helping with wildlife and running errands for residents and Ironforge personnel in the area.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["crushcogs arsenal"] = {
			name = "Crushcog's Arsenal",
			short = "Crushcog's Arsenal is an area in Dun Morogh between Gnomeregan and Ironforge. It is located in front of the massive, locked gate of a Hangar-style building.",
			full = "Crushcog's Arsenal is an area in Dun Morogh between Gnomeregan and Ironforge. It is located in front of the massive, locked gate of a Hangar-style building.\n\nIt is inhabited by Irradiated Technicians, Crushcog Battle Suits, and Repaired Mechano-Tanks.\n\nThe area comes into play in the quests\n\nAlthough there are Rocket Defense Turrets and Gnomeregan Recruits nearby, they do not appear to be involved.",
			source = "https://warcraft.wiki.gg/wiki/Crushcog's_Arsenal",
		},
		["frostmane front"] = {
			name = "Frostmane Front",
			short = "The Frostmane Front is an area controlled by the Frostmane ice trolls just west of the Frostmane Retreat in Dun Morogh. They're under attack by the nearby dwarves trying to push them back before they claim more land.",
			full = "The Frostmane Front is an area controlled by the Frostmane ice trolls just west of the Frostmane Retreat in Dun Morogh. They're under attack by the nearby dwarves trying to push them back before they claim more land. A group of siege engines and mortar teams support the dwarven riflemen while destroyed ballistae and steam tanks can be seen, being scavenged by the trolls.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, the area was invaded by the demons.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Front",
		},
		["frostmane hold"] = {
			name = "Frostmane Hold",
			short = "Frostmane Hold was once the base camp of the Frostmane ice trolls located in the western edge of the cold mountains of Dun Morogh south of Gnomeregan and New Tinkertown.",
			full = "Frostmane Hold was once the base camp of the Frostmane ice trolls located in the western edge of the cold mountains of Dun Morogh south of Gnomeregan and New Tinkertown. The hold is comprised of a few buildings and a cave system. The trolls who once resided here have fallen back to Frostmane Retreat.\n\nThe area was heavily guarded by troll headhunters and hideskinners.\n\nNow, Kharmarn Palegrip sends adventurers to deal with the troggs, including rescuing a number of captured gnomes. In [1-30] Finishin' the Job, he orders to detonate explosives intended to collapse the tunnel through which the troggs arrived in order to stop their advance.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["frostmane hovel"] = {
			name = "Frostmane Hovel",
			short = "Frostmane Hovel is a cave located in the south of Coldridge Valley in Dun Morogh. The adventurer is sent by Grelin Whitebeard to kill Grik'nir and a Wayward Fire Elemental who helps the trolls.",
			full = "Frostmane Hovel is a cave located in the south of Coldridge Valley in Dun Morogh. The adventurer is sent by Grelin Whitebeard to kill Grik'nir and a Wayward Fire Elemental who helps the trolls.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hovel",
		},
		["frostmane retreat"] = {
			name = "Frostmane Retreat",
			short = "Frostmane Retreat is an ice troll village found in Dun Morogh, located between Kharanos and the Tundrid Hills.",
			full = "Frostmane Retreat is an ice troll village found in Dun Morogh, located between Kharanos and the Tundrid Hills.\n\nAlliance forces consisting of adventurers and flying machines entered the area, fought Battok the Berserker and his warriors, and shrunk builders working on the construction of the village. Eventually, the Alliance mission was successful, with trolls's numbers being lowered.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, the area was invaded by the demons.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Retreat",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge (or the Ironforge Main Gate) lead from the lands of Dun Morogh into the City of Ironforge proper. They are a grand sight, and are visible from far across Dun Morogh.",
			full = "The Gates of Ironforge (or the Ironforge Main Gate) lead from the lands of Dun Morogh into the City of Ironforge proper. They are a grand sight, and are visible from far across Dun Morogh. They can be reached by heading north up the great ramp in central Dun Morogh, or southwest from the Commons. A huge statue of High King Modimus Anvilmar stands guard inside the Gates.\n\nDuring the Legion Invasions, a small Illidari camp was briefly set up here. It would occasionally come under attack by Fel Bats. Thunderbrew Specials could also be looted from here.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Gnomeregan is the subterranean capital city of the eponymous kingdom of Gnomeregan and the wrought-iron evidence of gnomish brilliance, ambition, and ingenuity.",
			full = "Gnomeregan is the subterranean capital city of the eponymous kingdom of Gnomeregan and the wrought-iron evidence of gnomish brilliance, ambition, and ingenuity.\n\nDuring the Third War, a trogg invasion led to its tragic downfall, pulled from their sleep by the upheaval of titan sites. In a desperate attempt to kill the invaders, the gnomish ruler, High Tinker Gelbin Mekkatorque, on the advice of his advisor Sicco Thermaplugg, ordered his people to open the pressure valves of their giant, grinding machines and released toxic radiation throughout the city. Though the radiation killed some of the troggs, it empowered others, while nearly eighty percent of gnomekind died within days. The survivors fled to the protection of Ironforge, while others were transformed into horrific, mindless, evil-doing leper gnomes, who still live there. Driven completely mad by the radiation, Thermaplugg declared himself \"King of Gnomeregan\" and took control of the city, leading an army of troggs and leper gnomes.\n\nAfter the Northrend campaign, Mekkatorque launched Operation: Gnomeregan with the support of the Alliance, allowing the gnomes to reclaim both the surface and the upper floors of Gnomeregan. Since then, the S.A.F.E. forces have been responsible for cleaning up the radiation, as well as saving the survivors inside the capital, using New Tinkertown as their base of operations at the surface.\n\nThe city is currently a mid-level dungeon.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Gol'Bolar Quarry",
			short = "Gol'Bolar Quarry is a large dig site found in southeastern Dun Morogh.",
			full = "Gol'Bolar Quarry is a large dig site found in southeastern Dun Morogh. It is the location of a small dwarven mining camp where young dwarves and gnomes can receive missions to exterminate the troggs who have overrun the excavation site and the Gol'Bolar Quarry Mine. There are also some vendors and profession trainers here ready to aid fresh-faced adventurers in any way they can.\n\nDuring the Legion Invasions, the area was invaded by the demons, but defended by Quarry Miners and adventurers. Some of the troggs were killed.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["golbolar quarry mine"] = {
			name = "Gol'Bolar Quarry Mine",
			short = "Gol'Bolar Quarry Mine is a deep mine located in the heart of Gol'Bolar Quarry.",
			full = "Gol'Bolar Quarry Mine is a deep mine located in the heart of Gol'Bolar Quarry. It was once a dwarven excavation site but, in the middle of a dig, the dwarves uncovered one of the underground caverns belonging to the troggs. The troggs pushed the dwarves out, and also took over the quarry outside of the mine. As opposed to the lower-level troggs in the outer quarry, this mine holds some of their strongest numbers which includes their leader, Hammerspine. Enter with caution!\n\nes:Mina Gol'Bolar",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry_Mine",
		},
		["grizzled den"] = {
			name = "Grizzled Den",
			short = "The Grizzled Den is a rather large cave system just southwest of Kharanos in Dun Morogh, where young adventurers can test their mettle against the ferocious wendigos which live there.",
			full = "The Grizzled Den is a rather large cave system just southwest of Kharanos in Dun Morogh, where young adventurers can test their mettle against the ferocious wendigos which live there. Many enter in search of wendigo manes, which are popular for use in seat covers, but it is a risky proposition as the monsters breathe frost spells and flock together to drive the assailants out.\n\nSome special finds in the cave system are copper veins and treasure chests. Also, there is a rare wendigo in the back that is a bit tougher than its counterparts. This is also a great place for new characters to party up with another and \"raid\" the cave. It's their first look at real partying.\n\nDuring the Legion Invasions, the outer area was invaded by the demons, killing the wendigos there.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Helm's Bed Lake",
			short = "Helm's Bed Lake is a smallish lake in southeastern Dun Morogh. Although the lake has mostly frozen over, a hole in the ice is maintained at all times in order to provide access to fresh water.",
			full = "Helm's Bed Lake is a smallish lake in southeastern Dun Morogh. Although the lake has mostly frozen over, a hole in the ice is maintained at all times in order to provide access to fresh water. While travel across the lake itself is quite safe, the surrounding area is crawling with dangerous wildlife and stray troggs. As if that was not enough, Dark Iron dwarves have also taken control of an abandoned building south of the lake, and will attack anyone who wanders too close.\n\nThe body of Narm Faulk is situated here.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, the western coast of the lake was invaded by the demons.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Iceflow Lake",
			short = "Iceflow Lake is a medium-sized lake located in western Dun Morogh.",
			full = "Iceflow Lake is a medium-sized lake located in western Dun Morogh. Although the altitude and the frigid temperature ensures that the lake continually freezes over, the dwarves of Brewnall Village keep a hole clear of ice in order to access fresh water and provide fishing opportunities. Paxton Ganter is located here.\n\nThe lake is dominated by a couple of large islands located in its center. These islands are best avoided, as they are home to a large pack of ravenous wolves, led by the worg Timber.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Ironband's Compound",
			short = "Ironband's Compound lies south of Helm's Bed Lake in eastern Dun Morogh, and is a base of operations for a band of Dark Iron dwarves who readily assault anyone unfortunate enough to wander too close.",
			full = "Ironband's Compound lies south of Helm's Bed Lake in eastern Dun Morogh, and is a base of operations for a band of Dark Iron dwarves who readily assault anyone unfortunate enough to wander too close. It was formerly inhabited by Sturgy Ironband.\n\nWarriors come to the compound in order to aid a fallen dwarf and secure evidence of the Dark Irons' presence for Ironforge in Ironband's Compound.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["ironforge"] = {
			name = "Ironforge",
			short = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance.",
			full = "Ironforge (displayed as the City of Ironforge in the overworld) is the capital city of the dwarves, proud members of the Alliance. Carved into the depths of Ironforge Mountain in northern Dun Morogh, it is the ancestral home of the dwarves and one of the oldest cities on Azeroth. The Council of Three Hammers rules over the city to ensure the fair and equal treatment of all dwarves within its walls from the High Seat. The city is also the capital of the Kingdom of Khaz Modan, which is ruled by the Bronzebeard clan.\n\nAn expansive underground city of craftsmen, explorers, miners, and warriors, famous for its industry and as an Alliance center of commerce, Ironforge is equal parts fortress and capital and a testament to the dwarves' strength and resilience. The city consists of a series of concentric rings, with the smaller levels deeper underground, all radiating out from the namesake Great Forge at its center. Ironforge is perhaps the most intricate of the Alliance cities, boasting many small passageways, shops built into the rock walls, and cavernous rooms. The feel of the city is a bustling, rowdy, and somewhat industrial one, where there are always a thousand things happening at any time of the day or night. However, it is predominantly safe-feeling and cozy; fires roar in the hearths of the inns and shops, and much dwarven laughing and frivolity is to be heard. Also, unlike Stormwind and Darnassus, the city is actually a massive cavern carved into the earth by the dwarves; the ceiling and floor are both hard stone.\n\nMainly because of the Deeprun Tram, linking Ironforge and Stormwind City, and the district of Tinker Town, Ironforge is one of the most racially diverse cities in the Alliance world. With the Council of Three Hammers uniting all three dwarven clans, Ironforge has recently welcomed Dark Iron dwarves and Wildhammer dwarves into Ironforge as well.\n\nThe collective frivolity, the bustling and gruff manner of the dwarves, and the proximity to many quest and raid areas have historically made Ironforge, along with Stormwind City, a popular place to idle.",
			source = "https://warcraft.wiki.gg/wiki/Ironforge",
		},
		["ironforge airfield"] = {
			name = "Ironforge Airfield",
			short = "The Ironforge Airfield, formerly known as the Airstrip or the Dun Morogh airfield, among other (unofficial) things, is an airfield located in a high mountain valley northeast of the dwarven capital city of Ironforge.",
			full = "The Ironforge Airfield, formerly known as the Airstrip or the Dun Morogh airfield, among other (unofficial) things, is an airfield located in a high mountain valley northeast of the dwarven capital city of Ironforge. It has two landing strips, and several gnome pilots are there standing next to their planes or tinkering with them. Around the airfield, there are a series of dwarven buildings and structures. Mountaineers from Ironforge patrol the area, and some members of the Stormpike Guard can be found here too. North of the airfield there is a gryphon roost, but it only connects to Gol'Bolar Quarry via a flying machine. Further north, near the Wetlands, there is a crashed gnome plane along with some bones.",
			source = "https://warcraft.wiki.gg/wiki/Ironforge_Airfield",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos is a bustling little town nestled among the mountain peaks of Dun Morogh.",
			full = "Kharanos is a bustling little town nestled among the mountain peaks of Dun Morogh. The town is surrounded by the stark wintry wilds of Dun Morogh, so adventure is a common commodity and some of the less tenacious folk in town might pay good coin to complete various tasks in the surrounding region. Kharanos is home to a large forge, a gnomish workshop, and the famous Thunderbrew Distillery, where adventurers can sit down and drink some of the best ale available in the world.\n\nFor all its quaint charm, Kharanos is a hub of military activity, defending against all manner of threats in the region. Directly to the west is a large cavern inhabited by fierce wendigo. To the northwest, the Frostmane trolls have rooted themselves atop Shimmer Ridge. Kharanos is where all new recruits fresh from Anvilmar report to begin their adventures in earnest.\n\nOnce, a giant Frostmane troll attacked the town and almost killed every dwarf. Only Lazlo Grindwidget was able to defeat the troll and thus was honored as a hero of Kharanos. All the citizens were rescued by Rohan, Anduin Wrynn and some members of the Alliance.\n\nDuring the Legion Invasions, the town was invaded by demons. It was defended by the Council of Three Hammers, guards, and adventurers of the Alliance and Horde. Several citizens were rescued, while others were inspired to battle as well.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["loading room"] = {
			name = "Loading Room",
			short = "The Loading Room is a section of the Train Depot in Gnomeregan, and the second area new gnomish players visit. Here members of S.A.F.E. tend to the Rescued Survivors of Gnomeregan.",
			full = "The Loading Room is a section of the Train Depot in Gnomeregan, and the second area new gnomish players visit. Here members of S.A.F.E. tend to the Rescued Survivors of Gnomeregan. A Physician's Assistant welcomes new arrivals.",
			source = "https://warcraft.wiki.gg/wiki/Loading_Room",
		},
		["misty pine refuge"] = {
			name = "Misty Pine Refuge",
			short = "Misty Pine Refuge is an outpost building of the Argent Dawn. It is located in central Dun Morogh, and currently houses only one agent of the organization, Father Gavin.",
			full = "Misty Pine Refuge is an outpost building of the Argent Dawn. It is located in central Dun Morogh, and currently houses only one agent of the organization, Father Gavin. Several refugees are waiting here, helped by Buin \"Phloppy\" Freehand, a generous volunteer.\n\nDuring the Legion Invasions, the area was invaded by the demons, but defended by Mountaineer Helmholt, his mountaineers, guards, and adventurers.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["mountain den"] = {
			name = "Mountain Den",
			short = "The Mountain Den is a cave found northeast of South Gate Outpost in Dun Morogh. It does not appear to serve any purpose and houses no NPCs.",
			full = "The Mountain Den is a cave found northeast of South Gate Outpost in Dun Morogh. It does not appear to serve any purpose and houses no NPCs.",
			source = "https://warcraft.wiki.gg/wiki/Mountain_Den",
		},
		["new tinkertown"] = {
			name = "New Tinkertown",
			short = "New Tinkertown is a small town built just outside of Gnomeregan. It is here that the surviving gnomes are teleported after having escaped the radiated city.",
			full = "New Tinkertown is a small town built just outside of Gnomeregan. It is here that the surviving gnomes are teleported after having escaped the radiated city.\n\nThe Survivor Assistance Facilitation Expedition (S.A.F.E.) use one of the buildings as their headquarters at the surface.",
			source = "https://warcraft.wiki.gg/wiki/New_Tinkertown",
		},
		["north gate outpost"] = {
			name = "North Gate Outpost",
			short = "North Gate Outpost is the northeasternmost settlement of the dwarves built in Dun Morogh. It lies in the middle of North Gate Pass, which links Dun Morogh in the west with Loch Modan in the east.",
			full = "North Gate Outpost is the northeasternmost settlement of the dwarves built in Dun Morogh. It lies in the middle of North Gate Pass, which links Dun Morogh in the west with Loch Modan in the east.\n\nThe mountaineers stationed at the outpost are busily defending it from encroaching wildlife, and some dwarves have gone missing in the mountains in search of the more ferocious beasts. Young dwarves and gnomes are tasked with exploring the area and looking for any signs of the lost mountaineers and the animals which killed them.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "North Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east.",
			full = "North Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east. It is frequently traveled by adventurers coming from or going to the Wetlands, as this pass is the closest to the descent from the Loch. North Gate Pass is also the location of the guard station of North Gate Outpost.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["old dormitory"] = {
			name = "Old Dormitory",
			short = "The Old Dormitory is the starting location of the gnomes following Operation: Gnomeregan's successful conclusion.",
			full = "The Old Dormitory is the starting location of the gnomes following Operation: Gnomeregan's successful conclusion.\n\nThe player starts out as an irradiated survivor who, with the help of Nevin Twistwrench and S.A.F.E., must fight their way to the surface.",
			source = "https://warcraft.wiki.gg/wiki/Old_Dormitory",
		},
		["shimmer ridge"] = {
			name = "Shimmer Ridge",
			short = "Shimmer Ridge is located in northern Dun Morogh, west of the Gates of Ironforge. The ridge is inhabited by Frostmane trolls, who grow [Shimmerweed], tame boars and dwell in two camps connected by a bridge.",
			full = "Shimmer Ridge is located in northern Dun Morogh, west of the Gates of Ironforge. The ridge is inhabited by Frostmane trolls, who grow [Shimmerweed], tame boars and dwell in two camps connected by a bridge. Young adventurers seek Shimmer Ridge out in order to collect the shimmer weed for an especially tasty ale recipe.\n\nAt Varian's request, Moira led her personal guard against them once the king's champions have stopped the magical storm and the trolls protecting Shimmer Ridge.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "South Gate Outpost",
			short = "South Gate Outpost is a dwarven settlement built in western Loch Modan. It lies in the middle of the South Gate Pass, which links Dun Morogh in the west with Loch Modan in the east.",
			full = "South Gate Outpost is a dwarven settlement built in western Loch Modan. It lies in the middle of the South Gate Pass, which links Dun Morogh in the west with Loch Modan in the east.\n\nThe mountaineers stationed at the outpost have cleared out most of the encroaching wildlife, and thus do not face the same amount of problems as do the dwarves of North Gate Outpost. Many travelers pass through the outpost on their way to or from Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "South Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east.",
			full = "South Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east. It is frequently traveled by adventurers coming from or going to Thelsamar, as this pass is the closest to the dwarven town. South Gate Pass is also the location of the guard station of South Gate Outpost.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Steelgrill's Depot",
			short = "Steelgrill's Depot is small settlement of miners and engineers that lies just east of Kharanos in Dun Morogh. There are three trainers, some vendors, and a few low-level quests available in the settlement.",
			full = "Steelgrill's Depot is small settlement of miners and engineers that lies just east of Kharanos in Dun Morogh. There are three trainers, some vendors, and a few low-level quests available in the settlement. The Operation: Gnomeregan quest chain has several quests here.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, the area was invaded by the demons.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Thunderbrew Distillery",
			short = "The Thunderbrew Distillery is a dwarven tavern in Kharanos. It features trainers for warriors, priests, paladins, mages, rogues, cooking, and first aid.",
			full = "The Thunderbrew Distillery is a dwarven tavern in Kharanos. It features trainers for warriors, priests, paladins, mages, rogues, cooking, and first aid. It also has several vendors, along with Innkeeper Belm with the usual services. The distillery is known far and wide for its excellent ale.\n\nGrimbooze Thunderbrew used to be the owner of the distillery when Chen Stormstout visited it.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["toxic airfield"] = {
			name = "Toxic Airfield",
			short = "The Toxic Airfield is a zone of Dun Morogh filled with Toxic Sludges and Living Contaminations.",
			full = "The Toxic Airfield is a zone of Dun Morogh filled with Toxic Sludges and Living Contaminations. After Operation: Gnomeregan and the Irradiator 3000, that which remained after the explosion turned into Toxic Airfield we know it today. All the gnomes that died or were dying during the mission turned into Toxic Sludge. Corporal Fizzwhistle and his Gnomeregan Recruits can be found here combating the contamination. Additionally, Engineer Grindspark will send players here to help with the cleanup using his GS-9x Multi-Bot. While no one controls this area, Gibblewilt makes his presents known here.\n\nMany destroyed flying machines and bombers are there.",
			source = "https://warcraft.wiki.gg/wiki/Toxic_Airfield",
		},
		["train depot"] = {
			name = "Train Depot",
			short = "The Train Depot is a large area located within Gnomeregan, and is the second place players encounter after taking the elevator down from Dun Morogh.",
			full = "The Train Depot is a large area located within Gnomeregan, and is the second place players encounter after taking the elevator down from Dun Morogh. It is full of leper gnomes and troggs, and was presumably a transportation hub before the city's networks were destroyed.\n\nThe Train Depot leads to the core of the city (the instance) via the Clockwerk Run tunnel to the west. Off the northern-most room (known by some as the Workshop) are the Loading Room (to the west, now known as the Old Dormitory) and the back door into the instance (to the north), which once could be opened with the [Workshop Key], and which leads down into the upper level of the Engineering Labs inside the instance. Namdo Bizzfizzle is also hiding up against the north side of the main platform on the lower level of this room.",
			source = "https://warcraft.wiki.gg/wiki/Train_Depot",
		},
		["tundrid hills"] = {
			name = "Tundrid Hills",
			short = "The Tundrid Hills are located in the southcentral are of Dun Morogh and west of Gol'Bolar Quarry. The hills are home to several species of hostile wildlife, and few travel here without a weapon handy.",
			full = "The Tundrid Hills are located in the southcentral are of Dun Morogh and west of Gol'Bolar Quarry. The hills are home to several species of hostile wildlife, and few travel here without a weapon handy. Sometimes, adventurers use the Tundrid Hills as a shortcut to travel between Coldridge Valley and eastern Dun Morogh, although this is a significantly more dangerous route than following the road through Kharanos.\n\nThe Frostmane Trolls have set up a large camp in the valley.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, the area was invaded by the demons.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
		["whitebeards encampment"] = {
			name = "Whitebeard's Encampment",
			short = "Whitebeard's Encampment is small camp site located in central Coldridge Valley.",
			full = "Whitebeard's Encampment is small camp site located in central Coldridge Valley.",
			source = "https://warcraft.wiki.gg/wiki/Whitebeard's_Encampment",
		},
		["workshop entrance"] = {
			name = "Workshop Entrance",
			short = "The Workshop Entrance (sometimes known as the \"Backdoor\") of Gnomeregan is a subzone at the far side of the Workshop room just past the Train Depot in the non-instanced part of Gnomeregan.",
			full = "The Workshop Entrance (sometimes known as the \"Backdoor\") of Gnomeregan is a subzone at the far side of the Workshop room just past the Train Depot in the non-instanced part of Gnomeregan. There is a door that once required the [Workshop Key] to open it and be able to access the instance through this area. Once in the dungeon, a hall will lead you to the Engineering Labs section of instance.\n\nWhen facing the Workshop Entrance from the far side of the Workshop, the Loading Room opening is to your left.",
			source = "https://warcraft.wiki.gg/wiki/Workshop_Entrance",
		},
	},
	-- Searing Gorge: 14 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Blackchar Cave",
			short = "Blackchar Cave is a mysterious, sealed-off cave near Blackrock Mountain. This is where players can find [1-90] Ironband the Elder during the Lunar Festival.",
			full = "Blackchar Cave is a mysterious, sealed-off cave near Blackrock Mountain. This is where players can find [1-90] Ironband the Elder during the Lunar Festival.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions.",
			full = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions. One of the most dangerous places in Azeroth, inside this unnaturally created volcano is some of the greatest work ever wrought by the dwarves. Created when Emperor Dagran Thaurissan accidentally summoned Ragnaros from the Firelands, the mountain was hotly contested between the Firelord's Dark Iron servants and the black dragon Nefarian's Blackrock orcs, until the Horde and Alliance adventurers invaded the volcano to decimate their armies, ending their decades-long conflict.\n\nDuring the Ironmarch, the Black Iron attempted to destroy Stormwind City by inducing an eruption, but were stopped in time by the heroes.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "Cauldron",
			short = "The Cauldron is an enormous excavation site in the center of the Searing Gorge. It was fortified some time after Ragnaros was summoned by the Dark Iron dwarves.",
			full = "The Cauldron is an enormous excavation site in the center of the Searing Gorge. It was fortified some time after Ragnaros was summoned by the Dark Iron dwarves. It is rimmed by the giant excavation machines of the Dark Iron clan. In the burning depths of the Cauldron, fire and magma elementals traverse the fiery crevices.\n\nMany Slave Workers captured by the Dark Irons toil away endlessly inside the Cauldron. Driven mad by their masters, the grueling work, and the constant oppressive heat, they will attack anyone interfering with their work in the Cauldron -- even potential liberators.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Dustfire Valley",
			short = "Dustfire Valley is a windswept valley in the Searing Gorge that leads north to the gates of Stonewrought Pass to the Valley of Kings in Loch Modan.",
			full = "Dustfire Valley is a windswept valley in the Searing Gorge that leads north to the gates of Stonewrought Pass to the Valley of Kings in Loch Modan. Now, however, travelers can simply travel through the gates without a key or by other means.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Firewatch Ridge",
			short = "Firewatch Ridge is where the main campsite of the Dark Iron dwarves in Searing Gorge lies. It overlooks the great excavation site of the Cauldron.",
			full = "Firewatch Ridge is where the main campsite of the Dark Iron dwarves in Searing Gorge lies. It overlooks the great excavation site of the Cauldron. Dark Irons, their mechanical golems, and giant flame spiders cover most of the ridge, making it exceptionally dangerous for adventurers. The northwestern part of it contains a Twilight's Hammer cave, where you could find elites.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Grimesilt Dig Site",
			short = "The Grimesilt Dig Site is a digsite once used by the Ironforge dwarves but was taken over and is currently still in the possession of the Dark Iron dwarves.",
			full = "The Grimesilt Dig Site is a digsite once used by the Ironforge dwarves but was taken over and is currently still in the possession of the Dark Iron dwarves. One original worker at the site, Dorius Stonetender, lies injured at the bottom of the pit, and another crew member is trapped in a nearby outhouse.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["iron summit"] = {
			name = "Iron Summit",
			short = "The Iron Summit is a small mountain northeast of Blackrock Mountain in the Searing Gorge on which a camp is located.",
			full = "The Iron Summit is a small mountain northeast of Blackrock Mountain in the Searing Gorge on which a camp is located. It belongs to a group of independent dark dwarves under the leadership of Mountain-Lord Rendan, who are not affiliated with the Dark Iron clan or the Thorium Brotherhood. While being a neutral quest hub the loyalty of Rendan is available for the right price.\n\nThe Incendosaurs that used to inhabit the lowest reaches of the Slag Pit now roam the rocky reaches around the Summit.",
			source = "https://warcraft.wiki.gg/wiki/Iron_Summit",
		},
		["pyrox flats"] = {
			name = "Pyrox Flats",
			short = "Pyrox Flats is a level area north of The Cauldron in Searing Gorge. It is inhabited by camps of Dark Iron dwarves.",
			full = "Pyrox Flats is a level area north of The Cauldron in Searing Gorge. It is inhabited by camps of Dark Iron dwarves.",
			source = "https://warcraft.wiki.gg/wiki/Pyrox_Flats",
		},
		["sea of cinders"] = {
			name = "Sea of Cinders",
			short = "The Sea of Cinders is a relatively flat stretch of land in the southern area of the Searing Gorge, just north of Blackrock Mountain.",
			full = "The Sea of Cinders is a relatively flat stretch of land in the southern area of the Searing Gorge, just north of Blackrock Mountain. The flat lands have been ravaged by fire and wind and are now an uninhabitable wasteland. Cinders and ashes from the still smoldering ground are constantly flying through the air, making it an extremely unpleasant area to travel through.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "Slag Pit",
			short = "The Slag Pit lies deep within the Cauldron excavation site in Searing Gorge. It is run by cruel Dark Iron dwarves and worked by their slave laborers.",
			full = "The Slag Pit lies deep within the Cauldron excavation site in Searing Gorge. It is run by cruel Dark Iron dwarves and worked by their slave laborers. Within the depths of the Slag Pit there is another danger, ravenous Incendosaurs. The Dark Irons are extremely hostile to any who would interfere with their mining operations.\n\nNote: although the Slave Workers initially show up as yellow mobs, they will turn hostile if you attack a Dark Iron Slaver or Dark Iron Taskmaster within their aggro radius.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Stonewrought Pass",
			short = "The Stonewrought Pass is a tunnel in Searing Gorge that leads northeast to Loch Modan. The pass is located at the northern end of Dustfire Valley, and ends at the Valley of Kings.",
			full = "The Stonewrought Pass is a tunnel in Searing Gorge that leads northeast to Loch Modan. The pass is located at the northern end of Dustfire Valley, and ends at the Valley of Kings.\n\nFranclorn Forgewright designed this, as well as the Stonewrought Dam and other stonework architecture in the Eastern Kingdoms.\n\nMountaineer Pebblebitty guarded Loch Modan gate, only letting Alliance players through after a small quest chain initiated by killing Margol the Rager. Since then, however, the pass is permanently open on both sides.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Tanner Camp",
			short = "Tanner Camp is a small camp in the Searing Gorge where Sarah Tanner, the master elemental leatherworker for the Alliance, lives.",
			full = "Tanner Camp is a small camp in the Searing Gorge where Sarah Tanner, the master elemental leatherworker for the Alliance, lives. Behind her tent is a long, sprawling passageway that leads to the thunder lizard Margol the Rager.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium advance"] = {
			name = "Thorium Advance",
			short = "Thorium Advance is a camp headed by the Thorium Brotherhood. It is situated along the road in the Searing Gorge that leads to the Badlands.",
			full = "Thorium Advance is a camp headed by the Thorium Brotherhood. It is situated along the road in the Searing Gorge that leads to the Badlands.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Advance",
		},
		["thorium point"] = {
			name = "Thorium Point",
			short = "Thorium Point is a small, neutral town in northern Searing Gorge inhabited by the Thorium Brotherhood.",
			full = "Thorium Point is a small, neutral town in northern Searing Gorge inhabited by the Thorium Brotherhood.\n\nIt has a flight path and the majority of the quests in the Searing Gorge as well as a couple of vendors. It is located northeast of Firewatch Ridge and is populated mostly by neutral Dark Iron dwarves. It is a critical hub for farming Thorium Brotherhood reputation.\n\nThere is a forge and anvil at this location.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Burning Steppes: 20 subzones
	[1428] = {
		["altar of storms burning steppes"] = {
			name = "Altar of Storms (Burning Steppes)",
			short = "An Altar of Storms can be found in the Burning Steppes, in the shadow of Blackrock Spire. Warlock members of the Blackrock clan have taken over the area and perform strange rituals at the altar.",
			full = "An Altar of Storms can be found in the Burning Steppes, in the shadow of Blackrock Spire. Warlock members of the Blackrock clan have taken over the area and perform strange rituals at the altar. On a hill to the west lies the home of Gorzeeki Wildeyes, which has been swarmed by hostile Blackrock orcs.\n\nGorzeeki can be found at a small campsite near the entrance to the area, waiting for a chance to get his home back.\n\nNew warlock initiates were sent here by Madam Shadow who lured them into a trap.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Storms_(Burning_Steppes)",
		},
		["black tooth hovel"] = {
			name = "Black Tooth Hovel",
			short = "Black Tooth Hovel is an expansive Dark Horde camp in the central Burning Steppes.",
			full = "Black Tooth Hovel is an expansive Dark Horde camp in the central Burning Steppes. It is roamed by members of the Blackrock clan along with Firegut ogres and Smolderthorn trolls, and is overseen by Quartermaster Kaoshin at the Pillar of Ash. Blackrock War Kodos roam the fields in the southeastern parts.\n\nThe hovel's main point of interest is a huge statue of Anduin Lothar, sword raised in the direction of Blackrock Mountain. The monument was built months after the Second War, looking out over the same plain where Lothar had fought and died during the Siege of Blackrock Spire. The defeated orcs had been put to hard labor building up the statue, an irony that Turalyon appreciated. Curiously, the modern-day Blackrock orcs seem to ignore it. A single Lotharian Lotus grows at the base of the statue.",
			source = "https://warcraft.wiki.gg/wiki/Black_Tooth_Hovel",
		},
		["blackrock mountain"] = {
			name = "Blackrock Mountain",
			short = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions.",
			full = "Blackrock Mountain is a volcanic zone located between the Burning Steppes and the Searing Gorge, linking the two regions. One of the most dangerous places in Azeroth, inside this unnaturally created volcano is some of the greatest work ever wrought by the dwarves. Created when Emperor Dagran Thaurissan accidentally summoned Ragnaros from the Firelands, the mountain was hotly contested between the Firelord's Dark Iron servants and the black dragon Nefarian's Blackrock orcs, until the Horde and Alliance adventurers invaded the volcano to decimate their armies, ending their decades-long conflict.\n\nDuring the Ironmarch, the Black Iron attempted to destroy Stormwind City by inducing an eruption, but were stopped in time by the heroes.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Blackrock Pass",
			short = "Blackrock Pass is the main entrance into the Burning Steppes from the Redridge Mountains. Prior to the opening of the Redridge Pass, it was the only foot entrance to the Steppes other than through Blackrock Mountain.",
			full = "Blackrock Pass is the main entrance into the Burning Steppes from the Redridge Mountains. Prior to the opening of the Redridge Pass, it was the only foot entrance to the Steppes other than through Blackrock Mountain. By traveling through the pass, you leave behind the tranquil low-level lands of the human starting areas and venture into the scorched and twisted ruin of the Burning Steppes. Low-level travelers are advised to avoid Blackrock Pass at all costs, as the enemies beyond are far stronger than those found in Redridge Mountains.\n\nThe pass contains a gate that borders Redridge Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Blackrock Stronghold",
			short = "Blackrock Stronghold is a massive stronghold controlled by the Blackrock clan of orcs. It is located in the northern region of the Burning Steppes, just outside Blackrock Spire.",
			full = "Blackrock Stronghold is a massive stronghold controlled by the Blackrock clan of orcs. It is located in the northern region of the Burning Steppes, just outside Blackrock Spire. Members and allies of the Blackrock clan gather outside in the Fields of Honor, being kept in line by Blackrock Sergeants.\n\nThe stronghold's operations are overseen by General Thorg'izog, who disciplines and gives orders to the troops in the surrounding area.\n\nDuring the Burning Steppes storyline the stronghold is infiltrated by a member of the Horde / Alliance, and most of the Blackrock Sergeants are killed in a mysterious deadly cudgeling incident.\n\nBy the time of the War of Light and Shadow, Warlord Grazla ruled the Dark Horde from the stronghold. She was ultimately slain at the behest of the Sons of Lothar. Afterward, Ariok and Addie Fizzlebog started keeping an eye on the area.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["chiselgrip"] = {
			name = "Chiselgrip",
			short = "Chiselgrip is a neutral Thorium Brotherhood camp located southwest of the Ruins of Thaurissan in the Burning Steppes.",
			full = "Chiselgrip is a neutral Thorium Brotherhood camp located southwest of the Ruins of Thaurissan in the Burning Steppes. It serves as a quest hub from which adventurers strike undercover at the Blackrock clan, after making the necessary preparations at Flamestar Post. Despite not being listed as one, Hoddruc Bladebender is a repair vendor. It has a flight path and two forges located near Stebben Oreknuckle.",
			source = "https://warcraft.wiki.gg/wiki/Chiselgrip",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "Draco'dar is a region of scorched hills in the southwest Burning Steppes. Draco'dar is crawling with minions of the black dragonflight and adventurers are advised not to enter the area alone.",
			full = "Draco'dar is a region of scorched hills in the southwest Burning Steppes. Draco'dar is crawling with minions of the black dragonflight and adventurers are advised not to enter the area alone.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Dreadmaul Rock",
			short = "Dreadmaul Rock, also known as Dreadmaul Peak, is the base of operations for the Firegut ogres. It is a large structure, with paths leading to the top and a complicated cave system of ogre mounds within.",
			full = "Dreadmaul Rock, also known as Dreadmaul Peak, is the base of operations for the Firegut ogres. It is a large structure, with paths leading to the top and a complicated cave system of ogre mounds within.\n\nDreadmaul Rock is now being used as a major base of operations for attacks by the clan aimed towards Redridge Mountains to the south.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["fields of honor"] = {
			name = "Fields of Honor",
			short = "The Fields of Honor are located around the front of Blackrock Stronghold in the Burning Steppes, extending to the Ruins of Thaurissan to the east and Black Tooth Hovel to the south.",
			full = "The Fields of Honor are located around the front of Blackrock Stronghold in the Burning Steppes, extending to the Ruins of Thaurissan to the east and Black Tooth Hovel to the south. Here, the Blackrock clan rally their troops for battle. Blackrock Soldiers, Smolderthorn Assassins, and Firegut Flamespeakers are kept in formation by Blackrock Sergeants, waiting for orders from General Thorg'izog.",
			source = "https://warcraft.wiki.gg/wiki/Fields_of_Honor",
		},
		["firegut furnace"] = {
			name = "Firegut Furnace",
			short = "Firegut Furnace is an ogre mound at the base of Dreadmaul Rock in the Burning Steppes. The Firegut Ogres make their home here.",
			full = "Firegut Furnace is an ogre mound at the base of Dreadmaul Rock in the Burning Steppes. The Firegut Ogres make their home here. Since their alliance with the Blackrock clan, the Furnace is occasionally visited by high-ranking Blackrock orcs.",
			source = "https://warcraft.wiki.gg/wiki/Firegut_Furnace",
		},
		["flame crest"] = {
			name = "Flame Crest",
			short = "Flame Crest is a Horde outpost in the Burning Steppes. It is located on a small outcropping of rock, only accessible by crossing a crude bridge.",
			full = "Flame Crest is a Horde outpost in the Burning Steppes. It is located on a small outcropping of rock, only accessible by crossing a crude bridge. There is a small cave in the back where Kibler lives with the talkative parrot Opus. Eitrigg and Ariok used the outpost as their base of operations when planning an attack against the Blackrock clan.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["flamestar post"] = {
			name = "Flamestar Post",
			short = "Flamestar Post is located immediately south of the bridge leading to Blackrock Mountain in the Burning Steppes.",
			full = "Flamestar Post is located immediately south of the bridge leading to Blackrock Mountain in the Burning Steppes. It is a small camp run by the Thorium Brotherhood and serves as the first quest hub for those entering the Burning Steppes. While here, adventurers help start a plan to fight back against the Blackrock orcs.\n\nIt contains a flight path and an Adventure Board leading Horde players into Blackrock Depths.",
			source = "https://warcraft.wiki.gg/wiki/Flamestar_Post",
		},
		["morgans vigil"] = {
			name = "Morgan's Vigil",
			short = "Morgan's Vigil is an Alliance settlement in the southeastern corner of the Burning Steppes.",
			full = "Morgan's Vigil is an Alliance settlement in the southeastern corner of the Burning Steppes. It is only a small village left in ruins; with houses and structures burned to the ground and a single mage tower left crumbled and destroyed. Several tents have been erected for the inhabitants to live in.\n\nAlthough once used as an outpost for adventurers, it has now been all but abandoned. Several of the previous residents, along with the town's namesake Morgan herself, have gone to the depths of Blackrock Mountain to better stop the nefarious activities there.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "Pillar of Ash",
			short = "The Pillar of Ash is a tall tower in the eastern end of Black Tooth Hovel in the Burning Steppes.",
			full = "The Pillar of Ash is a tall tower in the eastern end of Black Tooth Hovel in the Burning Steppes.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["ruins of thaurissan"] = {
			name = "Ruins of Thaurissan",
			short = "The Ruins of Thaurissan, once known as Thaurissan City, are what remains of the Dark Iron clan's original capital city.",
			full = "The Ruins of Thaurissan, once known as Thaurissan City, are what remains of the Dark Iron clan's original capital city. Little is known of the great city, but Royal Historian Archesonus of Ironforge has led research into its ruins found in the Burning Steppes, to reveal some information about the place. It was referred to as the home of the Dark Iron nation and later kingdom.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["skull warren"] = {
			name = "Skull Warren",
			short = "The Skull Warren is a cave at the middle section of the eastern face of Dreadmaul Rock in the Burning Steppes.",
			full = "The Skull Warren is a cave at the middle section of the eastern face of Dreadmaul Rock in the Burning Steppes. Part of Firegut Ogre territory for years, since their alliance with the Blackrock clan the former ogre mound has been taken over by the Blackrock as a training ground for their warlocks, overseen by High Warlock Xi'lun.",
			source = "https://warcraft.wiki.gg/wiki/Skull_Warren",
		},
		["slither rock"] = {
			name = "Slither Rock",
			short = "Slither Rock is a small cave found in the far northeastern corner of the Burning Steppes. It used to be inhabited by a sole creature - the black dragonspawn Cyrus Therepentous.",
			full = "Slither Rock is a small cave found in the far northeastern corner of the Burning Steppes. It used to be inhabited by a sole creature - the black dragonspawn Cyrus Therepentous. Hidden beyond the Terror Wing Path, Cyrus would nevertheless aid adventurers in vanquishing a common foe, albeit not without an ample supply of rude and derisive comments. Now Acride resides in the cave.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Terror Wing Path",
			short = "Terror Wing Path is the valley located in the eastern region of the Burning Steppes. Terror Wing is home to many whelps and dragonkin of the black dragonflight.",
			full = "Terror Wing Path is the valley located in the eastern region of the Burning Steppes. Terror Wing is home to many whelps and dragonkin of the black dragonflight.\n\nIn the southeastern section of Terror Wing Path the goblin-built Redridge Pass runs high into the hills, leading all the way through Redridge Mountains and into the Swamp of Sorrows. Sharon Boomgetter provides travelers with a one-way trip on the highway, going to the resort town of Bogpaddle.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
		["valley of ashes"] = {
			name = "Valley of Ashes",
			short = "The Valley of Ashes is an area in the Burning Steppes. It is a smoldering stretch of valley curving between the hills, with molten flows to the south and a charred plain to the north.",
			full = "The Valley of Ashes is an area in the Burning Steppes. It is a smoldering stretch of valley curving between the hills, with molten flows to the south and a charred plain to the north. Nothing but tough local wildlife lives here; the only sentient creatures in the area are the black dragonflight. The valley is surrounded by inhospitable land, as Dreadmaul Rock lies to the northeast, the Ruins of Thaurissan is to the northwest, and the Blackrock clan's Black Tooth Hovel is west.\n\nThe road running south through the valley leads through Blackrock Pass and eventually into the Redridge Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Ashes",
		},
		["whelping downs"] = {
			name = "Whelping Downs",
			short = "The Whelping Downs are found in the Burning Steppes, south of Blackrock Mountain. Hordes of dragonflight whelpings are kept or raised here by the Blackrock clan.",
			full = "The Whelping Downs are found in the Burning Steppes, south of Blackrock Mountain. Hordes of dragonflight whelpings are kept or raised here by the Blackrock clan. The Black dragonflight's whelps fly free, cared for and protected by Blackrock Whelpers. Whelps of other dragonflights are also held here before being transferred to Blackrock Spire, where they will be used in gruesome experiments.",
			source = "https://warcraft.wiki.gg/wiki/Whelping_Downs",
		},
	},
	-- Elwynn Forest: 30 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Brackwell Pumpkin Patch",
			short = "Brackwell Pumpkin Patch is a Stormwindian farmstead located in southeast Elwynn Forest. It served as the Brackwell family's home before the bandits moved in.",
			full = "Brackwell Pumpkin Patch is a Stormwindian farmstead located in southeast Elwynn Forest. It served as the Brackwell family's home before the bandits moved in.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Crystal Lake",
			short = "Crystal Lake is a lake located directly east of Goldshire in Elwynn Forest. It is crawling with murlocs and may be quite dangerous for the inexperienced adventurer.",
			full = "Crystal Lake is a lake located directly east of Goldshire in Elwynn Forest. It is crawling with murlocs and may be quite dangerous for the inexperienced adventurer. William Pestle sends adventurers here to gather kelp from the murlocs in order to make an invisibility potion. A grave with the inscription \"Deeply missed, never forgotten\" is located on an islet in the center. A human homestead stands on the southern shore.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Eastvale Logging Camp",
			short = "Eastvale Logging Camp (also known as the Eastvale Lumber Camp or just Eastvale Camp) is a series of Stormwindian lumber mill camps with living areas in between, located in eastern of Elwynn Forest.",
			full = "Eastvale Logging Camp (also known as the Eastvale Lumber Camp or just Eastvale Camp) is a series of Stormwindian lumber mill camps with living areas in between, located in eastern of Elwynn Forest. Orders for lumber are constantly streaming in from various buyers, and the lumberjacks work against strict deadlines. There is also stables where adventurers can purchase horses mounts.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Echo Ridge Mine",
			short = "Echo Ridge Mine is a mine located in northwestern Northshire Valley within Elwynn Forest.",
			full = "Echo Ridge Mine is a mine located in northwestern Northshire Valley within Elwynn Forest. It was once overtaken by kobolds, much to the frustration of the humans living in the area, leading Marshal McBride to enlist adventurers to regularly purge their ranks. It is unknown why it was closed, but it's possible that it had collapsed at some point due to the earthquakes or to prevent the kobolds of Elwynn Forest from getting back inside.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Fargodeep Mine",
			short = "The Fargodeep Mine is an abandoned Stormwindian gold mine located in Elwynn Forest, which has been overrun by a clan of kobolds. Its lower section is called Lower Mines.",
			full = "The Fargodeep Mine is an abandoned Stormwindian gold mine located in Elwynn Forest, which has been overrun by a clan of kobolds. Its lower section is called Lower Mines.\n\nAt the request of Marshal Dughan, the Alliance adventurers scouted the mines and confirmed the reports of kobold presence, leading to an increase in patrols in the area. The heroes later returned in Fargodeep Mine to collect gold dust for Remy \"Two Times\", gather large candles for William Pestle, and to recover a necklace from Goldtooth for \"Auntie\" Bernice Stonefield.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Forest's Edge",
			short = "Forest's Edge is a peninsula-like swath of forest southwest of Stormwind City in Elwynn Forest, located between Mirror Lake Orchard, the Nazferiti river and the small northern river near Westfall.",
			full = "Forest's Edge is a peninsula-like swath of forest southwest of Stormwind City in Elwynn Forest, located between Mirror Lake Orchard, the Nazferiti river and the small northern river near Westfall.\n\nIt is the location of a group of gnolls led by an elite named Hogger. A couple of boars also wander around the area. It also contains some herb spawn points, as well as a copper vein or two along the rivers. Westbrook Garrison is found on its northern area.\n\nHogger now resides on his own hill in the southern section.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Goldshire",
			short = "Goldshire is a human town centrally located in Elwynn Forest, just southwest of Northshire Valley.",
			full = "Goldshire is a human town centrally located in Elwynn Forest, just southwest of Northshire Valley. It has roads that lead to Stormwind City to the northwest, Northshire Abbey to the northeast, Westfall to the west, and Redridge Mountains to the east. It is the second settlement that most human heroes visit at the beginning of their journey. Marshal Dughan of the Stormwind Guard is in charge of the security. Many travelers are seen enjoying the hospitality of the Lion's Pride Inn, one of the most respectable ale houses in Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["goldtooths den"] = {
			name = "Goldtooth's Den",
			short = "Goldtooth's Den is a small camp in Elwynn Forest located above the Fargodeep Mine.",
			full = "Goldtooth's Den is a small camp in Elwynn Forest located above the Fargodeep Mine.\n\nHe has since relocated right above it.",
			source = "https://warcraft.wiki.gg/wiki/Goldtooth's_Den",
		},
		["hall of arms northshire"] = {
			name = "Hall of Arms (Northshire)",
			short = "The Hall of Arms wing of Northshire Abbey, located in Northshire Valley in Elwynn Forest, is home to both the paladin and warrior trainers for the least experienced of the Stormwind Army recruits.",
			full = "The Hall of Arms wing of Northshire Abbey, located in Northshire Valley in Elwynn Forest, is home to both the paladin and warrior trainers for the least experienced of the Stormwind Army recruits. It is situated south of the Main Hall, and the Library Wing lies on the opposite side of the Abbey.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Arms_(Northshire)",
		},
		["heroes vigil"] = {
			name = "Heroes' Vigil",
			short = "Heroes' Vigil is the central area of the Stone Cairn Lake island in eastern Elwynn Forest.",
			full = "Heroes' Vigil is the central area of the Stone Cairn Lake island in eastern Elwynn Forest. It features a ring of stones, and a monument called the Stone of Remembrance which commemorates the dead from the orcs' sacking of Goldshire and other nearby regions during the First War. The island itself is controlled by Rogue Wizards who can be quite dangerous to inexperienced adventurers.\n\nThe body of Henze Faulk is situated here.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["hogger hill"] = {
			name = "Hogger Hill",
			short = "Hogger Hill is a small hill located south of Westbrook Garrison, in the Alliance territory of Elwynn Forest.",
			full = "Hogger Hill is a small hill located south of Westbrook Garrison, in the Alliance territory of Elwynn Forest. It is named after the elite gnoll Hogger that can be found pacing on this hill, with a Dead Thief lying dead, and carcasses strewn about. Alliance troops arrived to face and take Hogger into custody in the Stockade.",
			source = "https://warcraft.wiki.gg/wiki/Hogger_Hill",
		},
		["jasperlode mine"] = {
			name = "Jasperlode Mine",
			short = "Jasperlode Mine, like Fargodeep Mine, was one of the key mining sites in Elwynn Forest, providing Stormwind City with valuable raw materials needed in the wars.",
			full = "Jasperlode Mine, like Fargodeep Mine, was one of the key mining sites in Elwynn Forest, providing Stormwind City with valuable raw materials needed in the wars. Lately, however, the mine has been overrun by kobolds, and with all the challenges that its army has to face, Stormwind does not have the manpower to drive the vermin out.\n\nUnfortunately for the kobolds of Elwynn Forest, the deepest recesses of this mine have been overrun by a colony of Mine Spiders who apparently see the hapless kobolds as a tasty snack. Although these spiders do not venture far from their nest, adventurers should beware as their queen, Mother Fang, does not approve of any uninvited guests.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nMarshal Dughan had a nightmare about being in the mine while on a mission to clear it of kobolds. He had over 10 men and Zaldimar Wefhellt with him, but he failed his mission and was overrun by the kobolds.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Jerod's Landing",
			short = "Jerod's Landing is a boat landing on the Elwynn Forest bank of the Nazferiti river.",
			full = "Jerod's Landing is a boat landing on the Elwynn Forest bank of the Nazferiti river. Upon being taken over by the Defias Brotherhood, the Dockmaster and his men used it to smuggle stolen goods from Redridge Mountains to Klaven's Tower in Westfall. Since the fell of the Brotherhood, the landing is currently operated independently by a group of thieves.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["library wing northshire"] = {
			name = "Library Wing (Northshire)",
			short = "The Library Wing of Northshire Abbey, located in Northshire Valley in Elwynn Forest, is home to the priest trainer Priestess Anetta and the mage trainer Khelden Bremen for the least experienced of the Stormwind Army's recruits.",
			full = "The Library Wing of Northshire Abbey, located in Northshire Valley in Elwynn Forest, is home to the priest trainer Priestess Anetta and the mage trainer Khelden Bremen for the least experienced of the Stormwind Army's recruits. It is situated south of the Main Hall, and the Hall of Arms lies on the opposite side of the abbey. Like in the rest of the abbey, Wounded Trainees can be found here.",
			source = "https://warcraft.wiki.gg/wiki/Library_Wing_(Northshire)",
		},
		["lions pride inn"] = {
			name = "Lion's Pride Inn",
			short = "Lion's Pride Inn (also known as the Goldshire Inn) is an inn found in the town of Goldshire, in Elwynn Forest.",
			full = "Lion's Pride Inn (also known as the Goldshire Inn) is an inn found in the town of Goldshire, in Elwynn Forest. According to Innkeeper Farley, the inn's motto is \"Rest and relaxation for the tired and cold.\" The inn has been run by the Farley family for years, since the time of King Llane Wrynn I, and they take great effort to run an above-board business.\n\nLion's Pride offers a wide range of services from class trainers and quest givers to drinks aplenty.",
			source = "https://warcraft.wiki.gg/wiki/Lion's_Pride_Inn",
		},
		["maclure vineyards"] = {
			name = "Maclure Vineyards",
			short = "The Maclure Vineyards, located in southern Elwynn Forest, belong to the Maclure Family.",
			full = "The Maclure Vineyards, located in southern Elwynn Forest, belong to the Maclure Family. The Maclures are in a bitter rivalry with the nearby Stonefield Family, but despite their intense dislike of each other, a child from both families has fallen in love with each other in true Romeo and Juliet fashion. There is hope their love can bring the two families together, and there are several quests that involve the feuding families. The Maclure Vineyards are a great place to practice skinning as there are over a dozen boars in the vineyards alone.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["main hall northshire"] = {
			name = "Main Hall (Northshire)",
			short = "The Main Hall of Northshire Abbey, located in Northshire Valley in Elwynn Forest, serves as the entry of the abbey and grants access to the tower, Hall of Arms, and Library Wing.",
			full = "The Main Hall of Northshire Abbey, located in Northshire Valley in Elwynn Forest, serves as the entry of the abbey and grants access to the tower, Hall of Arms, and Library Wing. This is also where young human adventurers receive their first quests. Like in the rest of the abbey, Wounded Trainees can be found here in the rooms on the sides.",
			source = "https://warcraft.wiki.gg/wiki/Main_Hall_(Northshire)",
		},
		["mirror lake"] = {
			name = "Mirror Lake",
			short = "Mirror Lake is situated in western Elwynn Forest, near an orchard. It is rather small and features a beautiful waterfall.",
			full = "Mirror Lake is situated in western Elwynn Forest, near an orchard. It is rather small and features a beautiful waterfall. Although Mirror Lake would be an ideal spot for swimming or fishing, the Defias bandits that infest the area make such sports hazardous.\n\nAfter Azeroth had been victim to massive mystic struggles, which tore magic currents from once stable channels, the flow of magic in Stormwind City and Elwynn Forest was somehow altered. Consequently, the Wizard's Sanctum society sent a mage adventurer to Mirror Lake, in order to test its water for magical properties before those who drank from it would be adversely affected.\n\nThe sewers from the Stormwind Stockade exit into Mirror Lake and Varok Saurfang escaped through it. Dark Ranger Lyana and the Horde champion tracked Varok through his escape route.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Mirror Lake Orchard",
			short = "Mirror Lake Orchard is situated in western Elwynn Forest, on the southern banks of Mirror Lake. At some point, Defias bandits had taken possession of the orchard as well as the nearby cottage.",
			full = "Mirror Lake Orchard is situated in western Elwynn Forest, on the southern banks of Mirror Lake. At some point, Defias bandits had taken possession of the orchard as well as the nearby cottage.\n\nDuring the Elemental Unrest, the area was commandeered by Twilight's Hammer cultists, led by Overseer Sylandra. Alliance adventurers were tasked to infiltrate the cultists' activities.\n\nIt is possible they are the original residents of the Orchard.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Northshire Abbey",
			short = "Northshire Abbey is the seat of the Brotherhood of Northshire, a religious order of clerics affiliated to the kingdom of Stormwind.",
			full = "Northshire Abbey is the seat of the Brotherhood of Northshire, a religious order of clerics affiliated to the kingdom of Stormwind. It is located in Northshire Valley, in the foothills of Elwynn Forest, with the town of Goldshire lying to the southwest. The abbey is comprised of three sections: the Main Hall, Hall of Arms, and Library Wing. It holds trainers for mages, priests, warriors, monks, and paladins, as well as a couple of quest givers. The warlock trainers haunt the small graveyard to the east of the main doors, while the rogue and hunter trainers can be found at the abbey's stable.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Northshire Valley",
			short = "Northshire Valley is a pristine valley in Elwynn Forest in which both Northshire Abbey and the Northshire Vineyards are located.",
			full = "Northshire Valley is a pristine valley in Elwynn Forest in which both Northshire Abbey and the Northshire Vineyards are located. This is where the human starting area is located, though the serene valley is visited by adventurers from all over the world.\n\nMarshal Douglas McBride of the Stormwind Guard acts as the commander of Northshire Abbey's garrison and is in charge of the defense of the valley.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Northshire Vineyards",
			short = "The Northshire Vineyards are located just east of the abbey in Northshire Valley.",
			full = "The Northshire Vineyards are located just east of the abbey in Northshire Valley.\n\nThe vineyards were originally taken over by the agents of the Defias Brotherhood and their leader, Garrick Padfoot. It was here that human players had their first encounter with the Brotherhood, fighting their minions and retrieving the stolen property of Milly Osworth.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Ridgepoint Tower",
			short = "Ridgepoint Tower is one of the scout towers of the Stormwind Guard in Elwynn Forest. These towers are well defended against any enemies who encroach into human lands.",
			full = "Ridgepoint Tower is one of the scout towers of the Stormwind Guard in Elwynn Forest. These towers are well defended against any enemies who encroach into human lands. Ridgepoint in particular serves as a watchpost against the advances of the gnolls and orcs from Redridge Mountains, undead from Duskwood, and the Defias from nearby camps.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Stone Cairn Lake",
			short = "Stone Cairn Lake is situated in northeastern Elwynn Forest, and holds one large island that gives the lake a characteristic ring shape.",
			full = "Stone Cairn Lake is situated in northeastern Elwynn Forest, and holds one large island that gives the lake a characteristic ring shape. The lake is named after Heroes' Vigil, the stone cairn monument erected upon the island to commemorate the huge loss of life during the First War against the orcs.\n\nWhile the lake has previously been a safe place to make pilgrimages to, it has now fallen into the hands of Rogue Wizards who have settled on the island. The water also holds a tribe of murlocs who have raised crude structures on the southern banks of the lake. This area has possibly the highest concentration of Copper in Elwynn.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "Stonefield Farm",
			short = "The Stonefield Farm is one of two rival farmsteads in southern Elwynn Forest. The Stonefield family is in a bitter rivalry with the nearby Maclure family.",
			full = "The Stonefield Farm is one of two rival farmsteads in southern Elwynn Forest. The Stonefield family is in a bitter rivalry with the nearby Maclure family. Despite their intense dislike of each other, a child from each family has fallen in love with one another in true \"Romeo and Juliet\" fashion. There is hope their love can bring the two families together and, to that end, there are several quests that involve the feuding families.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["stormwind city"] = {
			name = "Stormwind City",
			short = "Stormwind City, also known as New Stormwind or simply Stormwind, is the capital city of the eponymous kingdom of Stormwind and the largest human city on Azeroth.",
			full = "Stormwind City, also known as New Stormwind or simply Stormwind, is the capital city of the eponymous kingdom of Stormwind and the largest human city on Azeroth. Located north of Elwynn Forest on Azeroth region's northwest coast, it has become one of the last great human cities after the Third War, and embodies the heart of the Alliance. Stormwind's willingness to work with others to find diplomatic solutions stands out as one of its true strengths. Its citizens hold fast to the principles of honor and justice as they defend their settlements and the Alliance against any aggressors.\n\nNo city better demonstrates human determination than Stormwind. Destroyed by the Orcish Horde during the First War, the capital was painstakingly reconstructed by the Stonemasons' Guild after the Second War. From the magnificent Cathedral of Light, which serves as a major spiritual hub, to the awe-inspiring Valley of Heroes, which commemorates the sacrifices of Stormwind's loyal champions, the city truly represents the courageous heart of humanity, and serves as a bastion of the Holy Light.\n\nThe Stormwind City Guard are the law enforcement and protectors of Stormwind City, keeping the peace within the city's walls.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
		},
		["stormwind gate"] = {
			name = "Stormwind Gate",
			short = "Stormwind Gate is a massive gate that separates Stormwind City from Elwynn Forest. It is located between Elwynn Forest and the Valley of Heroes.",
			full = "Stormwind Gate is a massive gate that separates Stormwind City from Elwynn Forest. It is located between Elwynn Forest and the Valley of Heroes. Signs can be found throughout the human capital city pointing to Stormwind Gate. The gates are of course always open to allow players to travel in and out of the city. Two Stormwind City Guards stand just outside the gate (Elwynn Forest zone) and two stand just inside the gate (Stormwind City zone). Two Stormwind City Guards also patrol from one side of the Valley of Heroes (General Hammond Clay) to the other side (Stormwind Gate).\n\nIt's also the place for Alliance's holidays such as Hallow's End and Love is in the Air.\n\nDuring the third invasion of the Burning Legion, the gate was extra-protected by its guards, but the Uncrowned member still managed to enter it.\n\nDuring the War of the Thorns, refugees from Darnassus were spread through the city, spilling out most of the way to Goldshire.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Gate",
		},
		["thunder falls"] = {
			name = "Thunder Falls",
			short = "Thunder Falls is a narrow ravine, located in the mountains of north-western Elwynn Forest.",
			full = "Thunder Falls is a narrow ravine, located in the mountains of north-western Elwynn Forest. A steep path leading up to the ravine can be found on the right of Mirror Lake's waterfall where there is a small rural cottage and a few bandits, an anvil and a cozy fire, along with a small pier and boat at the river next to the house. If the river is followed it will eventually wind into another waterfall that empties near the border of Westfall. The bottom of the waterfall can be reached from above by carefully navigating through the hilly terrain.\n\nThunder Falls is quite unusual in the sense that it is a ravine with double-sided waterfall ends. The falls are fed by a third, inaccessible waterfall from the cliffs on the northern side of the mountains.\n\nIt is here you fish [Violet Perch], for [10-90 Daily] Thunder Falls.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Tower of Azora",
			short = "The Tower of Azora is a small mage tower in central Elwynn Forest. The tower is run by a number of servants of Azora, who all appear to be gnomes, and who are in turn presided over by the Archmage of Azora, Theocritus.",
			full = "The Tower of Azora is a small mage tower in central Elwynn Forest. The tower is run by a number of servants of Azora, who all appear to be gnomes, and who are in turn presided over by the Archmage of Azora, Theocritus. The denizens of the tower are in a constant feud with the inhabitants of the Tower of Ilgalar in Redridge Mountains, ruled over by the evil sorcerer Morganth. The two towers are constantly spying on one another through magical means.\n\nInside the tower are several vendors and an enchanting trainer.\n\nAn interview with the servants of Azora in the Gadgetzan Times reveals that many things straying too near the tower are adversely affected by its magical aura, so the servants often have to battle living buckets and mutant butterflies.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Westbrook Garrison",
			short = "Westbrook Garrison is a barracks of the Stormwind Guard located in Forest's Edge, on the western end of Elwynn Forest, near the border with Westfall.",
			full = "Westbrook Garrison is a barracks of the Stormwind Guard located in Forest's Edge, on the western end of Elwynn Forest, near the border with Westfall.\n\nBecause of the corruption and political instability caused by Lady Katrana Prestor, the garrison lived through difficult times when they had to deal with an increasing gnoll and thief activity coming from Westfall. With the bulk of the Stormwind Army abroad, they barely had enough men to keep the roads of the region safe. At some point, Deputy Rainer requested more Stormwind soldiers from Marshal Dughan in Goldshire, who instead sent Alliance adventurers as reinforcements. With their help, the garrison fought the Riverpaw pack who infested the woods south of the guard tower.\n\nSeveral wanted posters at the garrison gave the mission to kill Hogger, the chieftain of the Riverpaw gnolls who has overpowered all attempts at his capture.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Deadwind Pass: 20 subzones
	[1430] = {
		["abandoned kirin tor camp"] = {
			name = "Abandoned Kirin Tor Camp",
			short = "Located in the craggy hills just to the west of Karazhan, on the border with Duskwood, the Abandoned Kirin Tor Camp is, as the name suggests, a Kirin Tor camp that has been abandoned.",
			full = "Located in the craggy hills just to the west of Karazhan, on the border with Duskwood, the Abandoned Kirin Tor Camp is, as the name suggests, a Kirin Tor camp that has been abandoned. Arcane Hunters and Excited Mana Scavengers roam around. An old circle of power is still there.\n\nThe camp was used an unknown number of years prior to the First War by Arrexis, a member of the Council of Tirisfal who was researching Karazhan. Arrexis found a way to stop the warping of space caused by the tower from happening within special wards, but while bringing the wards up reality was weakened. Medivh, who was possessed by Sargeras and secretly killing members of the Council of Tirisfal in \"accidents\", encouraged Arrexis to try his ritual on demonic realms. Arrexis caught the attention of the eredar Balaadur. The catastrophe ended with Arrexis and all of his apprentices dead, Balaadur taking [Ebonchill], Daio exiled from the Kirin Tor for his part in it, and all records of Arrexis stripped from Kirin Tor records so that no one would repeat his mistakes.\n\nMerina was among the apprentices to come here with Arrexis.",
			source = "https://warcraft.wiki.gg/wiki/Abandoned_Kirin_Tor_Camp",
		},
		["alturus sanctum"] = {
			name = "Alturus' Sanctum",
			short = "Alturus' Sanctum is the sanctum of Archmage Alturus, a member of the Violet Eye, the group of Kirin Tor agents who were spying on Medivh and Karazhan.",
			full = "Alturus' Sanctum is the sanctum of Archmage Alturus, a member of the Violet Eye, the group of Kirin Tor agents who were spying on Medivh and Karazhan. When Khadgar was an apprentice to Medivh, he would sometimes come here to work with Alturus on a piece of the [Archmage's Prismatic Disc] entrusted to him by Archmage Antonidas. The portal to it is located in the Master's Cellar in Deadwind Pass.",
			source = "https://warcraft.wiki.gg/wiki/Alturus'_Sanctum",
		},
		["aridens camp"] = {
			name = "Ariden's Camp",
			short = "Ariden's Camp is a deserted campsite found just north of the main road passing through Deadwind Pass from Duskwood to the Swamp of Sorrows.",
			full = "Ariden's Camp is a deserted campsite found just north of the main road passing through Deadwind Pass from Duskwood to the Swamp of Sorrows. Ariden was the leader of the Dark Riders, and this was the camp he set up before being cursed, from which he attempted to sell Medivh's fake artifacts.\n\nIn Season of Discovery, a Dalaran Agent of the Violet Eye traveled here to investigate after several powerful artifacts disappeared from the Kirin Tor's vaults in Dalaran. Unable to feel the presence of the Dark Riders of Karazhan in Deadwind Pass, she tasked adventurers to bring her any of the stolen artifacts they found during their travels.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Deadman's Crossing",
			short = "Deadman's Crossing is the eastern crossroads leading west to Duskwood, east towards the Swamp of Sorrows, and south to Karazhan in Deadwind Pass.",
			full = "Deadman's Crossing is the eastern crossroads leading west to Duskwood, east towards the Swamp of Sorrows, and south to Karazhan in Deadwind Pass. It is marked with a hangman's tree still bearing a pair of corpses, as well as a signpost reading \"Turn Back!\" and \"Abandon hope, all ye who enter here.\"\n\nDespite the forbidding warnings and the high level of monsters in other areas in Deadwind Pass, Deadman's Crossing is perfectly safe for low-level adventurers to run through on their way to the Swamp of Sorrows, provided that they don't stray off the road.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Deadwind Ravine",
			short = "Deadwind Ravine is a craggy cleft running through the mountains south towards Karazhan in Deadwind Pass.",
			full = "Deadwind Ravine is a craggy cleft running through the mountains south towards Karazhan in Deadwind Pass. The western road runs through the ravine on the upper level, and at the end of the area lies the southern bridge nearby the ominous tower.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["forgotten crypt"] = {
			name = "Forgotten Crypt",
			short = "The Forgotten Crypt lies behind the tower of Karazhan, accessed in the cemetery at Morgan's Plot in Deadwind Pass. For the catacomb that has an entrance at the base of the tower itself, see Karazhan Catacombs.",
			full = "The Forgotten Crypt lies behind the tower of Karazhan, accessed in the cemetery at Morgan's Plot in Deadwind Pass. For the catacomb that has an entrance at the base of the tower itself, see Karazhan Catacombs.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Crypt",
		},
		["groshgok compound"] = {
			name = "Grosh'gok Compound",
			short = "The Grosh'gok Compound is an ogre mound located in the Vice inhabited by the Deadwind ogres. It is the southernmost and largest of the multiple caves in the Vice.",
			full = "The Grosh'gok Compound is an ogre mound located in the Vice inhabited by the Deadwind ogres. It is the southernmost and largest of the multiple caves in the Vice.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Karazhan (a.k.a. Medivh's Tower) is an abandoned citadel (or castle) located on a nexus of ley lines in southern Deadwind Pass.",
			full = "Karazhan (a.k.a. Medivh's Tower) is an abandoned citadel (or castle) located on a nexus of ley lines in southern Deadwind Pass. The tower is best known for its last known occupant -- Medivh, the last Guardian of Tirisfal. After Medivh was killed by Khadgar, Anduin Lothar, and Garona, the tower sealed itself off from the rest of the world. But recently, Karazhan has reawakened -- an evil presence has taken the tower as its own, its halls crawling with spirits and demons, and with the Shade of Medivh, his power being so great that his magic still echoes through the halls of Karazhan.\n\nIt is impossible to set eyes upon Karazhan without reflecting on the dark saga of its master. As befitting his title, the Last Guardian of Tirisfal had amassed a vast collection of writings and artifacts that dwarfs even that of the Kirin Tor. The tower is vast, dangerous, with ghosts everywhere, and where some of the world's most powerful and dangerous artifacts are stored, brought for years by the Dark Riders. Following the third invasion of the Burning Legion, Khadgar moved into the tower, seeking knowledge to save Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["karazhan catacombs"] = {
			name = "Karazhan Catacombs",
			short = "Karazhan Catacombs are the large catacombs under Karazhan in Deadwind Pass accessed via a gate at the bottom of the tower itself.",
			full = "Karazhan Catacombs are the large catacombs under Karazhan in Deadwind Pass accessed via a gate at the bottom of the tower itself. They acted as the main hideout for the Dark Riders and were where they brought all of their stolen artifacts. The [Ratts' Revenge] scenario is set in an instanced version of the catacombs. For the long-secret crypt that was made available to players in Legion in Morgan's Plot, see Forgotten Crypt.\n\nThis section concerns content related to Legion.\n\nSoon after the Battle for Broken Shore, Ariden stole the Scythe of Elune in Duskwood, a relic the Riders had been seeking for some time. He was followed to Karazhan not only by the druid adventurer, but also by a warlock adventurer seeking [Ulthalesh, the Deadwind Harvester], a death knight adventurer seeking [Apocalypse], and the priest Revil Kost who had dealt with the Dark Riders before. After they find clues as to his whereabouts at his old camp, Ariden was pursued into the Dark Riders' base of operations beneath Karazhan. He and his Dark Riders held them off, but though Ariden even claimed the artifacts they seek, he was defeated by the adventurers.\n\nAfter the battle, Revil Kost announced that the Dark Riders were defeated, and that he would reclaim the stolen artifacts and return them to their rightful owners.\n\nBefore the events of Black Empire Campaign, Wrathion intended to study the artifacts stored within the catacombs, continuing his journey to find a way to defeat the Old Gods. When the adventurers went to Karazhan in search of the Black Prince, one of his agent stood watch over the cave, but was killed by Sleepless operatives led by X'korr the Compelling who infiltrated the area.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan_Catacombs",
		},
		["karazhan raid"] = {
			name = "Karazhan (raid)",
			short = "The Karazhan raid instance is located in the abandoned citadel (or castle) of the same name, which is located in southern Deadwind Pass in the Eastern Kingdoms.",
			full = "The Karazhan raid instance is located in the abandoned citadel (or castle) of the same name, which is located in southern Deadwind Pass in the Eastern Kingdoms.\n\nThe raid is a single huge wing (containing seven stories and 17 map pages) containing both the lower guest complex and upper tower, with some shortcuts. It encompasses twelve boss encounters, some scripted with different possibilities per week from 22 different NPCs. While the layout is largely non-linear, there are four essential bosses: Moroes, the Opera Event, The Curator, and the Chess Event. These four must be defeated in order, but all other bosses are optional. The final boss is Prince Malchezzar, as the tower's last known occupant -- Medivh's presence as the last Guardian of Tirisfal being somewhat absent due to his death. The tower has been sealed off from the rest of the world and is filled with spirits and demons, which are the main opponents in the instance.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan_(raid)",
		},
		["masters cellar"] = {
			name = "Master's Cellar",
			short = "The Master's Cellar is an area riddled with ghosts in the southernmost portion of the Deadwind Pass, just south of Karazhan.",
			full = "The Master's Cellar is an area riddled with ghosts in the southernmost portion of the Deadwind Pass, just south of Karazhan. It is below the ruins of a small village, probably the former home of servants that worked in the nearby tower of Karazhan. Its lower section is called Lower Cellar.\n\nThere are two separate entrances to the Master's Cellar. One leads into a vast wine cellar, filled to the brim with Unliving Residents, Unliving Caretakers, Damned Souls, Restless Shades, and Wailing Spectres. The other leads into a similar cellar, but here the floor has collapsed into a cave system leading deep underground. The second cellar and cave system are also filled with the same type of undead, but there are no named or rare undead of any type to be found.\n\nThe place was infiltrated and Nalice killed by the adventurers on the orders of Wrathion.\n\nThis section concerns content related to Legion.\n\nDuring the third invasion of Azeroth, the Burning Legion forces took over the cellar during their invasion of Karazhan, and the entrances were guarded by Archmage Leryda and Archmage Alturus.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Morgan's Plot",
			short = "Morgan's Plot is a small decrepit church with a graveyard and crypt located in Deadwind Pass.",
			full = "Morgan's Plot is a small decrepit church with a graveyard and crypt located in Deadwind Pass. It can be found just behind Karazhan, and its graveyard serves as the respawn and spirit healer point for adventurers who die within the actual Karazhan instance. Lydia Accoste is found here.\n\nThe chapel itself was once inhabited by two Unliving Residents, and there was a third patrolling just down the hill.\n\nAegwynn and Cook are buried here, and Moroes and Medivh were before they were revived.\n\nThis section concerns content related to Legion.\n\nSince the third invasion of the Burning Legion, the place is now inhabited by Restless Spirits.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["paupers walk"] = {
			name = "Pauper's Walk",
			short = "The Pauper's Walk are long hallways which lead around the Forgotten Crypt. It is immediately accessed after you pass through the Well of the Forgotten.",
			full = "The Pauper's Walk are long hallways which lead around the Forgotten Crypt. It is immediately accessed after you pass through the Well of the Forgotten.",
			source = "https://warcraft.wiki.gg/wiki/Pauper's_Walk",
		},
		["pit of criminals"] = {
			name = "Pit of Criminals",
			short = "The Pit of Criminals is an area in the Forgotten Crypt where a pile of skeletons can be found.",
			full = "The Pit of Criminals is an area in the Forgotten Crypt where a pile of skeletons can be found.",
			source = "https://warcraft.wiki.gg/wiki/Pit_of_Criminals",
		},
		["sleeping gorge"] = {
			name = "Sleeping Gorge",
			short = "The Sleeping Gorge is a small chasm in eastern Deadwind Pass. One of the paths south to Karazhan runs through the gorge for a stretch before turning east into the Vice.",
			full = "The Sleeping Gorge is a small chasm in eastern Deadwind Pass. One of the paths south to Karazhan runs through the gorge for a stretch before turning east into the Vice.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["slough of dispair"] = {
			name = "Slough of Dispair",
			short = "The Slough of Dispair[sic] is an area in the Forgotten Crypt. It is an empty room with a hole in the middle.",
			full = "The Slough of Dispair[sic] is an area in the Forgotten Crypt. It is an empty room with a hole in the middle.",
			source = "https://warcraft.wiki.gg/wiki/Slough_of_Dispair",
		},
		["tome of the unrepentant"] = {
			name = "Tome of the Unrepentant",
			short = "The Tome[sic] of the Unrepentant is an area in the Forgotten Crypt where a large pool can be found. There are also a couple of graves.",
			full = "The Tome[sic] of the Unrepentant is an area in the Forgotten Crypt where a large pool can be found. There are also a couple of graves.",
			source = "https://warcraft.wiki.gg/wiki/Tome_of_the_Unrepentant",
		},
		["upside down sinners"] = {
			name = "Upside-down Sinners",
			short = "The Upside-down Sinners is an area in the Forgotten Crypt where humans are hanged upside down in the water with ropes tied to chains.",
			full = "The Upside-down Sinners is an area in the Forgotten Crypt where humans are hanged upside down in the water with ropes tied to chains.",
			source = "https://warcraft.wiki.gg/wiki/Upside-down_Sinners",
		},
		["vice"] = {
			name = "Vice",
			short = "The Vice is home to the Deadwind ogres. There are several Deadwind ogre mounds and camps in the area, scattered along the road to Karazhan in the southern area of Deadwind Pass.",
			full = "The Vice is home to the Deadwind ogres. There are several Deadwind ogre mounds and camps in the area, scattered along the road to Karazhan in the southern area of Deadwind Pass. Nobody knows why the ogres have chosen to settle in this desolate area with nothing but restless spirits and a few vultures for company.\n\nIt should also be noted that [Formula: Enchant Bracer - Superior Strength] drops off the Deadwind Warlocks of the area at a near 0.5% chance.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
		["well of the forgotten"] = {
			name = "Well of the Forgotten",
			short = "Well of the Forgotten is the first area in the Forgotten Crypt. The altar and the gate have been added in Legion.",
			full = "Well of the Forgotten is the first area in the Forgotten Crypt. The altar and the gate have been added in Legion.\n\nWarlocks get to come here for The Grimoire of the First Necrolyte in order to unlock the hidden skin for [Ulthalesh, the Deadwind Harvester].",
			source = "https://warcraft.wiki.gg/wiki/Well_of_the_Forgotten",
		},
	},
	-- Duskwood: 19 subzones
	[1431] = {
		["addles stead"] = {
			name = "Addle's Stead",
			short = "Addle's Stead is located in southwestern Duskwood, south of Raven Hill and west of the Vul'Gol Ogre Mound. It is one of the many abandoned farmsteads, presumably left behind when the darkness crept into Duskwood.",
			full = "Addle's Stead is located in southwestern Duskwood, south of Raven Hill and west of the Vul'Gol Ogre Mound. It is one of the many abandoned farmsteads, presumably left behind when the darkness crept into Duskwood. The farm is inhabited by Forlorn Spirits, presumably, spirits of dead Defias Brotherhood members who used to occupy the abandoned farm.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Beggar's Haunt",
			short = "Beggar's Haunt is an abandoned scout tower of the Stormwind Guard located in northeastern Duskwood, east of Manor Mistmantle and north of the road that leads into Deadwind Pass.",
			full = "Beggar's Haunt is an abandoned scout tower of the Stormwind Guard located in northeastern Duskwood, east of Manor Mistmantle and north of the road that leads into Deadwind Pass. It was once used by the Forsaken to conduct experiments, but now serves as a home to Abercrombie after Deathstalker Zraedus and Apothecary Faustin were killed or left.\n\nA twisting path leads from the tower to a small pool and waterfall, near which rests an unmarked grave with two large statues similar to the ones on the Dark Portal (See Knight's Hollow). Near the tower is another small cemetery with the Unknown Soldier.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Brightwood Grove",
			short = "Brightwood Grove is an area in Duskwood.",
			full = "Brightwood Grove is an area in Duskwood. The few buildings that stood at the edge of the grove lie in ruins and Nightbane worgen prowl the dark fields, erecting crude camps and hungrily attacking anyone who come too close. Young Alliance-based adventurers are often sent here to slay some of the wolf men to better control their numbers. The location is just west of Darkshire.\n\nIts only inhabitants were Med'an and Meryl Winterstorm and few individuals knew about them, such as Garona Halforcen and Koron. Twilight's Hammer cultists attacked their home and kidnapped Garona.\n\nDuring the Burning Legion's third invasion, the Twilight's Hammer cultists led by Twilight Lord Urgrok returned to the area and took over a Nightbare camp. An adventurer of the Conclave arrived at the camp and killed the cultists.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "Darkened Bank",
			short = "The Darkened Bank stretches along the northern shore of Duskwood. It runs from the far western edge of Duskwood east to the bridge that connects Duskwood to the Redridge Mountains.",
			full = "The Darkened Bank stretches along the northern shore of Duskwood. It runs from the far western edge of Duskwood east to the bridge that connects Duskwood to the Redridge Mountains. At the western edge of The Darkened Bank is a small camp with two refugees, Sven Yorgen and Lars, where you can receive a handful of quests that involve killing the weaker creatures in Duskwood. This is a good place to begin questing in Duskwood and is easily reached by swimming straight south from the far southwest corner of Elwynn Forest.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Darkshire",
			short = "Darkshire (formerly known as Grand Hamlet) is a once-quaint little woodland village located in Duskwood, but it has fallen on literally dark times.",
			full = "Darkshire (formerly known as Grand Hamlet) is a once-quaint little woodland village located in Duskwood, but it has fallen on literally dark times. The surrounding forests have been corrupted after the death of Medivh, cloaking the land in constant darkness for decades. The walking dead choke the graveyards, and foul creatures known as worgen have overrun many of the outlying farmsteads. Even worse, the political instability orchestrated by Lady Katrana Prestor in Stormwind City caused the abandonment of the town and its surrounding areas by the authorities and the Stormwind Army. This has left the stubborn people of Duskwood little choice but to defend themselves. Besides its town hall, the village also has a blacksmith and an inn.\n\nPrior to the third invasion of the Burning Legion and their adherence to the Veiled Hand cult, Lord Ello Ebonlocke and the Council of Darkshire ruled the town while Althea Ebonlocke led the Night Watch, a local militia that works to keep the roads free and the creeping darkness that plagues the land back for as long as possible. The people of Duskwood are a jumpy and suspicious lot, but they are desperate for any aid they can get against the evil that now surrounds their homes.\n\nBefore their treason, the Council of Darkshire was responsible for enforcing justice, such as ordering death sentences for those who sold bodies from Duskwood cemeteries. In the town hall, Clerk Daltry keeps records on the people that live and pass through the town, although some of his records are a little outdated. Tobias Mistmantle had to hide his \"true self\" from the citizens who react poorly to worgen.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["darkshire town hall"] = {
			name = "Darkshire Town Hall",
			short = "The Darkshire Town Hall is the seat of rule for Darkshire's mayor.",
			full = "The Darkshire Town Hall is the seat of rule for Darkshire's mayor. Before their treason to join the Veiled Hand, the town hall housed Lord Ello Ebonlocke, the former mayor, and the members of the Darkshire Council as well as historians and clerks. It is located on the western edge of the Darkshire town square. In the town hall, Clerk Daltry keeps records of the people that live and pass through the town, although some of his records are a little outdated.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire_Town_Hall",
		},
		["dawning wood catacombs"] = {
			name = "Dawning Wood Catacombs",
			short = "The Dawning Woods Catacombs lie beneath the Raven Hill Cemetery in Duskwood. These twisting catacombs are home to the most powerful undead in the region.",
			full = "The Dawning Woods Catacombs lie beneath the Raven Hill Cemetery in Duskwood. These twisting catacombs are home to the most powerful undead in the region. Many quests take Alliance characters into the catacombs. It is best to enter with a group, as a single adventurer can get quickly overwhelmed by the swarms of undead lurking in the darkness. The catacombs have two separate entrances. The eastern one leads into a den of ghouls, of the most disease-riddled and ferocious kind. The western entrance leads into a hall of skeletons, guarding the tombs of their former brethren.\n\nThis section concerns content related to Legion.\n\nA shadow altar is located within the catacombs which was used by the Conclave to find Natalie Seline's ghost.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nShe was stopped by Mathias Shaw and Flynn Fairwind, who killed her and fled with the sacred torch while being pursued by the undead.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Forlorn Rowe",
			short = "The Forlorn Rowe is located in northwestern Duskwood, on the northern edge of Raven Hill Cemetery.",
			full = "The Forlorn Rowe is located in northwestern Duskwood, on the northern edge of Raven Hill Cemetery. It is a hill cloaked in an ominous darkness, upon which the home of Morbent Fel rests, the powerful necromancer who rules the forest's undead creatures through evil arcane magic. Alliance-aligned adventurers will need to do a lot of running and fighting in order to obtain the only special weapon that could stop him.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nFollowing Morbent Fel's defeat against the Adventurers, Commander Ladimore placed the Torch of Holy Flame right in front of the necromancer's home to dispelling dark enchantments and keeping the undead docile in Duskwood.\n\nBut she was defeated by Mathias Shaw and Flynn Fairwind who purifies and brings back the torch to the hill to keep the undead docile.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "Hushed Bank",
			short = "The Hushed Bank is the stretch of Duskwood along the western river. It runs from where the river forks and the three corners of Westfall, Elwynn Forest, and Duskwood meet south to Stranglethorn Vale.",
			full = "The Hushed Bank is the stretch of Duskwood along the western river. It runs from where the river forks and the three corners of Westfall, Elwynn Forest, and Duskwood meet south to Stranglethorn Vale. The covered bridge connecting Duskwood and Westfall is also located on the Hushed Bank. Lars and Sven Yorgen could once be found on the northern corner of the Hushed Bank. It was also inhabited by spiders and wolves.\n\nThe camp of Lars and Sven had been taken over by Grave Robbers, while the typical beasts have been replaced with bears and owls.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Manor Mistmantle",
			short = "Manor Mistmantle is the stead of Stalvan Mistmantle. It is located in northeastern Duskwood, north of Darkshire and west of Beggar's Haunt.",
			full = "Manor Mistmantle is the stead of Stalvan Mistmantle. It is located in northeastern Duskwood, north of Darkshire and west of Beggar's Haunt. Stalvan Mistmantle was a former school teacher and personal tutor who is now an agent of the undead. The manor grounds are rotten and overrun by Stalvan's ghoulish minions. The only sign of life on the property is a single flower in the garden, known as the [Tear of Tilloa].\n\nAfter Stalvan's death, the manor became the base of Duskwood's branch of the Wolf Cult.\n\nThey also killed all the ghouls. A champion of Gilneas came to the area to obtain the fangs from the wolves and to collect the rare plant Elune's Grace.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Raven Hill",
			short = "Raven Hill is an abandoned town located in western Duskwood, north of Addle's Stead and south of the Raven Hill Cemetery.",
			full = "Raven Hill is an abandoned town located in western Duskwood, north of Addle's Stead and south of the Raven Hill Cemetery. Though once all but empty, several worgen have taken up residence here in their search for a cure to the worgen curse.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Raven Hill Cemetery",
			short = "Raven Hill Cemetery is the sprawling graveyard located north of the Alliance controlled town of Raven Hill in Duskwood.",
			full = "Raven Hill Cemetery is the sprawling graveyard located north of the Alliance controlled town of Raven Hill in Duskwood. The cemetery is crawling with scores of undead as well as massive spiders and gangs of grave robbers who will attack anyone interrupting their morbid tasks. The hill in the northwest corner of the cemetery is Forlorn Rowe, once the home of Morbent Fel. Through the cemetery, the undead Mor'Ladim patrols the cemetery and spells certain doom for adventurers he catches unaware.\n\nThe cemetery wasn't always so big, growing to dominate much of the area only after the region's corruption by dark forces. It is also currently abandoned, but wasn't always as such. When Morgan Ladimore came back from the Third War and saw the grave of his wife and children, he wept and murdered a trio of the cemetery's attendants.\n\nThis section concerns content related to Legion.\n\nAt the time of the third invasion of the Burning Legion, the few remaining followers of the Cult of Forgotten Shadows were lingering at the Raven Hill Cemetery, near the grave of their leader, Natalie Seline. The Conclave later sent here the High Priest to restore the cult. After her spirit was pulled from the Void and restored to her body, Natalie and the cultists traveled to the Netherlight Temple.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nFollowing Morbent Fel's defeat, the Torch of Holy Flame has been placed by Commander Ladimore in front of the necromancer's home to dispelling dark enchantments and keeping the undead docile in the cemetery.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "Roland's Doom",
			short = "Roland's Doom is a mine located in southeastern Duskwood, due east of the Rotting Orchard. It is here that the night elven priestess Velinde Starsong, the former wielder of the Scythe of Elune, died.",
			full = "Roland's Doom is a mine located in southeastern Duskwood, due east of the Rotting Orchard. It is here that the night elven priestess Velinde Starsong, the former wielder of the Scythe of Elune, died. Interacting with the mound of dirt there can invoke her spirit. One day, Jitters found the Scythe, summoning more worgen and in time the Dark Riders upon Duskwood and Darkshire, condemning them to permanent darkness. The mine is now the location of Gutspill and Nefaru of the Nightbane pack, who lead the worgen at the Rotting Orchard.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "Rotting Orchard",
			short = "The Rotting Orchard is located in southern Duskwood -- east of the Yorgen Farmstead, west of the Tranquil Gardens Cemetery, and southwest of Darkshire.",
			full = "The Rotting Orchard is located in southern Duskwood -- east of the Yorgen Farmstead, west of the Tranquil Gardens Cemetery, and southwest of Darkshire. The orchard has become home to many ravenous worgen of the Nightbane pack, who now occupy the orchard's dilapidated buildings and make camps, where the Nightbane Shadow Weavers practice their magic and Nightbane Stalkers keep watch in the shadows. The current packleader, Marus, patrols the area between the orchard and his den.\n\nA version of the orchard also exists within the Emerald Dream. Here, Nightmare-corrupted worgen protect the [Shadowscythe] under the command of Amokarok.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["scarlet raven tavern"] = {
			name = "Scarlet Raven Tavern",
			short = "The Scarlet Raven Tavern (or the Scarlet Raven) is located in the town of Darkshire in Duskwood.",
			full = "The Scarlet Raven Tavern (or the Scarlet Raven) is located in the town of Darkshire in Duskwood. Although the hearth has been kept warm, it now holds a more morose crowd while the darkness presses in on the tavern outside, which is downright bad for business. The inn features several quest givers, as well as a few vendors, and a Hero's Call Board at the entrance.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Raven_Tavern",
		},
		["tranquil gardens cemetery"] = {
			name = "Tranquil Gardens Cemetery",
			short = "The Tranquil Gardens Cemetery lies slightly southeast of Darkshire in Duskwood. While the presence of many undead has made the cemetery anything but tranquil, the undead here are the weakest you will find in Duskwood.",
			full = "The Tranquil Gardens Cemetery lies slightly southeast of Darkshire in Duskwood. While the presence of many undead has made the cemetery anything but tranquil, the undead here are the weakest you will find in Duskwood. The first quests The Night Watch give you involve dispatching the undead in this area. The Insane Ghoul is also located here, either inside the ruined church or wandering about outside. Just north of the cemetery lies Blind Mary's house.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Twilight Grove",
			short = "The Twilight Grove sits in the middle of Duskwood and contains an unnamed great tree. It is home to one of the four portals to the Emerald Dream and was once guarded by the lieutenants of Ysera's green dragonflight.",
			full = "The Twilight Grove sits in the middle of Duskwood and contains an unnamed great tree. It is home to one of the four portals to the Emerald Dream and was once guarded by the lieutenants of Ysera's green dragonflight. The great tree was planted by Fandral Staghelm and his followers from one of Nordrassil's branches, in order to stem the tide of saronite seeping up from the land.\n\nThe Twilight Grove also contains a moonwell and a night elf gazebo. The other three dream portals can be found in Feralas, the Hinterlands, and Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Vul'Gol Ogre Mound",
			short = "The Vul'Gol Ogre Mound is a small basin in southern Duskwood, which is completely overrun by Splinter Fist ogres led by Zzarc'Vul, after which the mound was named.",
			full = "The Vul'Gol Ogre Mound is a small basin in southern Duskwood, which is completely overrun by Splinter Fist ogres led by Zzarc'Vul, after which the mound was named. It is located just to the southwest of where the main road through Duskwood splits and runs south into Stranglethorn Vale. Humans used to live in the basin, as evidenced by the ruined farmhouses.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "Yorgen Farmstead",
			short = "The Yorgen Farmstead is an abandoned farm in southern Duskwood. The farm was once owned by Sven Yorgen who can be found at the small camp on the Darkened Bank.",
			full = "The Yorgen Farmstead is an abandoned farm in southern Duskwood. The farm was once owned by Sven Yorgen who can be found at the small camp on the Darkened Bank. The farmstead is now in the hands of the Defias Brotherhood. Be wary when approaching the farmstead, as many stealthed Defias assassins patrol the area.\n\nA version of the farmstead also exists within the Emerald Dream. Here, Nightmare-corrupted dragonkin can be found under the command of Ylanthrius, some of them protecting dragon eggs.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 18 subzones
	[1432] = {
		["algaz station"] = {
			name = "Algaz Station",
			short = "Algaz Station is a dwarven outpost in Loch Modan where many dwarven mountaineers are stationed. It is located just east of the North Gate Pass, and south of Dun Algaz, from which it takes its name.",
			full = "Algaz Station is a dwarven outpost in Loch Modan where many dwarven mountaineers are stationed. It is located just east of the North Gate Pass, and south of Dun Algaz, from which it takes its name. Mountaineer Stormpike can be found here, as well as an armorer named Gothor Brumn.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "Dun Algaz (or Algaz Gate) is the tunneled mountain pass area between Loch Modan and the Wetlands, as well as the name of a stronghold located in the pass.",
			full = "Dun Algaz (or Algaz Gate) is the tunneled mountain pass area between Loch Modan and the Wetlands, as well as the name of a stronghold located in the pass. It is bordered by Algaz Station in Loch Modan and Slabchisel's Survey in the Wetlands.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Farstrider Lodge",
			short = "The Farstrider Lodge (or Farstrider's Lodge) is a hunters' lodge located in southeastern Loch Modan. It houses several merchants and quest givers, as well as a hunter trainer and a pet trainer.",
			full = "The Farstrider Lodge (or Farstrider's Lodge) is a hunters' lodge located in southeastern Loch Modan. It houses several merchants and quest givers, as well as a hunter trainer and a pet trainer. Judging by its architecture, it is of high elven make, although there is only one known high elf residing there now -- its other inhabitants being humans and dwarves.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Grizzlepaw Ridge",
			short = "Grizzlepaw Ridge is a mountainous area located south of Thelsamar and east of Stonesplinter Valley in the dwarven territory of Loch Modan.",
			full = "Grizzlepaw Ridge is a mountainous area located south of Thelsamar and east of Stonesplinter Valley in the dwarven territory of Loch Modan. It is inhabited by a large pack of bears, and most notably, the ferocious Ol' Sooty, who occasionally wanders down from his lair to the base of the valley, pouncing upon anyone unfortunate to irritate him.\n\nGorick Guzzledraught is also here.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Ironband's Excavation Site",
			short = "Ironband's Excavation Site is located in southeastern Loch Modan, south of the Loch and southwest of Farstrider Lodge.",
			full = "Ironband's Excavation Site is located in southeastern Loch Modan, south of the Loch and southwest of Farstrider Lodge.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["ironwing cavern"] = {
			name = "Ironwing Cavern",
			short = "Ironwing Cavern is located south Ironband's Excavation Site in Loch Modan. The large cave is filled with hostile Proto-Striders (including Optimo) and Haywire Battle-Chickens.",
			full = "Ironwing Cavern is located south Ironband's Excavation Site in Loch Modan. The large cave is filled with hostile Proto-Striders (including Optimo) and Haywire Battle-Chickens. Towards the back of the cavern is a friendly dead mob called Rusted Skystrider.",
			source = "https://warcraft.wiki.gg/wiki/Ironwing_Cavern",
		},
		["loch"] = {
			name = "The Loch",
			short = "The Loch is the single most prominent feature of the dwarven territory of Loch Modan.",
			full = "The Loch is the single most prominent feature of the dwarven territory of Loch Modan. It was once the largest body of water on the continent of Khaz Modan, and third in size in the entire known world after the Lordamere and Darrowmere lakes. Since then, the Twilight's Hammer has set up camp on two of the islands in the middle of the lakebed.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Mo'grosh Stronghold",
			short = "Mo'grosh Stronghold is a set of ogre-infested caves located in northeastern Loch Modan. The Mo'grosh ogres number several darkmaulers and earthbenders, and serve the Twilight's Hammer.",
			full = "Mo'grosh Stronghold is a set of ogre-infested caves located in northeastern Loch Modan. The Mo'grosh ogres number several darkmaulers and earthbenders, and serve the Twilight's Hammer. They are in progress of defiling the land with the elementium spikes, just as their neighbors did at the camp on the drained Loch, and must be stopped. The ogres are led by the disciple of Cho'gall himself, Gor'kresh.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "North Gate Pass",
			short = "North Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east.",
			full = "North Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east. It is frequently traveled by adventurers coming from or going to the Wetlands, as this pass is the closest to the descent from the Loch. North Gate Pass is also the location of the guard station of North Gate Outpost.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Silver Stream Mine",
			short = "The Silver Stream Mine is located in the northern part of Loch Modan, east of Algaz Station, and southwest of Stonewrought Dam.",
			full = "The Silver Stream Mine is located in the northern part of Loch Modan, east of Algaz Station, and southwest of Stonewrought Dam. Although it traditionally was a bountiful source of silver for the dwarves of Ironforge, long ago it eventually became tapped out. It was then converted into a storage depot by the Miners' League. The mine is also the only known source of the Charged Rift Gems used to make mage robes.\n\nIt was recently been completely taken over by aggressive Tunnel Rat kobolds who seek the mine's resources for themselves.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate outpost"] = {
			name = "South Gate Outpost",
			short = "South Gate Outpost is a dwarven settlement built in western Loch Modan. It lies in the middle of the South Gate Pass, which links Dun Morogh in the west with Loch Modan in the east.",
			full = "South Gate Outpost is a dwarven settlement built in western Loch Modan. It lies in the middle of the South Gate Pass, which links Dun Morogh in the west with Loch Modan in the east.\n\nThe mountaineers stationed at the outpost have cleared out most of the encroaching wildlife, and thus do not face the same amount of problems as do the dwarves of North Gate Outpost. Many travelers pass through the outpost on their way to or from Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "South Gate Pass",
			short = "South Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east.",
			full = "South Gate Pass connects Dun Morogh in the high mountains to the west with Loch Modan in the lower mountains to the east. It is frequently traveled by adventurers coming from or going to Thelsamar, as this pass is the closest to the dwarven town. South Gate Pass is also the location of the guard station of South Gate Outpost.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Stonesplinter Valley",
			short = "Stonesplinter Valley is a valley carved among the mountains in southwestern Loch Modan. Once a pristine setting, the valley is now crawling with hostile Stonesplinter troggs.",
			full = "Stonesplinter Valley is a valley carved among the mountains in southwestern Loch Modan. Once a pristine setting, the valley is now crawling with hostile Stonesplinter troggs. Adventurers wishing to befriend the local dwarves will find plenty of work hunting the foul humanoids, and the most ambitious heroes strike deep into the heart of the valley in attempts to rid the region of the trogg leader, Grawmug.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Stonewrought Dam",
			short = "The massive Stonewrought Dam is located east of Dun Algaz pass, along Loch Modan's northern border.",
			full = "The massive Stonewrought Dam is located east of Dun Algaz pass, along Loch Modan's northern border.\n\nOne of the most impressive wonders of the world, few know that it is the work of a Dark Iron dwarf. Indeed, its construction was overseen by the great Dark Iron architect Franclorn Forgewright, who invented the \"stonewrought\" method.\n\nThe construction dams up the Loch, more than doubling its original size. The dam also creates the flooded plains of the Wetlands, which previously were mostly underwater.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Stoutlager Inn",
			short = "The Stoutlager Inn in Thelsamar features a few quest givers and several vendors, among them an innkeeper with the usual services.",
			full = "The Stoutlager Inn in Thelsamar features a few quest givers and several vendors, among them an innkeeper with the usual services. The inn is a popular place to spend some quality time with one's guildmates, drinking and chatting. It is one of the most popular places to go in Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Thelsamar is a dwarven town on the west side of Loch Modan, located north of Grizzlepaw Ridge and northeast of Stonesplinter Valley.",
			full = "Thelsamar is a dwarven town on the west side of Loch Modan, located north of Grizzlepaw Ridge and northeast of Stonesplinter Valley. The town has a gryphon roost, an inn, several vendors, as well as class and profession trainers. A north-south road runs just west of town, leading to the passes into Dun Morogh and the Wetlands.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["twilight camp"] = {
			name = "Twilight Camp",
			short = "Twilight Camp is an forward outpost of Twilight's Hammer clan in Loch Modan.",
			full = "Twilight Camp is an forward outpost of Twilight's Hammer clan in Loch Modan. The sky is dark and the ground is scorched and filled with the elementium spikes and characteristical architecture like the one found in Twilight Highlands above.\n\nIn the camp there is a landshaping device that could devastate the region even further.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Camp",
		},
		["valley of kings"] = {
			name = "Valley of Kings",
			short = "The Valley of Kings is located in the southwestern corner of the dwarven territory of Loch Modan, just west of Stonesplinter Valley.",
			full = "The Valley of Kings is located in the southwestern corner of the dwarven territory of Loch Modan, just west of Stonesplinter Valley. When going to or from Dun Morogh by the South Gate Pass, adventurers pass through a piece of this verdant valley, which also is an important throughway to the dangerous region known as the Searing Gorge. The gate to the gorge remains under lock and guard, and adventurers have to prove their power to Mountaineer Pebblebitty before she will grant them full access through the gate.\n\nThe main feature of this area is the two large statues of Dwarven kings Madoran Bronzebeard and Khardros Wildhammer. After the deaths of Madoran and Khardros, their sons jointly commissioned two great statues in honor of their fathers. The two statues would stand guard over the pass into the southlands, which had become volcanic in the wake of Ragnaros' scorching presence. They served as both a warning to all who would attack the dwarven kingdoms, and as a reminder of what price the Dark Irons paid for their crimes.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Redridge Mountains: 24 subzones
	[1433] = {
		["althers mill"] = {
			name = "Alther's Mill",
			short = "Alther's Mill is an abandoned lumber mill located northeast of Lakeshire in the Redridge Mountains region of Stormwind.",
			full = "Alther's Mill is an abandoned lumber mill located northeast of Lakeshire in the Redridge Mountains region of Stormwind.\n\nThis relatively backwater area was once overrun by spiders, buzzards and the occasional stray orc. Most folks passed through on the way to Stonewatch Keep. It has since been taken over by Blackrock clan of orcs who have a very large worg kennel here. Overseen by Homurk and Murdunk, this is where the captured human Messner was held.\n\nAt the conclusion of the Redridge Mountains storyline the area is cleared of all enemy NPCs.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["camp everstill"] = {
			name = "Camp Everstill",
			short = "Camp Everstill is a very small Alliance camp on the shores of Lake Everstill in Redridge Mountains.",
			full = "Camp Everstill is a very small Alliance camp on the shores of Lake Everstill in Redridge Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Everstill",
		},
		["galardell valley"] = {
			name = "Galardell Valley",
			short = "Galardell Valley is located in the northeastern part of the Redridge Mountains. It is the location of the infamous Tower of Ilgalar where the evil Morganth dwells.",
			full = "Galardell Valley is located in the northeastern part of the Redridge Mountains. It is the location of the infamous Tower of Ilgalar where the evil Morganth dwells. The valley is crawling with gnolls, and the most powerful of these is Lieutenant Fangore, who can dispatch an unprepared group of adventurers by calling to the nearby gnolls for help.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["keeshans post"] = {
			name = "Keeshan's Post",
			short = "Keeshan's Post is an area in Redridge Mountains north of Stonewatch Keep. It is initially unoccupied, but after [7-30] AHHHHHHHHHHHH!",
			full = "Keeshan's Post is an area in Redridge Mountains north of Stonewatch Keep. It is initially unoccupied, but after [7-30] AHHHHHHHHHHHH! AHHHHHHHHH!!!, Colonel Troteman will watch Stonewatch Tower through his telescope here. It is named after John J. Keeshan.",
			source = "https://warcraft.wiki.gg/wiki/Keeshan's_Post",
		},
		["lake everstill"] = {
			name = "Lake Everstill",
			short = "The serene Lake Everstill is a large azure lake located in the center of Redridge Mountains. The crystal-clear waters of the lake provide a spectacular setting for the sleepy settlement of Lakeshire.",
			full = "The serene Lake Everstill is a large azure lake located in the center of Redridge Mountains. The crystal-clear waters of the lake provide a spectacular setting for the sleepy settlement of Lakeshire. It is drained by its eastern river which flows near the dark Stonewatch Keep. Lake Everstill was once known for its fishing but recently has become overrun by tribes of murlocs. Adventurers hunting murlocs in the lake should make sure to keep an eye open for the elite Lake Thresher that patrols the deeps. The lake is crossed by Everstill Bridge.\n\nIn 24 ADP, a mage opened a portal at the bottom of Lake Everstill leading up to Ironforge without a liquid filter, causing the Great Lakeshire Drought and the Great Ironforge Flood.\n\nThe threshadons were also replaced by Freshwater Eels.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nAt some point, Makasa Flintwill, upon learning that Reigol Valdread was her father, she ran to the edge of the quarry, thinking about what she just learned. With the help of the Voice of the Light and Aram's sketchbook, she realized that the final shard of the Diamond Blade must be in a mine shaft in the quarry. She was soon approached by Telagos who used his magic to get the shard, merging it with the other, creating a whole blade of the weapon.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Lakeridge Highway",
			short = "Lakeridge Highway is an old highway that runs along the southern edge of Lake Everstill in Redridge Mountains. The highway was originally highly traveled in the days before the First War.",
			full = "Lakeridge Highway is an old highway that runs along the southern edge of Lake Everstill in Redridge Mountains. The highway was originally highly traveled in the days before the First War. Since orcs have taken over Stonewatch Keep the highway has fallen into disuse. Now gnolls patrol most of the highway and travel on the road is not recommended.\n\nThere are also camouflaged Blackrock Hunters further down the road.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Lakeshire",
			short = "Lakeshire (or Lakewood) is a human town that sits on the banks of Lake Everstill in the Redridge Mountains.",
			full = "Lakeshire (or Lakewood) is a human town that sits on the banks of Lake Everstill in the Redridge Mountains. The town is led by Magistrate Solomon and the Court of Lakeshire, while Marshal Marris and the Stormwind Guard are in charge of the security. The town contains a town hall, an inn, Verner Osgood's stables, and Chef Breanna's restaurant-house. The Everstill Bridge has recently been repaired.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["lakeshire inn"] = {
			name = "Lakeshire Inn",
			short = "The Lakeshire Inn in the Redridge Mountains is a well-known establishment, and has kept its warm atmosphere despite the town's beleaguered state.",
			full = "The Lakeshire Inn in the Redridge Mountains is a well-known establishment, and has kept its warm atmosphere despite the town's beleaguered state. It is a popular spot to sit down and have a chat and a drink of wine or ale, and the inn also offers bedrest to the weary traveler.\n\nOne of them got drunk and Darcy Parker put him into a bed in the inn. Before returning to his post duty, he left a mess there, leaving Innkeeper Brianna busy with cleaning. The next day, the inn was searched by two disguised Horde members, Dark Ranger Lyana and the champion, in order to find clues about Varok Saurfang's escape. During that day, the inn was extremely full.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire_Inn",
		},
		["lakeshire town hall"] = {
			name = "Lakeshire Town Hall",
			short = "The Lakeshire Town Hall in the Redridge Mountains is an old building that has been diligently refurbished several times.",
			full = "The Lakeshire Town Hall in the Redridge Mountains is an old building that has been diligently refurbished several times. The town hall is commonly the seat of rule by the local magistrate, and the current magistrate, Solomon, is a kind and wise ruler. The town's problems with gnolls and Blackrock orcs has put him in a state of desperation, however, and he readily accepts aid from helpful adventurers.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire_Town_Hall",
		},
		["redridge canyons"] = {
			name = "Redridge Canyons",
			short = "The Redridge Canyons are a subzone in the northwestern part of the Redridge Mountains. The area is home to the den of Yowler, leader of the local gnolls.",
			full = "The Redridge Canyons are a subzone in the northwestern part of the Redridge Mountains. The area is home to the den of Yowler, leader of the local gnolls.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["redridge pass"] = {
			name = "Redridge Pass",
			short = "Redridge Pass is a long road running through the easternmost section of the Redridge Mountains that stretches from Terror Wing Path in the Burning Steppes to Bogpaddle in the Swamp of Sorrows.",
			full = "Redridge Pass is a long road running through the easternmost section of the Redridge Mountains that stretches from Terror Wing Path in the Burning Steppes to Bogpaddle in the Swamp of Sorrows. It is not accessible on foot from the lower portion of Redridge.\n\nThe Steamwheedle Cartel offers a fast mode of transportation along the Pass via the Bogpaddle Bullet, a rocket that zips from the northern end in Burning Steppes to the south, stopping at their resort town of Bogpaddle. There is no similar transport heading north -- players will have to go on foot (or take a flight).",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Pass",
		},
		["renders camp"] = {
			name = "Render's Camp",
			short = "Render's Camp is a Blackrock orc outpost in the northwestern Redridge Mountains, near the entrance to the Burning Steppes.",
			full = "Render's Camp is a Blackrock orc outpost in the northwestern Redridge Mountains, near the entrance to the Burning Steppes.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Render's Rock",
			short = "Render's Rock is a large cave in the northwestern Redridge Mountains near the entrance to the Burning Steppes. It contains a number of powerful Blackrock orcs.",
			full = "Render's Rock is a large cave in the northwestern Redridge Mountains near the entrance to the Burning Steppes. It contains a number of powerful Blackrock orcs.\n\nRender's Rock is also the location of the wounded Corporal Keeshan, who needs help in getting to Lakeshire in one piece.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Render's Valley",
			short = "Render's Valley is a Blackrock orc outpost in the southeastern Redridge Mountains.",
			full = "Render's Valley is a Blackrock orc outpost in the southeastern Redridge Mountains.\n\nThe Blackrock orcs have since established a firmer hold here with a larger camp, towers, and elite mobs. Dragon riders now guard their camp.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Rethban Caverns",
			short = "Rethban Caverns is an extensive series of caverns which extend deep into the northwestern section of the Redridge Mountains.",
			full = "Rethban Caverns is an extensive series of caverns which extend deep into the northwestern section of the Redridge Mountains. Adventurers sometimes visit the caverns in search of [Rethban Ore], which can be found in the possession of the local gnolls who are led by the cunning Ardo Dirtpaw.\n\nThe caverns may have been named after Bart Rethban.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["shalewind canyon"] = {
			name = "Shalewind Canyon",
			short = "Shalewind Canyon is an area in the eastern part of Redridge Mountains, near Stonewatch Falls, with a small human encampment.",
			full = "Shalewind Canyon is an area in the eastern part of Redridge Mountains, near Stonewatch Falls, with a small human encampment.",
			source = "https://warcraft.wiki.gg/wiki/Shalewind_Canyon",
		},
		["stonewatch"] = {
			name = "Stonewatch",
			short = "Stonewatch is the common name of the military stronghold in central Redridge Mountains. This human fortress serves as a defensive base against the orcish raids coming from the nearby Burning Steppes.",
			full = "Stonewatch is the common name of the military stronghold in central Redridge Mountains. This human fortress serves as a defensive base against the orcish raids coming from the nearby Burning Steppes. It includes both the easily defensible Stonewatch Keep and the armored Stonewatch Tower, with the Stonewatch Falls cascading down a cliff face below it.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Stonewatch Falls",
			short = "Stonewatch Falls is located on the terminus of Lake Everstill's eastern river. It cascades down the hill below Stonewatch and forms a deep lake in the nook of the eastern Redridge Mountains.",
			full = "Stonewatch Falls is located on the terminus of Lake Everstill's eastern river. It cascades down the hill below Stonewatch and forms a deep lake in the nook of the eastern Redridge Mountains. A small tribe of murlocs make their home here, catching fish from the lake and erecting crude structures to sleep in.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Stonewatch Keep",
			short = "Stonewatch Keep is the main structure of the human stronghold of Stonewatch, which also includes the Stonewatch Tower. Originally, Stonewatch used to be controlled by the humans of Lakeshire.",
			full = "Stonewatch Keep is the main structure of the human stronghold of Stonewatch, which also includes the Stonewatch Tower. Originally, Stonewatch used to be controlled by the humans of Lakeshire. One day however, the warlock Morganth made an alliance with the Blackrock orcs led by Gath'Ilzogg, and together they combined their forces to invade Redridge. Fueled by the evil magic of Morganth, the Blackrock orcs attacked Stonewatch Keep in Redridge with horrific savagery. Ultimately, they captured Stonewatch Keep, but shortly after their victory, Morganth turned on his orcish cohorts. He constructed an arcane tower, the Tower of Ilgalar, and used his powers to build a small army of Shadowhide gnolls led by Lieutenant Fangore, to serve his malicious bidding. Both orc and man have fallen victim to the brutes that serve Morganth.\n\nLeft to fend for themselves, the orcs of the Blackrock clan maintained control of the keep, which was overseen by the Blackrock warlord Gath'Ilzogg and his trusted lieutenant, Tharil'zun. Having taken Corporal Keeshan of the Stormwind Army prisoner during the battle, they dragged him away to their encampments further north.\n\nMagistrate Solomon put a bounty on Gath'Ilzogg while Marshal Marris of Lakeshire enlisted the aid of Alliance adventurers to hunt down and kill Tharil'zun for his misdeeds.\n\nThe two death knights were holed up in Stonewatch and Colonel Troteman ordered Bravo Company to carry out their execution. Shortly after their defeat, Bravo Company had to face the black dragon Darkblaze himself. After defeating Darkblaze, all orcish forces appear to have abandoned Stonewatch.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Stonewatch Tower",
			short = "Stonewatch Tower is the secondary structure of the human stronghold of Stonewatch, which also includes the Stonewatch Keep.",
			full = "Stonewatch Tower is the secondary structure of the human stronghold of Stonewatch, which also includes the Stonewatch Keep. They both used to be controlled by the humans of Lakeshire but were taken by orcs of the Blackrock clan. Although the scout tower was for quite some time firmly in the hands of Gath'Ilzogg's underlings, after Darkblaze was defeated, the orcish forces left the stronghold deserted.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Three Corners",
			short = "Three Corners is a crossroads just inside Redridge Mountains. The crossroads splits three ways and leads to the \"Three Shires\": Goldshire in Elwynn Forest, Lakeshire, and Darkshire in Duskwood.",
			full = "Three Corners is a crossroads just inside Redridge Mountains. The crossroads splits three ways and leads to the \"Three Shires\": Goldshire in Elwynn Forest, Lakeshire, and Darkshire in Duskwood.\n\nAlliance adventurers venturing here from Elwynn are asked to assist in keeping the gnolls in check and further examining the situation in Redridge.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Tower of Ilgalar",
			short = "The Tower of Ilgalar is a mage tower in the eastern part of the Redridge Mountains, and was once controlled by Morganth, a powerful sorcerer who controlled the Shadowhide Gnoll Clan of gnolls.",
			full = "The Tower of Ilgalar is a mage tower in the eastern part of the Redridge Mountains, and was once controlled by Morganth, a powerful sorcerer who controlled the Shadowhide Gnoll Clan of gnolls. After being exiled from the Mage Quarter of Stormwind City, he took up residence here to continue his study of the dark arts.\n\nAt some point, Morganth was replaced by Grand Magus Doane, who is actually the black dragon Darkblaze.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
		["tower watch"] = {
			name = "Tower Watch",
			short = "Tower Watch is the scout tower of the Stormwind Guard found in the center of the Three Corners crossroads.",
			full = "Tower Watch is the scout tower of the Stormwind Guard found in the center of the Three Corners crossroads.",
			source = "https://warcraft.wiki.gg/wiki/Tower_Watch",
		},
		["yowlers den"] = {
			name = "Yowler's Den",
			short = "Yowler's Den is the base of Yowler, son of Yowler. It is found at the northern end of the Redridge Canyons north of Lakeshire in Redridge Mountains.",
			full = "Yowler's Den is the base of Yowler, son of Yowler. It is found at the northern end of the Redridge Canyons north of Lakeshire in Redridge Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Yowler's_Den",
		},
	},
	-- Stranglethorn Vale: 40 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Balia'mah Ruins",
			short = "Balia'mah Ruins are ancient troll ruins found in Northern Stranglethorn. They are currently inhabited by the Skullsplitter trolls.",
			full = "Balia'mah Ruins are ancient troll ruins found in Northern Stranglethorn. They are currently inhabited by the Skullsplitter trolls. They are located east-southeast of Grom'gol Base Camp on the east side of the river and south-west of Mosh'Ogg Ogre Mound.\n\nDuring the war against the Zandalari, the ruins were invaded by Jungle Serpents.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Bal'lal Ruins",
			short = "Bal'lal Ruins are ancient troll ruins located near the northwestern coast of Stranglethorn Vale, north of Grom'gol Base Camp and located on the coast of the Vile Reef.",
			full = "Bal'lal Ruins are ancient troll ruins located near the northwestern coast of Stranglethorn Vale, north of Grom'gol Base Camp and located on the coast of the Vile Reef. A number of Bloodscalp trolls reside in what's left of the ruin.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Bloodsail Compound",
			short = "The Bloodsail Compound is a loose camp of the Bloodsail Buccaneers found on western coast of Stranglethorn Vale near the central portion.",
			full = "The Bloodsail Compound is a loose camp of the Bloodsail Buccaneers found on western coast of Stranglethorn Vale near the central portion.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Booty Bay",
			short = "Booty Bay is a large pirate port city nestled into the cliffs surrounding a beautiful blue lagoon on the southern tip of Stranglethorn Vale.",
			full = "Booty Bay is a large pirate port city nestled into the cliffs surrounding a beautiful blue lagoon on the southern tip of Stranglethorn Vale. By foot, the city is entered by traversing through the bleached-white jaws of a giant shark. Life is cheaper here than in most places, and no one is to be trusted. It is considered a rogue's paradise, full of information and informants.\n\nLand of pirates, swindlers, and raiders, it is one of the most cutthroat places on Azeroth. There is a newspaper called the Booty Bay Journal.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Cape of Stranglethorn",
			short = "The Cape of Stranglethorn is the southern part of Stranglethorn Vale, designated as the piece of land south of the area around the Gurubashi Arena.",
			full = "The Cape of Stranglethorn is the southern part of Stranglethorn Vale, designated as the piece of land south of the area around the Gurubashi Arena. Booty Bay, located to the southwest, is a major city run by goblin pirates - many profession trainers are located here, as well as a neutral Auction House, bank, inn, a boat to Ratchet, and unique recipe/item vendors. The weekly Stranglethorn Fishing Extravaganza event happens every Sunday from 2-4pm.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Crystal Shore",
			short = "The Crystal Shore is a sandy coastline in the southeast of Cape of Stranglethorn where the South Seas wash up against the mainland and eastern beaches of Jaguero Isle.",
			full = "The Crystal Shore is a sandy coastline in the southeast of Cape of Stranglethorn where the South Seas wash up against the mainland and eastern beaches of Jaguero Isle. It runs from the Wild Shore northeast to the cliffs where the Cape meets Northern Stranglethorn. The beach is mostly isolated from the inland areas by a steep ridge, but two paths cut through it, including one to Mistvale Valley.\n\nThree Venture Company oil platforms tower over the southern waters, with pipelines leading to a storage tank built on the overlooking ridge. The Ruins of Aboraz sit on the north end of the shore.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Crystalvein Mine",
			short = "Crystalvein Mine is located near Zul'Mamwe, and the native basilisks eat the strange crystals which can be found within this mine. This gives the reptiles their hardened skin.",
			full = "Crystalvein Mine is located near Zul'Mamwe, and the native basilisks eat the strange crystals which can be found within this mine. This gives the reptiles their hardened skin. According to Crank Fizzlebub, these Singing Crystals were unique to Stranglethorn and quite valuable. The Venture Co. have moved into the area hoping to harvest the mine, but the basilisk infestation has made this impossible thus far. Outside crystallized trolls and humans can be found.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Grom'gol Base Camp",
			short = "Grom'gol Base Camp (or Grom'Gol) is an orcish camp on the southwestern coast of Northern Stranglethorn. Led by Commander Aggro'gosh, the outpost provides a safe chain of supply to Stonard in the Swamp of Sorrows.",
			full = "Grom'gol Base Camp (or Grom'Gol) is an orcish camp on the southwestern coast of Northern Stranglethorn. Led by Commander Aggro'gosh, the outpost provides a safe chain of supply to Stonard in the Swamp of Sorrows. This fort is heavily strengthened to be able to guard against jungle trolls, naga, and the many members of the Alliance who arrive from Booty Bay and Duskwood. The Savage Coast Raptor Fields are just to the north.\n\nDuring the war against the Zandalari, the camp was attacked by the Gurubashi trolls led by Bloodlord Mandokir. The attack was successfully repelled.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Gurubashi Arena",
			short = "The Gurubashi Arena (or The Great Arena) is an arena located on the northwestern section of the Cape of Stranglethorn, just north of Booty Bay.",
			full = "The Gurubashi Arena (or The Great Arena) is an arena located on the northwestern section of the Cape of Stranglethorn, just north of Booty Bay. The Arena is an old relic of the mighty Gurubashi Empire, which once controlled vast tracts of land in the southern regions of the Eastern Kingdoms.\n\nThe Gurubashi Arena provides ruffians a shot at competition, fame, and treasure. It is said that in ancient times, fights were to the death, and the sand of the area was muddy with troll blood. Short John Mithril is the overseer of the less-lethal matches. Old stories say that if one finds a blood-red amulet at midnight, a demon will devour their soul by daybreak. Once a generation, the greatest trolls from all over Azeroth come to this arena to challenge one another in combat. This is an ancient rite long presided over by the Zandalari troll king, Rastakhan. They fight for the glory of the loa. To win is one of the greatest honors to which a troll can aspire. With Rastakhan's death, it is unknown if the rite will continue.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Jaguero Isle",
			short = "Jaguero Isle is an island off the coast of Stranglethorn Vale that is populated by panthers and gorillas. Princess Poobah, a captive tauren, is kept there by an enormous ape -- King Mukla.",
			full = "Jaguero Isle is an island off the coast of Stranglethorn Vale that is populated by panthers and gorillas. Princess Poobah, a captive tauren, is kept there by an enormous ape -- King Mukla.\n\nAlong the coast of the Wild Shore, you will find Half-Buried Bottles. One of them will contain a [Carefully Folded Note] which begins the questline:\n\n[10-30] Message in a Bottle\n\nMessage in a Bottle",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Janeiro's Point",
			short = "Janeiro's Point is a small island just outside Booty Bay, upon which a giant statue of an unknown goblin with outstretched arms was built as a beacon to all travelers, welcoming ships to Booty Bay.",
			full = "Janeiro's Point is a small island just outside Booty Bay, upon which a giant statue of an unknown goblin with outstretched arms was built as a beacon to all travelers, welcoming ships to Booty Bay.\n\nThe sea giant Mok'rash the Cleaver has chosen the island as his abode.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Kal'ai Ruins",
			short = "Kal'ai Ruins is a collection of ancient troll ruins found in Northern Stranglethorn that are partially submerged now. The Murkgill tribe of murlocs live in these ruins.",
			full = "Kal'ai Ruins is a collection of ancient troll ruins found in Northern Stranglethorn that are partially submerged now. The Murkgill tribe of murlocs live in these ruins.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Kurzen's Compound",
			short = "Kurzen's Compound is an unusual human settlement located east of the Rebel Camp in Northern Stranglethorn.",
			full = "Kurzen's Compound is an unusual human settlement located east of the Rebel Camp in Northern Stranglethorn. Occupied by Kurzen's Expedition, once led by Colonel Kurzen, until his death, the expedition now takes orders from Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel.\n\nThe inhabitants of the Rebel Camp were once members of the compound before rebelling after Kurzen descended into madness. They are embroiled in a deadly conflict with the jungle fighters. It has a lumber mill and at the back of the Compound is a non-instanced dungeon, the Stockpile, where the fighters keep their equipment. The men also keep Panthers and Stranglethorn Tigers in cages near the stables so they can be trained to become Kurzen War Panthers and Kurzen War Tigers.\n\nDuring the events of Rise of Zandalari, all inhabitants were killed by Mauti.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lake Nazferiti",
			short = "Lake Nazferiti is a lake in Northern Stranglethorn. Bordering it is a large base of the goblin Venture Company. It features many frenzies and crocolisks in its waters.",
			full = "Lake Nazferiti is a lake in Northern Stranglethorn. Bordering it is a large base of the goblin Venture Company. It features many frenzies and crocolisks in its waters. Nazferiti river, which flows through the lake, may be the longest on the southern Eastern Kingdoms with a confirmed source at a waterfall in Redridge Mountains and unconfirmed headwaters within Deadwind Pass.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Mistvale Valley",
			short = "Mistvale Valley is a valley in the southern part of the Cape of Stranglethorn inhabited by the great Mistvale gorillas.",
			full = "Mistvale Valley is a valley in the southern part of the Cape of Stranglethorn inhabited by the great Mistvale gorillas. Adventurers often come through here looking to find Mistvale Giblets, Gorilla Fangs, or the very rare Aged Gorilla Sinew.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Mizjah Ruins",
			short = "The Mizjah Ruins are an area southeast of Grom'gol Base Camp inhabited by Mosh'Ogg Brutes and Mosh'Ogg Witch Doctors. These ogres are responsible for ambushing supply caravans going to Stonard.",
			full = "The Mizjah Ruins are an area southeast of Grom'gol Base Camp inhabited by Mosh'Ogg Brutes and Mosh'Ogg Witch Doctors. These ogres are responsible for ambushing supply caravans going to Stonard.\n\nDuring the events of Rise of the Zandalari, the place was overrun by Jungle Serpents.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Mosh'Ogg Ogre Mound",
			short = "The Mosh'Ogg Ogre Mound is an ogre mound inhabited by the Mosh'Ogg tribe of ogres located in Northern Stranglethorn, just south of Zul'Gurub.",
			full = "The Mosh'Ogg Ogre Mound is an ogre mound inhabited by the Mosh'Ogg tribe of ogres located in Northern Stranglethorn, just south of Zul'Gurub. Deep inside the mound, their leader, the ogre mage Mai'Zoth holds a powerful relic called the [Mind's Eye].\n\nLong before the ogres came to inhabit the cave, this was a place of worship containing the shrine to the loa Lukou, however after the Darkspear tribe left Stranglethorn Valley they mostly abandoned the worship of Lukou.\n\nDuring the war against the Zandalari, the place was overrun by Jungle Serpents and many of the ogres were killed.\n\nMany years later, the ogres, still active in the mound, managed to capture Lukou. The mound was entered by Rokhan when the Darkspear tribe was looking for and saving their loa.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Nek'mani Wellspring",
			short = "The Nek'mani Wellspring is a sacred spring located high in the cliffs overlooking the Southern Savage Coast on the west side of the Cape of Stranglethorn.",
			full = "The Nek'mani Wellspring is a sacred spring located high in the cliffs overlooking the Southern Savage Coast on the west side of the Cape of Stranglethorn. Its Holy Spring dispenses the only clean freshwater south of Duskwood. The spring is the subject of great conflict among religious scholars, since every race in Azeroth claims that the waters were made divine for their people. An expedition of naga explorers have recently advanced on the spring and guard it ferociously.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Nesingwary's Expedition",
			short = "Nesingwary's Expedition is Hemet Nesingwary's (and later Hemet Nesingwary Jr.'s) base camp in Northern Stranglethorn. It is situated just below the river north of Lake Nazferiti.",
			full = "Nesingwary's Expedition is Hemet Nesingwary's (and later Hemet Nesingwary Jr.'s) base camp in Northern Stranglethorn. It is situated just below the river north of Lake Nazferiti.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["old port authority"] = {
			name = "Old Port Authority",
			short = "The Old Port Authority is a warehouse in Booty Bay in the Cape of Stranglethorn. Its roof is being repaired by Goblin Construction Crews.",
			full = "The Old Port Authority is a warehouse in Booty Bay in the Cape of Stranglethorn. Its roof is being repaired by Goblin Construction Crews.",
			source = "https://warcraft.wiki.gg/wiki/Old_Port_Authority",
		},
		["rebel camp"] = {
			name = "Rebel Camp",
			short = "The Rebel Camp is a Alliance situated in the northernmost part of Northern Stranglethorn Vale, just west of the road leading south from Duskwood and northwest of Kurzen's Compound.",
			full = "The Rebel Camp is a Alliance situated in the northernmost part of Northern Stranglethorn Vale, just west of the road leading south from Duskwood and northwest of Kurzen's Compound. Its inhabitants are former followers of Colonel Kurzen, who managed to escape the madness that befell upon the Stormwidian expedition sent in the region.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruins of Aboraz",
			short = "The Ruins of Aboraz is a collection of ancient troll ruins on the southeastern coast of Stranglethorn Vale, now the home of the witch doctor Zanzil the Outcast.",
			full = "The Ruins of Aboraz is a collection of ancient troll ruins on the southeastern coast of Stranglethorn Vale, now the home of the witch doctor Zanzil the Outcast. Zanzil's ghouls, naga, and troll minions wander the ruins.\n\nIt is located southeast of Ruins of Jubuwal, east of Spirit Den, and south of Crystalvein Mine.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruins of Jubuwal",
			short = "Ruins of Jubuwal are ancient troll ruins, just east of the Gurubashi Arena, along main road that spans the length of Stranglethorn Vale.",
			full = "Ruins of Jubuwal are ancient troll ruins, just east of the Gurubashi Arena, along main road that spans the length of Stranglethorn Vale. Ghoul, naga, and troll minions of Zanzil the Outcast currently inhabit the ruins, including Jon-Jon the Crow and Maury \"Club Foot\" Wilkins, debtors to the ruthless \"Sea Wolf\" MacKinley.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruins of Zul'Kunda",
			short = "The Ruins of Zul'Kunda are very large jungle troll ruins in Northern Stranglethorn. This is the territory of the Bloodscalp tribe, and their leaders, Nezzliok the Dire and Gan'zulah, are stationed here.",
			full = "The Ruins of Zul'Kunda are very large jungle troll ruins in Northern Stranglethorn. This is the territory of the Bloodscalp tribe, and their leaders, Nezzliok the Dire and Gan'zulah, are stationed here. It is accessed via a path heading east from Zuuldaia Ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruins of Zul'Mamwe",
			short = "The Ruins of Zul'Mamwe is a troll ruin located south of the Mosh'Ogg Ogre Mound. It is surrounded by mountains on all sides except north.",
			full = "The Ruins of Zul'Mamwe is a troll ruin located south of the Mosh'Ogg Ogre Mound. It is surrounded by mountains on all sides except north. The second major troll tribe of Stranglethorn Vale, the Skullsplitters, inhabit Zul'Mamwe, led by their vicious chieftain, Ana'thek the Cruel.\n\nDuring the war against the Zandalari, these ruins were invaded by Jungle Serpents.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["salty sailor tavern"] = {
			name = "Salty Sailor Tavern",
			short = "The Salty Sailor Tavern is the local tavern and inn located in Booty Bay and is run by Innkeeper Skindle.",
			full = "The Salty Sailor Tavern is the local tavern and inn located in Booty Bay and is run by Innkeeper Skindle.\n\nIt can be visited during the Kirin Tor Tavern Crawl. The local specialty is the [South Island Iced Tea].",
			source = "https://warcraft.wiki.gg/wiki/Salty_Sailor_Tavern",
		},
		["savage coast"] = {
			name = "Savage Coast",
			short = "The Savage Coast is a coastline on the northern part of Stranglethorn Vale. It takes up the shore from the Westfall border, all the way down to the shore east of The Vile Reef, to the Grom'Gol Base Camp.",
			full = "The Savage Coast is a coastline on the northern part of Stranglethorn Vale. It takes up the shore from the Westfall border, all the way down to the shore east of The Vile Reef, to the Grom'Gol Base Camp. Many crocolisks and even some basilisks inhabit the shore. Several troll settlements are along this area.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Notable islands like Zandalar, Kezan or Tel'Abim are located here. Since this sea is found in between the continents, it is a portion of the Great Sea.",
			full = "Notable islands like Zandalar, Kezan or Tel'Abim are located here. Since this sea is found in between the continents, it is a portion of the Great Sea.\n\nDarkspear Islands\n\nHiji\n\nIsle of Kezan\n\nThe Maelstrom\n\nThe Eye\n\nPlunder Isle\n\nTel Abim\n\nZandalar",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Southern Savage Coast",
			short = "The Southern Savage Coast comprises many beaches and shallow waters on the west side of the Cape of Stranglethorn where the South Seas meet the shore.",
			full = "The Southern Savage Coast comprises many beaches and shallow waters on the west side of the Cape of Stranglethorn where the South Seas meet the shore. Its northernmost extent borders Hardwrench Hideaway, while it terminates just beyond Booty Bay and Janeiro's Point to the south where it meets the Wild Shore. It is divided from its northern namesake the Savage Coast by the Vile Reef, paralleling the transition of the Great Sea into the South Seas and Northern Stranglethorn to the Cape of Stranglethorn. Via a couple bays and inlets, it also shares short borders with the Gurubashi Arena and Nek'mani Wellspring.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Spirit Den",
			short = "The Spirit Den is a hidden cave located on the northern end of Mistvale Valley in the Cape of Stranglethorn. There, you can find Witch Doctor Unbagwa for the quest [10-30] Stranglethorn Fever.",
			full = "The Spirit Den is a hidden cave located on the northern end of Mistvale Valley in the Cape of Stranglethorn. There, you can find Witch Doctor Unbagwa for the quest [10-30] Stranglethorn Fever.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "Stockpile",
			short = "The Stockpile is a cave where Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel keep their war-waging equipment.",
			full = "The Stockpile is a cave where Chief Anders, Chief Gaulus, Chief Miranda, and Chief Esquivel keep their war-waging equipment.\n\nIt is a non-instanced dungeon located at the back of the Kurzen's Compound in Northern Stranglethorn.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Tkashi Ruins",
			short = "The Tkashi Ruins are ancient troll ruins found in Stranglethorn Vale, south-west of Nesingwary's Expedition. A large group of Bloodscalp trolls live here.",
			full = "The Tkashi Ruins are ancient troll ruins found in Stranglethorn Vale, south-west of Nesingwary's Expedition. A large group of Bloodscalp trolls live here. As part of the Alliance's continued southward movement following the collapse of Kurzen's Compound, Berrin Burnquill assigns adventurers to do battle with the ruins' inhabitants, uncover the roots of their shamanistic practices and retrieve a number of artifacts.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Venture Co. Base Camp",
			short = "The Venture Co. Base Camp is the base of operations for the Venture Company, specifically those interested in Tumbled Crystals. Adjacent to this area is the Venture Co.",
			full = "The Venture Co. Base Camp is the base of operations for the Venture Company, specifically those interested in Tumbled Crystals. Adjacent to this area is the Venture Co. Operations Center. During the Rise of the Zandalari, the place was overran by Jungle Serpents and goblins killed.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Venture Co. Operations Center",
			short = "The Venture Co. Operations Center is a Goblin Oil platform that is located on a lake in Northern Stranglethorn. Filled with Mechanics, Geologists and other Goblin teams invading the jungle.",
			full = "The Venture Co. Operations Center is a Goblin Oil platform that is located on a lake in Northern Stranglethorn. Filled with Mechanics, Geologists and other Goblin teams invading the jungle.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "Vile Reef",
			short = "The Vile Reef is a colorful reef portion of the Great Sea near the southwestern tip of the Eastern Kingdoms, mostly noted by travelers on the west coast of Stranglethorn Vale near Grom'Gol Base Camp.",
			full = "The Vile Reef is a colorful reef portion of the Great Sea near the southwestern tip of the Eastern Kingdoms, mostly noted by travelers on the west coast of Stranglethorn Vale near Grom'Gol Base Camp. It is populated by murlocs who inhabit sunken troll ruins among the reef. The Altar of the Tides can be found here.\n\nGiant Clams can be found scattered among the corals. These clams have been rumored to hold Blue Pearls. Also, many floating wreckages can be found along its coasts.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Wild Shore",
			short = "Wild Shore is the southernmost coastline of the Eastern Kingdoms where the land meets the South Seas. It is home to the Bloodsail Buccaneers and their fleet, and Gorlash the giant also wanders there.",
			full = "Wild Shore is the southernmost coastline of the Eastern Kingdoms where the land meets the South Seas. It is home to the Bloodsail Buccaneers and their fleet, and Gorlash the giant also wanders there.\n\nAt its western edge, the land ends in a rocky point, on the north side of which lies Booty Bay and the Southern Savage Coast. The shore includes a shallow strait separating the mainland from Jaguero Isle to the east. The beach transitions into the Crystal Shore to the northeast, as well as on the north and south sides of Jaguero.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Yojamba Isle",
			short = "Yojamba Isle (or Yojamba Island) is a small group of tiny islands found in the northwestern corner of Northern Stranglethorn, near the border with Westfall and northwest of the haunted isle and the Vile Reef.",
			full = "Yojamba Isle (or Yojamba Island) is a small group of tiny islands found in the northwestern corner of Northern Stranglethorn, near the border with Westfall and northwest of the haunted isle and the Vile Reef. This island was once used by the Zandalar Tribe to recruit the help of the Alliance and the Horde to defeat Hakkar the Soulflayer in Zul'Gurub.\n\nAfter Hakkar's defeat, the majority of Zandalari trolls left Stranglethorn and headed back home to Zandalar. Some later returned here to hold a meeting of the troll tribes in an attempt to unite all of them for the greater good of their race. Others went to Yojamba Exchange in Dazar'alor.\n\nThe isle is now only inhabited by the Crystal Spine Matriarch and the Bloodscalp Berserkers, Bloodscalp Witch Doctors, and Bloodscalp Shaman she has petrified.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ziata'jai Ruins",
			short = "The Ziata'jai Ruinsare ancient Troll ruins inhabited by the Skullsplitter tribe. It is located north of Fort Livingston. During the events of the Rise of Zandalari, the place was invaded by Jungle Serpents.",
			full = "The Ziata'jai Ruinsare ancient Troll ruins inhabited by the Skullsplitter tribe. It is located north of Fort Livingston. During the events of the Rise of Zandalari, the place was invaded by Jungle Serpents.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub is a temple city inhabited by jungle trolls located in northeastern Stranglethorn Vale. Thousands of years ago it was the capital of the Gurubashi Empire and all jungle troll tribes affiliated with them.",
			full = "Zul'Gurub is a temple city inhabited by jungle trolls located in northeastern Stranglethorn Vale. Thousands of years ago it was the capital of the Gurubashi Empire and all jungle troll tribes affiliated with them. However, now it only serves as the capital of the Gurubashi tribe.\n\nIt is an extremely dangerous place where the influence of Hakkar still persists, the trolls there are brutal, violent and fast. Many people venture there in search of treasures and artifacts. But few come out of it, if not at all.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Zuuldaia Ruins",
			short = "The Zuuldaia Ruins are ancient troll ruins on the northern part of the western coast of Stranglethorn Vale. A large number of Bloodscalp trolls inhabit the area.",
			full = "The Zuuldaia Ruins are ancient troll ruins on the northern part of the western coast of Stranglethorn Vale. A large number of Bloodscalp trolls inhabit the area.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Swamp of Sorrows: 22 subzones
	[1435] = {
		["bloodmire"] = {
			name = "Bloodmire",
			short = "The Bloodmire is a battleground between the Horde of Stonard and the Alliance of Marshtide Watch in the Swamp of Sorrows.",
			full = "The Bloodmire is a battleground between the Horde of Stonard and the Alliance of Marshtide Watch in the Swamp of Sorrows. Alarmed by the presence of Stonard so close to their borders, the Alliance have begun an aggressive push to get the Horde out of the swamp. The battle between the two factions is nearly evenly matched.\n\nThe battle has several stages, which can be seen by progressing through the related questline (which starts from Joanna Blueheart for Alliance or Dispatch Commander Ruag for Horde):\n\nStonard Warriors fight Marshtide Footmen, rallied by Horde wardrummers and Alliance clerics. Marshtide Peasants and Stonard Peons collect lumber for their respective side on the fringes.\n\nAs the battle progresses, Stonard Ogres and Marshtide Knights appear, summoned in by Stonard Warlocks and Marshtide Mages, respectively. Corpses from both factions now litter the ground.\n\nAt the battle's conclusion, Marshtide's forces invade Stonard, and Marshtide Invaders are narrowly fought off by the Stonard Defenders.\n\nThe quests draw influence from Warcraft II: Tides of Darkness, mirroring it right down to the NPCs fighting through the swamp. Several siege weapons are also scattering the area, including a wrecked steam tank, several ballistae, blade throwers and a siege engine.",
			source = "https://warcraft.wiki.gg/wiki/Bloodmire",
		},
		["bogpaddle"] = {
			name = "Bogpaddle",
			short = "Bogpaddle is a neutral goblin port in Swamp of Sorrows ruled by Trade Baron Silversnap.",
			full = "Bogpaddle is a neutral goblin port in Swamp of Sorrows ruled by Trade Baron Silversnap. He refers the town as \"the only beachfront resort and military-grade weapons yard in the Eastern Kingdoms\", and his abode has become a popular spot with the forces of both Stonard and Marshtide Watch despite the ongoing war. Carousers from both sides can be found in Bogpaddle in addition to the goblins who party on the beach.\n\nLike Mudsprocket and similar outposts, Bogpaddle is affiliated with the Steamwheedle Cartel but quests completed here award no reputation. Its inhabitants are considered part of Gadgetzan for the purposes of reputation discounts and the like. Some of the more adventurous goblins in the area can be found along the Misty Reed Strand and nearby Sorrowmurk, south of Bogpaddle.",
			source = "https://warcraft.wiki.gg/wiki/Bogpaddle",
		},
		["broken hall"] = {
			name = "Broken Hall",
			short = "The Broken Hall is located inside Temple of Atal'Hakkar and is the outermost area of the dungeon. Like many of the temple's chambers, it was damaged when the green dragonflight sunk it beneath the Pool of Tears.",
			full = "The Broken Hall is located inside Temple of Atal'Hakkar and is the outermost area of the dungeon. Like many of the temple's chambers, it was damaged when the green dragonflight sunk it beneath the Pool of Tears. The chamber's floor has broken, letting in large amount of water from the swamp outside, flooding it almost completely. It now lies abandoned, the Atal'ai having withdrawn to deeper levels. The stairs beyond this chamber lead to the Hall of Masks.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Hall",
		},
		["fallow sanctuary"] = {
			name = "Fallow Sanctuary",
			short = "The Fallow Sanctuary is the village of a tribe of Lost Ones simply called the \"Lost Ones\", who live in the Swamp of Sorrows. All the Lost Ones here have been driven mad with homesickness and turned completely feral.",
			full = "The Fallow Sanctuary is the village of a tribe of Lost Ones simply called the \"Lost Ones\", who live in the Swamp of Sorrows. All the Lost Ones here have been driven mad with homesickness and turned completely feral.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["fortunes fist"] = {
			name = "Fortune's Fist",
			short = "Fortune's Fist is a frigate used as a shipping freighter located in the Forbidding Sea off the northern Misty Reed Strand in the Swamp of Sorrows.",
			full = "Fortune's Fist is a frigate used as a shipping freighter located in the Forbidding Sea off the northern Misty Reed Strand in the Swamp of Sorrows. The ship has been seized by gilgoblins, and many of the former crewmembers can be found dead in the waters between the vessel and the shore. The survivors have holed up in a camp in the Sorrowmurk.\n\nThe Landward Cannon is found here and allows safe passage back to land... most of the time. The [Thousand-Thread-Count Fuse] can be found on deck, while the [Extra-Pure Blasting Powder] is found in the captain's quarters. Finally, the [Stack of Questionable Publications] is hidden away in the ship's hold.",
			source = "https://warcraft.wiki.gg/wiki/Fortune's_Fist",
		},
		["hall of masks"] = {
			name = "Hall of Masks",
			short = "The Hall of Masks is located inside the Temple of Atal'Hakkar, and is the second area of the dungeon.",
			full = "The Hall of Masks is located inside the Temple of Atal'Hakkar, and is the second area of the dungeon. Named for the giant skull mask statues lining the walls, the room's purpose is unknown, although a trench in the floor littered with bones suggests it had a macabre function during the Atal'ai's height. The Hall of Masks lies past the staircase leading from the Broken Hall, the passages beyond this chamber lead to the Butchery, the Chamber of Blood, and the Den of the Caller.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Masks",
		},
		["harborage"] = {
			name = "Harborage",
			short = "The Harborage is a base of Broken who managed to stay sane after crossing over to the world of Azeroth from Draenor. It is located in the northern part of the Swamp of Sorrows.",
			full = "The Harborage is a base of Broken who managed to stay sane after crossing over to the world of Azeroth from Draenor. It is located in the northern part of the Swamp of Sorrows. The Broken here were until recently led by Magtoor.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Itharius's Cave",
			short = "Itharius's Cave is the current residence of the mysterious high elf Itharius. It is located in the far southwestern corner of the Swamp of Sorrows.",
			full = "Itharius's Cave is the current residence of the mysterious high elf Itharius. It is located in the far southwestern corner of the Swamp of Sorrows. The area outside the cave is filled with unruly green whelps, which Itharius has taken it upon himself to watch over while they grow.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["marshtide watch"] = {
			name = "Marshtide Watch",
			short = "Marshtide Watch is an Alliance port outpost north of the Temple of Atal'Hakkar in the Swamp of Sorrows. It is made up of several cannon towers, stables, and a blacksmith.",
			full = "Marshtide Watch is an Alliance port outpost north of the Temple of Atal'Hakkar in the Swamp of Sorrows. It is made up of several cannon towers, stables, and a blacksmith.\n\nAccording to Joanna Blueheart, the commander of the settlement, the regions of Redridge Mountains, Duskwood, and Elwynn Forest are all a day's march from here.",
			source = "https://warcraft.wiki.gg/wiki/Marshtide_Watch",
		},
		["misty reed farm"] = {
			name = "Misty Reed Farm",
			short = "Misty Reed Farm is a farm in the Swamp of Sorrows. It used to be Misty Reed Post.",
			full = "Misty Reed Farm is a farm in the Swamp of Sorrows. It used to be Misty Reed Post.\n\nDark Ranger Lyana and Deathguard Elites arrived here to kill Varok on orders of Sylvanas Windrunner. Lyana threatened to burn it like Teldrassil was burnt. Varok was defended by Zekhan and the Horde champion and the attackers killed. Afterwards, Varok left the farm and Zekhan returned to Orgrimmar.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Farm",
		},
		["misty reed post"] = {
			name = "Misty Reed Post",
			short = "Misty Reed Post was a small Horde outpost of Stonard in the Swamp of Sorrows. It lied between the Stagalbog and the southern Misty Reed Strand.",
			full = "Misty Reed Post was a small Horde outpost of Stonard in the Swamp of Sorrows. It lied between the Stagalbog and the southern Misty Reed Strand. It was guarded by Tok'Kar, along with Katar, some Stonard Hunters and a Stonard Shaman. Tok'Kar dreams that one day the post will get a burrow or at least a tower. There is no flight path from here.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Misty Reed Strand",
			short = "The Misty Reed Strand is the gloomy coastline of the Swamp of Sorrows. There is little along the vast stretch of beach but driftwood, debris, and crocolisks, crabs, murlocs, and gilblins.",
			full = "The Misty Reed Strand is the gloomy coastline of the Swamp of Sorrows. There is little along the vast stretch of beach but driftwood, debris, and crocolisks, crabs, murlocs, and gilblins.\n\nIn recent years, the Steamwheedle Cartel's resort town of Bogpaddle was built on the northern edge with a full harbor, and several smaller encampments were started to the south. However the goblins have encountered unexpected opposition in the local coastal wildlife, and several of their camps have been viciously destroyed. An unnatural force has been driving the swamp creatures mad, and Baba Bogbrew, enlisted by the Steamwheedle Cartel, intends to find out why...",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Misty Valley",
			short = "Misty Valley is located in the northwestern corner of Swamp of Sorrows, north of the entrance to Deadwind Pass.",
			full = "Misty Valley is located in the northwestern corner of Swamp of Sorrows, north of the entrance to Deadwind Pass. It is home to the native Misty Grells and a giant panther, Duskfang, who lives in the far back of the valley in a cave.\n\nThe Mire Lord inhabited the valley's cave.\n\nIt is unknown where the elementals went, or whether the grells and panther lived there before but were inaccessible.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Pool of Tears",
			short = "The Pool of Tears is a large body of water on the eastern side of the Swamp of Sorrows.",
			full = "The Pool of Tears is a large body of water on the eastern side of the Swamp of Sorrows.\n\nAfter the construction of the Temple of Atal'Hakkar, Ysera sunk the temple under the Pool's waters, where it still sits. Until recently members of the green dragonflight covered the area nearby, watching over the corrupted temple.\n\nBlood-thirsty frenzies inhabit the water. Remains of Atal'ai ruins are scattered at the shore and underwater, where Atal'ai Artifacts can be found.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["purespring cavern"] = {
			name = "Purespring Cavern",
			short = "Purespring Cavern is an area in southwest Swamp of Sorrows, south of Splinterspear Junction. Dreamwatcher Forktongue, a level 55 Rare, resides in this cavern.",
			full = "Purespring Cavern is an area in southwest Swamp of Sorrows, south of Splinterspear Junction. Dreamwatcher Forktongue, a level 55 Rare, resides in this cavern.",
			source = "https://warcraft.wiki.gg/wiki/Purespring_Cavern",
		},
		["shifting mire"] = {
			name = "Shifting Mire",
			short = "The Shifting Mire is the central bulk of the Swamp of Sorrows west of the Pool of Tears. Here you will find Young Sawtooth Crocolisks, Sorrow Spinners, Swamp Jaguars and Lost Ones.",
			full = "The Shifting Mire is the central bulk of the Swamp of Sorrows west of the Pool of Tears. Here you will find Young Sawtooth Crocolisks, Sorrow Spinners, Swamp Jaguars and Lost Ones.\n\nThe name Shifting comes from a mysterious force causes the extremely fine silt on the ground to collect and move on its own accord, traveling as if alive. Anchorite Avuun says that the origin of the force is positive energy. See [15-30] Secrets of the Mire.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Sorrowmurk",
			short = "The Sorrowmurk is the area of the Swamp of Sorrows located just east of the Pool of Tears and the Sunken Temple.",
			full = "The Sorrowmurk is the area of the Swamp of Sorrows located just east of the Pool of Tears and the Sunken Temple. The area was once crawling with green dragonspawn as well as a large green drake that patrolled the region, making it inhospitable for all but the most adventurous traveler.\n\nA neutral band of goblins led by Crazy Larry has since established a camp on the shore of the Sorrowmurk. While the tide of dragonkin has subsided, the area has now come under attack from gilblins.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Splinterspear Junction",
			short = "Splinterspear Junction is where the main road into the Swamp of Sorrows splits.",
			full = "Splinterspear Junction is where the main road into the Swamp of Sorrows splits. The north branch will take you past the Harborage and to the Fallow Sanctuary, while the southern branch will take you to Stonard and the path to the Blasted Lands. An old orcish watch tower sits there and the area is regularly patrolled by Horde guards, so Alliance adventurers are advised to keep their eyes open when traveling the roads. The guards are PvP tagged.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Stagalbog",
			short = "The Stagalbog is a region of the Swamp of Sorrows which lies south of the Pool of Tears and borders the southern mountain range.",
			full = "The Stagalbog is a region of the Swamp of Sorrows which lies south of the Pool of Tears and borders the southern mountain range. It is dense marshland, with the small camp of Baba Bogbrew being the only sign of civilization. They emerged from the nearby Temple of Atal'Hakkar.\n\nStagalbog Cave sits at the edge of the mountains, a short distance west of Baba Bogbrew's camp.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Stagalbog Cave",
			short = "Stagalbog Cave is a large cave located in the Stagalbog in eastern Swamp of Sorrows. The cave used to be inhabited by many murlocs of the Marsh tribe and their leader, the Swamp Talker.",
			full = "Stagalbog Cave is a large cave located in the Stagalbog in eastern Swamp of Sorrows. The cave used to be inhabited by many murlocs of the Marsh tribe and their leader, the Swamp Talker.\n\nAs a result animals in the area began behaving oddly, acting more aggressively than usual and eventually making their way to the cave.\n\nA small camp of Steamwheedle Cartel goblins led by Baba Bogbrew lies outside the cave and immediately east.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Stonard",
			short = "Stonard is the lone Horde outpost located in the Swamp of Sorrows.",
			full = "Stonard is the lone Horde outpost located in the Swamp of Sorrows. Regular patrols are sent out, and a number of small orcish encampments have been established nearby to further strengthen the Horde's control over the region. It is one of the few orcish communities to still have a great hall in its midst and is protected by two burrows. Several trainers and vendors can be found at the post. Mages with sufficient skill can learn to teleport or open a portal to here.\n\nPreviously, Stonard was notable for being the location of the horde master alchemist and the only Horde shaman trainer in the Eastern Kingdoms.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Temple of Atal'Hakkar",
			short = "The Temple of Atal'Hakkar (also known as the Sunken Temple) is a shrine to the nefarious Blood God Hakkar the Soulflayer that was erected by the Atal'ai trolls led by their master Jammal'an the Prophet.",
			full = "The Temple of Atal'Hakkar (also known as the Sunken Temple) is a shrine to the nefarious Blood God Hakkar the Soulflayer that was erected by the Atal'ai trolls led by their master Jammal'an the Prophet. Believing that this was the intended site for Hakkar's reentry into Azeroth, the great Dragon Aspect Ysera and her green dragonflight sunk the temple into the depths of the Swamp of Sorrows. However, this actually helped the Atal'ai by ensuring their efforts to summon Hakkar went on undisturbed.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Westfall: 23 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Alexston Farmstead",
			short = "Alexston Farmstead is one of the many farms in northern and central Westfall that have once been taken over by the Defias Brotherhood.",
			full = "Alexston Farmstead is one of the many farms in northern and central Westfall that have once been taken over by the Defias Brotherhood. Since the fall of the organization, only the deadly mechanical Harvest Watchers roam the fields. Baros Alexston, an architect at the service of Stormwind City, hailed his humble origin from this very land, where he worked as a young boy.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasion, the area fell under the Burning Legion's control. Its residents were enslaved by nathrezim and were later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["cooper residence"] = {
			name = "Cooper Residence",
			short = "The Cooper Residence is a building located in Moonbrook in Westfall. It belonged to the Cooper family. [Dusty Journal] and The Moonbrook Times appear on the ground.",
			full = "The Cooper Residence is a building located in Moonbrook in Westfall. It belonged to the Cooper family. [Dusty Journal] and The Moonbrook Times appear on the ground.",
			source = "https://warcraft.wiki.gg/wiki/Cooper_Residence",
		},
		["dagger hills"] = {
			name = "Dagger Hills",
			short = "The Dagger Hills is actually a ridge, sitting behind Moonbrook in Westfall. The area is also called Southern Westfall.",
			full = "The Dagger Hills is actually a ridge, sitting behind Moonbrook in Westfall. The area is also called Southern Westfall. Nowadays the place is mostly devoid of life, with Grimbooze Thunderbrew being the only NPC who can be found there. Leprithus the ghoul can also arise in the area.\n\nDuring the Burning Legion's invasion, the area falls under the Legion's control. Its residents are enslaved by nathrezim and are later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "Dead Acre",
			short = "The Dead Acre was once one of many farms in southeast Westfall, close to the bridge leading into Duskwood.",
			full = "The Dead Acre was once one of many farms in southeast Westfall, close to the bridge leading into Duskwood. However, when the Defias Brotherhood took control of Westfall, they burned the farm that had once stood there, as well as the fields. Now, only the smoking ruins remain with mechanical Harvest Watchers roaming the smoldering fields.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasion, the area fell under the Burning Legion's control. Its residents were enslaved by nathrezim and were later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Deadmines",
			short = "The Deadmines are expansive, winding tunnels dug out under Westfall and part of northwestern Stranglethorn Vale. It is the lowest-level Alliance instance and is populated by members of the Defias Brotherhood.",
			full = "The Deadmines are expansive, winding tunnels dug out under Westfall and part of northwestern Stranglethorn Vale. It is the lowest-level Alliance instance and is populated by members of the Defias Brotherhood. Its entrance can be accessed in the town of Moonbrook in southwestern Westfall, while its exit is located in the western part of the Dagger Hills near the ocean.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["defias hideout"] = {
			name = "Defias Hideout",
			short = "The Defias Hideout is a building in Moonbrook and contains the hidden entrance upstairs that leads into the Deadmines.",
			full = "The Defias Hideout is a building in Moonbrook and contains the hidden entrance upstairs that leads into the Deadmines. It is often unoccupied because of the need for the bandits to be outside protecting the town from outsiders, or down in the mines themselves, working. It has recently been filled with vagrants like the rest of Moonbrook.",
			source = "https://warcraft.wiki.gg/wiki/Defias_Hideout",
		},
		["demonts place"] = {
			name = "Demont's Place",
			short = "Demont's Place lies just west of Moonbrook in Westfall. Like the Dead Acre, little remains of the original farmstead. It was previously occupied by Defias agents, but has been abandoned after the fall of the Brotherhood.",
			full = "Demont's Place lies just west of Moonbrook in Westfall. Like the Dead Acre, little remains of the original farmstead. It was previously occupied by Defias agents, but has been abandoned after the fall of the Brotherhood.\n\nDuring the Burning Legion's invasion, the area falls under the Legion's control. Its residents are enslaved by nathrezim and are later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Dust Plains",
			short = "The Dust Plains are the southernmost area of Westfall. The plains have a population of gnolls that threaten adventurers from their few camps.",
			full = "The Dust Plains are the southernmost area of Westfall. The plains have a population of gnolls that threaten adventurers from their few camps. An old mage tower known as Mortwake's Tower, recently taken over by mercenaries in the employ of Helix Gearbreaker, is located on the eastern edge of the plains.\n\nDuring the Burning Legion's invasion, the area falls under the Legion's control. Its residents are enslaved by nathrezim and are later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Furlbrow's Pumpkin Farm",
			short = "The Furlbrow's Pumpkin Farm (formerly known as Furlbrow's Pumpkin Patch) was one of the many farms in Westfall taken over by the Defias Brotherhood and their mechanical harvest golems.",
			full = "The Furlbrow's Pumpkin Farm (formerly known as Furlbrow's Pumpkin Patch) was one of the many farms in Westfall taken over by the Defias Brotherhood and their mechanical harvest golems. Farmer Furlbrow and his wife Verna fled during that time to the road near the Jansen Stead in northern Westfall.\n\nTheir farm was claimed by the Homeless Stormwind Citizens, Transients and similar individuals who can be found throughout the area. The farm also gained a flight path.\n\nDuring the Burning Legion's invasion, the area falls under the Legion's control. Its residents are enslaved by nathrezim and are later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Gold Coast Quarry",
			short = "The Gold Coast Quarry used to be a valuable mineral and gold mine in Westfall for the kingdom of Stormwind.",
			full = "The Gold Coast Quarry used to be a valuable mineral and gold mine in Westfall for the kingdom of Stormwind. As the region fell to ruins, the Defias Brotherhood once owned and patrolled the quarry for a long while, but since their defeat against the People's Militia, the quarry has been abandoned.\n\nThe duo and the members of the People's Militia were then ambushed by Defias members.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Jangolode Mine",
			short = "The Jangolode Mine was one of the key sources in Westfall of minerals for Stormwind City.",
			full = "The Jangolode Mine was one of the key sources in Westfall of minerals for Stormwind City. It was taken over by the Defias Brotherhood for a short time, however, when they were defeated the kobolds claimed the mine for themselves.\n\nDuring the Burning Legion's invasion, the area fell under the Legion's control. Its residents were enslaved by nathrezim and were later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "Jansen Stead",
			short = "The Jansen Stead is the northernmost farm in Westfall, and is located near the bridge to Elwynn Forest. Like most of the farms in Westfall, the owners have been driven off by the Defias Brotherhood.",
			full = "The Jansen Stead is the northernmost farm in Westfall, and is located near the bridge to Elwynn Forest. Like most of the farms in Westfall, the owners have been driven off by the Defias Brotherhood. The farm is occupied by a large amount of Homeless Stormwind Citizens, West Plains Drifters and Transients. The Jansen Stead is currently under investigation following the murder of Theodore and Verna Furlbrow nearby, but no one seems to want to reveal any details about their murder. This investigation eventually leads to the Furlbrows' nearby farm.\n\nPrivate Jansen of the Westfall Brigade is most likely connected to the farmstead.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Longshore",
			short = "Longshore is the vast stretch of coastline along Westfall. It is aptly named, being one of the biggest beaches on Azeroth.",
			full = "Longshore is the vast stretch of coastline along Westfall. It is aptly named, being one of the biggest beaches on Azeroth. Traveling along the coast can be tricky as swarms of murlocs (including Old Murk-Eye) roam the beaches unchecked. Many shipwrecks, including elven destroyers, lie off the coast.\n\nOn the far southwestern coast is the farm of Daphne Stilwell, who was attacked by members of the Defias Brotherhood until aspiring Knights of the Silver Hand sent by Duthorian Rall came to protect her. The Westfall Lighthouse is located off the far southern edge of Longshore.\n\nThe Half Pendant of Aquatic Endurance, which Alliance druids needed to collect to learn Aquatic Form, was stored in a Strange Lockbox near a shipwreck off northwestern Longshore.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "Molsen Farm",
			short = "The Molsen Farm is one of the many farms of Westfall that have once been taken over by the Defias Brotherhood. Since the fall of the organization, only the deadly mechanical Harvest Watchers roam the fields.",
			full = "The Molsen Farm is one of the many farms of Westfall that have once been taken over by the Defias Brotherhood. Since the fall of the organization, only the deadly mechanical Harvest Watchers roam the fields. Private Molsen of the Westfall Brigade may have a family connection with the farm.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasion, the area fell under the Burning Legion's control. Its residents were enslaved by nathrezim and were later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Moonbrook",
			short = "Moonbrook is a small town located southwest of Sentinel Hill, which once served as a mining town and the focal point of the farmlands in Westfall.",
			full = "Moonbrook is a small town located southwest of Sentinel Hill, which once served as a mining town and the focal point of the farmlands in Westfall. After being razed by the orcs during the First War, then rebuilt following the Second War, the rampant corruption in the kingdom brought the town under the control of the Defias Brotherhood. Without the Stormwind Army to protect them, the Defias drove out the citizens and used the Deadmines as their headquarters. After years of tyranny, the People's militia and the adventurers liberated Moonbrook after they killed the Brotherhood's leader, Edwin VanCleef.\n\nHowever, the war against the Lich King caused a financial crisis in the kingdom, and a high population of the homeless came to settle in Moonbrook. After the attack on Sentinel Hill, the Alliance heroes entered the Deadmines once again, where they wiped out all the new Defias leadership. In the following years, the town was once more supported by Stormwind, which protected it from bandits, the Riverpaw pack gnolls, and even demonic invasions. After his coronation, King Anduin Wrynn's reforms and aid to Westfall extinguished the spark of the revolution in the town.\n\nAlthough the town itself is devoid of vendors, the nearby camp of the Westfall Brigade to the northwest has a flight path and a few vendors.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["moonbrook schoolhouse"] = {
			name = "Moonbrook Schoolhouse",
			short = "The building is located in Moonbrook around southern Westfall and looks somewhat like a town hall. There is a cemetery behind it. It is the building in north-westernmost Moonbrook.",
			full = "The building is located in Moonbrook around southern Westfall and looks somewhat like a town hall. There is a cemetery behind it. It is the building in north-westernmost Moonbrook.\n\nAn Alliance adventurer was sent to the schoolhouse to find a letter in a footlocker that appeared in the main room of the ground floor, just short of the elevated part. It was revealed that the schoolhouse was built specifically for Stalvan Mistmantle, who eventually became its headmaster.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook_Schoolhouse",
		},
		["mortwakes tower"] = {
			name = "Mortwake's Tower",
			short = "Mortwake's Tower, formerly Klaven's Tower (named after its rogue Defias master Klaven Mortwake) lies at the southeastern edge of Westfall near the river and north of the Dagger Hills.",
			full = "Mortwake's Tower, formerly Klaven's Tower (named after its rogue Defias master Klaven Mortwake) lies at the southeastern edge of Westfall near the river and north of the Dagger Hills.\n\nSI:7 was previously scouting this mage tower (which was then identified as a watch tower) for some time and sometimes covertly sought help from adventurous rogues to sneak in and gather intelligence. It is such a well known launching point for Defias activity that it has also been called simply the \"Defias Tower\". Klaven's Tower was being used, along with Jerod's Landing in Elwynn Forest, in the smuggling of stolen goods from Redridge Mountains.\n\nDue to the fumes of the various troll poisons used by Mortwake, the inhabitants of the tower were especially weak to sneak attacks.\n\nWith the removal for the most part of class-specific quests, its primary purpose is for the quest [5-30] Secrets of the Tower.",
			source = "https://warcraft.wiki.gg/wiki/Mortwake's_Tower",
		},
		["raging chasm"] = {
			name = "Raging Chasm",
			short = "A huge beam of energy rises into the sky, surrounded by whirling trees and chunks of earth. The crater is populated by Chasm Slimes.",
			full = "A huge beam of energy rises into the sky, surrounded by whirling trees and chunks of earth. The crater is populated by Chasm Slimes.",
			source = "https://warcraft.wiki.gg/wiki/Raging_Chasm",
		},
		["saldeans farm"] = {
			name = "Saldean's Farm",
			short = "Saldean's Farm is unique in Westfall in that it is the only farm that was never completely overrun by the Defias Brotherhood.",
			full = "Saldean's Farm is unique in Westfall in that it is the only farm that was never completely overrun by the Defias Brotherhood. Though Defias harvest golems roam the fields, Farmer Saldean and his wife Salma Saldean have stubbornly refused to leave. The farmhouse has been serving as a halfway house for years, and the couple does its best to keep their guests alive.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Sentinel Hill",
			short = "Sentinel Hill is an Alliance settlement located in eastern Westfall. It has a flight path (gryphon roost), barracks-like inn, mailbox, forge, anvil, multiple cottages, and lumber mill down the hill from Sentinel Tower.",
			full = "Sentinel Hill is an Alliance settlement located in eastern Westfall. It has a flight path (gryphon roost), barracks-like inn, mailbox, forge, anvil, multiple cottages, and lumber mill down the hill from Sentinel Tower.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["sentinel tower"] = {
			name = "Sentinel Tower",
			short = "Sentinel Tower is a prominent landmark in Westfall. It stands upon the apex of Sentinel Hill as a scout tower to watch over the surrounding landscape.",
			full = "Sentinel Tower is a prominent landmark in Westfall. It stands upon the apex of Sentinel Hill as a scout tower to watch over the surrounding landscape. This is where one can find the Westfall Brigade's leaders, including Gryan Stoutmantle, the group's commander.\n\nAt some point, James Blackridge and his parents, accompanied by his friends Liam and Bram Woodring, came to take refuge at the Sentinel Tower after fleeing the Deadmines, where a conflict took place between the Defias Brotherhood and the Bloodsail Buccaneers.\n\nWhen Gryan tried to interrogate him about Helix Gearbreaker, he only announced the end for them. He was later freed by Vanessa VanCleef when the Defias Brotherhood attacked and burned Sentinel Hill, so that he could command the Juggernaught, which was being built in the Deadmines.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Tower",
		},
		["stendels pond"] = {
			name = "Stendel's Pond",
			short = "Stendel's Pond is a small pond, located southwest of Sentinel Hill in Westfall.",
			full = "Stendel's Pond is a small pond, located southwest of Sentinel Hill in Westfall.\n\nIt is currently surrounded by gnolls, a few skeleton remains and two graves, suggesting that the pond's water may be undrinkable.\n\n[Stendel's Bane], a very rare fish-item and the more common Sagefish Schools can both be found and fished up from the pond.\n\nDuring the Burning Legion's invasion, the area falls under the Legion's control. Its residents are enslaved by nathrezim and are later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Westfall Lighthouse",
			short = "The Westfall Lighthouse sits just off the coast on the far southern edge of Westfall. Outside the lighthouse stands the ghostly Captain Grayson, who tasked adventurers to kill the murlocs along the coast.",
			full = "The Westfall Lighthouse sits just off the coast on the far southern edge of Westfall. Outside the lighthouse stands the ghostly Captain Grayson, who tasked adventurers to kill the murlocs along the coast. The lighthouse was once staffed by humans, but Old Murk-Eye scared the keeper's family off. They returned and re-lit the flame but Old Murk-Eye coerced the murlocs to raid the Lighthouse with him once again. The second time the family was not so lucky, and before Grayson's eyes they perished helplessly. With no one to keep watch on the flame, the responsibility has fallen upon him.\n\nA beam of light will circle from the top of the lighthouse at night. During Children's Week, the Alliance Human Orphan will ask the adventurer to take him here.\n\nAt some point, James Blackridge, Liam, and Bram Woodring were captured by Jerias Bloodvein of the Bloodsail Buccaneers and his pirate crew at the lighthouse.\n\nMathias Shaw and Renzik \"The Shiv\" used to come to the Westfall Lighthouse, with Renzik leaving his belongings in the area. Following his death, they were collected, before Renzik's ashes were spread over Undermine.\n\nShaw cuts a notch into the doorway of the lighthouse for every SI:7 agent he loses. There are a lot of cuts in the door.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Wetlands: 27 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Angerfang Encampment",
			short = "The Angerfang Encampment, located in central Wetlands, is the largest Dragonmaw orc camp in the region, belonging to the Angerfang.",
			full = "The Angerfang Encampment, located in central Wetlands, is the largest Dragonmaw orc camp in the region, belonging to the Angerfang.\n\nThis section concerns content related to the original World of Warcraft.\n\nFormerly led by Nek'rosh Skullcrusher, son of Nekros Skullcrusher, their plan was to use the encampment as a rallying point to attack Menethil Harbor with catapults. The Alliance finally sent agents to deal with Nek'rosh, thus ending the Dragonmaw threat to Menethil. Captain Stoutfist had also adventurers bring him war banners from the defeated Angerfangs.\n\nHe was eventually attacked by Alliance adventurers sent by Prospector Whelgar to ensure that the Dragonmaw do not attack them at Whelgar's Retreat.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baradin Bay",
			short = "Baradin Bay is a portion of the Great Sea off the west coast of central Eastern Kingdoms. It spans from northwestern Dun Morogh in Khaz Modan, to southern Gilneas in Lordaeron.",
			full = "Baradin Bay is a portion of the Great Sea off the west coast of central Eastern Kingdoms. It spans from northwestern Dun Morogh in Khaz Modan, to southern Gilneas in Lordaeron. Important settlements located on its coast include: Menethil Harbor, Stromgarde Keep, the former township of Southshore, and Stormglen Village.\n\nDuring and after the Second War, the Kul Tiran armada patrolled the area regularly. Shipwrecks belonging to the seafaring nation's Third Fleet, destroyed in the Second War, can be seen on the coast of the Wetlands, while others have sunk to the bottom of the Great Sea.\n\nThe bay is inhabited by murlocs and crocolisks in the shallows, and crabs and sharks in the deeper water.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Black Channel Marsh",
			short = "Black Channel Marsh is located in the southwestern area of Wetlands.",
			full = "Black Channel Marsh is located in the southwestern area of Wetlands. It is mostly noted by travelers on the road to Menethil Harbor, and inexperienced adventurers are advised to take care because the marsh holds numerous raptor lairs and some of the hungrier beasts wander quite close to the road.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Bluegill Marsh",
			short = "Bluegill Marsh is located in the western Wetlands, and is the site of several Bluegill murloc camps. Many murlocs make their home here led by the ferocious Gobbler.",
			full = "Bluegill Marsh is located in the western Wetlands, and is the site of several Bluegill murloc camps. Many murlocs make their home here led by the ferocious Gobbler. Young travelers should tread carefully through the marsh because all the murlocs come in groups of two or three, and pulling one at a time is very tough. A few quests take you into Bluegill Marsh in hunt for murlocs or stolen goods.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Deepwater Tavern",
			short = "The Deepwater Tavern is situated in the Alliance town of Menethil Harbor in the territory of the Wetlands. It is a bustling village hub and a popular place for adventurers to find quests.",
			full = "The Deepwater Tavern is situated in the Alliance town of Menethil Harbor in the territory of the Wetlands. It is a bustling village hub and a popular place for adventurers to find quests. It holds a first aid trainer as well as a few vendors. It is frequently the site of bar brawls, many of which are initiated by Tapoke \"Slim\" Jahn.\n\nSince the disaster, the tavern appears to function as normal, with the sandbags being used as a bench by locals and riding rams and stable master outside seeming tolerant of the water. The tavern has become a place of refuge for some of those displaced by the flood, such as the Halloran family.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Direforge Hill",
			short = "Direforge Hill is located in northeastern Wetlands, southeast of Dun Modr, northeast of the Green Belt, and northwest of Raptor Ridge.",
			full = "Direforge Hill is located in northeastern Wetlands, southeast of Dun Modr, northeast of the Green Belt, and northwest of Raptor Ridge. It used to be a major campsite for Dark Iron dwarves led by the warlock Balgaras the Foul. Rampant Fire Elementals and Smouldering Oozes now torch the remains of the camps and the countryside, much to the distress of Rethiel the Greenwarden.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Dragonmaw Gates",
			short = "The Dragonmaw Gates are a set of four grandiose portals that block the winding path leading from the Wetlands up to Grim Batol in the Twilight Highlands.",
			full = "The Dragonmaw Gates are a set of four grandiose portals that block the winding path leading from the Wetlands up to Grim Batol in the Twilight Highlands. Once guarded by the red dragonflight, led by the powerful drake Axtroz, adventurers struck against the dragons at the gates.\n\nOne of the gates located at Wyrms' Bend was targeted by the Alliance and Horde forces attacking the Twilight's Hammer stronghold of Grim Batol. While being defended by the cultists, it was opened by the Horde's Gob Squad and Alliance's Highbank forces in order to reach the dwarven citadel.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "Dun Algaz (or Algaz Gate) is the tunneled mountain pass area between Loch Modan and the Wetlands, as well as the name of a stronghold located in the pass.",
			full = "Dun Algaz (or Algaz Gate) is the tunneled mountain pass area between Loch Modan and the Wetlands, as well as the name of a stronghold located in the pass. It is bordered by Algaz Station in Loch Modan and Slabchisel's Survey in the Wetlands.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Dun Modr is a fortified middle-sized dwarven city that sits along the road just south of Thandol Span, in the north of the Wetlands.",
			full = "Dun Modr is a fortified middle-sized dwarven city that sits along the road just south of Thandol Span, in the north of the Wetlands. It was occupied by Dark Iron dwarves, which claimed the fallen city as their own.\n\nThe city contains a blacksmith shop and an inn-brewery.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "Green Belt",
			short = "The Green Belt is an area of the eastern Wetlands which is home to crocolisks, bog beasts, and oozes. Rethiel the Greenwarden was also located here.",
			full = "The Green Belt is an area of the eastern Wetlands which is home to crocolisks, bog beasts, and oozes. Rethiel the Greenwarden was also located here. A wrecked Dragonmaw clan caravan can be found here with red whelps, implying it was destroyed in the aftermath of the Battle of Grim Batol.\n\nMeanwhile, the surrounding area had been affected by flooding and other unusual phenomena that have infuriated the Greenwarden. These problems included an infestation of malicious mirebeasts to the west, and fire elementals appearing from Direforge Hill to the northeast. To the southeast, a group of Dragonmaw Clan orcs renewed their effort to steal whelps of the black dragonflight, to the dismay of the black dragon Pyrricion and his slavers who can frequently be seen fighting with them.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["greenwardens grove"] = {
			name = "Greenwarden's Grove",
			short = "Greenwarden's Grove is a night elven outpost and quest hub, complete with a flight path.",
			full = "Greenwarden's Grove is a night elven outpost and quest hub, complete with a flight path.\n\nAfter they learned of Rethiel the Greenwarden from a local dwarven legend, which told of a plant-man acting as protector of the region, the night elves came to the Wetlands just to find him, and after they succeeded they ended up settling down. They founded a whole grove near him to watch over the Greenwarden. Ferilon Leafborn is the head druid there.\n\nThere are a tower and an inn. There's also a moonwell which, at some point, was visited by Arwis Blackstone.",
			source = "https://warcraft.wiki.gg/wiki/Greenwarden's_Grove",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Grim Batol is a mountain fortress located in the western Twilight Highlands (formerly in the eastern Wetlands). It has great walls and spires that reach toward a steel-gray sky, but the stronghold's bulk is underground.",
			full = "Grim Batol is a mountain fortress located in the western Twilight Highlands (formerly in the eastern Wetlands). It has great walls and spires that reach toward a steel-gray sky, but the stronghold's bulk is underground. It was founded by the Wildhammer dwarves until it was cursed during the War of the Three Hammers. It was later seized by orcs to serve as a prison for the Dragon Aspect Alexstrasza until she was freed during the Battle of Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Ironbeard's Tomb",
			short = "Ironbeard's Tomb is located just west of the road to Dun Modr in the north-central part of the Wetlands.",
			full = "Ironbeard's Tomb is located just west of the road to Dun Modr in the north-central part of the Wetlands. The crypt has been defiled by oozes in black, crimson, and monstrous varieties, and none who wish to bury their dead come here any longer. Adventurers used to journey to the tomb in hopes of locating Sida's lost bag, which could rarely be found on any given ooze in the area.\n\nBesides the crypt, there is also a graveyard and a dwarven statue, presumably of Ironbeard himself.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "Lost Fleet",
			short = "The Lost Fleet (also known as the Doomed Fleet, or the Third Fleet, and the Kul Tiras Third Fleet) are the remnants of the Kul Tiras fleet which was under the command of Derek Proudmoore during the Second War.",
			full = "The Lost Fleet (also known as the Doomed Fleet, or the Third Fleet, and the Kul Tiras Third Fleet) are the remnants of the Kul Tiras fleet which was under the command of Derek Proudmoore during the Second War. They were destroyed by red dragons controlled by the Dragonmaw clan and subsequently sunk in Baradin Bay off the coast of northern Bluegill Marsh. The ships located here are named Wave Mistress and Intrepid. A third ship, Flying Osprey, was part of the Third Fleet, but sank south of Menethil Harbor. The only survivor was First Mate Fitzsimmons of the Wave Mistress.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Menethil Bay",
			short = "Menethil Bay is a portion of the Great Sea off the west coast of the Wetlands in central Eastern Kingdoms. It is within Baradin Bay, its inlet between Menethil Harbor and the northern cliffs of Dun Morogh.",
			full = "Menethil Bay is a portion of the Great Sea off the west coast of the Wetlands in central Eastern Kingdoms. It is within Baradin Bay, its inlet between Menethil Harbor and the northern cliffs of Dun Morogh. The subsequent flooding of the nearby harbor filled the bay with sharks and crabs. The Flying Osprey wreckage is located in the bay's entrance.\n\nDirectly east of the bay is Black Channel Marsh.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Menethil Harbor",
			short = "Menethil Harbor is a dwarven port town located on a small island on the western shore of the Wetlands.",
			full = "Menethil Harbor is a dwarven port town located on a small island on the western shore of the Wetlands. A rough place that plays host to sailors, travelers, smugglers, and pirates, it's also a good place to purchase goods and even have a pint and relax. An Alliance stronghold, the most prominent shape here is the thick, stone wall which protects most of the town from inland incursions. Rising above all else, the four towers of Menethil Keep watch over the settlement like stern guardians. Except for the bridge, the only other ways of entering the town are by sea or by a secret underground path leading from the town to the mainland.\n\nIt has also The Lady Mehley boat that sails to the Ruins of Theramore in Dustwallow Marsh, on the continent of Kalimdor, and the Northspear icebreaker that goes to Valgarde in the Howling Fjord, on the continent of Northrend.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Menethil Keep",
			short = "Menethil Keep is the keep that dominates Menethil Harbor. Rising above all else, its four towers watch over the settlement like stern guardians.",
			full = "Menethil Keep is the keep that dominates Menethil Harbor. Rising above all else, its four towers watch over the settlement like stern guardians. It also held a few additional quest givers and a vendor. Menethil Keep has since been damaged by the flood and for a time fell under the control of the Twilight's Hammer.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Mosshide Fen",
			short = "Mosshide Fen is a region in the eastern part of the Wetlands which has fallen under control of the Mosshide tribe of gnolls.",
			full = "Mosshide Fen is a region in the eastern part of the Wetlands which has fallen under control of the Mosshide tribe of gnolls. Several of their camps dot the landscape, and their vicious leader Gnawbone commands his tribe to capture and eat any adventurers that they spot who are stalking through the marshlands looking for [Dwarven Tinder].",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Raptor Ridge",
			short = "Raptor Ridge is located in the eastern Wetlands, just northwest of the dangerous Dragonmaw Gates.",
			full = "Raptor Ridge is located in the eastern Wetlands, just northwest of the dangerous Dragonmaw Gates. The raptors lair here in large numbers, and the ridge also features a cavern where the fierce Razormaw Matriarch watches over her brood.\n\nAround the time of the war against the Lich King, Rhonin and Iridi arrived here. The mage told the draenei that most of the raptors had moved toward the direction of Menethil Harbor because they sensed what was going on in Grim Batol. After the situation in Grim Batol was dealt with, Rhonin was positive that the raptors would remain in the ridge and no longer encroach on Menethil Harbor.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Saltspray Glen",
			short = "Saltspray Glen is a small area in the northwestern Wetlands bordered by Bluegill Marsh to the south, Ironbeard's Tomb to the east, and Baradin Bay to the north and west.",
			full = "Saltspray Glen is a small area in the northwestern Wetlands bordered by Bluegill Marsh to the south, Ironbeard's Tomb to the east, and Baradin Bay to the north and west. Like Black Channel Marsh, Whelgar's Excavation Site, and Raptor Ridge, Saltspray Glen is crawling with the numerous raptors who nest here. The glen is so named for the ease with which the ocean throws seawater inland here when there is a strong wind blowing off from the bay.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["slabchisels survey"] = {
			name = "Slabchisel's Survey",
			short = "Slabchisel's Survey is a new dwarven camp established near the abandoned Gnoll camps close to Dun Algaz in the Wetlands.",
			full = "Slabchisel's Survey is a new dwarven camp established near the abandoned Gnoll camps close to Dun Algaz in the Wetlands.",
			source = "https://warcraft.wiki.gg/wiki/Slabchisel's_Survey",
		},
		["sundown marsh"] = {
			name = "Sundown Marsh",
			short = "Sundown Marsh, located to the northwest, is the deepest part of the Wetlands and where an odd couple make their home.",
			full = "Sundown Marsh, located to the northwest, is the deepest part of the Wetlands and where an odd couple make their home. Fradd Swiftgear and Wenna Silkbeard live here in a small stone dwelling with a windmill, called Swiftgear Station. They sell peculiar items they come across in the marsh, and also some uncommon recipes. The swampland on all sides are full of aggressive crocolisks, gnolls, raptors, bog beasts, and oozes, which discourages inexperienced adventurers from approaching.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["swiftgear station"] = {
			name = "Swiftgear Station",
			short = "Swiftgear Station is an outpost located in the northwest section of the Wetlands, within Sundown Marsh. Since then, Fradd built up the place into an outpost and it was named after him.",
			full = "Swiftgear Station is an outpost located in the northwest section of the Wetlands, within Sundown Marsh. Since then, Fradd built up the place into an outpost and it was named after him. Shilah Slabchisel is in charge of making sure that the place is safe enough for more settlement to start occurring.",
			source = "https://warcraft.wiki.gg/wiki/Swiftgear_Station",
		},
		["thandol span"] = {
			name = "Thandol Span",
			short = "The Thandol Span is a set of massive stone bridges connecting the Wetlands of northern Khaz Modan with the Arathi Highlands of southeastern Lordaeron.",
			full = "The Thandol Span is a set of massive stone bridges connecting the Wetlands of northern Khaz Modan with the Arathi Highlands of southeastern Lordaeron. It is one of the greatest engineering projects ever completed by the dwarves, having been under the guard of the Anvilmars for at least three generations. The area where it is located was once known as the Thandol Valley.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Thelgen Rock",
			short = "Thelgen Rock is an area in the southern Wetlands that is crawling with poisonous spiders. The name refers to an extensive cavern that stretches deep into the mountains.",
			full = "Thelgen Rock is an area in the southern Wetlands that is crawling with poisonous spiders. The name refers to an extensive cavern that stretches deep into the mountains. The caves hold deposits of [Incendicite Ore], needed for the quest Search for Incendicite. The spiders can be farmed for [Spider's Silk], though the drop rate is modest. Frustrated cartographers can also be seen roaming the area trying in vain to explore the last piece of their maps.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Whelgar's Excavation Site",
			short = "Whelgar's Excavation Site lies east of Menethil Harbor and southwest of Dun Modr in the Wetlands. Once a peaceful dwarven digsite, it was overrun by mottled raptors.",
			full = "Whelgar's Excavation Site lies east of Menethil Harbor and southwest of Dun Modr in the Wetlands. Once a peaceful dwarven digsite, it was overrun by mottled raptors. A small group of dwarves once resided here, trapped on a ridge overlooking the dig site, but they have since abandoned the site and evacuated to the nearby Whelgar's Retreat, where they set up a camp just off the main road.\n\nPaleolithic Elementals and Living Fossils, as well as the named Sarltooth (formerly alive and a quest objective, now a rare spawn), roam the area.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
		["whelgars retreat"] = {
			name = "Whelgar's Retreat",
			short = "Whelgar's Retreat is a dwarven outpost in the Wetlands on a hill outside the Whelgar Excavation Site.",
			full = "Whelgar's Retreat is a dwarven outpost in the Wetlands on a hill outside the Whelgar Excavation Site. Prospector Whelgar and his crew are searching for artifacts and fossils in the excavation site at the behest of the Explorer's League. The Retreat happens to be dangerously close to a Dragonmaw Clan encampment, which worries the Prospector.\n\nTwo paths lead to the camp, from the east and west. The western path leading here is off the road from Menethil Harbor around . It is marked by Explorer's League banners, torches, and dead raptors.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Retreat",
		},
	},
	-- Teldrassil: 18 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil is the giant tree and village in the center of Shadowglen, which is located in the northeastern corner of Teldrassil.",
			full = "Aldrassil is the giant tree and village in the center of Shadowglen, which is located in the northeastern corner of Teldrassil. The leader of Shadowglen, Tenaron Stormgrip, makes his home inside the very top of Aldrassil.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Ban'ethil Barrow Den",
			short = "Ban'ethil Barrow Den is a small barrow den in Teldrassil that was once one of the sacred places built by night elves to hold sleeping Druids of the Talon.",
			full = "Ban'ethil Barrow Den is a small barrow den in Teldrassil that was once one of the sacred places built by night elves to hold sleeping Druids of the Talon. However, control over it has recently been taken over by the corrupted furbolg Gnarlpine tribe, and is now a dangerous place to venture for a lone night elf. Its two sections are referred to as Lower Den and Upper Den.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Ban'ethil Hollow",
			short = "Ban'ethil Hollow is a small ravine in Teldrassil, located south of the road that leads from Dolanaar to Darnassus. The hollow is filled with many hostile furbolgs who will occasionally ambush adventurers on the road.",
			full = "Ban'ethil Hollow is a small ravine in Teldrassil, located south of the road that leads from Dolanaar to Darnassus. The hollow is filled with many hostile furbolgs who will occasionally ambush adventurers on the road. It is wise to exercise caution when traveling. The Ban'ethil Barrow Den is located in the back of the hollow.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "Cleft",
			short = "Not to be confused with the Cleft of Shadow in Orgrimmar.",
			full = "Not to be confused with the Cleft of Shadow in Orgrimmar.\n\nThe Cleft is a corrupted furbolg den located north west of Dolanaar in Teldrassil. The furbolg here are part of the Gnarlpine tribe and are led by Ursal the Mauler. They ambushed travelers along the road to Darnassus and were holding a group of slumbering druids captive. Moon Priestess Amara and her bodyguards guarded the road near the entrance.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["darnassus"] = {
			name = "Darnassus",
			short = "Darnassus (aka Darnassus City), now known as Remains of Darnassus, was the capital city of the night elves of the Alliance, found in western Teldrassil.",
			full = "Darnassus (aka Darnassus City), now known as Remains of Darnassus, was the capital city of the night elves of the Alliance, found in western Teldrassil. The High Priestess, Tyrande Whisperwind, resided in the Temple of the Moon, surrounded by other sisters of Elune and her mate, the Archdruid Malfurion Stormrage.\n\nDarnassus was the greatest city of the night elves, housing the leaders of both the druids and the faithful of Elune. It was carefully guarded by Sentinels, ancient protectors, and ancients of war. It was destroyed during the Burning of Teldrassil.",
			source = "https://warcraft.wiki.gg/wiki/Darnassus",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Dolanaar was a night elven village located in the central-eastern part of Teldrassil.",
			full = "Dolanaar was a night elven village located in the central-eastern part of Teldrassil. Found just southwest of Shadowglen, its central location made it involved in much of Teldrassil's regional affairs and the first major town usually encountered by aspiring night elf adventurers after leaving Shadowglen. Class trainers for all night elven classes, as well as profession training, were also available here.\n\nKoroleth and Kelestra used to live in the village.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nDuring the Burning of Teldrassil, the conflagration spread to Dolanaar.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Fel Rock",
			short = "Fel Rock is a now corrupted cave in Teldrassil. This once beautiful cave is located just north of Dolanaar and is infested with many grells.",
			full = "Fel Rock is a now corrupted cave in Teldrassil. This once beautiful cave is located just north of Dolanaar and is infested with many grells. It is also home to the vicious satyr Lord Melenas. The night elf druid Tallonkai Swiftroot sends alliance players into this foreboding cave to destroy Lord Melenas during the quest [1-30] Twisted Hatred.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Gnarlpine Hold",
			short = "Gnarlpine Hold lies in the far southwest corner of Teldrassil. It was formally home to the Gnarlpine furbolgs. Recently, corruption has taken over the area and many demons are now present.",
			full = "Gnarlpine Hold lies in the far southwest corner of Teldrassil. It was formally home to the Gnarlpine furbolgs. Recently, corruption has taken over the area and many demons are now present. A steady stream of demons flow out of the area to the north where Tarindrella and Teldrassil ancients meet for battle.\n\nDuring the Burning of Teldrassil, the conflagration spread to Gnarlpine Hold.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lake Al'Ameth",
			short = "Lake Al'Ameth is one of the largest bodies of water existing on Teldrassil. It is located just south of Dolanaar, though contains few fixtures apart from a small jetty.",
			full = "Lake Al'Ameth is one of the largest bodies of water existing on Teldrassil. It is located just south of Dolanaar, though contains few fixtures apart from a small jetty. Lately, many enraged timberlings have been sighted on the shores of the lake, and it is no longer safe.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "Oracle Glade",
			short = "The Oracle Glade is a shrine in the northwestern area of Teldrassil. It is home to the Oracle Tree, as well as the first and most powerful of Teldrassil's moonwells.",
			full = "The Oracle Glade is a shrine in the northwestern area of Teldrassil. It is home to the Oracle Tree, as well as the first and most powerful of Teldrassil's moonwells. Bloodfeather harpies have made nests in the area, threatening the Oracle Tree; a small group of Sentinels was dispatched to push them back. Malfurion Stormrage meditates here.\n\nThe Oracle Tree has a wide trunk and boughs shaped like a great eagle perched atop a mighty bear. Many whisper that it was grown by nature magic. The tree has carefully monitored Teldrassil's growth alongside the druids. It is capable of creating reports by shedding pieces of inscribed bark, which it uses to communicate with Archdruid Fandral Staghelm in Darnassus.\n\nWellspring Lake lies to the east. The road to the south connects with the main road just outside of Darnassus.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Pools of Arlithrien",
			short = "The Pools of Arlithrien is a collection of small pools in western Teldrassil, located south of the entrance to Darnassus. While once a peaceful area, the pools are now home to hostile wildlife.",
			full = "The Pools of Arlithrien is a collection of small pools in western Teldrassil, located south of the entrance to Darnassus. While once a peaceful area, the pools are now home to hostile wildlife. There is a lone moonwell in this area, abandoned by the night elves due to the threat of Gnarlpine furbolgs. The Pools of Arlithrien is found at .",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Rut'theran Village",
			short = "Rut'theran Village was a village port for the night elven city of Darnassus, located at the very bottom of the World Tree Teldrassil.",
			full = "Rut'theran Village was a village port for the night elven city of Darnassus, located at the very bottom of the World Tree Teldrassil. There is a portal here that goes directly into Darnassus, as well as three docks with regular boats going to the Exodar and Stormwind City. There is also a hippogryph roost that goes, for free, to both Darkshore and, for druids, Moonglade in Northern Kalimdor. The Midsummer Fire Festival braziers are lit here.\n\nIt was humble by night elf standards but with an exceedingly fresh appearance. In the hippogryph breeding area, hippogryph eggs were meticulously cared for and the young were raised. The kaldorei living in the village worked to support their capital above, but they also hosted all kinds of celebrations, like the Midsummer.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Shadowglen",
			short = "Shadowglen (or Shadow Glen) is the night elven starting area. It is found in the northeastern part of Teldrassil, which is just north of Starbreeze Village.",
			full = "Shadowglen (or Shadow Glen) is the night elven starting area. It is found in the northeastern part of Teldrassil, which is just north of Starbreeze Village. Like all starting areas, it has class trainers for all night elven classes.\n\nAfter the Burning of Teldrassil, Shadowglen Keepers fought against the Horde at Lor'danel in Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Shadowthread Cave",
			short = "Shadowthread Cave is in the northwest corner of the Shadowglen in Teldrassil.",
			full = "Shadowthread Cave is in the northwest corner of the Shadowglen in Teldrassil. While it has always been home to the great spiders of Teldrassil, recently the spiders have become increasingly hostile and the cave much more dangerous. The largest spider in the Shadowthread Cave is named Githyiss the Vile, a particularly nasty specimen that has been the bane of more than one inexperienced Kaldorei.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Starbreeze Village",
			short = "Starbreeze Village lies southeast of Shadowglen and east of Dolanaar in Teldrassil. Once a night elven village, Starbreeze became overrun by corrupted furbolgs of the Gnarlpine tribe.",
			full = "Starbreeze Village lies southeast of Shadowglen and east of Dolanaar in Teldrassil. Once a night elven village, Starbreeze became overrun by corrupted furbolgs of the Gnarlpine tribe. The village consists of a few small houses. Ferocitas the Dream Eater can be found in its outskirts and Uruson can be seen patrolling the village.\n\nDuring the Burning of Teldrassil, the conflagration spread to Starbreeze Village before it reached Darnassus.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring hovel"] = {
			name = "Wellspring Hovel",
			short = "Wellspring Hovel is a small hamlet located in Teldrassil on the main road between Darnassus and Dolanaar.",
			full = "Wellspring Hovel is a small hamlet located in Teldrassil on the main road between Darnassus and Dolanaar.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Hovel",
		},
		["wellspring lake"] = {
			name = "Wellspring Lake",
			short = "Wellspring Lake is a small lake northeast of Darnassus and southeast of the Oracle Glade in Teldrassil. Fed by a natural spring deep within the land of the World Tree, this small lake is drained by the Wellspring River.",
			full = "Wellspring Lake is a small lake northeast of Darnassus and southeast of the Oracle Glade in Teldrassil. Fed by a natural spring deep within the land of the World Tree, this small lake is drained by the Wellspring River. Previously a favored spot for night elven fishermen, the lake is now the home of corrupted timberlings. The surrounding area is also a dangerous place, as nightsabers and spiders infest the landscape.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Wellspring River",
			short = "Wellspring River comes from a natural spring that lies deep within the great tree Teldrassil.",
			full = "Wellspring River comes from a natural spring that lies deep within the great tree Teldrassil. The river flows north from Wellspring Lake and cascades over the edge of Teldrassil in a great waterfall to the sea, far below. Crazed timberlings now patrol the banks of the river, attacking anyone who wanders near.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Darkshore: 48 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "The ruins of Ameth'Aran can be found to the southeast of the Ruins of Auberdine, and east from the Blazing Strand, in Darkshore.",
			full = "The ruins of Ameth'Aran can be found to the southeast of the Ruins of Auberdine, and east from the Blazing Strand, in Darkshore. Once it was a place where the servants of Queen Azshara freely practiced their powerful magics. Now it is inhabited by the restless spirits of the Highborne that once dwelt within its walls.\n\nIn Ameth'Aran's ruins lie two large ancient tablets, scrawled with the stories of the town and its fall.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["apothecary darkshore"] = {
			name = "Apothecary (Darkshore)",
			short = "Apothecary is a Forsaken tent in Gloomtide Strand in Darkshore. It contains Alchemy Vat.",
			full = "Apothecary is a Forsaken tent in Gloomtide Strand in Darkshore. It contains Alchemy Vat.\n\nWhen the Alliance controls Darkshore, Druids of the Branch plant growth over it.",
			source = "https://warcraft.wiki.gg/wiki/Apothecary_(Darkshore)",
		},
		["ashenvale front"] = {
			name = "Ashenvale Front",
			short = "The Ashenvale Front is located in Darkshore.",
			full = "The Ashenvale Front is located in Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Ashenvale_Front",
		},
		["ashwood depot"] = {
			name = "Ashwood Depot",
			short = "Ashwood Depot is a Horde camp found in northern Darkshore after the War of the Thorns. It is run by Forsaken and goblins, and is featured in the fighting for the Battle for Darkshore.",
			full = "Ashwood Depot is a Horde camp found in northern Darkshore after the War of the Thorns. It is run by Forsaken and goblins, and is featured in the fighting for the Battle for Darkshore.\n\nThe camp's commander was Deathstalker Commander Belmont. The camp was eventually attacked by Tyrande Whisperwind herself, now the avatar of the Night Warrior. While Belmont taunted Tyrande that the entirety of Darkshore would soon bolster the Forsaken's armies, Tyrande slew Belmont's forces then froze him in place and left him to rot.\n\nWhen the Alliance controls Darkshore, the area is overgrown with trees. Worgen are seen defusing the ordnance left here by the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Ashwood_Depot",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine was a night elven town in Darkshore.",
			full = "Auberdine was a night elven town in Darkshore.\n\nAuberdine lay on the shores of the Veiled Sea within the region of Darkshore. The closeness of the sea produced a damp climate, with a seemingly omnipresent cover of storm clouds. The town was surrounded by hills and pine forests.\n\nAuberdine featured typical night elven architecture - low-slung, arched, wooden buildings. It had stone and earthen streets, the paths and bridges illuminated by lamps. The town had both residential and commercial areas. It only had a few public gathering places, these included the Last Haven Tavern, another inn, the town square and the hunter's hall. Auberdine also had a prominent port, with both passenger and cargo ships from the Eastern Kingdoms calling here. The port had its own, unique lighthouse of night elven design.\n\nThe houses in the town had wooden floors and furniture typical of elven architecture. A domicile visited by Broll Bearmantle had the typical trappings of a night elven home, with plant life within. It had sleeping quarters, where the inhabitants could lay on woven mats.\n\nThe mainland location of the town, as well as its port, made it the prime location for night elves trading with the outside world. This produced a racially mixed population that included dwarves, gnomes, humans and even high elves. To help the outsiders, Auberdine was unusually well lit for a night elven settlement, and featured some bilingual signposts in both Darnassian and Common.\n\nThe town was led by the elder Thundris Windweaver, who had stewardship of the day-to-day affairs of the townsfolk. He was supported by the Auberdine Village Council, who hired adventurers for a number of purposes. The defense was coordinated by the local Sentinels, with Sentinel Glynda Nal'Shea reporting directly to the council.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["auberdine coast"] = {
			name = "Auberdine Coast",
			short = "Auberdine Coast is an area in Darkshore that contains a long pier coming from the Ruins of Auberdine. Wisps can be seen tending to it.",
			full = "Auberdine Coast is an area in Darkshore that contains a long pier coming from the Ruins of Auberdine. Wisps can be seen tending to it.\n\nWhen the Horde controls the zone, the pier is destroyed. When the Alliance is in control, the pier stands proud.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine_Coast",
		},
		["auberdine refugee camp"] = {
			name = "Auberdine Refugee Camp",
			short = "The Auberdine Refugee Camp is located just outside the Ruins of Auberdine in Darkshore. It houses some of the original Auberdine inhabitants, as well as other NPCs.",
			full = "The Auberdine Refugee Camp is located just outside the Ruins of Auberdine in Darkshore. It houses some of the original Auberdine inhabitants, as well as other NPCs. Archaeologist Hollee also reaches the camp after [5-30] The Last Refugee.\n\nIn the Battle for Darkshore, the camp was lit on fire.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine_Refugee_Camp",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Bashal'Aran is a night elven ruin found to the southwest of Lor'danel in northern Darkshore, formerly consisting of ancient Highborne ruins.",
			full = "Bashal'Aran is a night elven ruin found to the southwest of Lor'danel in northern Darkshore, formerly consisting of ancient Highborne ruins.\n\nDuring the Battle for Darkshore, the ruins could be captured and turned into a night elven or a Forsaken base of operations, from where to launch an attack against the Alliance or Horde forces controlling the region. The warfront was won by the Alliance, but Bashal'Aran was later left in ruins once again.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["bashalaran collapse"] = {
			name = "Bashal'Aran Collapse",
			short = "The Bashal'Aran Collapse is a subzone of Darkshore. It is at least in part the remains of Bashal'Aran. It is located under the Maw of the Void.",
			full = "The Bashal'Aran Collapse is a subzone of Darkshore. It is at least in part the remains of Bashal'Aran. It is located under the Maw of the Void. Upon landing in a pool of water, the player finds Bielara Ivyshroud, a member of the Cenarion Circle, who will teleport the player back to the surface should you ask her. Behind her is a path spiraling up to the right containing two Forlorn Highborne, with Telarius Voidstrider, a demon hunter, located on a cliff at the end, performing some kind of ritual. Killing him yields the [Writings of the Dark Herald], which begins a quest. Completing the quest awards you [Ghosts in the Dark]. When you have the Writings return to Bielara Ivyshroud to leave.\n\nFollowing the Battle for Darkshore there is no way to access it, at the present time.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran_Collapse",
		},
		["bitterstone quarry"] = {
			name = "Bitterstone Quarry",
			short = "Bitterstone Quarry is located north of the Eye of the Vortex and east of the Auberdine Refugee Camp in Darkshore.",
			full = "Bitterstone Quarry is located north of the Eye of the Vortex and east of the Auberdine Refugee Camp in Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Bitterstone_Quarry",
		},
		["blackwood camp"] = {
			name = "Blackwood Camp",
			short = "Blackwood Camp is a settlement of the Blackwood tribe of furbolg. It is located south of the Ruins of Auberdine and southwest of the Eye of the Vortex in Darkshore.",
			full = "Blackwood Camp is a settlement of the Blackwood tribe of furbolg. It is located south of the Ruins of Auberdine and southwest of the Eye of the Vortex in Darkshore.\n\nThey were cleansed and the satyr killed using a night elf ritual. Malfurion Stormrage called upon their leader, Elder Brownpaw, to stop the land from tearing apart further. The Blackwoods obliged once the fire elemental threat had been stopped.\n\nDuring the War of the Thorns, the camp was taken by Horde Poachers. In the Battle for Darkshore, the furbolgs had reclaimed it, but most were dead and Gren Tornfur was corrupted.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Camp",
		},
		["blackwood den"] = {
			name = "Blackwood Den",
			short = "The Blackwood Den, sometimes known as Blackwood Hold, was located in the far southern area of Darkshore, near the border with Ashenvale.",
			full = "The Blackwood Den, sometimes known as Blackwood Hold, was located in the far southern area of Darkshore, near the border with Ashenvale. It was comprised of a few corrupted furbolg camps and a small cave. Inside the cave sat a lone night elf named Volcor who awaited rescue. Adventurers had to talk to someone in Auberdine in order to help Volcor get out of his predicament.\n\nBy the time of the Battle for Darkshore, they had renamed it Kor'gar.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["blazing strand"] = {
			name = "Blazing Strand",
			short = "The Blazing Strand is a fiery swath of destruction stretching from Ameth'Aran all the way west to the shore in Darkshore.",
			full = "The Blazing Strand is a fiery swath of destruction stretching from Ameth'Aran all the way west to the shore in Darkshore.\n\nDuring the War of the Thorns, Bilgewater goblins set up oil operations here. Sometime after, during the Battle for Darkshore, the area was taken by the Twilight's Hammer.",
			source = "https://warcraft.wiki.gg/wiki/Blazing_Strand",
		},
		["cinderfall grove"] = {
			name = "Cinderfall Grove",
			short = "Cinderfall Grove is a base located north of Bashal'Aran in Darkshore. It is contested during the Battle for Darkshore.",
			full = "Cinderfall Grove is a base located north of Bashal'Aran in Darkshore. It is contested during the Battle for Darkshore.\n\nWhen the Horde controls Darkshore, the grove's trees are being cut down while Forsaken and goblin soldiers patrol it and the Certified Explosives Expert is throwing bombs on the road.\n\nWhen the Alliance controls Darkshore, night elf forces control the camps while worgen are defusing the ordnance left here by the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Cinderfall_Grove",
		},
		["cliffspring falls"] = {
			name = "Cliffspring Falls",
			short = "The Cliffspring Falls (also known as the Cliffwater Falls) are the origin of the Cliffspring River in Darkshore, serving as the principal source of drinking water for the region.",
			full = "The Cliffspring Falls (also known as the Cliffwater Falls) are the origin of the Cliffspring River in Darkshore, serving as the principal source of drinking water for the region. Once a pure waterfall, the cave that is the source of the falls has become corrupted, like much of the surrounding area. Some believe the corruption is seeping from nearby Felwood while others believe that members of the Twilight's Hammer cult are responsible. Members of the cult have been found deep within the caves at the waterfall's source. The cave is also crawling with naga.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring hollow"] = {
			name = "Cliffspring Hollow",
			short = "Cliffspring Hollow is a cave behind Cliffspring Falls. Zenn Foulhoof resides here, leading a group of satyrs and grells in a scheme to spread a corruption amoungst the wildlife.",
			full = "Cliffspring Hollow is a cave behind Cliffspring Falls. Zenn Foulhoof resides here, leading a group of satyrs and grells in a scheme to spread a corruption amoungst the wildlife. Apothecary Furrows can also be found here.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Hollow",
		},
		["cliffspring river"] = {
			name = "Cliffspring River",
			short = "The Cliffspring River is a river in the northern part of Darkshore. It flows from the Cliffspring Falls out to the sea.",
			full = "The Cliffspring River is a river in the northern part of Darkshore. It flows from the Cliffspring Falls out to the sea. The river, like so many parts of Darkshore, is tainted by the local Stormscale naga and local wildlife which drinks from it often become sick.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["delaryns demise"] = {
			name = "Delaryn's Demise",
			short = "Delaryn's Demise is an area on Mist's Edge west of Lor'danel Landing in Darkshore. It is here that Delaryn Summermoon died after Warchief Sylvanas Windrunner ordered the destruction of Teldrassil.",
			full = "Delaryn's Demise is an area on Mist's Edge west of Lor'danel Landing in Darkshore. It is here that Delaryn Summermoon died after Warchief Sylvanas Windrunner ordered the destruction of Teldrassil.\n\nThe bodies of Ralara, Sarvonis, Tavar, and Slaughtered Sentinels are also found here.",
			source = "https://warcraft.wiki.gg/wiki/Delaryn's_Demise",
		},
		["dredge"] = {
			name = "Dredge",
			short = "The Dredge is a goblin platform located on the Veiled Sea north of Lor'danel Landing, in Darkshore. It belongs to the Bilgewater's Dredge Fleet.",
			full = "The Dredge is a goblin platform located on the Veiled Sea north of Lor'danel Landing, in Darkshore. It belongs to the Bilgewater's Dredge Fleet. Sira Moonwarden, one of the Horde commanders of the Battle for Darkshore, is located here when the Alliance is attacking. When the Horde is attacking, it is overgrown with plants and used as a base for Maiev Shadowsong.",
			source = "https://warcraft.wiki.gg/wiki/Dredge",
		},
		["earthshatter cavern"] = {
			name = "Earthshatter Cavern",
			short = "Earthshatter Cavern is a cavern filled with Twilight's Hammer agents and enslaved earth elementals near Ameth'Aran.",
			full = "Earthshatter Cavern is a cavern filled with Twilight's Hammer agents and enslaved earth elementals near Ameth'Aran.\n\nThe Twilight's Hammer have opened a portal to the Emerald Nightmare inside, where they are keeping Thessera imprisoned.",
			source = "https://warcraft.wiki.gg/wiki/Earthshatter_Cavern",
		},
		["eye of the vortex"] = {
			name = "Eye of the Vortex",
			short = "It was located very near Ameth'Aran. The land twisted up into a hill, the top of which holds a massive vortex which can be seen across the zone.",
			full = "It was located very near Ameth'Aran. The land twisted up into a hill, the top of which holds a massive vortex which can be seen across the zone. Twilight's Hammer agents flew near the top of the vortex, and kept the storm from dissipating.\n\nUsing every ounce of his power, the newly reawakened Malfurion Stormrage attempted to stabilize the storm, managing to prevent it from shattering Darkshore and sweeping the region away into the ocean. With the help of Elder Brownpaw, Selenn, Aroom, and Thessera, the Twilight's Hammer helping the storm are stopped.\n\nThe tornado was gone by the time of the War of the Thorns.\n\nDuring the Battle for Darkshore, the area was taken by the Twilight's Hammer.",
			source = "https://warcraft.wiki.gg/wiki/Eye_of_the_Vortex",
		},
		["forlorn crossing"] = {
			name = "Forlorn Crossing",
			short = "Forlorn Crossing is a crossroads between Bashal'Aran, Gloomtide Strand, Cinderfall Grove, and Ashwood Depot in Darkshore.",
			full = "Forlorn Crossing is a crossroads between Bashal'Aran, Gloomtide Strand, Cinderfall Grove, and Ashwood Depot in Darkshore.\n\nWhen the Alliance controls Darkshore, a lot of night elven forces patrol the area.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Crossing",
		},
		["gloomtide strand"] = {
			name = "Gloomtide Strand",
			short = "Gloomtide Strand is a camp created in western Darkshore after the War of the Thorns. It has Horde architecture. The area is featured in the fighting during the Battle for Darkshore.",
			full = "Gloomtide Strand is a camp created in western Darkshore after the War of the Thorns. It has Horde architecture. The area is featured in the fighting during the Battle for Darkshore.\n\nWhen the Horde controls Darkshore, it is run by the Forsaken. They have plague wagons active in the area. An Apothecary is found here.\n\nWhen the Alliance controls Darkshore, Druids of the Branch are regrowing the forest in the area, including over the Horde building itself. The camp is guarded by Sentinels.",
			source = "https://warcraft.wiki.gg/wiki/Gloomtide_Strand",
		},
		["grove of the ancients"] = {
			name = "Grove of the Ancients",
			short = "The Grove of the Ancients is a sacred ruin of an old night elven temple, where Onu, an Ancient of Lore, resides together with a pair of merchants and a sleeping druid.",
			full = "The Grove of the Ancients is a sacred ruin of an old night elven temple, where Onu, an Ancient of Lore, resides together with a pair of merchants and a sleeping druid. The grove lies in the southeastern part of Darkshore, nestled near the mountains, and is built around the surging Wildbend River. The Circle of Ancients meets here.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["korgar"] = {
			name = "Kor'gar",
			short = "Kor'gar is an orc outpost located on what once was the furbolg settlement of Blackwood Den, home to the Blackwood tribe.",
			full = "Kor'gar is an orc outpost located on what once was the furbolg settlement of Blackwood Den, home to the Blackwood tribe. It was taken by the Horde during the War of the Thorns and by the time of the Battle for Darkshore it had been already renamed.",
			source = "https://warcraft.wiki.gg/wiki/Kor'gar",
		},
		["long wash"] = {
			name = "Long Wash",
			short = "The Long Wash is ironically enough the shortest stretch of coast in Darkshore. It is the desolate stretch of sand that runs south from the Ruins of Auberdine until due west of Ameth'Aran.",
			full = "The Long Wash is ironically enough the shortest stretch of coast in Darkshore. It is the desolate stretch of sand that runs south from the Ruins of Auberdine until due west of Ameth'Aran. The shore is gloomy and dark under the perpetual overcast skies of Darkshore, and the beach is littered with debris and the carcasses of dead sea animals. Murlocs have recently been showing up with greater frequency along the coastline.\n\nDuring the War of the Thorns, the area became a small battlefield between the night elves and the invading Horde, hunting for food.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["lordanel"] = {
			name = "Lor'danel",
			short = "Lor'danel is a seaside night elf settlement in northern Darkshore. Unlike the rest of Darkshore, the ground and trees here are vibrant green.",
			full = "Lor'danel is a seaside night elf settlement in northern Darkshore. Unlike the rest of Darkshore, the ground and trees here are vibrant green. Lor'danel features an inn, a flight path, and a moonwell. Despite its coastal location, the town has no dock; instead, it is connected to Rut'theran Village by a flight path, which is automatically known by night elves upon character creation and learned by other Alliance characters by visiting either the Lor'danel or Rut'theran Village flight master.",
			source = "https://warcraft.wiki.gg/wiki/Lor'danel",
		},
		["lordanel landing"] = {
			name = "Lor'danel Landing",
			short = "Lor'danel Landing was a new camp established by the Horde in Darkshore after the War of the Thorns and the blighting of the night elven town of Lor'danel.",
			full = "Lor'danel Landing was a new camp established by the Horde in Darkshore after the War of the Thorns and the blighting of the night elven town of Lor'danel. It is located on the shore of the Veiled Sea, just west of Lor'danel, within the region called Mist's Edge. It was occupied by the Forsaken.",
			source = "https://warcraft.wiki.gg/wiki/Lor'danel_Landing",
		},
		["lornesta mine"] = {
			name = "Lornesta Mine",
			short = "Lornesta Mine is a subzone in the Battle for Darkshore.",
			full = "Lornesta Mine is a subzone in the Battle for Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Lornesta_Mine",
		},
		["masters glaive"] = {
			name = "Master's Glaive",
			short = "The Master's Glaive is located in the southwest part of Darkshore. It is a massive, adamantine glaive embedded in the skull of Soggoth the Slitherer, Herald of the Old Gods.",
			full = "The Master's Glaive is located in the southwest part of Darkshore. It is a massive, adamantine glaive embedded in the skull of Soggoth the Slitherer, Herald of the Old Gods. Onu, the Ancient of Lore, said that an \"old, old lord of the earth\" fell here, and sent players to investigate.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["maw of the void"] = {
			name = "Maw of the Void",
			short = "The Maw of the Void is a subzone of Darkshore southeast of Lor'danel. It is a massive whirlpool that all of the water of the zone, like the Cliffspring River, drains into.",
			full = "The Maw of the Void is a subzone of Darkshore southeast of Lor'danel. It is a massive whirlpool that all of the water of the zone, like the Cliffspring River, drains into. Jumping into it treats the player to a short cutscene of their character being sucked into the whirlpool. Players end up in the Bashal'Aran Collapse, falling a far distance, but lands safely. It is possible to obtain [Going Down?] without a chance of death from the fall. During Brewfest you can get completely smashed and jump into the whirlpool to get [Almost Blind Luck].\n\nDuring the Battle for Darkshore, the area was taken by the Twilight's Hammer.",
			source = "https://warcraft.wiki.gg/wiki/Maw_of_the_Void",
		},
		["mists edge"] = {
			name = "Mist's Edge",
			short = "Mist's Edge is by far the longest stretch of coast in Darkshore, reaching all the way from near the Ruins of Auberdine in the south through Lor'danel to the region's northern tip past the Shatterspear War Camp.",
			full = "Mist's Edge is by far the longest stretch of coast in Darkshore, reaching all the way from near the Ruins of Auberdine in the south through Lor'danel to the region's northern tip past the Shatterspear War Camp. It is dominated by gloomy bays and gray beaches, often littered with huge carcasses of sea animals -- which are part of some quests -- and dotted with the wrecks of sunken ships. Murlocs are an ever-present threat, but even more common are the crabs which scuttle along the entire stretch of shore.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["moonspray"] = {
			name = "Moonspray",
			short = "The Moonspray is a night elven transport vessel that serves as part of the Kaldorei Fleet in Kalimdor.",
			full = "The Moonspray is a night elven transport vessel that serves as part of the Kaldorei Fleet in Kalimdor.",
			source = "https://warcraft.wiki.gg/wiki/Moonspray",
		},
		["moontouched den"] = {
			name = "Moontouched Den",
			short = "Moontouched Den is a small wildkin enclave located in Darkshore, east of the Ruins of Auberdine. It contains a group of wildkin nests and fetishes.",
			full = "Moontouched Den is a small wildkin enclave located in Darkshore, east of the Ruins of Auberdine. It contains a group of wildkin nests and fetishes. The den proper is a small cave whose sole occupant is Aroom, the last surviving wildkin in the area. The other wildkin here are crazed spirits.\n\nAfter the War of the Thorns, the Horde moved into Darkshore and the Bilgewater Cartel began a mining operation at Moontouched Den, just north of Aroom's cave.",
			source = "https://warcraft.wiki.gg/wiki/Moontouched_Den",
		},
		["nazjvel"] = {
			name = "Nazj'vel",
			short = "Nazj'vel is located far south off the coast of the Twilight Shore in Darkshore and is home to the naga.",
			full = "Nazj'vel is located far south off the coast of the Twilight Shore in Darkshore and is home to the naga.\n\nThe entrance to the cave has been collapsed, but a pile of explosives is found in front of the rubble, indicating that the goblins intend to re-enter it. When the Horde is in control of Darkshore, Nazj'vel is taken by Gilnean worgen who destroyed the goblins' machinery. Adventurers are sent here to defeat enemy factions.",
			source = "https://warcraft.wiki.gg/wiki/Nazj'vel",
		},
		["remtravels excavation"] = {
			name = "Remtravel's Excavation",
			short = "Remtravel's Excavation is an archeological dig site in Darkshore named after the famous archaeologist, Prospector Remtravel.",
			full = "Remtravel's Excavation is an archeological dig site in Darkshore named after the famous archaeologist, Prospector Remtravel.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of auberdine"] = {
			name = "Ruins of Auberdine",
			short = "While partially rebuilt by the night elves in the aftermath of the battle, a large portion of the town still remains ruined.",
			full = "While partially rebuilt by the night elves in the aftermath of the battle, a large portion of the town still remains ruined.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Auberdine",
		},
		["ruins of lornesta"] = {
			name = "Ruins of Lornesta",
			short = "Ruins of Lornesta is a subzone of Darkshore. It is a flooded ruin full of Darkscale Scouts led by Lady Janira. Fuming Toadstools can also be found here.",
			full = "Ruins of Lornesta is a subzone of Darkshore. It is a flooded ruin full of Darkscale Scouts led by Lady Janira. Fuming Toadstools can also be found here.\n\nBy the time of the Battle for Darkshore, a cave opened up which came to be called the Lornesta Mine. When the Alliance controls Darkshore, they control the ruins. When the Horde controls Darkshore, the Darkscale naga control the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lornesta",
		},
		["ruins of mathystra"] = {
			name = "Ruins of Mathystra",
			short = "The Ruins of Mathystra are located in northern Darkshore, just past the Tower of Althalaxx.",
			full = "The Ruins of Mathystra are located in northern Darkshore, just past the Tower of Althalaxx. Mathystra used to be a night elven city before the Great Sundering, but it was utterly decimated by the destruction of the Well of Eternity, and has long since been abandoned by the night elves in favor of the smaller coastal villages further south.\n\nThe ruins contain scattered relics of the old Highborne, and young night elves sometimes attempt to search through Mathystra in search of these relics. Ghost Sabers can also be found here.\n\nThe ancient ruins were inhabited for a time by the Stormscale Naga, who aggressively guarded against any intrusions from outside sources. They established the Shatterspear War Camp next to the ruins. Several night elves are now scouting the area to learn about the trolls' intentions and movements.\n\nDuring the War of the Thorns, the area became a battlefield between the Horde and the night elves.\n\nWith the Battle for Darkshore, the Horde's actions drove the night elf spirits to madness. It is now solely occupied by the spirits of the Highborne.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["shatterspear pass"] = {
			name = "Shatterspear Pass",
			short = "After the Shatterspear tribe joined the Horde, the Horde built the pass leading to their vale with palisade walls at the bottom and towers along the road leading up to the tunnel entrance.",
			full = "After the Shatterspear tribe joined the Horde, the Horde built the pass leading to their vale with palisade walls at the bottom and towers along the road leading up to the tunnel entrance.\n\nAfter the War of the Thorns, the Shatterspear have recaptured the area. Moxo the Beheader patrols the pass.\n\nThey are said to be either failed messengers or those who sought a way out by force. The troll ambassador was glad to use the pass instead of tempting the same fate.",
			source = "https://warcraft.wiki.gg/wiki/Shatterspear_Pass",
		},
		["shatterspear vale"] = {
			name = "Shatterspear Vale",
			short = "Shatterspear Vale is a small valley surrounded by mountainous cliffs on all sides that houses a village inhabited by the trolls of the Shatterspear tribe in Darkshore in Kalimdor.",
			full = "Shatterspear Vale is a small valley surrounded by mountainous cliffs on all sides that houses a village inhabited by the trolls of the Shatterspear tribe in Darkshore in Kalimdor.\n\nMountains and trees ring the vale, skimming the sky. For thousands of years, its waterfall beat against the ground, carving the bowl of the vale. The waterfall flows into a large pool whose shoreline is doted with Shatterspear huts and smaller fishing tents.",
			source = "https://warcraft.wiki.gg/wiki/Shatterspear_Vale",
		},
		["shatterspear war camp"] = {
			name = "Shatterspear War Camp",
			short = "Shatterspear War Camp is a Horde encampment located north of the Ruins of Mathystra in Darkshore. It is populated by Shatterspear trolls from Shatterspear Vale preparing an attack to Lor'danel.",
			full = "Shatterspear War Camp is a Horde encampment located north of the Ruins of Mathystra in Darkshore. It is populated by Shatterspear trolls from Shatterspear Vale preparing an attack to Lor'danel. The camp has several orc and tauren Horde Enforcers, and holds some night elf prisoners. By the ocean, the war camp has its own dock.",
			source = "https://warcraft.wiki.gg/wiki/Shatterspear_War_Camp",
		},
		["tower of althalaxx"] = {
			name = "Tower of Althalaxx",
			short = "The Tower of Althalaxx is a tower located in northern Darkshore.",
			full = "The Tower of Althalaxx is a tower located in northern Darkshore. It was once one of the major sites of the Alliance quest chain revolving around Athrikus Narassin and repairing the damage he had caused along with the Shadow Council.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight shore darkshore"] = {
			name = "Twilight Shore (Darkshore)",
			short = "The Twilight Shore is a stretch of coast in southern Darkshore. It lies south of the Long Wash, which ends due west of Ameth'Aran, and runs all the way south to Ashenvale.",
			full = "The Twilight Shore is a stretch of coast in southern Darkshore. It lies south of the Long Wash, which ends due west of Ameth'Aran, and runs all the way south to Ashenvale. The Twilight Shore is the most rugged part of Darkshore's coast, and the gray beaches get broken up by jutting cliffs and small islands in the south. Murlocs are abundant here, and the waters bulge with aggressive threshadons who do not hesitate to attack adventurers swimming for shore.\n\nDuring the Battle for Darkshore, the Darkscale naga took advantage of the turmoil between the Alliance and Horde to invade the Twilight Shore.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Shore_(Darkshore)",
		},
		["twilight vale"] = {
			name = "Twilight Vale",
			short = "Twilight Vale is the name of the southern forests of Darkshore, starting south of Ameth'Aran until the border with Ashenvale.",
			full = "Twilight Vale is the name of the southern forests of Darkshore, starting south of Ameth'Aran until the border with Ashenvale. Like the rest of Darkshore, the woods of the Twilight Vale are crawling with corrupted furbolgs, feral nightsabers, and rabid bears. Travelers are advised to stick to the roads when traveling through the vale.\n\nDuring the War of the Thorns, the area was a battlefield between the Horde and the night elves.\n\nIn the Battle for Darkshore, while Darkshore is under Alliance control, the Bilgewater Cartel uses this area for logging and poaching. When Darkshore is under Horde control, the Druids of the Branch use it to grow treants.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Wildbend River",
			short = "The Wildbend River is a tainted river in the southern part of Darkshore, near the Grove of the Ancients. It is a continuation of Bloodvenom River from Felwood as it cascades down the mountains to Darkshore.",
			full = "The Wildbend River is a tainted river in the southern part of Darkshore, near the Grove of the Ancients. It is a continuation of Bloodvenom River from Felwood as it cascades down the mountains to Darkshore.\n\nThe Wildbend River became the site of a large battle between the Horde and Alliance in the events leading up to the Burning of Teldrassil.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
		["withering thicket"] = {
			name = "Withering Thicket",
			short = "The Withering Thicket is a small stretch of forest found north of the Ruins of Auberdine in Darkshore. Moonstalkers are commonly found here.",
			full = "The Withering Thicket is a small stretch of forest found north of the Ruins of Auberdine in Darkshore. Moonstalkers are commonly found here.\n\nKeeper Karithus and Seraphine are located here as well.\n\nParts of the Withering Thicket were cut down by the Horde after the War of the Thorns. The cleared area was used by them to hold night elven prisoners. Some prisoners were used as target practice. Ivus the Forest Lord eventually moved here to assist the elven effort at retaking Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Withering_Thicket",
		},
		["wreckage of the silver dawning"] = {
			name = "Wreckage of the Silver Dawning",
			short = "The Wreckage of the Silver Dawning is one of several sunken frigates off the northern coast of Darkshore. It was attacked and sunk by murlocs as it was approaching Auberdine after having crossed the Great Sea.",
			full = "The Wreckage of the Silver Dawning is one of several sunken frigates off the northern coast of Darkshore. It was attacked and sunk by murlocs as it was approaching Auberdine after having crossed the Great Sea. Some of the crew survived by swimming ashore, but the captain went down with the ship. Silver Dawning lies just south of Mist Veil.\n\nThe quest [5-30] An Ocean Not So Deep takes place here.",
			source = "https://warcraft.wiki.gg/wiki/Wreckage_of_the_Silver_Dawning",
		},
	},
	-- Ashenvale: 59 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar is a night elven town located in central Ashenvale. It is the largest settlement in the region.",
			full = "Astranaar is a night elven town located in central Ashenvale. It is the largest settlement in the region. It lies on an island within a lake, straddling the main road through Ashenvale, connected to the mainland with only a pair of bridges.\n\nAstranaar offers a wide range of services, as well as a flight master, to Alliance players. It also has an unnamed inn and a graveyard.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Bathran's Haunt",
			short = "Bathran's Haunt is located in northwestern Ashenvale, north of the Ruins of Ordil'Aran and a ways east of the Zoram Strand. It is the site of an ancient Kaldorei ruin, long since abandoned by the night elves.",
			full = "Bathran's Haunt is located in northwestern Ashenvale, north of the Ruins of Ordil'Aran and a ways east of the Zoram Strand. It is the site of an ancient Kaldorei ruin, long since abandoned by the night elves. However, it has recently become populated once again, by agents of the Forsaken. These undead creatures skulk among the fallen pillars and broken bits of marble, and the land itself has been tainted by their presence, the grass turning a foul brown and the flowers withering away.\n\nThe Forsaken agents, mostly made up of herbalists and their thugs, appear to be using the various local herbs, and their makeshift laboratory for malicious purposes. They are friendly to Horde players.\n\nThe haunt frequently sees action as questing adventurers enter the haunt in search of [Bathran's Hair] - a valuable remedial herb that only grows in this particular spot.\n\nMore recently, orcish overseers have been deployed in the haunt to watch the Forsaken. Relations between them are rather shaky.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom camp"] = {
			name = "Blackfathom Camp",
			short = "Blackfathom Camp is a small Alliance camp located northeast of Zoram'gar Outpost and southeast of Blackfathom Deeps. The camp is led by Talen.",
			full = "Blackfathom Camp is a small Alliance camp located northeast of Zoram'gar Outpost and southeast of Blackfathom Deeps. The camp is led by Talen.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Camp",
		},
		["blackfathom deeps"] = {
			name = "Blackfathom Deeps",
			short = "Blackfathom Deeps (or just Blackfathom) is a former, partially underwater temple to the moon goddess Elune that was once known as Lathar'Lazal.",
			full = "Blackfathom Deeps (or just Blackfathom) is a former, partially underwater temple to the moon goddess Elune that was once known as Lathar'Lazal. It was thought to have been destroyed during the Sundering, and lost beneath the ocean. Millennia later, members of the Twilight's Hammer cult were drawn by whispers and foul dreams to what is now a series of watery caverns located beneath Ashenvale, near the ancient night elven city of Zoram. After sacrificing untold numbers of innocents, the cult was rewarded with a new task: to protect one of the Old Gods' most cherished creatures, a pet that was in need of nurturing before it could unleash his dark powers on the world, the monstrous hydra Aku'mai the Devourer.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Bloodtooth Camp",
			short = "Bloodtooth Camp is located in Ashenvale just west of the Falfarren River and southwest of the southern Moonwell. As its name implies, it is the camp of a tribe of furbolgs led by Ran Bloodtooth.",
			full = "Bloodtooth Camp is located in Ashenvale just west of the Falfarren River and southwest of the southern Moonwell. As its name implies, it is the camp of a tribe of furbolgs led by Ran Bloodtooth. These furbolgs have all been corrupted, and are hostile to any outsiders.\n\nAlliance adventurers doing the Raene's Cleansing quest chain receive a mission from Krolg to enter the camp and slay Ran Bloodtooth and his bodyguards.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bolyuns camp"] = {
			name = "Bolyun's Camp",
			short = "Bolyun's Camp is a camp located in southwestern Ashenvale, southwest of the Shrine of Aessina, south of House of Edune, and west of Astranaar.",
			full = "Bolyun's Camp is a camp located in southwestern Ashenvale, southwest of the Shrine of Aessina, south of House of Edune, and west of Astranaar.\n\nThe camp's only residents are Alenndaar Lapidaar, Harlown Darkweave and the camp's namesake Bolyun.",
			source = "https://warcraft.wiki.gg/wiki/Bolyun's_Camp",
		},
		["bough shadow"] = {
			name = "Bough Shadow",
			short = "Bough Shadow is located in the northeastern corner of Ashenvale, just beyond Forest Song. This place contains one of the portals to the Emerald Dream.",
			full = "Bough Shadow is located in the northeastern corner of Ashenvale, just beyond Forest Song. This place contains one of the portals to the Emerald Dream. The great tree was planted by followers of Fandral Staghelm from one of Nordrassil's branches in order to stem the tide of saronite seeping up from the land.\n\nThe portal is guarded by the green drakes Phantim and Dreamstalker, along with other dragonkin. The green dragonspawn patrol the area in groups of three, consisting of an Emeraldon Oracle accompanied by Emeraldon Boughguards and/or Emeraldon Tree Warders.\n\nIn Season of Discovery, Bough Shadow is a location of a Nightmare Incursion.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Demon Fall Canyon",
			short = "Demon Fall Canyon is a fel-corrupted canyon located in Ashenvale, south of Felfire Hill and just east of Demon Fall Ridge.",
			full = "Demon Fall Canyon is a fel-corrupted canyon located in Ashenvale, south of Felfire Hill and just east of Demon Fall Ridge. It earned its name after the titanic clash between the demonic pit lord Mannoroth, and the two orcs Grommash Hellscream and Thrall. The pit lord succeeded in knocking Thrall out, but he was not quick enough to escape Grom's axe, which cleaved into Mannoroth's chest.\n\nThe demon's death created an explosion of fire and light, which tore the life from Grom as well. The orcs named the site of his sacrifice thusly and many would make pilgrimage there to honor the warrior who had liberated the orc people from the Burning Legion's curse. A monument to Grom Hellscream was also erected in his memory. The canyon is now populated by many hostile lesser demons.\n\nSeason of Discovery added a dungeon version of the zone.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Demon Fall Ridge",
			short = "Demon Fall Ridge is located in Ashenvale, just west and above of Demon Fall Canyon.",
			full = "Demon Fall Ridge is located in Ashenvale, just west and above of Demon Fall Canyon. It is home to several kinds of lesser demons, who inhabit both the exterior part of the ridge, as well as the interior of an abandoned barrow den set into the side of the ridge. In the deepest parts of this den waits Diathorus the Seeker - a dreadlord and ruler of the demonic conclave in Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Dor'Danil Barrow Den",
			short = "The Dor'Danil Barrow Den is located in Ashenvale, south of Splintertree Post, and southwest of Felfire Hill.",
			full = "The Dor'Danil Barrow Den is located in Ashenvale, south of Splintertree Post, and southwest of Felfire Hill. Although it has traditionally been the site of rest for night elven druids, the incursion of the Horde put the barrow den behind enemy lines. Although the orcs had little interest in a bunch of sleeping elves, the Forsaken who later joined the faction were not so disinterested. Experimenting with severing the sleeping druids from their spirits, they drove the night elves insane. The barrow den is now filled with skulking Forsaken assassins, the enraged souls of the severed druids, and three particularly powerful spirits -- those of Uthil Mooncall, Mavoris Cloudsbreak, and Taneel Darkwood.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Falfarren River",
			short = "The Falfarren River runs northeast to southwest across Ashenvale, and is approximately the dividing line between the night elven territory under Astranaar to the west, and the orcish territory under Splintertree Post to the east.",
			full = "The Falfarren River runs northeast to southwest across Ashenvale, and is approximately the dividing line between the night elven territory under Astranaar to the west, and the orcish territory under Splintertree Post to the east. It is not a terribly deep or wide river, though rainfall can cause it to swell. Several aggressive bog beasts can be found roaming below the surface of the river at sections around Felfire Hill.\n\nThe water of the river originates from the slopes of Mount Hyjal, and passes through a series of waterfalls into the lake at Xavian, before it runs between Splintertree and Night Run southwest. It then runs past the primary and most well-traveled bridge spanning the Falfarren, continuing between Silverwing Outpost and the Moonwell of Cleansing across another bridge before it slips underground beneath the mountains of the northern Barrens.\n\nDuring the War of the Thorns the night elves burnt its bridges to delay the Horde, though in the end they managed to cross it by freezing a section of the river.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Fallen Sky Lake",
			short = "Fallen Sky Lake is located in Ashenvale south of Silverwing Outpost, west of the Warsong Labor Camp, and northeast of Silverwing Grove.",
			full = "Fallen Sky Lake is located in Ashenvale south of Silverwing Outpost, west of the Warsong Labor Camp, and northeast of Silverwing Grove. It is a small lake, and the island in the center in it holds a level 30 Shadethicket Oracle that you must kill for a quest. Surrounding the lake are other shadethickets of lower levels than the oracle.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Felfire Hill",
			short = "Felfire Hill is located in Ashenvale, southeast of Splintertree Post, southwest of the Warsong Lumber Camp, and northeast of the Dor'Danil Barrow Den.",
			full = "Felfire Hill is located in Ashenvale, southeast of Splintertree Post, southwest of the Warsong Lumber Camp, and northeast of the Dor'Danil Barrow Den. It is the site of the arrival of several infernals during the Third War, and is inhabited by all manner of foul demons. The Horde has fortified both bridges leading to the hill in order to prevent attacks on any of their nearby settlements.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Fire Scar Shrine",
			short = "Fire Scar Shrine is located in southwestern Ashenvale, southwest of Astranaar, south of the Shrine of Aessina, and west of the Ruins of Stardust.",
			full = "Fire Scar Shrine is located in southwestern Ashenvale, southwest of Astranaar, south of the Shrine of Aessina, and west of the Ruins of Stardust.\n\nIt has been corrupted by the demonic influence of the Shadow Council, and is now a place of great evil. A powerful orcish warlock, Ilkrud Magthrull, previously resided at the shrine in service to the leader of the Cult of the Dark Strand, Athrikus Narassin.\n\nThe Shrine is now infested by demons which the Adventurer is tasked with culling by Bolyun.\n\nA rare doomguard named Akkrilus will appear in the shrine's area occasionally.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Forest Song",
			short = "Forest Song is an ancient night elf ruin located in northeastern Ashenvale, just northeast of Satyrnaar, north of the Warsong Lumber Camp, and southwest of Bough Shadow.",
			full = "Forest Song is an ancient night elf ruin located in northeastern Ashenvale, just northeast of Satyrnaar, north of the Warsong Lumber Camp, and southwest of Bough Shadow. Once almost abandoned, Forest Song is currently inhabited by night elves and draenei from the Exodar, who are building an outpost there to help the Silverwing Sentinels defend the forests from the Warsong clan and the Burning Legion remnants.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Greenpaw Village",
			short = "Greenpaw Village is located in central Ashenvale, south of Raynewood Retreat, northeast of Silverwind Refuge, and northwest of the southern moonwell.",
			full = "Greenpaw Village is located in central Ashenvale, south of Raynewood Retreat, northeast of Silverwind Refuge, and northwest of the southern moonwell. It is the home of the Foulweald tribe, led by Chief Murgut and the shaman Oakpaw. Both Horde and Alliance adventurers frequently come to Greenpaw to battle the corrupted bearmen. The village has been partially destroyed by the Horde, with the furbolg inhabiting the conquered areas taken prisoner.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["hellscreams watch"] = {
			name = "Hellscream's Watch",
			short = "Hellscream's Watch is a Horde encampment in Ashenvale, located just across the waters from the embattled Astranaar. It is one of the Horde's most contentious fronts in Ashenvale.",
			full = "Hellscream's Watch is a Horde encampment in Ashenvale, located just across the waters from the embattled Astranaar. It is one of the Horde's most contentious fronts in Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Hellscream's_Watch",
		},
		["house of edune"] = {
			name = "House of Edune",
			short = "The House of Edune can be found in western Ashenvale, near the Shrine of Aessina and Lake Falathim. The Edune and Dunadaire families live here.",
			full = "The House of Edune can be found in western Ashenvale, near the Shrine of Aessina and Lake Falathim. The Edune and Dunadaire families live here.",
			source = "https://warcraft.wiki.gg/wiki/House_of_Edune",
		},
		["howling vale"] = {
			name = "Howling Vale",
			short = "The Howling Vale is a cave located in north-central Ashenvale, just southwest of the border to Felwood. The vale is a home of the Shrine of Mel'Thandris.",
			full = "The Howling Vale is a cave located in north-central Ashenvale, just southwest of the border to Felwood. The vale is a home of the Shrine of Mel'Thandris. In front of the Shrine an ancient inscription, praising Elune, is written. The shrine has an inscription reading \"The truth is a guiding light\" in Darnassian.\n\nThe shrine has since become a sacred place to the night elves.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Iris Lake",
			short = "Iris Lake was located in north-central Ashenvale, east of Astranaar and west of Shael'dryn's moonwell. It was one of the many areas of the night elven forest which fell to the corruption of Felwood.",
			full = "Iris Lake was located in north-central Ashenvale, east of Astranaar and west of Shael'dryn's moonwell. It was one of the many areas of the night elven forest which fell to the corruption of Felwood. The water of the lake was a sickly yellowish green, and twisted bog beasts roamed the area, attacking anyone who visited seeking one of Elune's Tears.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Kargathia Keep",
			short = "Kargathia Keep (or Kargathia Outpost) is located in eastern Ashenvale, in the eastern part of the Warsong Lumber Camp just west of the Southfury River.",
			full = "Kargathia Keep (or Kargathia Outpost) is located in eastern Ashenvale, in the eastern part of the Warsong Lumber Camp just west of the Southfury River. It is the base of operations for the officers of the Warsong Clan, and has a strategic position that lets it receive reinforcements from Orgrimmar should a battle with the Alliance break out. The keep, much like Kargath in the Badlands, and Bladefist Bay in Durotar, is named for the legendary orcish hero Kargath Bladefist. Overseer Gorthak, the orc in charge of the camp, can be found here.\n\nThe building is a stronghold and is seemingly upgraded with spiked barricades.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["krolgs hut"] = {
			name = "Krolg's Hut",
			short = "Krolg's Hut is a the hut of Krolg located in the hills just south of Mystral Lake in Ashenvale.",
			full = "Krolg's Hut is a the hut of Krolg located in the hills just south of Mystral Lake in Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Krolg's_Hut",
		},
		["lake falathim"] = {
			name = "Lake Falathim",
			short = "Lake Falathim is located in western Ashenvale, southeast of the Zoram Strand and southwest of Maestra's Post. In this lake the goddess's moonlight always touches down, day or night.",
			full = "Lake Falathim is located in western Ashenvale, southeast of the Zoram Strand and southwest of Maestra's Post. In this lake the goddess's moonlight always touches down, day or night.\n\nAlthough it was once a popular place for night elves to go swim or fish, the lake was later overrun with ferocious murlocs. The scholar Teronis was last seen near the lake, and it boded ill of his fate that he never returned.\n\nThe murlocs eventually left the lake, which became dank and gloomy. The area is currently swarming with tentacles from Below and Harbinger Aphotic stands here.\n\nKeeper Heartwise has recently come here to combat the corruption and will solicit help from adventurers. The moonlight here lets spirits in the Veil see into the living world.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Maestra's Post",
			short = "Maestra's Post is located in western Ashenvale, south of the Ruins of Ordil'Aran and northwest of Astranaar.",
			full = "Maestra's Post is located in western Ashenvale, south of the Ruins of Ordil'Aran and northwest of Astranaar. It was once a small camp consisting of a tower and a large night elven building with only a few inhabitants, including Ashenvale's only population of humans - Feero Ironhand and Delgren the Purifier at that time. However, the forces of the Horde have since invaded, and it is now a major battleground.\n\nAs a result of renewed tension between the Alliance and Horde, Maestra's Post's has recently come under assault by Horde forces under the command of Orux Thrice-Damned and Feero and Delgren have been kidnapped. The Alliance forces are stretched thin, however, as they attempt to deal with both the corruption of the nearby furbolgs and the Horde forces. They will solicit help from willing adventurers.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["moonwell ashenvale"] = {
			name = "Moonwell (Ashenvale)",
			short = "There are three Moonwells in Ashenvale. The Moonwell of Purity is located in the northern part, east of Iris Lake and west of Raynewood Retreat.",
			full = "There are three Moonwells in Ashenvale. The Moonwell of Purity is located in the northern part, east of Iris Lake and west of Raynewood Retreat. The Moonwell of Cleansing is located west of Silverwing Outpost and southeast of Greenpaw Village. The former is oft visited by Alliance adventurers who are following the Raene's Cleansing quest chain. The third moonwell is located at Raynewood Retreat.",
			source = "https://warcraft.wiki.gg/wiki/Moonwell_(Ashenvale)",
		},
		["moonwell of cleansing"] = {
			name = "Moonwell of Cleansing",
			short = "The Moonwell of Cleansing is a moonwell in Ashenvale located near the southwestern end of Falfarren River, east of Mystral Lake and west of Silverwing Outpost.",
			full = "The Moonwell of Cleansing is a moonwell in Ashenvale located near the southwestern end of Falfarren River, east of Mystral Lake and west of Silverwing Outpost. It is connected to Silverwing Outpost by a bridge across Falfarren River, which, like the moonwell itself, is not marked on the world map. A Blink Dragon flies in a circle nearby.",
			source = "https://warcraft.wiki.gg/wiki/Moonwell_of_Cleansing",
		},
		["moonwell of purity"] = {
			name = "Moonwell of Purity",
			short = "The Moonwell of Purity is a subzone of Ashenvale near Thunder Peak. It is surrounded by Blink Dragons. This subzone is involved in the quest [7-30] A Trip to the Moonwell.",
			full = "The Moonwell of Purity is a subzone of Ashenvale near Thunder Peak. It is surrounded by Blink Dragons. This subzone is involved in the quest [7-30] A Trip to the Moonwell.",
			source = "https://warcraft.wiki.gg/wiki/Moonwell_of_Purity",
		},
		["morshan rampart"] = {
			name = "Mor'shan Rampart",
			short = "The Mor'shan Rampart lies at the northern terminus of the Gold Road in Northern Barrens. This makeshift defensive post was built to withstand the push of Alliance forces into the region from Ashenvale to the north.",
			full = "The Mor'shan Rampart lies at the northern terminus of the Gold Road in Northern Barrens. This makeshift defensive post was built to withstand the push of Alliance forces into the region from Ashenvale to the north. The rampart and its watch towers still serve as a makeshift launching point for raids on the night elven town of Astranaar.\n\nAshenvale Skirmishers regularly charge the rampart and engage in combat with the Mor'shan Defenders, while Ashenvale Bowmen shoot arrows at them.\n\nDuring the War of the Thorns, the elves were killed by two Horde rogues.\n\nThe area was changing hands between the Alliance and Mor'shan defenders since then.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["mystral lake"] = {
			name = "Mystral Lake",
			short = "Mystral Lake (or Lake Mystral) is located in south-central Ashenvale, just south of Silverwind Refuge and east of Talondeep Vale.",
			full = "Mystral Lake (or Lake Mystral) is located in south-central Ashenvale, just south of Silverwind Refuge and east of Talondeep Vale. It is the largest lake in the forest, and subsequently often visited by both Horde and Alliance characters for various reasons.\n\nThe water elementals of Mystral Lake pose a significant threat to lower level players: while they were previously loyal to the night elves, they were corrupted by Sarilus Foulborne.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Night Run",
			short = "Night Run is located in east-central Ashenvale, east of Raynewood Retreat and northwest of Splintertree Post. It's inhabited by the Felmusk satyr.",
			full = "Night Run is located in east-central Ashenvale, east of Raynewood Retreat and northwest of Splintertree Post. It's inhabited by the Felmusk satyr.\n\nShortly after the Sundering, Arvell and Ralaar in Pack Form attacked the Sentinels battling the satyrs, killing Aldorei, Elanu, Morina, Tyrnas and wounding Shandris. The attack marked the beginning of the War of the Satyr.\n\nIt is one of the three Ashenvale satyr settlements, the other two being Satyrnaar and Xavian. Of the three, Night Run is by far the smallest, boasting only a few broken pillars and pieces of ruined architecture as shelter for the satyr who live there. Here is one of the soulgems belonging to the Cult of the Dark Strand, which the Satyr are allied with.\n\nIt is also the hardest of the satyr settlements to get to, as it is located on a naze that juts out into the land with unclimbable cliffs on the side. To get to Night Run, one has to run along the Falfarren River almost to the waters of Xavian before turning west, or approach it from a narrow ledge north of Raynewood.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Nightsong Woods",
			short = "Nightsong Woods is the eastern part of Ashenvale forest, stretching from Raynewood Retreat and the road to Felwood in the west, all the way east to Azshara.",
			full = "Nightsong Woods is the eastern part of Ashenvale forest, stretching from Raynewood Retreat and the road to Felwood in the west, all the way east to Azshara.\n\nThis is where most of the heavy cross-faction fighting occurs, and where the Warsong Clan and the Silverwing Sentinels have their holdings. The Falfarren River runs through the Nightsong Woods, roughly dividing it into a western Alliance-aligned part, and an eastern Horde-aligned part. A second, nameless river farther to the east separates Splintertree Post, which is the center of operations for Horde in the region, and Alliance-controlled Silverwing Grove from the easternmost part, which is probably the most contested part of Ashenvale: control over it is split between the draenei and night elven outpost of Forest Song, the satyr outposts of Satyrnaar and Xavian, the Horde-aligned Warsong Lumber Camp, and the Burning Legion controlled Felfire Hill and Demon Fall Canyon.\n\nThe southern reaches of the woods have experienced widespread deforestation at the hands of the Warsong orcs, who use the thick lumber in the trees for settlements and resources.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["orendils retreat"] = {
			name = "Orendil's Retreat",
			short = "Orendil's Retreat is a hamlet located directly north of Maestra's Post and east of Blackfathom Deeps. Several scholars live here in addition to Sentinel Shyela, the camp's leader.",
			full = "Orendil's Retreat is a hamlet located directly north of Maestra's Post and east of Blackfathom Deeps. Several scholars live here in addition to Sentinel Shyela, the camp's leader.",
			source = "https://warcraft.wiki.gg/wiki/Orendil's_Retreat",
		},
		["raynewood retreat"] = {
			name = "Raynewood Retreat",
			short = "Raynewood Retreat is an area located in north-central Ashenvale, around the Great Tree of the same name, east of Shael'dryn's moonwell and west of Night Run.",
			full = "Raynewood Retreat is an area located in north-central Ashenvale, around the Great Tree of the same name, east of Shael'dryn's moonwell and west of Night Run. It is an Alliance outpost where Ordanus, a keeper of the grove and one of the eldest sons of the forest god Cenarius, is hiding.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["raynewood tower"] = {
			name = "Raynewood Tower",
			short = "Raynewood Tower is located near Raynewood Retreat in Ashenvale and serves as a small quest hub for the Alliance.",
			full = "Raynewood Tower is located near Raynewood Retreat in Ashenvale and serves as a small quest hub for the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Tower",
		},
		["remains of iris lake"] = {
			name = "Remains of Iris Lake",
			short = "The lake has evaporated and is now scorched earth thanks to the nearby lava flows from Thunder Peak.",
			full = "The lake has evaporated and is now scorched earth thanks to the nearby lava flows from Thunder Peak.",
			source = "https://warcraft.wiki.gg/wiki/Remains_of_Iris_Lake",
		},
		["ruins of ordilaran"] = {
			name = "Ruins of Ordil'Aran",
			short = "The Ruins of Ordil'Aran are located in northwestern Ashenvale, north of Maestra's Post and south of Bathran's Haunt.",
			full = "The Ruins of Ordil'Aran are located in northwestern Ashenvale, north of Maestra's Post and south of Bathran's Haunt. Although not much remains of the ancient city that once stood here, the site was a favorite spot for the Cult of the Dark Strand, who inhabited what is left of the ruins, ready to strike at any who approach. They have since been ousted by furbolgs of the Thistlefur tribe, who have taken over the ruins for themselves. Dead cultists still lie about the area.\n\nThe Ruins of Ordil'Aran are also the site of the [Heartswood] tree.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Ruins of Stardust",
			short = "The Ruins of Stardust are located in southwestern Ashenvale, south of Astranaar and west of the Talondeep Path.",
			full = "The Ruins of Stardust are located in southwestern Ashenvale, south of Astranaar and west of the Talondeep Path. The ruins are situated on a lake island, and several large bog beasts roam the ruins, corrupted by the lake's tainted waters. Much like Iris Lake, the ruins have been exposed to the demonic rot from Felwood, and the area is tinted a sickly yellowish green color. The most notable exception is the stardust shrubs scattered about the area. They are unmarred by the taint, and are known to contain powerful healing properties if imbibed.\n\nThe ruins were originally considered a holy place.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["ruuzels isle"] = {
			name = "Ruuzel's Isle",
			short = "Ruuzel's Isle is a small island with a few night elf ruins. Ruuzel commands her Wrathtail naga forces from a hill on the center of the island.",
			full = "Ruuzel's Isle is a small island with a few night elf ruins. Ruuzel commands her Wrathtail naga forces from a hill on the center of the island.",
			source = "https://warcraft.wiki.gg/wiki/Ruuzel's_Isle",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar is located in northeastern Ashenvale, northeast of Splintertree Post and southwest of Forest Song. It is one of the three Ashenvale satyr settlements, the other two being Night Run and Xavian.",
			full = "Satyrnaar is located in northeastern Ashenvale, northeast of Splintertree Post and southwest of Forest Song. It is one of the three Ashenvale satyr settlements, the other two being Night Run and Xavian. Of the three, Satyrnaar is the most intact and centrally located, boasting several tents among the ruined buildings as shelter for the Bleakheart satyr who live there. Here is one of the soulgems belonging to the Cult of the Dark Strand, which the satyr are allied with.\n\nIt the easiest of the satyr settlements to get to, as it is located just off the main road from Splintertree towards Azshara. As such, it is also the most contested of the three satyr ruins.\n\nA version of the settlement also exists within the Emerald Dream. Here, the Nightmare-affiliated satyr of the Dreamfire sect protect their ancient [Azsharan Prophecy] under the command of Zalius.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Shady Nook",
			short = "The Shady Nook is located in Ashenvale, south of Raynewood Retreat and east of Greenpaw Village. It is a small valley populated by a small family of bears, who presumably also inhabit the small cave located there.",
			full = "The Shady Nook is located in Ashenvale, south of Raynewood Retreat and east of Greenpaw Village. It is a small valley populated by a small family of bears, who presumably also inhabit the small cave located there.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Shrine of Aessina",
			short = "The Shrine of Aessina is located in southwestern Ashenvale, southwest of Maestra's Post, south of House of Edune, and west of Astranaar.",
			full = "The Shrine of Aessina is located in southwestern Ashenvale, southwest of Maestra's Post, south of House of Edune, and west of Astranaar.\n\nThe Alliance sought to rebuild its defenses, while the Horde was determined to burn it to the ground.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Silverwind Refuge",
			short = "Silverwind Refuge is located in south-central Ashenvale, just north of Mystral Lake and directly south of the Remains of Iris Lake and Thunder Peak.",
			full = "Silverwind Refuge is located in south-central Ashenvale, just north of Mystral Lake and directly south of the Remains of Iris Lake and Thunder Peak. Formerly a night elven settlement, it now serves as an Horde outpost with a flight master, an innkeeper, quest givers, a stable master, and vendors. The corpses of some of the previous inhabitants still lie on the ground around the outpost.\n\nThe quest [10-30] We're Here to Do One Thing, Maybe Two... from Blood Guard Aldo Rockrain begins the Horde quest line for Stonetalon Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Silverwing Grove",
			short = "Silverwing Grove is the Silverwing Sentinels base. It is located in south-central Ashenvale, southwest of Silverwing Outpost and west of Fallen Sky Lake.",
			full = "Silverwing Grove is the Silverwing Sentinels base. It is located in south-central Ashenvale, southwest of Silverwing Outpost and west of Fallen Sky Lake. It is the location of the entrance to the Warsong Gulch battleground, and holds several PvP-aligned NPCs, including an Alliance Brigadier General, a pair of vendors, and another PvP quest giver named Sentinel Farsong.\n\nDuring the War of the Thorns, the grove was attacked by the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Silverwing Outpost",
			short = "Silverwing Outpost is located in south-central Ashenvale, north of the border with the Barrens and southwest of Splintertree Post.",
			full = "Silverwing Outpost is located in south-central Ashenvale, north of the border with the Barrens and southwest of Splintertree Post. It is the eastern Alliance bastion of defense against the Horde, and it is located on the Horde side of the Falfarren River. Because of this, the sentinels posted there have to fight back constant attacks from the nearby orcs, who are unrelenting in their goal of ridding the woods of the Silverwings once and for all. Its leader is Duriel Moonfire.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nWith the outpost's fortifications falling to his tactics, his army was able to assault the Silverwing Sentinels and drive away any who survived the assault.\n\nDuring the War of the Thorns, the outpost was once again attacked by the Horde.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["skunkworks"] = {
			name = "Skunkworks",
			short = "The Skunkworks is a goblin encampment within the northern part of Silverwind Refuge. The camp is full of Goblin Technicians led by Chief Bombgineer Sploder, who keeps them working, yet not killing themselves.",
			full = "The Skunkworks is a goblin encampment within the northern part of Silverwind Refuge. The camp is full of Goblin Technicians led by Chief Bombgineer Sploder, who keeps them working, yet not killing themselves. Sploder resides on a Super Reaper 6000, along with The Bomb, which is later shipped to Stonetalon by balloon. Foreman Jinx, a Horde quest giver, can be found here, but cannot be killed by Alliance players.",
			source = "https://warcraft.wiki.gg/wiki/Skunkworks",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls.",
			full = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls. The resulting wide, swiftly-flowing river forms the boundary between the forest of Ashenvale and Azshara, and further south, the border between the Northern Barrens and Durotar. The river empties into the Great Sea in a cascading waterfall just northeast of the goblin port city of Ratchet.\n\nThere are three bridges that span the Southfury River: one crossing from Azshara into Ashenvale, one leading into the Horde's capital city of Orgrimmar, and one that crosses from Durotar into the Northern Barrens. Notably, just north of the western bridge of Orgrimmar, there is a spot on the river where four in-game zones meet: Ashenvale, Azshara, Durotar, and Northern Barrens.\n\nA goblin named Horton Hornblower sits at a dock near the mouth of the Southfury with his Riverboat. After doing quests for the goblins in Ratchet, he offers [5-30] Raging River Ride, which provides transportation to the area outside Nozzlepot's Outpost in the Northern Barrens.\n\nIt could still be used to water the crops, but it could no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree mine"] = {
			name = "Splintertree Mine",
			short = "The Splintertree Mine is a mine located in the back of Splintertree Post. It is being mined by Splintertree Peons overseen by Splintertree Overseers.",
			full = "The Splintertree Mine is a mine located in the back of Splintertree Post. It is being mined by Splintertree Peons overseen by Splintertree Overseers.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Mine",
		},
		["splintertree post"] = {
			name = "Splintertree Post",
			short = "Splintertree Post is a Horde outpost in Ashenvale, lying just north-west of Felfire Hill. Like most Horde outposts, Splintertree is mainly populated by orcs and tauren, all whom are primarily scouts and guards.",
			full = "Splintertree Post is a Horde outpost in Ashenvale, lying just north-west of Felfire Hill. Like most Horde outposts, Splintertree is mainly populated by orcs and tauren, all whom are primarily scouts and guards. There are several quest givers, a heavy armor vendor for repairs, an inn, mailbox, stable master, and a flight path maintained by wind rider flight master Vhulgra.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["stardust spire"] = {
			name = "Stardust Spire",
			short = "Stardust Spire is an Alliance outpost located in southern Ashenvale, north of Talondeep Pass in the Stonetalon Mountains.",
			full = "Stardust Spire is an Alliance outpost located in southern Ashenvale, north of Talondeep Pass in the Stonetalon Mountains. It contains survivors of the Horde takeover of Silverwind Refuge, led by Huntress Jalin, who are using the outpost as a base from which to launch attacks against the Horde. The residents of the outpost are primarily night elf Sentinels and members of a gnome explosives squad sent from Tinker Town. The flight master has connections to Astranaar, Thal'darah Overlook, Windshear Hold, and Nijel's Point.\n\nThe spire consists of a shored up sentry tower, and the watchtower sits atop the remains of a bigger structure.\n\nDuring the War of the Thorns, the retreat was attacked by the Horde. Sergeant Dontrag led a Horde assault against the spire but was encountered by Alliance champions. Jalin led her Sentinels against the Horde-controlled Silverwind Refuge.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nAfter the war, the place was observed by Zekhan from a safe distance and spotted Huntress Jalin leading her Sentinels. According to Horde reports, they destroyed every siege weapon the Horde brought down from the Stonetalon Mountains. She left the bones of the machines and the bodies of the engineers at the doorstep of the spire as a warning to her enemies.",
			source = "https://warcraft.wiki.gg/wiki/Stardust_Spire",
		},
		["talondeep path"] = {
			name = "Talondeep Path",
			short = "The Talondeep Path was a winding tunnel that connected Ashenvale with the Stonetalon Mountains.",
			full = "The Talondeep Path was a winding tunnel that connected Ashenvale with the Stonetalon Mountains. Although it was riddled with small dead ends and interesting holes in the walls, there were no friendly NPCs nor hostile mobs inside. The entrance on the Ashenvale side was found just west of Mystral Lake, while the entrance on the Stonetalon side was found in the northwestern part of Windshear Crag.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["talondeep vale"] = {
			name = "Talondeep Vale",
			short = "Talondeep Vale is a forested location between Silverwind Refuge, Talondeep Pass, and the Ruins of Stardust. Stardust Spire is located in or near here.",
			full = "Talondeep Vale is a forested location between Silverwind Refuge, Talondeep Pass, and the Ruins of Stardust. Stardust Spire is located in or near here.\n\npl:Talondeep Vale",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Vale",
		},
		["thistlefur hold"] = {
			name = "Thistlefur Hold",
			short = "Thistlefur Hold is located in west-central Ashenvale, in the northern part of Thistlefur Village.",
			full = "Thistlefur Hold is located in west-central Ashenvale, in the northern part of Thistlefur Village. It is home to the bulk of the Thistlefur furbolgs, and contains two quests for Horde characters -- collecting troll charms and rescuing Ruul Snowhoof, who is trapped in a cage deep in the hold.\n\nThe furbolgs here also held the Idol of Remulos for a time, which is what corrupted them and turned them hostile to all outsiders.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Hold",
		},
		["thistlefur village"] = {
			name = "Thistlefur Village",
			short = "Thistlefur Village is a village located in the westcentral area of Ashenvale, north of Astranaar. It is the homeland of the Thistlefur tribe of corrupted furbolgs, who aggressively attack anyone who wanders too close.",
			full = "Thistlefur Village is a village located in the westcentral area of Ashenvale, north of Astranaar. It is the homeland of the Thistlefur tribe of corrupted furbolgs, who aggressively attack anyone who wanders too close. The Thistlefur tribe is led by two extremely ferocious warriors: Dal Bloodclaw and Rorgish Jowl.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["thunder peak"] = {
			name = "Thunder Peak",
			short = "Thunder Peak is a large mountain peak near the Remains of Iris Lake in Ashenvale and is home to Lord Magmathar.",
			full = "Thunder Peak is a large mountain peak near the Remains of Iris Lake in Ashenvale and is home to Lord Magmathar.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Peak",
		},
		["warsong labor camp"] = {
			name = "Warsong Labor Camp",
			short = "The Warsong Labor Camp is located in southeastern Ashenvale, east of Fallen Sky Lake and southwest of Dor'Danil Barrow Den. It is a small area containing loggers, harvesters, and orcish guards.",
			full = "The Warsong Labor Camp is located in southeastern Ashenvale, east of Fallen Sky Lake and southwest of Dor'Danil Barrow Den. It is a small area containing loggers, harvesters, and orcish guards. It is occasionally attacked by Alliance adventurers since they can strike the guards without fear of retribution, due to the camp's relative isolation.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Warsong Lumber Camp",
			short = "Warsong Lumber Camp is Warsong clan's lumber-cutting camp in Ashenvale. The camp has a kennel and a stronghold, Kargathia Keep.",
			full = "Warsong Lumber Camp is Warsong clan's lumber-cutting camp in Ashenvale. The camp has a kennel and a stronghold, Kargathia Keep.\n\nA version of the lumber camp also exists within the Emerald Dream. Here, a group of goblins seemingly willingly crossed into the Dream to try to harvest it with their supercharged shredders. Boss \"Gobb\" Goldnick keeps watch on his [Dreamengine], but vengeful treants have risen to attack the Warsong Lumber Camp back in spite.\n\nThe area was a battlefield between the Alliance and Horde, with Illiyana and her sisters destroying shredders with nature magic.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nAccording to Zekhan's report after the war, Warsong Lumber Camp keeps the nearby Splintertree Post's walls and people uplifted with a steady stream of resources.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Xavian is a satyr sect located in northeastern Ashenvale, living in the ruins of an ancient Night elf temple, north of Satyrnaar and west of Forest Song.",
			full = "Xavian is a satyr sect located in northeastern Ashenvale, living in the ruins of an ancient Night elf temple, north of Satyrnaar and west of Forest Song. The general Xalan the Feared was killed there by Sentinels and druids led by Shandris Feathermoon and Arvell.\n\nIt is one of the three Ashenvale satyr settlements, the other two being Satyrnaar and Night Run. Of the three, Xavian seems to be the center of satyr political power in Ashenvale, as both Prince Raze and Geltharis live here. It is also the site of a dryad attack, and questing adventurers will find the mortally wounded Anilia, who searched for the stolen [Branch of Cenarius], lying on the ground here. They're using [Warsong Oil] for their detestable rituals.\n\nXavian is named after Xavius, one of the night elves responsible for summoning the burning legion through a portal manifested from the Well of Eternity in Zin-Azshari in what became later known as the War of the Ancients. Sargeras transformed Xavius into the first satyr when he became unhappy with his progress with the portal. With as close as Xavian is to Azshara, it's easy to assume that this is why it's named so.\n\nHow Terestian Illhoof and the [Xavian Stiletto], dropped by him in Karazhan, are related to the Xavian is unknown.\n\nDuring the War of the Thorns, the south of Xavian was a battlefield.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "Zoram Strand",
			short = "The Zoram Strand is a stretch of beach in the northwest corner of Ashenvale. Prior its destruction during the Great Sundering, it was a night elven city named Zoram.",
			full = "The Zoram Strand is a stretch of beach in the northwest corner of Ashenvale. Prior its destruction during the Great Sundering, it was a night elven city named Zoram.\n\nWhile the Horde have set up a minor outpost (Zoram'gar Outpost) in the Zoram Strand, the area has fallen to the naga. The dark creatures have taken up residence, evident in their numbers and in the shipwrecks and beached sea creatures along the shore. The Zoram Strand is also the site of the Blackfathom Deeps.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Zoram'gar Outpost",
			short = "The Zoram'gar Outpost (or the Zoram Strand Outpost) is a Horde port outpost located on the Zoram Strand of Ashenvale. Its port section is named the Zoram'gar Docks.",
			full = "The Zoram'gar Outpost (or the Zoram Strand Outpost) is a Horde port outpost located on the Zoram Strand of Ashenvale. Its port section is named the Zoram'gar Docks.\n\nDuring the war, the invading Horde army used the open shore of Zoram Strand near the outpost as a staging ground to begin their assault on Darkshore.\n\nBecause Zoram'gar is the Horde's only port near Azuremyst Isle, Alliance forces planted depth charges in the surrounding waters to prevent a naval assault on the island. So did the Horde to prevent any Alliance incursion.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Thousand Needles: 35 subzones
	[1441] = {
		["admirals den"] = {
			name = "Admiral's Den",
			short = "The Admiral's Den is a cavern found within the Southsea Holdfast of the Thousand Needles. It's here the Southsea Admiral Tony Two-Tusk can be found with several elite ogres protecting him from intruders.",
			full = "The Admiral's Den is a cavern found within the Southsea Holdfast of the Thousand Needles. It's here the Southsea Admiral Tony Two-Tusk can be found with several elite ogres protecting him from intruders.",
			source = "https://warcraft.wiki.gg/wiki/Admiral's_Den",
		},
		["arikaras needle"] = {
			name = "Arikara's Needle",
			short = "Arikara's Needle is a small bluff that is part of the greater Darkcloud Pinnacle in Thousand Needles. It's here the Grimtotem tribe at Darkcloud Pinnacle honor their dead.",
			full = "Arikara's Needle is a small bluff that is part of the greater Darkcloud Pinnacle in Thousand Needles. It's here the Grimtotem tribe at Darkcloud Pinnacle honor their dead. This is also the location where Arikara can be summoned.",
			source = "https://warcraft.wiki.gg/wiki/Arikara's_Needle",
		},
		["camp ethok"] = {
			name = "Camp E'thok",
			short = "Camp E'thok was a Galak centaur camp in northwestern Thousand Needles.",
			full = "Camp E'thok was a Galak centaur camp in northwestern Thousand Needles. The centaurs here raided a caravan that the goblin Wizlo Bearingshiner was in, but could not steal his most prized gadget, as it's tied around the neck of a ferocious panther he owned.\n\nAny centaur that survived made their way to Splithoof Heights.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Darkcloud Pinnacle",
			short = "East of the Great Lift, atop three small mesas (and several smaller, not inhabited mesas), is Darkcloud Pinnacle, a settlement that the Grimtotem tauren call home.",
			full = "East of the Great Lift, atop three small mesas (and several smaller, not inhabited mesas), is Darkcloud Pinnacle, a settlement that the Grimtotem tauren call home. These mesas are connected by rope bridges and have only two access points: a natural slope up a fourth mesa followed by a trip across a bridge, or another bridge from Razorfen Downs in Thousand Needles. Both entrances are well guarded.\n\nIt is here that a secret correspondence between Grimtotem leaders and an unknown dark power takes place. The leaders of the Grimtotems here are Arnak Grimtotem and Harb Foulmountain. The entry path from the base begins at .\n\nAramar Thorne described its location as being located on one of the largest mesa in the area.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["fizzle and pozziks speedbarge"] = {
			name = "Fizzle and Pozzik's Speedbarge",
			short = "Fizzle & Pozzik's Speedbarge looks like a massive, city-sized ship and an artificial island located on the Shimmering Deep in Thousand Needles.",
			full = "Fizzle & Pozzik's Speedbarge looks like a massive, city-sized ship and an artificial island located on the Shimmering Deep in Thousand Needles. Although the barge is named after its leaders, Fizzle Brassbolts and Pozzik, Jinky Twizzlefixxit and Razzeric separately believe that the ship should have been named after themselves: after all they built it.\n\nLorewise, a ship leaves for Gadgetzan every day.\n\nIt is a place where goblin and gnome engineers compete, free of the tensions abroad.",
			source = "https://warcraft.wiki.gg/wiki/Fizzle_and_Pozzik's_Speedbarge",
		},
		["freewind post"] = {
			name = "Freewind Post",
			short = "Freewind Post is a Horde town located high on a mesa in Thousand Needles.",
			full = "Freewind Post is a Horde town located high on a mesa in Thousand Needles. Tauren settlements in Thousand Needles are constructed atop the tall mesas in the region, staying out of reach of the centaur warbands that have several camps in the area. The village on the mesa's top is accessible by the employment of the ingenious wooden lifts of the tauren, although there is a series of rope bridges spanning amongst the adjacent pinnacles, gradually working their way to the top.\n\nThe tauren of Freewind Post work to stop the activity of the Galak tribe centaur in Thousand Needles. Screeching harpies pose a less dire threat to the stability of the region as well. Another large aspect of the society of Freewind Post deals with the wyverns of Highperch, where young tauren are sent to study the wyverns and to cull eggs from their ancestral nesting grounds to be raised as mounts for the Horde.\n\nThe Horde-aligned tauren of Freewind Post grew continually more wary of the activities of the Grimtotem tribe situated atop Darkcloud Pinnacle to the northwest. The Grimtotems had been suspected to be involved in murder, kidnappings of Freewind tauren, and visits from agents of unknown (but reportedly dark) origins. The chieftain of Darkcloud Pinnacle, Arnak Grimtotem, was largely held to be responsible for these heinous transgressions. A Freewind Post tauren, Lakota Windsong, was taken against her will when she refused Arnak's advances. Her brother was slain when he came to her defense. She is also apparently close friends with Thalia Amberhide.\n\nClosely related to the problems with the Grimtotem was the concern surrounding a so-called \"Alien Egg\" that was rumored to have appeared near the nests of the Needles' resident wind serpents. The Grimtotem had given supplication to the creature that hatched from the egg, Arikara, Serpent of Vengeance, in hopes that it would aid them in their mission to depose Cairne Bloodhoof as punishment for his changes to tauren culture and tradition.\n\nA blood elf presence appeared in Freewind Post in the form of Magistrix Elosai, who was effectively an exile of Silvermoon. Her controversial quest to seek a natural cure to the blood elves' racial addiction to the arcane led her to Freewind seeking reagents to use in her remedies, along with help from her associate, Wizlo Bearingshiner at Whitereach Post.\n\nBy the time Cairne died, the Grimtotem attacked the post, but the attack was repelled. Its warriors aided Baine in retaking Thunder Bluff.\n\nAt the base of the Post is a small group of tauren and night elves who are apparently are working in conjunction to drive away the Grimtotems.\n\nAt some point, Freewind has been liberated once more by tauren and quilboar alike, who've united against the Grimtotem to retake their home. The town is currently populated by both races, who are very friendly to outsiders and open to trading, while Elmarine keeps the peace. Unfortunately, Freewind suffers from frequent harpy attacks after sundown, occurring once every three or four nights.\n\nDuring the Burning Legion's third invasion, the bridge connecting Freewind Post and Darkcloud Pinnacle was barricaded with fel spikes by demons.\n\nWhether the quilboar and Elmarine remain in the town is unknown.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "Great Lift",
			short = "The Great Lift was a tauren built elevator that allowed travel between the Barrens and Thousand Needles.",
			full = "The Great Lift was a tauren built elevator that allowed travel between the Barrens and Thousand Needles. However, in recent times the quilboar in Southern Barrens have expanded their territory blocking the path from travelers.\n\nThe tauren Grish Longrunner and Brave Moonhorn that once resided here have gone missing, possibly either returning home or killed by the encroaching quilboar.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Highperch",
			short = "Highperch is an elevated western area of the Thousand Needles. It is home to the proud Highperch wyverns and their nests.",
			full = "Highperch is an elevated western area of the Thousand Needles. It is home to the proud Highperch wyverns and their nests. Years ago, Pao'ka Swiftmountain became trapped here, but after being rescued he decided that he would come back to ensure their safety. Then the Twilight's Hammer came and started capturing the wyverns and those they couldn't they destroyed.\n\nThe alpha male, Heartrazor, has been injured and tied down by four Twilight subduers at the back of Highperch. The captured wind riders have been taken to the shelf above Highperch known as the Twilight Aerie where Twilight members have begun using them as their own mounts.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Ironstone Camp",
			short = "Ironstone Camp is a small Horde camp at the border of the Shimmering Flats.",
			full = "Ironstone Camp is a small Horde camp at the border of the Shimmering Flats. This small group of Horde was sent to drive out the dwarven excavators from the Rustmaul Digsite, but got much more than they bargained for when the Silithid erupted from a nearby cave and attacked them. One of the members present, Moktar Krin, sends out other members of the Horde to kill the Silithid infesting the digsite.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage abyss"] = {
			name = "Mirage Abyss",
			short = "They're found throughout the Shimmering Deep in Thousand Needles with several Southsea Treasure Hunters within them trying to collect the treasure chests that were lost when the giant Whale Shark sank one of their ships.",
			full = "They're found throughout the Shimmering Deep in Thousand Needles with several Southsea Treasure Hunters within them trying to collect the treasure chests that were lost when the giant Whale Shark sank one of their ships. An excellent place to harvest [Stranglekelp].",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Abyss",
		},
		["mirage raceway"] = {
			name = "Mirage Raceway",
			short = "The Mirage Raceway (or Mirage Racetrack) was built by the goblin Pozzik and gnome Fizzle Brassbolts as a result of their rivalry to prove the superiority of their respective race.",
			full = "The Mirage Raceway (or Mirage Racetrack) was built by the goblin Pozzik and gnome Fizzle Brassbolts as a result of their rivalry to prove the superiority of their respective race. The two also built rocket cars and enlisted teams to drive them.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["raceway ruins"] = {
			name = "Raceway Ruins",
			short = "The Raceway Ruins are the ruins of Mirage Raceway found under the waters of Shimmering Deep in Thousand Needles.",
			full = "The Raceway Ruins are the ruins of Mirage Raceway found under the waters of Shimmering Deep in Thousand Needles. Southsea Treasure Hunters search the ruins for anything of value and have even trapped a raceway survivor within an outhouse, which has a limited amount of air left. Rocket Car Parts can be found scattered all over the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Raceway_Ruins",
		},
		["razorfen downs"] = {
			name = "Razorfen Downs",
			short = "Razorfen Downs (or simply Razorfen or the Downs) are the ancestral burial grounds of the quilboar, nestled amid huge brambles in the Thousand Needles.",
			full = "Razorfen Downs (or simply Razorfen or the Downs) are the ancestral burial grounds of the quilboar, nestled amid huge brambles in the Thousand Needles.\n\nIt is said that the entrance to the Downs is made from Agamaggan's maw. The entry to the outside dome is an arched gap, nearly invisible to any who didn't know where to look.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Roguefeather Den",
			short = "Roguefeather Den is a small cavern in south central Thousand Needles, filled with aggressive screeching harpies. The harpies zealously guard their gathered foodstuffs in the back of the den.",
			full = "Roguefeather Den is a small cavern in south central Thousand Needles, filled with aggressive screeching harpies. The harpies zealously guard their gathered foodstuffs in the back of the den.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Rustmaul Dig Site",
			short = "The Rustmaul Dig Site was an abandoned dwarven digsite in the Shimmering Flats. The Explorers' League was in the process of uncovering some ruins when a war party led by Moktar Krin attacked them, killing them all.",
			full = "The Rustmaul Dig Site was an abandoned dwarven digsite in the Shimmering Flats. The Explorers' League was in the process of uncovering some ruins when a war party led by Moktar Krin attacked them, killing them all. The battle apparently stirred up a nest of silithid creatures from a cave in the dig site. The continuous swarm of insects that erupted drove the already weakened war party off.\n\nThe surviving members of the Horde war party can be found at Ironstone Camp, while some did manage to make it to Orgrimmar. The area was renamed to Sunken Dig Site.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["screeching canyon"] = {
			name = "Screeching Canyon",
			short = "The Screeching Canyon was a canyon in the southern parts of Thousand Needles infested by aggressive Screeching harpies. The Roguefeather Den was located in the back of it.",
			full = "The Screeching Canyon was a canyon in the southern parts of Thousand Needles infested by aggressive Screeching harpies. The Roguefeather Den was located in the back of it.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering deep"] = {
			name = "Shimmering Deep",
			short = "The gnomes and goblins working together built a Speedbarge at the center of the lake and continue \"working\" relations with each other.",
			full = "The gnomes and goblins working together built a Speedbarge at the center of the lake and continue \"working\" relations with each other.\n\nA crystal shard of Aramar Thorne's compass was located at the bottom.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Deep",
		},
		["shimmering flats"] = {
			name = "Shimmering Flats",
			short = "The Shimmering Flats was a large stretch of salt flats at the southeastern end of Thousand Needles, on the border with Tanaris.",
			full = "The Shimmering Flats was a large stretch of salt flats at the southeastern end of Thousand Needles, on the border with Tanaris. The area was an open expanse devoid of any vegetation and home to various varieties of, among other things, basilisks, scorpids, turtles, and vultures. The area was a dried lakebed, as evidenced by the wrecked sailing vessel in the northern part.\n\nThe flatness of the area made it especially desirable for goblins and gnomes, who had set up the Mirage Raceway and constantly competed against each other to see who could build the fastest racing machine. Their inventions were frequently unstable, and the area was littered with the wreckage and parts of countless failed gizmos, as well as numerous craters.\n\nA group of dwarven archaeologists was attacked by a Horde raiding party led by Moktar Krin, but they all were driven out of the Rustmaul Dig Site in the southwest when they inadvertently dug into a subterranean silithid hive.\n\nWith the submerging of the Raceway, Fizzle and Pozzik built Fizzle and Pozzik's Speedbarge.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Notable islands like Zandalar, Kezan or Tel'Abim are located here. Since this sea is found in between the continents, it is a portion of the Great Sea.",
			full = "Notable islands like Zandalar, Kezan or Tel'Abim are located here. Since this sea is found in between the continents, it is a portion of the Great Sea.\n\nDarkspear Islands\n\nHiji\n\nIsle of Kezan\n\nThe Maelstrom\n\nThe Eye\n\nPlunder Isle\n\nTel Abim\n\nZandalar",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southsea holdfast"] = {
			name = "Southsea Holdfast",
			short = "The Southsea Holdfast is a Southsea Pirates outpost located on a shelf above the Shimmering Deep in Thousand Needles.",
			full = "The Southsea Holdfast is a Southsea Pirates outpost located on a shelf above the Shimmering Deep in Thousand Needles. They've built ramps from the top to the waters down below where they have three vessels awaiting orders. This group of pirates is led by Tony Two-Tusk, which can be found in the nearby cavern named the Admiral's Den.\n\nA goblin and his gnome companion from the speedbarge came to this location to barter with the pirate, however, they were captured and since then the pirate have begun attacking the ship.\n\nDuring the Thousand Boat Bash, the ships anchored here are raided for grog.",
			source = "https://warcraft.wiki.gg/wiki/Southsea_Holdfast",
		},
		["speedbarge bar"] = {
			name = "Speedbarge Bar",
			short = "The Speedbarge Bar is an inn and tavern below the deck of the Fizzle and Pozzik's Speedbarge in Thousand Needles, with Daisy serving as its inn- and barkeeper.",
			full = "The Speedbarge Bar is an inn and tavern below the deck of the Fizzle and Pozzik's Speedbarge in Thousand Needles, with Daisy serving as its inn- and barkeeper.\n\nHotfix also works here.",
			source = "https://warcraft.wiki.gg/wiki/Speedbarge_Bar",
		},
		["splithoof crag"] = {
			name = "Splithoof Crag",
			short = "Splithoof Crag was the name of the Galak centaur village located against the northern wall of Thousand Needles, just east of Darkcloud Pinnacle.",
			full = "Splithoof Crag was the name of the Galak centaur village located against the northern wall of Thousand Needles, just east of Darkcloud Pinnacle.\n\nThe surviving centaur founded a new village, Splithoof Heights, on the cliffs looking over the Shimmering Deep.\n\nThe crag is now littered with debris and underwater life, along the mountain side, in the center of the village, is a cavern known as Splithoof Hold. This is where the Cloven Hoof, an ancient artifact, was heavily guarded and protected by the Ancient Brazier and its Sacred Flame.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof heights"] = {
			name = "Splithoof Heights",
			short = "Splithoof Heights is the Galak centaur village, on the large shelf to the north of the Shimmering Deep in Thousand Needles.",
			full = "Splithoof Heights is the Galak centaur village, on the large shelf to the north of the Shimmering Deep in Thousand Needles.\n\nThe land contains many oil pools and likely has a huge pocket of oil under them. Both the goblins and gnomes are trying to make a deal with the centaur in order to gain the drilling rights to the oil.\n\nThe centaur here worship an air elemental and a lord within the Skywall, named Whrrrl, who has become the supposed leader of the tribe.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Heights",
		},
		["splithoof hold"] = {
			name = "Splithoof Hold",
			short = "Splithoof Hold is a cave located in Splithoof Crag in Thousand Needles. The Galak centaur tribe adapted it into a stronghold.",
			full = "Splithoof Hold is a cave located in Splithoof Crag in Thousand Needles. The Galak centaur tribe adapted it into a stronghold. The cavern housed the Ancient Brazier and the Sacred Flame, which eternally burns, even underwater. In the end though, Aquarian doused it.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["sunken dig site"] = {
			name = "Sunken Dig Site",
			short = "The Sunken Dig Site is the flooded remains of the silithid-infested Rustmaul Dig Site in the southern Thousand Needles.",
			full = "The Sunken Dig Site is the flooded remains of the silithid-infested Rustmaul Dig Site in the southern Thousand Needles. When the region was flooded, most of the silithid seem to have burrowed underground (although the wasps now instead fly about above the water's surface). The gnome Brivelthwerp wanted to turn the now seemingly empty hive into a refrigeration vault for his ice cream empire. However, when the pipes had almost been installed, the silithid burrowed out of the cave and killed all of his employees. Brivelthwerp himself survived on his tugboat on the surface, where he asks adventurers for help in salvaging the operation.",
			source = "https://warcraft.wiki.gg/wiki/Sunken_Dig_Site",
		},
		["tahonda ruins"] = {
			name = "Tahonda Ruins",
			short = "The Tahonda Ruins are a tauren village that long ago came to ruin and slipped beneath the sands of the Shimmering Flats.",
			full = "The Tahonda Ruins are a tauren village that long ago came to ruin and slipped beneath the sands of the Shimmering Flats.\n\nLittle to no information was known about this village. The ruins were inhabited by Saltstone basilisks, which might have been the reason why it was abandoned. Other evidence points to an attack by hostile forces: two sets of three parallel tears in the leather of one of the buildings.\n\nThe ruins now sit beneath the waves in the southern reaches of Shimmering Deep, near the path through the mountain to Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["tirths haunt"] = {
			name = "Tirth's Haunt",
			short = "Tirth's Haunt is a small camp site where Magus Tirth, having gone mad when he failed to prevent the flooding of Thousand Needles, can be found torturing \"Plucky\" Johnson.",
			full = "Tirth's Haunt is a small camp site where Magus Tirth, having gone mad when he failed to prevent the flooding of Thousand Needles, can be found torturing \"Plucky\" Johnson. The camp is just south of the Southsea Holdfast. A portal was created the connects from here to Ajamon Ghostcaller.",
			source = "https://warcraft.wiki.gg/wiki/Tirth's_Haunt",
		},
		["twilight aerie"] = {
			name = "Twilight Aerie",
			short = "Twilight Aerie, located in Thousand Needles, sits atop the shelf above Highperch. It is guarded by flying Aerie Aces loyal to the Twilight's Hammer.",
			full = "Twilight Aerie, located in Thousand Needles, sits atop the shelf above Highperch. It is guarded by flying Aerie Aces loyal to the Twilight's Hammer. Twilight Skymaster Richtofen leads the group that has invaded Highperching capturing and killing the wyvern.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Aerie",
		},
		["twilight bulwark"] = {
			name = "Twilight Bulwark",
			short = "Twilight Bulwark is a large Twilight's Hammer outpost located on a shelf in southern Thousand Needles. It overlooks what used to be the Screeching Canyon until it was flooded.",
			full = "Twilight Bulwark is a large Twilight's Hammer outpost located on a shelf in southern Thousand Needles. It overlooks what used to be the Screeching Canyon until it was flooded.\n\nThe outpost has three leaders: Commander Fastfuse, Codemaster Deethuk, and Elementalist Starion, with them gone the combined forces of Freewind Post will be able to clear out the cultists from here. Magatha Grimtotem is being held in the eastern part of the Bulwark by bonds that only a particular code can release.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Bulwark",
		},
		["twilight withering"] = {
			name = "Twilight Withering",
			short = "The Twilight Withering, to the east of Twilight Bulwark, is a similar outpost located on a shelf southeast of Freewind Post in Thousand Needles.",
			full = "The Twilight Withering, to the east of Twilight Bulwark, is a similar outpost located on a shelf southeast of Freewind Post in Thousand Needles. It's here the Twilight's Hammer have summoned a monstrosity, an elemental infused with all four elements along with some Elementium. Known as Animus, this creature is absorbing two powerful elementals, Bound Fury and Bound Vortex. Using The Doomstone, when it has absorbed enough energy from them it will explode taking Thousand Needles with it.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Withering",
		},
		["weathered nook"] = {
			name = "Weathered Nook",
			short = "The Weathered Nook was a small, well-hidden cave and home to Dorn Plainstalker and Prate Cloudseer, found on the northern wall of Thousand Needles.",
			full = "The Weathered Nook was a small, well-hidden cave and home to Dorn Plainstalker and Prate Cloudseer, found on the northern wall of Thousand Needles.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Weazel's Crater",
			short = "Weazel's Crater is a large, deep crater located in the northern part of the Shimmering Flats. Its origins are mysterious, but its name suggests either who found it or who created it.",
			full = "Weazel's Crater is a large, deep crater located in the northern part of the Shimmering Flats. Its origins are mysterious, but its name suggests either who found it or who created it. Due to the fact that there are often goblin and gnome races around the area in highly dangerous cars (as seen by the many bits of rubble and craters scattered about) perhaps this is a result from a rather unstable invention.\n\nIt's currently inhabited by Saltstone basilisks.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["westreach summit"] = {
			name = "Westreach Summit",
			short = "Westreach Summit is tauren village located in the northwestern corner of Thousand Needles. The Horde there are under attack by marauding members of the Grimtotem tribe.",
			full = "Westreach Summit is tauren village located in the northwestern corner of Thousand Needles. The Horde there are under attack by marauding members of the Grimtotem tribe. On top of the summit is Kanati Greycloud leading the defense with several Summit Defenders and Nah'te the flight master. Motega Firemane can be found near the water.",
			source = "https://warcraft.wiki.gg/wiki/Westreach_Summit",
		},
		["whitereach post"] = {
			name = "Whitereach Post",
			short = "Whitereach Post was a small Horde camp along the road near Camp E'thok in Thousand Needles. Its possible survivors made their way to Westreach Summit, though it's unknown since only Kanati Greycloud has been seen since.",
			full = "Whitereach Post was a small Horde camp along the road near Camp E'thok in Thousand Needles. Its possible survivors made their way to Westreach Summit, though it's unknown since only Kanati Greycloud has been seen since.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Windbreak Canyon",
			short = "Windbreak Canyon was a canyon filled with wind serpents and their nests. This place covered most of the area between Freewind Post and the Shimmering Flats on the north side of the road in Thousand Needles.",
			full = "Windbreak Canyon was a canyon filled with wind serpents and their nests. This place covered most of the area between Freewind Post and the Shimmering Flats on the north side of the road in Thousand Needles. The path to the Weathered Nook can be found here.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Stonetalon Mountains: 40 subzones
	[1442] = {
		["battlescar valley"] = {
			name = "Battlescar Valley",
			short = "Battlescar Valley appears to have been a valley with a Horde lumber operation going on before the Alliance attacked and disrupted the lumbering taking place.",
			full = "Battlescar Valley appears to have been a valley with a Horde lumber operation going on before the Alliance attacked and disrupted the lumbering taking place. The night elves have even set flame to the Super Reaper 6000 here. Since then the valley has become a constant site of battles.\n\nThe valley is located northeast of the Farwatcher's Glen and southwest of the Cliffwalker Post in the Stonetalon Mountains. At the heart of the valley stands an ancient tree that has withstood the force of ages and served as a place of peace and learning for generations.",
			source = "https://warcraft.wiki.gg/wiki/Battlescar_Valley",
		},
		["blackwolf river"] = {
			name = "Blackwolf River",
			short = "The Blackwolf River is a small river running through Windshear Crag from the Cragpool Lake in the Stonetalon Mountains.",
			full = "The Blackwolf River is a small river running through Windshear Crag from the Cragpool Lake in the Stonetalon Mountains. It was originally heavily polluted due to the deforestation operations that the Venture Company did in the valley. It also seems the river has been cleansed in some degree.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Boulderslide Cavern",
			short = "Boulderslide Cavern is a cave found at the end of Boulderslide Ravine where the Boulderslide kobolds nest. They frantically mining a rare glowing purple crystal called Resonite, which they guard with their lives.",
			full = "Boulderslide Cavern is a cave found at the end of Boulderslide Ravine where the Boulderslide kobolds nest. They frantically mining a rare glowing purple crystal called Resonite, which they guard with their lives. The crystals have a trace of earthen magic.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Boulderslide Ravine",
			short = "Boulderslide Ravine is a small ravine that is most notable for leading into Boulderslide Cavern. It is accessible from Webwinder Path.",
			full = "Boulderslide Ravine is a small ravine that is most notable for leading into Boulderslide Cavern. It is accessible from Webwinder Path. It is mostly untouched by the nearby warring forces, and is populated by rams and the occasional Cliff Stormer. It often contains mining nodes.\n\nThere is a small abandoned cave opposite the ravine from Boulderslide Cavern. It contains several barrels and is lit by crude torches. The walls are decorated with tribal art that may be that of the tauren.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Camp Aparaje",
			short = "Camp Aparaje was a tauren village in eastern Stonetalon Mountains that was attacked by Grimtotem forces from Grimtotem Post led by Grundig Darkcloud.",
			full = "Camp Aparaje was a tauren village in eastern Stonetalon Mountains that was attacked by Grimtotem forces from Grimtotem Post led by Grundig Darkcloud. Makaba Flathoof used to live there with his daughter Kaya.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Charred Vale",
			short = "The Charred Vale is a large valley once a verdant place but now lies mostly in flames and lava in the southwest section of the Stonetalon Mountains.",
			full = "The Charred Vale is a large valley once a verdant place but now lies mostly in flames and lava in the southwest section of the Stonetalon Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cliffwalker post"] = {
			name = "Cliffwalker Post",
			short = "Cliffwalker Post is a small tauren village on a rise in northern Stonetalon Mountains. It is home to the Cliffwalker family.",
			full = "Cliffwalker Post is a small tauren village on a rise in northern Stonetalon Mountains. It is home to the Cliffwalker family. The village was burned by orders from Overlord Krom'gar after his army's general was killed by the tauren leaders.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nIts rising path is dotted by tauren totems. When Aramar Thorne and Taryndrella passed by Cliffwalker Post, Aram could see figures moving among the trees at the top of the rise. A heavily armed tauren brave emerged down the path that led to the post, but he did not notice them and returned. A few minutes later, Galena Stormspear‎ went by it and several tauren braves noticed her and charged at her. Aram and Drella, now with a subdued ram named Blossom, joined with Galena and managed to flee.",
			source = "https://warcraft.wiki.gg/wiki/Cliffwalker_Post",
		},
		["cragpool lake"] = {
			name = "Cragpool Lake",
			short = "The Cragpool Lake is a small lake in Windshear Crag in the Stonetalon Mountains. An enormous structure built by the Venture Company runs above it.",
			full = "The Cragpool Lake is a small lake in Windshear Crag in the Stonetalon Mountains. An enormous structure built by the Venture Company runs above it. While most of the Venture Company has left the crag those that remained can be found on the structure, including Gerenzo Wrenchwhistle who once used this spot to oversee the Windshear Crag operation. The lake has been declared off limits due to an enormous fish, Cragjaw, that now lives there.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["dagger pass"] = {
			name = "Dagger Pass",
			short = "Dagger Pass is a small pass leading between Mirkfallon Lake to the east and Battlescar Valley to the west. Mountains rise high and steep on either side of it, and there is little vegetation.",
			full = "Dagger Pass is a small pass leading between Mirkfallon Lake to the east and Battlescar Valley to the west. Mountains rise high and steep on either side of it, and there is little vegetation. There is a small empty cave at the southwestern edge.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Pass",
		},
		["deep reaches"] = {
			name = "Deep Reaches",
			short = "The Deep Reaches is a mine found in central Stonetalon Mountains.",
			full = "The Deep Reaches is a mine found in central Stonetalon Mountains. It appears as though both the Horde and Alliance have dug out separate areas to form the mine, but the Explorers' League which dug out the Alliance's side of the mine inadvertently opened a backdoor to the primary Horde base in the area, Krom'gar Fortress.\n\nThis has allowed Krom'gar Assassins to begin killing the Alliance within the mine, the surviving Alliance miners now hide awaiting help. Meanwhile on the Horde side of the mine Raging Earth Elementals have killed everything, except for some peons that were working in the area and managed to find a hiding spot to avoid death. The Alliance are attempting to seal off the mine and prevent further Horde attacks.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Reaches",
		},
		["fallowmere inn"] = {
			name = "Fallowmere Inn",
			short = "The Fallowmere Inn is the inn in the Alliance outpost of Windshear Hold, maintained by Alithia Fallowmere. From here Lord Fallowmere, flanked by Windshear Hold Guardians, looks out over Windshear Crag.",
			full = "The Fallowmere Inn is the inn in the Alliance outpost of Windshear Hold, maintained by Alithia Fallowmere. From here Lord Fallowmere, flanked by Windshear Hold Guardians, looks out over Windshear Crag. The inn also houses the injured, such as Northwatch Captain Kosak.",
			source = "https://warcraft.wiki.gg/wiki/Fallowmere_Inn",
		},
		["farwatchers glen"] = {
			name = "Farwatcher's Glen",
			short = "Farwatcher's Glen is an Alliance town located southwest of Thal'darah Grove and Thal'darah Overlook in Stonetalon Mountains.",
			full = "Farwatcher's Glen is an Alliance town located southwest of Thal'darah Grove and Thal'darah Overlook in Stonetalon Mountains. While using night elf architecture, it features many different Alliance races, most prominently worgen. It holds flight paths to Thal'darah Overlook, Mirkfallon Post, Windshear Hold, and Nijel's Point.\n\nIn addition to Alliance NPCs, a significant number of ravens can be found here.",
			source = "https://warcraft.wiki.gg/wiki/Farwatcher's_Glen",
		},
		["fold"] = {
			name = "The Fold",
			short = "The Fold is a small Horde encampment located near the Talondeep Pass in Stonetalon Mountains. It is the first stop for Horde soldiers entering from Ashenvale.",
			full = "The Fold is a small Horde encampment located near the Talondeep Pass in Stonetalon Mountains. It is the first stop for Horde soldiers entering from Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/The_Fold",
		},
		["greatwood vale"] = {
			name = "Greatwood Vale",
			short = "The Greatwood Vale is a forested valley in the foothills of the Stonetalon Mountains. It is accessible via Webwinder Path.",
			full = "The Greatwood Vale is a forested valley in the foothills of the Stonetalon Mountains. It is accessible via Webwinder Path. The Horde settlement of Malaka'jin is to the south, and the Alliance settlement of Northwatch Expedition Base Camp is to the north.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Grimtotem Post",
			short = "Grimtotem Post is the base of Grimtotem tribe operations in Stonetalon Mountains. Many different types, such as Brutes, Ruffians, Sorcerers, and Mercenaries patrol the post and nearby areas.",
			full = "Grimtotem Post is the base of Grimtotem tribe operations in Stonetalon Mountains. Many different types, such as Brutes, Ruffians, Sorcerers, and Mercenaries patrol the post and nearby areas. The Grimtotem here are led by the fierce Grundig Darkcloud.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["kromgar fortress"] = {
			name = "Krom'gar Fortress",
			short = "Krom'gar Fortress, the main base of the Krom'gar, is a Horde base built within Windshear Crag, opposite the new Alliance town of Windshear Hold in Stonetalon Mountains.",
			full = "Krom'gar Fortress, the main base of the Krom'gar, is a Horde base built within Windshear Crag, opposite the new Alliance town of Windshear Hold in Stonetalon Mountains. Below the Fortress at the base of the cliff is the Horde entrance to the Deep Reaches.\n\nDespite its denomination of \"fortress\", it is only made up of a fortified burrow, a blacksmith, and two towers.",
			source = "https://warcraft.wiki.gg/wiki/Krom'gar_Fortress",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Malaka'jin is a Horde village in the Stonetalon Mountains, just south of the Grimtotem Post. It houses a small community of troll hunters who make a modest income by selling their catches to passing Horde adventurers.",
			full = "Malaka'jin is a Horde village in the Stonetalon Mountains, just south of the Grimtotem Post. It houses a small community of troll hunters who make a modest income by selling their catches to passing Horde adventurers.\n\nMalaka'jin expanded into a quest hub with a flight master. It is from here the Horde will launch their attacks against the Grimtotem tribe in Stonetalon. The High Road from the Southern Barrens also connects here.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Mirkfallon Lake",
			short = "Mirkfallon Lake is a lake located within the center of Stonetalon Mountains. It was once host to a wide variety of creatures, including wyverns, slimes, and thunder lizards.",
			full = "Mirkfallon Lake is a lake located within the center of Stonetalon Mountains. It was once host to a wide variety of creatures, including wyverns, slimes, and thunder lizards.\n\nThe goblins have carved out the hill in the center of the lake, replacing it with an oil platform, and pumpjacks surround the area. Several paths cross through this area: Stonetalon Peak and Cliffwalker Post are north, Dagger Pass to the west leads to Battlescar Valley, Webwinder Path is south, and a mountain path to the east leads to Windshear Hold and Windshear Crag. Above the lake is Windshear Heights, the nesting site for the area's remaining wyverns. To the southwest of the lake is an Alliance camp, Mirkfallon Post.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["mirkfallon post"] = {
			name = "Mirkfallon Post",
			short = "Mirkfallon Post is an Alliance camp located south of Mirkfallon Lake in Stonetalon Mountains. The camp is apparently directed by two scout leaders.",
			full = "Mirkfallon Post is an Alliance camp located south of Mirkfallon Lake in Stonetalon Mountains. The camp is apparently directed by two scout leaders.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Post",
		},
		["northwatch expedition base camp"] = {
			name = "Northwatch Expedition Base Camp",
			short = "The Northwatch Expedition Base Camp (or just the Northwatch Expedition Base) is an Alliance camp located near the Unearthed Grounds, headed by Force Commander Valen in the Stonetalon Mountains.",
			full = "The Northwatch Expedition Base Camp (or just the Northwatch Expedition Base) is an Alliance camp located near the Unearthed Grounds, headed by Force Commander Valen in the Stonetalon Mountains. Accessible from the Greatwood Vale, it overlooks Grimtotem Post and the conflict taking place there. It is from here that the Alliance began digging what is now known as the Deep Reaches, and the outpost also opens up to the Unearthed Grounds; both areas are the site of conflict with the Horde at present.\n\nDue to the ongoing war effort, contingents of Northwatch Infantry regularly pass through here. Members of the Explorers' League are also present due to the excavations.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nAt some point, when the Alliance soldiers were seemingly fighting elsewhere, Malus and the Hidden lured Aramar Thorne into the base camp. A great battle ensued here between the Hidden and Aram's friends, with Malus killing Taryndrella. The arakkoa Ssarbik opened a portal and the Hidden left with Aram, but not before kicking Reigol Valdread off the camp down to the valley. The camp was left battle-torn, and Makasa took its remaining weapons. Almost a year later, Aram returned here but did not stay long in the camp. He came to see the Forever Tree below. According to the base's soldiers, the tree blooms year-round.",
			source = "https://warcraft.wiki.gg/wiki/Northwatch_Expedition_Base_Camp",
		},
		["northwatch expedition base camp inn"] = {
			name = "Northwatch Expedition Base Camp Inn",
			short = "Northwatch Expedition Base Camp Inn is an inn located in the Northwatch Expedition Base Camp in the Stonetalon Mountains.",
			full = "Northwatch Expedition Base Camp Inn is an inn located in the Northwatch Expedition Base Camp in the Stonetalon Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Northwatch_Expedition_Base_Camp_Inn",
		},
		["ruins of eldrethar"] = {
			name = "Ruins of Eldre'thar",
			short = "The Ruins of Eldre'thar are newly discovered ruins of a Highborne city located inside Sishir Canyon. The ghostly highborne elves still haunt the area.",
			full = "The Ruins of Eldre'thar are newly discovered ruins of a Highborne city located inside Sishir Canyon. The ghostly highborne elves still haunt the area. The area is a night elf archaeology dig site and Nal'taszar can be found floating the lake's waters. Various conversations can be overheard among the named highborne ghosts.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldre'thar",
		},
		["sishir canyon"] = {
			name = "Sishir Canyon",
			short = "Sishir Canyon is an empty canyon that leads from the main road in the Stonetalon Mountains to the Ruins of Eldre'thar.",
			full = "Sishir Canyon is an empty canyon that leads from the main road in the Stonetalon Mountains to the Ruins of Eldre'thar.\n\nSishir Canyon was previously a canyon completely taken over by monstrous Deepmoss spiders. Their eggs and webbing densely covered the whole area, and deep inside, the most powerful of their number Besseleth awaited. When Stonetalon was redesigned this area became the opened up Webwinder Hollow and a new canyon was added and given the same name just west of it.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["sludgewerks"] = {
			name = "Sludgewerks",
			short = "The Sludgewerks is a small Horde base built near a wyvern habitat on the shores of Mirkfallon Lake in Stonetalon Mountains.",
			full = "The Sludgewerks is a small Horde base built near a wyvern habitat on the shores of Mirkfallon Lake in Stonetalon Mountains. Initially designed to not do any harm to the wyvern, the goblins that run the platform have had the misfortune of dealing with the droppings of the local wyvern because of this design and location.",
			source = "https://warcraft.wiki.gg/wiki/Sludgewerks",
		},
		["stonetalon peak"] = {
			name = "Stonetalon Peak",
			short = "Stonetalon Peak is an Alliance settlement at the far northwestern end of the Stonetalon Mountains. It is built within a verdant mountain valley and is maintained by the druids of the nearby Talon Den.",
			full = "Stonetalon Peak is an Alliance settlement at the far northwestern end of the Stonetalon Mountains. It is built within a verdant mountain valley and is maintained by the druids of the nearby Talon Den. Stonetalon Peak has recently been destroyed by invading tendrils. The area is now inhabited with Corrupted Sentinels. Brother Ravenoak has woken up, and appears to have been corrupted by the tendrils.\n\nLocal cultures consider the mountain sacred. It is suffused by magic.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Sun Rock Retreat",
			short = "Sun Rock Retreat (also spelled Sunrock Retreat) is a Horde settlement centrally-located in the Stonetalon Mountains, hidden amid the peaks south of Mirkfallon Lake.",
			full = "Sun Rock Retreat (also spelled Sunrock Retreat) is a Horde settlement centrally-located in the Stonetalon Mountains, hidden amid the peaks south of Mirkfallon Lake. It was once the area's primary hub of activity and trade, hosting a contingent of predominantly orcish and tauren forces devoted to repairing the damage done to the mountains by the Venture Company and other malignant forces.\n\nIn ages past, tauren made pilgrimages to Sun Rock Retreat to engage in rituals to cross over to the spirit world, as the place has a strong bond to the spirit realm. It is said that long ago, An'she himself kissed the mountain where the retreat now stands.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "Talon Den",
			short = "The Talon Den is a barrow den on Stonetalon Peak inhabited by Mirkfallon Dryads, night elves Cenarion Caretakers, and Mirkfallon Keepers.",
			full = "The Talon Den is a barrow den on Stonetalon Peak inhabited by Mirkfallon Dryads, night elves Cenarion Caretakers, and Mirkfallon Keepers.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep pass"] = {
			name = "Talondeep Pass",
			short = "The Talondeep Pass is an artificial mountain pass that connects Ashenvale with the Stonetalon Mountains. It was created by goblins by excavating away the Talondeep Path.",
			full = "The Talondeep Pass is an artificial mountain pass that connects Ashenvale with the Stonetalon Mountains. It was created by goblins by excavating away the Talondeep Path. It is intended for both the Horde and the Alliance. A side pass from Stardust Spire leads to Trueshot Point for the Alliance. The entrance on the Ashenvale side is found just east of Stardust Spire, while the entrance on the Stonetalon side is found in the northeastern part of Windshear Crag, next to the Fold.\n\nAlliance players travel from Ashenvale to Stonetalon Mountains through the Talondeep Pass during the quests [7-30] Hellscream's Legacy and [7-30] Field Test: Gnomecorder, while Horde players pass through it during the quest [10-30] We're Here to Do One Thing, Maybe Two....\n\nThe goblins built a mine field here, but the night elves disarmed them all.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Pass",
		},
		["talondeep path"] = {
			name = "Talondeep Path",
			short = "The Talondeep Path was a winding tunnel that connected Ashenvale with the Stonetalon Mountains.",
			full = "The Talondeep Path was a winding tunnel that connected Ashenvale with the Stonetalon Mountains. Although it was riddled with small dead ends and interesting holes in the walls, there were no friendly NPCs nor hostile mobs inside. The entrance on the Ashenvale side was found just west of Mystral Lake, while the entrance on the Stonetalon side was found in the northwestern part of Windshear Crag.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thaldarah grove"] = {
			name = "Thal'darah Grove",
			short = "Thal'darah Grove was a druid training ground located at the heart of Battlescar Valley in the Stonetalon Mountains.",
			full = "Thal'darah Grove was a druid training ground located at the heart of Battlescar Valley in the Stonetalon Mountains. This ancient tree had been a place of peace and learning for generations and had been used by both the night elves and tauren.\n\nOverlord Krom'gar believed this to be the location of a weapon of mass destruction that would be used against the Horde when they got the chance. It played a key role in a quest chain involving a bomb. The quest ended when the bomb was dropped on Thal'darah Grove ultimately destroying it. Before the destruction, some druids were rescued by the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Thal'darah_Grove",
		},
		["thaldarah overlook"] = {
			name = "Thal'darah Overlook",
			short = "Thal'darah Overlook is an Alliance town located just south of Stonetalon Peak in Stonetalon Mountains. It has a moonwell and wisps.",
			full = "Thal'darah Overlook is an Alliance town located just south of Stonetalon Peak in Stonetalon Mountains. It has a moonwell and wisps.",
			source = "https://warcraft.wiki.gg/wiki/Thal'darah_Overlook",
		},
		["trueshot point"] = {
			name = "Trueshot Point",
			short = "Trueshot Point is a small Alliance encampment near the entrance of Talondeep Pass in Stonetalon Mountains. It is occupied notably by Kalen Trueshot, offering [10-30] The Only Way Down is in a Body Bag.",
			full = "Trueshot Point is a small Alliance encampment near the entrance of Talondeep Pass in Stonetalon Mountains. It is occupied notably by Kalen Trueshot, offering [10-30] The Only Way Down is in a Body Bag.\n\nThis subzone is not directly accessible from the rest of Stonetalon Mountains. The only way to Trueshot Point on foot is from the nearby Stardust Spire in Ashenvale.",
			source = "https://warcraft.wiki.gg/wiki/Trueshot_Point",
		},
		["unearthed grounds"] = {
			name = "Unearthed Grounds",
			short = "The Unearthed Grounds was an Explorers' League excavation site found just north of the Greatwood Vale and east of the Northwatch Expedition Base Camp in Stonetalon Mountains.",
			full = "The Unearthed Grounds was an Explorers' League excavation site found just north of the Greatwood Vale and east of the Northwatch Expedition Base Camp in Stonetalon Mountains. The area was forcibly taken by the Horde from the dwarves who were working it.",
			source = "https://warcraft.wiki.gg/wiki/Unearthed_Grounds",
		},
		["webwinder hollow"] = {
			name = "Webwinder Hollow",
			short = "Webwinder Hollow, formerly Sishir Canyon, is a large valley just off of Webwinder Path in the Stonetalon Mountains. The valley is filled with Deepmoss spiders and their queen, Queen Silith.",
			full = "Webwinder Hollow, formerly Sishir Canyon, is a large valley just off of Webwinder Path in the Stonetalon Mountains. The valley is filled with Deepmoss spiders and their queen, Queen Silith.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Hollow",
		},
		["webwinder path"] = {
			name = "Webwinder Path",
			short = "Webwinder Path is a main stretch of road that goes from Malaka'jin, all the way to Mirkfallon Lake. Much of the land that runs alongside the path has sunk a great amount.",
			full = "Webwinder Path is a main stretch of road that goes from Malaka'jin, all the way to Mirkfallon Lake. Much of the land that runs alongside the path has sunk a great amount. The Horde setup up a barricade just west of Malaka'Jin in order to prevent the Alliance from heading further east.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nAramar Thorne and Makasa Flintwill led their groups through the path. When they looked skyward, Makasa and Murky noticed how the forest above was made into a labyrinth of spider webs formed into tunnels and loops, a veritable fortress of glittering ivory strands, with hundreds of spiders.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Windshear Crag",
			short = "Windshear Crag was once a massive old-growth forest nestled in a valley in the Stonetalon Mountains.",
			full = "Windshear Crag was once a massive old-growth forest nestled in a valley in the Stonetalon Mountains.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear heights"] = {
			name = "Windshear Heights",
			short = "Windshear Heights is a wyvern habitat located east of the Mirkfallon Lake in the Stonetalon Mountains.",
			full = "Windshear Heights is a wyvern habitat located east of the Mirkfallon Lake in the Stonetalon Mountains. Since the construction of the Sludgewerks on the lake, the Heights has become one of the largest remaining nesting areas for the Pridewing Wyverns.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Heights",
		},
		["windshear hold"] = {
			name = "Windshear Hold",
			short = "Windshear Hold is an Alliance town located in Windshear Crag, Stonetalon Mountains. While using night elf architecture, it features many different Alliance races.",
			full = "Windshear Hold is an Alliance town located in Windshear Crag, Stonetalon Mountains. While using night elf architecture, it features many different Alliance races. It holds flight paths to Stardust Spire, Thal'darah Overlook, Farwatcher's Glen, and Nijel's Point.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Hold",
		},
		["windshear mine"] = {
			name = "Windshear Mine",
			short = "Windshear Mine is a tin mine claimed by the Horde after the Venture Company abandoned the area. The mine is located at the end of Blackwolf River in Windshear Crag.",
			full = "Windshear Mine is a tin mine claimed by the Horde after the Venture Company abandoned the area. The mine is located at the end of Blackwolf River in Windshear Crag. When the Venture Company controlled the area they employed kobolds to mine the area.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
		["windshear valley"] = {
			name = "Windshear Valley",
			short = "Windshear Valley is a forested valley within the Windshear Crag of the Stonetalon Mountains. The Northwatch Expeditionary Unit control this valley currently and have cleared most of the wildlife that once lived here.",
			full = "Windshear Valley is a forested valley within the Windshear Crag of the Stonetalon Mountains. The Northwatch Expeditionary Unit control this valley currently and have cleared most of the wildlife that once lived here. Now, besides the Alliance, only Stonetalon Rams are here.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Valley",
		},
	},
	-- Desolace: 32 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Bolgan's Hole",
			short = "Bolgan's Hole is a cave in Gelkis Village in Desolace that houses the most prominent members of the Gelkis centaur. The clan's khan -- currently Khan Shodo, formerly Khan Shaka -- is housed here.",
			full = "Bolgan's Hole is a cave in Gelkis Village in Desolace that houses the most prominent members of the Gelkis centaur. The clan's khan -- currently Khan Shodo, formerly Khan Shaka -- is housed here. Blue crystals called tears of Theradras grow there which the clan's shaman hoard, believing they grant them Princess Theradras' protection.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["cenarion wildlands"] = {
			name = "Cenarion Wildlands",
			short = "The Cenarion Wildlands are a new lush area in the middle of Desolace. At the center of the grove is Karnum's Glade, a brightly lit shrine with night elf architecture.",
			full = "The Cenarion Wildlands are a new lush area in the middle of Desolace. At the center of the grove is Karnum's Glade, a brightly lit shrine with night elf architecture.\n\nWith the sudden changes to the area, some of the local flora and fauna didn't react as well as the Cenarion Circle had hoped. Uprooted Lashers roam the areas in the east and south disrupting the new life that springs forth. Meanwhile, the air elementals are preventing its further growth into the desert to the west. All of the wildlife in the area, however, have responded to their new environment in strange and exciting ways.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Wildlands",
		},
		["earth song gate"] = {
			name = "Earth Song Gate",
			short = "Earth Song Gate is a stone gate, flanked by centaur statues, that leads from Zaetar's Choice to the lower section of the Wicked Tunnels in Desolace.",
			full = "Earth Song Gate is a stone gate, flanked by centaur statues, that leads from Zaetar's Choice to the lower section of the Wicked Tunnels in Desolace. This portion of the Wicked Tunnels contains the instance portal to the Earth Song Falls in Maraudon.",
			source = "https://warcraft.wiki.gg/wiki/Earth_Song_Gate",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Ethel Rethor is a night elven ruin in the far northwest of Desolace. Most of the ruins are located under-water with the exception of a lone tower with a small bridge leading to a closed entrance.",
			full = "Ethel Rethor is a night elven ruin in the far northwest of Desolace. Most of the ruins are located under-water with the exception of a lone tower with a small bridge leading to a closed entrance. As with many other coastal elven ruins this one is also inhabited by naga.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["foulspore pools"] = {
			name = "Foulspore Pools",
			short = "The Foulspore Pools are a portion of the tunnel system leading to Maraudon below Desolace, accessed by taking the southern tunnel from Zaetar's Choice.",
			full = "The Foulspore Pools are a portion of the tunnel system leading to Maraudon below Desolace, accessed by taking the southern tunnel from Zaetar's Choice. The area is filled with basilisks, earth elementals, and glittering orange crystals dripping into pools of orange water. The dryad Cavindra is found at a small pool of unpolluted water. The instance portal to the Foulspore Cavern in Maraudon is located at the far end of the area.",
			source = "https://warcraft.wiki.gg/wiki/Foulspore_Pools",
		},
		["furiens post"] = {
			name = "Furien's Post",
			short = "Furien's Post is a small blood elf forward post charged with monitoring potential adversaries to the Horde in Desolace. They were requested by the Cenarion Circle to keep an eye on one of their researchers, Korrah.",
			full = "Furien's Post is a small blood elf forward post charged with monitoring potential adversaries to the Horde in Desolace. They were requested by the Cenarion Circle to keep an eye on one of their researchers, Korrah. It's a task the blood elves don't care for, but they occasionally check on Korrah so as to not get on the Cenarion Circle's bad side.",
			source = "https://warcraft.wiki.gg/wiki/Furien's_Post",
		},
		["gelkis village"] = {
			name = "Gelkis Village",
			short = "Gelkis Village is a centaur village located just to the east and slightly south of Shadowprey Village in southwestern Desolace.",
			full = "Gelkis Village is a centaur village located just to the east and slightly south of Shadowprey Village in southwestern Desolace. It is the principal village of the Gelkis clan, and is situated in a ring around a large ravine. A cluster of cliffs and bluffs in the ravine are connected by a series of bridges and lead to Bolgan's Hole, a cave in the southern mountain face of Desolace. The Gelkis Khan resides within this cave. The entire village is directly adjacent to Desolace's main north-south road and is thus a hazard for many travelers. Recently the centaur have expanded the village some and now have huts on the east side of the road that leads into Feralas, near the lake.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Ghost Walker Post",
			short = "Ghost Walker Post is a small tauren outpost established in central Desolace directly adjacent to the Kodo Graveyard.",
			full = "Ghost Walker Post is a small tauren outpost established in central Desolace directly adjacent to the Kodo Graveyard. It is one of two Horde outposts in the region, though Ghost Walker Post is much more exposed to danger compared to Shadowprey Village and its relatively secure location. It is from Ghost Walker Post that the Horde wages its war on the Burning Blade and their servants in Desolace as well as the various centaur tribes. The leader of Ghost Walker Post is Gurda Wildmane, a tauren shaman. Gurda and the other shamans ease the nearby kodo into their next lives and sometimes communicate with the spirits of dead kodo. There is also a contingent of orcs here, sent by Thrall. Ghost Walker Post is home to only the bare necessities of adventuring in Desolace, lacking so much as an inn or a wind rider master. The village has become part of the Cenarion Wildlands.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["karnums glade"] = {
			name = "Karnum's Glade",
			short = "Karnum's Glade is a Cenarion Circle respite located in the middle of the Cenarion Wildlands in Desolace and under the care and direction of Karnum Marshweaver.",
			full = "Karnum's Glade is a Cenarion Circle respite located in the middle of the Cenarion Wildlands in Desolace and under the care and direction of Karnum Marshweaver. Cenarion Hippogryphs fly around in the air above the glade as well as the Wildlands around it.",
			source = "https://warcraft.wiki.gg/wiki/Karnum's_Glade",
		},
		["kodo graveyard"] = {
			name = "Kodo Graveyard",
			short = "The Kodo Graveyard is a large gaveyard that is final resting place of the Kodo, location in Desolace.",
			full = "The Kodo Graveyard is a large gaveyard that is final resting place of the Kodo, location in Desolace. Notably, there is a quest to collect kodo bones that requires adventurers to fight kodo apparitions which materialize when they attempt to loot bones on the ground.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Kolkar Village",
			short = "Kolkar Village was the center of power for the Kolkar clan of centaur. The village located on the eastern margin of Desolace between Sargeron to the north and Magram Village to the south was conquered by the Magram clan.",
			full = "Kolkar Village was the center of power for the Kolkar clan of centaur. The village located on the eastern margin of Desolace between Sargeron to the north and Magram Village to the south was conquered by the Magram clan.\n\nThe Kolkars were the most prolific of the centaur clans in Kalimdor, having villages and outposts in both the Barrens and Durotar, so a blow to their base of power at the village in Desolace would be a strategic move for their enemies.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Kormek's Hut",
			short = "Kormek's Hut is a small hovel in north-central Desolace. It is inhabited by the odd pair of Willow and Bibbly F'utzbuckle. Willow, who can be found inside the hut, is a friendly member of the Twilight's Hammer.",
			full = "Kormek's Hut is a small hovel in north-central Desolace. It is inhabited by the odd pair of Willow and Bibbly F'utzbuckle. Willow, who can be found inside the hut, is a friendly member of the Twilight's Hammer. Bibbly greatly enjoys dancing around in the pen outside, excited by the potential profit of kodo bones (which also litter the pen). The location of the hut's namesake is unknown.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram territory"] = {
			name = "Magram Territory",
			short = "Magram Territory is a large centaur village in eastern Desolace. Formerly Kolkar Village, it is here where the Magram clan reside after having nearly annihilated the Kolkar clan.",
			full = "Magram Territory is a large centaur village in eastern Desolace. Formerly Kolkar Village, it is here where the Magram clan reside after having nearly annihilated the Kolkar clan. The Magram moved into the area after demons from the Burning Blade took over their land in the far south.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Territory",
		},
		["magram village"] = {
			name = "Magram Village",
			short = "Magram Village is a centaur village, home of the Magram clan. It is located in the southeastern area of Desolace on the shores and islands of a series of polluted yellow pools.",
			full = "Magram Village is a centaur village, home of the Magram clan. It is located in the southeastern area of Desolace on the shores and islands of a series of polluted yellow pools. Crude bridges connect the islands to each other and the shore. Adventurers can choose to ally with the Magram clan in their ongoing war against the Gelkis clan.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Mannoroc Coven",
			short = "Mannoroc Coven located directly to the south of Ghost Walker Post and east of Shadowprey Village, is the location of a number of night elven ruins in Desolace.",
			full = "Mannoroc Coven located directly to the south of Ghost Walker Post and east of Shadowprey Village, is the location of a number of night elven ruins in Desolace. It is named after the dreaded Pit Lord, Mannoroth. The already dead earth has been even further blasted with fel magic by demons that inhabit the area. The magic is thick in the air and travelers will notice that a deadly pall falls over the region upon entering. The infernal, the succubus, the felhound and the felguard stalk the area and are hostile to all foolish enough to pass through.\n\nSeveral agents of the Burning Legion, including fel hunters, infernals, doom guards and succubi, reside here, led by Lord Azrethoc. The orc warlock Jugkar Grim'rod also represents the Burning Blade here. This group is the largest demonic coven in central Kalimdor.\n\nThe coven is a haven for the demons who have been summoned into the world by the Burning Blade cultists using a number of magical portals. The demons that populate the Mannoroc Coven are proof that this nefarious scheme has been dangerously successful. Recently, a number of adventurers have sealed some of these portals using the [Hand of Iruxos] on the behest of Taiga Wisemane, but no matter how many portals are banished, more inevitably appear over time, suggesting that a more permanent solution needs to be found to prevent Desolace from turning into a stronghold of the Burning Legion in Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Nijel's Point",
			short = "Nijel's Point is an Alliance and Cenarion Circle outpost located in the northern mountains of Desolace. It holds flight paths to Feathermoon Stronghold, Theramore Isle, and Lor'danel.",
			full = "Nijel's Point is an Alliance and Cenarion Circle outpost located in the northern mountains of Desolace. It holds flight paths to Feathermoon Stronghold, Theramore Isle, and Lor'danel.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Ranazjar Isle",
			short = "Ranazjar Isle is a small, rocky island off the northwest coast of Desolace. It was inhabited by the serpentine naga, but now they lie slaughtered on the ground by Lord Hydronis.",
			full = "Ranazjar Isle is a small, rocky island off the northwest coast of Desolace. It was inhabited by the serpentine naga, but now they lie slaughtered on the ground by Lord Hydronis. On the isle, there are night elven ruins that seem to be part of the same ancient city as those of Ethel Rethor.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "Sargeron was once a night elven city, but has lain in ruins since the War of the Ancients.",
			full = "Sargeron was once a night elven city, but has lain in ruins since the War of the Ancients. The town's original name has been lost to time, but its ruins are now home to numerous Hatefury satyr who have redubbed it Sargeron -- after their demonic master Sargeras.\n\nThe ruins were home to many holy sites of Elune, including Elune's Cathedral, Elune's Temple and Elune's Sanctuary. Several relics can still be found there, namely Elune's Brazier, Elune's Handmaiden, the Cup of Elune and the Ancient Vortex Runestone.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Sar'theris Strand",
			short = "Sar'theris Strand is the name of the coast of Desolace. It is heavily populated by sea giants, naga, and makrura.",
			full = "Sar'theris Strand is the name of the coast of Desolace. It is heavily populated by sea giants, naga, and makrura. The Karnitol Shipwreck lies off the northern part of the strand, and a small boat lies smashed on the beach below Ethel Rethor. Though Desolace is a grey, gloomy wasteland, the Sar'theris Strand is sunny and grassy. It is off this coast that [Sar'theris Striker] can be fished for [15-30] Nat Pagle, Angler Extreme.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Scrabblescrew's Camp",
			short = "Scrabblescrew's Camp is a small goblin camp located not far from the Kodo Graveyard in Desolace. It is the home of Smeed Scrabblescrew, an enterprising goblin who maintains a kodo caravan.",
			full = "Scrabblescrew's Camp is a small goblin camp located not far from the Kodo Graveyard in Desolace. It is the home of Smeed Scrabblescrew, an enterprising goblin who maintains a kodo caravan.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Shadowbreak Ravine",
			short = "Shadowbreak Ravine is a well-hidden haven for Burning Blade cultists found in the mountains southeast of Shok'Thokar in Desolace.",
			full = "Shadowbreak Ravine is a well-hidden haven for Burning Blade cultists found in the mountains southeast of Shok'Thokar in Desolace. It holds several structures including giant mushrooms and a summoning circle with giant chains. The Burning Blade and demon army, which has invaded Magram Village and pushed the centaur from the area, are commanded by Agogridon. They have begun burning the structures and renamed the area to Shok'Thokar. After the quest [10-30] Death to Agogridon, the area will only have the corpses of Burning Blade cultists and demons.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Shadowprey Village",
			short = "Shadowprey Village is a port located on the southern end of the coast of Desolace. Primarily a troll fishing village, Shadowprey is also a travel node for Horde adventurers.",
			full = "Shadowprey Village is a port located on the southern end of the coast of Desolace. Primarily a troll fishing village, Shadowprey is also a travel node for Horde adventurers. It lies along the Sar'theris Strand, south of the Valley of Spears. Nearby a representative of the Cenarion Circle, the dryad Selendra, investigates the whereabouts of Zaetar's remains.\n\nThis village is home to a number of professional troll fishermen, whose catches help supply food to the Ghost Walker Post and are always in high demand. Recently, Blubbergut, a greedy orca, has been feasting upon all the fish near the village making it difficult to catch any and feed the residents.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["shokthokar"] = {
			name = "Shok'Thokar",
			short = "Shok'Thokar, formerly Magram Village, was the Magram centaur's village before it was taken by the Burning Blade and their demon masters from the Shadowbreak Ravine.",
			full = "Shok'Thokar, formerly Magram Village, was the Magram centaur's village before it was taken by the Burning Blade and their demon masters from the Shadowbreak Ravine. The cultists have even built a new tower near the mountainside to watch over the area.\n\nAfter the quest death of the pit lord Agogridon, the area will have the corpses of Burning Blade cultists and demons, while the three Khans of Gelkis, Magram, and Kolkar remain united and found at the main hut of the village.",
			source = "https://warcraft.wiki.gg/wiki/Shok'Thokar",
		},
		["slitherblade shore"] = {
			name = "Slitherblade Shore",
			short = "Slitherblade Shore is the northern shoreline of Desolace. With Ethel Rethor in the middle, this area reaches up to the border of Stonetalon Mountains and down to Sar'theris Strand with Ranazjar Isle found off the coast.",
			full = "Slitherblade Shore is the northern shoreline of Desolace. With Ethel Rethor in the middle, this area reaches up to the border of Stonetalon Mountains and down to Sar'theris Strand with Ranazjar Isle found off the coast. This includes a newly risen island with night elven ruins from where a naga priestess commands the Slitherblade. Several shipwrecks can be found here.",
			source = "https://warcraft.wiki.gg/wiki/Slitherblade_Shore",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Tethris Aran is a series of night elven ruins found in northern Desolace just north of Thunder Axe Fortress. The ruins are inhabited only by the wild creatures of Desolace.",
			full = "Tethris Aran is a series of night elven ruins found in northern Desolace just north of Thunder Axe Fortress. The ruins are inhabited only by the wild creatures of Desolace. The night elven settlement that was here was presumably destroyed by the Great Sundering.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thargads camp"] = {
			name = "Thargad's Camp",
			short = "Thargad's Camp is an Explorers' League camp located north of Gelkis Village and east of Shadowprey Village. Only three residents live here; one of them is Thargad, the camp's leader.",
			full = "Thargad's Camp is an Explorers' League camp located north of Gelkis Village and east of Shadowprey Village. Only three residents live here; one of them is Thargad, the camp's leader.",
			source = "https://warcraft.wiki.gg/wiki/Thargad's_Camp",
		},
		["thunder axe fortress"] = {
			name = "Thunder Axe Fortress",
			short = "Thunder Axe Fortress is a stronghold occupied by the Burning Blade cult. The fortress is located in northwestern Desolace and is now led by Kohor.",
			full = "Thunder Axe Fortress is a stronghold occupied by the Burning Blade cult. The fortress is located in northwestern Desolace and is now led by Kohor. While they have lost the Hand of Iruxos years ago, they found a way to summon a very powerful demon named Nazargen. If summoned too soon though, he would be weak enough to be dealt with.\n\nThe fortress is made up of a stronghold, a barracks, a cave and several watch towers.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["thunks abode"] = {
			name = "Thunk's Abode",
			short = "Thunk's Abode is a camp in northeastern Desolace, northeast of the Cenarion Wildlands and south of Sargeron.",
			full = "Thunk's Abode is a camp in northeastern Desolace, northeast of the Cenarion Wildlands and south of Sargeron. Cenarion Embassador Thunk has set up here under Cenarion Circle's orders to turn the barren surrounding land into prairie. Thunk's Wyvern acts as a flight master.",
			source = "https://warcraft.wiki.gg/wiki/Thunk's_Abode",
		},
		["valley of bones"] = {
			name = "Valley of Bones",
			short = "The Valley of Bones is a crag on the southern edge of Desolace, infested by skeletons and centaur necromancers and haunted by ghosts of the Magram clan.",
			full = "The Valley of Bones is a crag on the southern edge of Desolace, infested by skeletons and centaur necromancers and haunted by ghosts of the Magram clan. Collapsed against the cliff walls are a pair of massive skeletons of unknown origin called the Dead Goliaths.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Valley of Spears",
			short = "The Valley of Spears is a valley in western Desolace where the Maraudine clan of centaur make their home. The entrance to Maraudon is located in the southwestern end of the valley.",
			full = "The Valley of Spears is a valley in western Desolace where the Maraudine clan of centaur make their home. The entrance to Maraudon is located in the southwestern end of the valley. Besides the countless centaur, one can also find the captive Melizza Brimbuzzle here.\n\nOn foot, the valley is only accessible through narrow mountain passes in the south and east.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
		["wicked tunnels"] = {
			name = "Wicked Tunnels",
			short = "The Wicked Tunnels are a portion of the tunnel system leading to Maraudon below Desolace. It consists of two different sections, both accessed from Zaetar's Choice.",
			full = "The Wicked Tunnels are a portion of the tunnel system leading to Maraudon below Desolace. It consists of two different sections, both accessed from Zaetar's Choice. Taking the north tunnel from Zaetar's Choice leads to the upper Wicked Tunnels, a multi-leveled, maze-like tangle of tunnels and bridges filled with glowing purple crystals, earth elementals, and rock borers, and containing an instance portal to the Wicked Grotto in Maraudon. Taking the east tunnel from Zaetar's Choice through Earth Song Gate leads to the lower Wicked Tunnels, a much smaller and more straightforward area containing the instance portal to the Earth Song Falls.",
			source = "https://warcraft.wiki.gg/wiki/Wicked_Tunnels",
		},
		["zaetars choice"] = {
			name = "Zaetar's Choice",
			short = "Zaetar's Choice is a crossroads in the tunnels leading to Maraudon below Desolace. Here, the tunnel splits into three paths, each containing a portal to a different section of the Maraudon dungeon:",
			full = "Zaetar's Choice is a crossroads in the tunnels leading to Maraudon below Desolace. Here, the tunnel splits into three paths, each containing a portal to a different section of the Maraudon dungeon:\n\nThe left path, with purple crystals, leads through the upper Wicked Tunnels to the Wicked Grotto.\n\nThe middle path, with two statues, leads through Earth Song Gate and the lower Wicked Tunnels to Earth Song Falls.\n\nThe right path, with orange crystals, leads through the Foulspore Pools to Foulspore Cavern.\n\nThe area is named after Zaetar, the centaur forefather.",
			source = "https://warcraft.wiki.gg/wiki/Zaetar's_Choice",
		},
	},
	-- Feralas: 47 subzones
	[1444] = {
		["broken commons"] = {
			name = "Broken Commons",
			short = "The Broken Commons is an area of Dire Maul located just beyond Eldreth Row. This is where each quarter entrance can be found: To the east Warpwood Quarter, to the west Capital Gardens, and to the north Gordok Commons.",
			full = "The Broken Commons is an area of Dire Maul located just beyond Eldreth Row. This is where each quarter entrance can be found: To the east Warpwood Quarter, to the west Capital Gardens, and to the north Gordok Commons. In the center is The Maul, Dire Maul's arena.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Commons",
		},
		["camp ataya"] = {
			name = "Camp Ataya",
			short = "Camp Ataya is a small tauren settlement located in the shade of the Twin Colossals in Feralas.",
			full = "Camp Ataya is a small tauren settlement located in the shade of the Twin Colossals in Feralas.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nAs a response, the Horde Council sent Belgrom Rockmaul for aid.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Ataya",
		},
		["camp mojache"] = {
			name = "Camp Mojache",
			short = "Camp Mojache is a tauren village in eastern Feralas overlooking the scenic Wildwind Lake. The camp straddles a swift-flowing stream that feeds the lake.",
			full = "Camp Mojache is a tauren village in eastern Feralas overlooking the scenic Wildwind Lake. The camp straddles a swift-flowing stream that feeds the lake. Tauren refugees have started flooding into the village from Thousand Needles, mostly from Freewind Post, due to the destruction.\n\nThe camp is known for its thick hides and courageous braves offering travelers protection against the dangers of Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["camp mojache longhouse"] = {
			name = "Camp Mojache Longhouse",
			short = "Camp Mojache Longhouse is an inn located in Camp Mojache in Feralas.",
			full = "Camp Mojache Longhouse is an inn located in Camp Mojache in Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache_Longhouse",
		},
		["capital gardens"] = {
			name = "Capital Gardens",
			short = "The Capital Gardens are the western instance in Dire Maul. The area might once have been a pristine city park district, but now the trees stand gray and withered, and the broken streets are full of dangerous ancients.",
			full = "The Capital Gardens are the western instance in Dire Maul. The area might once have been a pristine city park district, but now the trees stand gray and withered, and the broken streets are full of dangerous ancients.\n\nMost Highborne lived here until their defeat and escape from Dire Maul.",
			source = "https://warcraft.wiki.gg/wiki/Capital_Gardens",
		},
		["darkmist ruins"] = {
			name = "Darkmist Ruins",
			short = "The Darkmist Ruins are Highborne ruins located south of Woodpaw Den in Feralas. The ruins are currently inhabited by Highborne Poltergeist.",
			full = "The Darkmist Ruins are Highborne ruins located south of Woodpaw Den in Feralas. The ruins are currently inhabited by Highborne Poltergeist.\n\nThe ruins, which are located on top a mountain, can be accessed through the Woodpaw Den from the north, Woodpaw Hills from the east, or Ruins of Isildien from the west.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Ruins",
		},
		["dire maul"] = {
			name = "Dire Maul",
			short = "Dire Maul is a three-wing instance found in north-central Feralas. It was once a proud Highborne city called Eldre'Thalas (or Eldre'thalas), but now lies in ruins, overrun by ogres, satyrs, and undead.",
			full = "Dire Maul is a three-wing instance found in north-central Feralas. It was once a proud Highborne city called Eldre'Thalas (or Eldre'thalas), but now lies in ruins, overrun by ogres, satyrs, and undead. Only a tiny remnant of the original Highborne population remains in the form of a murderous sect called the Shen'dralar. It is comprised of three instances: the Warpwood Quarter, the Capital Gardens, and the Gordok Commons.\n\nThe sub-region of Dire Maul plays host to two night elf archaeology dig sites: the Broken Commons Digsite and the Dire Maul Digsite.\n\nThe ruins stand strong because of an ancient crafting technique that bound arcane energy within the stone.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Dream Bough",
			short = "Dream Bough is a Great Tree found on a small island in the middle of Jademir Lake in northern Feralas. This is the location of one of the portals to the Emerald Dream and guarded by the Green dragonflight.",
			full = "Dream Bough is a Great Tree found on a small island in the middle of Jademir Lake in northern Feralas. This is the location of one of the portals to the Emerald Dream and guarded by the Green dragonflight.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["dreamers rest"] = {
			name = "Dreamer's Rest",
			short = "Dreamer's Rest is a small camp located south of Oneiros, on the eastern side of the Twin Colossals in Feralas. Overseen by the Druids of the Talon, it offers many facilities for an outpost of its size.",
			full = "Dreamer's Rest is a small camp located south of Oneiros, on the eastern side of the Twin Colossals in Feralas. Overseen by the Druids of the Talon, it offers many facilities for an outpost of its size.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nThe disrupted memories of its ancients was what caused Thrall to subsequently journey to the Caverns of Time in order to find out exactly who or what was interfering with history.",
			source = "https://warcraft.wiki.gg/wiki/Dreamer's_Rest",
		},
		["eldreth row"] = {
			name = "Eldreth Row",
			short = "Eldreth Row is the outermost area of Dire Maul, located outside the instance portals and before the Broken Commons.",
			full = "Eldreth Row is the outermost area of Dire Maul, located outside the instance portals and before the Broken Commons. It is a tall section of halls that makes up the front section of Eldre'Thalas, now partially ruined and overgrown. Numerous Gordunni ogres patrol the area. The Dire Pool is located on the far western side, while one of the entrances to the Warpwood Quarter is on the far eastern side.",
			source = "https://warcraft.wiki.gg/wiki/Eldreth_Row",
		},
		["emerald summit"] = {
			name = "Emerald Summit",
			short = "The Emerald Summit is a high stone plateau just off the main road from Camp Mojache in the Lower Wilds of Feralas.",
			full = "The Emerald Summit is a high stone plateau just off the main road from Camp Mojache in the Lower Wilds of Feralas.\n\nA formerly corrupted member of the green dragonflight, Ysondre, calls heroes here to aid her in killing the last of the Dragons of Nightmare, Taerar.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Summit",
		},
		["feathermoon stronghold"] = {
			name = "Feathermoon Stronghold",
			short = "Feathermoon Stronghold was the name of the night elf island fortress located off the western coast of Feralas on Sardor Isle on the continent of Kalimdor.",
			full = "Feathermoon Stronghold was the name of the night elf island fortress located off the western coast of Feralas on Sardor Isle on the continent of Kalimdor. It had a hippogryph point and could be reached from Auberdine, Nijel's Point and Thalanaar. The stronghold was established by General Shandris Feathermoon, who for the past ten thousand years has been Tyrande Whisperwind's right hand in the Sentinels.\n\nFeathermoon was most easily accessible by a boat taken from Feralas in the Forgotten Coast to an island dock, though many Alliance players who didn't like to wait for the boat preferred to swim.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feathermoon stronghold classic"] = {
			name = "Feathermoon Stronghold",
			short = "Feathermoon Stronghold was the name of the night elf island fortress located off the western coast of Feralas on Sardor Isle on the continent of Kalimdor.",
			full = "Feathermoon Stronghold was the name of the night elf island fortress located off the western coast of Feralas on Sardor Isle on the continent of Kalimdor. It had a hippogryph point and could be reached from Auberdine, Nijel's Point and Thalanaar. The stronghold was established by General Shandris Feathermoon, who for the past ten thousand years has been Tyrande Whisperwind's right hand in the Sentinels.\n\nFeathermoon was most easily accessible by a boat taken from Feralas in the Forgotten Coast to an island dock, though many Alliance players who didn't like to wait for the boat preferred to swim.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Feral Scar Vale",
			short = "Feral Scar Vale is an area belonging to the Feral Scar yeti in the High Wilderness of western Feralas.",
			full = "Feral Scar Vale is an area belonging to the Feral Scar yeti in the High Wilderness of western Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "Forgotten Coast",
			short = "The Forgotten Coast is the coast that makes up the entire border of western Feralas with the Veiled Sea. Here several water elementals and sea giants roam the shore.",
			full = "The Forgotten Coast is the coast that makes up the entire border of western Feralas with the Veiled Sea. Here several water elementals and sea giants roam the shore. Zorbin Fandazzle can be found at the fork in the main road that leads to the coast, through the new Feathermoon Stronghold. There is another path further north that is safer for the Horde to enter the coast with.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nThere is also a murloc fishing village. Sometimes, birds used to swoop in and carry off tadpoles, or it would be attacked by humans or gnolls. The Gordunni ogres were raiding the coast for years and taking several of the murlocs and others captive into Dire Maul. The Gordunni ogres had taken a dozen or so to Dire Maul, including Murrl and Murrgly.\n\nThe captive murlocs were eventually freed from Dire Maul by Aramar Thorne and his friends, with Wuul Breezerider and an ogre girl escorting them out of the ruined city back home.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Frayfeather Highlands",
			short = "The Frayfeather Highlands are the territory of the Frayfeather hippogryphs.",
			full = "The Frayfeather Highlands are the territory of the Frayfeather hippogryphs. Deep into the Frayfeather Highlands, one can find nests containing Hippogryph Eggs to bring back to Gadgetzan's Super Egg-O-Matic machine for inspection.\n\nThe hippogryphs are named after the highlands.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordok commons"] = {
			name = "Gordok Commons",
			short = "The Gordok Commons are the northern instance in Dire Maul. This area of the city has been taken over by the Gordok, the elite members of the Gordunni ogre clan, and are now the seat of power for King Gordok himself.",
			full = "The Gordok Commons are the northern instance in Dire Maul. This area of the city has been taken over by the Gordok, the elite members of the Gordunni ogre clan, and are now the seat of power for King Gordok himself. By tradition, however, whoever slays the king will become the new King Gordok.",
			source = "https://warcraft.wiki.gg/wiki/Gordok_Commons",
		},
		["gordunni outpost"] = {
			name = "Gordunni Outpost",
			short = "The Gordunni Outpost is an area in the mountains north of Lariss Pavilion currently held by the Gordunni ogres. Their presence has wilted the normally verdant plant life of Feralas into a withered brown.",
			full = "The Gordunni Outpost is an area in the mountains north of Lariss Pavilion currently held by the Gordunni ogres. Their presence has wilted the normally verdant plant life of Feralas into a withered brown.\n\nThe hills have two caves, a small one towards the entrance and an ogre mound at the back of the area. Near the back cave is a captured sasquatch, Bigfist.\n\nGordunni Hillguards, Gordunni Channelers and Gordunni Tamers roam the area.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Grimtotem Compound",
			short = "The Grimtotem Compound is a large village, made of two areas, east of Dire Maul in Feralas. As the name implies, it is here Grimtotem tauren make one of their homes.",
			full = "The Grimtotem Compound is a large village, made of two areas, east of Dire Maul in Feralas. As the name implies, it is here Grimtotem tauren make one of their homes. In the southern section a large cage contains several imprisoned Sprite Darters.\n\nEast of the northern section are a few gnoll camps.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "High Wilderness",
			short = "The High Wilderness is a vast forest that stretches from the Forgotten Coast to Verdantis River in western Feralas.",
			full = "The High Wilderness is a vast forest that stretches from the Forgotten Coast to Verdantis River in western Feralas. Many creatures can be found in this forest, including but not limited to: bears, wolves, hippogryphs, yetis, treants, and ogres.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Isle of Dread",
			short = "The Isle of Dread was an island once located off the west coast in Feralas, south of Sardor Isle. It was the home to many level 60-62 elite chimaeras referred to as \"chimaerok\".",
			full = "The Isle of Dread was an island once located off the west coast in Feralas, south of Sardor Isle. It was the home to many level 60-62 elite chimaeras referred to as \"chimaerok\". The chimaeras, along with technically the whole isle, were a part of the Scepter of the Shifting Sands questline which opened the gates of Ahn'Qiraj.\n\nThe chimaeras on the isle consisted of thee types, plus their leader.\n\nArcane Chimaerok\n\nChimaerok\n\nChimaerok Devourer\n\nLord Lakmaeran (leader)\n\nThe three lesser chimaeras dropped Chimaerok Tenderloins which was a quest-objective in [60R] The Isle of Dread!. This quest eventually led to Dirge's Kickin' Chimaerok Chops which gave the player [Recipe: Dirge's Kickin' Chimaerok Chops].\n\nLord Lakmaeran, in addition to also dropping [Chimaerok Tenderloin], also dropped [Lakmaeran's Carcass] which was an objective in the same quest. The carcass was eventually turned into a [500 Pound Chicken] which was gobbled up by the gnome wizard Narain Soothfancy.\n\nThe isle was also the home to a group of naga who dwelled in a cave at the northern end. They were led by Lord Shalzaru, whom players were asked to kill as a quest for the former Feathermoon Stronghold. The cave itself seems to have been completely unique in design and went quite deep. There was a secret underwater passageway that lead into an inner chamber, although it had no apparent special uses besides being the location in which Lady Szallah resided. The only entrance to the central valley was in the southeastern part of the island, from all other sides the central valley was inaccessible due to unyielding cliffs.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Jademir Lake",
			short = "Jademir Lake is a medium sized lake in northern Feralas with a small island, Dream Bough, at its center. Dream Bough contains a portal to the Emerald Dream, guarded by Lethlas and several green dragonspawn.",
			full = "Jademir Lake is a medium sized lake in northern Feralas with a small island, Dream Bough, at its center. Dream Bough contains a portal to the Emerald Dream, guarded by Lethlas and several green dragonspawn.\n\nInfected green whelps can be found on the northwestern shore.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lake dumont"] = {
			name = "Lake Dumont",
			short = "Lake Dumont is an extremely large lake with an island in northern Feralas, located just north of Dire Maul near the bordering Desolace and can be reached by foot at north-east of Dreamer's Rest.",
			full = "Lake Dumont is an extremely large lake with an island in northern Feralas, located just north of Dire Maul near the bordering Desolace and can be reached by foot at north-east of Dreamer's Rest.\n\nThe island has a ruined mage tower that, judging from the fact it is still burning and the rubble scattered around, some at the bottom of the lake, was probably destroyed not too long ago. There is also a small boat in the lake.\n\nThe isle also houses several seemingly stranded NPCs. All the NPCs are Alliance, however they're friendly to Horde players.\n\nThe north end of the lake contains crumbled night elf ruins. On the shore by the ruins is a path into the mountains of Mulgore. Though the lake extends past the northern border of Feralas, it is still counted as part of Feralas in-game and not part of Desolace.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Dumont",
		},
		["lariss pavilion"] = {
			name = "Lariss Pavilion",
			short = "Lariss Pavilion is a large outdoor night elf style building in Feralas just north of Camp Mojache. The nearby dryads that are usually peaceful have been corrupted by the Emerald Nightmare and now attack anyone.",
			full = "Lariss Pavilion is a large outdoor night elf style building in Feralas just north of Camp Mojache. The nearby dryads that are usually peaceful have been corrupted by the Emerald Nightmare and now attack anyone.\n\nThe Pavilion is home to a mysterious man named Azj'Tordin. Apparently, a Highborne who disagreed with Prince Tortheldrin, he left Dire Maul via means of a backdoor located at the bottom of the Pavilion, but not before an imp by the name of Pusillin stole his book of incantations.\n\nAn orc, Xerash Fireblade, can also be found here.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Lower Wilds",
			short = "The Lower Wilds is the eastern section of Feralas that leads into Thousand Needles. The area in inhabited by treants, corrupted dryads, and Freewind Post Refugees walking the path to Camp Mojache.",
			full = "The Lower Wilds is the eastern section of Feralas that leads into Thousand Needles. The area in inhabited by treants, corrupted dryads, and Freewind Post Refugees walking the path to Camp Mojache.\n\nThe Emerald Summit can be found just east of town along the road. At the far eastern edge of the wilds is New Thalanaar.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["maul subzone"] = {
			name = "Maul (subzone)",
			short = "The Maul (or Dire Maul Arena) is a large pit located outside the three instance wings of Dire Maul in the middle of the Broken Commons.",
			full = "The Maul (or Dire Maul Arena) is a large pit located outside the three instance wings of Dire Maul in the middle of the Broken Commons.\n\nLike the Gurubashi Arena in Stranglethorn Vale, entering the Maul flags players for Free for All PvP and allows them to attack and kill other players in the Maul, regardless of faction, except their party members.\n\nPlayers can enter the Maul either by simply dropping into it or by entering a doorway on the west side of the commons that takes them into a tunnel leading past packs of sleeping Gordok hyenas and finally to the fighting area. The tunnel is the only exit from the Maul. It may be most prudent to enter through the tunnel, since dropping down causes the player to take damage from falling and their opponent may attack them before they have recovered their health.\n\nMushgog\n\nThe Razza\n\nSkarr the Unbreakable",
			source = "https://warcraft.wiki.gg/wiki/Maul_(subzone)",
		},
		["new thalanaar"] = {
			name = "New Thalanaar",
			short = "New Thalanaar is a night elf outpost located in the far east of Feralas, and was built after the original Thalanaar was flooded. It is currently under siege by Grimtotem forces.",
			full = "New Thalanaar is a night elf outpost located in the far east of Feralas, and was built after the original Thalanaar was flooded. It is currently under siege by Grimtotem forces. As a result, Alliance players are quickly asked to make their way out of the war zone to the dock where a boat awaits to take them to Fizzle and Pozzik's Speedbarge. New Thalanaar remained under siege by the Grimtotem for several months.\n\nThere is a one-way trip here from Shadebough via the quest [15-30] To New Thalanaar from Falfindel Waywarder, a refugee from Thalanaar.",
			source = "https://warcraft.wiki.gg/wiki/New_Thalanaar",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "Oneiros is an area south of the Jademir Lake in northern Feralas.",
			full = "Oneiros is an area south of the Jademir Lake in northern Feralas.\n\nWithin the ruins is a small night elf camp, Dreamer's Rest.\n\nA version of the ruins also exists within the Emerald Dream. Here, Nightmare-corrupted dragonkin can be found under the command of Tyrannikus, some of them protecting dragon eggs.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Rage Scar Hold",
			short = "Rage Scar Hold is a dug in cave in Feralas, between Feathermoon Stronghold and Dreamer's Rest. It contains the most vicious yetis in the area.",
			full = "Rage Scar Hold is a dug in cave in Feralas, between Feathermoon Stronghold and Dreamer's Rest. It contains the most vicious yetis in the area.\n\nBooks and symbols within the cave seem to indicate the Yetis are studying this kind of magic unless it was owned by some unfortunate magi in the past.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of feathermoon"] = {
			name = "Ruins of Feathermoon",
			short = "A new Feathermoon Stronghold was built on the mainland, while a number of Feathermoon's forces and Gilnean soldiers remained on the island to fight off the naga.",
			full = "A new Feathermoon Stronghold was built on the mainland, while a number of Feathermoon's forces and Gilnean soldiers remained on the island to fight off the naga.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Feathermoon",
		},
		["ruins of isildien"] = {
			name = "Ruins of Isildien",
			short = "The Ruins of Isildien are the ruins of a large night elven city in southwestern Feralas. The Gordunni ogres have made the ruins their home.",
			full = "The Ruins of Isildien are the ruins of a large night elven city in southwestern Feralas. The Gordunni ogres have made the ruins their home. It was destroyed 10,000 years ago.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruins of Ravenwind",
			short = "The Ruins of Ravenwind are the remains of an ancient Kaldorei civilization in northern Feralas, specifically the Highborne (much like Dire Maul).",
			full = "The Ruins of Ravenwind are the remains of an ancient Kaldorei civilization in northern Feralas, specifically the Highborne (much like Dire Maul). It is currently overrun with Northspring harpies.\n\nA version of the ruins also exists within the Emerald Dream. Here, harpies can also be found under the command of their queen Slirena.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruins of Solarsal",
			short = "The Ruins of Solarsal are some night elven ruins southwest of the destroyed Feathermoon Stronghold in Sardor Isle. Hatecrest naga inhabit the grounds.",
			full = "The Ruins of Solarsal are some night elven ruins southwest of the destroyed Feathermoon Stronghold in Sardor Isle. Hatecrest naga inhabit the grounds.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Sardor Isle",
			short = "Sardor Isle is an island located west of mainland Feralas, north of the now sunken Isle of Dread. It was previously the location of Feathermoon Stronghold, a night elven village led by Shandris Feathermoon.",
			full = "Sardor Isle is an island located west of mainland Feralas, north of the now sunken Isle of Dread. It was previously the location of Feathermoon Stronghold, a night elven village led by Shandris Feathermoon. It was also inhabited by several naga and a pack of wolves.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shadebough"] = {
			name = "Shadebough",
			short = "Shadebough is a small camp located northeast of the Writhing Deep in the Lower Wilds of Feralas and under the leadership of Adella.",
			full = "Shadebough is a small camp located northeast of the Writhing Deep in the Lower Wilds of Feralas and under the leadership of Adella. It is worth noting that unlike other Alliance camps this one forces you to ride through gnoll infested lands to reach the camp.",
			source = "https://warcraft.wiki.gg/wiki/Shadebough",
		},
		["shalzarus lair"] = {
			name = "Shalzaru's Lair",
			short = "A large, twisting naga lair south of Feathermoon Stronghold's island at the northern end of the Isle of Dread. The master of the Hatecrest, Shalzaru, dwells deep inside.",
			full = "A large, twisting naga lair south of Feathermoon Stronghold's island at the northern end of the Isle of Dread. The master of the Hatecrest, Shalzaru, dwells deep inside.\n\nThe cave consists of a main cave and a smaller cave. They are connected by a waterway. The cave is filled with Hatecrest Sorceresses and Hatecrest Serpent Guards.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["steam pools"] = {
			name = "Steam Pools",
			short = "The Steam Pools is an area in southern Feralas, high in the mountains bordering Silithus, with a large lake at its base and smaller steaming hot pools found further up along the mountain side.",
			full = "The Steam Pools is an area in southern Feralas, high in the mountains bordering Silithus, with a large lake at its base and smaller steaming hot pools found further up along the mountain side. It houses a holiday resort for the rich, run by Gadgetzan.",
			source = "https://warcraft.wiki.gg/wiki/Steam_Pools",
		},
		["stonemaul hold"] = {
			name = "Stonemaul Hold",
			short = "Stonemaul Hold is a fortified ogre mound outpost located southwest of Dire Maul in Feralas. The outpost is led by Orhan Ogreblade, leader of the Stonemaul clan in the area.",
			full = "Stonemaul Hold is a fortified ogre mound outpost located southwest of Dire Maul in Feralas. The outpost is led by Orhan Ogreblade, leader of the Stonemaul clan in the area.\n\nIt's from here that Orhan uses the Stonemauls to help bring the Gordunni ogres down so that the Horde can use the resources that the Gordunni waste.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Hold",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "The outpost had very little to offer in the way of goods and services, although it was the location for the Tribal Leatherworking trainer Caryssia Moonhunter and had a flight path that could be reached from Feathermoon Stronghold, Theramore Isle, and Gadgetzan.",
			full = "The outpost had very little to offer in the way of goods and services, although it was the location for the Tribal Leatherworking trainer Caryssia Moonhunter and had a flight path that could be reached from Feathermoon Stronghold, Theramore Isle, and Gadgetzan.\n\nNew Thalanaar was constructed immediately to the west.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["tower of estulan"] = {
			name = "Tower of Estulan",
			short = "Tower of Estulan is a mage tower located south of Dire Maul in Feralas, and is led by Estulan. The tower and its camp serves as an academy, training the next generation of Highborne mages.",
			full = "Tower of Estulan is a mage tower located south of Dire Maul in Feralas, and is led by Estulan. The tower and its camp serves as an academy, training the next generation of Highborne mages. It notably contains an Arcane Ancient named Arcosin.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Estulan",
		},
		["twin colossals"] = {
			name = "Twin Colossals",
			short = "The Twin Colossals (a.k.a. Twin Colossi) are a pair of high vertical mountains, rising up on the west side of Feralas, and are the highest point in the whole area.",
			full = "The Twin Colossals (a.k.a. Twin Colossi) are a pair of high vertical mountains, rising up on the west side of Feralas, and are the highest point in the whole area. The road from Feralas to Desolace runs between these two mountains. The two mesas are one of the most striking landmarks of the area and inspire awe in whoever beholds them.\n\nGregan Brewspewer witnessed a giant makura named Diamond Head claw its way up the top of the eastern mountain. He can now be found there in a small but deep pond.\n\nThis teleport is now offered for free to Alliance characters by Telaron Windflight in Dreamer's Rest at the bottom of the pillar, but the Horde can only access it via flying mounts.\n\nAt the top, there is a good view of the surrounding area, a small lake where one can fish, and a night elf male, Kalin Windflight, who sells [Colossal Parachute] which enables the player to safely leave the mountain for 20 silver each.\n\nA version of the mountains also exists within the Emerald Dream. Here, Nightmare-corrupted Children of Cenarius can be found under the command of Alondrius, preparing for battle against an unknown enemy.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Verdantis River",
			short = "The Verdantis River is a small river weaving through central Feralas just southeast of Dire Maul. This area is the only place in the world to catch [Feralas Ahi].",
			full = "The Verdantis River is a small river weaving through central Feralas just southeast of Dire Maul. This area is the only place in the world to catch [Feralas Ahi].",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["warpwood quarter"] = {
			name = "Warpwood Quarter",
			short = "The Warpwood Quarter is the eastern instance in Dire Maul. It has been taken over by the nefarious Alzzin the Wildshaper, a satyr who has corrupted the Fruit of Fertility so that it produces vile Felvine Shards.",
			full = "The Warpwood Quarter is the eastern instance in Dire Maul. It has been taken over by the nefarious Alzzin the Wildshaper, a satyr who has corrupted the Fruit of Fertility so that it produces vile Felvine Shards. Alzzin has attracted all manner of corrupted plant life, satyrs, mages and demons to his cause. The entire district is overgrown with crazed plant life.\n\nThe main instance portal can be found in the Broken Commons of Dire Maul, but a hidden back entrance is located beneath the Lariss Pavilion in eastern Feralas. This back door can only be accessed with the [Crescent Key].\n\nThe area is so named for its numerous Warpwood ancients, but it also contains many lashers, as well as the annoying imp Pusillin, who will set off on a wild chase through the entire area, and eventually into the Hidden Reach. The Conservatory lies in the middle of the quarter, and dropping down from the edge is safe as long as there are no aggressive mobs at the bottom, and the jumper is at full health.",
			source = "https://warcraft.wiki.gg/wiki/Warpwood_Quarter",
		},
		["wildwind lake"] = {
			name = "Wildwind Lake",
			short = "Wildwind Lake is a stretch of water near Camp Mojache in the region of Feralas.",
			full = "Wildwind Lake is a stretch of water near Camp Mojache in the region of Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Woodpaw Den",
			short = "Woodpaw Den is an area of Feralas which is heavily populated by the Woodpaw Alphas of the Woodpaw gnolls.",
			full = "Woodpaw Den is an area of Feralas which is heavily populated by the Woodpaw Alphas of the Woodpaw gnolls.\n\nSouth of the den is the Darkmist Ruins.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Woodpaw Hills",
			short = "The Woodpaw Hills is a forest in southeastern Feralas.",
			full = "The Woodpaw Hills is a forest in southeastern Feralas. It's here the gnolls of the Woodpaw clan make their home, however, they're being driven out by the \"bugs\" that have burst through the ground in the southeasternmost area of the hills in an area now called the Writhing Deep.\n\nRecently mountain giants have arrived in the area, although [15-30] Mountain Giant Muisek states they came down from the mountains to aid the night elves when the Burning Legion attacked. These giants, unlike the Cliff Giants in the west are hostile to the Horde.\n\nThe Woodpaw Alphas that lead the tribe were once found in the camps, they can now be found only in the Woodpaw Den.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Writhing Deep",
			short = "The Writhing Deep is the site of the Hive Zukk'ash silithid infestation in southeastern Feralas.",
			full = "The Writhing Deep is the site of the Hive Zukk'ash silithid infestation in southeastern Feralas. The Zukk'ash silithid are driving the nearby gnolls into a frenzy, which is causing them to try and head north, attacking Camp Mojache.\n\nHelp from Camp Mojache squashed the insects around the hive, but the silithid and their countless eggs remain protected within. According to Rexxar, it is only a matter of time before the next generation of silithid hatches.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Dustwallow Marsh: 30 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Alcaz Island",
			short = "Alcaz Island is a large island off the northeast coast of Dustwallow Marsh. Unlike the rest of the zone, it features tropical vegetation similar to the nearby Echo Isles.",
			full = "Alcaz Island is a large island off the northeast coast of Dustwallow Marsh. Unlike the rest of the zone, it features tropical vegetation similar to the nearby Echo Isles. It is inhabited mostly by gnomes raised into undeath, and technological inventions led by Doctor Weavil. The island was once under the control of the Strashaz naga.\n\nAfter the Theramore's Fall scenario, Alcaz Island becomes deserted, and can be accessed again by speaking to Zidormi.\n\nIt is a no-fly zone and nearing it on a flying mount automatically dismounts the character, alongside the message \"You are hit with anti-aircraft gunfire!\"",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Beezil's Wreck",
			short = "Beezil's Wreck is a goblin zeppelin that has crashed in the deepest parts of Dustwallow Marsh, east of Tabetha's Farm.",
			full = "Beezil's Wreck is a goblin zeppelin that has crashed in the deepest parts of Dustwallow Marsh, east of Tabetha's Farm. The zeppelin was carrying a shipment of supplies south, and is frequently sought out by adventurers looking for Seaforium Boosters.\n\nHe can now be found at Light's Hope Chapel.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["blackhoof village"] = {
			name = "Blackhoof Village",
			short = "Blackhoof Village is a Grimtotem tribe village located in the northern part of the Dustwallow Marsh.",
			full = "Blackhoof Village is a Grimtotem tribe village located in the northern part of the Dustwallow Marsh. The outpost holds captured Theramore Guards just waiting for a friendly face, as well as containing the secret of who burned down Shady Rest Inn.",
			source = "https://warcraft.wiki.gg/wiki/Blackhoof_Village",
		},
		["bloodfen burrow"] = {
			name = "Bloodfen Burrow",
			short = "Bloodfen Burrow is a cave in south-western Dustwallow Marsh where a highly concentrated number of Bloodfen raptors have come to nest.",
			full = "Bloodfen Burrow is a cave in south-western Dustwallow Marsh where a highly concentrated number of Bloodfen raptors have come to nest. Upon close inspection, the remnants of some sort of settlement can be seen just outside the cave, torn apart by the ravenous dinosaurs. One part of Cortello's Riddle can be found here.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Bluefen",
			short = "Bluefen is a marshy area located on northern Dustwallow Marsh, in between Brackenwall Village and Blackhoof Village. It is overran with spiders, birds, raptors, crocolisks, and Theramore Infiltrators.",
			full = "Bluefen is a marshy area located on northern Dustwallow Marsh, in between Brackenwall Village and Blackhoof Village. It is overran with spiders, birds, raptors, crocolisks, and Theramore Infiltrators.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Brackenwall Village",
			short = "Brackenwall Village is a small Horde-affiliated outpost in northwest Dustwallow Marsh. It is run and populated mainly by the Stonemaul ogres.",
			full = "Brackenwall Village is a small Horde-affiliated outpost in northwest Dustwallow Marsh. It is run and populated mainly by the Stonemaul ogres. Besides a few huts, the village also counts an ogre mound.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Darkmist Cavern",
			short = "Darkmist Cavern is the name for a small mine in northwest Dustwallow Marsh that has become completely overrun with the terrifyingly large Darkmist Spiders.",
			full = "Darkmist Cavern is the name for a small mine in northwest Dustwallow Marsh that has become completely overrun with the terrifyingly large Darkmist Spiders. The inhabitants of Dustwallow can't seem to agree on whether the spiders were named after the cavern or if it's the other way around. There are ruins of small houses outside the mine, suggesting there might have previously been a small settlement there.\n\n\"Swamp Eye\" Jarl sends adventurers here in order to collect spider eyes for some soup.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Den of Flame",
			short = "The Den of Flame is an area in Dustwallow Marsh, just west of the Stonemaul Ruins that has been completely overrun by dragonkin of the black dragonflight, presumably under the orders of the great black dragon Onyxia, who resides nearby.",
			full = "The Den of Flame is an area in Dustwallow Marsh, just west of the Stonemaul Ruins that has been completely overrun by dragonkin of the black dragonflight, presumably under the orders of the great black dragon Onyxia, who resides nearby. The structure was built by the Stonemaul ogres to be their ogre mound, as the architecture in the area corroborates, and as such it still contains the [Stonemaul Banner] required by [15-30] Banner of the Stonemaul.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["direhorn post"] = {
			name = "Direhorn Post",
			short = "Direhorn Post is a camp full of hostile Grimtotem tauren, north of Tabetha's Farm in the Quagmire of Dustwallow Marsh.",
			full = "Direhorn Post is a camp full of hostile Grimtotem tauren, north of Tabetha's Farm in the Quagmire of Dustwallow Marsh.\n\nApothecary Cylla drops a [Sealed Letter] which starts The Apothecary's Letter or Signs of Treachery?.",
			source = "https://warcraft.wiki.gg/wiki/Direhorn_Post",
		},
		["dragonmurk"] = {
			name = "Dragonmurk",
			short = "The Dragonmurk is a section of southern Dustwallow Marsh where dragon whelps and dragonspawn of the black dragonflight are very prolific.",
			full = "The Dragonmurk is a section of southern Dustwallow Marsh where dragon whelps and dragonspawn of the black dragonflight are very prolific. Surrounded by the Dragonmurk are the Den of Flame and the Stonemaul Ruins, both of which are also inhabited by black dragonspawn.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Dreadmurk Shore",
			short = "Dreadmurk Shore is the name of the coastline and islands of Dustwallow Marsh between Theramore Isle and Northwatch Hold of the Barrens.",
			full = "Dreadmurk Shore is the name of the coastline and islands of Dustwallow Marsh between Theramore Isle and Northwatch Hold of the Barrens. It is heavily infested by the Mirefin murloc tribe. The waters are home to sea turtles and other sea creatures. The Defias have also recently suffered a shipwreck somewhere between Dreadmurk and Alcaz and have set up camp on a few islands and the beach near them.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Dustwallow Bay",
			short = "Dustwallow Bay is a portion of the Great Sea off the eastern coast of central Kalimdor, mostly noted by travelers on the eastern coast of the Dustwallow Marsh west of Theramore Isle.",
			full = "Dustwallow Bay is a portion of the Great Sea off the eastern coast of central Kalimdor, mostly noted by travelers on the eastern coast of the Dustwallow Marsh west of Theramore Isle. Nat Pagle the noted fisherman is located on an island just off the bay in Tidefury Cove.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Emberstrife's Den",
			short = "Emberstrife's Den is a sizable cave in the Wyrmbog region of southern Dustwallow Marsh.",
			full = "Emberstrife's Den is a sizable cave in the Wyrmbog region of southern Dustwallow Marsh. It is the home of the Black drake Emberstrife, who puts young black dragonlings through vigorous tests in order to become esteemed enough to enter Onyxia's Lair.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Foothold Citadel",
			short = "Foothold Citadel was an Alliance barracks within Theramore Isle. It was the headquarters of the Theramore Guard, and the location of some military personnel as well as several vendors.",
			full = "Foothold Citadel was an Alliance barracks within Theramore Isle. It was the headquarters of the Theramore Guard, and the location of some military personnel as well as several vendors.\n\nDaelin Proudmoore died in battle in this keep when Thrall's forces stormed Theramore, led by Rexxar and his friends.\n\nYears later, the citadel was destroyed when the mana bomb destroyed Theramore.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["jewelhammers vault"] = {
			name = "Jewelhammer's Vault",
			short = "Jewelhammer's Vault is a titan observatory located underneath Alcaz Island in Dustwallow Marsh. The entrance is underwater at .",
			full = "Jewelhammer's Vault is a titan observatory located underneath Alcaz Island in Dustwallow Marsh. The entrance is underwater at . It is here that a Vault Guardian guards the Jewelhammer's Chest, which contains [The Missing Chapter].",
			source = "https://warcraft.wiki.gg/wiki/Jewelhammer's_Vault",
		},
		["lost point"] = {
			name = "Lost Point",
			short = "Lost Point is a run-down, decrepit scout tower built by the humans of Theramore. It is located in western Dustwallow Marsh, and is currently inhabited by Theramore deserters.",
			full = "Lost Point is a run-down, decrepit scout tower built by the humans of Theramore. It is located in western Dustwallow Marsh, and is currently inhabited by Theramore deserters. Balos Jacken is these deserters' leader, and has information about Private Hendel's part in the kidnapping of a very important personality.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["mudsprocket"] = {
			name = "Mudsprocket",
			short = "Mudsprocket is a goblin town in the south-west of Dustwallow Marsh. It is a quest hub with a flight master, inn, graveyard, anvil, forge and mailbox.",
			full = "Mudsprocket is a goblin town in the south-west of Dustwallow Marsh. It is a quest hub with a flight master, inn, graveyard, anvil, forge and mailbox. This town's faction is tied with Gadgetzan and it contains a goblin laboratory.",
			source = "https://warcraft.wiki.gg/wiki/Mudsprocket",
		},
		["nats landing"] = {
			name = "Nat's Landing",
			short = "Nat's Landing is the name of Nat Pagle's newly renovated fishing spot in the Dustwallow Bay of Dustwallow Marsh.",
			full = "Nat's Landing is the name of Nat Pagle's newly renovated fishing spot in the Dustwallow Bay of Dustwallow Marsh. It features a tent for shelter, a couple of fish racks to hang catches from, some rods and reels below a lantern nailed to a tree, and a small rickety dock from which Nat fishes.",
			source = "https://warcraft.wiki.gg/wiki/Nat's_Landing",
		},
		["north point tower"] = {
			name = "North Point Tower",
			short = "North Point Tower was built by Theramore in northern Dustwallow Marsh, near a well-traveled stretch of road. It is staffed by a sizable contingent of Theramore Guards who have imprisoned a blood elf of the Horde here.",
			full = "North Point Tower was built by Theramore in northern Dustwallow Marsh, near a well-traveled stretch of road. It is staffed by a sizable contingent of Theramore Guards who have imprisoned a blood elf of the Horde here. The prisoner has a friend in Brackenwall Village who pleads passerbies to rescue her.\n\nThe scout tower is the most distant of Theramore's outpost since the deserters took over Lost Point.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Onyxia's Lair",
			short = "Onyxia's Lair is a level 80 raid dungeon located in the Wyrmbog, Dustwallow Marsh. It is home to Onyxia, the brood mother of the black dragonflight.",
			full = "Onyxia's Lair is a level 80 raid dungeon located in the Wyrmbog, Dustwallow Marsh. It is home to Onyxia, the brood mother of the black dragonflight.\n\nOnyxia's Lair was originally a level 60, 40-player raid dungeon, one of two that were available upon release of World of Warcraft (the other being Molten Core).",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "Quagmire",
			short = "The Quagmire is the name given to a large section of marshland located in central Dustwallow Marsh.",
			full = "The Quagmire is the name given to a large section of marshland located in central Dustwallow Marsh. It stretches from Lost Point in the west to Dustwallow Bay in the east, and from Brackenwall Village in the north to the Dragonmurk in the south. Beezil's Wreck, Direhorn Post, and Tabetha's Farm are also located within the Quagmire. It is inhabited by dangerous crocolisks, Grimtotem Clan tauren, spiders and oozes that live throughout the region.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Sentry Point",
			short = "Sentry Point is a scout tower built by Theramore and located on the mainland of Dustwallow Marsh just across the bridge from the citadel itself.",
			full = "Sentry Point is a scout tower built by Theramore and located on the mainland of Dustwallow Marsh just across the bridge from the citadel itself. The tower acts as its name suggests, watching the comings and goings on the road to Theramore. The point was once attacked by elementals sent by Cho'gall.\n\nDespite this, it is not destroyed in World of Warcraft.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Shady Rest Inn",
			short = "The Shady Rest Inn (or simply Shady Rest) was a human-built inn near the border between Dustwallow Marsh and the Southern Barrens.",
			full = "The Shady Rest Inn (or simply Shady Rest) was a human-built inn near the border between Dustwallow Marsh and the Southern Barrens.\n\nSome time ago it was mysteriously burned to the ground. Paval Reethe as well as possibly Lieutenant Caldwell were implicated by investigating agents, but both were killed before they could reveal the truth of who was behind the attack. James Hyal ran the inn at the time of the attack and his wife and child were killed in the blaze. Since then, James has been traumatized by the incident.\n\nAdventurers would later learn the truth behind the burning of the Shady Rest Inn by completing a quest chain, learning that it was the Grimtotem tauren who were responsible for burning down the building.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Stonemaul Ruins",
			short = "The Stonemaul Ruins (previously known as Stonemaul Village) are the former home of the Stonemaul ogres. The ruins are located within Dragonmurk and are currently infested with Firemane dragonspawn.",
			full = "The Stonemaul Ruins (previously known as Stonemaul Village) are the former home of the Stonemaul ogres. The ruins are located within Dragonmurk and are currently infested with Firemane dragonspawn.\n\nThis section concerns content related to Warcraft III: Reign of Chaos or its expansion The Frozen Throne.\n\nSometime after their arrival in Kalimdor, the Stonemaul clan established Stonemaul Village within Dustwallow Marsh.\n\nAfter Kor'gall came into possession of the ancient orcish axe, Serathil, he seized control of the clan, ruling the village with brutality and mercilessness. Crol'ka, whose brothers had been killed by Kor'gall, recognized that the warlord was leading the clan to ruin and barely escaped the village with his life. In time, Crol'ka was found by a Darkspear patrol and requested help for the Stonemaul.\n\nAs the Darkspear tended to Crol'ka, Rexxar and his companions made their way to Stonemaul Village. However, upon their arrival, they were barred entry and forced to fight their way in. Acknowledging Rexxar's strength, Kor'gall agreed to let him join the Stonemaul -- if he survived the Gauntlet, a valley full of deadly beasts, thus completing the Trial of Strength. Rexxar and his companions endured the Gauntlet, and upon their return to the village, an impressed Kor'gall allowed him to join the clan. After Kor'gall refused to aid the Horde, Rexxar challenged him for leadership of the Stonemaul, ultimately killing him and assuming control. At Rexxar's command, the Stonemaul joined the war against the kingdom of Kul Tiras.\n\nFollowing the conflict's end, Rexxar appointed Mok'Morokk as the Stonemaul's new leader and departed. However, after Rexxar's departure, Mok'Morokk fell prey to the temptations of power. Rather than lead, he demanded. He did not serve his people or the village; instead, he expected them to serve him.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Swamplight Manor",
			short = "Swamplight Manor is a small house located in the Witch Hill region of Dustwallow Marsh. It is home to the famous cook, \"Swamp Eye\" Jarl.",
			full = "Swamplight Manor is a small house located in the Witch Hill region of Dustwallow Marsh. It is home to the famous cook, \"Swamp Eye\" Jarl. In the small garden outside the \"manor\", there is a pile of dirt that contains the buried report of an orcish spy. Alliance characters turn this in to Captain Garran Vimes and Horde characters can turn it in to Nazeer Bloodpike.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["tabethas farm"] = {
			name = "Tabetha's Farm",
			short = "Tabetha's Farm (aka Tabetha's hut) is a small hut with a garden located in the murkiest part of the Quagmire in Dustwallow Marsh.",
			full = "Tabetha's Farm (aka Tabetha's hut) is a small hut with a garden located in the murkiest part of the Quagmire in Dustwallow Marsh. Tabetha herself is present in the building along with her two apprentices Garion and Morlann. She also has a dock to host those who navigate the waters of the swamp by riverboat. Andello Porter of SI:7 can be found here.",
			source = "https://warcraft.wiki.gg/wiki/Tabetha's_Farm",
		},
		["theramore isle"] = {
			name = "Theramore Isle",
			short = "Theramore Isle (a.k.a. Theramore Keep, Theramore City or simply Theramore) was a human city and port town located in a rocky island east of Dustwallow Marsh, as well as the capital of the eponymous city-state/kingdom.",
			full = "Theramore Isle (a.k.a. Theramore Keep, Theramore City or simply Theramore) was a human city and port town located in a rocky island east of Dustwallow Marsh, as well as the capital of the eponymous city-state/kingdom. Before its destruction, it was considered the Alliance's most martial presence in Kalimdor. Since its destruction, it is simply known as the Ruins of Theramore.\n\nThe bronze dragon Zidormi allows adventurers to see how the area appeared in the past and return to the present when asked. Dustwallow Marsh quests are still doable in the past Theramore. A mage with sufficient skill can use teleport and open portals into this city, although they will now be teleported midair over the crater where Jaina's mage tower once stood.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Tidefury Cove",
			short = "Tidefury Cove is located at the end of Dustwallow Bay, south of Theramore Isle and off the coast of the Wyrmbog in Dustwallow Marsh.",
			full = "Tidefury Cove is located at the end of Dustwallow Bay, south of Theramore Isle and off the coast of the Wyrmbog in Dustwallow Marsh. It is dotted with small islands and reefs, and is a perilous place to steer one's ships. Two ships are currently found broken upon the shallows here, now riddled with roaming makrura. The famous fisherman Nat Pagle also makes his home on Nat's Landing, one of the cove's many islets.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Witch Hill",
			short = "Witch Hill is an area in Dustwallow Marsh, located about a third of the way down the peninsula on the way to Theramore Island (or northwest from there).",
			full = "Witch Hill is an area in Dustwallow Marsh, located about a third of the way down the peninsula on the way to Theramore Island (or northwest from there). Near its center is Swamplight Manor, home of \"Swamp Eye\" Jarl. It also contains a few camps of the Mirefin murloc tribe. Witch Hill is haunted by the demon Zelfrax.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Wyrmbog",
			short = "The Wyrmbog is the area in the south of Dustwallow Marsh, south of the Dragonmurk. Many dragons of the black dragonflight, including Onyxia and Emberstrife, reside here.",
			full = "The Wyrmbog is the area in the south of Dustwallow Marsh, south of the Dragonmurk. Many dragons of the black dragonflight, including Onyxia and Emberstrife, reside here. The entrances to Emberstrife's Den and Onyxia's Lair are located within this bog.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 31 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Abyssal Sands",
			short = "Abyssal Sands is a subzone of Tanaris, which is a desert itself.",
			full = "Abyssal Sands is a subzone of Tanaris, which is a desert itself.\n\nDuring the Burning Legion's invasion, the area falls under the Legion's control.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["bootlegger outpost"] = {
			name = "Bootlegger Outpost",
			short = "Bootlegger Outpost is a small outpost of the Steamwheedle Cartel located on the edge of the Gaping Chasm in Tanaris. Narain Soothfancy can now be found here, along with his book Soothsaying for Dummies.",
			full = "Bootlegger Outpost is a small outpost of the Steamwheedle Cartel located on the edge of the Gaping Chasm in Tanaris. Narain Soothfancy can now be found here, along with his book Soothsaying for Dummies.\n\nMarin Noggenfogger sent the goblins here on a mission to either find a way to make a profit off the silithid or wipe them clean off the map.\n\nThis section concerns content related to Legion.\n\nDuring the Burning Legion's invasion, the outpost fell under the Legion's control. Its residents were enslaved by nathrezim but later rescued by the defenders.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.",
			source = "https://warcraft.wiki.gg/wiki/Bootlegger_Outpost",
		},
		["broken pillar"] = {
			name = "Broken Pillar",
			short = "The Broken Pillar is a small group of troll ruins in an area south of Gadgetzan and east of the Abyssal Sands. It is here that Marvon Rivetseeker, a goblin scientist from Ratchet, has set up camp in search of answers.",
			full = "The Broken Pillar is a small group of troll ruins in an area south of Gadgetzan and east of the Abyssal Sands. It is here that Marvon Rivetseeker, a goblin scientist from Ratchet, has set up camp in search of answers. Marvon's work on the pillar later became a subject of studies for archaeologists.\n\nDuring the Burning Legion's invasion, the ruins fall under the Legion's control.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Caverns of Time",
			short = "The Caverns of Time (or simply the Caverns) are home to the Dragon Aspect Nozdormu and his bronze dragonflight, as well as the Timewalkers.",
			full = "The Caverns of Time (or simply the Caverns) are home to the Dragon Aspect Nozdormu and his bronze dragonflight, as well as the Timewalkers. Located in the eastern part of Tanaris, it contain various portals to different key historical periods and events in Warcraft history. The caverns act as a crossroads for the various timeways, branching from the one true timeline, and through them one can travel back and forth along the ebb and flow of time.\n\nSince the world was young, the bronze dragonflight has safeguarded the winding labyrinth, monitoring the shifting timeways to ensure that the delicate balance of time is upheld. It is the bronze dragons' sacred mission, one which was charged to them by the titans, to guard the caverns against the intrusion of mortals, whose interference would assuredly disrupt the flow of time. In recent years, a mysterious force called the infinite dragonflight meddled with time, leading the flight to recruit adventurers to make sure that the events that took place in the past remain as they were.\n\nThe hourglass at the center of the caverns are a perfect replica of the Sacred Hourglass found at the Temporal Conflux in Thaldraszus.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["circle of aquementas"] = {
			name = "Circle of Aquementas",
			short = "The Circle of Aquementas is a swirling, circular structure composed of upright stones found south of Lost Rigger Cove on the eastern coast of Tanaris.",
			full = "The Circle of Aquementas is a swirling, circular structure composed of upright stones found south of Lost Rigger Cove on the eastern coast of Tanaris.\n\nNow, the circle is abandoned and littered with the corpses of pirates. The elemental himself can be still found in Tanaris as Aquementas the Unchained. The location is no longer officially shown on the minimap as a subzone.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Aquementas",
		},
		["dawnrise expedition"] = {
			name = "Dawnrise Expedition",
			short = "Dawnrise Expedition is a small blood elf camp established by the Reliquary in the western area of the Valley of the Watchers in southern Tanaris.",
			full = "Dawnrise Expedition is a small blood elf camp established by the Reliquary in the western area of the Valley of the Watchers in southern Tanaris. It has an Alliance equivalent, Gunstan's Dig.",
			source = "https://warcraft.wiki.gg/wiki/Dawnrise_Expedition",
		},
		["deserted workshop"] = {
			name = "Deserted Workshop",
			short = "The Deserted Workshop is a location in Tanaris just northwest of Gadgetzan.",
			full = "The Deserted Workshop is a location in Tanaris just northwest of Gadgetzan. It contains a wrecked rocket car on the side of a hill, with the cart's tracks showing that it came from the mountains in the north on the border of Thousand Needles. Currently the area seems to serve no purpose.",
			source = "https://warcraft.wiki.gg/wiki/Deserted_Workshop",
		},
		["dunemaul compound"] = {
			name = "Dunemaul Compound",
			short = "Dunemaul Compound is the ogre mound of the Dunemaul ogres of Tanaris. Their leader, Sandscraper, resides here in his cave.",
			full = "Dunemaul Compound is the ogre mound of the Dunemaul ogres of Tanaris. Their leader, Sandscraper, resides here in his cave. Megs Dreadshredder, located just east at the Dunemaul Recruitment Camp, tries to \"recruit\" these ogres into the Horde.\n\nDuring the Burning Legion's invasion, the camp falls under the Legion's control. Its residents are enslaved by nathrezim and are later killed by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["dunemaul recruitment camp"] = {
			name = "Dunemaul Recruitment Camp",
			short = "Dunemaul Recruitment Camp is a small Horde camp just east of the Dunemaul Compound in Tanaris.",
			full = "Dunemaul Recruitment Camp is a small Horde camp just east of the Dunemaul Compound in Tanaris. Megs Dreadshredder believes it is a waste for this ogres to just be sitting around here doing nothing, when they could be working for the Horde, but directly under the Bilgewater Cartel as cheap local labor. She eventually recruits the Dunemaul Ogres with the help of an ogre \"Ambassador\" and an adventurer.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, the camp was defended by Bilgewater Muscles.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Recruitment_Camp",
		},
		["eastmoon ruins"] = {
			name = "Eastmoon Ruins",
			short = "The Eastmoon Ruins is an area of ancient troll ruins found just west of the Gaping Chasm in Tanaris. It has been taken over by the by the Dunemaul ogres and later by the Wastewanders.",
			full = "The Eastmoon Ruins is an area of ancient troll ruins found just west of the Gaping Chasm in Tanaris. It has been taken over by the by the Dunemaul ogres and later by the Wastewanders.\n\nDuring the Burning Legion's invasion, the area is under assault from the Legion. The Wastewanders, surprisingly, have been putting up a fight.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Gadgetzan",
			short = "Rising out of the northern Tanaris desert, Gadgetzan is the capital city of the Steamwheedle Cartel, the largest of the goblin cartels.",
			full = "Rising out of the northern Tanaris desert, Gadgetzan is the capital city of the Steamwheedle Cartel, the largest of the goblin cartels.\n\nSome of the best goblin engineers, miners, and alchemists ply their trade here. The goblins believe in profit above loyalty, thus Gadgetzan is considered neutral territory in any Horde-Alliance conflict. Anyone with a fat wallet or services to offer is welcomed in Gadgetzan. Both governments officially recognize goblin neutrality, and for those who don't, the streets are heavily patrolled by goblin bruisers ready to pound to a pulp anyone disrupting their trade by instigating conflict.\n\nThe city boasts many features including a port for all factions, but also with a blanket of black fumes hanging over the city.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Gaping Chasm",
			short = "The Gaping Chasm is one of the minor silithid hives found in southeastern Tanaris. The area is swarming with Hazzali silithid and has several large hive complexes within.",
			full = "The Gaping Chasm is one of the minor silithid hives found in southeastern Tanaris. The area is swarming with Hazzali silithid and has several large hive complexes within.\n\nThis section concerns content related to the original World of Warcraft.\n\nSenior Surveyor Fizzledowser sent Junior Surveyor Scrimshank to Gaping Chasm, but he went missing. He died in the area, and his gear was recovered by adventurers and returned to Fizzledowser.\n\nRecently the Bootlegger Outpost was established with the goblins trying to exploit the silithid for profit and cleaning out the bugs. Several goblins have been cocooned in the chasm but rescued by adventurers sent by Zeke Bootscuff. Having failed to come up with ideas on how to profit from the silithid, Zeke resorted to having the chasm blown up.\n\nThis section concerns content related to Legion.\n\nDuring the Legion Invasions, a goblin called \"Flight\" Technician Wumble had a camp on the southwestern side of the chasm. The camp was defended by Gadgetzan Defenders and Gadgetzan Sharpshooters, and Captured Imps could be found in cages there.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Land's End Beach",
			short = "Land's End Beach is the southernmost point of Tanaris, in the far southeastern corner of Kalimdor.",
			full = "Land's End Beach is the southernmost point of Tanaris, in the far southeastern corner of Kalimdor. They were headed for either Durotar or Gadgetzan, but the survivors do not realize they've landed on Kalimdor and believe themselves to be on an uncharted island instead. Shortly after the shipwreck, the survivors found a glowing titan artifact which drove them delusional and violent. Gadgetzan sent a few goblins in flying machines to rescue the survivors, but at that point the castaways had all gone insane and killed their would-be rescuers.\n\nThe Crazed Bilgewater Survivors now roam the beach, running around both the wreckage by the water and in a makeshift camp close to the mountains, attacking anyone who gets near. Their leader, Meatface, guards the artifact in a locked chest next to a graveyard where they bury their dead. Surf Gliders and Duneshore Crabs roam the eastern side of the beach. Another crewmember, the rare mob Fronkle the Disturbed, sometimes appears in a crashed bomber on the eastern coast.\n\nThey recovered the artifact from Meatface for study. The duo found the area still inhabited by Bilgewater survivors, who were as crazed as ever and still believe themselves cut off from the world.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Lost Rigger Cove",
			short = "Protected by mountains on three sides, Lost Rigger Cove is the hideout port of the Southsea Pirates on the coast of Tanaris. It notably contains a shipyard where a new vessel is being built.",
			full = "Protected by mountains on three sides, Lost Rigger Cove is the hideout port of the Southsea Pirates on the coast of Tanaris. It notably contains a shipyard where a new vessel is being built.\n\nFighting to make a deal with the baron of Gadgetzan, the gnome and goblin speakers have set up camp just outside the main area and have begun attacking and killing off the pirates.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Noonshade Ruins",
			short = "The Noonshade Ruins are ancient troll ruins located to the east of Gadgetzan in northeastern Tanaris.",
			full = "The Noonshade Ruins are ancient troll ruins located to the east of Gadgetzan in northeastern Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Noxious Lair",
			short = "The Noxious Lair, also known as the Centipaar Hive, is a minor silithid hive found in southwestern Tanaris.",
			full = "The Noxious Lair, also known as the Centipaar Hive, is a minor silithid hive found in southwestern Tanaris.\n\nNot much is known about the Noxious Lair, but a certain quest tells us there used to be water at its location. The Silithid have moved in and drained western Tanaris of its resources.\n\nOn the surface, the lair is slightly sunk, as if there was a broad river or shallow lake at its location once, overlooking the Un'Goro Crater. The floor is mostly sandy. Here and there large twitching claws are erect, seemingly from large silithid creatures buried in the sand, and where they erect the soil is drenched with silithid goo.\n\nInside the lair beneath the surface, it is like any other silithid hive: Humid, warm and eerie. There are many tunnels connecting the two entrances and the breeding rooms with each other. The walls of the tunnels are coated with silithid acid and decorated with unborn insects.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["road warrior"] = {
			name = "Road Warrior",
			short = "The Road Warrior is the inn of Gadgetzan, owned by Innkeeper Fizzgrimble.",
			full = "The Road Warrior is the inn of Gadgetzan, owned by Innkeeper Fizzgrimble.\n\nIt was a stop during the Kirin Tor Tavern Crawl. The local specialty is the [Mechs on the Beach].",
			source = "https://warcraft.wiki.gg/wiki/Road_Warrior",
		},
		["ruins of uldum"] = {
			name = "Ruins of Uldum",
			short = "The Ruins of Uldum (formerly just Uldum) is an ancient hall of stone located in the southern part of the Valley of the Watchers, in the desert of Tanaris.",
			full = "The Ruins of Uldum (formerly just Uldum) is an ancient hall of stone located in the southern part of the Valley of the Watchers, in the desert of Tanaris.\n\nThe ruins are full of Sandstone Earthen, who are immobile (if unprovoked) and malfunctioning. The western side of the room has been damaged, revealing a titan device. The Antediluvean Chest can be found in the back of the room. Tampering with the chest summons the Antechamber Guardian. The area appears to also be known as the \"Antechamber of Uldum\" and may have once been the grand entrance to Uldum itself. The quakes that ripped its doors open probably collapsed the tunnels. If the path was not blocked off, the tunnel would lead to a smaller door at Cursed Landing in Uldum.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Uldum",
		},
		["sandsorrow watch"] = {
			name = "Sandsorrow Watch",
			short = "Sandsorrow Watch (or simply Sandsorrow) is a massive area just west of Gadgetzan in Tanaris. It's populated by the Farraki tribe trolls and their zombies.",
			full = "Sandsorrow Watch (or simply Sandsorrow) is a massive area just west of Gadgetzan in Tanaris. It's populated by the Farraki tribe trolls and their zombies. The watch tower at the eastern section has been taken over and is now a neutral questing hub. Trenton Lighthammer appears to be leading this small camp, where they have also captured and caged up a Sandfury Blood Drinker and Sandfury Zombie.\n\nTrenton provided him with various supplies.\n\nDuring the Burning Legion's invasion, the area fell under the Legion's control. Any remaining troll residents were enslaved by nathrezim and were later killed by the defenders.\n\nThey spoke with Trenton and found two Sandfury trolls captured in his camp. The captives were to be interrogated about the legend of Sul'thraze.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "South Seas",
			short = "Notable islands like Zandalar, Kezan or Tel'Abim are located here. Since this sea is found in between the continents, it is a portion of the Great Sea.",
			full = "Notable islands like Zandalar, Kezan or Tel'Abim are located here. Since this sea is found in between the continents, it is a portion of the Great Sea.\n\nDarkspear Islands\n\nHiji\n\nIsle of Kezan\n\nThe Maelstrom\n\nThe Eye\n\nPlunder Isle\n\nTel Abim\n\nZandalar",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Southbreak Shore",
			short = "Southbreak Shore in Tanaris is an expanse of flat beach to the south of Lost Rigger Cove. It is quiet and almost deserted apart from the hostile pirates that have taken over the northern section of the beach.",
			full = "Southbreak Shore in Tanaris is an expanse of flat beach to the south of Lost Rigger Cove. It is quiet and almost deserted apart from the hostile pirates that have taken over the northern section of the beach. From here Captain Dreadbeard commands the local pirates and has begun getting aid from sea giants, though unclear how.\n\nThe hostile turtles and sea giants that roamed the surf have moved on and in their place Duneshore Crabs now skitter around.\n\nJust off the coast lies a small island with a lone gnome named Winkey. She offers no reason to visit her.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Southmoon Ruins",
			short = "The Southmoon Ruins is an area of ancient troll ruins in southern Tanaris, just north of the Valley of the Watchers. Ancient tablets were discovered here, believed to contain Titan knowledge.",
			full = "The Southmoon Ruins is an area of ancient troll ruins in southern Tanaris, just north of the Valley of the Watchers. Ancient tablets were discovered here, believed to contain Titan knowledge. The Reliquary and Explorers' League now fight for control the tablets within.\n\nDirectly south of here is the Explorer's League camp, known as Gunstan's Dig according to flight paths. Prospector Gunstan leads the group from here.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Steamwheedle Port",
			short = "Steamwheedle Port was a port village on the eastern coast of the Tanaris desert, in the South Seas.",
			full = "Steamwheedle Port was a port village on the eastern coast of the Tanaris desert, in the South Seas. Belonging to the goblins' neutral Steamwheedle Cartel, it was connected by a road to its mother city of Gadgetzan to the west, and also had a dock for ships to and from Kezan. Many of its residents have gone missing, were killed by the destructive forces, or went to live in Gadgetzan for a modest relocation fee.\n\nSteamwheedle Port was home to Yeh'kinya, who started the Hakkar the Soulflayer storyline with the quest Screecher Spirits.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["steelspark station"] = {
			name = "Steelspark Station",
			short = "Steelspark Station is a small Gnomeregan Covert Ops camp located in the northwestern area of Land's End Beach in Tanaris.",
			full = "Steelspark Station is a small Gnomeregan Covert Ops camp located in the northwestern area of Land's End Beach in Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Steelspark_Station",
		},
		["thistleshrub valley"] = {
			name = "Thistleshrub Valley",
			short = "Thistleshrub Valley is an area thick with giant cacti (which are very unusually alive for Tanaris) and was also thick with desert-dwelling thistleshrubs until recently.",
			full = "Thistleshrub Valley is an area thick with giant cacti (which are very unusually alive for Tanaris) and was also thick with desert-dwelling thistleshrubs until recently. Desert Blooms can now be found here, but only sparsely.\n\nBudd's gang can be found in Thistleshrub Valley getting ready to lead the caravan into Uldum, with Adarrah leading the charge.\n\nDuring the Burning Legion's invasion, the area fell under the Legion's control.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Uldum is an ancient desert located on the southern coast of Kalimdor, surrounded by the Un'Goro Crater in the north, Tanaris in the east and Silithus in the northwest.",
			full = "Uldum is an ancient desert located on the southern coast of Kalimdor, surrounded by the Un'Goro Crater in the north, Tanaris in the east and Silithus in the northwest. It is the homeland of stone-cat people known as tol'vir and is rich with titan lore.\n\nThere is no super weapon, however; Uldum is the weapon, intended to wipe out all life on Azeroth in case Algalon the Observer's Reply-Code Omega went through to the titans.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Valley of the Watchers",
			short = "The Valley of the Watchers is an area in southern Tanaris that once held an impenetrable gate into Uldum. The tunnel behind the gates has since collapsed, but used to connect to the Cursed Landing in Uldum.",
			full = "The Valley of the Watchers is an area in southern Tanaris that once held an impenetrable gate into Uldum. The tunnel behind the gates has since collapsed, but used to connect to the Cursed Landing in Uldum.\n\nSandstone Golems can be found rampaging about where the elite Dune Smasher mountain giants used to be.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Waterspring Field",
			short = "The Waterspring Field of Tanaris was named so because of the many water towers which pump the life-giving liquid from reserves deep underground.",
			full = "The Waterspring Field of Tanaris was named so because of the many water towers which pump the life-giving liquid from reserves deep underground.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Wavestrider Beach",
			short = "Wavestrider Beach was the shoreline in eastern Tanaris that stretched from Steamwheedle Port to the Lost Rigger Cove. This was where Desert Crawlers and Steeljaw Snappers roamed the beach.",
			full = "Wavestrider Beach was the shoreline in eastern Tanaris that stretched from Steamwheedle Port to the Lost Rigger Cove. This was where Desert Crawlers and Steeljaw Snappers roamed the beach.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Zalashji's Den",
			short = "It's unknown if Zalashji survived.",
			full = "It's unknown if Zalashji survived.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Zul'Farrak, or Zul'farrak, is a Sandfury troll city located in northwestern Tanaris.",
			full = "Zul'Farrak, or Zul'farrak, is a Sandfury troll city located in northwestern Tanaris.\n\nTanaris used to be a jungle and territory of the Gurubashi Empire, and Zul'Farrak was a city there. When the Great Sundering shattered the ancient landmass, the area swiftly became the desert of Tanaris. The Farraki tribe of trolls were stranded here and eventually adapted to their harsh new environment, becoming sand trolls.\n\nFrom the World Dungeons page on the official World of Warcraft Community Site:\n\nThis sun-blasted city is home to the Sandfury trolls, known for their particular ruthlessness and dark mysticism. Troll legends tell of a powerful sword called [Sul'thraze the Lasher], a weapon capable of instilling fear and weakness in even the most formidable of foes. Long ago, the weapon was split in half. However, rumors have circulated that the two halves may be found somewhere within Zul'Farrak's walls. Reports have also suggested that a band of mercenaries fleeing Gadgetzan wandered into the city and became trapped. Their fate remains unknown. But perhaps most disturbing of all are the hushed whispers of an ancient creature sleeping within a sacred pool at the city's heart - a mighty demigod who will wreak untold destruction upon any adventurer foolish enough to awaken him.\n\nDuring the Elemental Unrest, the city was entered by the Horde and Alliance to kill Kai'ju Gahz'rilla.\n\nThe surviving Sandfury joined the Zandalari.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 49 subzones
	[1447] = {
		["ancient grove"] = {
			name = "Ancient Grove",
			short = "The Ancient Grove is a forest on the southern edge of Azshara. Since the construction of Orgrimmar's rear gate to the east, it has been slowly cut down by the Horde.",
			full = "The Ancient Grove is a forest on the southern edge of Azshara. Since the construction of Orgrimmar's rear gate to the east, it has been slowly cut down by the Horde. Few trees remain, guarded by night elves and the Talrendis Ancient. The Ancient is killed during [5-30] Arborcide.",
			source = "https://warcraft.wiki.gg/wiki/Ancient_Grove",
		},
		["arcane pinnacle"] = {
			name = "Arcane Pinnacle",
			short = "The Arcane Pinnacle is a mountain peak in Azshara where adventurers may attempt Archmage Xylem's quests in the Trial of Fire, Trial of Frost and Trial of Shadow.",
			full = "The Arcane Pinnacle is a mountain peak in Azshara where adventurers may attempt Archmage Xylem's quests in the Trial of Fire, Trial of Frost and Trial of Shadow.\n\nDuring the initial quest to reach the top, if a player gets blown off the cliff, there is a jump gate at that will put you back up where the initial Image of Archmage Xylem is located.\n\nAt the top of the Pinnacle, another Image of Archmage Xylem resides along with a his apprentices and a portal with three stones next to it: the Frost, Fire and Shadow Portal Stone. Clicking one of the stones tunes the portal to the one of the trials and changes its name to \"Icy Mortality\", \"Burning Determination\" or \"Grim Intention\". While in one of the Trial areas, the portal to return to the Arcane Pinnacle is named \"Waning Sanity\" to reflect Xylem's condition. There is no Alliance equivalent of the quests, though the associated achievements are attainable by both factions.\n\nLobos will regularly disappear as he attempts the Trial of Fire but apparently fails. There are no services here and those who leave will have to find their way back on foot, but Zoey Wizzlespark does sell enchanting supplies.",
			source = "https://warcraft.wiki.gg/wiki/Arcane_Pinnacle",
		},
		["bay of storms"] = {
			name = "Bay of Storms",
			short = "The Bay of Storms is a portion of the Great Sea off the eastern coast of Kalimdor, mostly noted by travelers on the eastern coast of the Azshara.",
			full = "The Bay of Storms is a portion of the Great Sea off the eastern coast of Kalimdor, mostly noted by travelers on the eastern coast of the Azshara. It is the location of Scalebeard's Cave, Hetaera's Clutch, and the Temple of Arkkoran. The bay is located around the area of .",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Bear's Head",
			short = "Bear's Head is a remote subzone located by the southeastern edge of the mountains of Azshara.",
			full = "Bear's Head is a remote subzone located by the southeastern edge of the mountains of Azshara. Xylem's Tower, located on a cliff in the area, houses Archmage Xylem as well as several apprentices and associates, including the high elves Joy Ar'nareth and Rayan Dawnrisen.\n\nThe area is named after the villages of Timbermaw furbolgs dotting the landscape, which work as outposts for the more northerly Timbermaw Hold and Ursolan.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bilgewater harbor"] = {
			name = "Bilgewater Harbor",
			short = "From its roots as a humble \"city-in-a-box\" to the bustling metropolis it is today, Bilgewater Harbor straddles the line between myth and legend.",
			full = "From its roots as a humble \"city-in-a-box\" to the bustling metropolis it is today, Bilgewater Harbor straddles the line between myth and legend. At least, that's what the brochure says. The orc commanders might argue differently, though. It isn't exactly easy to maintain discipline in an otherwise lawless city where every vice you can imagine is available for just a handful of silver and debauchery is half off.",
			source = "https://warcraft.wiki.gg/wiki/Bilgewater_Harbor",
		},
		["bitter reaches"] = {
			name = "Bitter Reaches",
			short = "The Bitter Reaches is the name given to the northeastern region of Azshara.",
			full = "The Bitter Reaches is the name given to the northeastern region of Azshara. It is densely populated by hippogryphs, oozes and chimaerae, except along the northern edge where elite mountain giants have displaced most of the wildlife. Some herbs such as [Mountain Silversage] grow here, though sparsely.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["blackmaw hold"] = {
			name = "Blackmaw Hold",
			short = "Blackmaw Hold is a large village of Blackmaw tribe furbolgs along the northern mountain range of Azshara.",
			full = "Blackmaw Hold is a large village of Blackmaw tribe furbolgs along the northern mountain range of Azshara. The furbolg here are aggressive towards outsiders and especially unhappy with the Bilgewater Cartel's modifications of the surrounding area. The Hold includes several camps linked by crude fencing, a bone pit used by shamans, what appears to be a garden or graveyard, a giant guardian totem, and the hold itself which has a distinct bear-head-shaped entrance. The area includes a shallow canyon called the Blackmaw Scar near the village filled with snails. Blackmaw Hold itself has been the capital of the tribe since before the War of the Ancients, over 10,000 years ago.\n\nThe night elves attempted to form an alliance with the Blackmaws, but Horde spies sabotaged their meeting, killing many furbolg in and around the hold.",
			source = "https://warcraft.wiki.gg/wiki/Blackmaw_Hold",
		},
		["darnassian base camp"] = {
			name = "Darnassian Base Camp",
			short = "Darnassian Base Camp, once known as Thalassian Base Camp, is a medium sized area in northern Azshara.",
			full = "Darnassian Base Camp, once known as Thalassian Base Camp, is a medium sized area in northern Azshara.\n\nSeveral fairly low-ranking Highborne night elves have taken over the camp from the hostile blood elves that were once there. Under the leadership of Lorekeeper Amberwind, they are dealing in and attempting to research arcane magic.\n\nThe blood elf Andorel Sunsworn wants them dealt with and remarks on the relative ineptitude of the night elf magi, notably their use of an Arcane Construct, (though noting the \"terrible potential\" should they find anything of value in northern Azshara's ruins), which the high elves of the Eastern Kingdoms had banned 1500 years ago, and further asserting that the kaldorei lost the area ten thousand years ago.",
			source = "https://warcraft.wiki.gg/wiki/Darnassian_Base_Camp",
		},
		["forlorn ridge"] = {
			name = "Forlorn Ridge",
			short = "Forlorn Ridge is a mountain that was once located in southwestern Azshara. When the Bilgewater goblins settled the region, they moved the entire mountain north.",
			full = "Forlorn Ridge is a mountain that was once located in southwestern Azshara. When the Bilgewater goblins settled the region, they moved the entire mountain north.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["gallywix pleasure palace"] = {
			name = "Gallywix Pleasure Palace",
			short = "The Gallywix Pleasure Palace is the residence of Trade Prince Jastor Gallywix, former master of the Bilgewater Cartel.",
			full = "The Gallywix Pleasure Palace is the residence of Trade Prince Jastor Gallywix, former master of the Bilgewater Cartel. It was built on the summit of the relocated Forlorn Ridge in western Azshara, northeast of Talrendis Point. The Bilgewater goblins moved the mountain in order to strip mine its minerals.\n\nThe palace has an ocean view, grenade golf course, a secret booze cellar, a luxury pool, and a sauna. The booze cellar is not seen in the game.",
			source = "https://warcraft.wiki.gg/wiki/Gallywix_Pleasure_Palace",
		},
		["gallywix rocketway exchange"] = {
			name = "Gallywix Rocketway Exchange",
			short = "The Gallywix Rocketway Exchange is a station of the Bilgewater Cartel Rocketway, located near the Gallywix Pleasure Palace in Azshara.",
			full = "The Gallywix Rocketway Exchange is a station of the Bilgewater Cartel Rocketway, located near the Gallywix Pleasure Palace in Azshara.\n\nThe Rocket-jockey will greet successful arrivals with, \"Welcome to the Gallywix Rocketway Exchange! Debts to pay or get the heck away.\"",
			source = "https://warcraft.wiki.gg/wiki/Gallywix_Rocketway_Exchange",
		},
		["haldarr encampment"] = {
			name = "Haldarr Encampment",
			short = "The Haldarr Encampment was located in western Azshara, northeast of Shadowsong Shrine and southwest of old Valormok. It was densely populated by Haldarr satyr, the death of which is an objective of a quest.",
			full = "The Haldarr Encampment was located in western Azshara, northeast of Shadowsong Shrine and southwest of old Valormok. It was densely populated by Haldarr satyr, the death of which is an objective of a quest.\n\nSentinel Keldara Sunblade laid injured, captured or was consorting here.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Hetaera's Clutch",
			short = "Hetaera's Clutch was a large underwater temple of Elune located in the Bay of Storms, off the coast of Azshara. It was populated by the children of Hetaera, the hydras.",
			full = "Hetaera's Clutch was a large underwater temple of Elune located in the Bay of Storms, off the coast of Azshara. It was populated by the children of Hetaera, the hydras. Hetaera herself was found swimming the waters a bit north of the Clutch, sometimes sitting on an island there.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["horizon scout"] = {
			name = "Horizon Scout",
			short = "The Horizon Scout is a shipwreck located in the Ruined Reaches south of Azshara.",
			full = "The Horizon Scout is a shipwreck located in the Ruined Reaches south of Azshara.\n\nCaptain Vanessa Beltis is stranded on the southern peninsula of Azshara, but Roland Geardabbler and several Horizon Scout crew members appear to be trapped aboard the ship with Roland keeping everyone alive by channeling some type of water breathing aura, which is visible around himself.\n\nIn the stairwell of the forward section, there appears to be a small chunk of Azsharite on the floor, which may or may not be part of the reason for the Horizon Scout's sinking. Though it was mostly likely the nearby naga that sank the ship to prevent them from leaving so they could find what they were looking for from the humans.\n\nThe ship itself was unique in that the interior is designed unlike any other ship models currently in-game. However a number of sunken ships in Kelp'thar Forest now have this model.",
			source = "https://warcraft.wiki.gg/wiki/Horizon_Scout",
		},
		["hull of the foebreaker"] = {
			name = "Hull of the Foebreaker",
			short = "The Hull of the Foebreaker is a ship located at the docks of Bilgewater Harbor in Azshara.",
			full = "The Hull of the Foebreaker is a ship located at the docks of Bilgewater Harbor in Azshara.",
			source = "https://warcraft.wiki.gg/wiki/Hull_of_the_Foebreaker",
		},
		["jagged reef"] = {
			name = "Jagged Reef",
			short = "The Jagged Reef is the name for the northern coast of Azshara. It consists of stretches of sandy beach, broken up by jets of stone and small inlets of the ocean.",
			full = "The Jagged Reef is the name for the northern coast of Azshara. It consists of stretches of sandy beach, broken up by jets of stone and small inlets of the ocean. Traveling along the shore here is hazardous due to the treacherous rocks and shallows that lie beneath the ocean surface. Murlocs, hydras, and makrura inhabit the region, swimming in the shallows or plodding across the beach looking for food.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lake Mennar",
			short = "Lake Mennar is one of the few places in the world where the blue dragonflight can be found outside of Northrend. The only comparable place is Mazthoril in Winterspring.",
			full = "Lake Mennar is one of the few places in the world where the blue dragonflight can be found outside of Northrend. The only comparable place is Mazthoril in Winterspring. Although most of the region on all sides of the lake is inhabited by dragonspawn, the actual lake itself is free from danger and can provide solace and refreshment to those who are brave enough to get through the perimeter dragonkin.\n\nThough it was once a common sight to see young azure whelplings near Lake Mennar, they have since migrated to the colder climates of Winterspring in the wake of Azuregos' departure.\n\nThis section concerns content related to the Warcraft novels, novellas, or short stories.\n\nMalynea Skyreaver then explained that what is drawing them is a Sarcen Stone",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Legash Encampment",
			short = "The Legash Encampment is located in northern Azshara, east of Ursolan and north of the Thalassian Base Camp. It is occupied by Legashi satyr.",
			full = "The Legash Encampment is located in northern Azshara, east of Ursolan and north of the Thalassian Base Camp. It is occupied by Legashi satyr.\n\nArchmage Xylem found a grimoire here.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["mountainfoot strip mine"] = {
			name = "Mountainfoot Strip Mine",
			short = "Mountainfoot Strip Mine is a very large mine operation in southwestern Azshara. It is situated in what was formerly the site of the mountain of Forlorn Ridge.",
			full = "Mountainfoot Strip Mine is a very large mine operation in southwestern Azshara. It is situated in what was formerly the site of the mountain of Forlorn Ridge. It is implied that the mountain where Gallywix Pleasure Palace is located is the former Forlorn Ridge.\n\nDuring the Burning Legion's invasion, the mine fell under the Legion's control. Its residents were enslaved by nathrezim and were later killed or rescued by the defenders.",
			source = "https://warcraft.wiki.gg/wiki/Mountainfoot_Strip_Mine",
		},
		["northern rocketway exchange"] = {
			name = "Northern Rocketway Exchange",
			short = "The Northern Rocketway Exchange is a station of the Bilgewater Cartel Rocketway, west of the Darnassian Base Camp. It contains a mailbox, forge and cooking fires, which include a grill with some unusual delicacies.",
			full = "The Northern Rocketway Exchange is a station of the Bilgewater Cartel Rocketway, west of the Darnassian Base Camp. It contains a mailbox, forge and cooking fires, which include a grill with some unusual delicacies.\n\nThe Rocket-jockey will greet successful arrivals with, \"Welcome to the Northern Rocketway Exchange! We at Rocketway Relations are glad you survived that last turn!\"",
			source = "https://warcraft.wiki.gg/wiki/Northern_Rocketway_Exchange",
		},
		["northern rocketway terminus"] = {
			name = "Northern Rocketway Terminus",
			short = "The Northern Rocketway Terminus is a station of the Bilgewater Cartel Rocketway, located directly north of Bilgewater Harbor and southwest of Sable Ridge.",
			full = "The Northern Rocketway Terminus is a station of the Bilgewater Cartel Rocketway, located directly north of Bilgewater Harbor and southwest of Sable Ridge. Like the southern terminus, it has a flight master, located on the platform near the Bilgewater Rocket-jockey.\n\nThe Rocket-jockey will greet successful arrivals with, \"Welcome to the Northern Rocketway Terminus! You probably took a wrong turn, but we're happy to have you anyway!\" In addition to the lack of NPCs, this part of the rocketway is not classified as its own subzone, instead being classified as part of the Bitter Reaches.",
			source = "https://warcraft.wiki.gg/wiki/Northern_Rocketway_Terminus",
		},
		["orgrimmar rear gate"] = {
			name = "Orgrimmar Rear Gate",
			short = "The Orgrimmar Rear Gate connects the city of Orgrimmar to Azshara, controlled by the Horde-allied goblins of the Bilgewater Cartel. It is set at the end of a long canyon road leading from the Valley of Honor.",
			full = "The Orgrimmar Rear Gate connects the city of Orgrimmar to Azshara, controlled by the Horde-allied goblins of the Bilgewater Cartel. It is set at the end of a long canyon road leading from the Valley of Honor.\n\nAg'tor Bloodfist and Labor Captain Grabbit await adventurers here with the first quests of the Azshara storyline. Talrendis Scouts can initially be found sneaking around the vicinity at first, but as the storyline progresses, it comes under siege from Alliance forces. Despite this Horde forces, with the aid of adventurers, are able to repel the invasion.\n\nDuring the Legion Invasions, demons targeted the area. Allied forces cooperated by Jastor Gallywix defended the area.",
			source = "https://warcraft.wiki.gg/wiki/Orgrimmar_Rear_Gate",
		},
		["orgrimmar rocketway exchange"] = {
			name = "Orgrimmar Rocketway Exchange",
			short = "The Orgrimmar Rocketway Exchange is a station of the Bilgewater Cartel Rocketway, near the rear gate to the city of Orgrimmar.",
			full = "The Orgrimmar Rocketway Exchange is a station of the Bilgewater Cartel Rocketway, near the rear gate to the city of Orgrimmar.\n\nMany goblins previously residing in Goblin Slums, now replaced with Orgrimmar Embassy, were moved inside the building here as part of a \"workforce adjustment.\" Allied races must be unlocked in order to see them here.\n\nThe quest [5-30] Return of the Highborne? acts as a breadcrumb quest from the rear gate to this location.",
			source = "https://warcraft.wiki.gg/wiki/Orgrimmar_Rocketway_Exchange",
		},
		["ravencrest monument"] = {
			name = "Ravencrest Monument",
			short = "The Ravencrest Monument marks the remains of a huge statue in Azshara, referred to by Torg Twocrush as an \"ancient night elven colossus\".",
			full = "The Ravencrest Monument marks the remains of a huge statue in Azshara, referred to by Torg Twocrush as an \"ancient night elven colossus\". Located southeast of the Ruins of Eldarath, what is left of the time-worn statue rests atop cliffs on the tip of Azshara's southern point, overlooking the Great Sea.\n\nUndoubtedly an impressive site long ago, the statue now lies in ruins. Only the broken-off legs still stand, with various other parts scattered on the ground around them. Presumably, the rest has become buried, or sunk beneath the waves of the sea below. The ruins are inhabited by the hostile Spitelash tribe of naga.\n\nThe Ravencrest Monument cannot be accessed by sea. Travelers seeking to visit the site must approach it from inland and cross a bridge.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Rethress Sanctum",
			short = "Rethress Sanctum is a ruined shrine located in the Ruined Reaches, southwest of Ravencrest Monument in Azshara. It is currently uninhabited, visited only by stray murlocs and makrura.",
			full = "Rethress Sanctum is a ruined shrine located in the Ruined Reaches, southwest of Ravencrest Monument in Azshara. It is currently uninhabited, visited only by stray murlocs and makrura.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Ruined Reaches",
			short = "The Ruined Reaches form the southern coast of Azshara near the border to Durotar. It is mostly stretches of beach and cliffs broken up by inlets of water and dotted with various ruins and shipwrecks.",
			full = "The Ruined Reaches form the southern coast of Azshara near the border to Durotar. It is mostly stretches of beach and cliffs broken up by inlets of water and dotted with various ruins and shipwrecks. Like the Jagged Reef to the north, travel along the reaches can be hazardous, both due to the treacherous shallows lying just below the surface of the ocean, but also due to aggressive murlocs, hydras, and makrura. On the western shores of the Ruined Reaches is a gnomish building on a hill (accessible by the main land down a steep path, not on the beach ) where Blimo Gadgetspring and Jubie Gadgetspring make their home and business selling engineering and trade supplies. If you ride the elevator up to the second floor, you'll find their bedroom with a third bed. It is unknown who, if anyone, sleeps in the extra bed.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of arkkoran"] = {
			name = "Ruins of Arkkoran",
			short = "The Ruins of Arkkoran are what remain of a once large ancient night elven temple known as the Temple of Arkkoran. It was the home of the sea giant Arkkoroc.",
			full = "The Ruins of Arkkoran are what remain of a once large ancient night elven temple known as the Temple of Arkkoran. It was the home of the sea giant Arkkoroc.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Arkkoran",
		},
		["ruins of eldarath"] = {
			name = "Ruins of Eldarath",
			short = "The Ruins of Eldarath are all that remains of an ancient night elven city located in central Azshara.",
			full = "The Ruins of Eldarath are all that remains of an ancient night elven city located in central Azshara.\n\nBefore the Great Sundering, Eldarath was a flourishing city -- a mighty stronghold, even. It is believed that many ancient and powerful Highborne artifacts may be found among its ruins. 10,000 years later, it was found by Li Li Stormstout. Some of the most powerful mages of the Highborne created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places. Multiple such tablets can be found in the Ruins of Eldarath.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["ruins of nordressa"] = {
			name = "Ruins of Nordressa",
			short = "The Ruins of Nordressa is an area west of the Northern Rocketway Exchange where the Image of Archmage Xylem is located along with several of his apprentices.",
			full = "The Ruins of Nordressa is an area west of the Northern Rocketway Exchange where the Image of Archmage Xylem is located along with several of his apprentices. The quest chains involving Xylem start here, initiated by Sorata Firespinner, a burnt-out apprentice who gives players an apprentice's hat and sends them here.\n\nThe entrance to this area is on the eastern side of the encampment around and is marked by a series of torches. After players have completed some tasks for Xylem and his apprentices, they will be sent to the Arcane Pinnacle, where Xylem's trials take place.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Nordressa",
		},
		["sable ridge"] = {
			name = "Sable Ridge",
			short = "This section concerns content related to Legion.",
			full = "This section concerns content related to Legion.\n\nBy the time of the Burning Legion's third invasion, Raethas Dawnseer commented that the ruins looked like the goblins already picked them clean.",
			source = "https://warcraft.wiki.gg/wiki/Sable_Ridge",
		},
		["scalebeards cave"] = {
			name = "Scalebeard's Cave",
			short = "Scalebeard's Cave was located on a tiny island in the western part of the Bay of Storms in Azshara.",
			full = "Scalebeard's Cave was located on a tiny island in the western part of the Bay of Storms in Azshara. It was the home of the rare elite turtle Scalebeard, but he tended to not be present, usually preferring to spend his time hunting in the Great Sea.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["secret lab"] = {
			name = "Secret Lab",
			short = "The Secret Lab is a small lab located within a crater like hole in southern Azshara. It houses a few experiments that the Bilgewater goblins have been performing, most notably on raptors.",
			full = "The Secret Lab is a small lab located within a crater like hole in southern Azshara. It houses a few experiments that the Bilgewater goblins have been performing, most notably on raptors. They, like the goblins at Area 52, have built a working rocket to space.\n\nX. Nizzlebex is the director of the Secret Lab, but something appears to have gone terribly wrong. All the buildings are on fire, and the buzzer to request assistance indicates no one is home. Research Interns can be found running around attempting to extinguish themselves. Meanwhile, Subject Four, apparently an escaped experiment, seeks to exact revenge on humanoids, while Subject Nine attempts to formulate an escape plan.",
			source = "https://warcraft.wiki.gg/wiki/Secret_Lab",
		},
		["shadowsong shrine"] = {
			name = "Shadowsong Shrine",
			short = "Shadowsong Shrine was a ruin-covered hill in western Azshara. It was haunted by the ghosts of the highborne, who also roamed the surrounding landscape looking to quench all intruding life.",
			full = "Shadowsong Shrine was a ruin-covered hill in western Azshara. It was haunted by the ghosts of the highborne, who also roamed the surrounding landscape looking to quench all intruding life. The shrine shared its name with both Jarod Shadowsong, commander of the resistance during the War of the Ancients and Maiev Shadowsong, older sister of Jarod and the famous warden who was held responsible for the captivity of Illidan Stormrage after his betrayal at Mt. Hyjal. Any connection they have with the shrine is unknown.\n\nThe area has been incorporated into Talrendis Point.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "Shattered Strand",
			short = "The Shattered Strand is a coastal area in Azshara, lining the north side of the Bay of Storms. It is densely populated by hydras, sea giants, makrura and murlocs.",
			full = "The Shattered Strand is a coastal area in Azshara, lining the north side of the Bay of Storms. It is densely populated by hydras, sea giants, makrura and murlocs. The strand is also the location of the Temple of Arkkoran and the Tower of Eldara.\n\nSome goblins also took advantage of the wealth of beach front property and engaged in real estate speculation here.\n\nDuring the Burning Legion's invasion, the strand falls under the Legion's control. Several naga were killed while the Horde troops continued to battle the demons.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southern rocketway terminus"] = {
			name = "Southern Rocketway Terminus",
			short = "The Southern Rocketway Terminus is a station of the Bilgewater Cartel Rocketway, located directly south of Bilgewater Harbor and east of the Secret Lab.",
			full = "The Southern Rocketway Terminus is a station of the Bilgewater Cartel Rocketway, located directly south of Bilgewater Harbor and east of the Secret Lab. Like the northern terminus, it has a flight master, located at a small landing pad below the station.\n\nThe Rocket-jockey will greet successful arrivals with, \"Welcome to the Southern Rocketway Terminus! Home of the world famous Secret Lab!\"\n\nTaking a rocket ride between this terminus and the northern terminus will award you [Joy Ride].\n\nThe terminus is useful to either get to Bilgewater Harbor for the first time, or to get to the Secret Lab.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Rocketway_Terminus",
		},
		["southfury river"] = {
			name = "Southfury River",
			short = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls.",
			full = "The Southfury River is likely Kalimdor's most prominent river. Beginning from a lake in Mount Hyjal, it drops into the regions below via a set of spectacular waterfalls. The resulting wide, swiftly-flowing river forms the boundary between the forest of Ashenvale and Azshara, and further south, the border between the Northern Barrens and Durotar. The river empties into the Great Sea in a cascading waterfall just northeast of the goblin port city of Ratchet.\n\nThere are three bridges that span the Southfury River: one crossing from Azshara into Ashenvale, one leading into the Horde's capital city of Orgrimmar, and one that crosses from Durotar into the Northern Barrens. Notably, just north of the western bridge of Orgrimmar, there is a spot on the river where four in-game zones meet: Ashenvale, Azshara, Durotar, and Northern Barrens.\n\nA goblin named Horton Hornblower sits at a dock near the mouth of the Southfury with his Riverboat. After doing quests for the goblins in Ratchet, he offers [5-30] Raging River Ride, which provides transportation to the area outside Nozzlepot's Outpost in the Northern Barrens.\n\nIt could still be used to water the crops, but it could no longer be drunk.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Southridge Beach",
			short = "Southridge Beach is located in central Azshara, lining the South edge of the Bay of Storms. It is heavily inhabited by the naga, but also supports makrura, hydras, murlocs, and the occasional sea giant.",
			full = "Southridge Beach is located in central Azshara, lining the South edge of the Bay of Storms. It is heavily inhabited by the naga, but also supports makrura, hydras, murlocs, and the occasional sea giant. Countless ruins dot the beach, remnants of the once-great city of Eldarath.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Storm Cliffs",
			short = "The Storm Cliffs are the cliff directly east of the Southern Rocketway Terminus in Azshara. The Spitelash naga take up residence here.",
			full = "The Storm Cliffs are the cliff directly east of the Southern Rocketway Terminus in Azshara. The Spitelash naga take up residence here. The Ravencrest Monument can be found at the far east of the cliffs.\n\nSeason of Discovery turned the zone into a instanced raid encounter.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Talrendis Point",
			short = "Talrendis Point is a large night elven outpost located in southwestern Azshara.",
			full = "Talrendis Point is a large night elven outpost located in southwestern Azshara. It has two guard towers (the northern one occupying the area of the former Shadowsong Shrine), a moonwell in the southern part, and a building in the western area.\n\nThough friendly to Alliance players, the town offers no services to friendly visitors.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Temple of Arkkoran",
			short = "The Temple of Arkkoran was a former temple of Elune located on the northeastern shores of Azshara and it was where the sea giant Arkkoroc lived.",
			full = "The Temple of Arkkoran was a former temple of Elune located on the northeastern shores of Azshara and it was where the sea giant Arkkoroc lived. He could be found at the top level of the temple and was guarded by murlocs and makrura who attacked on sight. The Shattered Strand, which the temple was located on, is also under watch by hydras and aggressive sea giants.\n\nThe temple is a popular farming spot because of the Stormshroud Armor patterns ( [chest] and [shoulders]) and [Golden Pearls] that drop there.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Temple of Zin-Malor",
			short = "The Temple of Zin-Malor is an ancient building situated in the Ruins of Eldarath. It was once a prominent night elven temple to the worship of their goddess, Elune.",
			full = "The Temple of Zin-Malor is an ancient building situated in the Ruins of Eldarath. It was once a prominent night elven temple to the worship of their goddess, Elune. Its similarity to the nearby Temple of Arkkoran is striking, as they both have a very similar design to the current Temple of the Moon in Darnassus. The temple is currently occupied by the Spitelash tribe of naga under the leadership of Warlord Krellian, who himself inhabits the temple in a place of honor. The [Crystal of Zin-Malor] once rested here but was stolen by the inhabitants of Kel'Theril in Winterspring.\n\nThe gift was actually a message of advice and wisdom to the Highborne: that they did not actually need arcane magic at all.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Thalassian Base Camp",
			short = "The Thalassian Base Camp was located in northern Azshara, south of the Legash Encampment and east of Ursolan. It was a hill containing numerous small camps under control of blood elves.",
			full = "The Thalassian Base Camp was located in northern Azshara, south of the Legash Encampment and east of Ursolan. It was a hill containing numerous small camps under control of blood elves. The leader of the Thalassian Base Camp, Magus Rimtori, recently made and reneged on a deal with the Horde to offer a share of the findings in exchange for funding and protection of the expedition. Because of this betrayal, Horde players were being recruited to exact vengeance upon Magus Rimtori and her followers, during the quests Betrayed and Betrayed. While Rimtori was off exploring Azshara under the protection of her bodyguards, Magister Hawkhelm watched over the camp. The Kaldorei Tome of Summoning lay on one of the ridges of the base camp and could be used to summon in demons. This was indicative of the expedition's true intentions.\n\nThey had developed a special method for pulverizing the magical items they acquired, producing [Glittering Dust] which differed from the components normally acquired by a [Disenchant] spell. Archmage Xylem was interested into that dust.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "Tower of Eldara",
			short = "The Tower of Eldara was once part of the extensive night elven civilization that stretched across most of what is now called Azshara.",
			full = "The Tower of Eldara was once part of the extensive night elven civilization that stretched across most of what is now called Azshara. It is located on the very tip of land northeast of the Bay of Storms, and the sandy beaches near the tower are heavily patrolled by murlocs, makrura, and hydras. The tower itself stands closed and abandoned.\n\nDuring the Burning Legion's third invasion, Phloem tried to open it, but without a success.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["trial of fire"] = {
			name = "Trial of Fire",
			short = "The Trial of Fire is where players complete the quest [5-30] The Trial of Fire and can earn the [Glutton for Fiery Punishment] achievement.",
			full = "The Trial of Fire is where players complete the quest [5-30] The Trial of Fire and can earn the [Glutton for Fiery Punishment] achievement. It can be accessed by flying mount or by selecting the fire stone and teleporting here from the Arcane Pinnacle.\n\nAccording to the warning emotes provided in the quest:\n\nEvery few seconds, many of the nearby runes will burst with fire.\n\nAs each rune bursts, a bolt of fire will travel to one or more nearby runes, triggering it to be one of the next runes to burst.\n\nIf you watch these bolts of fire closely to see which runes are not hit, you can spot safe spots for the next burst.\n\nStay within the runes without getting hit by fire until you have 10 stacks of Fire Dancing to complete the trial.\n\nIn addition to Image of Archmage Xylem, an apprentice named Darwin can be found here attempting to perform the trial and dancing. You can follow Darwin's movements in order to accomplish it. Although the description calls it a fire dance you don't have to dance.",
			source = "https://warcraft.wiki.gg/wiki/Trial_of_Fire",
		},
		["trial of frost"] = {
			name = "Trial of Frost",
			short = "The Trial of Frost is a subzone of Azshara where the Image of Archmage Xylem gives the quest [5-30] The Trial of Frost and where the player can complete the achievement [Glutton for Icy Punishment] by avoiding the Eyes of Frost.",
			full = "The Trial of Frost is a subzone of Azshara where the Image of Archmage Xylem gives the quest [5-30] The Trial of Frost and where the player can complete the achievement [Glutton for Icy Punishment] by avoiding the Eyes of Frost.\n\nOne of Xylem's apprentices, Henny, can be found here attempting the Trial. The peak appears to be part of the Bitter Reaches, and one can see the dragons of Sable Ridge from this vantage point.",
			source = "https://warcraft.wiki.gg/wiki/Trial_of_Frost",
		},
		["trial of shadow"] = {
			name = "Trial of Shadow",
			short = "The Trial of Shadow is a subzone of Azshara where the Image of Archmage Xylem gives the quest [5-30] The Trial of Shadow and where the player can complete the achievement [Glutton for Shadowy Punishment].",
			full = "The Trial of Shadow is a subzone of Azshara where the Image of Archmage Xylem gives the quest [5-30] The Trial of Shadow and where the player can complete the achievement [Glutton for Shadowy Punishment].",
			source = "https://warcraft.wiki.gg/wiki/Trial_of_Shadow",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Ursolan is an area in Azshara just east of Timbermaw Hold. It is characterized by a deep scar running through the middle of it, full of Talrendis Biologists.",
			full = "Ursolan is an area in Azshara just east of Timbermaw Hold. It is characterized by a deep scar running through the middle of it, full of Talrendis Biologists. Ursolan is now the site of an extensive Timbermaw furbolg settlement, which runs south through the Hold to Bear's Head.\n\nUrsolan's namesake is Ursol, a Kalimdor bear demigod revered by the furbolg race.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok is an orc-controlled Horde outpost in Azshara. It was originally found to the northwest, north of the Haldarr Encampment.",
			full = "Valormok is an orc-controlled Horde outpost in Azshara. It was originally found to the northwest, north of the Haldarr Encampment.\n\nThe subject of this section has been removed from World of Warcraft but is present in Classic.\n\nOld Valormok was a small outpost found in northwestern Azshara. The warriors there experienced difficult times but were still hopeful. It was populated with many more orcs, but most were slain by the treacherous blood elf Magus Rimtori, who was sent with warriors by Belgrom Rockmaul to find riches and powerful artifacts. Instead, Rimtori ended up killing the Horde warriors and taking what she found for herself. The leader of the camp, Ag'tor Bloodfist, sent adventurers out to avenge both his warriors and Rockmaul's pride. They made war upon the nearby Thalassian Base Camp, slaughtering the elves there and eventually killing Magus Rimtori. Jediga was also sent here by Rockmaul as a punishment, though she made the most of this by instructing adventurers to try and find ancient Highborne tablets to sell to interested parties in the area to get out of Azshara.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
		["xylems tower"] = {
			name = "Xylem's Tower",
			short = "Xylem's Tower (or Azshara Tower) is a mage tower located at Bear's Head in Azshara. The only way to get to it is to receive a teleport from Sanath Lim-yo.",
			full = "Xylem's Tower (or Azshara Tower) is a mage tower located at Bear's Head in Azshara. The only way to get to it is to receive a teleport from Sanath Lim-yo. It is the home of Archmage Xylem, Coral Moongale and a few others.",
			source = "https://warcraft.wiki.gg/wiki/Xylem's_Tower",
		},
	},
	-- Felwood: 23 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Bloodvenom Falls",
			short = "Bloodvenom Falls is a corrupted waterfall high in Felwood. It is the source of the Bloodvenom River.",
			full = "Bloodvenom Falls is a corrupted waterfall high in Felwood. It is the source of the Bloodvenom River. The corruption of the Falls is carried beyond Felwood, as the Bloodvenom River cascades down the mountains to become the tainted Wildbend River in Darkshore.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Bloodvenom Post",
			short = "Bloodvenom Post was a tiny Horde outpost in Felwood near the Bloodvenom River.",
			full = "Bloodvenom Post was a tiny Horde outpost in Felwood near the Bloodvenom River.\n\nIt sat on the high cliffs overlooking Darkshore. It seems to have been founded by the tauren due to the original architecture and the tauren guards.\n\nTo find the ruins of the post, follow the Bloodvenom River west along the south side, starting from the main stone path that runs north and south through Felwood. You will notice a dark trail -- simply follow it around the hillside to reach the ruins.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Bloodvenom River",
			short = "The Bloodvenom River is a corrupted river in central Felwood. The river spreads its corruption beyond Felwood, eventually becoming the Wildbend River in Darkshore.",
			full = "The Bloodvenom River is a corrupted river in central Felwood. The river spreads its corruption beyond Felwood, eventually becoming the Wildbend River in Darkshore. The banks of the Bloodvenom are crawling with noxious oozes and other corrupted wildlife. Swimming is not recommended and do not drink the water if you have a compromised immune system.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Deadwood Village",
			short = "Deadwood Village is a furbolg village of the Deadwood tribe in southern Felwood. Like most of their kin, the Deadwood furbolgs have been corrupted and are hostile.",
			full = "Deadwood Village is a furbolg village of the Deadwood tribe in southern Felwood. Like most of their kin, the Deadwood furbolgs have been corrupted and are hostile. A wooden fence comprised of thick timbers encloses much of the village and there are more sturdy structures inside.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Emerald Sanctuary",
			short = "Emerald Sanctuary is a camp of the Emerald Circle in southeastern Felwood. The druids stationed here give quests to adventurers about investigating demonic corruption at Jaedenar and snuffing it out.",
			full = "Emerald Sanctuary is a camp of the Emerald Circle in southeastern Felwood. The druids stationed here give quests to adventurers about investigating demonic corruption at Jaedenar and snuffing it out.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Felpaw Village",
			short = "Felpaw Village is a furbolg settlement that lies in the very north of Felwood, near the entrance of Timbermaw Hold. The village belongs to the Deadwood, a tribe of furbolgs that have been corrupted.",
			full = "Felpaw Village is a furbolg settlement that lies in the very north of Felwood, near the entrance of Timbermaw Hold. The village belongs to the Deadwood, a tribe of furbolgs that have been corrupted.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Irontree Cavern",
			short = "Irontree Cavern is a deep cave inhabited by Warpwood Shredders and Warpwood Moss Flayers.",
			full = "Irontree Cavern is a deep cave inhabited by Warpwood Shredders and Warpwood Moss Flayers.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree clearing"] = {
			name = "Irontree Clearing",
			short = "Irontree Clearing, located in Felwood, comprises the northern section of Irontree Woods that includes Irontree Cavern. It is a Horde-friendly area full of Irontree Shredders and a strip mining camp.",
			full = "Irontree Clearing, located in Felwood, comprises the northern section of Irontree Woods that includes Irontree Cavern. It is a Horde-friendly area full of Irontree Shredders and a strip mining camp. The Clearing stretches from the area around the Cavern all the way across the main Felwood road to a small Horde camp and quest hub, complete with a flight master.\n\nThe goblins of this clearing have begun attacking the worgen and night elves located in nearby Talonbranch Glade who have attempted to stop their lumber operations. The Clearing's lower reaches are later attacked and destroyed by the Worgen following the increased hostility.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Clearing",
		},
		["irontree woods"] = {
			name = "Irontree Woods",
			short = "Irontree Woods lies in northern Felwood. Once a peaceful forest glade, it has been corrupted like the rest of Felwood by the demonic presence of the Burning Legion.",
			full = "Irontree Woods lies in northern Felwood. Once a peaceful forest glade, it has been corrupted like the rest of Felwood by the demonic presence of the Burning Legion. Three Ancients - Hastat, Stoma and Vartrus, the great living trees of the night elves, have been petrified and remain permanently entombed within the Irontree Woods. Crazed treants, twisted bog beasts, ferocious wildlife, and corrupted water elementals also roam the woods, attacking any who venture near.\n\nWhile the Ancients are dead, life still spreads among them. When an adventurer poured moonwell water in the middle a seedling was born. After the short time taking care of it, it finally blossomed and when it was complete, it returned to the place it was born and will stay there until it is ready to take his place as the new Ancient.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Jadefire Glen",
			short = "Jadefire Glen is an encampment of demonic satyr in southern Felwood. Many of the quests in Felwood involve killing the satyr here and scattered throughout the rest of the corrupted woods.",
			full = "Jadefire Glen is an encampment of demonic satyr in southern Felwood. Many of the quests in Felwood involve killing the satyr here and scattered throughout the rest of the corrupted woods.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Jadefire Run",
			short = "Jadefire Run is a satyr encampment in northern Felwood. The most powerful satyr in the region make their home here, so exercise caution when adventuring in the area.",
			full = "Jadefire Run is a satyr encampment in northern Felwood. The most powerful satyr in the region make their home here, so exercise caution when adventuring in the area. Feronas Sindweller, a demon hunter, was under the impression the healers were nothing more than the demons in disguise. There also appears to be more traditional demonic architecture in the Run.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar is an area in Felwood that has been completely taken over by the Shadow Council. The site lies on a series of ancient night elf ruins and two druidic barrow dens.",
			full = "Jaedenar is an area in Felwood that has been completely taken over by the Shadow Council. The site lies on a series of ancient night elf ruins and two druidic barrow dens. It was named in worship of Kil'jaeden.\n\nThe Shadow Hold, the Shadow Council's stronghold on Azeroth, and the Shrine of the Deceiver are also located here.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran was once a great night elf settlement, long before the Great Sundering. It is located at the southern edge of Felwood.",
			full = "Morlos'Aran was once a great night elf settlement, long before the Great Sundering. It is located at the southern edge of Felwood. There are similar ruins located nearby, at Ameth'Aran and Bashal'Aran in Darkshore, Ordil'Aran in Ashenvale, and Tethris'Aran in Desolace. Once thriving cities, now these ruins only serve as a reminder of the golden age that was lost long ago.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruins of Constellas",
			short = "The Ruins of Constellas is an area of Felwood. Xavathras, and his group of Jadefire satyr, inhabit the area.",
			full = "The Ruins of Constellas is an area of Felwood. Xavathras, and his group of Jadefire satyr, inhabit the area. Judging by the remnants of the architecture, and the existence of a moonwell, it used to be one of the many night elven settlements near Mount Hyjal. The moonwell has since become corrupted with Fel energy, and is being cultivated by Xavathras on behalf of Xavaric.\n\nDruidic Emerald Bearkin are attacking the demons of the Ruins. A camp rests to the southeast where Eridan Bluewind and Arcanist Delaris await with quests. Further into the heart of the Ruins the path leading to Xavathras is blocked by a wall of fire.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Shadow Hold",
			short = "Shadow Hold, located within Jaedenar in western Felwood, is a former night elf barrow den which now serves as the Shadow Council's stronghold on Azeroth.",
			full = "Shadow Hold, located within Jaedenar in western Felwood, is a former night elf barrow den which now serves as the Shadow Council's stronghold on Azeroth. It is a gigantic subterranean labyrinth roamed by warlocks and their demonic familiars. The satyr Prince Xavalis and dreadlord Lord Banehollow also reside here.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shadowlurk ridge"] = {
			name = "Shadowlurk Ridge",
			short = "Shadowlurk Ridge lies near the Ruins of Constellas in Felwood. It is home to a swarm of Jadefire Imps that stretch the entire length of the area.",
			full = "Shadowlurk Ridge lies near the Ruins of Constellas in Felwood. It is home to a swarm of Jadefire Imps that stretch the entire length of the area.",
			source = "https://warcraft.wiki.gg/wiki/Shadowlurk_Ridge",
		},
		["shatter scar vale"] = {
			name = "Shatter Scar Vale",
			short = "Shatter Scar Vale lies north of the Bloodvenom Falls in Felwood. Shatter Scar Vale is where many of the demonic infernals fell to Azeroth during the invasion of the Burning Legion during the Third War.",
			full = "Shatter Scar Vale lies north of the Bloodvenom Falls in Felwood. Shatter Scar Vale is where many of the demonic infernals fell to Azeroth during the invasion of the Burning Legion during the Third War. Still-smoldering craters dot the vale, and demons still wander the scarred landscape.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Shrine of the Deceiver",
			short = "The Shrine of the Deceiver is a corrupted barrow den located at Jaedenar in Felwood. It is named for the Burning Legion's lord - Kil'jaeden the Deceiver.",
			full = "The Shrine of the Deceiver is a corrupted barrow den located at Jaedenar in Felwood. It is named for the Burning Legion's lord - Kil'jaeden the Deceiver. The shrine is filled with warlocks of the Shadow Council and is a dangerous place to enter for the unprepared.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["sindwellers rise"] = {
			name = "Sindweller's Rise",
			short = "Sindweller's Rise is a small clearing in northern Felwood. It is located just off the road, north west of the Irontree Woods. Feronas Sindweller is found here.",
			full = "Sindweller's Rise is a small clearing in northern Felwood. It is located just off the road, north west of the Irontree Woods. Feronas Sindweller is found here.",
			source = "https://warcraft.wiki.gg/wiki/Sindweller's_Rise",
		},
		["talonbranch glade"] = {
			name = "Talonbranch Glade",
			short = "Talonbranch Glade is an Alliance outpost in the northern parts of Felwood.",
			full = "Talonbranch Glade is an Alliance outpost in the northern parts of Felwood. Gilnean worgen were sent to Talonbranch in order to help the night elves with defending it from the attacking goblins from the Bilgewater Cartel; the Glade then turning into a prominent Gilnean outpost. Talonbranch Glade is located south of Timbermaw Hold, which leads to Moonglade and Winterspring.\n\nAccording to the leader Denmother Ulrica, several of the worgen (possibly including herself) present in Talonbranch had been around since Velinde Starsong first summoned the worgen with the Scythe of Elune.\n\nThey refer to their group as a pack, the tree as their home, and Ulrica as their Denmother.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.",
			full = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under the corruptive influence of the Burning Legion. However, amidst the chaos and the madness, the Timbermaw tribe escaped the darkness that had fallen on Kalimdor. In the safety of Timbermaw Hold, the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. The corruption had sunk in deep, so that even long after Illidan had consumed the source of the corruption, a powerful warlock artifact called the Skull of Gul'dan, and vanquished the demons' leader Tichondrius, the taint on the woods still remained.\n\nThe furbolgs wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw tribe are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern Felwood and prove themselves as friends of the Timbermaw tribe will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing/resurrection knowledge with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["whisperwind grove"] = {
			name = "Whisperwind Grove",
			short = "Whisperwind Grove is a neutral town of the Emerald Circle, a largely autonomous branch of the Cenarion Circle. Whisperwind Grove is located just south of Irontree Woods in Felwood.",
			full = "Whisperwind Grove is a neutral town of the Emerald Circle, a largely autonomous branch of the Cenarion Circle. Whisperwind Grove is located just south of Irontree Woods in Felwood. Notably, the land around Whisperwind Grove has been cleansed of corruption, and it is the location of the only uncorrupted moonwell in all of Felwood.",
			source = "https://warcraft.wiki.gg/wiki/Whisperwind_Grove",
		},
		["wildheart point"] = {
			name = "Wildheart Point",
			short = "Wildheart Point is a neutral outpost of the Emerald Circle located in Felwood, east of Jaedenar.",
			full = "Wildheart Point is a neutral outpost of the Emerald Circle located in Felwood, east of Jaedenar.",
			source = "https://warcraft.wiki.gg/wiki/Wildheart_Point",
		},
	},
	-- Un'Goro Crater: 16 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Fire Plume Ridge",
			short = "Fire Plume Ridge is the volcano in the center of Un'Goro Crater. Lava flows down the sides of the mountain, where fire elementals can be found.",
			full = "Fire Plume Ridge is the volcano in the center of Un'Goro Crater. Lava flows down the sides of the mountain, where fire elementals can be found. The strongest of all fire elementals in Un'Goro, Blazerunner, lives within a cave at its peak.\n\nThe fiery mountain forms a natural border where the jungle meets the earth, scorched from lava flows. Shallow veins of magma flow beneath the bowl of the crater, heating the steam pools and geysers around Un'Goro.\n\nThe hottest place in the ridge is apparently 428,000 degrees Kraklenheit.\n\nRingo came to the ridge to explore and ended up getting lost and now suffers from heat exhaustion, he can be found in the southern cave.\n\nThe spirits of fire told him that they have been burning here for centuries, petering out and reigniting over and over again. Zekhan would like to take Queen Talanji here one day if she'd agree, to keep up good relations between the Darkspear and the Zandalari.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Fungal Rock",
			short = "Fungal Rock is a large cavern in the northeastern wall of Un'Goro Crater. The cavern is filled with gorillas, which have made their home, and Ghost Mushrooms.",
			full = "Fungal Rock is a large cavern in the northeastern wall of Un'Goro Crater. The cavern is filled with gorillas, which have made their home, and Ghost Mushrooms. Outside the entrance is a small pool of water with a waterfall, this is where A-Me 01, Karna Remtravel's mechanical ape can be found.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Golakka Hot Springs",
			short = "Golakka Hot Springs is a region in western Un'Goro Crater, just north of Terror Run. The area features geysers and pools heated by the nearby volcano.",
			full = "Golakka Hot Springs is a region in western Un'Goro Crater, just north of Terror Run. The area features geysers and pools heated by the nearby volcano. Spark Nilminer can be found at the top of a large geyser, while Maximillian of Northshire can be found at the base of the same one.\n\nSteaming Fury elementals patrol the shores of the pools.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["hall of repose ungoro crater"] = {
			name = "Hall of Repose (Un'Goro Crater)",
			short = "The Hall of Repose is the main room of the Shaper's Terrace found in Un'Goro Crater. High Cultist Herenn is located here and possesses the [Omega Rune] necessary to activate the Etymidian for [20-30] The Activation Rune.",
			full = "The Hall of Repose is the main room of the Shaper's Terrace found in Un'Goro Crater. High Cultist Herenn is located here and possesses the [Omega Rune] necessary to activate the Etymidian for [20-30] The Activation Rune.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Repose_(Un'Goro_Crater)",
		},
		["ironstone plateau"] = {
			name = "Ironstone Plateau",
			short = "Ironstone Plateau is a region in northeastern Un'Goro Crater. It is home to fledgling Pterrordax, and features several stretches of bare rock tucked on the bare edge of the crater wall.",
			full = "Ironstone Plateau is a region in northeastern Un'Goro Crater. It is home to fledgling Pterrordax, and features several stretches of bare rock tucked on the bare edge of the crater wall. Its secluded and monster-free area sometimes attracts guilds to hold guild meets there.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Lakkari Tar Pits",
			short = "The Lakkari Tar Pits are lakes of thick, foul-smelling black tar found in northern Un'Goro Crater, just south of Marshal's Refuge.",
			full = "The Lakkari Tar Pits are lakes of thick, foul-smelling black tar found in northern Un'Goro Crater, just south of Marshal's Refuge. Scavengers hang around looking for easy prey, as the tar often traps creatures in its grip. The bones of hundreds of beasts jut out from the tar's surface. The area is also inhabited by tar beasts.\n\nRare tarblossom flowers grow at the bottom of the pits. They're valued for their beauty and durability, but their being deep in the tar makes them difficult to harvest.\n\nWhile in contact with the tar, the Swimming in Tar debuff reduces movement speed by 70%.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Marshal's Refuge",
			short = "Marshal's Refuge was a neutral camp at the northern edge of Un'Goro Crater set up by Marshal Expeditions.",
			full = "Marshal's Refuge was a neutral camp at the northern edge of Un'Goro Crater set up by Marshal Expeditions.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshals stand"] = {
			name = "Marshal's Stand",
			short = "Marshal's Stand is a fortified base near the road leading from the Marshlands in Un'Goro Crater. To the north is Fire Plume Ridge, a volcano in the center of the crater.",
			full = "Marshal's Stand is a fortified base near the road leading from the Marshlands in Un'Goro Crater. To the north is Fire Plume Ridge, a volcano in the center of the crater. After leaving Marshal's Refuge, Marshal Expeditions made their way here and built this small base, making sure they won't be run off so easily again.\n\nAfter the war, the base was visited by Zekhan and Rexxar.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Stand",
		},
		["marshlands"] = {
			name = "Marshlands",
			short = "The Marshlands is a vast marsh covering much of the southeastern Un'Goro Crater.",
			full = "The Marshlands is a vast marsh covering much of the southeastern Un'Goro Crater. This is often the first area encountered when entering the crater for the first time, as entering anywhere else from Tanaris would likely end in death. The marshes are inhabited by large amounts of raptors, some normal, some poisonous.\n\nNearby on a large mound are two quest givers, Torwa Pathfinder and Garl Stormclaw, who apparently traveled here on a canoe from some other location in the crater. On the opposite side is Mor'vek, a ravasaur trainer.\n\nIn the north, Ithis Moonwarden has setup a small camp watching over young bloodpetals.\n\nThis is the only area Blue Power Crystals can be found.\n\nDuring the Primalists' attack, the area was invaded by elementals. Their presence imbued the raptors.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["mossy pile"] = {
			name = "Mossy Pile",
			short = "Mossy Pile is a small fortified camp located just northwest of Fire Plume Ridge in Un'Goro Crater. It's here that a few goblins from Gadgetzan, while working with Marshal Expeditions, exploit the area for profit.",
			full = "Mossy Pile is a small fortified camp located just northwest of Fire Plume Ridge in Un'Goro Crater. It's here that a few goblins from Gadgetzan, while working with Marshal Expeditions, exploit the area for profit.",
			source = "https://warcraft.wiki.gg/wiki/Mossy_Pile",
		},
		["roiling gardens"] = {
			name = "Roiling Gardens",
			short = "The Roiling Gardens is an area found just north of the Marshlands in Un'Goro Crater. The area has been thrown off balance with an increasing number of Bloodpetals inhabiting the place.",
			full = "The Roiling Gardens is an area found just north of the Marshlands in Un'Goro Crater. The area has been thrown off balance with an increasing number of Bloodpetals inhabiting the place. The trees are enveloped with more flowers and vines than usual. Large, sporous blossoms project themselves from the ground where they once did not. If something is not done soon, the balance of nature here will be destroyed.\n\nThis is the only area Green Power Crystals can be found.",
			source = "https://warcraft.wiki.gg/wiki/Roiling_Gardens",
		},
		["screaming reaches"] = {
			name = "Screaming Reaches",
			short = "The Screaming Reaches is the region in northwestern Un'Goro Crater, just west of Mossy Pile. This appropriately named area is filled with screeching pterrordax.",
			full = "The Screaming Reaches is the region in northwestern Un'Goro Crater, just west of Mossy Pile. This appropriately named area is filled with screeching pterrordax. In the far northwestern part of this area is another ramp, similar to the one used to enter Un'Goro, that exits into Silithus.\n\nThis is the only area Yellow Power Crystals can be found.\n\nDuring the Primalists' attack, the area was invaded by elementals. Their presence imbued the beasts of the area.",
			source = "https://warcraft.wiki.gg/wiki/Screaming_Reaches",
		},
		["shapers terrace"] = {
			name = "Shaper's Terrace",
			short = "The Shaper's Terrace is the name of two titan-related areas found in Un'Goro Crater, referring to Khaz'goroth \"The Shaper\".",
			full = "The Shaper's Terrace is the name of two titan-related areas found in Un'Goro Crater, referring to Khaz'goroth \"The Shaper\". One section, on the bluffs above and east of Marshal's Refuge, contains a Waygate connecting to Sholazar Basin. Another in the cliffs on the eastern wall of Un'Goro houses the titanic watcher Nablya, who continues Khaz'gorith's experiments on life in the crater.",
			source = "https://warcraft.wiki.gg/wiki/Shaper's_Terrace",
		},
		["slithering scar"] = {
			name = "Slithering Scar",
			short = "The Slithering Scar is a medium-sized silithid hive that takes up most of the southern Un'Goro Crater.",
			full = "The Slithering Scar is a medium-sized silithid hive that takes up most of the southern Un'Goro Crater. This hive is home to the Gorishi sect, where they're currently raising a colossus that, when fully grown, will be released into Un'Goro.\n\nThis hive once had a queen, who was summoned by messing with the Gorishi Silithid Crystal within the hive.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "Terror Run",
			short = "Terror Run is an area just west of the Slithering Scar in southwestern Un'Goro Crater. This is the only area where Red Power Crystals can be found.",
			full = "Terror Run is an area just west of the Slithering Scar in southwestern Un'Goro Crater. This is the only area where Red Power Crystals can be found.\n\nDuring the Primalists' attack, the area was invaded by elementals. Their presence imbued the beasts in the area.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
		["waygate location"] = {
			name = "Waygate (location)",
			short = "The Waygate is a portal between the southern part of Sholazar Basin and the Shaper's Terrace in Un'Goro Crater.",
			full = "The Waygate is a portal between the southern part of Sholazar Basin and the Shaper's Terrace in Un'Goro Crater. It is of titan craft and arcane power, and a piece of titan technology that is still active makes a pillar of light into a magical portal. As the twin of a machine in Un'Goro Crater, this waygate hasn't been active in seven centuries, but can be activated using the switches found in the Makers' Overlook and the Makers' Perch. The gate then becomes active and will teleport anyone to Un'Goro in an instant.\n\nFollowing the war against the Jailer, the brothers Bronzebeard visited the waygate and learned how to use it. According to Muradin Bronzebeard, the Oracles have a village not far from the Mosslight Pillar due to the presence of the Waygate.",
			source = "https://warcraft.wiki.gg/wiki/Waygate_(location)",
		},
	},
	-- Moonglade: 6 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lake Elune'ara",
			short = "Lake Elune'ara is a large body of crystal water that covers the central part of the Moonglade.",
			full = "Lake Elune'ara is a large body of crystal water that covers the central part of the Moonglade.\n\nThe mad demigod Omen, defeated many centuries ago, yet resides in Lake Elune'ara.\n\nIn Season of Discovery, [Water of Elune'ara] can be used to water Ancient Saplings all over the world.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Nighthaven",
			short = "Nighthaven is the main settlement in the Moonglade. It is a primarily night elven village that is the home to the druids of the Cenarion Circle.",
			full = "Nighthaven is the main settlement in the Moonglade. It is a primarily night elven village that is the home to the druids of the Cenarion Circle.\n\nThe village is located on the shores of Lake Elune'ara. It features night elvish architecture, some of it with stone walls. It also has a pair of moonwells. Nighthaven's location is considered remote and the village is usually sequestered to outsiders. It caters mostly to druids, who have an ability to teleport here and have access to exclusive flight masters. There are trainers for druidism and herbalism in the town, as well as a number of unique vendors, such as a specialty dressmaker, Geenia Sunshadow. The village is also home to the Nighthaven Inn, which can be visited during the Kirin Tor Tavern Crawl.\n\nThe town is the center of the Lunar Festival, and for this holiday it opens up to outsiders. The druids welcome members of both the Alliance and Horde to celebrate and shoot fireworks - a symbol of Elune's power. During the event, non-druids can also teleport here with a [Lunar Festival Invitation]. For the duration of the festival, a number of special vendors and quests can be accessed here.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["nighthaven inn"] = {
			name = "Nighthaven Inn",
			short = "Nighthaven Inn is the inn of Nighthaven. It can be visited during the Kirin Tor Tavern Crawl. The local specialty is the [Entangling Rootbeer].",
			full = "Nighthaven Inn is the inn of Nighthaven. It can be visited during the Kirin Tor Tavern Crawl. The local specialty is the [Entangling Rootbeer].",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven_Inn",
		},
		["shrine of remulos"] = {
			name = "Shrine of Remulos",
			short = "The Shrine of Remulos is a shrine dedicated to Keeper Remulos, located in western Moonglade. It also houses the night elf Tajarri, who helps young druids along in their quest for the aquatic form.",
			full = "The Shrine of Remulos is a shrine dedicated to Keeper Remulos, located in western Moonglade. It also houses the night elf Tajarri, who helps young druids along in their quest for the aquatic form.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Stormrage Barrow Dens",
			short = "The Stormrage Barrow Dens are the sacred barrow dens of the Moonglade where many of the nightelven druids slumber in the Emerald Dream.",
			full = "The Stormrage Barrow Dens are the sacred barrow dens of the Moonglade where many of the nightelven druids slumber in the Emerald Dream. The great druid Malfurion Stormrage, for whom the barrow dens are named, used to slumber deep within the dens. Clintar Dreamwalker now sleeps here.\n\nDirectly north of the barrow dens are Minions of Omen, high level wolf-like creatures. They only come out at night during the Lunar Festival. A part of the Moonkin Festival also occurs here.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.",
			full = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under the corruptive influence of the Burning Legion. However, amidst the chaos and the madness, the Timbermaw tribe escaped the darkness that had fallen on Kalimdor. In the safety of Timbermaw Hold, the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. The corruption had sunk in deep, so that even long after Illidan had consumed the source of the corruption, a powerful warlock artifact called the Skull of Gul'dan, and vanquished the demons' leader Tichondrius, the taint on the woods still remained.\n\nThe furbolgs wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw tribe are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern Felwood and prove themselves as friends of the Timbermaw tribe will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing/resurrection knowledge with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 23 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Bones of Grakkarond",
			short = "The Bones of Grakkarond lied in central Silithus. They were the huge bones of the bronze dragon Grakkarond, who was slain by Ossirian the Unscarred during the War of the Shifting Sands.",
			full = "The Bones of Grakkarond lied in central Silithus. They were the huge bones of the bronze dragon Grakkarond, who was slain by Ossirian the Unscarred during the War of the Shifting Sands. The Bones of Grakkarond are considered sacred by the Anubisath.\n\nThe dragon bones alongside the majority of Silithus were destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Bronzebeard Encampment",
			short = "Bronzebeard Encampment was located in the southern Silithus, east of the Scarab Wall.",
			full = "Bronzebeard Encampment was located in the southern Silithus, east of the Scarab Wall.\n\nThis section concerns content related to Legion.\n\nAt the end of the third invasion of the Burning Legion, the camp alongside the majority of settlements of Silithus were destroyed when Sargeras attacked Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Cenarion Hold",
			short = "Cenarion Hold was a location of utmost strategic importance in Silithus and one of the biggest druid settlements in Kalimdor -- almost as big as Moonglade itself.",
			full = "Cenarion Hold was a location of utmost strategic importance in Silithus and one of the biggest druid settlements in Kalimdor -- almost as big as Moonglade itself. The Cenarion Circle took over the duty of defending the ancient night elven settlement against the increasingly hostile and aggressive silithid and other forces that had set foot in the troubled region, establishing the Fort, after the War of the Shifting Sands to guard the imprisoned Old God C'Thun and its armies.\n\nThe settlement was reached on foot by following the well-worn track through the Un'Goro Crater northwest from the Mossy Pile. The path climbs steeply up the cliff, and switches back on itself to enter Silithus. The merchants of Cenarion Hold gladly sold their goods to any adventurer who passed through, since business was hard to come by.\n\nThis section concerns content related to Legion.\n\nThe hold was destroyed along with the rest of Silithus when Sargeras tried to destroy Azeroth at the end of the third invasion of the Burning Legion. Malfurion Stormrage reported that everyone in the hold was killed instantly. During a ceremony in Thunder Bluff, Hamuul Runetotem advocated recreating the Cenarion Hold, and some in Orgrimmar are wondering whether Cenarion Hold is needed now that C'Thun and his aqir are defeated.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "Crystal Vale",
			short = "The Crystal Vale is a valley at in the far northwestern corner of Silithus. It is populated by earth and air elementals and contains generous deposits of thorium.",
			full = "The Crystal Vale is a valley at in the far northwestern corner of Silithus. It is populated by earth and air elementals and contains generous deposits of thorium. It is also where Thunderaan is summoned to complete the Thunderfury, Blessed Blade of the Windseeker quest chain. One quest in the area is [15-30] The Twilight Mystery.\n\nThe Ravaged Twilight Camp is located in the vale.\n\nThe valley is mostly destroyed at the end of the third invasion of the Burning Legion alongside the majority of Silithus. Highlord Demitrian continued to stay in the area though.\n\nAir and earth elementals remain in the area but are chaotic from living in the long shadow of the Sword of Sargeras. The elementals chattered and rumbled with stories about the many pains of Azeroth, from centuries ago to more recent days. The tales made it clear that much shamanic work remains to be done in Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["gates of ahnqiraj subzone"] = {
			name = "Gates of Ahn'Qiraj (subzone)",
			short = "The Gates of Ahn'Qiraj is an area located right after the Scarab Wall, in southwestern Silithus.",
			full = "The Gates of Ahn'Qiraj is an area located right after the Scarab Wall, in southwestern Silithus. It became available during the Gates of Ahn'Qiraj event, allowing access to the instances of the Temple and Ruins of Ahn'Qiraj.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ahn'Qiraj_(subzone)",
		},
		["hiveashi"] = {
			name = "Hive'Ashi",
			short = "Hive'Ashi was a silithid hive located in northern Silithus. The silithid from Hive'Ashi also infested the Swarming Pillar.",
			full = "Hive'Ashi was a silithid hive located in northern Silithus. The silithid from Hive'Ashi also infested the Swarming Pillar.\n\nThe nest was destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth through Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Hive'Regal",
			short = "Hive'Regal was a silithid nest located in southern Silithus.",
			full = "Hive'Regal was a silithid nest located in southern Silithus.\n\nThe majority of the nest was destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth through Silithus. Some of it still remains though.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Hive'Zora",
			short = "Hive'Zora was a silithid nest in western Silithus.",
			full = "Hive'Zora was a silithid nest in western Silithus.\n\nThe nest was destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth through Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["magnis encampment"] = {
			name = "Magni's Encampment",
			short = "Magni's Encampment is found just west of the Sword of Sargeras in Silithus: The Wound. The Cenarion Circle and Earthen Ring have gathered here to aid Magni Bronzebeard in healing the wound left by Sargeras.",
			full = "Magni's Encampment is found just west of the Sword of Sargeras in Silithus: The Wound. The Cenarion Circle and Earthen Ring have gathered here to aid Magni Bronzebeard in healing the wound left by Sargeras.\n\nThe Titan Translocator in Magni's Encampment is used to access the Chamber of Heart an ancient titan vault found far below Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Magni's_Encampment",
		},
		["oasis inn"] = {
			name = "Oasis Inn",
			short = "The Oasis Inn is the inn of Cenarion Hold, owned by Calandrath.",
			full = "The Oasis Inn is the inn of Cenarion Hold, owned by Calandrath.\n\nIt can be visited during the Kirin Tor Tavern Crawl. The local specialty is the [Liquid Qiraj].",
			source = "https://warcraft.wiki.gg/wiki/Oasis_Inn",
		},
		["ortells hideout"] = {
			name = "Ortell's Hideout",
			short = "Ortell's Hideout is a small cave located in southeastern Silithus where Hermit Ortell resides. After Sargeras destroyed Silithus, the cave's entrance vanished.",
			full = "Ortell's Hideout is a small cave located in southeastern Silithus where Hermit Ortell resides. After Sargeras destroyed Silithus, the cave's entrance vanished. It was likely buried by an avalanche, as the mountains around the border of the zone shifted.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Ravaged Twilight Camp",
			short = "The Ravaged Twilight Camp is located at in the Crystal Vale in northwestern Silithus. It is the current home of Highlord Demitrian. A reference is made to it in State of the Cult, Volume 127.",
			full = "The Ravaged Twilight Camp is located at in the Crystal Vale in northwestern Silithus. It is the current home of Highlord Demitrian. A reference is made to it in State of the Cult, Volume 127. The camp itself did not survive Sargeras plunging the Sword of Sargeras into Silithus, forming Silithus: The Wound, but Demetrian remains.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "Scarab Dais",
			short = "The Scarab Dais is where the Scarab Gong is located, just northwest of the Scarab Wall outside of Ahn'Qiraj, in southern Silithus.",
			full = "The Scarab Dais is where the Scarab Gong is located, just northwest of the Scarab Wall outside of Ahn'Qiraj, in southern Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Scarab Wall",
			short = "The Scarab Wall lies at the southern edge of Silithus, marking the boundary between the silithid-controlled desert and the ruined city of Ahn'Qiraj, spanning from its east boundary to its west.",
			full = "The Scarab Wall lies at the southern edge of Silithus, marking the boundary between the silithid-controlled desert and the ruined city of Ahn'Qiraj, spanning from its east boundary to its west. The wall was molded from the very sands beneath it at the end of the War of the Shifting Sands, rising at least a hundred feet above the desert. Where its height ended, the magic of the bronze dragonflight took over, forming a barrier many times taller than the sandstone beneath it. The night elves named their shared creation Irana'ethil, \"Shield against the Shadow.\" The walls kept C'Thun and its crawly minions sealed within.\n\nThe opening of the Gates of Ahn'Qiraj was a World Event. While in-game a player attains the rank of [Scarab Lord] when opening the wall, it is known that either Kalahad or Shiromar was the one who rang the gong in the lore.\n\nThe Scarab Wall was one of the only two parts of Silithus to survive Sargeras's destruction of the zone, the other being Valor's Rest.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["silithus the wound"] = {
			name = "Silithus: The Wound",
			short = "Silithus: The Wound, also known as the Wound in the World, is the name given to Silithus after the dark titan plunged his sword into Kalimdor.",
			full = "Silithus: The Wound, also known as the Wound in the World, is the name given to Silithus after the dark titan plunged his sword into Kalimdor. The wake of destruction now covers the majority of the desert. Zidormi and Rhonormu make it possible to switch between old Silithus and the Wound.\n\nThe impact of the sword has caused the ground around it to always be hot.",
			source = "https://warcraft.wiki.gg/wiki/Silithus%3A_The_Wound",
		},
		["southwind village"] = {
			name = "Southwind Village",
			short = "Southwind Village was once a night elven base of operation in Silithus, but was destroyed by the qiraji during the War of the Shifting Sands.",
			full = "Southwind Village was once a night elven base of operation in Silithus, but was destroyed by the qiraji during the War of the Shifting Sands.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Staghelm Point",
			short = "Staghelm Point was a night elven tower found on the top of a peak in northeastern Silithus.",
			full = "Staghelm Point was a night elven tower found on the top of a peak in northeastern Silithus.\n\nDuring the Call of the Scarab micro-holiday, the Twilight creatures scale with player level.\n\nIt was badly damaged following Sargeras' devastation on the region. The Alliance built a base near the road leading to the ruined tower, and later the Cenarion Circle joined its rebuilding efforts.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Swarming Pillar",
			short = "The Swarming Pillar was a large silithid-infested peak in the middle of Silithus containing one of their hives, just south of Cenarion Hold.",
			full = "The Swarming Pillar was a large silithid-infested peak in the middle of Silithus containing one of their hives, just south of Cenarion Hold. It got its name from a massive swarm of small silithid that buzzed around the hive. Although being the largest, it was just one of the too many hives whose foundations were built beneath the sands of Silithus.\n\nThe silithid hive was eventually destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth through Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Twilight Base Camp",
			short = "The Twilight Base Camp was one of four Twilight's Hammer camps in Silithus.",
			full = "The Twilight Base Camp was one of four Twilight's Hammer camps in Silithus.\n\nDuring the Call of the Scarab micro-holiday, creatures scale with the player from level 60 to max level.\n\nThe camp, alongside the majority of settlements in Silithus, was destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Twilight Outpost",
			short = "The Twilight Outpost is found in the far southwestern corner of Silithus, just northwest of the Scarab Wall and west of the Bronzebeard Encampment.",
			full = "The Twilight Outpost is found in the far southwestern corner of Silithus, just northwest of the Scarab Wall and west of the Bronzebeard Encampment. During the Call of the Scarab micro-holiday, creatures scale with the player from level 60 to max level.\n\nThe original outpost, alongside the majority of settlements in Silithus, was destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth. The few survivors of the Twilight's Hammer would build a new settlement in the same spot, but their leader Michiel Voidstrider was quickly killed before he could rally the cult into action.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Twilight Post",
			short = "The Twilight Post was found in the northwest area of Silithus, far west of Cenarion Hold and northwest of Twilight Base Camp.",
			full = "The Twilight Post was found in the northwest area of Silithus, far west of Cenarion Hold and northwest of Twilight Base Camp. During the Call of the Scarab micro-holiday, creatures scale with the player from level 60 to max level.\n\nThe settlement, alongside the majority of settlements in Silithus, was destroyed at the end of the third invasion of the Burning Legion when Sargeras tried to destroy Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Twilight's Run",
			short = "Twilight's Run is a cave filled with members of the Twilight's Hammer Cult at the base of Staghelm Point in northern Silithus.",
			full = "Twilight's Run is a cave filled with members of the Twilight's Hammer Cult at the base of Staghelm Point in northern Silithus.\n\nDuring the Call of the Scarab micro-holiday in late January, the Twilight creatures scale with player level and drop event-related items.\n\nAfter Sargeras destroyed Silithus, the cave's entrance vanished. It was likely buried by an avalanche, as the mountains around the border of the zone shifted. The Alliance built a base not far from where the entrance once was.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Valor's Rest",
			short = "Valor's Rest is the name of a camp in Silithus used by both the Alliance and the Horde. The most notable feature is its graveyard. It is home to members of the Cenarion Circle and a vaguely familiar insect infestation.",
			full = "Valor's Rest is the name of a camp in Silithus used by both the Alliance and the Horde. The most notable feature is its graveyard. It is home to members of the Cenarion Circle and a vaguely familiar insect infestation. Valor's Rest can be reached easily by riding up the path in the northwest corner of the Un'Goro Crater, and it is the first thing you will see when entering Silithus.\n\nValor's Rest was one of only two parts of Silithus to survive Sargeras' destruction of the zone, the other being the Scarab Wall.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Winterspring: 23 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Ban'Thallow Barrow Den",
			short = "The Ban'Thallow Barrow Den is a barrow den located behind Starfall Village in Winterspring. The bugs appeared nearly overnight, hatching from unseen eggs and swarming the tunnels.",
			full = "The Ban'Thallow Barrow Den is a barrow den located behind Starfall Village in Winterspring. The bugs appeared nearly overnight, hatching from unseen eggs and swarming the tunnels. Luckily, there were no druids sleeping inside when the infestation occurred, although the den still contains blessed relics that hold great value to the people of Starfall Village.\n\nIt was all the few druids in Starfall could do to keep the bugs from spreading outside the den, so Wynd Nightchaser has hired goblins from Everlook who claim expertise in extermination: Rinno, Remma, and Marcy Curtainfire. He sends an adventurer to help the trio in a short questline starting with [15-30] Exterminators at Work.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["beryl egress"] = {
			name = "Beryl Egress",
			short = "Beryl Egress is a small camp situated outside of the cave of Mazthoril. Most of the camp's residents are members of the blue dragonflight, who have been forced out of their nearby cavern home.",
			full = "Beryl Egress is a small camp situated outside of the cave of Mazthoril. Most of the camp's residents are members of the blue dragonflight, who have been forced out of their nearby cavern home. The leader of the camp is Haleh, who is concerned with getting rid of Umbranse the Spiritspeaker and taking back Mazthoril.",
			source = "https://warcraft.wiki.gg/wiki/Beryl_Egress",
		},
		["caverns of consumption"] = {
			name = "Caverns of Consumption",
			short = "The Caverns of Consumption is a secret area on the northernmost point of the coast of Winterspring located at using Kalimdor's coordinates.",
			full = "The Caverns of Consumption is a secret area on the northernmost point of the coast of Winterspring located at using Kalimdor's coordinates. The [Sun Darter Hatchling] pet can be found by those who can bypass the puzzles within.\n\nEntering the cave will debuff players with Consuming Silence, preventing the use of player abilities or toys.\n\nThis is one of the secrets that counts for [Mind-Seeker].",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Consumption",
		},
		["darkwhisper gorge"] = {
			name = "Darkwhisper Gorge",
			short = "Darkwhisper Gorge is an area being used as a Twilight's Hammer recruitment and training spot. It is found in the southeastern part of Mount Hyjal.",
			full = "Darkwhisper Gorge is an area being used as a Twilight's Hammer recruitment and training spot. It is found in the southeastern part of Mount Hyjal. It was previously a subzone of Winterspring.\n\nMeanwhile the back entrance, Darkwhisper Pass, has become its more common way in.\n\nIts main entrance from Winterspring has been redecorated to match the Twilight cult's theme and appearance. This area, however, remains empty until players are sent there for quests.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr is a small base nearby an icy cavern in south-eastern Winterspring.",
			full = "Dun Mandarr is a small base nearby an icy cavern in south-eastern Winterspring. The camp is overrun by ferocious moonkin and was set up by Jaron Stoneshaper, its dwarven origin obvious from the linguistic qualities of the cave's name. Jaron had discovered a [Blue-Feathered Amulet], which enraged the wildkin and caused them to chase Jaron off and destroy his camp.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Everlook",
			short = "Everlook is a trading post run by the goblins of the Steamwheedle Cartel. It lies at the crossroads of Winterspring's main trade routes and contains a goblin laboratory.",
			full = "Everlook is a trading post run by the goblins of the Steamwheedle Cartel. It lies at the crossroads of Winterspring's main trade routes and contains a goblin laboratory.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Frostfire Hot Springs",
			short = "Frostfire Hot Springs are a series of steaming pools at the far western end of Winterspring.",
			full = "Frostfire Hot Springs are a series of steaming pools at the far western end of Winterspring. Donova Snowden, who has set up a camp nearby, is very curious about the reasons they appeared in the icy land and what power they hold. She theorizes that perhaps they came to be from demonic interference stemming from Darkwhisper Gorge far south in Winterspring.\n\nThis is also a good place to fish for Raw Nightfin Snappers and [Plated Armorfish], though the area is inhabited by the Winterfall tribe.\n\nThe Winterfall tribe still remains in control of the pool closest to Timbermaw Hold.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Frostsaber Rock",
			short = "Frostsaber Rock is a large jutting tor in the northern part of Winterspring.",
			full = "Frostsaber Rock is a large jutting tor in the northern part of Winterspring.\n\nAt the very apex of Frostsaber Rock stands Rivern Frostwind of the Wintersaber Trainers. He offers friends of the Alliance to work for him, and in exchange he will teach them how to tame and ride one of the beautiful beasts.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Frostwhisper Gorge",
			short = "Frostwhisper Gorge is a canyon in southern Winterspring, just north of Darkwhisper Gorge. It is scattered with night elven ruins both at the bottom of the gorge and at the ridges above.",
			full = "Frostwhisper Gorge is a canyon in southern Winterspring, just north of Darkwhisper Gorge. It is scattered with night elven ruins both at the bottom of the gorge and at the ridges above.\n\nSeveral of the huge Frostmaul Preservers and Frostmaul Giants reside here, as well as Ice Avatars led by Frostilicus.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["goodgrub smoking pit"] = {
			name = "Goodgrub Smoking Pit",
			short = "The Goodgrub Smoking Pit is a small quest hub located northeast of Starfall Village in Winterspring. The residents at this location encourage adventurers to slay the nearby wildlife to provide great food for them.",
			full = "The Goodgrub Smoking Pit is a small quest hub located northeast of Starfall Village in Winterspring. The residents at this location encourage adventurers to slay the nearby wildlife to provide great food for them. It was set up by Jez Goodgrub.",
			source = "https://warcraft.wiki.gg/wiki/Goodgrub_Smoking_Pit",
		},
		["hidden grove"] = {
			name = "Hidden Grove",
			short = "The Hidden Grove is a forested crater in northeastern Winterspring. The grove is surrounded on all sides by high cliffs and is virtually inaccessible.",
			full = "The Hidden Grove is a forested crater in northeastern Winterspring. The grove is surrounded on all sides by high cliffs and is virtually inaccessible. There is one entrance through a cave on the southeastern face of the ridge at . Dropping down from the top is also possible in some places, albeit very dangerous. The grove is home to many moonkin who are extremely hostile, and so most adventurers don't attempt to enter the glade.\n\nBefore the appearance of the moonkin, the Hidden Grove used to be occupied by a robust population of harmless white hares.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Ice Thistle Hills",
			short = "The Ice Thistle Hills is a large area just southeast of Everlook. It is the home of the Ice Thistle yeti, who live in and around a cave some way up in the hill, and in the surrounding area.",
			full = "The Ice Thistle Hills is a large area just southeast of Everlook. It is the home of the Ice Thistle yeti, who live in and around a cave some way up in the hill, and in the surrounding area. Adventurers often come here to find Thick Yeti Furs and Pristine Yeti Horns for their quests.\n\nThis area is a popular place to farm leather, as the yeti also drop money and \"humanoid\" drops (excepting cloth) such as poor quality armor. One can also find Icecaps around the outdoor area, Thorium veins inside the cave, and, if one is very lucky, a [Black Lotus] at the lip of the cave.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lake Kel'Theril",
			short = "Lake Kel'Theril is a small frozen lake in central Winterspring. The shores of the lake are home to the Ruins of Kel'Theril, which along with the lake itself is populated by many tormented spirits of the Highborne.",
			full = "Lake Kel'Theril is a small frozen lake in central Winterspring. The shores of the lake are home to the Ruins of Kel'Theril, which along with the lake itself is populated by many tormented spirits of the Highborne. Adventurers came here to hunt ectoplasm for their tier 0.5 armor quests.\n\nDuring the periodic Elemental Invasions, Princess Tempestria spawned here.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["laughing yeti"] = {
			name = "Laughing Yeti",
			short = "The Laughing Yeti is the inn of Everlook, owned by Himmik.",
			full = "The Laughing Yeti is the inn of Everlook, owned by Himmik.\n\nIt can be visited during the Kirin Tor Tavern Crawl. The local specialty is the [Sparkling Snowplum Brandy].",
			source = "https://warcraft.wiki.gg/wiki/Laughing_Yeti",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "Mazthoril is a huge and deep icy cavern -- populated by blue dragons -- located near the central part of Winterspring, not far from Lake Kel'Theril or Everlook.",
			full = "Mazthoril is a huge and deep icy cavern -- populated by blue dragons -- located near the central part of Winterspring, not far from Lake Kel'Theril or Everlook.\n\nPerhaps Malygos's last sane act was aiding in the creation of the World Tree over the second Well of Eternity and placing many of his surviving dragons nearby in the caverns of Mazthoril to hold eternal vigil over the sacred site. Although the tree is watched over by four of the dragonflights, it is the blue dragonflight that is particularly devoted to this cause, and while their numbers here are not large, they guard the tree from lower on the mountainside in their caverns.\n\nThe blue dragons in, are near Hyjal, are primarily on watch for activity from the black dragonflight, although there have recently been concerns that the blue dragonflight will be needed to assist the dragons at the Summit if the demons in Darkwhisper Gorge attack. To this end, the blue dragonflight organizes an army here, led by the dragonspawn General Cobaltann, to protect the world from the increasing threat of the black dragons. Specifically, Cobaltann focuses on the protection of dragon eggs, which are being stolen by the blacks for some evil purpose.\n\nThe goblins of Everlook recently discovered a new mine to the south of their city, not far from the dragon caves of Mazthoril. This mine is valuable due to a large amount of arcanite within it, but thus far it proves inaccessible. While not part of the blue dragon's cave complex, the dragons are territorial, and so the goblins are looking for a hero that can find a way to convince the blue dragonflight to allow them access to the mine, in exchange of a nice reward of course.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Moon Horror Den",
			short = "Moon Horror Den is a small cave inhabited by Raging Owlbeasts. However, they may not always be there, as many players complete Wild Guardians.",
			full = "Moon Horror Den is a small cave inhabited by Raging Owlbeasts. However, they may not always be there, as many players complete Wild Guardians. It is situated quite close to Everlook, just a short walk to the northeast from the city gates. Despite its apparent closeness to the Winterfall Village however, the mountain itself blocks a direct path and a long ride around is needed to head further south from the cave.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Owl Wing Thicket",
			short = "Owl Wing Thicket is a series of caves in southern Winterspring. They host a large number of berserk, moontouched, and crazed owlbeasts.",
			full = "Owl Wing Thicket is a series of caves in southern Winterspring. They host a large number of berserk, moontouched, and crazed owlbeasts. It is here that the ancient Guardians of Elune tell how the moonkin came into the world (in a quest chain exclusive to the Alliance), guided by Ranshalla.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Ruins of Kel'Theril",
			short = "The Ruins of Kel'Theril are the remnants of a great night elven city.",
			full = "The Ruins of Kel'Theril are the remnants of a great night elven city. It was destroyed long ago during the Great Sundering, and now lies in complete ruin, haunted by the tormented spirits of the Highborne who did not survive the disaster. The ruins lie on the edges of Lake Kel'Theril in central Winterspring.\n\nThere was a Remorseful Highborne here that gave a quest to Alliance players.\n\nNew undead mobs are here now. In addition to the night elven spirits that still inhabit the northern section of ruins, high elven ghosts now inhabit the eastern section (Betrayed Rangers and Archmage Maenius) while blood elven wretched inhabit the western section (Wretched Spectres). The Emerald Circle druid Kelek Skykeeper, waiting on the shores of Lake Kel'Theril, sends heroes off on a quest that ultimately describes how generations of elves were destroyed by the [Crystal of Zin-Malor].",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["snowden chalet"] = {
			name = "Snowden Chalet",
			short = "Snowden Chalet is located due south of Timbermaw Hold in Winterspring. It serves as a camp for Donova Snowden and Witch Doctor Mau'ari who both offer quests.",
			full = "Snowden Chalet is located due south of Timbermaw Hold in Winterspring. It serves as a camp for Donova Snowden and Witch Doctor Mau'ari who both offer quests.",
			source = "https://warcraft.wiki.gg/wiki/Snowden_Chalet",
		},
		["starfall village"] = {
			name = "Starfall Village",
			short = "Starfall Village (or just Starfall) is a small night elven settlement of Alliance vendors and quest givers in Winterspring, the only Alliance settlement in the region.",
			full = "Starfall Village (or just Starfall) is a small night elven settlement of Alliance vendors and quest givers in Winterspring, the only Alliance settlement in the region. It is found along the main road, northwest of Everlook and south of Frostsaber Rock. It contains a barrow den known as the Ban'Thallow Barrow Den, a night elven lodge, and a smaller house.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Timbermaw Hold",
			short = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.",
			full = "Timbermaw Hold is the capital of the Timbermaw tribe of furbolgs. It is located in north east Felwood and includes the tunnel that connects Felwood with Moonglade and Winterspring.\n\nWhen the corruption of the Burning Legion crept into the sacred forests of Kalimdor, the furbolgs fell under the corruptive influence of the Burning Legion. However, amidst the chaos and the madness, the Timbermaw tribe escaped the darkness that had fallen on Kalimdor. In the safety of Timbermaw Hold, the furbolgs of the Timbermaw tribe weathered the storm, yet they were forced to watch helplessly as the forest they had loved so much was slowly turned into a twisted, festering perversion of its former self. The corruption had sunk in deep, so that even long after Illidan had consumed the source of the corruption, a powerful warlock artifact called the Skull of Gul'dan, and vanquished the demons' leader Tichondrius, the taint on the woods still remained.\n\nThe furbolgs wary of all strangers, fearing that they may mistake them for their corrupted brethren and attack. However, the Timbermaw tribe are painfully aware that they will not last on their own; adventurers who seek out Timbermaw Hold in northern Felwood and prove themselves as friends of the Timbermaw tribe will learn that the furbolgs value their friends above all else. Though they possess no fine jewels or any worldly riches, the Timbermaw's shamanistic tradition is still strong. They know much about the art of crafting armors from animal hides, and they are more than happy to share their healing/resurrection knowledge with friends of their tribe. The Timbermaw's main concerns are putting an end to their corrupted brethren's suffering and finding a cure to heal the wounds the corruption of Felwood has inflicted upon the land, so that one day, the ancient forests will once again resound with the peaceful chants and the soft laughter of the children of the forest.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Timbermaw Post",
			short = "Timbermaw Post is a small furbolg camp located southeast across the road from the Frostfire Hot Springs, and west of Lake Kel'Theril.",
			full = "Timbermaw Post is a small furbolg camp located southeast across the road from the Frostfire Hot Springs, and west of Lake Kel'Theril. Although the name suggests that the camp was originally held by the Timbermaw tribe, it is now in complete control the corrupted furbolgs of the Winterfall tribe.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Winterfall Village",
			short = "Winterfall Village is a large village of corrupted furbolgs in the far eastern area of Winterspring, near Everlook.",
			full = "Winterfall Village is a large village of corrupted furbolgs in the far eastern area of Winterspring, near Everlook. The village was ruled by High Chief Winterfall, who resided in a small cave at the very top of the settlement. It appears that High Chief Winterfall's position has been taken by Grolnar the Berserk, who now resides in the former chieftain's cave.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Stormwind City: 39 subzones
	[1453] = {
		["canals stormwind city"] = {
			name = "Canals (Stormwind City)",
			short = "The Canals, located in the Canal District, are a series of waterways that wind their way through Stormwind City, separating each of its various districts.",
			full = "The Canals, located in the Canal District, are a series of waterways that wind their way through Stormwind City, separating each of its various districts. While these canals are mostly used for thoroughfare, they do house a few shops overlooking the marble pathways and docks, and it is a popular area for fishermen to spend time hauling small catches. It also houses the Stormwind Stockade.\n\nAdventurers should be wary of falling into the canals, as there have been reports of a giant albino crocolisk roaming them.\n\nAfter the devastation of the First War, the canals had been left clogged with stones, lumber and human bodies. The forces of the Alliance of Lordaeron took care of respectfully clearing the canals and burying the corpses once they retook the city.",
			source = "https://warcraft.wiki.gg/wiki/Canals_(Stormwind_City)",
		},
		["cathedral of light"] = {
			name = "Cathedral of Light",
			short = "Cathedral of Light (or Stormwind Cathedral) in Cathedral Square in Stormwind City is the most striking monument of the Church of the Holy Light.",
			full = "Cathedral of Light (or Stormwind Cathedral) in Cathedral Square in Stormwind City is the most striking monument of the Church of the Holy Light. The Cathedral stands as a home to high-ranking members of the Church and a sacred place for all followers of the Light on Azeroth; it is also the base of operations of the Order of the Silver Hand in the kingdom. It is described as an elegant and peaceful place, inviting for prayer and reflection, and as a sanctuary where one can meditate on the Light's mysteries. It is also the center of all healing practices in the city. The cathedral's catacombs are the resting place of the honored dead: priests, war heroes, paladins, and others.\n\nPriests and paladins travel to the cathedral from far and wide seeking training and wisdom from their resident counterparts, training their skills and researching great truths behind the walls of the Cathedral. High Priestess Laurena is the highest-ranking priest trainer in Stormwind City, Lord Grayson Shadowbreaker is one of the foremost human paladins of the Alliance and the chief paladin in Stormwind, and Duthorian Rall is one of Stormwind City's most influential paladins.\n\nWhile not barred from the edifice, void elves are not welcomed warmly here. They are even invited to leave as they are not considered appropriate, which is the complete opposite of the Lightforged draenei who are well received.",
			source = "https://warcraft.wiki.gg/wiki/Cathedral_of_Light",
		},
		["cathedral square"] = {
			name = "Cathedral Square",
			short = "Cathedral Square (also called the Holy District and Cathedral District) in Stormwind City is so named for the mighty Cathedral of Light which stands as the greatest monument to the Holy Light in Azeroth and dominating its surroundings.",
			full = "Cathedral Square (also called the Holy District and Cathedral District) in Stormwind City is so named for the mighty Cathedral of Light which stands as the greatest monument to the Holy Light in Azeroth and dominating its surroundings. The cathedral is the center of the religion of Light and is thus home to paladin and priest trainers, as well as a first aid trainer. To get to Cathedral Square, one can head northeast from Lion's Rest, northwest from the Trade District, or southeast from the Dwarven District.\n\nStormwind citizens often congregate in the Square for conversation, exchange of ideas, and the occasional swiped apple. It includes selected shops as well as the headquarters of powerful organizations such as the Argent Dawn (now the Argent Crusade). It is also an important civic center, housing City Hall and the orphanage. The extensive Stormwind City Cemetery lies to the north of the square.\n\nThe Cathedral Square is regularly visited by school children and their School Mistress Miss Danna who presents it as the center of spiritual enlightenment of the city, and the place where paladins and priests train and study in the research of great truths behind the walls of the Cathedral.",
			source = "https://warcraft.wiki.gg/wiki/Cathedral_Square",
		},
		["champions hall"] = {
			name = "Champions' Hall",
			short = "The Champions' Hall is the officer's barracks for the Alliance in Stormwind City. It is located in the south of the Old Town.",
			full = "The Champions' Hall is the officer's barracks for the Alliance in Stormwind City. It is located in the south of the Old Town.\n\nInside the Hall are vendors who sell PvP reward gear for members of the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["command center"] = {
			name = "Command Center",
			short = "The Alliance Command Center is the base of operations for Stormwind's army officers, warrior trainers and hunter trainers.",
			full = "The Alliance Command Center is the base of operations for Stormwind's army officers, warrior trainers and hunter trainers. Though these barracks normally houses a large number of soldiers and commanders, most of the city's army has been sent away to distant battlefields, and the Command Center keeps only a skeleton crew of hardened veterans to train the city's militia. The four famous trainers are Ander Germaine, Wu Shen, Ilsa Corbin, and Wulf Hansreim, with Ander having the responsibility of training and coordinating the warriors, and Wulf being in command of the hunters.\n\nNo reason is given. Presumably this is a retcon.\n\nNow the Command Center houses more hunter trainers on the ground floor, as well as [Justice Points] and [Valor Points] quartermasters.",
			source = "https://warcraft.wiki.gg/wiki/Command_Center",
		},
		["cut throat alley"] = {
			name = "Cut-Throat Alley",
			short = "Cut-Throat Alley is a currently unpopulated alley of the city of Stormwind. The alley is technically located in the Dwarven District; however, it does not share the smoggy ambiance of the District.",
			full = "Cut-Throat Alley is a currently unpopulated alley of the city of Stormwind. The alley is technically located in the Dwarven District; however, it does not share the smoggy ambiance of the District.\n\nCut-Throat Alley can only be reached on foot by passing through a shop called the Shady Lady, on the Dwarven side of the Canals just south of the footbridge from Cathedral Square; its coordinates are . The alley's only features are a number of crates and barrels, and the only accessible buildings from it are that shop and an empty two-story, one-bedroom residence. It does not connect to the rest of the Dwarven District.",
			source = "https://warcraft.wiki.gg/wiki/Cut-Throat_Alley",
		},
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "The Deeprun Tram (or simply the Tram) is a long, fully enclosed, underground (and partially underwater) set of double tracks upon which rolls two sets of three wagons, all credited to the gnomes' technical engineering.",
			full = "The Deeprun Tram (or simply the Tram) is a long, fully enclosed, underground (and partially underwater) set of double tracks upon which rolls two sets of three wagons, all credited to the gnomes' technical engineering. The service is fast and smooth, and is provided free of charge to travelers between the Alliance-aligned cities of Ironforge and Stormwind City. To keep the tram running smoothly and safely, there are gnomes that work on it daily. As such, any problems with it can be quickly addressed. The underwater section of the tram is, in fact, a subterranean lake.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["dwarven district"] = {
			name = "Dwarven District",
			short = "The Dwarven District lies in the northern corner of Stormwind City. Here, the dwarves of Ironforge established an enclave after the Second War to house all the workers sent by King Magni.",
			full = "The Dwarven District lies in the northern corner of Stormwind City. Here, the dwarves of Ironforge established an enclave after the Second War to house all the workers sent by King Magni. The forges in the district produce a constant haze, supplemented by the constant strokes of smiths' hammers. Hunters will find a place to stay within the Hunter's Guild, located in this area. Profession trainers for mining, blacksmithing, and engineering, and corresponding forges and anvils can also be found here. The Stormwind City end of the Deeprun Tram line is accessible through a tunnel on the east side of the district.\n\nTo get to the Dwarven District, you can head northeast from Cathedral Square, northwest from Old Town, west from Stormwind Keep, or get off the Deeprun Tram at the Stormwind City station.\n\nDuring the War Against the Nightmare, while the Emerald Nightmare's mist enveloped Stormwind City, noises and sounds of desperate struggle could be heard from the Dwarven District, as the dwarves were still fighting the invaders.",
			source = "https://warcraft.wiki.gg/wiki/Dwarven_District",
		},
		["eastern earthshrine"] = {
			name = "Eastern Earthshrine",
			short = "The Eastern Earthshrine is a ritual circle erected by the Earthen Ring for use by the Alliance. It is located in the city of Stormwind, in the middle of a lake northwest of Stormwind Keep.",
			full = "The Eastern Earthshrine is a ritual circle erected by the Earthen Ring for use by the Alliance. It is located in the city of Stormwind, in the middle of a lake northwest of Stormwind Keep. Its Horde counterpart is the Western Earthshrine in Orgrimmar.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Earthshrine",
		},
		["forge stormwind"] = {
			name = "Forge (Stormwind)",
			short = "The Forge is a small blacksmith shop behind the main building of the Stormwind Embassy.",
			full = "The Forge is a small blacksmith shop behind the main building of the Stormwind Embassy.",
			source = "https://warcraft.wiki.gg/wiki/Forge_(Stormwind)",
		},
		["gryphon roost"] = {
			name = "Gryphon Roost",
			short = "The Gryphon Roost is the location of Stormwind City's flight master Dungar Longdrink, gryphon vendor Tannec Stonebeak and riding trainer Bralla Cloudwing, located just off the Trade District, and houses the city's gryphons, raised by the two Wildhammer dwarves.",
			full = "The Gryphon Roost is the location of Stormwind City's flight master Dungar Longdrink, gryphon vendor Tannec Stonebeak and riding trainer Bralla Cloudwing, located just off the Trade District, and houses the city's gryphons, raised by the two Wildhammer dwarves.",
			source = "https://warcraft.wiki.gg/wiki/Gryphon_Roost",
		},
		["lions rest"] = {
			name = "Lion's Rest",
			short = "It is a peaceful place dedicated to reflection which commemorates the late King Varian Wrynn as well as those who fell in battle to defend the Alliance.",
			full = "It is a peaceful place dedicated to reflection which commemorates the late King Varian Wrynn as well as those who fell in battle to defend the Alliance. The monument there does not contain the body of the king, as it could not be recovered. King Anduin Wrynn often uses this place to address his people on solemn occasions.\n\nThe Stormwind City Guards describe it as a place of contemplation and remembrance, a tranquil park dedicated in honor of those who have made the ultimate sacrifice on behalf of the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Lion's_Rest",
		},
		["mage quarter"] = {
			name = "Mage Quarter",
			short = "The Mage Quarter (also called the Mage District or the Mage's District) lies in the southern corner of Stormwind City.",
			full = "The Mage Quarter (also called the Mage District or the Mage's District) lies in the southern corner of Stormwind City. The infamous Slaughtered Lamb tavern is located there, as well as the Wizard's Sanctum, the portal room to most of the major Alliance cities. To get to the Mage Quarter, visitors can travel southwest across the Canals from either Cathedral Square, Lion's Rest, or the Trade District.\n\nWithin the Wizard's Sanctum, the kingdom's mages study the arts of arcane magic, while their community have a task to ensure the safety of the capital and its lands. The Slaughtered Lamb serves as a sanctum to the warlock coven of Stormwind and is used as training grounds for new recruits. Throughout the rest of the quarter, herbalism, alchemy, and tailoring related stores can be found.",
			source = "https://warcraft.wiki.gg/wiki/Mage_Quarter",
		},
		["northern elwynn mountains"] = {
			name = "Northern Elwynn Mountains",
			short = "The Northern Elwynn Mountains is an area of Stormwind City, directly north of Stormwind Harbor. Besides the Harbor, it is also adjacent to Stormwind City Outskirts and Elwynn Forest.",
			full = "The Northern Elwynn Mountains is an area of Stormwind City, directly north of Stormwind Harbor. Besides the Harbor, it is also adjacent to Stormwind City Outskirts and Elwynn Forest. The Skyfire, refurbished as an aircraft carrier, lies hovering in this area.",
			source = "https://warcraft.wiki.gg/wiki/Northern_Elwynn_Mountains",
		},
		["old barracks"] = {
			name = "Old Barracks",
			short = "The Old Barracks was displayed as a subzone when in any part of the former Park. It was involved in the quest The Old Barracks.",
			full = "The Old Barracks was displayed as a subzone when in any part of the former Park. It was involved in the quest The Old Barracks.\n\nThe only NPCs found here aside from the occasional Stormwind Guard was Caretaker Folsom. Upon reaching the area, Janey Anship would say, \"The Park's been ruined... we'll have to go another way, today. Miserable dragon!\"\n\nIt was located behind the Park, and was added with Stormwind Harbor. In a sense, it was never old.",
			source = "https://warcraft.wiki.gg/wiki/Old_Barracks",
		},
		["old town"] = {
			name = "Old Town",
			short = "Old Town is Stormwind City's oldest section, and many parts of it still predate the reconstruction of the city after its razing by the orcs during the events of the First War.",
			full = "Old Town is Stormwind City's oldest section, and many parts of it still predate the reconstruction of the city after its razing by the orcs during the events of the First War. As the district had not been badly ravaged, it had never needed true rebuilding. Consequently, less attention had been paid to its upkeep since then, and so while preserved, it was not nearly as pristine as the rest of the capital. It is a rustic, downtrodden place, where the streets are described as far dirtier and smellier than the other districts. It is also the residential area for most of the poor folk of the city, as beggars, thieves, and poor people can be found there.\n\nTo get to the Old Town, you can head northeast from the Trade District, south from Stormwind Keep, or southeast from the Dwarven District.\n\nIn the district, the Command Center is the base of operations for Stormwind's army officers, which include the Champions' Hall, the army's barracks, open training grounds, stables, and the headquarters of the SI:7, a secretive military force of Stormwind's sovereign monarch which acts as the Alliance's intelligence agency under the lead of Spymaster Mathias Shaw.\n\nDuring the War Against the Nightmare, while the Emerald Nightmare's mist enveloped Stormwind City, noises could be heard from the Old Town. In the district, the bodies of citizens could be found across the streets with an odor of decay stronger than before.\n\nThe Twilight's Blade infiltrated Old Town and attempted to recruit the citizens of Stormwind, but were stopped by Magister Umbric and adventurers.",
			source = "https://warcraft.wiki.gg/wiki/Old_Town",
		},
		["olivias pond"] = {
			name = "Olivia's Pond",
			short = "Olivia's Pond is a small body of water located in the Stormwind City Outskirts. It is presumably named after Olivia Jayne, a draenei girl who can be seen walking along the lakeside.",
			full = "Olivia's Pond is a small body of water located in the Stormwind City Outskirts. It is presumably named after Olivia Jayne, a draenei girl who can be seen walking along the lakeside. Not far from the pond lie the fields and barns of Wollerton Stead, as well as the Stormwind Embassy.\n\nThe pond is restocked with [Crystal Bass] every year. It is also part of a number of annual celebrations and holidays, including Love is in the Air, where rosewood gondolas wander the pond.\n\nFollowing the War of the Thorns in 33 ADP, night elf refugees established a camp on the shore of the pond.",
			source = "https://warcraft.wiki.gg/wiki/Olivia's_Pond",
		},
		["park"] = {
			name = "Park",
			short = "The Park used to be the district located in the western corner of Stormwind City.",
			full = "The Park used to be the district located in the western corner of Stormwind City. It was once a place devoted to leisure activities for Stormwind's populace until it became a refuge for visiting night elves, who found the comforting presence of nature a welcome respite from the vast stone thoroughfares of Stormwind proper. It was the only place in the Eastern Kingdoms where druid trainers resided. The night elves created a Moonwell in the center of the park square.\n\nTo get to the Park, one would have headed southwest from Cathedral Square or northwest from the Mage Quarter.\n\nWhen he attacked the city, the druid trainer Sheldras Moontree, priest trainer Nara Meideros, and Argos Nightwhisper were the only ones known to escape alive, with the rest unaccounted for. They relocated down to Stormwind Harbor. Lion's Rest was finally built on its ruins.",
			source = "https://warcraft.wiki.gg/wiki/Park",
		},
		["petitioners chamber"] = {
			name = "Petitioner's Chamber",
			short = "The Petitioner's Chamber (aka Hall of Petitioners) is the first room to the right when ascending the ramp into Stormwind Keep. This is where the public waits when they have sought an audience.",
			full = "The Petitioner's Chamber (aka Hall of Petitioners) is the first room to the right when ascending the ramp into Stormwind Keep. This is where the public waits when they have sought an audience. There are currently three public attendants in the room, including Caledra Dawnbreeze, Count Remington Ridgewell and Bishop DeLavey.",
			source = "https://warcraft.wiki.gg/wiki/Petitioner's_Chamber",
		},
		["pig and whistle tavern"] = {
			name = "Pig and Whistle Tavern",
			short = "The Pig and Whistle Tavern is a tavern and inn in Stormwind City. Located in the district known as Old Town, the Pig and Whistle is home away from home for the weary Alliance traveler.",
			full = "The Pig and Whistle Tavern is a tavern and inn in Stormwind City. Located in the district known as Old Town, the Pig and Whistle is home away from home for the weary Alliance traveler. Kendor Kabonka can be found here, as well as soldiers recalling the First and Second Wars.\n\nDuring the Burning Legion's third invasion, the tavern was taken by the Veiled Hand cultists including Althea Ebonlocke. She was killed by Garona Halforcen and the Shadow of the Uncrowned. Several fel braziers could be seen.",
			source = "https://warcraft.wiki.gg/wiki/Pig_and_Whistle_Tavern",
		},
		["royal gallery"] = {
			name = "Royal Gallery",
			short = "The Royal Gallery was a little room beyond the small courtyard park of Stormwind Keep, next to the Royal Library.",
			full = "The Royal Gallery was a little room beyond the small courtyard park of Stormwind Keep, next to the Royal Library. The gallery featured fine art and grandiose statues of illustrious personas such as Mara Fordragon, King Llane, and Daelin Proudmoore.",
			source = "https://warcraft.wiki.gg/wiki/Royal_Gallery",
		},
		["royal library"] = {
			name = "Royal Library",
			short = "The Royal Library (or the Stormwind Library) of Stormwind City is located inside Stormwind Keep.",
			full = "The Royal Library (or the Stormwind Library) of Stormwind City is located inside Stormwind Keep. There is an extensive collection of scrolls, tomes, books, and texts on various subjects, and adventurers from all races of the Alliance may come here to peruse the lore. Milton Sheaf seems to be the head librarian.\n\nHarrison Jones teaches archaeology in the library.",
			source = "https://warcraft.wiki.gg/wiki/Royal_Library",
		},
		["si 7 stormwind city"] = {
			name = "SI:7 (Stormwind City)",
			short = "SI:7 is the main headquarters building of the same-named organization. Leaders of the organization are located here, in the Old Town of Stormwind City.",
			full = "SI:7 is the main headquarters building of the same-named organization. Leaders of the organization are located here, in the Old Town of Stormwind City.\n\nDuring the Burning Legion's third invasion, the building was infiltrated by the agents of the Uncrowned twice in order to reveal Detheroc and find Mathias Shaw.",
			source = "https://warcraft.wiki.gg/wiki/SI%3A7_(Stormwind_City)",
		},
		["slaughtered lamb"] = {
			name = "Slaughtered Lamb",
			short = "The Slaughtered Lamb is a seedy pub in the Mage Quarter of Stormwind City. The top floor is empty except for the bartender Jarel Moor, who advises patrons to \"stay away from the shadows\".",
			full = "The Slaughtered Lamb is a seedy pub in the Mage Quarter of Stormwind City. The top floor is empty except for the bartender Jarel Moor, who advises patrons to \"stay away from the shadows\".",
			source = "https://warcraft.wiki.gg/wiki/Slaughtered_Lamb",
		},
		["stormwind city cemetery"] = {
			name = "Stormwind City Cemetery",
			short = "The Stormwind City Cemetery is a large graveyard located to the north of Cathedral Square, nestled on the edge of Stormwind Lake, within Stormwind City.",
			full = "The Stormwind City Cemetery is a large graveyard located to the north of Cathedral Square, nestled on the edge of Stormwind Lake, within Stormwind City. It contains a large number of graves and also a tomb very similar to Uther's.\n\nAmong those buried here is Queen Tiffin Ellerian Wrynn, wife of King Varian.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_City_Cemetery",
		},
		["stormwind city outskirts"] = {
			name = "Stormwind City Outskirts",
			short = "The Stormwind City Outskirts is a small rural area outside the walls of Stormwind, accessable from the Dwarven District. There is a pond and a small farmhouse located in this area.",
			full = "The Stormwind City Outskirts is a small rural area outside the walls of Stormwind, accessable from the Dwarven District. There is a pond and a small farmhouse located in this area.\n\nAfter the ending of the third invasion of the Burning Legion, a new embassy was constructed in the outskirts.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_City_Outskirts",
		},
		["stormwind embassy"] = {
			name = "Stormwind Embassy",
			short = "The Stormwind Embassy is a building in Stormwind City that serves as a meeting point for the leadership of the Alliance and as headquarters for its allied races.",
			full = "The Stormwind Embassy is a building in Stormwind City that serves as a meeting point for the leadership of the Alliance and as headquarters for its allied races.\n\nA forge and a mining trainer can also be found behind the embassy proper.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Embassy",
		},
		["stormwind harbor"] = {
			name = "Stormwind Harbor",
			short = "Stormwind Harbor is a large port and shipyard, consisting of a series of wharfs, dry docks, and fortifications located in the northwestern area of Stormwind City, with the access point set between Lion's Rest and Cathedral Square.",
			full = "Stormwind Harbor is a large port and shipyard, consisting of a series of wharfs, dry docks, and fortifications located in the northwestern area of Stormwind City, with the access point set between Lion's Rest and Cathedral Square. The harbor serves as a major strategic base for both the kingdom of Stormwind and the Alliance navy. Here, many Alliance warships are constructed and fleets assembled; it is likely the largest and most important Alliance naval base in the Great Sea and potentially beyond. From a civilian perspective, transport ships regularly sail from the harbor to numerous other destinations across Azeroth, such as Boralus in Kul Tiras, and Valiance Keep in Northrend.\n\nThe harbor has been expanded in recent years and is much safer to enter than in the past. It is heavily fortified to protect against attack, presumably by the Horde, whose navy is also known to operate off the western coast of the Eastern Kingdoms. To this end, there are numerous tiered plateaus leading to the city proper, upon which are stationed articles of heavy artillery in the form of cannons (whether on the ground or mounted in towers). Additionally, on the lower tiers, numerous ballistae and steam tanks can be found aimed out to sea.\n\nThe Stormwind Harbor Guards is a military subgroup of the Stormwind City Guard, operating and patrolling the Stormwind Harbor. It is necessary for a crew to have regulatory papers to moor at Stormwind Harbor. While pirates are usually killed on sight by the Stormwind Army, in very rare cases, they may obtain a royal pardon for past crimes if they manage to accomplish a mission of great importance to the kingdom. If successful, they will be allowed to moor at the kingdom's harbor.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Harbor",
		},
		["stormwind keep"] = {
			name = "Stormwind Keep",
			short = "The mighty Stormwind Keep (also called Stonewind Keep, Castle Stormwind, stronghold of Stormwind, Stormwind Castle, and after its reconstruction sometimes referred as Castle of New Stormwind) is the seat of power of the human kingdom of Stormwind.",
			full = "The mighty Stormwind Keep (also called Stonewind Keep, Castle Stormwind, stronghold of Stormwind, Stormwind Castle, and after its reconstruction sometimes referred as Castle of New Stormwind) is the seat of power of the human kingdom of Stormwind. This keep is the residence of the Stormwindian kings, currently King Anduin Wrynn. The royal court as well as some of the nobles of the kingdom are also here.\n\nThe Keep offers a view of the whole city, so that the king can watch over the masses, and provide a powerful reminder of what deserves to be defended. Citizens make good use of the garden and the Royal Library, strolling the grounds and reading, and it has private areas - the king's rooms, guest quarters for prominent visitors, and a small royal armory for extremely rare pieces. The keep has its own personal contingent of fiercely devoted guards but also a considerable number of agents, posing as lesser noblemen or servants to the crown. There are also multiple secret passages.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Keep",
		},
		["stormwind lake"] = {
			name = "Stormwind Lake",
			short = "The Stormwind Lake is the most prominent feature of a new park-like district in Stormwind City opened in the northeastern part of the city, behind the Cathedral of Light.",
			full = "The Stormwind Lake is the most prominent feature of a new park-like district in Stormwind City opened in the northeastern part of the city, behind the Cathedral of Light. The Stormwind City Cemetery surrounds the northern part of the lake.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Lake",
		},
		["stormwind stockade"] = {
			name = "Stormwind Stockade",
			short = "Stormwind Stockade, aka the Stormwind Stockades and The Stockade, is a high-security prison complex, hidden beneath the canal district of Stormwind City.",
			full = "Stormwind Stockade, aka the Stormwind Stockades and The Stockade, is a high-security prison complex, hidden beneath the canal district of Stormwind City. Presided over by Warden Thelwater, the Stockade is home to petty crooks, political insurgents, murderers, and a score of the most dangerous criminals in the land. The stockade allowed visitors for the prisoners.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Stockade",
		},
		["stormwind stockade classic"] = {
			name = "Stormwind Stockade",
			short = "Stormwind Stockade, aka The Stockade, is a heavily guarded prison in the middle of Stormwind City.",
			full = "Stormwind Stockade, aka The Stockade, is a heavily guarded prison in the middle of Stormwind City. A large number of dangerous criminals, including some criminal masterminds and Defias mercenaries, are currently being held in the stockade. However, not so long ago, there was a revolt inside the dungeon, and the prisoners now keep the Stockade under their control.\n\nRecommended group composition is a competent and reasonably balanced group of players around level 27, with a decent level 27, at least, tank or very competent players for the final mini-boss.",
			source = "https://warcraft.wiki.gg/wiki/Stormwind_Stockade_(Classic)",
		},
		["trade district"] = {
			name = "Trade District",
			short = "The Trade District (also referred to as the Bazaar District) is just inside Stormwind City from the main gate. It is the place in the city where you can get most goods.",
			full = "The Trade District (also referred to as the Bazaar District) is just inside Stormwind City from the main gate. It is the place in the city where you can get most goods. The Guild Master is to the left in the Visitor's Center when you come in and can help you make a guild or a guild tabard. The goods that are sold in the Trade District are cheese, arcane goods and reagents, general goods, flowers, cloth/leather/mail armor, bows, guns, and clothes. The bank, mailbox, and inn are on the southwest side of the Trade District. The Gryphon Master is up a ramp on the east side.\n\nAlso, a flight trainer and flying mount vendor have been added to the area that houses the flight master.\n\nTo get to the Trade District, you can head northeast from the Valley of Heroes, southwest from Old Town, southeast from the Cathedral Square, or northeast from the Mage Quarter.\n\nDuring the War Against the Nightmare, while the Emerald Nightmare's mist enveloped Stormwind City, the Trade District was plunged into darkness.",
			source = "https://warcraft.wiki.gg/wiki/Trade_District",
		},
		["training hall"] = {
			name = "Training Hall",
			short = "The Training Hall is located in the Old Town of Stormwind City. It is the repurposed Command Center.",
			full = "The Training Hall is located in the Old Town of Stormwind City. It is the repurposed Command Center.",
			source = "https://warcraft.wiki.gg/wiki/Training_Hall",
		},
		["valley of heroes"] = {
			name = "Valley of Heroes",
			short = "The Valley of Heroes is a valley that lies before Stormwind Gate. A bridge of stone crosses the narrow moat and is the first sight of all who enter.",
			full = "The Valley of Heroes is a valley that lies before Stormwind Gate. A bridge of stone crosses the narrow moat and is the first sight of all who enter. This gloriously lush valley lies south of the city, and many visitors must pass through it, as it is one of three entrances to Stormwind (the others are the Deeprun Tram, and the Stormwind Harbor). The statues of five famous Alliance heroes stand on either side of the path, welcoming visitors while providing an awe-inspiring warning.\n\nThe valley is also the location of several important Stormwind officials. Astride his tall stallion is General Hammond Clay, the successor of the late General Marcus Jonathan, as commander of the defense of Stormwind City. Down the left fork of the bridge is the paladin, Major Mattingly, and down to the right stands Field Marshal Stonebridge.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
		["war room"] = {
			name = "War Room",
			short = "The War Room (also spelled war room and also known as the map room) is located inside Stormwind Keep, to the right and southeast of the central throne room from the main hall of the keep.",
			full = "The War Room (also spelled war room and also known as the map room) is located inside Stormwind Keep, to the right and southeast of the central throne room from the main hall of the keep. Weapons of war line the walls, everything from blunderbusses to swords to even three cannons. There are areas piled high with books about military strategy and its signature map table at the room's center where Alliance military leaders plan their strategies. It is also here where players can turn off their experience point gain by paying Behsten.\n\nFollowing the Burning of Teldrassil, Tyrande Whisperwind and Malfurion Stormrage were relocated here. During the ceremony for Varian Wrynn after the Battle for Broken Shore, the room was briefly attacked by the Burning Legion but defended by the royal guard.\n\nSince the war against the Jailer and Turalyon becoming Regent of Stormwind, Alleria can be found here.",
			source = "https://warcraft.wiki.gg/wiki/War_Room",
		},
		["winds redemption"] = {
			name = "Wind's Redemption",
			short = "The Wind's Redemption is a battleship serving in the Alliance navy, under the control of the 7th Legion.",
			full = "The Wind's Redemption is a battleship serving in the Alliance navy, under the control of the 7th Legion. The ship is known for taking part in important missions for the Alliance, and is usually used to carry high-profile leaders and champions.",
			source = "https://warcraft.wiki.gg/wiki/Wind's_Redemption",
		},
		["wizards sanctum"] = {
			name = "Wizard's Sanctum",
			short = "The Wizard's Sanctum is a mage tower and a portal room located in the central-southern part of the Mage Quarter, in Stormwind City. The Horde equivalent is the Pathfinder's Den at the Gates of Orgrimmar.",
			full = "The Wizard's Sanctum is a mage tower and a portal room located in the central-southern part of the Mage Quarter, in Stormwind City. The Horde equivalent is the Pathfinder's Den at the Gates of Orgrimmar. Though the personnel working here are generally affiliated with Stormwind, decorations such as the insignia at its entrance suggest the Kirin Tor helped with the remodeling. The area is patrolled by arcane golems and summoned water elementals.",
			source = "https://warcraft.wiki.gg/wiki/Wizard's_Sanctum",
		},
		["wollerton stead"] = {
			name = "Wollerton Stead",
			short = "The Wollerton Stead is a small farmhouse located in the Stormwind City Outskirts.",
			full = "The Wollerton Stead is a small farmhouse located in the Stormwind City Outskirts.\n\nFollowing the Burning of Teldrassil, many kaldorei and Gilnean refugees were found here. Darnassian Druids were magically growing pumpkins here while Volunteer Farmhands collected them.",
			source = "https://warcraft.wiki.gg/wiki/Wollerton_Stead",
		},
	},
	-- Orgrimmar: 22 subzones
	[1454] = {
		["barracks orgrimmar"] = {
			name = "Barracks (Orgrimmar)",
			short = "The Barracks is located in the Valley of Honor of Orgrimmar. It is the repurposed Hall of the Brave and serves as a class hub.",
			full = "The Barracks is located in the Valley of Honor of Orgrimmar. It is the repurposed Hall of the Brave and serves as a class hub.",
			source = "https://warcraft.wiki.gg/wiki/Barracks_(Orgrimmar)",
		},
		["broken tusk"] = {
			name = "Broken Tusk",
			short = "The Broken Tusk is the one of several inns of Orgrimmar, this one located within the Valley of Strength near the Orgrimmar General Store and Auction House.",
			full = "The Broken Tusk is the one of several inns of Orgrimmar, this one located within the Valley of Strength near the Orgrimmar General Store and Auction House. Its most famous resident is Gamon, long beset by members of his own faction due to his formerly low level.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Tusk",
		},
		["cleft of shadow"] = {
			name = "Cleft of Shadow",
			short = "The Cleft of Shadow (or the Cleft of Shadows) is home to Orgrimmar's rogue, mage, and warlock trainers.",
			full = "The Cleft of Shadow (or the Cleft of Shadows) is home to Orgrimmar's rogue, mage, and warlock trainers. It is also the location of the entrance to the Ragefire Chasm instance and is inhabited by the less-than-savory denizens of the great city. Its Arcane Enclave also has the second of the city's portals to the Blasted Lands, the first being in the troll-designed Valley of Spirits.",
			source = "https://warcraft.wiki.gg/wiki/Cleft_of_Shadow",
		},
		["drag"] = {
			name = "Drag",
			short = "The Drag is an alley lined with shops which links the Valley of Strength and the Valley of Wisdom in Orgrimmar. The Valley of Honor and the Cleft of Shadow can be accessed from the Drag.",
			full = "The Drag is an alley lined with shops which links the Valley of Strength and the Valley of Wisdom in Orgrimmar. The Valley of Honor and the Cleft of Shadow can be accessed from the Drag. The shaded street is known far and wide for its myriad of vendors and profession trainers. Nearly every profession trainer can be found here, except for the First Aid, which is found at the Orgrimmar Embassy.",
			source = "https://warcraft.wiki.gg/wiki/Drag",
		},
		["engineering works orgrimmar"] = {
			name = "Engineering Works (Orgrimmar)",
			short = "The Engineering Works is a small engineering shop behind the main building of the Orgrimmar Embassy.",
			full = "The Engineering Works is a small engineering shop behind the main building of the Orgrimmar Embassy.",
			source = "https://warcraft.wiki.gg/wiki/Engineering_Works_(Orgrimmar)",
		},
		["gates of orgrimmar"] = {
			name = "Gates of Orgrimmar",
			short = "The Gates of Orgrimmar (or Orgrimmar Main Gate) is quite simply the main gateway into Orgrimmar. The area leads from the Dranosh'ar Blockade in Durotar to the Valley of Strength.",
			full = "The Gates of Orgrimmar (or Orgrimmar Main Gate) is quite simply the main gateway into Orgrimmar. The area leads from the Dranosh'ar Blockade in Durotar to the Valley of Strength.\n\nFollowing the Battle for Lordaeron, a sizable group of Forsaken refugees set up a camp on the upper portion of the Gates.\n\nSylvanas Windrunner-loyal Horde warriors gathered on the gate when Varok Saurfang, his rebels, and the Alliance, arrived at Dranosh'ar Blockade to breach them. They observed the mak'gora duel between Varok and Sylvanas. After the Banshee Queen killed the High Overlord and fled, the Forsaken banner-carriers stomped their banners in unison and respect as Thrall, Zekhan, and King Anduin Wrynn brought the body inside.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Orgrimmar",
		},
		["goblin slums"] = {
			name = "Goblin Slums",
			short = "It connected to the Valley of Spirits, and was an oily, dirty place - similar to areas in Bilgewater Port. In addition to class and profession trainers, the area had its own innkeeper, auctioneer, and bankers.",
			full = "It connected to the Valley of Spirits, and was an oily, dirty place - similar to areas in Bilgewater Port. In addition to class and profession trainers, the area had its own innkeeper, auctioneer, and bankers.\n\nThe space occupied by the Goblin Slums was originally part of the Valley of Spirits prior to the goblins joining the Horde. The trolls moved further north in the valley, while the goblins were given this part of the valley to use as their own. The slums were presided over by Boss Mida. Off-duty goblins could be found lounging around the pool area as well as waiting in line to withdraw their money from the bank, and off-duty Orgrimmar Grunts joined them to converse and tell jokes. For the most part, however, the area was exclusively goblin.\n\nThere originally appeared to be an oil-drilling operation within the lake, overseen by Environmental Engineer Linza; the surrounding area was filthy, with the pollution flowing downstream to the new Valley of Spirits. In addition to toads and muddy crawfish, the Goblin Slums were home to Robo-Chicks.",
			source = "https://warcraft.wiki.gg/wiki/Goblin_Slums",
		},
		["grommash hold"] = {
			name = "Grommash Hold",
			short = "Grommash Hold is an enormous fortress located in the Valley of Strength in the orc capital of Orgrimmar.",
			full = "Grommash Hold is an enormous fortress located in the Valley of Strength in the orc capital of Orgrimmar. It is named after the orcish hero Grommash Hellscream, it is the former seat of the Warchief of the Horde, and now it is the seat of the Horde Council. Delegations from Silvermoon and the Undercity reside within, including paladin and priest trainers, as well as the trainer for archaeology.",
			source = "https://warcraft.wiki.gg/wiki/Grommash_Hold",
		},
		["hall of legends"] = {
			name = "Hall of Legends",
			short = "The Hall of Legends is the officer's barracks for the Horde. It is in the Valley of Strength, in Orgrimmar.",
			full = "The Hall of Legends is the officer's barracks for the Horde. It is in the Valley of Strength, in Orgrimmar.\n\nIn the center of the Hall is a table surrounded by four Horde: Chieftain Earthbind of Thunder Bluff, Advisor Willington of the Undercity, Blood Guard Hini'wana of the Darkspear Trolls, and Councilor Arial D'Anastasis of Silvermoon City. On the table are several maps of Azeroth, as well as an open book titled [Military Ranks of the Horde & Alliance], which lists the old PvP ranks and accompanying insignias.\n\nIts Alliance counterpart is the Champions' Hall in Stormwind City.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["hall of the brave"] = {
			name = "Hall of the Brave",
			short = "The Hall of the Brave is a large barracks located in the Valley of Honor in the orc capital of Orgrimmar. The Hall contains many of the Horde's army officers, warrior trainers, and battlemasters.",
			full = "The Hall of the Brave is a large barracks located in the Valley of Honor in the orc capital of Orgrimmar. The Hall contains many of the Horde's army officers, warrior trainers, and battlemasters. Several training dummies are located throughout the building, inside and out. It was referred to as the warriors' guild house.\n\nThe previous barracks was a single floor building with an interior that mostly matched the Hall of Legends. It was rebuilt using the new and improved orc architecture, that was first seen in Northrend.\n\nAfter the introduction of the Mag'har clans into the Horde, they can be found throughout the hall, using it as an impromptu home. New Mag'har characters start just outside of this building.\n\nSoon, an adventurer came here and confronted Eitrigg. When confronted about meeting Saurfang in secret, Eitrigg openly admitted to it while remarking that he grew tired of the deceit. Believing that Sylvanas is driven by something dark, Eitrigg vowed to draw blood for her no longer. He then revealed his intention to join Saurfang's army outside of Orgrimmar and asked the loyalists to stand with him. Should the loyalists agree, then they both exit Orgrimmar together and join the revolution, however, should the loyalists refuse, Eitrigg declared that their choices have been made. Eitrigg would lose the subsequent the fight to the loyalists, taken captive, and delivered out of the Hall of Brave to Nathanos Blightcaller.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_the_Brave",
		},
		["miwanas longhouse"] = {
			name = "Miwana's Longhouse",
			short = "Miwana's Longhouse is the inn run by Miwana in the Valley of Wisdom of Orgrimmar.",
			full = "Miwana's Longhouse is the inn run by Miwana in the Valley of Wisdom of Orgrimmar.\n\nHiwahi Three-Feathers, a tailoring trainer, can also be found inside the inn. An innkeeper and tailoring trainer can be found inside, while shaman trainers and a skinning trainer can be found outside, the shaman trainers standing around the bonfire.",
			source = "https://warcraft.wiki.gg/wiki/Miwana's_Longhouse",
		},
		["nip and tusk"] = {
			name = "Nip and Tusk",
			short = "Nip and Tusk is the Orgrimmar's barbershop managed by Bebri Coifcurl.",
			full = "Nip and Tusk is the Orgrimmar's barbershop managed by Bebri Coifcurl.",
			source = "https://warcraft.wiki.gg/wiki/Nip_and_Tusk",
		},
		["orgrimmar embassy"] = {
			name = "Orgrimmar Embassy",
			short = "The Orgrimmar Embassy is a district in Orgrimmar that serves as a meeting point for the leadership of the Horde and as headquarters for many of its allied races.",
			full = "The Orgrimmar Embassy is a district in Orgrimmar that serves as a meeting point for the leadership of the Horde and as headquarters for many of its allied races.\n\nThe door to the embassy is located at coordinates [39, 80.] This is to the left and up the hill from the main gate. A small engineering shop and an engineering trainer can also be found next to the embassy.\n\nDuring Varok Saurfang's rebellion, Jastor Gallywix came to the goblin camp near the building and ordered Overworked Underlings to burn Piles of Misfiled Paperwork and Stacks of Totally Legal Paperwork.\n\nWith that matter settled, Lor'themar Theron addressed the absence of a Warchief. Despite support for Thrall to take up the mantle again he refused, citing that he had promised Varok Saurfang he would not take on the role once more. Instead he brought up the idea of the Warchief not being necessary, bringing in the belief that a change was needed for the Horde's leadership. With this, the Horde Council was created.",
			source = "https://warcraft.wiki.gg/wiki/Orgrimmar_Embassy",
		},
		["pathfinders den"] = {
			name = "Pathfinder's Den",
			short = "Pathfinder's Den (or Orgrimmar Portal Room) is a portal room found within the Gates of Orgrimmar. The Alliance equivalent is the Wizard's Sanctum in the Mage Quarter of Stormwind City.",
			full = "Pathfinder's Den (or Orgrimmar Portal Room) is a portal room found within the Gates of Orgrimmar. The Alliance equivalent is the Wizard's Sanctum in the Mage Quarter of Stormwind City.\n\nDuring Saurfang's rebellion, the entrances to Orgrimmar became surrounded by his allies, and the city was locked down on Sylvanas' orders, causing the Pathfinder's Den to be closed down as well. Several adventurers demanded to enter the room, but Stoki Wonderwand didn't allow them and directed them to the Warchief instead. When Saurfang challenged Sylvanas to mak'gora, she killed him and abandoned the Horde. The portal room was opened, but Stoki remained distrustful of the former banshee loyalists, promptly refusing to let them use her portals. With Orgrimmar not having a Warchief, the den was patrolled by First Arcanist Thalyssra, who calmed any quarrels here, explaining to Stoki the importance of forgiveness. Lady Liadrin and her squad of Blood Knights started their patrol from here as well.",
			source = "https://warcraft.wiki.gg/wiki/Pathfinder's_Den",
		},
		["ragefire chasm"] = {
			name = "Ragefire Chasm",
			short = "Ragefire Chasm is an instance dungeon located in Orgrimmar. The entry portal is in the Cleft of Shadow, next to Neeru Fireblade's tent.",
			full = "Ragefire Chasm is an instance dungeon located in Orgrimmar. The entry portal is in the Cleft of Shadow, next to Neeru Fireblade's tent. The volcanic caverns are home to many hostile troggs, and once was one of the Burning Blade clan's bases of operations. Recently, suspicious activity has started showing up in the Chasm in the form of Dark Shaman, obedient to an unknown force.\n\nAshra Valandril was present to take care of the bosses of this dungeon before the Dark Shaman took over.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
		["ragefire chasm classic"] = {
			name = "Ragefire Chasm",
			short = "Ragefire Chasm is an instance dungeon located in Orgrimmar. The entry portal is in the Cleft of Shadow, next to Neeru Fireblade's tent.",
			full = "Ragefire Chasm is an instance dungeon located in Orgrimmar. The entry portal is in the Cleft of Shadow, next to Neeru Fireblade's tent. The lava-filled chasm is home to many hostile troggs, and followers of the Burning Blade have also recently begun poking around the area.\n\nThis is one of the shortest instances in the game, and of the easiest difficulty. For many players, this will be their first instance. See the Instance Grouping Guide for some helpful hints.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm_(Classic)",
		},
		["valley of honor"] = {
			name = "Valley of Honor",
			short = "The Valley of Honor is the military district of Orgrimmar. It is home to both warrior and hunter trainers, various arms and armor vendors, and the Horde battlemasters.",
			full = "The Valley of Honor is the military district of Orgrimmar. It is home to both warrior and hunter trainers, various arms and armor vendors, and the Horde battlemasters. The Ring of Valor arena is located here. The Hall of the Brave houses the warrior guild, as well as all the city's battlemasters. Blacksmithing, mining, and fishing trainers and vendors are found in the valley.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Honor",
		},
		["valley of spirits"] = {
			name = "Valley of Spirits",
			short = "The Valley of Spirits is a long narrow valley that leads from the Valley of Strength to the Talon Gate in Orgrimmar. It is the long-standing seat of the Darkspear trolls.",
			full = "The Valley of Spirits is a long narrow valley that leads from the Valley of Strength to the Talon Gate in Orgrimmar. It is the long-standing seat of the Darkspear trolls.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spirits",
		},
		["valley of strength"] = {
			name = "Valley of Strength",
			short = "The Valley of Strength is the main valley of Orgrimmar. The area is a bustling hive of activity for most of the day and night, with all manner of adventurers frequenting its shops and facilities.",
			full = "The Valley of Strength is the main valley of Orgrimmar. The area is a bustling hive of activity for most of the day and night, with all manner of adventurers frequenting its shops and facilities. It is also the first area encountered after passing through the main gate.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Strength",
		},
		["valley of wisdom"] = {
			name = "Valley of Wisdom",
			short = "The Valley of Wisdom was once the location of Grommash Hold, where Warchief Thrall once resided in Orgrimmar.",
			full = "The Valley of Wisdom was once the location of Grommash Hold, where Warchief Thrall once resided in Orgrimmar. The valley connects to the Drag in the east, the Valley of Spirits to the west, and the Cleft of Shadow and Valley of Strength to the south. Like most of the districts of Orgrimmar, it contains access to an inn, banker, and auction house.\n\nA few remains of Grommash Hold can still be seen where the tauren were allowed to set up huts and take this valley for their own use. The armor of pit lord Mannoroth, which once rested on a tree here is now gone, and the tree was destroyed.\n\nA towering waterfall casts a cool mist over the valley, making the tauren structures shine.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Wisdom",
		},
		["western earthshrine"] = {
			name = "Western Earthshrine",
			short = "The Western Earthshrine is a ritual circle erected by the Earthen Ring for use by the Horde.",
			full = "The Western Earthshrine is a ritual circle erected by the Earthen Ring for use by the Horde. It is located in the city of Orgrimmar, on a high ridge overlooking the Valley of Wisdom, accessed by a series of bridges from the Orgrimmar Skyway. Its Alliance counterpart is the Eastern Earthshrine in Stormwind City.\n\nThe Mount Hyjal portal is opened by completing As Hyjal Burns, and leads to Nordrassil. There is a portal near Nordrassil Inn that leads back to Orgrimmar.\n\nThe Vashj'ir portal is opened by completing Call of Duty, and initially opens into The Immortal Coil in Kelp'thar Forest. At some point in the main Vashj'ir quest chain, likely after completing [30-35] Silver Tide Hollow (confirmation needed), the portal's destination changes, leading into Silver Tide Hollow in the Shimmering Expanse. Eventually, the portal's destination is moved to Tenebrous Cavern. There is no return portal at any of these locations.\n\nThe Deepholm portal is opened by completing Deepholm, and leads to the Temple of Earth. The Temple of Earth has a portal leading back to the Western Earthshrine.\n\nThe Uldum portal is definitely open after completing Escape From the Lost City (it may be opened earlier in the quest chain, testing is needed) and leads into Ramkahen. There is no return portal.\n\nThe Twilight Highlands portal is definitely open after completing Muddied Waters (it may be opened earlier in the quest chain, testing is needed) and leads to Dragonmaw Port. Completing Any Portal in a Storm opens up a portal back to the Western Earthshrine.\n\nThe Tol Barad Peninsula portal is always open, but can only be used after reaching level 85. It leads to Hellscream's Grasp, which has a portal back to the Western Earthshrine.",
			source = "https://warcraft.wiki.gg/wiki/Western_Earthshrine",
		},
		["wyverns tail"] = {
			name = "Wyvern's Tail",
			short = "The Wyvern's Tail is a small inn in Orgrimmar's Valley of Honor.",
			full = "The Wyvern's Tail is a small inn in Orgrimmar's Valley of Honor.\n\nAlthough not shown in-game, the tavern includes a second floor with numerous rooms and beds and large tables on the main floor for eating. Ironhoof brought the injured orc Malgar to the inn to recuperate.",
			source = "https://warcraft.wiki.gg/wiki/Wyvern's_Tail",
		},
	},
	-- Ironforge: 19 subzones
	[1455] = {
		["aegrims study"] = {
			name = "Aegrim's Study",
			short = "Aegrim's Study is a chamber originally belonging to thane Aegrim Bronzebeard of the Bronzebeard clan. It is accessible from Old Ironforge in Ironforge.",
			full = "Aegrim's Study is a chamber originally belonging to thane Aegrim Bronzebeard of the Bronzebeard clan. It is accessible from Old Ironforge in Ironforge. Ancient Golem Guard‎s and dwarven corpses are located here.",
			source = "https://warcraft.wiki.gg/wiki/Aegrim's_Study",
		},
		["cask n anvil"] = {
			name = "Cask 'n' Anvil",
			short = "The Cask 'n' Anvil is an empty inn located in the Great Forge between Thistlefuzz Arcanery and Ironforge Physician.",
			full = "The Cask 'n' Anvil is an empty inn located in the Great Forge between Thistlefuzz Arcanery and Ironforge Physician.",
			source = "https://warcraft.wiki.gg/wiki/Cask_'n'_Anvil",
		},
		["commons"] = {
			name = "Commons",
			short = "The Commons is the main thoroughfare for trade in the city of Ironforge. It contains the bank, Auction House and inn, as well as a few shops.",
			full = "The Commons is the main thoroughfare for trade in the city of Ironforge. It contains the bank, Auction House and inn, as well as a few shops. The Commons is always the busiest and most crowded portion of the city.\n\nTo get to the Commons, you can head northeast from the Gates of Ironforge, southwest from the Great Forge, west from the Military Ward, or south from the Mystic Ward.\n\nIronforge was the home of the original Alliance auction house, and before expansions pulled away the top level population, this area was infamous for its lag.",
			source = "https://warcraft.wiki.gg/wiki/Commons",
		},
		["deeprun tram"] = {
			name = "Deeprun Tram",
			short = "The Deeprun Tram (or simply the Tram) is a long, fully enclosed, underground (and partially underwater) set of double tracks upon which rolls two sets of three wagons, all credited to the gnomes' technical engineering.",
			full = "The Deeprun Tram (or simply the Tram) is a long, fully enclosed, underground (and partially underwater) set of double tracks upon which rolls two sets of three wagons, all credited to the gnomes' technical engineering. The service is fast and smooth, and is provided free of charge to travelers between the Alliance-aligned cities of Ironforge and Stormwind City. To keep the tram running smoothly and safely, there are gnomes that work on it daily. As such, any problems with it can be quickly addressed. The underwater section of the tram is, in fact, a subterranean lake.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["forlorn cavern"] = {
			name = "Forlorn Cavern",
			short = "The Forlorn Cavern is a long, winding road built around Ironforge's underground lake. Its naturally dark and secluded nature makes it perfect for lots of shady deals.",
			full = "The Forlorn Cavern is a long, winding road built around Ironforge's underground lake. Its naturally dark and secluded nature makes it perfect for lots of shady deals. Rogue and warlock trainers can be found here (the latter inside the Bonegrip's Runes and Dooms), as well as vendors catering to those classes. The Cavern also holds two shops, the Stoneblade's and the Traveling Fisherman.\n\nTo get to the Forlorn Cavern, you can head east from the Mystic Ward or west from the Hall of Explorers.\n\nIt is recommended to be careful in the Forlorn Cavern, where dark things are going on, while risking encountering thieves and warlocks.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Cavern",
		},
		["gates of ironforge"] = {
			name = "Gates of Ironforge",
			short = "The Gates of Ironforge (or the Ironforge Main Gate) lead from the lands of Dun Morogh into the City of Ironforge proper. They are a grand sight, and are visible from far across Dun Morogh.",
			full = "The Gates of Ironforge (or the Ironforge Main Gate) lead from the lands of Dun Morogh into the City of Ironforge proper. They are a grand sight, and are visible from far across Dun Morogh. They can be reached by heading north up the great ramp in central Dun Morogh, or southwest from the Commons. A huge statue of High King Modimus Anvilmar stands guard inside the Gates.\n\nDuring the Legion Invasions, a small Illidari camp was briefly set up here. It would occasionally come under attack by Fel Bats. Thunderbrew Specials could also be looted from here.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["great forge"] = {
			name = "Great Forge",
			short = "The Great Forge (situated in the Great Forge District) is the heart and namesake of the dwarf capital of Ironforge.",
			full = "The Great Forge (situated in the Great Forge District) is the heart and namesake of the dwarf capital of Ironforge. It was the first part of the city to be built by the early dwarves who first settled under Ironforge Mountain. The rest of the city grew around it and was consequently named \"Ironforge\" in its honor.\n\nThe Great Forge never shuts down. It's a loud, hot, and cheerful place, serving not only as the physical center of the city, but also the central part of city life. Most citizens regularly pass through the forge, while visitors come to admire what is happening there. The current keeper of the Great Forge is Myolor Sunderfury. At its center is the famed Great Anvil, where most of the best dwarven blacksmithing trainers can be found. Ringed around the Great Forge are several foundries pouring molten slag and a great deal of shops and guild offices, including trainers for cooking, mining, first aid, tailoring and leatherworking, as well as the High Seat, the court of the Council of Three Hammers. Ironforge's gryphon master Gryth Thurden is also located here.\n\nTwo bells were created here. As a token of friendship, the dwarves sent one to Lordaeron and the other to Stormwind City. It was also here, upon the Great Anvil itself, that the legendary blade Ashbringer was forged by King Magni Bronzebeard.\n\nAccording to Mathias Shaw, the Great Forge is a fine spot for eavesdropping and hearing news from across the Alliance.",
			source = "https://warcraft.wiki.gg/wiki/Great_Forge",
		},
		["hall of arms"] = {
			name = "Hall of Arms",
			short = "The Hall of Arms is the command center of dwarven military power in the Kingdom of Ironforge and serves as the headquarters of the city's armed forces.",
			full = "The Hall of Arms is the command center of dwarven military power in the Kingdom of Ironforge and serves as the headquarters of the city's armed forces. It additionally houses trainers for warriors and hunters, as well as several important battlemasters. The Hall of Arms can be found in the Military Ward, Ironforge's southeastern district.\n\nThe Hall doubles as a major arsenal for the city and the kingdom. Supplies and, more importantly, vehicles can be seen stored in large quantities. Here, assembled flying machines are constantly launched from access ports in the roof and sent to the Ironforge Airfield just outside the city. Steam tanks are also assembled and maintained within the complex for use by Alliance forces in the field.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Arms",
		},
		["hall of explorers"] = {
			name = "Hall of Explorers",
			short = "The Hall of Explorers, also called the Assembly of Explorers, is a major district in the dwarven capital of Ironforge and the headquarters of the famed Explorers' League.",
			full = "The Hall of Explorers, also called the Assembly of Explorers, is a major district in the dwarven capital of Ironforge and the headquarters of the famed Explorers' League. Every archaeological expedition organized by the Alliance is coordinated from here, while it also houses one of the most complete museums of artifacts in the world. The Hall of Explorers is always ready to entertain, educate, and especially inform the agents of the SI:7.\n\nAt first glance, the Hall of Explorers seems like a museum with all the interesting artifacts collected by the League. But few people are familiar with the excellent, and unofficial, relationship between SI:7 and the Explorers' League. Which leads the High Explorer Muninn Magellas to hide precious missives in a cache under the carpet at the entrance of the Hall for the agents of SI:7.\n\nThe Library is the centerpiece of the Hall of Explorers, and contains the museum as well as a vast collection of tomes and knowledge. The district itself is accessed from the Forlorn Cavern, Great Forge, and Tinker Town from the west, southwest, and south respectively.\n\nSapphronetta Flivvers worked here as a consultant member.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Explorers",
		},
		["hall of mysteries"] = {
			name = "Hall of Mysteries",
			short = "The Hall of Mysteries is a temple, also a center of arcane and divine practice and study, within the dwarven Kingdom of Ironforge.",
			full = "The Hall of Mysteries is a temple, also a center of arcane and divine practice and study, within the dwarven Kingdom of Ironforge. The hall can be found within the Mystic Ward district of Ironforge city, and houses several mage, paladin, and priest class trainers. Many of Ironforge's most powerful and gifted individuals reside within the hall, which dominates its section of the city.\n\nThe temple is described as being illuminated by a blue-purple-white light, while inside, five pillars are adorned with a repeating geometric pattern wrought in gold and blue, which supported the upper story and the ceiling. Its rooms are filled with gnomes and dwarves in soft and flowing robes, in contrast to the majority of the city's inhabitants who wear plate armor in their daily life. According to Anduin Wrynn, the Hall of Mysteries is not quite as \"sacred-feeling\" as the Cathedral of Light, but the Light is still there.\n\nIn the city, the Hall serves as the base of operations for the dwarven priests and paladins of the Church of the Light and the Order of the Silver Hand, the highest-ranking being High Priest Rohan and Valgar Highforge. They train apprentices before sending them to the Cathedral of Light in Stormwind City. The promising young paladins of the Silver Hand are sent here to continue their training by studying the [Tome of Divinity], but also to be sent on missions against the enemies of the kingdom that were once the Dark Iron dwarves.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Mysteries",
		},
		["high seat"] = {
			name = "High Seat",
			short = "The High Seat (or High Throne) serves as the throne room of the monarch of the city and kingdom of Ironforge. The chamber is located at the heart of the city, found just off the Great Forge and Commons areas.",
			full = "The High Seat (or High Throne) serves as the throne room of the monarch of the city and kingdom of Ironforge. The chamber is located at the heart of the city, found just off the Great Forge and Commons areas. The throne room was used until recent times by King Magni Bronzebeard, Ironforge's monarch. During this period, a provisional body known as the Council of Three Hammers was established to rule the dwarves, and continued to occupy the High Seat.\n\nThe High Seat currently hosts three thrones (one for each of the clans forming the Council) belonging to Moira Thaurissan, Muradin Bronzebeard, and Falstad Wildhammer. Several other important figures also reside here, such as Senator Barin Redstone and Royal Historian Archesonus.\n\nThe room is spacious enough to accommodate a large number of people, and can sometimes be full when petitioners are heard.",
			source = "https://warcraft.wiki.gg/wiki/High_Seat",
		},
		["library ironforge"] = {
			name = "Library (Ironforge)",
			short = "The Library is a large hoard of knowledge and artifacts within the dwarven capital city of Ironforge.",
			full = "The Library is a large hoard of knowledge and artifacts within the dwarven capital city of Ironforge. Occupying the eastern section of the Hall of Explorers, the Library is arguably the largest singular building in the city, and is notably also home to a museum and many quest givers. The Library and its contents are administered by the Explorers' League, who are dedicated to collecting knowledge and relics from across Azeroth. Members of the League catalogue and analyze all of their findings in the library.\n\nThe library being very large, Librarian Mae Paledust is the best finder to contact to find rare books. A row of coded books is also present at the far end of the library, headed by Bill Spearshaker.",
			source = "https://warcraft.wiki.gg/wiki/Library_(Ironforge)",
		},
		["military ward"] = {
			name = "Military Ward",
			short = "The Military Ward of Ironforge is a district that serves as the command center and base of the Ironforge military, as well as the focal point for most martial functions within the city.",
			full = "The Military Ward of Ironforge is a district that serves as the command center and base of the Ironforge military, as well as the focal point for most martial functions within the city. Central to the Military Ward is the Hall of Arms, which houses hunter and warrior trainers, battlemasters, and a hangar for both steam tanks and dwarven flying machines. Several supply shops and similar establishments can also be found scattered throughout the district.",
			source = "https://warcraft.wiki.gg/wiki/Military_Ward",
		},
		["mystic ward"] = {
			name = "Mystic Ward",
			short = "The Mystic Ward is the northwestern district of the dwarven capital of Ironforge and serves as the center for magical activities and study within the kingdom.",
			full = "The Mystic Ward is the northwestern district of the dwarven capital of Ironforge and serves as the center for magical activities and study within the kingdom. The Mystic Ward can be accessed via the Commons from the south, the Great Forge from the southeast, and the Forlorn Cavern from the east.\n\nWithin the district, there are a few shops owned by merchants who cater to mages with their magical goods. In the Hall of Mysteries, which dominates much of the district, are present a number of notable and very powerful magic users, notably class trainers for mages, paladins, and priests.\n\nThe hall's pool doesn't seem to have exactly any other purpose than to be decorative, and its bottom is full of coins that have been tossed by those who made wishes in front of it.",
			source = "https://warcraft.wiki.gg/wiki/Mystic_Ward",
		},
		["old ironforge"] = {
			name = "Old Ironforge",
			short = "Old Ironforge, also known as the Assembly of Thanes, is a chamber deep below the High Seat of the dwarven capital of Ironforge. He stood rooted on what has become known as Magni's Dais.",
			full = "Old Ironforge, also known as the Assembly of Thanes, is a chamber deep below the High Seat of the dwarven capital of Ironforge. He stood rooted on what has become known as Magni's Dais. A long and winding path leads over the lava to the two doors of Aegrim's Study.",
			source = "https://warcraft.wiki.gg/wiki/Old_Ironforge",
		},
		["stonefire tavern"] = {
			name = "Stonefire Tavern",
			short = "The Stonefire Tavern is an inn located in the Commons district of the city of Ironforge, just north of the main gates.",
			full = "The Stonefire Tavern is an inn located in the Commons district of the city of Ironforge, just north of the main gates. The tavern is owned by Innkeeper Firebrew and his daughter Gwenna Firebrew, and acts as one of the main taverns of the city.",
			source = "https://warcraft.wiki.gg/wiki/Stonefire_Tavern",
		},
		["thistlefuzz arcanery"] = {
			name = "Thistlefuzz Arcanery",
			short = "Thistlefuzz Arcanery is a shop located east of the Great Forge in central Ironforge. Trainers and suppliers for both enchanting and inscription are found here.",
			full = "Thistlefuzz Arcanery is a shop located east of the Great Forge in central Ironforge. Trainers and suppliers for both enchanting and inscription are found here.\n\nA Lexicon of Power floats above the table on the lower floor.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefuzz_Arcanery",
		},
		["tinker town"] = {
			name = "Tinker Town",
			short = "Tinker Town (also spelled Tinkertown) is the gnomish quarter of Ironforge. It is home to a number of alchemy and engineering trainers, as well as the entrance to the famed Deeprun Tram.",
			full = "Tinker Town (also spelled Tinkertown) is the gnomish quarter of Ironforge. It is home to a number of alchemy and engineering trainers, as well as the entrance to the famed Deeprun Tram.\n\nWhen the gnomes lost Gnomeregan to the troggs, the dwarves of Ironforge took in the refugees. The gnomes constructed Tinker Town in the district where the Ironforge Deeprun Tram station had been built. Some dwarves like Skuerto were booted out of the city to make way for them, implying dwarves originally lived in this ward. Prior to Operation: Gnomeregan, Tinker Town was the center of the gnomish court in exile and High Tinker Mekkatorque could be found here, along with his closest advisers.",
			source = "https://warcraft.wiki.gg/wiki/Tinker_Town",
		},
		["vault of ironforge"] = {
			name = "Vault of Ironforge",
			short = "The Vault of Ironforge is the main bank and treasure store in the city of Ironforge, located just across from the Auction House in the Commons district.",
			full = "The Vault of Ironforge is the main bank and treasure store in the city of Ironforge, located just across from the Auction House in the Commons district. Available to members of the Alliance, the bank's services are overseen by Dinita and the Stonemantle family.",
			source = "https://warcraft.wiki.gg/wiki/Vault_of_Ironforge",
		},
	},
	-- Thunder Bluff: 6 subzones
	[1456] = {
		["cat and the shaman"] = {
			name = "Cat and the Shaman",
			short = "The Cat and the Shaman is an inn in Thunder Bluff owned by Innkeeper Pala.",
			full = "The Cat and the Shaman is an inn in Thunder Bluff owned by Innkeeper Pala.",
			source = "https://warcraft.wiki.gg/wiki/Cat_and_the_Shaman",
		},
		["elder rise"] = {
			name = "Elder Rise",
			short = "Elder Rise is directly east of the central bluff and is the home of the Cenarion Circle in Thunder Bluff. Many tauren druids and priests reside here and provide training.",
			full = "Elder Rise is directly east of the central bluff and is the home of the Cenarion Circle in Thunder Bluff. Many tauren druids and priests reside here and provide training. The Arch Druid Hamuul Runetotem resides here. Before her exile, the leader of the Grimtotem tribe, Magatha Grimtotem, used to inhabit the hut between the two bridges. Elder Rise connects to high rise and middle rise by separate rope bridges.\n\nElder Rise holds the governing Council of Elders and also members of the Cenarion Circle.\n\nThey were happy to hear that the Horde Council wished them health and safety, and the elders stated few needs from their people, in addition of healing.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["high rise"] = {
			name = "High Rise",
			short = "The High Rise (or the high rise) is the top of Thunder Bluff's central mesa and contains the home of High Chieftain Baine Bloodhoof.",
			full = "The High Rise (or the high rise) is the top of Thunder Bluff's central mesa and contains the home of High Chieftain Baine Bloodhoof. Outside of the High Chieftain's quarters, Thunder Bluff's populace can witness important decisions and fateful events in an open-air auditorium.\n\nIt contains a crude amphitheater around a bonfire. Professional trainers for cooking and fishing can also be found here. It connects to the middle rise and lower rise through the wind rider roost, and to Hunter Rise and Elder Rise by separate rope bridges. This is the only one of the three central rises to not contain a lift to the plains of Mulgore below.",
			source = "https://warcraft.wiki.gg/wiki/High_Rise",
		},
		["hunter rise"] = {
			name = "Hunter Rise",
			short = "Located to the south of the main bluff in Thunder Bluff, Hunter Rise is the home of the hunters, warriors, and paladins of the tauren.",
			full = "Located to the south of the main bluff in Thunder Bluff, Hunter Rise is the home of the hunters, warriors, and paladins of the tauren. Others who call this area home are trappers, trackers, and tanners. The trainers for these groups reside within the renowned Hunter's Hall and the Sunwalker Lodge. Outside, training dummies are provided for practicing fighters, and battlemasters seek recruits for attacks against the Alliance. Hunter Rise connects to lower rise and high rise by separate rope bridges.\n\nMany begged Rexxar for advice or stories from his travels.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Pools of Vision",
			short = "The Pools of Vision are located within a tunnel system just below the cap of Spirit Rise, and serve as the Forsaken base of operations at Thunder Bluff.",
			full = "The Pools of Vision are located within a tunnel system just below the cap of Spirit Rise, and serve as the Forsaken base of operations at Thunder Bluff.\n\nThe entrance to pools of vision is at the right-hand side of the bridge from low rise to spirit rise. The end of the bridge is at , and the entrance to the cave is at .\n\nYou can fish the waters here; the catches are the same for all the major cities except for Dalaran.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
		},
		["spirit rise"] = {
			name = "Spirit Rise",
			short = "Spirit Rise is situated to the northwest of the central bluff and is the center for shamanistic studies in Thunder Bluff. The Skychaser tribe holds great influence here.",
			full = "Spirit Rise is situated to the northwest of the central bluff and is the center for shamanistic studies in Thunder Bluff. The Skychaser tribe holds great influence here. Below the surface of the mesa are the steamy Pools of Vision. It connects to lower rise and middle rise by separate rope bridges. There is also a zeppelin dock that players can use to travel to Orgrimmar.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Rise",
		},
	},
	-- Darnassus: 7 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Cenarion Enclave",
			short = "The Cenarion Enclave is a major district and a grove in the night elven capital of Darnassus, where the city's druids reside and meet.",
			full = "The Cenarion Enclave is a major district and a grove in the night elven capital of Darnassus, where the city's druids reside and meet. Archdruid Fandral Staghelm formerly led his followers and kin from the boughs of the Enclave, until Malfurion Stormrage returned from the Emerald Dream during the War Against the Nightmare. The area remains a hub for druid trainers.\n\nBelow-ground, a secretive rogue guild can be found if one knows where to look within the westernmost bough. Darnassus's hunters also come to the Cenarion Enclave to train in the easternmost tree, while the skill and means to ride nightsabers can also be obtained at the foot of the Enclave tree.\n\nThe Cenarion Enclave is located in the northwest of the city, accessible from the Temple Gardens to the south, Craftsmen's Terrace to the east, and the Howling Oak to the north. Tall trees -- oaks and ashes especially -- lined the enclave. Each tree bore mystic runes shaped from the very bark. Within the circular grove, a handful of unique structures molded both from living wood and carefully-shaped stones represent the usual gathering place for convocations. The largest of these structures served as the residence of Fandral Staghelm.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Craftsmen's Terrace",
			short = "The Craftsmen's Terrace is a major district in the north of the night elf capital city of Darnassus. The terrace is home to most of Darnassus's profession trainers and shops, and contains one of the city's primary inns.",
			full = "The Craftsmen's Terrace is a major district in the north of the night elf capital city of Darnassus. The terrace is home to most of Darnassus's profession trainers and shops, and contains one of the city's primary inns. Guild services are available here, while an embassy of the Argent Dawn faction is also present. The Craftsmen's Terrace can be accessed from the Warrior's Terrace to the south, and the Cenarion Enclave and Howling Oak to the west and northwest.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["howling oak"] = {
			name = "Howling Oak",
			short = "The Howling Oak was an area in the north of the night elven capital city of Darnassus, centered around large Gilnean oak tree. The tree itself was a \"worgen tree\", very similar to Tal'doren in the Blackwald.",
			full = "The Howling Oak was an area in the north of the night elven capital city of Darnassus, centered around large Gilnean oak tree. The tree itself was a \"worgen tree\", very similar to Tal'doren in the Blackwald. The area was accessible from the Craftsmen's Terrace and Cenarion Enclave from the southeast and southwest respectively. It was a place where both worgen and night elf druids trained.\n\nThe Howling Oak was originally grown through the aid of the night elven druids from a seed taken from Gilneas. It stood for all the Gilneans have endured since the ruin of their kingdom, and all that their people have since accomplished. Shortly after the Gilneans' arrival in Darnassus, King Genn Greymane made an appearance here, as he and his people were greeted personally by Tyrande Whisperwind.\n\nDuring the War of the Thorns, the Howling Oak was ultimately destroyed alongside Darnassus in the Burning of Teldrassil. However, all the Gilnean refugees were evacuated before the fire started and moved to Stormwind City, where they settled in the area around Olivia's Pond. It was Queen Mia Greymane, as a respected authority figure and the most suitable person available, who appeased the Gilnean people in the area and organized their evacuation with the help of the Highborne mage Maelir.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Oak",
		},
		["temple gardens"] = {
			name = "Temple Gardens",
			short = "The Temple Gardens are a large open area in the center of the night elven capital of Darnassus.",
			full = "The Temple Gardens are a large open area in the center of the night elven capital of Darnassus. The gardens themselves encompass the body of water, walkways, and small islands at the heart of the city, being named for the large Temple of the Moon located immediately to the south.\n\nA portal in the far west of the district provides the only non-flying method of traveling to Rut'theran Village at the base of the World Tree, while Darnassus's bank can also be found on the largest island. The Temple Gardens are connected by bridges to the Cenarion Enclave to the north, the Craftsmen's, Warrior's, and Tradesmen's Terraces to the east, and the Temple of the Moon to the south.\n\nDuring the Burning of Teldrassil, the conflagration leaped to the Temple Gardens.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["temple of the moon"] = {
			name = "Temple of the Moon",
			short = "The Temple of the Moon (or the Temple of Elune) in Darnassus was a major temple dedicated to the goddess Elune, the dwelling and moonlit sanctum of the Sisters of Elune, and the center of all night elven spiritual life.",
			full = "The Temple of the Moon (or the Temple of Elune) in Darnassus was a major temple dedicated to the goddess Elune, the dwelling and moonlit sanctum of the Sisters of Elune, and the center of all night elven spiritual life. The temple also served as the seat of government in Darnassus and Teldrassil, with the night elven leaders High Priestess Tyrande Whisperwind and Archdruid Malfurion Stormrage residing here. Incidentally, it was one of the largest artificial structures in the region.\n\nThe building itself was built in Darnassus following the Battle of Mount Hyjal that ended the Third War. In its center was the statue of Haidene placed in the middle of a moonwell which was used for bathing and recuperating. The waters of the temple are known to be blessed, being described as the water of Elune herself.\n\nThe temple was destroyed alongside Darnassus during the War of the Thorns after the Horde burned Teldrassil.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_the_Moon",
		},
		["tradesmens terrace"] = {
			name = "Tradesmen's Terrace",
			short = "The Tradesmen's Terrace is a large district in the southern portion of Darnassus, the night elf capital.",
			full = "The Tradesmen's Terrace is a large district in the southern portion of Darnassus, the night elf capital. The terrace is the center of commerce in the city, hosting most vendors and shopkeepers, as well as Darnassus's auction house. The area can be accessed from the Warrior's Terrace in the north, as well as the Temple of the Moon and Temple Gardens in the west.\n\nDuring the Burning of Teldrassil, the wooden buildings of the Tradesmen's Terrace burned quickly.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Warrior's Terrace",
			short = "The Warrior's Terrace (also referred to as the Hall of Justice) is a major central district in the night elf capital city of Darnassus, serving as a base for the city's warrior trainers, battlemasters, and the Sentinels.",
			full = "The Warrior's Terrace (also referred to as the Hall of Justice) is a major central district in the night elf capital city of Darnassus, serving as a base for the city's warrior trainers, battlemasters, and the Sentinels. Most night elves of military status utilized the training areas here to hone their skills. There they had the use of target ranges and dueling grounds. It occupies the easternmost section of Darnassus, located at the main gate leading out into the greater Teldrassil region.\n\nThe district protects Darnassus from violent incursions. Patrollers on nightsaber mounts guard the city's impressive gates.\n\nThe Warrior's Terrace is accessible from the Craftsmen's Terrace in the north, the Tradesmen's Terrace in the south, and the Temple Gardens in the west. In addition to the large military presence, the terrace also hosts a large number of low- and high-level training dummies, as well as blacksmithing training and supplies.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Undercity: 9 subzones
	[1458] = {
		["apothecarium"] = {
			name = "Apothecarium",
			short = "The Apothecarium lies in the southwest corner of the Undercity.",
			full = "The Apothecarium lies in the southwest corner of the Undercity. It is the home of the Royal Apothecary Society, a large-scale organization of undead led by Master Apothecary Faranell and dedicated to eradicating the \"infestation of humanity\" from Lordaeron. This is where the Forsaken work to brew their newest plagues and poisons, as well as creating more powerful abominations to serve in their armies. It is the center for alchemy training for the Forsaken. Forsaken medics such as Vellcinda Benton also studied here to learn the science of tissue and organ transplants.\n\nDuring the Battle for the Undercity, the Alliance led by Varian Wrynn entered the Apothecarium and killed Putress here. The king was horrified when he saw the laboratory.\n\nDuring the Burning Legion's third invasion, it was revealed that Koltira was held captive in the Apothecarium. Thassarian and the Deathlord of the Ebon Blade infiltrated the Apothecarium only to find it abandoned. They killed Gurgoth and freed Koltira.",
			source = "https://warcraft.wiki.gg/wiki/Apothecarium",
		},
		["canals undercity"] = {
			name = "Canals (Undercity)",
			short = "The Canals are the areas between the four quarters of the Undercity. A river of green \"liquid\" flows in a large channel around the quarters in a circular path.",
			full = "The Canals are the areas between the four quarters of the Undercity. A river of green \"liquid\" flows in a large channel around the quarters in a circular path.",
			source = "https://warcraft.wiki.gg/wiki/Canals_(Undercity)",
		},
		["magic quarter"] = {
			name = "Magic Quarter",
			short = "The Magic Quarter is the northeastern quadrant of the Undercity and the center of Forsaken arcane research. Its dominant feature is a Temple of the Damned which takes up most of the area.",
			full = "The Magic Quarter is the northeastern quadrant of the Undercity and the center of Forsaken arcane research. Its dominant feature is a Temple of the Damned which takes up most of the area. The facilities in the quarter are:\n\nMage trainers\n\nWarlock and demon trainers\n\nTailoring trainers\n\nPortal trainer",
			source = "https://warcraft.wiki.gg/wiki/Magic_Quarter",
		},
		["rogues quarter"] = {
			name = "Rogues' Quarter",
			short = "The Rogues' Quarter is located in the southeastern corner of the Undercity. It is home to many of the Forsaken's more shady characters, the rogues' guild, and a few profession trainers.",
			full = "The Rogues' Quarter is located in the southeastern corner of the Undercity. It is home to many of the Forsaken's more shady characters, the rogues' guild, and a few profession trainers.\n\nFacilities:\n\nRogue trainers\n\nPoison vendor\n\nLeatherworking trainers\n\nSkinning trainers\n\nEngineering trainers\n\nFirst Aid trainers",
			source = "https://warcraft.wiki.gg/wiki/Rogues'_Quarter",
		},
		["royal quarter"] = {
			name = "Royal Quarter",
			short = "The Royal Quarter (or the Hall of the Dark Lady) of the Undercity contains the throne room where the Dark Lady Sylvanas Windrunner controls her burgeoning empire of undeath.",
			full = "The Royal Quarter (or the Hall of the Dark Lady) of the Undercity contains the throne room where the Dark Lady Sylvanas Windrunner controls her burgeoning empire of undeath. This room, which is guarded by elite Royal Dreadguards, originally contained the battlemasters for the city.\n\nVarimathras was originally found here alongside the Dark Lady, but he betrayed the Horde alongside Putress causing the disaster at the Wrath Gate, prompting the Alliance and Horde to launch a counterattack. The Horde fought through the city, entering the Royal Quarter filled with demonic portals channeled by Varimathras for the minions of the Burning Legion. Several bodies of the royal dreadguards were also seen on the ground. In the aftermath of the defeat of Varimathras and the summoned minions, King Varian Wrynn and his Stormwind Elites entered the chamber and attacked Warchief Thrall and Lady Sylvanas only to be frozen by Jaina Proudmoore and teleported to Stormwind City.\n\nSince Varimathras' defeat, Bragor Bloodfist has also been assigned to this area to assist the Dark Lady.\n\nDuring the Burning Legion's third invasion, a ceremony of the Horde leaders was held here.\n\nAfter Sylvanas left for Orgrimmar to lead the Horde, a new governing body called the Desolate Council ruled from the throne room as well, with its leader, Vellcinda Benton standing in Sylvanas' spot.",
			source = "https://warcraft.wiki.gg/wiki/Royal_Quarter",
		},
		["ruins of lordaeron"] = {
			name = "Ruins of Lordaeron",
			short = "The Ruins of Lordaeron (or Lordaeron Keep, also called Ruins of Capital City and Capital City Ruins, and sometimes referred to as Lordaeron City) is the remains of the city of Lordaeron, the great capital city of the fallen kingdom of Lordaeron.",
			full = "The Ruins of Lordaeron (or Lordaeron Keep, also called Ruins of Capital City and Capital City Ruins, and sometimes referred to as Lordaeron City) is the remains of the city of Lordaeron, the great capital city of the fallen kingdom of Lordaeron. It was destroyed by the Scourge after Arthas Menethil betrayed his people and set on the path to become the Lich King. The area is literally haunted by the final tragic events that led to the death of King Terenas and the city's destruction. Lordaeron's palace still stands, and once served as an entrance into the Forsaken capital of the Undercity.\n\nAfter the Battle for Lordaeron, the Forsaken lost control of the ruins, and the city was further devastated and completely blighted. With the help of adventurers, the Forsaken later applied techniques learned in Maldraxxus to purge the blight from the ruins. Afterward, the city became their new capital, watched over by the new Desolate Council. The city holds a translocation orb that links to Silvermoon City, and has also several portals that lead to Orgrimmar, Vengeance Landing, and Grom'gol Base Camp; in lieu of the still ruined zeppelin towers that once led to these locations.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["sewers"] = {
			name = "Sewers",
			short = "The Sewers (or the bat sewer entrances) are a side entrance to the Undercity, accessible from west of the main gate to the Ruins of Lordaeron, near the Scarlet Watchtower in Tirisfal Glades.",
			full = "The Sewers (or the bat sewer entrances) are a side entrance to the Undercity, accessible from west of the main gate to the Ruins of Lordaeron, near the Scarlet Watchtower in Tirisfal Glades. This is used as the quickest way in and out for flight paths, as the only other way into the city is by using elevators from the ruins.\n\nThe sewers were used by the Alliance to enter the city during the Battle for the Undercity.\n\nYears later, the sewers were used by the Ebon Blade to enter the city during a mission to rescue Koltira Deathweaver.",
			source = "https://warcraft.wiki.gg/wiki/Sewers",
		},
		["trade quarter"] = {
			name = "Trade Quarter",
			short = "The Trade Quarter (or the Heart of the City) is the central area and hub of trade of the Undercity, located just beyond the lifts to the Ruins of Lordaeron.",
			full = "The Trade Quarter (or the Heart of the City) is the central area and hub of trade of the Undercity, located just beyond the lifts to the Ruins of Lordaeron. The center of the Quarter houses the bank, and most of the shops of the Undercity lie around the bank on a series of levels. All other parts of the city can be reached through this quarter via winding passages into the Canals. Under one of the bridges to the bank, you will find Jeremiah Payson the Cockroach Vendor.\n\nFacilities:\n\nInn - There are no beds in this inn, only open wooden caskets (with no lining either). Not recommended for the living.\n\nA Bank, referred to as the Undercity coffer.\n\nA Horde auction house (outer ring)\n\nA Bat Handler\n\nCooking trainer\n\nGuildmaster",
			source = "https://warcraft.wiki.gg/wiki/Trade_Quarter",
		},
		["war quarter"] = {
			name = "War Quarter",
			short = "The War Quarter is located in the northwest corner of the Undercity. This is where the Forsaken military is based, and is also home to the city's priest and warrior guilds, as well as a few profession trainers.",
			full = "The War Quarter is located in the northwest corner of the Undercity. This is where the Forsaken military is based, and is also home to the city's priest and warrior guilds, as well as a few profession trainers.\n\nThe War Quarter contains an Altar of Darkness.\n\nFacilities:\n\nHunter trainers\n\nPriest trainers\n\nWarrior trainers\n\nWeapon skill trainer\n\nBlacksmithing trainers\n\nMining trainers",
			source = "https://warcraft.wiki.gg/wiki/War_Quarter",
		},
	},
}
